    function withTimeout(promise, ms, label) {
      const timeoutMs = Math.max(500, Number(ms) || 8000);
      return new Promise((resolve, reject) => {
        let settled = false;
        const timer = setTimeout(() => {
          if (settled) return;
          settled = true;
          reject(new Error(label || 'timeout'));
        }, timeoutMs);
        Promise.resolve(promise).then(
          (value) => {
            if (settled) return;
            settled = true;
            clearTimeout(timer);
            resolve(value);
          },
          (err) => {
            if (settled) return;
            settled = true;
            clearTimeout(timer);
            reject(err);
          }
        );
      });
    }

