    // 数千件だと数秒かかるので、画面を止めないよう少しずつ判定する（中断されたら null）
    async function buildSimilarItemGroups(index, postings, threshold, isAlive, onProgress) {
      const groups = [];
      const visited = new Set();
      const minScore = Number.isFinite(threshold) ? threshold : 0.62;
      let i = 0;
      let lastProgress = performance.now();
      while (i < index.length) {
        const sliceEnd = idleSliceEnd(await waitForIdleSlice());
        if (isAlive && !isAlive()) return null;
        for (; i < index.length && performance.now() < sliceEnd; i++) {
          if (visited.has(i)) continue;
          const currentGroup = [index[i].item];
          const candIdx = candidateIndicesFromPostings(index[i], postings, i, index.length);
          for (let n = 0; n < candIdx.length; n++) {
            const j = candIdx[n];
            if (visited.has(j)) continue;
            const score = scoreIndexedSimilarity(index[i], index[j]);
            if (score >= minScore) {
              currentGroup.push({ ...index[j].item, matchScore: score });
              visited.add(j);
            }
          }
          if (currentGroup.length > 1) {
            visited.add(i);
            groups.push(currentGroup);
          }
        }
        if (onProgress && performance.now() - lastProgress > 500) {
          onProgress(i, index.length);
          lastProgress = performance.now();
        }
      }
      return groups;
    }

