    // ========== 人生のエネルギー（初年・中年・晩年）描画 ==========
    function renderSanmeiLifeEnergy(chart) {
      const body = (chart && chart.body) || {};
      const earlyStar = body.early || '';
      const midStar = body.mid || '';
      const lateStar = body.late || '';

      const earlyG = SANMEI_JUUSEI_STAGE_GUIDE[earlyStar] || {};
      const midG = SANMEI_JUUSEI_STAGE_GUIDE[midStar] || {};
      const lateG = SANMEI_JUUSEI_STAGE_GUIDE[lateStar] || {};

      const sEarly = SANMEI_JUUSEI_SCORE[earlyStar] ?? 0;
      const sMid = SANMEI_JUUSEI_SCORE[midStar] ?? 0;
      const sLate = SANMEI_JUUSEI_SCORE[lateStar] ?? 0;
      const totalScore = sEarly + sMid + sLate;

      // 総量と体質判定
      let bodyType = '身中';
      let typeBadgeClass = 'bg-amber-900/60 border-amber-500/60 text-amber-100';
      let typeDesc = '';
      if (totalScore >= 24) {
        bodyType = '身強（最強〜強エネルギー）';
        typeBadgeClass = 'bg-rose-900/70 border-rose-500/70 text-rose-100';
        typeDesc = `エネルギー総量は【${totalScore}点】で「身強」に分類されます。大型排気量エンジンのように強い馬力と自力開拓力を持ちます。責任の重い立場、独立起業、忙しい環境、高い目標に向かって全力を注ぐことで運が開けます。エネルギーが余ると不満や周囲との摩擦に向かいやすいため、仕事・スポーツ・創作などでエネルギーを完全燃焼させることが開運の具体策です。`;
      } else if (totalScore >= 14) {
        bodyType = '身中（バランス・中庸エネルギー）';
        typeBadgeClass = 'bg-amber-900/60 border-amber-500/60 text-amber-100';
        typeDesc = `エネルギー総量は【${totalScore}点】で「身中」に分類されます。最もバランスの取れた中庸型（ハイブリッド型）です。単独で無理な突破を狙うよりも、周囲と協力しながら要所で力を発揮する柔軟な生き方が適しています。「自分でやること」と「人に任せること」の配分が上手で、安定した成果を着実に積み上げられます。`;
      } else {
        bodyType = '身弱（精神・省エネ型エネルギー）';
        typeBadgeClass = 'bg-sky-900/70 border-sky-500/70 text-sky-100';
        typeDesc = `エネルギー総量は【${totalScore}点】で「身弱」に分類されます。繊細で精神性の高い省エネ型（精密モーター型）です。体力勝負や長時間の消耗戦・激務は不向きですが、頭脳、感性、専門スキル、仕組み化、人の力を借りることで突出した成果を出せます。十分な休息を予定に先組みし、知恵と信用を武器に勝負するのが成功の秘訣です。`;
      }

      // バイオリズム（推移パターン）判定
      let biorhythmDesc = '';
      if (sEarly >= 8 && sLate <= 5) {
        biorhythmDesc = `【人生のバイオリズム: 初年活動・晩年成熟型】 若年期（初年${sEarly}点）に高いエネルギーで果敢に挑戦して人生の土台を築き、晩年（${sLate}点）は精神的なゆとりや趣味・知恵を楽しむ理想的な成熟パターンです。若い頃の経験が晩年の豊かな安心につながります。`;
      } else if (sLate >= 8 && sEarly <= 6) {
        biorhythmDesc = `【人生のバイオリズム: 大器晩成・晩年充実型】 年齢を重ねるごとにエネルギーと存在感が増す晩年充実型（晩年${sLate}点）です。若い頃の地道な苦労や学びが人生後半で大きく花開き、60代以降に集大成として大活躍する黄金期を迎えます。焦らず着実に積み上げましょう。`;
      } else if (sMid >= sEarly && sMid >= sLate && sMid >= 8) {
        biorhythmDesc = `【人生のバイオリズム: 中年期頂点・山型】 働き盛りの20代後半〜50代（中年期${sMid}点）に最大のエネルギーが集中する実力発揮パターンです。キャリアや事業、家庭において最も勝負どころとなる時期にフルパワーを発揮し、大きな社会的成果を収められます。`;
      } else if (Math.max(sEarly, sMid, sLate) - Math.min(sEarly, sMid, sLate) <= 3) {
        biorhythmDesc = `【人生のバイオリズム: 全期安定・持続型】 初年（${sEarly}点）・中年（${sMid}点）・晩年（${sLate}点）でエネルギーの極端な落差がなく、一生を通じてマイペースに一定のバイタリティを維持できる安定パターンです。どの年代でもブレずに力を発揮できます。`;
      } else {
        biorhythmDesc = `【人生のバイオリズム: 各期変化・柔軟対応型】 初年（${sEarly}点）→ 中年（${sMid}点）→ 晩年（${sLate}点）と時期ごとにエネルギーの波が変化します。各ライフステージの星の性質に合わせて柔軟に生き方や役割をシフトしていくことで、波にうまく乗ることができます。`;
      }

      const totalEl = document.getElementById('sanmei-energy-total-score');
      if (totalEl) totalEl.textContent = String(totalScore);

      const bodyTypeEl = document.getElementById('sanmei-energy-body-type');
      if (bodyTypeEl) {
        bodyTypeEl.textContent = bodyType;
        bodyTypeEl.className = `px-2.5 py-0.5 rounded-lg text-xs font-black border ${typeBadgeClass}`;
      }

      const badgeSummary = document.getElementById('sanmei-energy-badge-summary');
      if (badgeSummary) {
        badgeSummary.textContent = `${totalScore}点 / ${bodyType.split('（')[0]}`;
      }

      const miniScoresEl = document.getElementById('sanmei-energy-stage-mini-scores');
      if (miniScoresEl) {
        miniScoresEl.innerHTML = `
          <span class="px-2 py-0.5 rounded bg-sky-950/80 border border-sky-700/60 text-sky-300">初年: ${earlyStar || '—'}(${sEarly}点)</span>
          <span class="text-slate-500 font-bold">→</span>
          <span class="px-2 py-0.5 rounded bg-amber-950/80 border border-amber-700/60 text-amber-300">中年: ${midStar || '—'}(${sMid}点)</span>
          <span class="text-slate-500 font-bold">→</span>
          <span class="px-2 py-0.5 rounded bg-violet-950/80 border border-violet-700/60 text-violet-300">晩年: ${lateStar || '—'}(${sLate}点)</span>
        `;
      }

      const typeDescEl = document.getElementById('sanmei-energy-type-desc');
      if (typeDescEl) typeDescEl.textContent = typeDesc;

      const biorhythmDescEl = document.getElementById('sanmei-energy-biorhythm-desc');
      if (biorhythmDescEl) biorhythmDescEl.textContent = biorhythmDesc;

      // 3期ブロックの描画ヘルパー
      const renderBlock = (elId, stageTitle, ageRange, pillarName, starName, score, stageGuide, periodKey, borderTone) => {
        const el = document.getElementById(elId);
        if (!el) return;
        if (!starName) {
          el.innerHTML = `<div class="text-xs text-slate-500 font-bold">データがありません</div>`;
          return;
        }
        const g = stageGuide || {};
        const pGuide = g[periodKey] || {};
        const stageName = g.stage || '';
        const meaning = g.meaning || (SANMEI_JUUSEI_GUIDE[starName] || {}).meaning || '';

        // プログレスバーの割合（最大12点）
        const percent = Math.min(100, Math.round((score / 12) * 100));

        el.innerHTML = `
          <div class="flex items-start justify-between gap-2 border-b border-${borderTone}-800/40 pb-2">
            <div>
              <div class="text-[10px] font-extrabold text-${borderTone}-400/90">${stageTitle}（${ageRange}）</div>
              <div class="text-base font-black text-${borderTone}-100 flex items-center gap-1.5 mt-0.5">
                <span>${starName}</span>
                <span class="text-[11px] font-bold text-slate-400">（${stageName}）</span>
              </div>
              <div class="text-[9px] text-${borderTone}-500/80 font-bold">${pillarName}・${g.level || ''}</div>
            </div>
            <div class="text-right flex-shrink-0">
              <div class="flex items-baseline justify-end gap-0.5">
                <span class="text-2xl font-black text-${borderTone}-200 font-mono">${score}</span>
                <span class="text-[10px] font-bold text-${borderTone}-400/80">/12点</span>
              </div>
              <div class="w-16 h-1.5 bg-black/60 rounded-full overflow-hidden border border-${borderTone}-900/60 mt-1">
                <div class="h-full bg-${borderTone}-400 rounded-full" style="width: ${percent}%;"></div>
              </div>
            </div>
          </div>

          <div class="space-y-2 text-xs">
            <div>
              <div class="text-[10px] font-extrabold text-amber-300/90 mb-0.5">象意・キーワード</div>
              <p class="text-[11px] text-cyan-100/90 font-bold leading-relaxed">${meaning}</p>
            </div>

            ${pGuide.theme ? `
            <div class="pt-1.5 border-t border-${borderTone}-900/40">
              <div class="text-[10px] font-extrabold text-${borderTone}-300 mb-0.5">この時期のメインテーマ</div>
              <p class="text-[11px] text-cyan-100 font-extrabold leading-relaxed">${pGuide.theme}</p>
            </div>` : ''}

            ${pGuide.traits ? `
            <div>
              <div class="text-[10px] font-extrabold text-${borderTone}-400 mb-0.5">特徴・現れやすい傾向</div>
              <p class="text-[11px] text-cyan-100/80 font-bold leading-relaxed">${pGuide.traits}</p>
            </div>` : ''}

            ${pGuide.action ? `
            <div class="bg-black/30 rounded-lg p-2 border border-${borderTone}-900/50">
              <div class="text-[10px] font-extrabold text-emerald-400 mb-0.5">過ごし方・才能の活かし方</div>
              <p class="text-[11px] text-emerald-100/90 font-bold leading-relaxed">${pGuide.action}</p>
            </div>` : ''}

            ${pGuide.caution ? `
            <div class="bg-black/30 rounded-lg p-2 border border-rose-950/60">
              <div class="text-[10px] font-extrabold text-rose-400 mb-0.5">注意点・アドバイス</div>
              <p class="text-[11px] text-rose-100/90 font-bold leading-relaxed">${pGuide.caution}</p>
            </div>` : ''}
          </div>
        `;
      };

      renderBlock('sanmei-energy-block-early', '🌱 初年期', '0歳〜20代前半', '年支（育ち・基盤）', earlyStar, sEarly, earlyG, 'early', 'sky');
      renderBlock('sanmei-energy-block-mid', '🔥 中年期', '20代後半〜50代', '月支（社会・勝負どころ）', midStar, sMid, midG, 'mid', 'amber');
      renderBlock('sanmei-energy-block-late', '👑 晩年期', '60代以降〜生涯', '日支（集大成・心の安住）', lateStar, sLate, lateG, 'late', 'violet');
    }

    // 十二大従星（人生の発達段階＝エネルギー量。主星の「出方」を規定）
