    function sanmeiBuildIsouPositionReading(label, relationName, isNatal) {
      const axis = sanmeiGetIsouPairAxis(label);
      const baseKey = sanmeiIsouGuideKey(relationName) || relationName;
      const baseGuide = isNatal ? SANMEI_ISOU_NATAL_GUIDE[baseKey] : SANMEI_ISOU_GUIDE[baseKey];
      const builder = SANMEI_ISOU_POS_BUILDERS[baseKey];
      if (builder && axis) return builder(axis, isNatal, baseGuide);
      const theme = (axis && axis.theme) || SANMEI_PAIR_CONTEXT[label] || '';
      const lead = axis ? sanmeiIsouPosLead(axis, isNatal) : '';
      return {
        position: `${lead}${theme}${theme ? ' ' : ''}この位置ならではの${baseKey}として読みます。`,
        traits: (baseGuide && baseGuide.traits) || [],
        events: (baseGuide && baseGuide.events) || [],
        mindset: (baseGuide && baseGuide.mindset) || ''
      };
    }

    function sanmeiIsouPositionSummary(label, relationName, isNatal) {
      const reading = sanmeiBuildIsouPositionReading(label, relationName, isNatal);
      if (!reading) return relationName;
      const bits = (isNatal ? reading.traits : reading.events) || [];
      const first = bits[0] ? String(bits[0]).replace(/。$/, '') : '';
      return first ? `${relationName}（${first}）` : relationName;
    }

