    function sanmeiCalcTalentStar(body) {
      if (!body) return null;
      const placed = [
        { pos: '頭', star: body.head },
        { pos: '左手', star: body.leftHand },
        { pos: '中心', star: body.center },
        { pos: '右手', star: body.rightHand },
        { pos: '腹', star: body.belly }
      ].filter((x) => x.star);
      if (placed.length < 2) return null;
      const scored = placed.map((item, i) => {
        let ke = 0;
        placed.forEach((other, j) => {
          if (i === j) return;
          const eSelf = SANMEI_STAR_ELEMENT[item.star];
          const eO = SANMEI_STAR_ELEMENT[other.star];
          if (eSelf == null || eO == null) return;
          if ((eSelf + 2) % 5 === eO) ke += 1;
        });
        return { ...item, ke };
      });
      const maxKe = Math.max(...scored.map((s) => s.ke));
      const tops = scored.filter((s) => s.ke === maxKe);
      let pattern = '一般型';
      const uniqueKes = [...new Set(scored.map((s) => s.ke))].sort((a, b) => b - a);
      if (maxKe === 0) pattern = '無玄の型';
      else if (scored.every((s) => s.ke === 2) && scored.length === 5) pattern = '五宮同均の型';
      else if (maxKe >= 4 && tops.length === 1) pattern = tops[0].pos === '中心' ? '了殿の型' : '点欽の型';
      else if (uniqueKes[0] === 3 && uniqueKes.includes(2) && uniqueKes.includes(1)) pattern = '順殿の型';
      else if (tops.length === 1 && tops[0].pos === '中心' && maxKe >= 3) pattern = '了殿の型';
      const guide = SANMEI_TALENT_PATTERN_GUIDE[pattern] || SANMEI_TALENT_PATTERN_GUIDE['一般型'];
      return {
        tops,
        maxKe,
        pattern,
        guide,
        scored: scored.sort((a, b) => b.ke - a.ke)
      };
    }

    function sanmeiCalcShitenun(body) {
      if (!body) return null;
      // 縦線: 頭・中心・腹（中心は精神星としても数えない）／横線: 左手・中心・右手
      const verticalSpirit = [body.head, body.belly].filter(sanmeiIsSpiritStar);
      const horizontalSpirit = [body.leftHand, body.rightHand].filter(sanmeiIsSpiritStar);
      const talentRealm = verticalSpirit.length > 0 ? '精神' : '現実';
      const posture = horizontalSpirit.length > 0 ? '立型' : '坐型';
      let key = '南天運';
      if (talentRealm === '精神' && posture === '立型') key = '北天運';
      else if (talentRealm === '精神' && posture === '坐型') key = '西天運';
      else if (talentRealm === '現実' && posture === '立型') key = '東天運';
      const guide = SANMEI_SHITENUN_GUIDE[key];
      return {
        key,
        talentRealm,
        posture,
        verticalSpirit,
        horizontalSpirit,
        centerAsReality: body.center || '',
        guide,
        talent: sanmeiCalcTalentStar(body)
      };
    }

    function renderSanmeiShitenun(chart) {
      const badge = document.getElementById('sanmei-shitenun-badge');
      if (!badge) return;
      const body = (chart && chart.body) || {};
      const pack = sanmeiCalcShitenun(body);
      const setTxt = (id, t) => {
        const el = document.getElementById(id);
        if (el) el.textContent = t || '';
      };
      const setHtml = (id, html) => {
        const el = document.getElementById(id);
        if (el) el.innerHTML = html || '';
      };
      const diagramEl = document.getElementById('sanmei-shitenun-diagram');
      if (!pack) {
        setTxt('sanmei-shitenun-badge', '—');
        setTxt('sanmei-shitenun-realm', '');
        setTxt('sanmei-shitenun-posture', '');
        setTxt('sanmei-shitenun-layout', '');
        setHtml('sanmei-shitenun-meaning', '');
        setHtml('sanmei-shitenun-tips', '');
        setHtml('sanmei-shitenun-fields', '');
        if (diagramEl) diagramEl.innerHTML = '';
        const tb = document.getElementById('sanmei-talent-star-box');
        if (tb) tb.innerHTML = '';
        return;
      }
      const g = pack.guide || {};
      badge.textContent = pack.key;
      setTxt('sanmei-shitenun-realm', `${pack.talentRealm}才能領域`);
      setTxt('sanmei-shitenun-posture', pack.posture);
      if (diagramEl) {
        const toneFor = (dirKey) => (pack.key === dirKey ? 'amber' : 'cyan');
        renderFortuneDiagram(diagramEl, {
          kind: 'cross',
          caption: '縦＝心／横＝現実',
          nodes: [
            {
              slot: 'north',
              label: '北・心のゴール',
              body: `${body.head || '—'}${pack.key === '北天運' ? ' ★' : ''}`,
              tone: toneFor('北天運')
            },
            {
              slot: 'south',
              label: '南・心の出発',
              body: `${body.belly || '—'}${pack.key === '南天運' ? ' ★' : ''}`,
              tone: toneFor('南天運')
            },
            {
              slot: 'west',
              label: '西・現実のゴール',
              body: `${body.rightHand || '—'}${pack.key === '西天運' ? ' ★' : ''}`,
              tone: toneFor('西天運')
            },
            {
              slot: 'east',
              label: '東・現実の出発',
              body: `${body.leftHand || '—'}${pack.key === '東天運' ? ' ★' : ''}`,
              tone: toneFor('東天運')
            },
            {
              slot: 'center',
              label: '交差・あなたの型',
              body: `${pack.key}（${pack.talentRealm}・${pack.posture}）`,
              tone: 'amber'
            }
          ]
        });
      }
      const vLabel = pack.verticalSpirit.length
        ? `縦線・精神領域（北ゴール／南出発）の精神星: ${pack.verticalSpirit.join('・')}`
        : '縦線・精神領域（北／南）: 精神星なし → 現実才能領域寄り';
      const hLabel = pack.horizontalSpirit.length
        ? `横線・現実領域（東出発／西ゴール）の精神星: ${pack.horizontalSpirit.join('・')}`
        : '横線・現実領域（東／西）: 精神星なし → 坐型寄り';
      const cLabel = pack.centerAsReality
        ? `中央・性格（才能判定では現実扱い）: ${pack.centerAsReality}`
        : '中央・性格: —';
      setHtml('sanmei-shitenun-layout', fortuneCollapsibleTextHtml(`${vLabel} ／ ${hLabel} ／ ${cLabel}`, { maxLen: 70, toneClass: 'text-slate-400' }));
      setHtml('sanmei-shitenun-meaning', fortuneCollapsibleTextHtml(g.meaning || '', { maxLen: 72, toneClass: 'text-cyan-100/90' }));
      setHtml('sanmei-shitenun-tips', fortuneCollapsibleTextHtml(g.tips ? `先生の活かし方: ${g.tips}` : '', { maxLen: 72, toneClass: 'text-cyan-100/80' }));
      setHtml('sanmei-shitenun-fields', fortuneCollapsibleTextHtml(g.fields ? `向きやすい分野: ${g.fields}` : '', { maxLen: 64, toneClass: 'text-slate-400' }));

      const tb = document.getElementById('sanmei-talent-star-box');
      if (tb) {
        const talent = pack.talent;
        if (!talent) {
          tb.innerHTML = '';
        } else {
          const tg = talent.guide || SANMEI_TALENT_PATTERN_GUIDE[talent.pattern] || SANMEI_TALENT_PATTERN_GUIDE['一般型'];
          const topNames = talent.tops.map((t) => `${t.star}（${t.pos}・剋${t.ke}）`).join('、');
          const scoreLine = talent.scored.map((t) => `${t.star.replace('星', '')}${t.ke}`).join('・');
          tb.innerHTML = `<div class="text-[11px] font-extrabold text-amber-400/90">才能星・特殊命式（剋線の型）</div>
            <div class="text-xs text-cyan-100/90 font-bold leading-relaxed mt-0.5">${topNames || '—'}　／ <span class="text-amber-300">${talent.pattern}</span></div>
            <div class="text-[10px] text-slate-500 font-bold leading-relaxed mt-1">剋数: ${scoreLine}（多いほどこだわり・やらざるを得ないテーマの目安）</div>
            <div class="mt-2 space-y-1.5 text-[11px] font-bold leading-relaxed">
              ${fortuneCollapsibleTextHtml(tg.condition || '', { maxLen: 60, toneClass: 'text-slate-400' })}
              ${fortuneCollapsibleTextHtml(tg.meaning || '', { maxLen: 60, toneClass: 'text-cyan-100/90' })}
              ${fortuneCollapsibleTextHtml(tg.how || '', { maxLen: 60, toneClass: 'text-cyan-100/80' })}
              ${fortuneCollapsibleTextHtml(tg.tips || '', { maxLen: 60, toneClass: 'text-emerald-200/80' })}
              ${fortuneCollapsibleTextHtml(tg.caution || '', { maxLen: 60, toneClass: 'text-rose-200/70' })}
            </div>`;
        }
      }
      chart.shitenun = pack;
    }

    // ---------- 格局・局法（簡易） ----------
    const SANMEI_STAR_ELEMENT = {
      '貫索星': 0, '石門星': 0,
      '鳳閣星': 1, '調舒星': 1,
      '禄存星': 2, '司禄星': 2,
      '車騎星': 3, '牽牛星': 3,
      '龍高星': 4, '玉堂星': 4
    };
