    function sanmeiGoalStarDetail(starName, posKey, body) {
      if (!starName || !SANMEI_FLOW_POS_KEYS.includes(posKey)) return null;
      const posGuide = SANMEI_GOAL_POS_GUIDE[posKey];
      const starGuide = SANMEI_GOAL_STAR_AT_POS[posKey] && SANMEI_GOAL_STAR_AT_POS[posKey][starName];
      if (!posGuide || !starGuide) return null;
      const pack = sanmeiKishouPack(posKey, starName, body);
      const isStart = posKey === 'belly' || posKey === 'leftHand';
      const roleMap = {
        head: '精神のゴール',
        rightHand: '現実のゴール',
        belly: '精神のスタート',
        leftHand: '現実のスタート'
      };
      return {
        posKey,
        starName,
        posTitle: posGuide.title,
        role: roleMap[posKey] || posGuide.title,
        isStart,
        isKishou: pack && pack.isKishou,
        ...starGuide
      };
    }

    function formatSanmeiGoalStarHtml(detail) {
      if (!detail) return '';
      const styleLabel = detail.isStart ? '始め方' : '仕上げ方';
      const styleText = detail.startStyle || detail.finishStyle || '';
      return `<div class="mt-2 pt-2 border-t border-violet-800/40 space-y-1.5">
        <div class="text-[11px] font-extrabold text-violet-300/90">${detail.role}における${detail.starName}</div>
        ${fortuneCollapsibleTextHtml(detail.meaning || '', { maxLen: 56, toneClass: 'text-cyan-100/90' })}
        ${styleText ? fortuneCollapsibleTextHtml(`${styleLabel}: ${styleText}`, { maxLen: 48, toneClass: 'text-slate-400' }) : ''}
        ${detail.lifeArea ? fortuneCollapsibleTextHtml(`現れやすい場: ${detail.lifeArea}`, { maxLen: 48, toneClass: 'text-slate-400' }) : ''}
        ${detail.yoten ? `<p class="text-[10px] font-bold text-emerald-300/90 leading-relaxed">陽転: ${detail.yoten}</p>` : ''}
        ${detail.inten ? `<p class="text-[10px] font-bold text-rose-300/80 leading-relaxed">陰転: ${detail.inten}</p>` : ''}
      </div>`;
    }

    function formatSanmeiGoalPosBriefHtml(posKey) {
      const g = SANMEI_GOAL_POS_GUIDE[posKey];
      if (!g) return '';
      const titleCls = posKey === 'head' ? 'text-sky-300'
        : posKey === 'rightHand' ? 'text-amber-300'
          : posKey === 'belly' ? 'text-rose-300'
            : posKey === 'leftHand' ? 'text-emerald-300'
              : 'text-cyan-300';
      return `<div class="text-[11px] font-extrabold ${titleCls}">${g.title}</div>
        <p class="text-[10px] font-bold text-slate-500 leading-relaxed">${g.flow}</p>
        ${fortuneCollapsibleTextHtml(g.intro, { maxLen: 56, toneClass: 'text-cyan-100/85' })}`;
    }

    // ---------- 帰星（循環法・極星） ----------
    // 人体図の主星を相生だけでつなぎ、流れが止まった星が帰星（極星）。
    // 相生が無い／五行が揃って一周する場合は胸の主星を帰星とする。
