    // normalize star name for guide lookup
    function ziweiStarKey(name) {
      if (!name) return '';
      let k = String(name).replace(/星$/g, '').trim();
      const map = { '天机': '天機', '天梁': '天梁', '破军': '破軍', '七杀': '七殺', '贪狼': '貪狼', '巨门': '巨門', '廉贞': '廉貞', '武曲': '武曲', '天同': '天同', '太阴': '太陰', '天相': '天相', '天府': '天府', '紫微': '紫微', '太阳': '太陽' };
      return map[k] || k;
    }

