    function calculateUnifiedReading(opts) {
      refreshUnifiedSourceChips();
      const birth = unifiedResolveBirth();
      if (!birth.date) {
        alert('生年月日がありません。設定の「パーソナライズ」か、いずれかの占いパネルに入力してください');
        return;
      }

      const sources = [];
      let sanmeiPack = null;
      let baziPack = null;
      let ziweiPack = null;

      // 自己理解の土台は常に四柱命式ベース（用語は出さない）
      try {
        const chart = calculateSanmeiChart(birth.date, birth.time);
        const sogo = buildSanmeiSogoInterpretation(chart);
        const signals = unifiedSanmeiSignals(chart, sogo);
        sanmeiPack = { chart, sogo, signals };
        const analysis = baziAnalyzeChart(chart);
        const daiunInfo = baziListDaiun(chart, birth.date, birth.time, birth.gender, 8);
        const liunian = baziAnalyzeLiunian(chart, analysis, daiunInfo);
        window.__baziNatalChart = chart;
        const baziSogo = buildBaziSogo(analysis, daiunInfo, liunian);
        baziPack = {
          analysis,
          sogo: baziSogo,
          signals: unifiedBaziSignals(analysis, baziSogo, daiunInfo, liunian),
          daiunInfo,
          liunian
        };
      } catch (err) {
        console.error(err);
        alert('レポートの算出に失敗しました');
        return;
      }

      if (isZiweiEnabled()) {
        const api = ziweiGetAstroApi();
        if (api && typeof api.bySolar === 'function') {
          try {
            const [hh, mm] = birth.time.split(':').map(Number);
            const timeIndex = ziweiTimeIndex(hh || 0, mm || 0);
            const gender = birth.gender === 'female' ? '女' : '男';
            const solar = ziweiFormatSolarDate(birth.date);
            const astrolabe = api.bySolar(solar, timeIndex, gender, true, 'ja-JP');
            const sogo = buildZiweiSogoInterpretation(astrolabe);
            ziweiPack = { astrolabe, sogo, signals: unifiedZiweiSignals(astrolabe, sogo) };
          } catch (err) {
            console.warn('ziwei optional enrich failed', err);
          }
        }
      }

      const unified = buildUnifiedSogo({
        birth,
        sources,
        sanmei: sanmeiPack,
        bazi: baziPack,
        ziwei: ziweiPack
      });

      const pack = { birth, sources, unified, sanmeiPack, baziPack, ziweiPack, sanmei: sanmeiPack, bazi: baziPack, ziwei: ziweiPack };
      const motivation = buildUnifiedMotivation(pack, 0);
      pack.motivation = motivation;

      const resultEl = document.getElementById('unified-result');
      const headlineEl = document.getElementById('unified-sogo-headline');
      const sectionsEl = document.getElementById('unified-sogo-sections');
      renderUnifiedMotivation(motivation);
      if (headlineEl) headlineEl.textContent = unified.headline;
      renderUnifiedPainMindsetBanner(unified.sufferTips);
      renderUnifiedSelfSections(sectionsEl, unified.sections, unified.situations, unified.situationEnergyTip, unified.talkTips, unified.sufferTips, unified.fortuneExtras);

      // ラッキー／アンラッキーカラーの算出と描画
      try {
        const dayStem = (sanmeiPack && sanmeiPack.chart && sanmeiPack.chart.day) ? sanmeiPack.chart.day.stem : 0;
        const strengthKey = (baziPack && baziPack.signals && baziPack.signals.strengthKey) || 'mid';
        const colors = buildUnifiedLuckyColors(dayStem, strengthKey);
        renderUnifiedLuckyColors(colors);
      } catch (errColor) {
        console.warn('buildUnifiedLuckyColors failed', errColor);
      }

      if (resultEl) resultEl.classList.remove('hidden');
      window.__unifiedReading = pack;
      if (resultEl && (!opts || opts.scroll !== false)) {
        resultEl.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    }

    const ZIWEI_LATE_RAT_KEY = 'ziwei_late_rat_mode';

    function getZiweiLateRatMode() {
      try {
        return localStorage.getItem(ZIWEI_LATE_RAT_KEY) === 'late' ? 'late' : 'early';
      } catch (_) {
        return 'early';
      }
    }

    function syncZiweiLateRatSelect() {
      const sel = document.getElementById('ziwei-late-rat-mode');
      if (sel) sel.value = getZiweiLateRatMode();
    }

    function onZiweiLateRatModeChange(val) {
      const mode = val === 'late' ? 'late' : 'early';
      try { localStorage.setItem(ZIWEI_LATE_RAT_KEY, mode); } catch (_) { }
      syncZiweiLateRatSelect();
      const resultEl = document.getElementById('ziwei-result');
      if (resultEl && !resultEl.classList.contains('hidden') && typeof calculateZiweiChart === 'function') {
        calculateZiweiChart(true);
      }
    }

    function ziweiTimeIndex(hour, minute) {
      const total = (hour || 0) * 60 + (minute || 0);
      // iztro: 0=早子(00-01 / 23-01早子設定), 1..11=丑..亥, 12=晚子(23-24晩子設定)
      if (total >= 23 * 60) return getZiweiLateRatMode() === 'late' ? 12 : 0;
      if (total < 60) return 0;
      if (total < 3 * 60) return 1;
      if (total < 5 * 60) return 2;
      if (total < 7 * 60) return 3;
      if (total < 9 * 60) return 4;
      if (total < 11 * 60) return 5;
      if (total < 13 * 60) return 6;
      if (total < 15 * 60) return 7;
      if (total < 17 * 60) return 8;
      if (total < 19 * 60) return 9;
      if (total < 21 * 60) return 10;
      return 11;
    }

    function ziweiFormatSolarDate(dateStr) {
      // iztro expects YYYY-M-D (no leading zero required, but OK)
      const [y, m, d] = dateStr.split('-').map(Number);
      return `${y}-${m}-${d}`;
    }

    function ziweiGetAstroApi() {
      if (typeof iztro !== 'undefined' && iztro.astro) return iztro.astro;
      if (typeof window !== 'undefined' && window.iztro && window.iztro.astro) return window.iztro.astro;
      return null;
    }

    async function ensureZiweiLibraryLoaded() {
      if (ziweiGetAstroApi()) return true;
      if (typeof window.__ensureExternalScript === 'function') {
        const ok = await window.__ensureExternalScript('./iztro.min.js', () => !!ziweiGetAstroApi());
        if (ok && ziweiGetAstroApi()) return true;
      }
      return !!ziweiGetAstroApi();
    }

    function ziweiFindMingPalace(astrolabe) {
      if (!astrolabe || !astrolabe.palaces) return null;
      if (typeof astrolabe.palace === 'function') {
        return astrolabe.palace('命宮') || astrolabe.palace('命宫') || null;
      }
      return astrolabe.palaces.find((p) => p.name === '命宮' || p.name === '命宫') || null;
    }

    function ziweiMajorShort(key) {
      const g = ZIWEI_MAJOR_GUIDE[key];
      if (!g) return `${key}が命宮にあります。`;
      return typeof g === 'string' ? g : (g.short || g.meaning);
    }

    function ziweiMingGuide(mingPalace) {
      if (!mingPalace) {
        return { title: '命宮', text: '命宮データを取得できませんでした。', extra: '' };
      }
      const majors = (mingPalace.majorStars || []).map((s) => ziweiStarKey(s.name)).filter(Boolean);
      const branch = mingPalace.earthlyBranch || '';
      if (!majors.length) {
        return {
          title: `命宮・空宮（${branch}）`,
          text: '命宮に十四主星がなく空宮です。対宮や三方の主星の影響を受けやすく、環境・他者との関わりで自分像が形作られやすい傾向があります。三方四正の星をあわせて見ると立体的になります。',
          extra: '空宮のときは、対宮（遷移）や官祿・財帛など三方四正の主星を命の補完として読むと、自己像がはっきりします。'
        };
      }
      const parts = majors.map((k) => `【${k}】${ziweiMajorShort(k)}`);
      const mutagenNotes = (mingPalace.majorStars || [])
        .filter((s) => s.mutagen)
        .map((s) => `${ziweiStarKey(s.name)}が${ZIWEI_MUTAGEN_LABEL[s.mutagen] || s.mutagen}`);
      let text = parts.join(' ');
      if (mutagenNotes.length) {
        text += ` 生年四化: ${mutagenNotes.join('、')}。`;
      }
      text += ' 命宮は自己・性格・人生の基調を見る宮です。他の十一宮と合わせて読むと精度が上がります。';
      const mindsets = majors
        .map((k) => ZIWEI_MAJOR_GUIDE[k] && ZIWEI_MAJOR_GUIDE[k].mindset)
        .filter(Boolean);
      const extra = mindsets.length
        ? `活かし方: ${mindsets.join(' ')}`
        : '十二宮カードをタップすると、各宮のテーマと主星の詳細が出ます。';
      return {
        title: `命宮・${majors.join('＋')}（${branch}）`,
        text,
        extra
      };
    }

    function ziweiFindPalaceByNames(astrolabe, names) {
      if (!astrolabe || !astrolabe.palaces) return null;
      const set = new Set(names);
      return astrolabe.palaces.find((p) => set.has(p.name)) || null;
    }

    function ziweiPalaceMajorsLine(palace) {
      if (!palace) return '主星なし';
      const majors = (palace.majorStars || []).map((s) => {
        const key = ziweiStarKey(s.name);
        const mut = s.mutagen ? `[${s.mutagen}]` : '';
        return `${key || s.name}${mut}`;
      });
      return majors.length ? majors.join('、') : '主星なし（空宮）';
    }

    function ziweiCollectNatalMutagens(astrolabe) {
      const muts = [];
      (astrolabe.palaces || []).forEach((p) => {
        const stars = [].concat(p.majorStars || [], p.minorStars || []);
        stars.forEach((s) => {
          if (s.mutagen) {
            muts.push({
              palace: p.name,
              star: ziweiStarKey(s.name) || s.name,
              mut: s.mutagen,
              label: ZIWEI_MUTAGEN_LABEL[s.mutagen] || s.mutagen
            });
          }
        });
      });
      const order = { '禄': 0, '祿': 0, '權': 1, '权': 1, '科': 2, '忌': 3 };
      muts.sort((a, b) => (order[a.mut] ?? 9) - (order[b.mut] ?? 9));
      return muts;
    }

