    function closeAbstinenceFeature(opts) {
      ABSTINENCE_FEATURE_KEYS.forEach((key) => {
        const card = document.getElementById(ABSTINENCE_CARD_IDS[key]);
        if (card) card.classList.add('hidden');
      });
      document.querySelectorAll('.abstinence-hub-btn').forEach((btn) => {
        btn.classList.remove('abstinence-hub-btn-active');
        btn.setAttribute('aria-pressed', 'false');
      });
      const hub = document.getElementById('abstinence-hub');
      const panelRoot = document.getElementById('abstinence-panel-root');
      const backBtn = document.getElementById('abstinence-feature-back');
      const jump = document.querySelector('.abstinence-jump');
      if (hub) hub.classList.remove('hidden');
      if (panelRoot) panelRoot.classList.add('hidden');
      if (backBtn) backBtn.classList.add('hidden');
      if (jump) jump.classList.add('hidden');
      refreshAbstinenceHome();
      if (!opts || !opts.silent) {
        if (hub) hub.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    }

    function openAbstinenceFeature(key, opts) {
      opts = opts || {};
      if (!ABSTINENCE_FEATURE_KEYS.includes(key)) return;
      ABSTINENCE_FEATURE_KEYS.forEach((k) => {
        const card = document.getElementById(ABSTINENCE_CARD_IDS[k]);
        if (card) card.classList.toggle('hidden', k !== key);
      });
      document.querySelectorAll('.abstinence-hub-btn').forEach((btn) => {
        const on = btn.dataset.abstinenceKey === key;
        btn.classList.toggle('abstinence-hub-btn-active', on);
        btn.setAttribute('aria-pressed', on ? 'true' : 'false');
      });
      const hub = document.getElementById('abstinence-hub');
      const panelRoot = document.getElementById('abstinence-panel-root');
      const backBtn = document.getElementById('abstinence-feature-back');
      const jump = document.querySelector('.abstinence-jump');
      if (hub) hub.classList.add('hidden');
      if (panelRoot) panelRoot.classList.remove('hidden');
      if (backBtn) backBtn.classList.remove('hidden');
      if (jump) jump.classList.remove('hidden');

      const card = document.getElementById(ABSTINENCE_CARD_IDS[key]);
      if (card && typeof setSettingsAccExpanded === 'function') {
        setSettingsAccExpanded(card, true);
      }
      if (key === 'abstinence') initAbstinenceUI();
      if (!opts.silent) {
        const scroller = document.getElementById('abstinence-mode');
        if (scroller) scroller.scrollTop = 0;
      }
    }

    window.openAbstinenceFeature = openAbstinenceFeature;
    window.closeAbstinenceFeature = closeAbstinenceFeature;
    window.refreshAbstinenceHome = refreshAbstinenceHome;
    window.scrollAbstinenceSection = scrollAbstinenceSection;

    const FORTUNE_FEATURE_KEYS = ['unified', 'sanmei', 'ziwei', 'bazi'];
    const ALL_FORTUNE_CARD_KEYS = ['profile', 'unified', 'sanmei', 'ziwei', 'bazi'];

    function fortuneWxClassForElem(elemIdx) {
      const map = ['sanmei-wx-wood', 'sanmei-wx-fire', 'sanmei-wx-earth', 'sanmei-wx-metal', 'sanmei-wx-water'];
      return map[elemIdx] || 'sanmei-wx-earth';
    }

    function getTodayKanshiPack() {
      if (typeof calculateSanmeiChart !== 'function') return null;
      const now = new Date();
      const dateStr = `${now.getFullYear()}-${birthPad2(now.getMonth() + 1)}-${birthPad2(now.getDate())}`;
      const timeStr = `${birthPad2(now.getHours())}:${birthPad2(now.getMinutes())}`;
      const chart = calculateSanmeiChart(dateStr, timeStr);
      const dateLabel = typeof formatJaDateLabel === 'function'
        ? formatJaDateLabel(dateStr)
        : dateStr;
      return {
        dateLabel,
        pillars: [
          { key: 'year', label: '年', stem: chart.year.stem, branch: chart.year.branch, ganzi: chart.year.ganzi },
          { key: 'month', label: '月', stem: chart.month.stem, branch: chart.month.branch, ganzi: chart.month.ganzi },
          { key: 'day', label: '日', stem: chart.day.stem, branch: chart.day.branch, ganzi: chart.day.ganzi, featured: true },
          { key: 'hour', label: '時', stem: chart.hour.stem, branch: chart.hour.branch, ganzi: chart.hour.ganzi }
        ]
      };
    }

    function renderFortuneHomeKanshi() {
      const wrap = document.getElementById('fortune-home-kanshi');
      const dateEl = document.getElementById('fortune-home-kanshi-date');
      const pillarsEl = document.getElementById('fortune-home-kanshi-pillars');
      if (!wrap || !dateEl || !pillarsEl) return;
      const pack = getTodayKanshiPack();
      if (!pack) {
        wrap.classList.add('hidden');
        return;
      }
      wrap.classList.remove('hidden');
      dateEl.textContent = pack.dateLabel;
      pillarsEl.innerHTML = '';
      pack.pillars.forEach((pillar) => {
        const stemElem = typeof sanmeiStemElement === 'function'
          ? sanmeiStemElement(pillar.stem)
          : Math.floor(pillar.stem / 2);
        const branchElem = SANMEI_BRANCH_ELEMENT[pillar.branch];
        const stemChar = SANMEI_STEMS[pillar.stem];
        const branchChar = SANMEI_BRANCHES[pillar.branch];

        const cell = document.createElement('div');
        cell.className = 'fortune-home-kanshi-cell' + (pillar.featured ? ' is-featured' : '');
        cell.setAttribute('aria-label', `${pillar.label}柱 ${pillar.ganzi}`);

        const role = document.createElement('span');
        role.className = 'fortune-home-kanshi-role';
        role.textContent = pillar.label;

        const ganzi = document.createElement('div');
        ganzi.className = 'fortune-home-kanshi-ganzi';
        ganzi.title = `${pillar.label}柱 ${pillar.ganzi}`;

        const stemSpan = document.createElement('span');
        stemSpan.className = `fortune-home-kanshi-char sanmei-wx ${fortuneWxClassForElem(stemElem)}`;
        stemSpan.textContent = stemChar;

        const branchSpan = document.createElement('span');
        branchSpan.className = `fortune-home-kanshi-char sanmei-wx ${fortuneWxClassForElem(branchElem)}`;
        branchSpan.textContent = branchChar;

        ganzi.appendChild(stemSpan);
        ganzi.appendChild(branchSpan);
        cell.appendChild(role);
        cell.appendChild(ganzi);
        pillarsEl.appendChild(cell);
      });
      try {
        const dayPillar = (pack.pillars || []).find((p) => p.key === 'day') || (pack.pillars && pack.pillars[2]);
        if (dayPillar && dayPillar.ganzi) {
          const nowD = new Date();
          const todayIso = `${nowD.getFullYear()}-${String(nowD.getMonth() + 1).padStart(2, '0')}-${String(nowD.getDate()).padStart(2, '0')}`;
          const stemElemIdx = Math.floor((dayPillar.stem || 0) / 2);
          const elemThemes = [
            '木気：芽吹き・アイデアを伸ばす日',
            '火気：直感・熱量を言葉にする日',
            '土気：整理・思考の輪郭を固める日',
            '金気：決断・余分を削ぎ落とす日',
            '水気：内省・柔軟に流れを読む日'
          ];
          const guide = elemThemes[stemElemIdx] || '';
          let quote = '';
          try {
            const rawPrev = localStorage.getItem('dump_daily_fortune_insight');
            if (rawPrev) {
              const prev = JSON.parse(rawPrev);
              if (prev && prev.date === todayIso) {
                if (typeof prev.quote === 'string' && prev.quote.trim()) quote = prev.quote.trim();
                else if (typeof prev.text === 'string' && prev.text.trim() && !/^今日の干支：/.test(prev.text.trim())) {
                  quote = prev.text.trim();
                }
              }
            }
          } catch (_) { }
          const kanshiLine = guide
            ? `今日の干支：${dayPillar.ganzi}（${guide}）`
            : `今日の干支：${dayPillar.ganzi}`;
          localStorage.setItem('dump_daily_fortune_insight', JSON.stringify({
            date: todayIso,
            kanshi: dayPillar.ganzi,
            guide,
            quote,
            text: quote ? `${kanshiLine} / ${quote}` : kanshiLine
          }));
        }
      } catch (_) { }
    }

