    function abstinenceLocalDayKey(value) {
      const d = value instanceof Date ? value : new Date(value);
      if (Number.isNaN(d.getTime())) return '';
      const y = d.getFullYear();
      const m = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      return y + '-' + m + '-' + day;
    }

    function buildAbstinenceDailyEventSeries(events, daySpan) {
      const spanCap = Number(typeof ABSTINENCE_SLIP_CHART_MAX_DAYS === 'number' ? ABSTINENCE_SLIP_CHART_MAX_DAYS : 90);
      const span = Math.max(7, Math.min(spanCap, Number(daySpan) || 21));
      const now = new Date();
      const end = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      const start = new Date(end);
      start.setDate(start.getDate() - (span - 1));
      const days = [];
      for (let i = 0; i < span; i++) {
        const d = new Date(start);
        d.setDate(start.getDate() + i);
        days.push({
          key: abstinenceLocalDayKey(d),
          date: d,
          count: 0,
          label: (d.getMonth() + 1) + '/' + d.getDate()
        });
      }
      const byKey = new Map(days.map((row) => [row.key, row]));
      const sorted = (events || [])
        .map((s) => ({ at: new Date(s.at), raw: s }))
        .filter((s) => !Number.isNaN(s.at.getTime()))
        .sort((a, b) => a.at - b.at);
      sorted.forEach((s) => {
        const row = byKey.get(abstinenceLocalDayKey(s.at));
        if (row) row.count += 1;
      });
      const gapPoints = [];
      for (let i = 1; i < sorted.length; i++) {
        const gapDays = (sorted[i].at - sorted[i - 1].at) / 86400000;
        if (!(gapDays >= 0)) continue;
        const key = abstinenceLocalDayKey(sorted[i].at);
        if (!byKey.has(key)) continue;
        gapPoints.push({ key, gap: gapDays });
      }
      return { days, gapPoints, span, total: sorted.length };
    }

    function renderAbstinenceEventDayChart(opts) {
      const svg = document.getElementById(opts.svgId);
      const hintEl = opts.hintId ? document.getElementById(opts.hintId) : null;
      const scrollEl = opts.scrollId ? document.getElementById(opts.scrollId) : null;
      if (!svg) return;
      const palette = opts.palette || {
        bar: 'rgba(244,63,94,0.75)',
        barStroke: 'rgba(251,113,133,0.85)',
        line: 'rgba(251,191,36,0.85)',
        label: '#fda4af',
        empty: '#64748b'
      };
      const series = buildAbstinenceDailyEventSeries(opts.events || [], opts.daySpan || 21);
      const days = series.days;
      if (hintEl) {
        const countLabel = opts.lifetime ? `通算 ${series.total}回` : `計 ${series.total}回`;
        hintEl.textContent = series.total
          ? `${countLabel} · ${days.length}日${days.length > 21 ? ' · 横にスライド' : ''}`
          : 'まだデータなし';
      }

      const maxCount = Math.max(1, ...days.map((d) => d.count));
      const gapVals = series.gapPoints.map((g) => g.gap);
      const maxGap = Math.max(1, ...(gapVals.length ? gapVals : [1]));
      const padL = 28;
      const padR = 28;
      const padT = 18;
      const padB = 26;
      const n = days.length;
      const stepX = 22;
      const plotW = Math.max(stepX * n, 220);
      const W = Math.max(280, padL + padR + plotW);
      const H = 140;
      const plotH = H - padT - padB;
      const barW = Math.max(6, Math.min(14, stepX * 0.55));
      const xOf = (i) => padL + stepX * i + stepX / 2;
      const yCount = (c) => padT + ((maxCount - c) / maxCount) * plotH;
      const yGap = (g) => padT + ((maxGap - g) / maxGap) * plotH;

      const grid = [0, Math.ceil(maxCount / 2), maxCount].filter((v, i, arr) => arr.indexOf(v) === i).map((v) => {
        const y = yCount(v);
        return `<line x1="${padL}" y1="${y.toFixed(1)}" x2="${(W - padR).toFixed(1)}" y2="${y.toFixed(1)}" stroke="rgba(148,163,184,0.12)" stroke-width="1"/>
          <text x="${padL - 4}" y="${(y + 3).toFixed(1)}" text-anchor="end" fill="#64748b" font-size="8" font-weight="700">${v}</text>`;
      }).join('');

      const bars = days.map((d, i) => {
        const x = xOf(i);
        if (!d.count) {
          return `<line x1="${x.toFixed(1)}" y1="${(padT + plotH).toFixed(1)}" x2="${x.toFixed(1)}" y2="${(padT + plotH - 2).toFixed(1)}" stroke="rgba(100,116,139,0.35)" stroke-width="2"/>`;
        }
        const y = yCount(d.count);
        const h = Math.max(2, padT + plotH - y);
        return `<rect x="${(x - barW / 2).toFixed(1)}" y="${y.toFixed(1)}" width="${barW.toFixed(1)}" height="${h.toFixed(1)}" rx="2" fill="${palette.bar}" stroke="${palette.barStroke}" stroke-width="0.8"/>
          <text x="${x.toFixed(1)}" y="${Math.max(padT + 8, y - 3).toFixed(1)}" text-anchor="middle" fill="${palette.label}" font-size="8" font-weight="800">${d.count}</text>`;
      }).join('');

      const gapByKey = new Map(series.gapPoints.map((g) => [g.key, g.gap]));
      const gapCoords = days
        .map((d, i) => (gapByKey.has(d.key) ? { x: xOf(i), y: yGap(gapByKey.get(d.key)), gap: gapByKey.get(d.key) } : null))
        .filter(Boolean);
      const gapLine = gapCoords.length >= 2
        ? `<polyline points="${gapCoords.map((c) => c.x.toFixed(1) + ',' + c.y.toFixed(1)).join(' ')}" fill="none" stroke="${palette.line}" stroke-width="1.6" stroke-dasharray="3 3" stroke-linejoin="round" stroke-linecap="round"/>`
        : '';
      const gapDots = gapCoords.map((c) =>
        `<circle cx="${c.x.toFixed(1)}" cy="${c.y.toFixed(1)}" r="2.4" fill="${palette.line}"/>`
      ).join('');

      const xLabels = days.map((d, i) => {
        const labelEvery = n > 40 ? 7 : n > 18 ? 2 : 1;
        if (labelEvery > 1 && i % labelEvery !== 0 && i !== n - 1 && i !== 0) return '';
        return `<text x="${xOf(i).toFixed(1)}" y="${H - 6}" text-anchor="middle" fill="#94a3b8" font-size="7" font-weight="700">${d.label}</text>`;
      }).join('');

      const emptyNote = !series.total
        ? `<text x="${(W / 2).toFixed(1)}" y="${(H / 2).toFixed(1)}" text-anchor="middle" fill="${palette.empty}" font-size="11" font-weight="800">まだ記録がありません</text>`
        : '';

      svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
      svg.style.width = W + 'px';
      svg.style.minWidth = Math.min(280, W) + 'px';
      svg.innerHTML = `<rect x="0" y="0" width="${W}" height="${H}" fill="transparent"/>${grid}${bars}${gapLine}${gapDots}${xLabels}${emptyNote}`;
      if (scrollEl) {
        requestAnimationFrame(() => {
          try { scrollEl.scrollLeft = Math.max(0, scrollEl.scrollWidth - scrollEl.clientWidth); } catch (_) { }
        });
      }
    }

    function paintAbstinenceWetRecover(pen, clean, now) {
      const labelEl = document.getElementById('abstinence-wet-timer-recover-label');
      const pctEl = document.getElementById('abstinence-wet-timer-recover-pct');
      const barEl = document.getElementById('abstinence-wet-timer-recover-bar');
      const hintEl = document.getElementById('abstinence-wet-timer-hint');
      const recoverDays = Number(pen && pen.recoverDays) || ABSTINENCE_WET_RECOVER_DAYS;
      const recoverMs = recoverDays * 24 * 60 * 60 * 1000;
      const lastAt = clean && clean.fromWet ? clean.lastAt : null;
      let active = false;
      let pct = 100;
      let label = pen && pen.total > 0 ? '身体減衰は回復済み' : '減衰なし';
      let hint = '夢精しても禁欲日数は消えません。身体の減衰は約2〜3日で薄れます。';
      if (pen && pen.activeCount && lastAt != null) {
        active = true;
        const elapsed = Math.max(0, now.getTime() - lastAt);
        pct = Math.max(0, Math.min(100, Math.round((elapsed / recoverMs) * 100)));
        const remainHours = Math.max(0, Math.ceil((recoverMs - elapsed) / (60 * 60 * 1000)));
        const remainLabel = remainHours >= 24
          ? `あと約${Math.ceil(remainHours / 24)}日`
          : (remainHours > 0 ? `あと約${remainHours}時間` : 'まもなく回復');
        const decay = Math.max(0, Number(pen.decayPct) || 0);
        label = `身体 −${decay}% · ${remainLabel}`;
        hint = pen.recoverHint
          ? `${pen.recoverHint}。夢精しても禁欲日数は消えません。`
          : `身体の減衰は約${recoverDays}日で薄れます。${remainLabel}が目安です。`;
      }
      if (labelEl) labelEl.textContent = active ? '身体回復（進行中）' : '身体回復';
      if (pctEl) pctEl.textContent = active ? `${pct}% · ${label}` : label;
      if (barEl) barEl.style.width = `${Math.max(0, Math.min(100, pct))}%`;
      if (hintEl) hintEl.textContent = hint;
    }

    function renderAbstinenceWetPanel(wetPen, slips) {
      const totalEl = document.getElementById('abstinence-wet-total');
      const recentEl = document.getElementById('abstinence-wet-recent');
      const decayEl = document.getElementById('abstinence-wet-decay');
      const sinceEl = document.getElementById('abstinence-wet-since');
      const noteEl = document.getElementById('abstinence-wet-note');
      const scienceEl = document.getElementById('abstinence-wet-science-text');
      const listEl = document.getElementById('abstinence-wet-list');
      const wets = getAbstinenceWetSlips(slips);
      const pen = wetPen || getAbstinenceWetPenalty(wets);
      const now = new Date();
      const clean = getAbstinenceWetCleanSnapshot(slips, now);
      paintAbstinenceEqualTimer({
        days: 'abstinence-wet-timer-days',
        hours: 'abstinence-wet-timer-hours',
        mins: 'abstinence-wet-timer-mins',
        best: 'abstinence-wet-timer-best',
        habit: 'abstinence-wet-timer-habit',
        next: 'abstinence-wet-timer-next',
        pct: 'abstinence-wet-timer-pct',
        bar: 'abstinence-wet-timer-mile-bar'
      }, clean);
      const timerSince = document.getElementById('abstinence-wet-timer-since');
      if (timerSince) {
        timerSince.textContent = clean.fromWet
          ? `前回の夢精 ${formatAbstinenceSlipTime(new Date(clean.lastAt).toISOString())}`
          : '前回の夢精なし（禁欲開始から計測）';
      }
      paintAbstinenceWetRecover(pen, clean, now);
      if (totalEl) totalEl.textContent = String(pen.total);
      if (recentEl) recentEl.textContent = String(pen.activeCount || 0);
      if (decayEl) decayEl.textContent = pen.decayPct > 0 ? `−${pen.decayPct}%` : '−0%';
      const since = getAbstinenceDaysSinceLastWet(wets);
      if (sinceEl) sinceEl.textContent = since == null ? '—' : formatAbstinenceSlipAgeLabel(since);
      if (noteEl) {
        if (pen.total === 0) {
          noteEl.textContent = '夢精は日数を消しません。射精を伴うため、温存精子と身体エネルギーは短期間下がります。';
        } else if (pen.decayPct > 0) {
          noteEl.textContent = `身体側 −${pen.decayPct}%。${pen.recoverHint || ''} 温存精子は約${ABSTINENCE_WET_SPERM_REBUILD_DAYS}日かけて戻る目安です。`;
        } else {
          noteEl.textContent = pen.recoverHint || '夢精の身体減衰は回復済みです。';
        }
      }
      if (scienceEl) {
        scienceEl.textContent = '意図的な閲覧ではないので継続日数は維持。射精後は精巣の再充満・一時的なだるさが数日かかることがある、という一般的な目安です（個人差大・医学診断ではありません）。';
      }
      rememberAbstinenceWetSlips(wets);
      renderAbstinenceEventDayChart({
        svgId: 'abstinence-wet-chart',
        hintId: 'abstinence-wet-chart-hint',
        scrollId: 'abstinence-wet-chart-scroll',
        events: getAbstinenceWetSlipsForChart(),
        daySpan: ABSTINENCE_SLIP_CHART_MAX_DAYS,
        lifetime: true,
        palette: {
          bar: 'rgba(139,92,246,0.78)',
          barStroke: 'rgba(196,181,253,0.9)',
          line: 'rgba(34,211,238,0.9)',
          label: '#ddd6fe',
          empty: '#64748b'
        }
      });
      if (listEl) {
        listEl.innerHTML = '';
        const recent = wets.slice(0, 5);
        const byId = {};
        (pen.perSlip || []).forEach((p) => { byId[p.id] = p; });
        if (!recent.length) {
          listEl.innerHTML = '<p class="text-slate-500 text-[11px] font-bold">まだ登録はありません。</p>';
        } else {
          recent.forEach((s, idx) => {
            const info = byId[s.id];
            const active = info && info.weight > ABSTINENCE_SLIP_ACTIVE_EPS;
            const right = active ? `身体 −${info.hitPct}%` : (idx === 0 ? '回復済' : '回復済');
            const row = document.createElement('div');
            row.className = 'flex justify-between items-center gap-2 px-2.5 py-1.5 rounded-lg bg-black/40 border border-violet-900/40 text-violet-100/90';
            row.innerHTML = `<span>${formatAbstinenceSlipTime(s.at)}</span><span class="text-violet-400/80">${right}</span>`;
            listEl.appendChild(row);
          });
        }
      }
    }

    function renderAbstinenceSlipPanel(penalty, slips, charmLost) {
      const totalEl = document.getElementById('abstinence-slip-total');
      const recentEl = document.getElementById('abstinence-slip-recent');
      const decayEl = document.getElementById('abstinence-slip-decay');
      const disappointBox = document.getElementById('abstinence-slip-disappoint');
      const disappointText = document.getElementById('abstinence-slip-disappoint-text');
      const listEl = document.getElementById('abstinence-slip-list');
      const atInput = document.getElementById('abstinence-slip-at-input');
      if (atInput && !atInput.value) fillAbstinenceSlipAtNow();

      if (totalEl) totalEl.textContent = String(penalty.total);
      if (recentEl) recentEl.textContent = String(penalty.activeCount != null ? penalty.activeCount : penalty.recent7);
      if (decayEl) decayEl.textContent = penalty.decayPct > 0 ? `−${penalty.decayPct}%` : '−0%';

      const now = new Date();
      const clean = getAbstinenceViewCleanSnapshot(slips, now);
      paintAbstinenceEqualTimer({
        days: 'abstinence-slip-timer-days',
        hours: 'abstinence-slip-timer-hours',
        mins: 'abstinence-slip-timer-mins',
        best: 'abstinence-slip-timer-best',
        habit: 'abstinence-slip-timer-habit',
        next: 'abstinence-slip-timer-next',
        pct: 'abstinence-slip-timer-pct',
        bar: 'abstinence-slip-timer-mile-bar'
      }, clean);
      const sinceEl = document.getElementById('abstinence-slip-timer-since');
      const recoverLabel = document.getElementById('abstinence-slip-timer-recover-label');
      const recoverPctEl = document.getElementById('abstinence-slip-timer-recover-pct');
      const recoverBar = document.getElementById('abstinence-slip-timer-recover-bar');
      const timerHint = document.getElementById('abstinence-slip-timer-hint');
      const cleanLine = document.getElementById('abstinence-view-clean-line');
      if (sinceEl) {
        sinceEl.textContent = clean.fromSlip
          ? `前回閲覧 ${formatAbstinenceSlipTime(new Date(clean.lastAt).toISOString())}`
          : '前回閲覧なし（禁欲開始から計測）';
      }
      const recover = getAbstinenceViewRecoverProgress(penalty, now);
      if (recoverLabel) recoverLabel.textContent = recover.active ? '減衰回復（進行中）' : '減衰回復';
      if (recoverPctEl) recoverPctEl.textContent = recover.active ? `${recover.pct}% · ${recover.label}` : recover.label;
      if (recoverBar) recoverBar.style.width = `${Math.max(0, Math.min(100, recover.pct))}%`;
      if (timerHint) timerHint.textContent = recover.hint;
      if (cleanLine) {
        cleanLine.textContent = clean.fromSlip
          ? `閲覧クリーン ${clean.label}`
          : `閲覧クリーン ${clean.label}（未スリップ）`;
      }

      const avgEl = document.getElementById('abstinence-slip-avg-reset');
      const noteEl = document.getElementById('abstinence-slip-reset-note');
      const resetStats = getAbstinenceResetStats();
      const resetCount = resetStats.length;
      const avg = resetCount
        ? resetStats.reduce((sum, s) => sum + (Number(s.slipCount) || 0), 0) / resetCount
        : NaN;
      if (avgEl) avgEl.textContent = resetCount ? formatAbstinenceResetAverage(avg) : '—';
      if (noteEl) {
        if (resetCount === 0) {
          noteEl.textContent = `今回の継続は閲覧${penalty.total}回。リセット履歴が貯まると、何回の閲覧でタイマーを戻しているかの平均が出ます。`;
        } else {
          noteEl.textContent = `過去${resetCount}回のリセットで、平均${formatAbstinenceResetAverage(avg)}回の閲覧スリップのあとにカウントを戻しています。今回の継続は閲覧${penalty.total}回です。`;
        }
      }

      if (disappointBox && disappointText) {
        if (penalty.decayPct > 0) {
          disappointBox.classList.remove('hidden');
          let msg = penalty.message || '';
          if (charmLost > 0) {
            msg += ` 魅力度 −${charmLost}。でもタイマーは生きている。`;
          } else {
            msg += ' でもタイマーは生きている。';
          }
          if (penalty.recoverHint) msg += ` ${penalty.recoverHint}。`;
          disappointText.textContent = msg;
        } else if (penalty.total > 0 && penalty.recoverHint) {
          disappointBox.classList.remove('hidden');
          disappointText.textContent = penalty.recoverHint + '。履歴は残っていますが、パラメータへの影響はありません。';
        } else {
          disappointBox.classList.add('hidden');
          disappointText.textContent = '';
        }
      }

      if (listEl) {
        listEl.innerHTML = '';
        const recent = getAbstinenceViewSlips(slips).slice(0, 5);
        const byId = {};
        (penalty.perSlip || []).forEach((p) => { byId[p.id] = p; });
        if (recent.length === 0) {
          listEl.innerHTML = '<p class="text-slate-500 text-[11px] font-bold">まだ登録はありません。</p>';
        } else {
          recent.forEach((s, idx) => {
            const info = byId[s.id];
            const active = info && info.weight > ABSTINENCE_SLIP_ACTIVE_EPS;
            const right = active
              ? `減衰 −${info.hitPct}%`
              : (idx === 0 ? '回復済' : '回復済');
            const row = document.createElement('div');
            row.className = 'flex justify-between items-center gap-2 px-2.5 py-1.5 rounded-lg bg-black/40 border border-rose-900/40 text-rose-100/90';
            row.innerHTML = `<span>${formatAbstinenceSlipTime(s.at)}</span><span class="text-rose-400/80">${right}</span>`;
            listEl.appendChild(row);
          });
        }
      }
      rememberAbstinenceViewSlips(getAbstinenceViewSlips(slips));
      renderAbstinenceEventDayChart({
        svgId: 'abstinence-slip-chart',
        hintId: 'abstinence-slip-chart-hint',
        scrollId: 'abstinence-slip-chart-scroll',
        events: getAbstinenceViewSlipsForChart(),
        daySpan: ABSTINENCE_SLIP_CHART_MAX_DAYS,
        lifetime: true,
        palette: {
          bar: 'rgba(244,63,94,0.75)',
          barStroke: 'rgba(251,113,133,0.85)',
          line: 'rgba(251,191,36,0.85)',
          label: '#fda4af',
          empty: '#64748b'
        }
      });
    }

    function isAbstinenceEnabled() {
      return true;
    }

    function initAbstinenceUI() {
      const panel = document.getElementById('abstinence-panel');
      if (panel) panel.classList.remove('hidden');
      getAbstinenceStartDate();
      renderAbstinenceTimer();
      syncAbstinenceTimerState({ render: true }).catch(() => { });
      syncAbstinenceSlips({ render: true }).catch(() => { });
      if (!abstinenceTimerInterval) {
        abstinenceTimerInterval = setInterval(() => {
          renderAbstinenceTimer();
        }, 30000);
      }
    }

    const ABSTINENCE_PERF_RECOVERY_DAYS = 3.8;
    const ABSTINENCE_PERF_GROWTH_START = 2;

    function getAbstinenceStartDate() {
      const saved = localStorage.getItem('setting_abstinence_start_date');
      if (saved) return new Date(saved);
      const now = new Date();
      localStorage.setItem('setting_abstinence_start_date', now.toISOString());
      return now;
    }

    function formatAbstinenceSpermCount(n) {
      if (!Number.isFinite(n) || n <= 0) return '0';
      if (n >= 1e8) {
        const oku = n / 1e8;
        return `${oku >= 10 ? oku.toFixed(1) : oku.toFixed(2)}億`;
      }
      if (n >= 1e4) return `${Math.round(n / 1e4)}万`;
      return String(Math.round(n));
    }

    function getAbstinenceCharmProfile(days, hours) {
      const t = days + hours / 24;
      // フラットライン期（8〜13日）は一時的に伸びが鈍る
      const flatlineDip = (days >= 8 && days <= 13) ? 8 : 0;
      const clamp = (v) => Math.max(0, Math.min(100, Math.round(v)));
      const gaze = clamp(12 + t * 2.1 - flatlineDip * 0.4);
      const skin = clamp(10 + t * 1.6 - flatlineDip * 0.3);
      const aura = clamp(15 + t * 1.9 + Math.min(20, days * 0.25) - flatlineDip * 0.5);
      const presence = clamp(8 + t * 1.45 + Math.min(15, days * 0.2) - flatlineDip * 0.35);
      const score = clamp((gaze + skin + aura + presence) / 4);
      const delta = Math.max(0, score - 35);
      let rank = '萌芽';
      let blurb = '土台づくり。目力と睡眠の回復から魅力が立ち上がります。';
      if (score >= 85) {
        rank = '圧倒的存在感';
        blurb = '場の空気を変える磁場。落ち着きと自信が外に漏れ出やすい段階です。';
      } else if (score >= 70) {
        rank = '磁場強化';
        blurb = '第一印象がシャープに。視線・姿勢・声の通りが良くなりやすい目安です。';
      } else if (score >= 55) {
        rank = 'オーラ形成';
        blurb = '内側の余裕が外見に乗り始める。肌艶・目力の底上げを実感しやすい帯です。';
      } else if (score >= 40) {
        rank = '目力覚醒';
        blurb = 'テストステロンと自己効力感の初動。目つき・姿勢が引き締まりやすい。';
      } else if (days >= 8 && days <= 13) {
        rank = '調整期（フラット）';
        blurb = '一時的に感覚が鈍っても魅力の土台は積み上がっています。焦らず継続を。';
      }
      return { score, gaze, skin, aura, presence, delta, rank, blurb };
    }

    const ABSTINENCE_FIRST_EJAC_KEY = 'setting_abstinence_first_ejac_age';
    const ABSTINENCE_EJAC_FREQ_KEY = 'setting_abstinence_ejac_freq';
    const ABSTINENCE_EJAC_FREQ = {
      daily: { label: 'ほぼ毎日', reserve: 34, drain: 26 },
      few_week: { label: '週に2〜3回', reserve: 46, drain: 16 },
      weekly: { label: '週1回程度', reserve: 56, drain: 10 },
      few_month: { label: '月に2〜3回', reserve: 66, drain: 5 },
      monthly: { label: '月1回以下', reserve: 74, drain: 2 },
      abstaining: { label: 'もともと少なめ／禁欲気味', reserve: 72, drain: 0 }
    };
    const ABSTINENCE_CAPACITY_AXES = [
      { key: 'stage', label: '人前に立つ能力' },
      { key: 'confidence', label: '自信' },
      { key: 'health', label: '健康' },
      { key: 'athletic', label: '運動能力' },
      { key: 'thinking', label: '思考能力' }
    ];

    function getAbstinenceFirstEjacAge() {
      const n = parseInt(localStorage.getItem(ABSTINENCE_FIRST_EJAC_KEY) || '', 10);
      if (!Number.isFinite(n) || n < 8 || n > 25) return null;
      return n;
    }

    function getAbstinenceEjacFreq() {
      const v = localStorage.getItem(ABSTINENCE_EJAC_FREQ_KEY) || '';
      return ABSTINENCE_EJAC_FREQ[v] ? v : '';
    }

    function getActiveProfileAgeYears() {
      try {
        const p = typeof getProfileBirth === 'function' ? getProfileBirth() : null;
        if (!p || !p.date) return null;
        const birth = new Date(p.date);
        if (isNaN(birth.getTime())) return null;
        const now = new Date();
        let age = now.getFullYear() - birth.getFullYear();
        const m = now.getMonth() - birth.getMonth();
        if (m < 0 || (m === 0 && now.getDate() < birth.getDate())) age -= 1;
        return age >= 8 && age <= 120 ? age : null;
      } catch (e) {
        return null;
      }
    }

    function getAbstinenceFirstEjacMeta(age) {
      if (age == null) return { bias: 0, habit: 1, label: '未設定（中立）' };
      if (age <= 11) return { bias: -2, habit: 1.16, label: '起動が早い' };
      if (age <= 13) return { bias: 0, habit: 1.08, label: '一般的な起動' };
      if (age <= 15) return { bias: 2, habit: 1, label: '標準〜やや遅め' };
      if (age <= 17) return { bias: 3, habit: 0.94, label: '遅めの起動' };
      return { bias: 2, habit: 0.92, label: 'かなり遅めの起動' };
    }

    function hydrateAbstinenceCapacityInputs() {
      const ageEl = document.getElementById('abstinence-first-ejac-age');
      const freqEl = document.getElementById('abstinence-ejac-freq');
      if (ageEl && document.activeElement !== ageEl) {
        const age = getAbstinenceFirstEjacAge();
        ageEl.value = age == null ? '' : String(age);
      }
      if (freqEl && document.activeElement !== freqEl) {
        freqEl.value = getAbstinenceEjacFreq();
      }
    }

    function saveAbstinenceCapacitySettings() {
      const ageEl = document.getElementById('abstinence-first-ejac-age');
      const freqEl = document.getElementById('abstinence-ejac-freq');
      if (ageEl) {
        const n = parseInt(String(ageEl.value || '').trim(), 10);
        if (Number.isFinite(n) && n >= 8 && n <= 25) localStorage.setItem(ABSTINENCE_FIRST_EJAC_KEY, String(n));
        else localStorage.removeItem(ABSTINENCE_FIRST_EJAC_KEY);
      }
      if (freqEl) {
        if (ABSTINENCE_EJAC_FREQ[freqEl.value]) localStorage.setItem(ABSTINENCE_EJAC_FREQ_KEY, freqEl.value);
        else localStorage.removeItem(ABSTINENCE_EJAC_FREQ_KEY);
      }
      if (typeof renderAbstinenceTimer === 'function') renderAbstinenceTimer();
    }

    function abstinenceCapacityRadarPoints(values, cx, cy, r) {
      const n = values.length;
      return values.map((v, i) => {
        const ang = -Math.PI / 2 + (i * 2 * Math.PI) / n;
        const rr = r * (Math.max(0, Math.min(100, Number(v) || 0)) / 100);
        return `${(cx + Math.cos(ang) * rr).toFixed(1)},${(cy + Math.sin(ang) * rr).toFixed(1)}`;
      }).join(' ');
    }

    function getAbstinenceCapacityProfile(days, hours) {
      const t = (Number(days) || 0) + (Number(hours) || 0) / 24;
      const flatlineDip = (days >= 8 && days <= 13) ? 5 : 0;
      const firstAge = getAbstinenceFirstEjacAge();
      const freqKey = getAbstinenceEjacFreq();
      const first = getAbstinenceFirstEjacMeta(firstAge);
      const freq = ABSTINENCE_EJAC_FREQ[freqKey] || { label: '未設定', reserve: 50, drain: 10 };
      const profileAge = getActiveProfileAgeYears();
      const yearsActive = (profileAge && firstAge && profileAge > firstAge)
        ? Math.min(40, profileAge - firstAge)
        : null;
      const yearsForLoad = yearsActive == null ? 10 : yearsActive;
      // 過去習慣の負債は設定したまま固定せず、継続日数で減衰（一度設定→日数に連動）
      const habitLoad0 = Math.min(12, yearsForLoad * 0.22 * (freq.drain / 12) * first.habit);
      const habitDebt0 = freq.drain * first.habit * 0.85;
      // 継続日数に比例して伸びる（魅力ゲージと同系統）
      const growth = Math.min(
        54,
        t * 1.6
        + (days >= 7 ? 3 : 0)
        + (days >= 14 ? 3 : 0)
        + (days >= 21 ? 4 : 0)
        + (days >= 30 ? 4 : 0)
        + (days >= 66 ? 4 : 0)
      );
      const baseline = 26 + first.bias + freq.reserve * 0.16;
      const clamp = (v) => Math.max(8, Math.min(96, Math.round(v)));
      const axisAt = (tDays, extras) => {
        const tt = Number(tDays) || 0;
        const dDays = Math.floor(tt);
        const flat = (dDays >= 8 && dDays <= 13) ? 5 : 0;
        const g = Math.min(
          54,
          tt * 1.6
          + (dDays >= 7 ? 3 : 0)
          + (dDays >= 14 ? 3 : 0)
          + (dDays >= 21 ? 4 : 0)
          + (dDays >= 30 ? 4 : 0)
          + (dDays >= 66 ? 4 : 0)
        );
        const debt = habitDebt0 * Math.exp(-tt / 8);
        const load = habitLoad0 * Math.exp(-tt / 14);
        const b = baseline + g - debt - load - flat;
        return {
          stage: clamp(b + 4 + g * 0.12 + (extras.stage || 0)),
          confidence: clamp(b + 6 + first.bias * 0.6 + (extras.confidence || 0)),
          health: clamp(b + 8 + g * 0.08 + (extras.health || 0)),
          athletic: clamp(b + 2 + g * 0.16 + (dDays >= 7 ? 3 : 0) + (extras.athletic || 0)),
          thinking: clamp(b + 5 + g * 0.14 - flat * 0.4 + (extras.thinking || 0))
        };
      };
      const nowAxes = axisAt(t, {
        health: -(habitDebt0 * Math.exp(-t / 8)) * 0.08,
        athletic: -(habitDebt0 * Math.exp(-t / 8)) * 0.12,
        thinking: -flatlineDip * 0.2
      });
      const startAxes = axisAt(0, {});
      const stage = nowAxes.stage;
      const confidence = nowAxes.confidence;
      const health = nowAxes.health;
      const athletic = nowAxes.athletic;
      const thinking = nowAxes.thinking;
      const score = clamp((stage + confidence + health + athletic + thinking) / 5);
      const startScore = clamp((startAxes.stage + startAxes.confidence + startAxes.health + startAxes.athletic + startAxes.thinking) / 5);
      const delta = Math.max(0, score - startScore);
      const configured = !!(firstAge || freqKey);
      let rank = '萌芽';
      if (score >= 85) rank = '高出力';
      else if (score >= 70) rank = '安定発揮';
      else if (score >= 55) rank = '回復加速';
      else if (score >= 40) rank = '底上げ中';
      if (!configured) rank = '未設定';
      if (days >= 8 && days <= 13 && configured && score < 70) rank = '調整期（フラット）';

      let blurb = '年齢と頻度を一度入れると、禁欲日数に連動して5軸が上がります。';
      if (configured) {
        if (t < 1) {
          blurb = `${first.label}・${freq.label}を土台にしました。日数が伸びるとパラメータが自動で上がります。`;
        } else if (freqKey === 'daily' && t < 7) {
          blurb = '禁欲前の頻度が高めでも、継続日数に連動して回復側へ倒れていきます。';
        } else if (freq.drain <= 5 && t >= 7) {
          blurb = '温存が進み、自信と存在感が出やすい目安。思考のクリアさは睡眠が本体です。';
        } else if (firstAge != null && firstAge <= 11 && freq.drain >= 16 && t < 14) {
          blurb = '起動が早く習慣の影響を受けやすい型。続くほど伸びしろが出やすい目安です。';
        } else if (flatlineDip) {
          blurb = 'フラットライン前後は感覚が鈍っても、能力の土台は日数に連動して積み上がっています。';
        } else {
          blurb = `${first.label}・${freq.label}を一度設定済み。いまの継続（相当${formatAbstinenceEquivLabel(t)}）で自動換算中です。`;
        }
      }

      return {
        score, stage, confidence, health, athletic, thinking, delta, growth: Math.round(growth),
        rank, blurb, configured, firstAge, freqKey,
        firstLabel: first.label, freqLabel: freq.label,
        yearsActive, profileAge, t
      };
    }

    function renderAbstinenceCapacityViz(days, hours, mult, wetMult) {
      hydrateAbstinenceCapacityInputs();
      const cap = getAbstinenceCapacityProfile(days, hours);
      const wm = Number.isFinite(wetMult) ? wetMult : 1;
      // 夢精は運動・健康にやや強く、思考には弱めに効かせる
      const axisMult = {
        stage: mult,
        confidence: mult * Math.pow(wm, 0.85),
        health: mult * Math.pow(wm, 1.15),
        athletic: mult * Math.pow(wm, 1.25),
        thinking: mult * Math.pow(wm, 0.55)
      };
      const axes = ABSTINENCE_CAPACITY_AXES.map((ax) => ({
        ...ax,
        value: applyAbstinenceSlipMult(cap[ax.key], axisMult[ax.key] != null ? axisMult[ax.key] : mult)
      }));
      const score = applyAbstinenceSlipMult(cap.score, mult);
      const shape = document.getElementById('abstinence-capacity-shape');
      if (shape) {
        shape.setAttribute('points', abstinenceCapacityRadarPoints(axes.map((a) => a.value), 110, 110, 80));
        shape.setAttribute('opacity', cap.configured ? '1' : '0.35');
      }
      const scoreEl = document.getElementById('abstinence-capacity-score');
      if (scoreEl) scoreEl.textContent = cap.configured ? String(score) : '—';
      const capEquivEl = document.getElementById('abstinence-capacity-equiv');
      if (capEquivEl) {
        const t = (Number(days) || 0) + (Number(hours) || 0) / 24;
        const equiv = t * Math.max(0.05, Math.min(1, Number(mult) || 1));
        capEquivEl.textContent = `相当${formatAbstinenceEquivLabel(equiv)}`;
      }
      const deltaEl = document.getElementById('abstinence-capacity-delta');
      if (deltaEl) {
        if (!cap.configured) deltaEl.textContent = '設定待ち';
        else deltaEl.textContent = `継続 +${Math.max(0, applyAbstinenceSlipMult(cap.delta, mult))}`;
      }
      axes.forEach((ax) => {
        const vEl = document.getElementById(`abstinence-capacity-${ax.key}-val`);
        const bEl = document.getElementById(`abstinence-capacity-${ax.key}-bar`);
        if (vEl) vEl.textContent = cap.configured ? String(ax.value) : '—';
        if (bEl) bEl.style.width = cap.configured ? `${ax.value}%` : '0%';
      });
      const rankEl = document.getElementById('abstinence-capacity-rank');
      if (rankEl) rankEl.textContent = cap.rank;
      const blurbEl = document.getElementById('abstinence-capacity-blurb');
      if (blurbEl) {
        blurbEl.textContent = (mult < 1 && cap.configured)
          ? `${cap.blurb} 閲覧スリップで表示は減衰中。`
          : cap.blurb;
      }
      const metaEl = document.getElementById('abstinence-capacity-meta');
      if (metaEl) {
        const bits = [];
        bits.push(cap.firstAge != null ? `最初の射精 ${cap.firstAge}歳（${cap.firstLabel}）` : '最初の射精 未設定');
        bits.push(cap.freqKey ? `禁欲前 ${cap.freqLabel}` : '頻度 未設定');
        if (cap.configured) {
          bits.push(`日数連動 継続+${cap.delta}`);
        }
        if (cap.yearsActive != null) bits.push(`起動から約${cap.yearsActive}年`);
        else if (cap.profileAge == null) bits.push('生年月日があると経過年も加味');
        metaEl.textContent = bits.join(' · ');
      }
    }

    const ABSTINENCE_BODY_MODE_KEY = 'setting_abstinence_body_mode';
    let abstinenceBodySelectedId = null;
    let abstinenceBodyState = null;
    let abstinenceBodyDrag = null;
    let abstinenceBodyPose = { ry: -24, rx: 8 };
    let abstinenceBodyOrbit = true;

    const ABSTINENCE_BODY_REGIONS = [
      {
        id: 'brain',
        label: '脳・報酬系',
        evidence: '中',
        source: 'キュー反応（Voon ら）／睡眠と認知',
        loadWeight: 0.92,
        recoverAt: (days) => 12 + Math.min(78, days * 1.15 + (days >= 21 ? 8 : 0)),
        note: (days, load, slipAge) => {
          if (load >= 28) return '閲覧の「次がある」期待が報酬系を再点火しやすい。ここで画面を閉じると、リセットより学習の破壊は小さい。';
          if (days <= 2) return 'イライラと欲求が強い帯。報酬の期待がまだ大きい。睡眠を守ると翌日の自制が楽になる。';
          if (days <= 13) return 'フラットライン前後は感覚が鈍っても、脳が壊れたわけではない。きっかけを踏まない練習期間。';
          if (days <= 29) return '脳の霧が晴れやすい目安。集中の改善は、深夜閲覧をやめて眠れた効果として説明しやすい。';
          return '自動反応が弱まりやすい維持期。完了ではなく、キューに負ける間隔が空くのが成功。';
        }
      },
      {
        id: 'eyes',
        label: '目・視覚キュー',
        evidence: '中',
        source: '視覚手がかり反応／睡眠負債',
        loadWeight: 1,
        recoverAt: (days) => 10 + Math.min(80, days * 1.35),
        note: (days, load) => {
          if (load >= 28) return '映像の新奇さそのものが条件づけを更新する。目と脳が同時に負荷。見た直後〜数日がチェイサー帯。';
          if (days <= 6) return '画面を閉じる練習が本体。目の疲れ・目力は禁欲より睡眠と照明の影響が大きい。';
          if (days <= 20) return '夜更かし閲覧が減ると、目覚めと視線のシャープさが出やすい。';
          return '澄んだ視線は睡眠・姿勢・画面時間の副産物として出やすい。俗説の超能力視は言い過ぎ。';
        }
      },
      {
        id: 'skin',
        label: '肌・顔',
        evidence: '弱',
        source: '睡眠・水分が主因。禁欲単独の証明は弱い',
        loadWeight: 0.5,
        recoverAt: (days) => 8 + Math.min(72, days * 0.95),
        note: (days, load) => {
          if (load >= 28) return '深夜閲覧の睡眠負債が翌日の顔に出やすい。禁欲日数は残っていても、肌の表示は削られる。';
          if (days <= 7) return 'ツヤの変化を禁欲だけに帰するのは根拠が弱い。水と睡眠を優先。';
          if (days <= 29) return '皮脂バランスやハリは、眠れた週に出やすい目安。';
          return 'キメ細やかさは生活全体。運動・食事・ストレスの寄与を切り分けられない。';
        }
      },
      {
        id: 'heart',
        label: '心肺・活力',
        evidence: '弱',
        source: '睡眠制限とT・気分の一般報告',
        loadWeight: 0.48,
        recoverAt: (days) => 14 + Math.min(76, days * 1.05 + (days >= 7 ? 6 : 0)),
        note: (days, load) => {
          if (load >= 28) return '夜更かしが自律神経をざわつかせ、翌日の活力と自制を下げやすい。';
          if (days <= 6) return '身体は回復モードへ。動悸やエネルギー感の本体は睡眠リズム。';
          if (days <= 29) return '目覚めの良さ・疲れにくさは、夜の時間の使い方が変わった効果として説明しやすい。';
          return '高い活力の維持は運動習慣の寄与が大きい。禁欲だけで心肺が覚醒する証拠は弱い。';
        }
      },
      {
        id: 'core',
        label: '体幹・姿勢',
        evidence: '俗説',
        source: '姿勢変化は運動開始と混同しやすい',
        loadWeight: 0.32,
        recoverAt: (days) => 6 + Math.min(70, days * 0.55 + (days >= 60 ? 12 : 0)),
        note: (days, load) => {
          if (load >= 28) return '閲覧後のだるさで猫背・閉じこもりが出やすい。立ち上がって2分歩くだけでも向きが戻る。';
          if (days <= 20) return 'この帯では姿勢の劇的変化は出にくい。体を使い始めると先に変わる。';
          if (days <= 89) return '体幹の安定は、継続中に運動を始めた効果と切り分けにくい。';
          return '覇気・オーラの一部は姿勢から来る。鍛えた結果として読むのが妥当。';
        }
      },
      {
        id: 'pelvis',
        label: 'ホルモン・生殖',
        evidence: '中',
        source: 'Jiang 2003（n=28）の7日ピーク／射精後プロラクチンは一時的',
        loadWeight: 0.72,
        recoverAt: (days) => {
          if (days <= 0) return 16;
          if (days < 7) return 16 + (days / 7) * 76;
          if (days === 7) return 94;
          if (days <= 13) return Math.max(58, 94 - (days - 7) * 5.2);
          return Math.min(86, 62 + (days - 13) * 0.22);
        },
        note: (days, load) => {
          if (load >= 28) return '射精なしでもチェイサー（追い欲求）が出やすい。ホルモンが長期破壊される証拠は弱く、危ないのは連続閲覧。';
          if (days <= 2) return 'Tは日内変動の方が大きい。「0日目から急上昇」は根拠が弱い。';
          if (days === 7) return 'よく引用される7日ピーク帯（Jiang n=28）。筋肉や魅力が1.45倍になる意味ではない。';
          if (days <= 13) return 'ピーク後はベース付近へ戻りやすい曲線。フラットライン＝ホルモンゼロ、ではない。';
          return '長期のT崩壊・蓄積無限は俗説。健康指標は睡眠・孤立の減少で説明されることが多い。';
        }
      },
      {
        id: 'legs',
        label: '脚・スタミナ',
        evidence: '弱',
        source: '睡眠と活動量。無尽蔵スタミナは比喩',
        loadWeight: 0.28,
        recoverAt: (days) => 8 + Math.min(74, days * 0.7 + (days >= 14 ? 8 : 0)),
        note: (days, load) => {
          if (load >= 28) return '夜更かしで脚のだるさ・翌日の運動回避が起きやすい。負荷の出口は歩くこと。';
          if (days <= 6) return 'そわそわを短い散歩に変えると、欲求のピークをやり過ごしやすい。';
          if (days <= 29) return '疲れにくさは睡眠と軽い運動の回復として出やすい。';
          return '「疲れを知らない」はモチベ表現。実際は体を動かした継続がスタミナになる。';
        }
      }
    ];

    function clampAbstinencePct(v) {
      return Math.max(0, Math.min(100, Math.round(v)));
    }

    function getAbstinenceDaysSinceLastSlip(slips, now = new Date()) {
      if (!slips || !slips.length) return null;
      let last = 0;
      slips.forEach((s) => {
        const t = new Date(s.at).getTime();
        if (Number.isFinite(t) && t > last) last = t;
      });
      if (!last) return null;
      return Math.max(0, (now.getTime() - last) / (24 * 60 * 60 * 1000));
    }

    function formatAbstinenceSlipAgeLabel(daysFloat) {
      if (daysFloat == null) return 'なし';
      if (daysFloat < 1 / 24) return 'たった今';
      if (daysFloat < 1) return `${Math.max(1, Math.round(daysFloat * 24))}時間前`;
      if (daysFloat < 1.5) return '1日目';
      return `${Math.floor(daysFloat)}日目`;
    }

    function getAbstinenceBodyState(days, penalty, slips, now = new Date(), paramDays, wetPenalty) {
      const decay = penalty && Number.isFinite(penalty.decayPct) ? penalty.decayPct : 0;
      const wetDecay = wetPenalty && Number.isFinite(wetPenalty.decayPct) ? wetPenalty.decayPct : 0;
      const slipAge = getAbstinenceDaysSinceLastSlip(getAbstinenceViewSlips(slips), now);
      const wetAge = getAbstinenceDaysSinceLastWet(slips, now);
      const pDays = Number.isFinite(paramDays) ? paramDays : days;
      const regions = ABSTINENCE_BODY_REGIONS.map((meta) => {
        const recoverDays = meta.id === 'pelvis' ? days : pDays;
        const recover = clampAbstinencePct(meta.recoverAt(recoverDays));
        const viewLoad = decay * meta.loadWeight;
        const wetLoad = wetDecay * (meta.id === 'pelvis' ? 0.95 : meta.id === 'core' ? 0.45 : 0.2);
        const load = clampAbstinencePct(viewLoad + wetLoad);
        return {
          id: meta.id,
          label: meta.label,
          evidence: meta.evidence,
          source: meta.source,
          recover,
          load,
          note: meta.note(days, load, slipAge != null ? slipAge : wetAge)
        };
      });
      let autoId = 'brain';
      if (wetDecay >= 12) autoId = 'pelvis';
      else if (decay >= 15) autoId = 'eyes';
      else if (days === 7) autoId = 'pelvis';
      else if (days >= 60) autoId = 'core';
      return { days, decay: decay + wetDecay * 0.5, slipAge, regions, autoId };
    }

    function getAbstinenceBodyMode() {
      const saved = localStorage.getItem(ABSTINENCE_BODY_MODE_KEY);
      return saved === '3d' ? '3d' : '2d';
    }

    function applyAbstinenceBodyTransform(mode, ry, rx) {
      const wrap = document.getElementById('abstinence-body-wrap');
      const rig = document.getElementById('abstinence-body-rig');
      const hint = document.getElementById('abstinence-body-orbit-hint');
      const btn2 = document.getElementById('abstinence-body-mode-2d');
      const btn3 = document.getElementById('abstinence-body-mode-3d');
      const rotL = document.getElementById('abstinence-body-rot-left');
      const rotR = document.getElementById('abstinence-body-rot-right');
      const dragging = !!(abstinenceBodyDrag && abstinenceBodyDrag.down);
      if (wrap) {
        wrap.classList.toggle('abstinence-body-mode-3d', mode === '3d');
        wrap.classList.toggle('abstinence-body-mode-2d', mode === '2d');
        wrap.classList.toggle('is-orbiting', mode === '3d' && abstinenceBodyOrbit && !dragging);
      }
      if (rig) {
        const y = mode === '3d' ? (ry != null ? ry : abstinenceBodyPose.ry) : 0;
        const x = mode === '3d' ? (rx != null ? rx : abstinenceBodyPose.rx) : 0;
        abstinenceBodyPose = { ry: y, rx: x };
        rig.style.setProperty('--abs-ry', y + 'deg');
        rig.style.setProperty('--abs-rx', x + 'deg');
        if (mode === '3d' && !(abstinenceBodyOrbit && !dragging)) {
          rig.style.transform = `rotateY(${y}deg) rotateX(${x}deg)`;
        } else if (mode !== '3d') {
          rig.style.transform = 'rotateY(0deg) rotateX(0deg)';
        } else {
          rig.style.transform = '';
        }
      }
      if (hint) hint.classList.toggle('hidden', mode !== '3d');
      if (rotL) rotL.classList.toggle('hidden', mode !== '3d');
      if (rotR) rotR.classList.toggle('hidden', mode !== '3d');
      const on = 'px-2.5 py-1 rounded-lg border border-cyan-400/70 text-[10px] font-extrabold text-cyan-100 bg-cyan-950/70';
      const off = 'px-2.5 py-1 rounded-lg border border-cyan-800/50 text-[10px] font-extrabold text-cyan-300 bg-black/40';
      if (btn2) btn2.className = mode === '2d' ? on : off;
      if (btn3) btn3.className = mode === '3d' ? on : off;
    }

    function setAbstinenceBodyMode(mode) {
      const next = mode === '3d' ? '3d' : '2d';
      localStorage.setItem(ABSTINENCE_BODY_MODE_KEY, next);
      abstinenceBodyDrag = null;
      if (next === '3d') {
        abstinenceBodyOrbit = true;
        abstinenceBodyPose = { ry: -24, rx: 8 };
      }
      applyAbstinenceBodyTransform(next, abstinenceBodyPose.ry, abstinenceBodyPose.rx);
      if (next === '3d') {
        const wrap = document.getElementById('abstinence-body-wrap');
        if (wrap) {
          wrap.classList.remove('is-orbiting');
          void wrap.offsetWidth;
          wrap.classList.add('is-orbiting');
        }
      }
    }

    function nudgeAbstinenceBody(deltaY) {
      localStorage.setItem(ABSTINENCE_BODY_MODE_KEY, '3d');
      abstinenceBodyOrbit = false;
      abstinenceBodyDrag = null;
      abstinenceBodyPose.ry = Math.max(-70, Math.min(70, (abstinenceBodyPose.ry || -24) + deltaY));
      applyAbstinenceBodyTransform('3d', abstinenceBodyPose.ry, abstinenceBodyPose.rx);
    }
    window.setAbstinenceBodyMode = setAbstinenceBodyMode;
    window.nudgeAbstinenceBody = nudgeAbstinenceBody;

    function selectAbstinenceBodyRegion(id) {
      if (!id) return;
      abstinenceBodySelectedId = id;
      const state = abstinenceBodyState;
      if (!state) return;
      const region = state.regions.find((r) => r.id === id);
      if (!region) return;
      document.querySelectorAll('#abstinence-body-hotspots .abstinence-body-hotspot').forEach((g) => {
        g.classList.toggle('is-selected', g.getAttribute('data-abs-region') === id);
      });
      document.querySelectorAll('#abstinence-body-region-chips [data-abs-region]').forEach((btn) => {
        const on = btn.getAttribute('data-abs-region') === id;
        btn.classList.toggle('border-cyan-400/70', on);
        btn.classList.toggle('bg-cyan-950/70', on);
        btn.classList.toggle('text-cyan-100', on);
        btn.classList.toggle('border-slate-700/50', !on);
        btn.classList.toggle('bg-black/40', !on);
        btn.classList.toggle('text-slate-300', !on);
      });
      const title = document.getElementById('abstinence-body-detail-title');
      const level = document.getElementById('abstinence-body-detail-level');
      const note = document.getElementById('abstinence-body-detail-note');
      const source = document.getElementById('abstinence-body-detail-source');
      const recVal = document.getElementById('abstinence-body-detail-recover-val');
      const recBar = document.getElementById('abstinence-body-detail-recover-bar');
      const loadVal = document.getElementById('abstinence-body-detail-load-val');
      const loadBar = document.getElementById('abstinence-body-detail-load-bar');
      if (title) title.textContent = region.label;
      if (level) {
        level.textContent = `根拠 ${region.evidence}`;
        level.className = `text-[10px] font-extrabold px-2 py-0.5 rounded border ${abstinenceScienceLevelClass(region.evidence)}`;
      }
      if (note) note.textContent = region.note;
      if (source) source.textContent = region.source;
      if (recVal) recVal.textContent = String(region.recover);
      if (recBar) recBar.style.width = `${region.recover}%`;
      if (loadVal) loadVal.textContent = String(region.load);
      if (loadBar) loadBar.style.width = `${region.load}%`;
    }

    function bindAbstinenceBodyMap() {
      const scene = document.getElementById('abstinence-body-scene');
      const svg = document.getElementById('abstinence-body-svg');
      if (!scene || scene.dataset.ready === '1') return;
      scene.dataset.ready = '1';
      if (svg) {
        svg.addEventListener('click', (event) => {
          const g = event.target.closest('[data-abs-region]');
          if (g) selectAbstinenceBodyRegion(g.getAttribute('data-abs-region'));
        });
      }
      const onMove = (event) => {
        if (!abstinenceBodyDrag || !abstinenceBodyDrag.down || getAbstinenceBodyMode() !== '3d') return;
        event.preventDefault();
        const dx = event.clientX - abstinenceBodyDrag.x;
        const dy = event.clientY - abstinenceBodyDrag.y;
        abstinenceBodyDrag.x = event.clientX;
        abstinenceBodyDrag.y = event.clientY;
        abstinenceBodyDrag.ry = Math.max(-70, Math.min(70, abstinenceBodyDrag.ry + dx * 0.55));
        abstinenceBodyDrag.rx = Math.max(-18, Math.min(22, abstinenceBodyDrag.rx - dy * 0.28));
        abstinenceBodyPose = { ry: abstinenceBodyDrag.ry, rx: abstinenceBodyDrag.rx };
        applyAbstinenceBodyTransform('3d', abstinenceBodyDrag.ry, abstinenceBodyDrag.rx);
      };
      const onUp = (event) => {
        if (abstinenceBodyDrag) abstinenceBodyDrag.down = false;
        if (event && scene.hasPointerCapture && scene.hasPointerCapture(event.pointerId)) {
          scene.releasePointerCapture(event.pointerId);
        }
      };
      scene.addEventListener('pointerdown', (event) => {
        if (getAbstinenceBodyMode() !== '3d') return;
        if (event.target.closest('[data-abs-region]')) return;
        abstinenceBodyOrbit = false;
        const ry = Number.isFinite(abstinenceBodyPose.ry) ? abstinenceBodyPose.ry : -24;
        const rx = Number.isFinite(abstinenceBodyPose.rx) ? abstinenceBodyPose.rx : 8;
        abstinenceBodyDrag = { x: event.clientX, y: event.clientY, ry, rx, down: true };
        applyAbstinenceBodyTransform('3d', ry, rx);
        scene.setPointerCapture(event.pointerId);
      });
      scene.addEventListener('pointermove', onMove);
      scene.addEventListener('pointerup', onUp);
      scene.addEventListener('pointercancel', onUp);
    }

    function renderAbstinenceBodyMap(days, penalty, slips, paramDays, equivT, wetPenalty) {
      bindAbstinenceBodyMap();
      const state = getAbstinenceBodyState(days, penalty, slips, new Date(), paramDays, wetPenalty);
      abstinenceBodyState = state;
      applyAbstinenceBodyTransform(
        getAbstinenceBodyMode(),
        abstinenceBodyDrag && getAbstinenceBodyMode() === '3d' ? abstinenceBodyDrag.ry : undefined,
        abstinenceBodyDrag && getAbstinenceBodyMode() === '3d' ? abstinenceBodyDrag.rx : undefined
      );
      const daysEl = document.getElementById('abstinence-body-days');
      const paramDaysEl = document.getElementById('abstinence-body-param-days');
      const ageEl = document.getElementById('abstinence-body-slip-age');
      const loadEl = document.getElementById('abstinence-body-load');
      if (daysEl) daysEl.textContent = String(days);
      if (paramDaysEl) paramDaysEl.textContent = formatAbstinenceEquivDaysNumber(equivT != null ? equivT : paramDays);
      if (ageEl) ageEl.textContent = formatAbstinenceSlipAgeLabel(state.slipAge);
      if (loadEl) loadEl.textContent = state.decay > 0 ? `−${Math.round(state.decay)}%` : '−0%';

      const wrap = document.getElementById('abstinence-body-wrap');
      const scene = document.getElementById('abstinence-body-scene');
      const vitalityHost = scene || wrap;
      if (vitalityHost) {
        const avg = state.regions.reduce((s, r) => s + (Number(r.recover) || 0), 0) / Math.max(1, state.regions.length);
        const loadAvg = state.regions.reduce((s, r) => s + (Number(r.load) || 0), 0) / Math.max(1, state.regions.length);
        const vitality = Math.max(0.18, Math.min(1, (avg / 100) * (1 - loadAvg / 180)));
        vitalityHost.style.setProperty('--abs-vitality', vitality.toFixed(3));
      }

      state.regions.forEach((region) => {
        const g = document.querySelector(`#abstinence-body-hotspots [data-abs-region="${region.id}"]`);
        if (!g) return;
        const rec = g.querySelector('.abs-hot-recover');
        const load = g.querySelector('.abs-hot-load');
        if (rec) rec.setAttribute('fill-opacity', String(0.08 + region.recover / 140));
        if (load) {
          load.setAttribute('fill-opacity', String(region.load / 130));
          load.setAttribute('data-active', region.load >= 18 ? '1' : '0');
        }
      });

      const chips = document.getElementById('abstinence-body-region-chips');
      if (chips && chips.dataset.ready !== '1') {
        chips.dataset.ready = '1';
        chips.innerHTML = ABSTINENCE_BODY_REGIONS.map((meta) =>
          `<button type="button" data-abs-region="${meta.id}" onclick="selectAbstinenceBodyRegion('${meta.id}')" class="px-2 py-1 rounded-lg border border-slate-700/50 bg-black/40 text-slate-300 text-[10px] font-extrabold">${meta.label}</button>`
        ).join('');
      }

      const selected = abstinenceBodySelectedId && state.regions.some((r) => r.id === abstinenceBodySelectedId)
        ? abstinenceBodySelectedId
        : state.autoId;
      selectAbstinenceBodyRegion(selected);
    }

    function abstinenceBuffGainSnapshot(paramDays, paramHours, mult) {
      const pd = Number(paramDays) || 0;
      const ph = Number(paramHours) || 0;
      const m = Number.isFinite(mult) ? mult : 1;
      const apply = (v) => Math.max(0, Math.round(applyAbstinenceSlipMult(v, m)));
      return {
        willpower: apply(pd * 10 + ph),
        sleepScore: Math.min(100, apply(Math.min(100, Math.floor(pd * 1.2)))),
        productivity: Math.min(55, apply(Math.min(55, Math.floor(pd * 1.4 + ph * 0.06)))),
        focusBlocks: apply(Math.floor((pd * 30 + ph * 1.25) / 25)),
        urges: apply(pd * 2 + Math.floor(ph / 12))
      };
    }

    function buildAbstinenceBuffCatalogSections() {
      const charmRankRows = [
        { minScore: 40, rank: '目力覚醒', effect: '目つき・姿勢が引き締まりやすい' },
        { minScore: 55, rank: 'オーラ形成', effect: '肌艶・目力の底上げを実感しやすい' },
        { minScore: 70, rank: '磁場強化', effect: '視線・姿勢・声の通りが良くなりやすい' },
        { minScore: 85, rank: '圧倒的存在感', effect: '場の空気を変える磁場（上限付近）' }
      ];
      const capacityRankRows = [
        { minScore: 40, rank: '底上げ中', effect: '5軸（人前・自信・健康・運動・思考）が上昇開始' },
        { minScore: 55, rank: '回復加速', effect: '習慣負債が薄れ、各軸が底上げ' },
        { minScore: 70, rank: '安定発揮', effect: 'フラット期を除き安定した出力帯' },
        { minScore: 85, rank: '高出力', effect: '5軸総合が高水準（設定済み時）' }
      ];
      const capacityBonusRows = [
        { days: 7, effect: '能力成長 +3（全5軸の日数連動）' },
        { days: 14, effect: '能力成長 +3' },
        { days: 21, effect: '能力成長 +4' },
        { days: 30, effect: '能力成長 +4' },
        { days: 66, effect: '能力成長 +4（習慣化の平均日数付近）' }
      ];
      const gainMilestones = [1, 3, 7, 14, 21, 30, 60, 90].map((d) => {
        const snap = abstinenceBuffGainSnapshot(d, 0, 1);
        return {
          days: d,
          effect: `意志力 ${snap.willpower}pt · 睡眠 ${snap.sleepScore}/100 · 生産性 +${snap.productivity}% · 集中 ${snap.focusBlocks}枠`
        };
      });
      const stageRows = ABSTINENCE_STAGES.map((s) => ({
        days: s.minDays,
        label: s.title.replace(/^【[^】]+】/, '').trim(),
        effect: `${s.mental.slice(0, 36)}… / ${s.physical.slice(0, 36)}…`
      }));
      return [
        {
          id: 'rank',
          title: '称号バッジ',
          basis: 'days',
          unit: '日',
          items: ABSTINENCE_RANKS.map((r) => ({
            threshold: r.minDays,
            label: r.rank,
            effect: 'カウンター上の称号が更新'
          }))
        },
        {
          id: 'milestone',
          title: 'マイルストーン',
          basis: 'days',
          unit: '日',
          items: ABSTINENCE_MILESTONES.map((m) => ({
            threshold: m,
            label: ABSTINENCE_MILESTONE_LABELS[m] ? `${m}日（${ABSTINENCE_MILESTONE_LABELS[m]}）` : `${m}日`,
            effect: m === ABSTINENCE_HABIT_DAYS ? '習慣化の平均目安（Lally 2010）' : 'プログレスバーの節目'
          }))
        },
        {
          id: 'gains',
          title: '我慢で得ているもの（換算値）',
          basis: 'paramDays',
          unit: '相当日',
          items: gainMilestones.map((g) => ({
            threshold: g.days,
            label: `相当${g.days}日`,
            effect: g.effect
          }))
        },
        {
          id: 'charm',
          title: '魅力ランク',
          basis: 'charmScore',
          unit: 'スコア',
          items: charmRankRows.map((r) => ({
            threshold: r.minScore,
            label: r.rank,
            effect: r.effect
          }))
        },
        {
          id: 'capacity-bonus',
          title: '能力ボーナス（年齢・頻度設定時）',
          basis: 'paramDays',
          unit: '相当日',
          items: capacityBonusRows.map((r) => ({
            threshold: r.days,
            label: `${r.days}相当日`,
            effect: r.effect
          }))
        },
        {
          id: 'capacity-rank',
          title: '能力総合ランク（設定済み時）',
          basis: 'capacityScore',
          unit: 'スコア',
          items: capacityRankRows.map((r) => ({
            threshold: r.minScore,
            label: r.rank,
            effect: r.effect
          }))
        },
        {
          id: 'stage',
          title: 'フェーズ効果（精神・肉体）',
          basis: 'days',
          unit: '日',
          items: stageRows.map((s) => ({
            threshold: s.days,
            label: s.label,
            effect: s.effect
          }))
        }
      ];
    }

    function renderAbstinenceBuffCatalog(days, paramDays, paramHours, mult) {
      const root = document.getElementById('abstinence-buff-catalog');
      const summaryEl = document.getElementById('abstinence-buff-catalog-summary');
      if (!root) return;

      const d = Number(days) || 0;
      const pd = Number(paramDays) || 0;
      const ph = Number(paramHours) || 0;
      const m = Number.isFinite(mult) ? mult : 1;
      const charmBase = getAbstinenceCharmProfile(pd, ph);
      const charmScore = applyAbstinenceSlipMult(charmBase.score, m);
      const cap = getAbstinenceCapacityProfile(pd, ph);
      const capScore = cap.configured ? applyAbstinenceSlipMult(cap.score, m) : null;

      const basisValue = {
        days: d,
        paramDays: pd + ph / 24,
        charmScore,
        capacityScore: capScore == null ? -1 : capScore
      };

      const isAchieved = (section, threshold) => {
        const v = basisValue[section.basis];
        if (section.basis === 'capacityScore' && capScore == null) return false;
        return v >= threshold;
      };

      const sections = buildAbstinenceBuffCatalogSections();
      let nextLabel = '';
      outer: for (const section of sections) {
        if (section.basis === 'capacityScore' && capScore == null) continue;
        for (const item of section.items) {
          if (!isAchieved(section, item.threshold)) {
            nextLabel = `${section.title}：${item.label}`;
            break outer;
          }
        }
      }

      if (summaryEl) {
        const bits = [`継続 ${d}日`, `相当 ${formatAbstinenceEquivLabel(pd + ph / 24)}`];
        if (nextLabel) bits.push(`次 → ${nextLabel}`);
        summaryEl.textContent = bits.join(' · ');
      }

      const basisNote = {
        days: '継続日数',
        paramDays: '相当日数（減衰反映）',
        charmScore: `魅力スコア（現在 ${charmScore}/100）`,
        capacityScore: capScore == null ? '能力スコア（年齢・頻度未設定）' : `能力スコア（現在 ${capScore}/100）`
      };

      root.innerHTML = sections.map((section) => {
        let nextMarked = false;
        const rows = section.items.map((item) => {
          const achieved = isAchieved(section, item.threshold);
          const isNext = !achieved && !nextMarked && (section.basis !== 'capacityScore' || capScore != null);
          if (isNext) nextMarked = true;
          const rowCls = achieved
            ? 'border-emerald-700/50 bg-emerald-950/25'
            : isNext
              ? 'border-amber-600/50 bg-amber-950/20 ring-1 ring-amber-500/30'
              : 'border-slate-800/60 bg-black/20';
          const status = achieved
            ? '<span class="text-[9px] font-black text-emerald-300 bg-emerald-950/60 border border-emerald-700/40 px-1.5 py-0.5 rounded">達成</span>'
            : isNext
              ? '<span class="text-[9px] font-black text-amber-200 bg-amber-950/60 border border-amber-700/40 px-1.5 py-0.5 rounded">次</span>'
              : '<span class="text-[9px] font-black text-slate-500 bg-slate-900/60 border border-slate-700/40 px-1.5 py-0.5 rounded">—</span>';
          const threshLabel = section.basis === 'days' || section.basis === 'paramDays'
            ? `${item.threshold}${section.unit}`
            : `${item.threshold}+`;
          return `<div class="flex flex-wrap items-start gap-2 rounded-lg border px-2.5 py-2 ${rowCls}">
            <div class="shrink-0 w-14 text-[10px] font-mono font-extrabold text-cyan-300/90">${escapeHtmlText(threshLabel)}</div>
            <div class="flex-1 min-w-[8rem]">
              <div class="text-[11px] font-extrabold text-slate-100 leading-snug">${escapeHtmlText(item.label)}</div>
              <div class="text-[10px] font-bold text-slate-400 mt-0.5 leading-relaxed">${escapeHtmlText(item.effect)}</div>
            </div>
            <div class="shrink-0">${status}</div>
          </div>`;
        }).join('');
        return `<div class="space-y-1.5">
          <div class="flex flex-wrap items-baseline justify-between gap-2">
            <h5 class="text-[11px] font-extrabold text-cyan-200">${escapeHtmlText(section.title)}</h5>
            <span class="text-[9px] font-bold text-slate-500">${escapeHtmlText(basisNote[section.basis] || '')}</span>
          </div>
          <div class="space-y-1">${rows}</div>
        </div>`;
      }).join('');
    }

    function renderAbstinenceTimer() {
      const startDate = getAbstinenceStartDate();
      const now = new Date();
      let diffMs = now - startDate;
      if (diffMs < 0) diffMs = 0;

      const totalMins = Math.floor(diffMs / (1000 * 60));
      const totalHours = Math.floor(totalMins / 60);
      const days = Math.floor(totalHours / 24);
      const hours = totalHours % 24;
      const mins = totalMins % 60;

      const daysEl = document.getElementById('abstinence-counter-days');
      const hoursEl = document.getElementById('abstinence-counter-hours');
      const minsEl = document.getElementById('abstinence-counter-mins');

      if (daysEl) paintAbstinenceDayGlyphs(daysEl, days);
      if (hoursEl) hoursEl.textContent = String(hours).padStart(2, '0');
      if (minsEl) minsEl.textContent = String(mins).padStart(2, '0');
      const abstAccStatus = document.getElementById('abstinence-acc-status');
      if (abstAccStatus) abstAccStatus.textContent = `${days}日 ${String(hours).padStart(2, '0')}:${String(mins).padStart(2, '0')}`;

      const inputEl = document.getElementById('abstinence-start-input');
      if (inputEl) {
        const localIso = new Date(startDate.getTime() - (startDate.getTimezoneOffset() * 60000)).toISOString().slice(0, 16);
        inputEl.value = localIso;
      }

      let currentRank = ABSTINENCE_RANKS[0].rank;
      for (let i = ABSTINENCE_RANKS.length - 1; i >= 0; i--) {
        if (days >= ABSTINENCE_RANKS[i].minDays) {
          currentRank = ABSTINENCE_RANKS[i].rank;
          break;
        }
      }
      const rankBadge = document.getElementById('abstinence-rank-badge');
      if (rankBadge) rankBadge.textContent = currentRank;

      const savedMinsBase = Math.floor(days * 30 + (hours * 1.25));
      const slips = getAbstinenceSlips();
      const viewSlips = getAbstinenceViewSlips(slips);
      renderAbstinenceChallengePanel(days, viewSlips.length);
      renderAbstinenceBestAndResidual(days);
      renderAbstinenceDnsLockPanel(days);
      const penalty = getAbstinenceSlipPenalty(slips);
      const wetPen = getAbstinenceWetPenalty(slips);
      const mult = combineAbstinenceMult(penalty, wetPen);
      const paramSplit = splitAbstinenceParamDays(days, hours);
      const paramDays = paramSplit.paramDays;
      const paramHours = paramSplit.paramHours;
      const equivT = getAbstinenceParamEquivT(days, hours, mult);
      renderAbstinenceParamEquivLine(days, hours, equivT, { ...penalty, decayPct: Math.round((1 - mult) * 100) });

      const urgesAvoidedBase = days * 2 + Math.floor(hours / 12);
      const urgesAvoided = Math.max(0, urgesAvoidedBase - penalty.total * 2 - wetPen.total);
      const savedMins = applyAbstinenceSlipMult(savedMinsBase, mult);
      const savedH = Math.floor(savedMins / 60);
      const savedM = savedMins % 60;
      const savedTimeLabel = savedH > 0 ? `${savedH}時間 ${savedM}分` : `${savedM}分`;
      const savedTimeEl = document.getElementById('abstinence-time-saved');
      if (savedTimeEl) savedTimeEl.textContent = `約 ${savedTimeLabel}`;

      const focusBlocks = applyAbstinenceSlipMult(Math.floor(savedMinsBase / 25), mult);
      const willpower = applyAbstinenceSlipMult(paramDays * 10 + paramHours, mult);
      const sleepScore = Math.min(100, applyAbstinenceSlipMult(Math.min(100, Math.floor(paramDays * 1.2)), mult));
      // 夜更かし回避で守った睡眠（1日あたり約25分の目安）
      const sleepSavedMins = applyAbstinenceSlipMult(Math.floor(days * 25 + (hours * 25) / 24), mult);
      const sleepSavedH = Math.floor(sleepSavedMins / 60);
      const sleepSavedM = sleepSavedMins % 60;
      const sleepSavedLabel = sleepSavedH > 0 ? `${sleepSavedH}時間 ${sleepSavedM}分` : `${sleepSavedM}分`;
      // 生産性アップ（集中の底上げ％・上限55%）
      const productivityPct = Math.min(55, applyAbstinenceSlipMult(Math.min(55, Math.floor(paramDays * 1.4 + paramHours * 0.06)), mult));
      const deepWorkMins = Math.floor(focusBlocks * 25 * 0.8);
      const deepWorkH = Math.floor(deepWorkMins / 60);
      const deepWorkM = deepWorkMins % 60;
      const productivityNote = deepWorkH > 0
        ? `深い作業 約${deepWorkH}時間${deepWorkM > 0 ? deepWorkM + '分' : ''}`
        : `深い作業 約${deepWorkM}分`;
      // 放出回避の精子数 — 夢精後は再充満で戻る目安
      const spermRetained = getAbstinenceSpermRetained(urgesAvoided, slips);

      const gainTimeEl = document.getElementById('abstinence-gain-time');
      const gainUrgesEl = document.getElementById('abstinence-gain-urges');
      const gainFocusEl = document.getElementById('abstinence-gain-focus');
      const gainWillEl = document.getElementById('abstinence-gain-willpower');
      const gainSleepEl = document.getElementById('abstinence-gain-sleep');
      const gainSleepBarEl = document.getElementById('abstinence-gain-sleep-bar');
      const gainSleepTimeEl = document.getElementById('abstinence-gain-sleep-time');
      const gainProdEl = document.getElementById('abstinence-gain-productivity');
      const gainProdNoteEl = document.getElementById('abstinence-gain-productivity-note');
      const gainSpermEl = document.getElementById('abstinence-gain-sperm');
      if (gainTimeEl) gainTimeEl.textContent = savedTimeLabel;
      if (gainUrgesEl) gainUrgesEl.textContent = String(urgesAvoided);
      if (gainFocusEl) gainFocusEl.textContent = String(focusBlocks);
      if (gainWillEl) gainWillEl.textContent = String(willpower);
      if (gainSleepEl) gainSleepEl.textContent = String(sleepScore);
      if (gainSleepBarEl) gainSleepBarEl.style.width = `${sleepScore}%`;
      if (gainSleepTimeEl) gainSleepTimeEl.textContent = sleepSavedLabel;
      if (gainProdEl) gainProdEl.textContent = String(productivityPct);
      if (gainProdNoteEl) gainProdNoteEl.textContent = productivityNote;
      if (gainSpermEl) gainSpermEl.textContent = formatAbstinenceSpermCount(spermRetained);

      const charmBase = getAbstinenceCharmProfile(paramDays, paramHours);
      const charm = {
        ...charmBase,
        score: applyAbstinenceSlipMult(charmBase.score, mult),
        gaze: applyAbstinenceSlipMult(charmBase.gaze, mult),
        skin: applyAbstinenceSlipMult(charmBase.skin, mult),
        aura: applyAbstinenceSlipMult(charmBase.aura, mult),
        presence: applyAbstinenceSlipMult(charmBase.presence, mult),
        delta: applyAbstinenceSlipMult(charmBase.delta, mult)
      };
      if (penalty.total > 0 || wetPen.total > 0) {
        charm.rank = charm.score >= 40 ? charmBase.rank : '減衰中';
        const bits = [];
        if (penalty.decayPct > 0) bits.push(`閲覧 −${penalty.decayPct}%`);
        if (wetPen.decayPct > 0) bits.push(`夢精 −${wetPen.decayPct}%`);
        charm.blurb = bits.length
          ? `${bits.join('・')}（合成表示）。継続日数は残っている。`
          : charmBase.blurb;
      }
      if (paramSplit.liveCarry > 0.5) {
        const carryBit = `リセット残存 相当${Math.round(paramSplit.liveCarry * 10) / 10}日ぶん。`;
        charm.blurb = charm.blurb ? `${charm.blurb} ${carryBit}` : carryBit;
      }
      const charmLost = Math.max(0, charmBase.score - charm.score);
      const charmScoreEl = document.getElementById('abstinence-charm-score');
      const charmRingEl = document.getElementById('abstinence-charm-ring');
      const charmRankEl = document.getElementById('abstinence-charm-rank');
      const charmDeltaEl = document.getElementById('abstinence-charm-delta');
      const charmBlurbEl = document.getElementById('abstinence-charm-blurb');
      if (charmScoreEl) charmScoreEl.textContent = String(charm.score);
      if (charmRingEl) charmRingEl.setAttribute('stroke-dasharray', `${charm.score} 100`);
      if (charmRankEl) charmRankEl.textContent = charm.rank;
      const charmEquivEl = document.getElementById('abstinence-charm-equiv');
      if (charmEquivEl) charmEquivEl.textContent = `相当${formatAbstinenceEquivLabel(equivT)}`;
      if (charmDeltaEl) {
        charmDeltaEl.textContent = charmLost > 0
          ? `基準比 +${charm.delta}%（減衰 −${charmLost}）`
          : `基準比 +${charm.delta}%`;
      }
      if (charmBlurbEl) charmBlurbEl.textContent = charm.blurb;
      const setCharmBar = (key, val) => {
        const vEl = document.getElementById(`abstinence-charm-${key}-val`);
        const bEl = document.getElementById(`abstinence-charm-${key}-bar`);
        if (vEl) vEl.textContent = String(val);
        if (bEl) bEl.style.width = `${val}%`;
      };
      setCharmBar('gaze', charm.gaze);
      setCharmBar('skin', charm.skin);
      setCharmBar('aura', charm.aura);
      setCharmBar('presence', charm.presence);

      renderAbstinenceCapacityViz(paramDays, paramHours, mult, wetPen.mult);
      renderAbstinenceBuffCatalog(days, paramDays, paramHours, mult);

      renderAbstinenceSlipPanel(penalty, slips, charmLost);
      renderAbstinenceWetPanel(wetPen, slips);

      let nextMilestone = ABSTINENCE_MILESTONES.find(m => m > days);
      let prevMilestone = 0;
      if (!nextMilestone) {
        nextMilestone = days + 30;
        prevMilestone = days;
      } else {
        const idx = ABSTINENCE_MILESTONES.indexOf(nextMilestone);
        prevMilestone = idx > 0 ? ABSTINENCE_MILESTONES[idx - 1] : 0;
      }

      const progressPercent = Math.min(100, Math.max(0, Math.floor(((days - prevMilestone) / (nextMilestone - prevMilestone)) * 100)));
      const nextTextEl = document.getElementById('abstinence-next-milestone-text');
      const percentEl = document.getElementById('abstinence-progress-percent');
      const barEl = document.getElementById('abstinence-progress-bar');

      if (nextTextEl) {
        const extra = ABSTINENCE_MILESTONE_LABELS[nextMilestone];
        nextTextEl.textContent = extra ? `次の目標: ${nextMilestone}日目（${extra}）` : `次の目標: ${nextMilestone}日目`;
      }
      if (percentEl) percentEl.textContent = `${progressPercent}%`;
      if (barEl) barEl.style.width = `${progressPercent}%`;

      const stage = ABSTINENCE_STAGES.find(s => days >= s.minDays && days <= s.maxDays) || ABSTINENCE_STAGES[ABSTINENCE_STAGES.length - 1];
      const phaseTitleEl = document.getElementById('abstinence-phase-title');
      const mentalEl = document.getElementById('abstinence-mental-effect');
      const physicalEl = document.getElementById('abstinence-physical-effect');

      if (phaseTitleEl) phaseTitleEl.textContent = stage.title;
      if (mentalEl) mentalEl.textContent = stage.mental;
      if (physicalEl) physicalEl.textContent = stage.physical;

      renderAbstinenceBodyMap(days, penalty, slips, paramDays, equivT, wetPen);
      renderAbstinenceScience(days, penalty);

      const quoteIndex = (days + new Date().getDate()) % ABSTINENCE_QUOTES.length;
      const quoteEl = document.getElementById('abstinence-quote-text');
      if (quoteEl) quoteEl.textContent = ABSTINENCE_QUOTES[quoteIndex];

      const abstHub = document.getElementById('abstinence-hub');
      if (abstHub && !abstHub.classList.contains('hidden') && typeof renderAbstinenceHome === 'function') {
        renderAbstinenceHome();
      }
    }

    function updateAbstinenceStartDateFromInput() {
      const inputEl = document.getElementById('abstinence-start-input');
      if (!inputEl || !inputEl.value) return;
      const newDate = new Date(inputEl.value);
      if (isNaN(newDate.getTime())) return;
      localStorage.setItem('setting_abstinence_start_date', newDate.toISOString());
      renderAbstinenceTimer();
    }

    let abstinenceResetReturnFocus = null;

    function openAbstinenceResetModal() {
      const modal = document.getElementById('abstinence-reset-modal');
      const dialog = document.getElementById('abstinence-reset-dialog');
      const inputEl = document.getElementById('abstinence-reset-at-input');
      const commentEl = document.getElementById('abstinence-reset-comment-input');
      if (!modal || !inputEl) return;
      abstinenceResetReturnFocus = document.activeElement;
      const daysEl = document.getElementById('abstinence-counter-days');
      const days = Number(daysEl && daysEl.textContent) || 0;
      renderAbstinenceScience(days, getAbstinenceSlipPenalty(getAbstinenceSlips()));
      inputEl.value = formatAbstinenceLocalDateTimeValue(new Date());
      inputEl.max = formatAbstinenceLocalDateTimeValue(new Date(Date.now() + 60 * 1000));
      if (commentEl) commentEl.value = '';
      modal.removeAttribute('inert');
      modal.setAttribute('aria-hidden', 'false');
      modal.classList.remove('opacity-0', 'pointer-events-none', 'scale-[0.98]');
      modal.classList.add('opacity-100', 'scale-100');
      requestAnimationFrame(() => {
        if (dialog) dialog.focus();
        inputEl.focus();
      });
      if (modal.dataset.ready !== '1') {
        modal.dataset.ready = '1';
        modal.addEventListener('click', (event) => {
          if (event.target === modal) closeAbstinenceResetModal();
        });
        document.addEventListener('keydown', (event) => {
          if (event.key === 'Escape' && modal.getAttribute('aria-hidden') === 'false') {
            event.preventDefault();
            closeAbstinenceResetModal();
          }
        });
      }
    }

    function closeAbstinenceResetModal(restoreFocus = true) {
      const modal = document.getElementById('abstinence-reset-modal');
      if (!modal || modal.getAttribute('aria-hidden') === 'true') return;
      modal.classList.remove('opacity-100', 'scale-100');
      modal.classList.add('opacity-0', 'pointer-events-none', 'scale-[0.98]');
      modal.setAttribute('aria-hidden', 'true');
      modal.setAttribute('inert', '');
      const returnTo = abstinenceResetReturnFocus;
      abstinenceResetReturnFocus = null;
      if (restoreFocus && returnTo && typeof returnTo.focus === 'function' && document.contains(returnTo)) {
        returnTo.focus();
      }
    }

    function confirmAbstinenceReset() {
      const inputEl = document.getElementById('abstinence-reset-at-input');
      const commentEl = document.getElementById('abstinence-reset-comment-input');
      if (!inputEl || !inputEl.value) {
        alert('再スタート日時を入力してください');
        return;
      }
      const resetDate = new Date(inputEl.value);
      if (isNaN(resetDate.getTime())) {
        alert('再スタート日時を正しく入力してください');
        return;
      }
      if (resetDate.getTime() > Date.now() + 60 * 1000) {
        alert('未来の日時は指定できません');
        return;
      }
      const whenLabel = resetDate.toLocaleString('ja-JP');
      const comment = commentEl ? sanitizeTimerResetComment(commentEl.value) : '';
      const commentLine = comment ? `\nメモ: ${comment}` : '';
      if (!confirm(`禁欲タイマーをリセットしますか？\n再スタート: ${whenLabel}${commentLine}\n日数・閲覧スリップ・夢精履歴と、減衰中・回復中の表示は0に戻します。\nパラメータは前回が長いと約半分残し、短いリセットが続くとほぼ初期です。\n基本性能は射精で一時的に下がり、数日で基準100付近へ戻ります。`)) return;
      closeAbstinenceResetModal(false);
      resetAbstinenceTimer(resetDate, comment);
    }

    async function resetAbstinenceTimer(resetDate, comment) {
      if (!(resetDate instanceof Date) || isNaN(resetDate.getTime())) {
        openAbstinenceResetModal();
        return;
      }
      const startAt = resetDate.toISOString();
      const previousStartAt = localStorage.getItem('setting_abstinence_start_date') || '';
      const slips = getAbstinenceSlips();
      const streakDays = abstinenceStreakDaysBetween(previousStartAt, startAt);
      const viewSlips = getAbstinenceViewSlips(slips);
      const wetSlips = getAbstinenceWetSlips(slips);
      recordAbstinenceResetStat(startAt, previousStartAt, viewSlips.length, comment, viewSlips, wetSlips);
      applyAbstinenceResetResidual(streakDays);
      applyAbstinencePerfReset(streakDays, resetDate);
      localStorage.setItem('setting_abstinence_start_date', startAt);
      markAbstinenceSlipsCleared(startAt);
      saveAbstinenceSlips([]);
      {
        const dnsState = getAbstinenceDnsLockState();
        if (dnsState.osLocked || dnsState.unlockedConfirmed) {
          // リセット後は新しい「最長/平均＋1」が目標。OS側がまだロックなら継続、解除済みなら再ロック待ち
          saveAbstinenceDnsLockState({
            unlockedConfirmed: false,
            osLocked: !!dnsState.osLocked && !dnsState.unlockedConfirmed,
            dismissPromptUntilDays: null,
            lastPromptThreshold: null
          });
        }
      }
      renderAbstinenceTimer();
      setAbstinenceSlipSyncHint('同期中…');
      try {
        await publishAbstinenceTimerReset(startAt);
        const ok = await deleteCloudAbstinenceSlipRecords(slips);
        if (!ok) throw new Error('abstinence_timer_reset_sync_failed');
        clearAbstinenceSlipsClearedMarker();
        setAbstinenceSlipSyncHint('端末間で同期済み');
      } catch (e) {
        setAbstinenceSlipSyncHint('リセット同期に失敗（端末内はリセット済み）');
      }
    }

    function updateLightweightModeStatus(enabled) {
      const status = document.getElementById('lightweight-mode-status');
      if (!status) return;
      status.textContent = enabled ? 'ON · アニメーション停止中' : 'OFF';
      status.className = enabled
        ? 'text-[11px] text-emerald-400 font-bold'
        : 'text-[11px] text-slate-400 font-bold';
    }
    function applyLightweightMode(enabled) {
      document.documentElement.classList.toggle('lightweight-mode', enabled);
      updateLightweightModeStatus(enabled);
      const container = document.getElementById('floating-icons-container');
      if (!container) return;
      container.replaceChildren();
    }

    function normalizeColorTheme(theme) {
      return (theme === 'light' || theme === 'soft' || theme === 'soft-light') ? theme : 'dark';
    }
    function getColorTheme() {
      try {
        return normalizeColorTheme(localStorage.getItem('setting_color_theme'));
      } catch (_) {
        return 'dark';
      }
    }
    function colorThemeLabel(theme) {
      const t = normalizeColorTheme(theme);
      if (t === 'light') return 'ライト';
      if (t === 'soft') return '目にやさしい';
      if (t === 'soft-light') return '目にやさしい（白）';
      return 'ダーク';
    }
    function updateColorThemeUI(theme) {
      const t = normalizeColorTheme(theme);
      const status = document.getElementById('color-theme-status');
      if (status) {
        status.textContent = colorThemeLabel(t);
        status.className = (t === 'light' || t === 'soft-light')
          ? 'text-[11px] text-amber-800 font-bold'
          : (t === 'soft' ? 'text-[11px] text-amber-300 font-bold' : 'text-[11px] text-cyan-300 font-bold');
        if (t === 'light') status.className = 'text-[11px] text-cyan-600 font-bold';
      }
      const darkBtn = document.getElementById('theme-btn-dark');
      const lightBtn = document.getElementById('theme-btn-light');
      const softBtn = document.getElementById('theme-btn-soft');
      const softLightBtn = document.getElementById('theme-btn-soft-light');
      if (darkBtn) {
        darkBtn.classList.toggle('is-active', t === 'dark');
        darkBtn.setAttribute('aria-pressed', t === 'dark' ? 'true' : 'false');
      }
      if (lightBtn) {
        lightBtn.classList.toggle('is-active', t === 'light');
        lightBtn.setAttribute('aria-pressed', t === 'light' ? 'true' : 'false');
      }
      if (softBtn) {
        softBtn.classList.toggle('is-active', t === 'soft');
        softBtn.setAttribute('aria-pressed', t === 'soft' ? 'true' : 'false');
      }
      if (softLightBtn) {
        softLightBtn.classList.toggle('is-active', t === 'soft-light');
        softLightBtn.setAttribute('aria-pressed', t === 'soft-light' ? 'true' : 'false');
      }
    }
    function applyColorTheme(theme) {
      const t = normalizeColorTheme(theme);
      document.documentElement.classList.toggle('theme-light', t === 'light');
      document.documentElement.classList.toggle('theme-dark', t === 'dark');
      document.documentElement.classList.toggle('theme-soft', t === 'soft');
      document.documentElement.classList.toggle('theme-soft-light', t === 'soft-light');
      document.documentElement.dataset.theme = t;
      const meta = document.getElementById('meta-theme-color')
        || document.querySelector('meta[name="theme-color"]');
      if (meta) {
        meta.setAttribute(
          'content',
          t === 'light' ? '#e8eef5'
            : (t === 'soft' ? '#17130f'
              : (t === 'soft-light' ? '#f7f3ec' : '#030509'))
        );
      }
      updateColorThemeUI(t);
      const supModeEl = document.getElementById('supplement-mode');
      const supActive = !!(supModeEl && supModeEl.classList.contains('active'));
      const hasChart = typeof suppleChartInstance !== 'undefined' && !!suppleChartInstance;
      if ((supActive || hasChart) && typeof renderSuppleChart === 'function' && document.getElementById('suppleIntakeChart')) {
        try { renderSuppleChart(); } catch (_) { }
      }
    }
    function setColorTheme(theme) {
      const t = normalizeColorTheme(theme);
      try { localStorage.setItem('setting_color_theme', t); } catch (_) { }
      applyColorTheme(t);
    }

    // ========== 起動時の演出（スプラッシュ演出）設定・プレビュー ==========
