    let treeSelectedNodeId = null;
    let treeSelectedNodeIds = new Set();
    let treeSelectedEdgeId = null;
    function treeClearNodeSelection() {
      treeSelectedNodeId = null;
      treeSelectedNodeIds = new Set();
    }

    function treeSelectOnlyNode(id) {
      const sid = id != null && id !== '' ? String(id) : '';
      treeSelectedNodeId = sid || null;
      treeSelectedNodeIds = sid ? new Set([sid]) : new Set();
    }

    function treeCollectSelectedNodeIds() {
      const ids = new Set(treeSelectedNodeIds || []);
      if (treeSelectedNodeId) ids.add(String(treeSelectedNodeId));
      const live = [];
      ids.forEach((id) => {
        if (treeFindNode(id)) live.push(id);
      });
      return live;
    }

    function treeNodeIsSelected(id) {
      if (id == null || id === '') return false;
      const sid = String(id);
      if (sid === String(treeSelectedNodeId || '')) return true;
      return !!(treeSelectedNodeIds && treeSelectedNodeIds.has(sid));
    }

    /** 選択中ノードから矢印が出る先（to）と、矢印が入る元（from） */
    function treeLinkedNodeSets() {
      const selected = new Set(treeCollectSelectedNodeIds());
      const from = new Set();
      const to = new Set();
      if (!selected.size || !treeState) return { from, to };
      (treeState.edges || []).forEach((e) => {
        if (!e) return;
        const src = String(e.from || '');
        const dst = String(e.to || '');
        if (selected.has(src) && dst && !selected.has(dst)) to.add(dst);
        if (selected.has(dst) && src && !selected.has(src)) from.add(src);
      });
      return { from, to };
    }

    function treeToggleNodeInSelection(id) {
      const sid = String(id);
      const ids = new Set(treeCollectSelectedNodeIds());
      if (ids.has(sid)) ids.delete(sid);
      else ids.add(sid);
      treeSelectedNodeIds = ids;
      treeSelectedNodeId = ids.has(sid) ? sid : (ids.size ? ids.values().next().value : null);
    }

    function treePruneNodeSelection() {
      const live = treeCollectSelectedNodeIds();
      treeSelectedNodeIds = new Set(live);
      if (!live.length) {
        treeSelectedNodeId = null;
        return;
      }
      if (!treeSelectedNodeId || !live.includes(String(treeSelectedNodeId))) {
        treeSelectedNodeId = live[live.length - 1];
      }
    }

