    function treeNormalizeZoom(z) {
      const n = Number(z);
      if (!Number.isFinite(n)) return 1;
      return Math.max(TREE_ZOOM_MIN, Math.min(TREE_ZOOM_MAX, Math.round(n * 1000) / 1000));
    }

    function treeGetZoom() {
      return treeNormalizeZoom(treeState && treeState.zoom);
    }

    function treeDom() {
      if (treeDomCache && treeDomCache.wrap && treeDomCache.wrap.isConnected) return treeDomCache;
      treeDomCache = {
        wrap: document.getElementById('tree-canvas-wrap'),
        sizer: document.getElementById('tree-zoom-sizer'),
        stage: document.getElementById('tree-stage'),
        layer: document.getElementById('tree-nodes-layer'),
        rails: document.getElementById('tree-rails-svg'),
        edges: document.getElementById('tree-edges-svg'),
        lanes: document.getElementById('tree-lanes-layer'),
        rulerTop: document.getElementById('tree-ruler-top'),
        rulerBottom: document.getElementById('tree-ruler-bottom'),
        rulerLeft: document.getElementById('tree-ruler-left'),
        rulerRight: document.getElementById('tree-ruler-right')
      };
      return treeDomCache;
    }

    function treeApplyLiteLayerTransform() {
      const d = treeDom();
      const t = (treeLiteOriginTx || treeLiteOriginTy)
        ? ('translate(' + treeLiteOriginTx + 'px,' + treeLiteOriginTy + 'px)')
        : '';
      if (d.layer) d.layer.style.transform = t;
      if (d.edges) d.edges.style.transform = t;
      const memos = document.getElementById('tree-edge-memos');
      if (memos) memos.style.transform = t;
    }

    function treeBakeLiteOriginShift() {
      if (!treeLiteOriginTx && !treeLiteOriginTy) {
        treeApplyLiteLayerTransform();
        return;
      }
      treeLiteOriginTx = 0;
      treeLiteOriginTy = 0;
      treeApplyLiteLayerTransform();
      const d = treeDom();
      if (!d.layer || !treeState) return;
      const byId = new Map((treeState.nodes || []).map((n) => [n.id, n]));
      d.layer.querySelectorAll('.tree-node').forEach((el) => {
        const n = byId.get(el.dataset.nodeId);
        if (n) treePlaceNodeEl(el, n);
      });
    }

    /** 操作中のキャンバス拡張: 寸法だけ更新（定規・CSS変数の再設定はしない） */
    function treeApplyStageSizeOnly() {
      const d = treeDom();
      if (!d.stage) return;
      const zoom = treeGetZoom();
      const size = treeStageSize();
      d.stage.style.width = size.w + 'px';
      d.stage.style.height = size.h + 'px';
      if (d.sizer) {
        d.sizer.style.width = Math.max(size.w * zoom, d.wrap ? d.wrap.clientWidth : 0) + 'px';
        d.sizer.style.height = Math.max(size.h * zoom, d.wrap ? d.wrap.clientHeight : 0) + 'px';
      }
    }

    function treeApplyZoomTransform(opts) {
      opts = opts || {};
      const d = treeDom();
      const wrap = d.wrap;
      const sizer = d.sizer;
      const stage = d.stage;
      if (!stage) return;
      // 操作中の拡張は寸法更新だけで十分（scale / 定規の再生成はしない）
      if (opts.sizeOnly || (treeUiLite && !opts.forceFull && !opts.keepCenter)) {
        treeApplyStageSizeOnly();
        treeSyncRulerScrollOnly();
        return;
      }
      const zoom = treeGetZoom();
      const size = treeStageSize();
      stage.style.setProperty('--tree-col-w', TREE_COL_W + 'px');
      stage.style.setProperty('--tree-row-h', TREE_ROW_H + 'px');
      stage.style.setProperty('--tree-pad', TREE_PAD + 'px');
      stage.style.transform = 'scale(' + zoom + ')';
      stage.style.width = size.w + 'px';
      stage.style.height = size.h + 'px';
      if (sizer) {
        sizer.style.width = Math.max(size.w * zoom, wrap ? wrap.clientWidth : 0) + 'px';
        sizer.style.height = Math.max(size.h * zoom, wrap ? wrap.clientHeight : 0) + 'px';
      }
      if (opts.keepCenter && wrap) {
        const cx = (opts.prevScrollLeft + (opts.prevViewW || wrap.clientWidth) / 2) / (opts.prevZoom || 1);
        const cy = (opts.prevScrollTop + (opts.prevViewH || wrap.clientHeight) / 2) / (opts.prevZoom || 1);
        wrap.scrollLeft = Math.max(0, cx * zoom - wrap.clientWidth / 2);
        wrap.scrollTop = Math.max(0, cy * zoom - wrap.clientHeight / 2);
      }
      if (opts.skipRulers || treeUiLite) {
        treeSyncRulerScrollOnly();
        return;
      }
      treeLastRulerKey = '';
      treeRenderRulers();
    }

    /** 操作中用: 定規トラックのスクロール位置だけ合わせる（DOM再生成なし） */
    function treeSyncRulerScrollOnly() {
      const d = treeDom();
      if (!d.wrap) return;
      const sl = d.wrap.scrollLeft;
      const st = d.wrap.scrollTop;
      if (d.rulerTop) d.rulerTop.scrollLeft = sl;
      if (d.rulerBottom) d.rulerBottom.scrollLeft = sl;
      if (d.rulerLeft) d.rulerLeft.scrollTop = st;
      if (d.rulerRight) d.rulerRight.scrollTop = st;
    }

    function treeScheduleRulerScrollSync() {
      if (treeRulerScrollRaf) return;
      treeRulerScrollRaf = requestAnimationFrame(() => {
        treeRulerScrollRaf = 0;
        treeSyncRulerScrollOnly();
      });
    }

    function treeEnterUiLite() {
      if (treeUiLite) return;
      treeUiLite = true;
      treeLiteOriginTx = 0;
      treeLiteOriginTy = 0;
      const d = treeDom();
      if (d.wrap) d.wrap.classList.add('is-lite');
      treeApplyLiteLayerTransform();
    }

    function treeExitUiLite() {
      if (!treeUiLite) return;
      // まだ操作中なら終了描画はしない（パンとドラッグの重なり対策）
      if (treeIsInteractBusy()) return;
      treeUiLite = false;
      const d = treeDom();
      if (d.wrap) d.wrap.classList.remove('is-lite');
      treeBakeLiteOriginShift();
      treeLastRulerKey = '';
      treeLastRailsKey = '';
      // 仮想化中はパン後に表示範囲のノードを作り直す
      if (treeState && (treeState.nodes || []).length > TREE_NODE_VIRTUALIZE_AT) {
        renderTree();
      } else {
        treeRenderRailsOnly();
      }
    }

    /** 画面上の指定点（既定は表示中央）を固定したまま拡大率を変更する */
    function treeZoomTo(nextZoom, clientX, clientY) {
      if (!treeState) return;
      const wrap = document.getElementById('tree-canvas-wrap');
      const prevZoom = treeGetZoom();
      const zoom = treeNormalizeZoom(nextZoom);
      if (!wrap) {
        treeState.zoom = zoom;
        treeApplyZoomTransform();
        treeScheduleZoomSave();
        return;
      }
      if (Math.abs(zoom - prevZoom) < 0.0005) return;
      const rect = wrap.getBoundingClientRect();
      const anchorX = (clientX == null ? rect.left + rect.width / 2 : clientX) - rect.left;
      const anchorY = (clientY == null ? rect.top + rect.height / 2 : clientY) - rect.top;
      const stageX = (wrap.scrollLeft + anchorX) / prevZoom;
      const stageY = (wrap.scrollTop + anchorY) / prevZoom;
      treeState.zoom = zoom;
      treeApplyZoomTransform();
      wrap.scrollLeft = Math.max(0, stageX * zoom - anchorX);
      wrap.scrollTop = Math.max(0, stageY * zoom - anchorY);
      treeScheduleGrowNearEdges();
      treeScheduleZoomSave();
      treeShowZoomHint();
    }

    function treeShowZoomHint() {
      setTreeHint('表示 ' + Math.round(treeGetZoom() * 100) + '%');
      if (treeZoomHintTimer) clearTimeout(treeZoomHintTimer);
      treeZoomHintTimer = setTimeout(() => {
        treeZoomHintTimer = null;
        treeResetInteractionHint();
      }, 1200);
    }

    /** ホイール／トラックパッドのスクロールを全体の拡大縮小に割り当てる */
    function treeOnCanvasWheel(e) {
      if (!treeState) return;
      e.preventDefault();
      let delta = e.deltaY;
      if (e.deltaMode === 1) delta *= 16;
      else if (e.deltaMode === 2) delta *= 400;
      if (!delta) return;
      const factor = Math.exp(-Math.max(-160, Math.min(160, delta)) * 0.0018);
      treeZoomTo(treeGetZoom() * factor, e.clientX, e.clientY);
    }

    function treeNormalizeEdgeStyle(style) {
      return style === 'line' ? 'line' : 'arrow';
    }

    function treeNormalizeDashStyle(style) {
      return (style === 'dashed' || style === 'dash' || style === true) ? 'dashed' : 'solid';
    }

    function treeCloneState(state) {
      return JSON.parse(JSON.stringify(state || emptyTreeState()));
    }

    function treeNormalizeLaneBag(rawBag) {
      const out = {};
      if (!rawBag || typeof rawBag !== 'object') return out;
      Object.keys(rawBag).forEach((k) => {
        const i = Number(k);
        if (!Number.isFinite(i) || Math.abs(i) >= TREE_HARD_MAX) return;
        const name = String((rawBag[k] && rawBag[k].name) || '').trim().slice(0, 24);
        if (!name) return;
        out[String(Math.floor(i))] = { name };
      });
      return out;
    }

    function normalizeTreeStateObject(raw) {
      if (!raw || typeof raw !== 'object') return emptyTreeState();
      const originCol = Number.isFinite(Number(raw.originCol)) ? Math.floor(Number(raw.originCol)) : 0;
      const originRow = Number.isFinite(Number(raw.originRow)) ? Math.floor(Number(raw.originRow)) : 0;
      const nodes = Array.isArray(raw.nodes) ? raw.nodes.map((n, i) => ({
        id: String(n.id || ('n' + i)),
        label: String(n.label || 'ノード').slice(0, 40),
        // ワールド座標（スクロール／キャンバス拡張で変わらない固有番号）
        col: Math.max(-TREE_HARD_MAX, Math.min(TREE_HARD_MAX - 1, Math.floor(Number(n.col) || 0))),
        row: Math.max(-TREE_HARD_MAX, Math.min(TREE_HARD_MAX - 1, Math.floor(Number(n.row) || 0))),
        accent: !!n.accent
      })) : [];
      let maxLayoutCol = TREE_DEFAULT_COLS - 1;
      let maxLayoutRow = TREE_DEFAULT_ROWS - 1;
      nodes.forEach((n) => {
        maxLayoutCol = Math.max(maxLayoutCol, (n.col - originCol) + TREE_EDGE_BUFFER);
        maxLayoutRow = Math.max(maxLayoutRow, (n.row - originRow) + TREE_EDGE_BUFFER);
      });
      const cols = Math.max(TREE_DEFAULT_COLS, Math.min(TREE_HARD_MAX, Math.max(Number(raw.cols) || 0, maxLayoutCol + 1)));
      const rows = Math.max(TREE_DEFAULT_ROWS, Math.min(TREE_HARD_MAX, Math.max(Number(raw.rows) || 0, maxLayoutRow + 1)));
      const nodeById = new Map(nodes.map((n) => [n.id, n]));
      const edges = Array.isArray(raw.edges) ? raw.edges.map((e, i) => {
        const from = String(e.from || '');
        const to = String(e.to || '');
        if (!from || !to || from === to) return null;
        const fromNode = nodeById.get(from);
        const toNode = nodeById.get(to);
        if (!fromNode || !toNode) return null;
        let fromSide = treeNormalizeSide(e.fromSide || e.fromPort);
        let toSide = treeNormalizeSide(e.toSide || e.toPort);
        if (!fromSide || !toSide) {
          const inferred = treeInferSides(fromNode, toNode);
          fromSide = fromSide || inferred.fromSide;
          toSide = toSide || inferred.toSide;
        }
        const edge = {
          id: String(e.id || ('e' + i)),
          from,
          to,
          fromSide,
          toSide,
          style: treeNormalizeEdgeStyle(e.style || e.kind || e.linkStyle),
          dashStyle: treeNormalizeDashStyle(e.dashStyle || e.dashed || e.stroke)
        };
        const memo = String(e.memo || '').replace(/\r\n/g, '\n').trim().slice(0, 4000);
        if (memo) edge.memo = memo;
        return edge;
      }).filter(Boolean) : [];
      const laneCols = treeNormalizeLaneBag(raw.laneLabels && raw.laneLabels.cols);
      const laneRows = treeNormalizeLaneBag(raw.laneLabels && raw.laneLabels.rows);
      const state = {
        cols,
        rows,
        originCol,
        originRow,
        linkStyle: treeNormalizeEdgeStyle(raw.linkStyle),
        dashStyle: treeNormalizeDashStyle(raw.dashStyle || raw.dashed),
        zoom: treeNormalizeZoom(raw.zoom),
        nodes: nodes.length ? nodes : emptyTreeState().nodes,
        edges
      };
      if (Object.keys(laneCols).length || Object.keys(laneRows).length) {
        state.laneLabels = { cols: laneCols, rows: laneRows };
      }
      return state;
    }

    function treeNewPaletteId() {
      return 'p' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5);
    }

    function loadTreeLibrary() {
      try {
        const raw = JSON.parse(localStorage.getItem(TREE_LIBRARY_KEY) || 'null');
        if (raw && Array.isArray(raw.palettes) && raw.palettes.length) {
          const palettes = raw.palettes.map((p, i) => ({
            id: String(p.id || ('p' + i)),
            name: String(p.name || ('パレット ' + (i + 1))).slice(0, 40),
            updatedAt: p.updatedAt || '',
            state: normalizeTreeStateObject(p.state)
          }));
          let activeId = String(raw.activeId || palettes[0].id);
          if (!palettes.some((p) => p.id === activeId)) activeId = palettes[0].id;
          return { activeId, palettes };
        }
      } catch (e) { }
      let legacy = null;
      try {
        legacy = JSON.parse(localStorage.getItem(TREE_STORAGE_KEY) || 'null');
      } catch (e) { }
      const id = treeNewPaletteId();
      return {
        activeId: id,
        palettes: [{
          id,
          name: 'パレット 1',
          updatedAt: '',
          state: normalizeTreeStateObject(legacy)
        }]
      };
    }

    function saveTreeLibrary(opts) {
      if (!treeLibrary) return;
      opts = opts || {};
      try {
        localStorage.setItem(TREE_LIBRARY_KEY, JSON.stringify(treeLibrary));
        // 互換: 旧キーにもアクティブ状態を残す
        if (treeState) localStorage.setItem(TREE_STORAGE_KEY, JSON.stringify(treeState));
        if (opts.touch !== false) {
          localStorage.setItem(TREE_LIBRARY_UPDATED_AT_KEY, new Date().toISOString());
          treeLibraryDirty = true;
          try { localStorage.setItem(TREE_LIBRARY_DIRTY_KEY, '1'); } catch (e) { }
          if (opts.queueCloud !== false) queueTreeLibraryCloudSync();
        }
      } catch (e) { }
    }

    function treeActivePalette() {
      if (!treeLibrary) return null;
      return treeLibrary.palettes.find((p) => p.id === treeLibrary.activeId) || treeLibrary.palettes[0] || null;
    }

    function treeFlushActiveToLibrary() {
      if (!treeLibrary || !treeState) return;
      const pal = treeActivePalette();
      if (!pal) return;
      const next = treeCloneState(treeState);
      const changed = !treeSnapshotEquals(pal.state, next);
      pal.state = next;
      if (changed) pal.updatedAt = new Date().toISOString();
    }

    function normalizeTreeLibraryObject(raw) {
      if (!raw || typeof raw !== 'object') return null;
      if (!Array.isArray(raw.palettes) || !raw.palettes.length) return null;
      const palettes = raw.palettes.map((p, i) => ({
        id: String(p.id || ('p' + i)),
        name: String(p.name || ('パレット' + (i + 1))).slice(0, 40),
        updatedAt: p.updatedAt || '',
        state: normalizeTreeStateObject(p.state)
      }));
      let activeId = String(raw.activeId || palettes[0].id);
      if (!palettes.some((p) => p.id === activeId)) activeId = palettes[0].id;
      return { activeId, palettes };
    }

    async function ensureTreeLibraryStore() {
      if (treeLibraryStoreReady) return;
      await callAPI('addConfigRecord', {
        folder: TREE_LIBRARY_FOLDER,
        file: TREE_LIBRARY_FILE
      }, { silent: true });
      treeLibraryStoreReady = true;
    }

    function parseTreeLibrarySnapshot(row) {
      if (!row || row.content == null) return null;
      try {
        const payload = JSON.parse(row.content);
        const library = normalizeTreeLibraryObject(payload && payload.library ? payload.library : payload);
        const updatedAt = new Date(payload && payload.updatedAt).getTime();
        if (!library || !Number.isFinite(updatedAt)) return null;
        return {
          cloudId: row.id ? String(row.id) : '',
          library,
          updatedAt,
          updatedAtIso: new Date(updatedAt).toISOString()
        };
      } catch (e) {
        return null;
      }
    }

    async function fetchCloudTreeLibrarySnapshot() {
      const items = await callAPI('getFolderFileItems', {
        folder: TREE_LIBRARY_FOLDER,
        file: TREE_LIBRARY_FILE
      }, { silent: true });
      if (!Array.isArray(items) || !items.length) return null;
      const parsed = items.map(parseTreeLibrarySnapshot).filter(Boolean)
        .sort((a, b) => b.updatedAt - a.updatedAt);
      if (!parsed.length) return null;
      parsed[0].extraIds = parsed.slice(1).map((p) => p.cloudId).filter(Boolean);
      return parsed[0];
    }

    function treeLibrarySignature(lib) {
      if (!lib) return '';
      try {
        return JSON.stringify({
          activeId: lib.activeId,
          palettes: (lib.palettes || []).map((p) => ({
            id: p.id,
            name: p.name,
            state: p.state
          }))
        });
      } catch (e) {
        return '';
      }
    }

    function treeClearLibraryDirty() {
      treeLibraryDirty = false;
      try { localStorage.removeItem(TREE_LIBRARY_DIRTY_KEY); } catch (e) { }
    }

    function treeLibraryLocalUpdatedAtMs() {
      const fromKey = new Date(localStorage.getItem(TREE_LIBRARY_UPDATED_AT_KEY) || 0).getTime();
      let maxPal = 0;
      const lib = treeLibrary || null;
      if (lib && Array.isArray(lib.palettes)) {
        for (let i = 0; i < lib.palettes.length; i++) {
          const t = new Date((lib.palettes[i] && lib.palettes[i].updatedAt) || 0).getTime();
          if (Number.isFinite(t) && t > maxPal) maxPal = t;
        }
      }
      return Math.max(Number.isFinite(fromKey) ? fromKey : 0, maxPal);
    }

    let treeDeferredRenderTimer = null;

    function treeRenderIfTreeTabActive() {
      const tab = document.getElementById('tree-mode');
      if (!tab || !tab.classList.contains('active')) return;
      // ドラッグ中に作り直すと、掴んでいるノード／接続点が消えて操作が途切れる
      if (treeIsInteractBusy()) {
        if (!treeDeferredRenderTimer) {
          treeDeferredRenderTimer = setTimeout(() => {
            treeDeferredRenderTimer = null;
            treeRenderIfTreeTabActive();
          }, 300);
        }
        return;
      }
      treeRenderPaletteSelect();
      renderTree();
      treeUpdateLinkStyleButton();
      treeUpdateHistoryButtons();
    }

    async function publishTreeLibrary(prefetched) {
      if (!treeLibrary) treeLibrary = loadTreeLibrary();
      if (treeState) treeFlushActiveToLibrary();
      await ensureTreeLibraryStore();
      let localUpdatedAt = treeLibraryLocalUpdatedAtMs();
      if (!localUpdatedAt) {
        const nowIso = new Date().toISOString();
        localStorage.setItem(TREE_LIBRARY_UPDATED_AT_KEY, nowIso);
        localUpdatedAt = new Date(nowIso).getTime();
      }
      const existing = prefetched === undefined ? await fetchCloudTreeLibrarySnapshot() : prefetched;
      // fetch 後にもう一度ローカルを確定（待ち時間中の編集を落とさない）
      if (treeState) treeFlushActiveToLibrary();
      localUpdatedAt = Math.max(localUpdatedAt, treeLibraryLocalUpdatedAtMs());
      // 競合: クラウドの方が新しく、かつローカル保護が無いときだけ取り込む
      if (existing && existing.updatedAt > localUpdatedAt && !treeShouldProtectLocalEdits()) {
        if (applyTreeLibraryFromCloud(existing.library, existing.updatedAtIso)) {
          treeRenderIfTreeTabActive();
        }
        return;
      }
      if (existing && existing.updatedAt > localUpdatedAt && treeShouldProtectLocalEdits()) {
        // ローカル編集を守る。あとで取り込み
        treeSyncPendingPull = true;
      }
      const updatedAt = new Date(Math.max(localUpdatedAt, Date.now())).toISOString();
      localStorage.setItem(TREE_LIBRARY_UPDATED_AT_KEY, updatedAt);
      const payload = JSON.stringify({
        v: 1,
        updatedAt,
        library: {
          activeId: treeLibrary.activeId,
          palettes: treeLibrary.palettes
        }
      });
      try {
        await upsertSystemSnapshotRecord({
          cloudId: existing && existing.cloudId,
          extraIds: existing && existing.extraIds,
          folder: TREE_LIBRARY_FOLDER,
          file: TREE_LIBRARY_FILE,
          content: payload
        });
      } catch (_) {
        throw new Error('tree_library_sync');
      }
      treeClearLibraryDirty();
    }

    function queueTreeLibraryCloudSync() {
      if (treeCloudPublishTimer) clearTimeout(treeCloudPublishTimer);
      treeCloudPublishTimer = setTimeout(() => {
        publishTreeLibrary().catch(() => { });
      }, 200);
    }

    function treeNoteLocalEdit() {
      treeLocalEditGen += 1;
      treeLastLocalEditAt = Date.now();
      treeLibraryDirty = true;
      try { localStorage.setItem(TREE_LIBRARY_DIRTY_KEY, '1'); } catch (e) { }
    }

    function treeIsBusyEditing() {
      return !!(treeDrag || treePortLink || treeEdgeRebind || treeEdgeRebindPending
        || treeInlineEdit || treePan || treePinch || treeUiLite || treeSaveSuppressed);
    }

    function treeShouldProtectLocalEdits() {
      if (treeLibraryDirty || treeIsBusyEditing()) return true;
      if (treeLocalEditGen > 0 && (Date.now() - treeLastLocalEditAt) < TREE_EDIT_GRACE_MS) return true;
      if (treeSaveTimer) return true;
      return false;
    }

    function applyTreeLibraryFromCloud(library, updatedAtIso) {
      // ローカル編集の保護（同期の二重チェック）
      if (treeShouldProtectLocalEdits()) {
        treeSyncPendingPull = true;
        return false;
      }
      const next = normalizeTreeLibraryObject(library);
      if (!next) return false;
      treeLibrary = next;
      const pal = treeActivePalette();
      treeState = treeCloneState(pal && pal.state ? pal.state : emptyTreeState());
      treeClearNodeSelection();
      treeSelectedEdgeId = null;
      treePortTap = null;
      treeEdgeRebind = null;
      treeEdgeRebindPending = null;
      treeResetHistory();
      treeSyncPendingPull = false;
      try {
        localStorage.setItem(TREE_LIBRARY_KEY, JSON.stringify(treeLibrary));
        if (treeState) localStorage.setItem(TREE_STORAGE_KEY, JSON.stringify(treeState));
        if (updatedAtIso) localStorage.setItem(TREE_LIBRARY_UPDATED_AT_KEY, updatedAtIso);
      } catch (_) { }
      treeClearLibraryDirty();
      return true;
    }

    async function syncTreeLibrary(options) {
      options = options || {};
      const wantRender = options.render !== false;

      // 進行中の同期を待ってから描画（裏同期が render:false でもツリー表示を取りこぼさない）
      if (treeLibrarySyncPromise) {
        try { await treeLibrarySyncPromise; } catch (_) { }
        if (wantRender) treeRenderIfTreeTabActive();
        return treeLibrary;
      }

      treeLibrarySyncing = true;
      treeLibrarySyncPromise = (async () => {
        if (!treeLibrary) treeLibrary = loadTreeLibrary();
        if (treeState) treeFlushActiveToLibrary();
        const startGen = treeLocalEditGen;

        // 取得を先に行う（毎回の addConfigRecord 待ちを避ける）
        let cloud = null;
        try {
          cloud = await fetchCloudTreeLibrarySnapshot();
        } catch (_) {
          cloud = null;
        }

        // fetch 待ちのあいだに編集が入っていたら必ずローカル優先
        if (treeState) treeFlushActiveToLibrary();
        const editedDuringFetch = treeLocalEditGen !== startGen;
        const protect = treeShouldProtectLocalEdits() || editedDuringFetch;

        if (protect) {
          if (treeLibraryDirty || editedDuringFetch) {
            try { await publishTreeLibrary(cloud); } catch (_) { }
          } else if (cloud) {
            treeSyncPendingPull = true;
          }
          return treeLibrary;
        }

        const localUpdatedAt = treeLibraryLocalUpdatedAtMs();
        const cloudNewer = !!(cloud && (!Number.isFinite(localUpdatedAt) || cloud.updatedAt > localUpdatedAt));
        const contentDiffers = !!(cloud && treeLibrarySignature(treeLibrary) !== treeLibrarySignature(cloud.library));

        if (treeLibraryDirty) {
          await publishTreeLibrary(cloud);
        } else if (cloud && cloudNewer) {
          // クラウドの方が新しいときだけ取り込む（contentDiffers だけでは上書きしない）
          if (applyTreeLibraryFromCloud(cloud.library, cloud.updatedAtIso)) {
            treeRenderIfTreeTabActive();
          }
        } else if (cloud && contentDiffers && Number.isFinite(localUpdatedAt) && localUpdatedAt >= cloud.updatedAt) {
          // 内容が違うがローカルが同じか新しい → 上げる
          await publishTreeLibrary(cloud);
        } else if (!cloud) {
          ensureTreeLibraryStore().catch(() => { });
        }
        return treeLibrary;
      })();

      try {
        await treeLibrarySyncPromise;
        if (wantRender) treeRenderIfTreeTabActive();
        return treeLibrary;
      } catch (e) {
        return treeLibrary;
      } finally {
        treeLibrarySyncPromise = null;
        treeLibrarySyncing = false;
      }
    }

    let treePollChecking = false;
    function startTreeLibraryPoll() {
      if (treeLibraryPollTimer) return;
      treeLibraryPollTimer = setInterval(async () => {
        if (document.visibilityState !== 'visible') return;
        if (treePollChecking) return;
        const onTree = !!(document.getElementById('tree-mode')
          && document.getElementById('tree-mode').classList.contains('active'));
        if (!onTree && !treeLibraryDirty) return;
        // 編集中／未送信は取り込みせず、送信だけ試みる
        if (treeShouldProtectLocalEdits() || !onTree) {
          if (treeLibraryDirty) queueTreeLibraryCloudSync();
          return;
        }
        treePollChecking = true;
        try {
          const changed = await checkPollStampChanged('tree');
          if (changed) {
            await syncTreeLibrary({ render: true }).catch(() => { });
          }
        } finally {
          treePollChecking = false;
        }
      }, TREE_SYNC_POLL_MS);
    }

    function stopTreeLibraryPoll() {
      if (!treeLibraryPollTimer) return;
      clearInterval(treeLibraryPollTimer);
      treeLibraryPollTimer = null;
    }

    /** 編集が終わったら、保留中のクラウド取り込みを拾う */
    function treeMaybeSyncAfterIdle() {
      if (!treeSyncPendingPull || treeShouldProtectLocalEdits()) return;
      const onTree = !!(document.getElementById('tree-mode')
        && document.getElementById('tree-mode').classList.contains('active'));
      syncTreeLibrary({ render: onTree }).catch(() => { });
    }

    function treeRenderPaletteSelect() {
      const sel = document.getElementById('tree-palette-select');
      if (!sel || !treeLibrary) return;
      const active = treeLibrary.activeId;
      sel.innerHTML = treeLibrary.palettes.map((p) =>
        `<option value="${p.id}"${p.id === active ? ' selected' : ''}>${escapeHtmlText(p.name)}</option>`
      ).join('');
    }

    function treeSwitchPalette(id) {
      if (!treeLibrary || !id || id === treeLibrary.activeId) return;
      treeFlushActiveToLibrary();
      const next = treeLibrary.palettes.find((p) => p.id === id);
      if (!next) return;
      treeLibrary.activeId = id;
      treeState = treeCloneState(next.state);
      treeResetHistory();
      treeClearNodeSelection();
      treeSelectedEdgeId = null;
      treePortTap = null;
      treeClearLinkPreview();
      saveTreeLibrary();
      treeRenderPaletteSelect();
      renderTree();
      treeOpenAtOrigin();
      setTreeHint('「' + next.name + '」を開きました');
    }

    function treeAddPalette() {
      if (!treeLibrary) return;
      treeFlushActiveToLibrary();
      const n = treeLibrary.palettes.length + 1;
      const name = window.prompt('新しいパレット名', 'パレット ' + n);
      if (name == null) return;
      const trimmed = String(name).trim().slice(0, 40) || ('パレット ' + n);
      const id = treeNewPaletteId();
      treeLibrary.palettes.push({
        id,
        name: trimmed,
        updatedAt: new Date().toISOString(),
        state: emptyTreeState()
      });
      treeLibrary.activeId = id;
      treeState = emptyTreeState();
      treeResetHistory();
      treeSelectOnlyNode(treeState.nodes[0] ? treeState.nodes[0].id : null);
      treeSelectedEdgeId = null;
      saveTreeLibrary();
      treeRenderPaletteSelect();
      renderTree();
      treeOpenAtOrigin();
      setTreeHint('「' + trimmed + '」を作成しました');
    }

    function treeRenamePalette() {
      if (!treeLibrary) return;
      const pal = treeActivePalette();
      if (!pal) return;
      const name = window.prompt('パレット名', pal.name);
      if (name == null) return;
      const trimmed = String(name).trim().slice(0, 40);
      if (!trimmed) return;
      pal.name = trimmed;
      pal.updatedAt = new Date().toISOString();
      saveTreeLibrary();
      treeRenderPaletteSelect();
      setTreeHint('名前を「' + trimmed + '」に変更');
    }

    function treeDeletePalette() {
      if (!treeLibrary) return;
      if (treeLibrary.palettes.length <= 1) {
        setTreeHint('最後の1つは削除できません');
        return;
      }
      const pal = treeActivePalette();
      if (!pal) return;
      if (!confirm('パレット「' + pal.name + '」を削除しますか？\n（中のノードも消えます）')) return;
      treeLibrary.palettes = treeLibrary.palettes.filter((p) => p.id !== pal.id);
      treeLibrary.activeId = treeLibrary.palettes[0].id;
      treeState = treeCloneState(treeLibrary.palettes[0].state);
      treeResetHistory();
      treeClearNodeSelection();
      treeSelectedEdgeId = null;
      saveTreeLibrary();
      treeRenderPaletteSelect();
      renderTree();
      treeOpenAtOrigin();
      setTreeHint('パレットを削除しました');
    }

    function treeGetDrawStyle() {
      return treeNormalizeEdgeStyle(treeState && treeState.linkStyle);
    }

    function treeGetDrawDashStyle() {
      return treeNormalizeDashStyle(treeState && treeState.dashStyle);
    }

    function treeUpdateDashStyleButton() {
      const btn = document.getElementById('tree-dash-style-btn');
      if (!btn) return;
      let dash = treeGetDrawDashStyle();
      if (treeSelectedEdgeId && treeState) {
        const edge = treeState.edges.find((e) => e.id === treeSelectedEdgeId);
        if (edge) dash = treeNormalizeDashStyle(edge.dashStyle || edge.dashed);
      }
      const isDashed = dash === 'dashed';
      btn.textContent = isDashed ? '╌' : '━';
      btn.title = treeSelectedEdgeId
        ? (isDashed ? '選択中: 点線 → タップで実線に変更' : '選択中: 実線 → タップで点線に変更')
        : (isDashed ? '次の接続: 点線（タップで実線に）' : '次の接続: 実線（タップで点線に）');
      btn.setAttribute('aria-label', btn.title);
      btn.classList.toggle('is-active', isDashed);
    }

    function treeUpdateLinkStyleButton() {
      const btn = document.getElementById('tree-link-style-btn');
      if (btn) {
        let style = treeGetDrawStyle();
        if (treeSelectedEdgeId && treeState) {
          const edge = treeState.edges.find((e) => e.id === treeSelectedEdgeId);
          if (edge) style = treeNormalizeEdgeStyle(edge.style);
        }
        const isLine = style === 'line';
        btn.textContent = isLine ? '—' : '→';
        btn.title = treeSelectedEdgeId
          ? (isLine ? '選択中: 線 → タップで矢印に変更' : '選択中: 矢印 → タップで線に変更')
          : (isLine ? '次の接続: 線（タップで矢印に）' : '次の接続: 矢印（タップで線に）');
        btn.setAttribute('aria-label', btn.title);
        btn.classList.toggle('is-active', isLine);
      }
      treeUpdateDashStyleButton();
    }

    function treeToggleDashStyle() {
      if (!treeState) return;
      if (treeSelectedEdgeId) {
        const edge = treeState.edges.find((e) => e.id === treeSelectedEdgeId);
        if (edge) {
          treePushUndoSnapshot();
          const cur = treeNormalizeDashStyle(edge.dashStyle || edge.dashed);
          const next = cur === 'dashed' ? 'solid' : 'dashed';
          edge.dashStyle = next;
          delete edge.dashed;
          treeState.dashStyle = next;
          scheduleTreeSave();
          renderTree();
          treeUpdateDashStyleButton();
          setTreeHint(next === 'dashed' ? '点線に変更しました' : '実線に変更しました');
          return;
        }
      }
      treePushUndoSnapshot();
      const cur = treeGetDrawDashStyle();
      const next = cur === 'dashed' ? 'solid' : 'dashed';
      treeState.dashStyle = next;
      scheduleTreeSave();
      treeUpdateDashStyleButton();
      setTreeHint(next === 'dashed'
        ? '次の接続は「点線」で追加します'
        : '次の接続は「実線」で追加します');
    }

    function treeToggleLinkStyle() {
      if (!treeState) return;
      if (treeSelectedEdgeId) {
        const edge = treeState.edges.find((e) => e.id === treeSelectedEdgeId);
        if (edge) {
          treePushUndoSnapshot();
          edge.style = treeNormalizeEdgeStyle(edge.style) === 'line' ? 'arrow' : 'line';
          treeState.linkStyle = edge.style;
          scheduleTreeSave();
          renderTree();
          treeUpdateLinkStyleButton();
          setTreeHint(edge.style === 'line' ? '線に変更しました' : '矢印に変更しました');
          return;
        }
      }
      treePushUndoSnapshot();
      treeState.linkStyle = treeGetDrawStyle() === 'line' ? 'arrow' : 'line';
      scheduleTreeSave();
      treeUpdateLinkStyleButton();
      const prev = document.getElementById('tree-link-preview');
      if (prev) prev.classList.toggle('is-line', treeState.linkStyle === 'line');
      setTreeHint(treeState.linkStyle === 'line'
        ? '次の接続は「線」で追加します'
        : '次の接続は「矢印」で追加します');
    }

    function treeNormalizeSide(side) {
      const s = String(side || '').toLowerCase();
      if (s === 't' || s === 'top' || s === 'u' || s === 'up' || s === 'n') return 't';
      if (s === 'b' || s === 'bottom' || s === 'd' || s === 'down' || s === 's') return 'b';
      if (s === 'l' || s === 'left' || s === 'w') return 'l';
      if (s === 'r' || s === 'right' || s === 'e') return 'r';
      return '';
    }

    function treeInferSides(fromNode, toNode) {
      const a = treeNodeCenter(fromNode);
      const b = treeNodeCenter(toNode);
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      if (Math.abs(dx) >= Math.abs(dy)) {
        return { fromSide: dx >= 0 ? 'r' : 'l', toSide: dx >= 0 ? 'l' : 'r' };
      }
      return { fromSide: dy >= 0 ? 'b' : 't', toSide: dy >= 0 ? 't' : 'b' };
    }

    function loadTreeState() {
      treeLibrary = loadTreeLibrary();
      const pal = treeActivePalette();
      return treeCloneState(pal && pal.state ? pal.state : emptyTreeState());
    }

    function saveTreeState() {
      if (!treeState) return;
      if (!treeLibrary) treeLibrary = loadTreeLibrary();
      treeNoteLocalEdit();
      treeFlushActiveToLibrary();
      saveTreeLibrary();
    }

    function treeSnapshotEquals(a, b) {
      try {
        return JSON.stringify(a || null) === JSON.stringify(b || null);
      } catch (_) {
        return false;
      }
    }

    function treeUpdateHistoryButtons() {
      const undoBtn = document.getElementById('tree-undo-btn');
      const redoBtn = document.getElementById('tree-redo-btn');
      if (undoBtn) undoBtn.disabled = !treeUndoStack.length;
      if (redoBtn) redoBtn.disabled = !treeRedoStack.length;
    }

    function treeResetHistory() {
      treeUndoStack = [];
      treeRedoStack = [];
      treeUpdateHistoryButtons();
    }

    function treePushUndoSnapshot(snapshot) {
      if (!treeState) return;
      const snap = treeCloneState(snapshot || treeState);
      const last = treeUndoStack.length ? treeUndoStack[treeUndoStack.length - 1] : null;
      if (treeSnapshotEquals(last, snap)) return;
      treeUndoStack.push(snap);
      if (treeUndoStack.length > TREE_HISTORY_LIMIT) treeUndoStack.shift();
      treeRedoStack = [];
      treeUpdateHistoryButtons();
    }

    function treeNormalizeSelectionAfterHistoryRestore() {
      treePruneNodeSelection();
      if (treeSelectedEdgeId && !treeState.edges.some((e) => e.id === treeSelectedEdgeId)) treeSelectedEdgeId = null;
      treePortTap = null;
      treePortLink = null;
      treeEdgeRebind = null;
      treeEdgeRebindPending = null;
      treeClearLinkPreview();
    }

    function treeUndo() {
      if (!treeState || !treeUndoStack.length) return;
      closeTreeInlineEdit(false);
      if (treeSaveTimer) {
        clearTimeout(treeSaveTimer);
        treeSaveTimer = null;
      }
      const prev = treeUndoStack.pop();
      treeRedoStack.push(treeCloneState(treeState));
      if (treeRedoStack.length > TREE_HISTORY_LIMIT) treeRedoStack.shift();
      treeState = treeCloneState(prev);
      treeNormalizeSelectionAfterHistoryRestore();
      saveTreeState();
      renderTree();
      treeUpdateHistoryButtons();
      setTreeHint('1つ前に戻しました');
    }

    function treeRedo() {
      if (!treeState || !treeRedoStack.length) return;
      closeTreeInlineEdit(false);
      if (treeSaveTimer) {
        clearTimeout(treeSaveTimer);
        treeSaveTimer = null;
      }
      const next = treeRedoStack.pop();
      treeUndoStack.push(treeCloneState(treeState));
      if (treeUndoStack.length > TREE_HISTORY_LIMIT) treeUndoStack.shift();
      treeState = treeCloneState(next);
      treeNormalizeSelectionAfterHistoryRestore();
      saveTreeState();
      renderTree();
      treeUpdateHistoryButtons();
      setTreeHint('やり直しました');
    }

    function treeIsInteractBusy() {
      return !!(treePan || treeDrag || treePinch || treePortLink || treeEdgeRebind);
    }

    function scheduleTreeSave() {
      // 同期レース対策: 保存前でも即座に dirty / 世代を上げる
      treeNoteLocalEdit();
      if (treeSaveSuppressed || treeIsInteractBusy()) {
        treeSaveSuppressed = true;
        return;
      }
      if (treeSaveTimer) clearTimeout(treeSaveTimer);
      treeSaveTimer = setTimeout(saveTreeState, 200);
    }

    function treeFlushDeferredSave() {
      treeSaveSuppressed = false;
      if (treeSaveTimer) clearTimeout(treeSaveTimer);
      treeSaveTimer = setTimeout(() => {
        saveTreeState();
        treeMaybeSyncAfterIdle();
      }, 120);
    }

    function treeScheduleZoomSave() {
      if (treeZoomSaveTimer) clearTimeout(treeZoomSaveTimer);
      treeZoomSaveTimer = setTimeout(() => {
        treeZoomSaveTimer = null;
        treeSaveSuppressed = false;
        scheduleTreeSave();
      }, 700);
    }

    function treeOriginCol() {
      return (treeState && Number.isFinite(Number(treeState.originCol)))
        ? Math.floor(Number(treeState.originCol))
        : 0;
    }

    function treeOriginRow() {
      return (treeState && Number.isFinite(Number(treeState.originRow)))
        ? Math.floor(Number(treeState.originRow))
        : 0;
    }

    /** レイアウト列（キャンバス上 0..cols-1）→ 固有ワールド列 */
    function treeLayoutToWorldCol(layoutCol) {
      return Math.floor(Number(layoutCol) || 0) + treeOriginCol();
    }

    function treeLayoutToWorldRow(layoutRow) {
      return Math.floor(Number(layoutRow) || 0) + treeOriginRow();
    }

    /** 固有ワールド列 → レイアウト列 */
    function treeWorldToLayoutCol(worldCol) {
      return Math.floor(Number(worldCol) || 0) - treeOriginCol();
    }

    function treeWorldToLayoutRow(worldRow) {
      return Math.floor(Number(worldRow) || 0) - treeOriginRow();
    }

    /** 表示用の固有番号（1始まり。スクロールしても変わらない） */
    function treeWorldLabelCol(worldCol) {
      return Math.floor(Number(worldCol) || 0) + 1;
    }

    function treeWorldLabelRow(worldRow) {
      return Math.floor(Number(worldRow) || 0) + 1;
    }

    function treeCellCenter(layoutCol, layoutRow) {
      return {
        x: TREE_PAD + layoutCol * TREE_COL_W + TREE_COL_W / 2,
        y: TREE_PAD + layoutRow * TREE_ROW_H + TREE_ROW_H / 2
      };
    }

    function treeNodeCenter(node) {
      if (!node) return { x: TREE_PAD + TREE_COL_W / 2, y: TREE_PAD + TREE_ROW_H / 2 };
      return treeCellCenter(treeWorldToLayoutCol(node.col), treeWorldToLayoutRow(node.row));
    }

    function treeNodeAtWorld(worldCol, worldRow) {
      return (treeState.nodes || []).some((n) => n && n.col === worldCol && n.row === worldRow);
    }

    function treePlaceNodeEl(el, n) {
      if (!el || !n) return;
      const center = treeNodeCenter(n);
      el.style.left = (center.x - TREE_NODE_W / 2) + 'px';
      el.style.top = (center.y - TREE_NODE_H / 2) + 'px';
    }

    function treeScrollNodeIntoView(nodeId) {
      const n = treeFindNode(nodeId);
      const wrap = document.getElementById('tree-canvas-wrap');
      if (!n || !wrap) return;
      const center = treeNodeCenter(n);
      const zoom = treeGetZoom() || 1;
      const targetLeft = Math.max(0, center.x * zoom - wrap.clientWidth * 0.5);
      const targetTop = Math.max(0, center.y * zoom - wrap.clientHeight * 0.5);
      try {
        wrap.scrollTo({ left: targetLeft, top: targetTop, behavior: 'smooth' });
      } catch (_) {
        wrap.scrollLeft = targetLeft;
        wrap.scrollTop = targetTop;
      }
    }

    function treePortPoint(node, side) {
      const c = treeNodeCenter(node);
      const hw = TREE_NODE_W / 2;
      const hh = TREE_NODE_H / 2;
      const s = treeNormalizeSide(side) || 'r';
      if (s === 't') return { x: c.x, y: c.y - hh };
      if (s === 'b') return { x: c.x, y: c.y + hh };
      if (s === 'l') return { x: c.x - hw, y: c.y };
      return { x: c.x + hw, y: c.y };
    }

    function treePortOut(pt, side, len) {
      const d = len == null ? 18 : len;
      const s = treeNormalizeSide(side) || 'r';
      if (s === 't') return { x: pt.x, y: pt.y - d };
      if (s === 'b') return { x: pt.x, y: pt.y + d };
      if (s === 'l') return { x: pt.x - d, y: pt.y };
      return { x: pt.x + d, y: pt.y };
    }

    function treeSnapColRow(clientX, clientY) {
      const pt = treeClientToStage(clientX, clientY);
      if (!treeState) return { col: treeOriginCol(), row: treeOriginRow() };
      let layoutCol = Math.round((pt.x - TREE_PAD - TREE_COL_W / 2) / TREE_COL_W);
      let layoutRow = Math.round((pt.y - TREE_PAD - TREE_ROW_H / 2) / TREE_ROW_H);
      const cols = treeState.cols || TREE_DEFAULT_COLS;
      const rows = treeState.rows || TREE_DEFAULT_ROWS;
      const margin = TREE_EDGE_BUFFER;
      // 端付近だけで拡張。中央のドラッグでは毎フレーム ensure しない
      const nearEdge = layoutCol < margin || layoutRow < margin
        || layoutCol >= cols - margin || layoutRow >= rows - margin
        || layoutCol < 0 || layoutRow < 0 || layoutCol >= cols || layoutRow >= rows;
      if (nearEdge) {
        const ensured = treeEnsureCanvasBounds({
          includeCol: layoutCol,
          includeRow: layoutRow,
          apply: true,
          rerender: false,
          skipViewport: true,
          skipRulers: true
        });
        layoutCol += ensured.dCol;
        layoutRow += ensured.dRow;
      }
      layoutCol = Math.max(0, Math.min((treeState.cols || cols) - 1, layoutCol));
      layoutRow = Math.max(0, Math.min((treeState.rows || rows) - 1, layoutRow));
      return {
        col: treeLayoutToWorldCol(layoutCol),
        row: treeLayoutToWorldRow(layoutRow)
      };
    }

    function treeClientToStage(clientX, clientY) {
      const wrap = document.getElementById('tree-canvas-wrap');
      if (!wrap) return { x: 0, y: 0 };
      const zoom = treeGetZoom() || 1;
      const rect = wrap.getBoundingClientRect();
      return {
        x: (clientX - rect.left + wrap.scrollLeft) / zoom,
        y: (clientY - rect.top + wrap.scrollTop) / zoom
      };
    }

    function treeFindNode(id) {
      return (treeState.nodes || []).find((n) => n.id === id) || null;
    }

    function setTreeHint(text) {
      const el = document.getElementById('tree-hint');
      if (el) el.textContent = text || '';
    }

    function treeResetInteractionHint() {
      setTreeHint('交点で追加 · Ctrlで複数選択してドラッグでまとめて移動 · 番号でジャンル · 矢印を選んでメモを封入 · ホイール/ピンチで拡大縮小 · 右ドラッグで移動');
      treeUpdateLinkStyleButton();
    }

    function treeStageSize() {
      if (!treeState) return { w: 800, h: 500 };
      return {
        w: Math.max(TREE_PAD * 2 + treeState.cols * TREE_COL_W, 640),
        h: Math.max(TREE_PAD * 2 + treeState.rows * TREE_ROW_H, 480)
      };
    }

    /** いま見えている範囲をセル座標で返す（やや広め） */
    function treeViewportCellRange() {
      const wrap = document.getElementById('tree-canvas-wrap');
      if (!wrap || !treeState) {
        return { c0: 0, c1: (treeState && treeState.cols ? treeState.cols : TREE_DEFAULT_COLS) - 1, r0: 0, r1: (treeState && treeState.rows ? treeState.rows : TREE_DEFAULT_ROWS) - 1 };
      }
      const zoom = treeGetZoom() || 1;
      const left = wrap.scrollLeft / zoom;
      const top = wrap.scrollTop / zoom;
      const right = (wrap.scrollLeft + Math.max(wrap.clientWidth, 1)) / zoom;
      const bottom = (wrap.scrollTop + Math.max(wrap.clientHeight, 1)) / zoom;
      return {
        c0: Math.floor((left - TREE_PAD) / TREE_COL_W) - 1,
        c1: Math.ceil((right - TREE_PAD - TREE_COL_W / 2) / TREE_COL_W) + 1,
        r0: Math.floor((top - TREE_PAD) / TREE_ROW_H) - 1,
        r1: Math.ceil((bottom - TREE_PAD - TREE_ROW_H / 2) / TREE_ROW_H) + 1
      };
    }

    /** 左／上に余白を足す。ノードのワールド座標は変えず、原点だけずらす */
    function treeShiftOrigin(dCol, dRow) {
      if (!treeState || (!dCol && !dRow)) return;
      treeState.originCol = treeOriginCol() - dCol;
      treeState.originRow = treeOriginRow() - dRow;
      const d = treeDom();
      if (treeUiLite) {
        // 操作中は全ノードの left/top を触らず、レイヤー transform で吸収
        treeLiteOriginTx += dCol * TREE_COL_W;
        treeLiteOriginTy += dRow * TREE_ROW_H;
        treeApplyLiteLayerTransform();
      } else if (d.layer) {
        const byId = new Map((treeState.nodes || []).map((n) => [n.id, n]));
        d.layer.querySelectorAll('.tree-node').forEach((el) => {
          const n = byId.get(el.dataset.nodeId);
          if (n) treePlaceNodeEl(el, n);
        });
      }
      const wrap = d.wrap;
      const zoom = treeGetZoom() || 1;
      const dx = dCol * TREE_COL_W * zoom;
      const dy = dRow * TREE_ROW_H * zoom;
      if (wrap) {
        wrap.scrollLeft += dx;
        wrap.scrollTop += dy;
      }
      if (treePan) {
        treePan.scrollLeft += dx;
        treePan.scrollTop += dy;
      }
      treeLastRailsKey = '';
      treeLastRulerKey = '';
      treeEdgesDirty = true;
      // 操作中は配線の本計算を後回し（終了時にまとめて）
      if (!treeIsInteractBusy() && !treeUiLite) treeScheduleEdgeRefresh(false);
    }

    /**
     * 無限キャンバスの境界を広げる。
     * - ノード／指定セル／表示範囲の外側に TREE_EDGE_BUFFER 分の空きを確保
     * - 左・上にはみ出す必要があれば原点をずらす（ノード番号は不変）
     * @returns {{ changed:boolean, dCol:number, dRow:number }}
     */
    function treeEnsureCanvasBounds(opts) {
      opts = opts || {};
      if (!treeState) return { changed: false, dCol: 0, dRow: 0 };

      let minLayoutCol = 0;
      let minLayoutRow = 0;
      let maxLayoutCol = Math.max(0, (treeState.cols || TREE_DEFAULT_COLS) - 1);
      let maxLayoutRow = Math.max(0, (treeState.rows || TREE_DEFAULT_ROWS) - 1);

      (treeState.nodes || []).forEach((n) => {
        if (!n) return;
        const lc = treeWorldToLayoutCol(n.col);
        const lr = treeWorldToLayoutRow(n.row);
        minLayoutCol = Math.min(minLayoutCol, lc - TREE_EDGE_BUFFER);
        minLayoutRow = Math.min(minLayoutRow, lr - TREE_EDGE_BUFFER);
        maxLayoutCol = Math.max(maxLayoutCol, lc + TREE_EDGE_BUFFER);
        maxLayoutRow = Math.max(maxLayoutRow, lr + TREE_EDGE_BUFFER);
      });

      if (Number.isFinite(opts.includeCol)) {
        minLayoutCol = Math.min(minLayoutCol, opts.includeCol - TREE_EDGE_BUFFER);
        maxLayoutCol = Math.max(maxLayoutCol, opts.includeCol + TREE_EDGE_BUFFER);
      }
      if (Number.isFinite(opts.includeRow)) {
        minLayoutRow = Math.min(minLayoutRow, opts.includeRow - TREE_EDGE_BUFFER);
        maxLayoutRow = Math.max(maxLayoutRow, opts.includeRow + TREE_EDGE_BUFFER);
      }

      if (!opts.skipViewport) {
        const vp = treeViewportCellRange();
        minLayoutCol = Math.min(minLayoutCol, vp.c0 - TREE_EDGE_BUFFER + 1);
        maxLayoutCol = Math.max(maxLayoutCol, vp.c1 + TREE_EDGE_BUFFER - 1);
        minLayoutRow = Math.min(minLayoutRow, vp.r0 - TREE_EDGE_BUFFER + 1);
        maxLayoutRow = Math.max(maxLayoutRow, vp.r1 + TREE_EDGE_BUFFER - 1);
      }

      let dCol = 0;
      let dRow = 0;
      if (minLayoutCol < 0) dCol = -minLayoutCol;
      if (minLayoutRow < 0) dRow = -minLayoutRow;
      if (dCol || dRow) {
        treeShiftOrigin(dCol, dRow);
        maxLayoutCol += dCol;
        maxLayoutRow += dRow;
        minLayoutCol += dCol;
        minLayoutRow += dRow;
      }

      const nextCols = Math.max(TREE_DEFAULT_COLS, Math.min(TREE_HARD_MAX, maxLayoutCol + 1));
      const nextRows = Math.max(TREE_DEFAULT_ROWS, Math.min(TREE_HARD_MAX, maxLayoutRow + 1));
      let changed = !!(dCol || dRow);
      if (nextCols > treeState.cols) {
        treeState.cols = nextCols;
        changed = true;
      }
      if (nextRows > treeState.rows) {
        treeState.rows = nextRows;
        changed = true;
      }

      if (changed && opts.apply !== false) {
        const lite = !!(opts.skipRulers || treeUiLite || treeIsInteractBusy());
        if (lite) treeApplyZoomTransform({ sizeOnly: true });
        else {
          treeApplyZoomTransform({ skipRulers: !!opts.skipRulers });
          if (opts.rerender !== false) treeRenderRailsOnly();
        }
      }
      return { changed, dCol, dRow };
    }

    /** 端に近づいたら余白を足す（パン中は拡張しない＝抜本的に軽くする） */
    function treeGrowNearEdges() {
      if (!treeState || treeGrowingBounds) return false;
      // パン中の自動拡張が重さの主因。ノード配置と矢印の引き中だけ広げる
      if (treePan || (treeUiLite && !treeDrag && !treePortLink && !treeEdgeRebind)) return false;
      const wrap = treeDom().wrap || document.getElementById('tree-canvas-wrap');
      if (!wrap) return false;
      treeGrowingBounds = true;
      try {
        const zoom = treeGetZoom() || 1;
        const busy = treeUiLite || treeIsInteractBusy();
        const edgePx = Math.max(TREE_COL_W, TREE_ROW_H) * zoom * (busy ? 2.2 : 1.2);
        const needLeft = wrap.scrollLeft < edgePx;
        const needTop = wrap.scrollTop < edgePx;
        const needRight = wrap.scrollLeft + wrap.clientWidth > wrap.scrollWidth - edgePx;
        const needBottom = wrap.scrollTop + wrap.clientHeight > wrap.scrollHeight - edgePx;
        if (!needLeft && !needTop && !needRight && !needBottom) {
          // 端でなければ拡張しない（交点は scroll 側の rails refresh で更新）
          return false;
        }
        const chunk = busy ? TREE_GROW_CHUNK_BUSY : TREE_EDGE_BUFFER;
        const includeCol = needLeft
          ? -chunk
          : (needRight ? treeState.cols + chunk - 1 : null);
        const includeRow = needTop
          ? -chunk
          : (needBottom ? treeState.rows + chunk - 1 : null);
        const res = treeEnsureCanvasBounds({
          includeCol,
          includeRow,
          apply: true,
          rerender: !busy,
          skipRulers: busy
        });
        if (res.changed && !treeIsInteractBusy()) scheduleTreeSave();
        else if (res.changed) treeSaveSuppressed = true;
        return !!res.changed;
      } finally {
        treeGrowingBounds = false;
      }
    }

    /** 固有座標 0 のマスの左上を、見ている範囲の左上に合わせる */
    function treeAlignCoordsToZero(opts) {
      opts = opts || {};
      if (!treeState) return;
      const wrap = document.getElementById('tree-canvas-wrap');
      if (!wrap) return;
      treeEnsureCanvasBounds({
        includeCol: treeWorldToLayoutCol(0),
        includeRow: treeWorldToLayoutRow(0),
        apply: true,
        rerender: true
      });
      const zoom = treeGetZoom() || 1;
      const x = Math.max(0, (TREE_PAD + treeWorldToLayoutCol(0) * TREE_COL_W) * zoom);
      const y = Math.max(0, (TREE_PAD + treeWorldToLayoutRow(0) * TREE_ROW_H) * zoom);
      const already = Math.abs(wrap.scrollLeft - x) < 2 && Math.abs(wrap.scrollTop - y) < 2;
      wrap.scrollLeft = x;
      wrap.scrollTop = y;
      treeLastRulerKey = '';
      treeRenderRulers();
      if (opts.silent) return;
      setTreeHint(already ? 'すでに座標0が左上です' : '座標0を左上に合わせました');
      if (treeZoomHintTimer) clearTimeout(treeZoomHintTimer);
      treeZoomHintTimer = setTimeout(() => {
        treeZoomHintTimer = null;
        treeResetInteractionHint();
      }, 1400);
    }

    /** ツリーを開いた直後は、レイアウト確定後にもう一度 0 に合わせる */
    function treeOpenAtOrigin() {
      const run = () => {
        const mode = document.getElementById('tree-mode');
        if (!mode || !mode.classList.contains('active') || !treeState) return;
        treeAlignCoordsToZero({ silent: true });
      };
      run();
      requestAnimationFrame(run);
    }

    function treeScheduleGrowNearEdges() {
      if (treeGrowRaf) return;
      treeGrowRaf = requestAnimationFrame(() => {
        treeGrowRaf = 0;
        const busy = treeUiLite || treeIsInteractBusy();
        const now = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
        if (busy && (now - treeGrowLastAt) < TREE_GROW_THROTTLE_BUSY_MS) return;
        treeGrowLastAt = now;
        treeGrowNearEdges();
      });
    }

    function treeScheduleRailsRefresh() {
      if (treeRailsRaf) return;
      treeRailsRaf = requestAnimationFrame(() => {
        treeRailsRaf = 0;
        treeRenderRailsOnly();
      });
    }

    const TREE_LANE_COLORS = [
      'rgba(34, 211, 238, 0.34)',
      'rgba(251, 191, 36, 0.36)',
      'rgba(167, 139, 250, 0.36)',
      'rgba(52, 211, 153, 0.34)',
      'rgba(251, 113, 133, 0.34)',
      'rgba(96, 165, 250, 0.36)',
      'rgba(244, 114, 182, 0.34)',
      'rgba(163, 230, 53, 0.32)'
    ];

    function treeShiftLaneKeys(dCol, dRow) {
      const lanes = treeState && treeState.laneLabels;
      if (!lanes) return;
      const move = (bag, delta) => {
        if (!bag || !delta) return bag || {};
        const next = {};
        Object.keys(bag).forEach((k) => {
          const i = Number(k) + delta;
          if (!Number.isFinite(i) || i < 0) return;
          next[String(i)] = bag[k];
        });
        return next;
      };
      if (dCol) lanes.cols = move(lanes.cols, dCol);
      if (dRow) lanes.rows = move(lanes.rows, dRow);
      if (!Object.keys(lanes.cols || {}).length && !Object.keys(lanes.rows || {}).length) {
        delete treeState.laneLabels;
      }
    }

    function treeLaneBag(axis) {
      const lanes = treeState && treeState.laneLabels;
      if (!lanes) return null;
      return axis === 'col' ? lanes.cols : lanes.rows;
    }

    function treeLaneName(axis, index) {
      const bag = treeLaneBag(axis);
      const item = bag && bag[String(index)];
      return item && item.name ? String(item.name) : '';
    }

    function treeLaneColor(name) {
      let h = 0;
      const s = String(name || '');
      for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
      return TREE_LANE_COLORS[h % TREE_LANE_COLORS.length];
    }

    function treeLaneSignature() {
      const lanes = treeState && treeState.laneLabels;
      if (!lanes) return '';
      const pack = (bag) => Object.keys(bag || {}).sort().map((k) => k + '=' + bag[k].name).join(',');
      return pack(lanes.cols) + '/' + pack(lanes.rows);
    }

    function treeSetLaneName(axis, index, name) {
      if (!treeState || !Number.isFinite(index) || Math.abs(index) >= TREE_HARD_MAX) return;
      if (!treeState.laneLabels) treeState.laneLabels = { cols: {}, rows: {} };
      const key = axis === 'col' ? 'cols' : 'rows';
      if (!treeState.laneLabels[key]) treeState.laneLabels[key] = {};
      if (!name) delete treeState.laneLabels[key][String(index)];
      else treeState.laneLabels[key][String(index)] = { name };
      if (!Object.keys(treeState.laneLabels.cols || {}).length && !Object.keys(treeState.laneLabels.rows || {}).length) {
        delete treeState.laneLabels;
      }
    }

    function treeRenameLane(axis, index) {
      if (!treeState || (axis !== 'col' && axis !== 'row') || !Number.isFinite(index)) return;
      const axisLabel = axis === 'col' ? '列' : '行';
      const labelNum = axis === 'col' ? treeWorldLabelCol(index) : treeWorldLabelRow(index);
      const current = treeLaneName(axis, index);
      const next = window.prompt(axisLabel + ' ' + labelNum + ' のジャンル名（空欄で解除）', current);
      if (next == null) return;
      const name = String(next).trim().slice(0, 24);
      if (name === current) return;
      treePushUndoSnapshot();
      treeSetLaneName(axis, index, name);
      scheduleTreeSave();
      treeLastRulerKey = '';
      const laneLayer = document.getElementById('tree-lanes-layer');
      if (laneLayer) delete laneLayer.dataset.key;
      treeRenderRulers();
      setTreeHint(name
        ? (axisLabel + labelNum + ' を「' + name + '」にしました')
        : (axisLabel + labelNum + ' の名前を外しました'));
    }

    function treeRenderLanes() {
      const layer = document.getElementById('tree-lanes-layer');
      if (!layer || !treeState) return;
      const wrap = document.getElementById('tree-canvas-wrap');
      const zoom = treeGetZoom() || 1;
      const lanes = treeState.laneLabels || { cols: {}, rows: {} };
      const colKeys = Object.keys(lanes.cols || {});
      const rowKeys = Object.keys(lanes.rows || {});
      if (!colKeys.length && !rowKeys.length) {
        if (layer.dataset.key !== '') {
          layer.dataset.key = '';
          layer.innerHTML = '';
        }
        return;
      }
      const viewLeft = wrap ? wrap.scrollLeft / zoom : 0;
      const viewTop = wrap ? wrap.scrollTop / zoom : 0;
      const viewKey = treeLaneSignature() + '@' + treeState.cols + 'x' + treeState.rows
        + ':' + treeOriginCol() + ',' + treeOriginRow()
        + ':' + Math.round(viewLeft / 12) + ',' + Math.round(viewTop / 12);
      if (layer.dataset.key === viewKey) return;
      layer.dataset.key = viewKey;
      const inset = 10;
      const gridW = treeState.cols * TREE_COL_W;
      const gridH = treeState.rows * TREE_ROW_H;
      const parts = [];
      colKeys.forEach((k) => {
        const worldC = Number(k);
        const layoutC = treeWorldToLayoutCol(worldC);
        if (layoutC < -1 || layoutC > treeState.cols) return;
        const name = lanes.cols[k].name;
        const x = TREE_PAD + layoutC * TREE_COL_W + inset;
        const nameTop = Math.max(inset, viewTop - TREE_PAD + 8);
        parts.push(
          '<div class="tree-lane-bar is-col" style="left:' + x + 'px;top:' + TREE_PAD + 'px;width:'
          + (TREE_COL_W - inset * 2) + 'px;height:' + gridH + 'px;background:' + treeLaneColor(name) + '">'
          + '<span class="tree-lane-name" style="top:' + nameTop.toFixed(0) + 'px">' + escapeHtmlText(name) + '</span></div>'
        );
      });
      rowKeys.forEach((k) => {
        const worldR = Number(k);
        const layoutR = treeWorldToLayoutRow(worldR);
        if (layoutR < -1 || layoutR > treeState.rows) return;
        const name = lanes.rows[k].name;
        const y = TREE_PAD + layoutR * TREE_ROW_H + inset;
        const nameLeft = Math.max(inset, viewLeft - TREE_PAD + 8);
        parts.push(
          '<div class="tree-lane-bar is-row" style="left:' + TREE_PAD + 'px;top:' + y + 'px;width:'
          + gridW + 'px;height:' + (TREE_ROW_H - inset * 2) + 'px;background:' + treeLaneColor(name) + '">'
          + '<span class="tree-lane-name" style="left:' + nameLeft.toFixed(0) + 'px">' + escapeHtmlText(name) + '</span></div>'
        );
      });
      layer.innerHTML = parts.join('');
      layer.style.width = (TREE_PAD * 2 + gridW) + 'px';
      layer.style.height = (TREE_PAD * 2 + gridH) + 'px';
    }

    /** 上・下に列番号、左・右に行番号（固有ワールド座標・1始まり）。選択中のマスを強調 */
    function treeRenderRulers() {
      if (!treeState) return;
      const wrap = document.getElementById('tree-canvas-wrap');
      const top = document.getElementById('tree-ruler-top');
      const bottom = document.getElementById('tree-ruler-bottom');
      const left = document.getElementById('tree-ruler-left');
      const right = document.getElementById('tree-ruler-right');
      if (!wrap || !top || !bottom || !left || !right) return;
      const zoom = treeGetZoom() || 1;
      const size = treeStageSize();
      const vr = treeViewportCellRange();
      const c0 = Math.max(0, Math.min(treeState.cols - 1, vr.c0));
      const c1 = Math.max(c0, Math.min(treeState.cols - 1, vr.c1));
      const r0 = Math.max(0, Math.min(treeState.rows - 1, vr.r0));
      const r1 = Math.max(r0, Math.min(treeState.rows - 1, vr.r1));
      const sel = (treeState.nodes || []).find((n) => n.id === treeSelectedNodeId) || null;
      const selLayoutCol = sel ? treeWorldToLayoutCol(sel.col) : null;
      const selLayoutRow = sel ? treeWorldToLayoutRow(sel.row) : null;
      const w = Math.max(size.w * zoom, wrap.clientWidth || 0);
      const h = Math.max(size.h * zoom, wrap.clientHeight || 0);
      const stepX = Math.max(1, Math.ceil(16 / (TREE_COL_W * zoom)));
      const stepY = Math.max(1, Math.ceil(14 / (TREE_ROW_H * zoom)));
      const key = [c0, c1, r0, r1, zoom, Math.round(w), Math.round(h), stepX, stepY,
        treeOriginCol(), treeOriginRow(),
        sel ? sel.col : '', sel ? sel.row : '', treeLaneSignature()].join(':');
      if (key !== treeLastRulerKey) {
        treeLastRulerKey = key;
        const xParts = [];
        for (let c = c0; c <= c1; c++) {
          const worldC = treeLayoutToWorldCol(c);
          const colName = treeLaneName('col', worldC);
          if (c % stepX !== 0 && !(selLayoutCol === c) && !colName) continue;
          const x = (TREE_PAD + c * TREE_COL_W + TREE_COL_W / 2) * zoom;
          const color = colName ? treeLaneColor(colName) : '';
          const label = treeWorldLabelCol(worldC);
          xParts.push(
            '<button type="button" class="tree-ruler-label' + (selLayoutCol === c ? ' is-active' : '') + (colName ? ' is-named' : '')
            + '" data-axis="col" data-index="' + worldC + '" title="' + (colName ? escapeHtmlText(colName) : ('列 ' + label))
            + '" style="left:' + x.toFixed(1) + 'px' + (color ? ';background:' + color : '') + '">' + label + '</button>'
          );
        }
        const yParts = [];
        for (let r = r0; r <= r1; r++) {
          const worldR = treeLayoutToWorldRow(r);
          const rowName = treeLaneName('row', worldR);
          if (r % stepY !== 0 && !(selLayoutRow === r) && !rowName) continue;
          const y = (TREE_PAD + r * TREE_ROW_H + TREE_ROW_H / 2) * zoom;
          const color = rowName ? treeLaneColor(rowName) : '';
          const label = treeWorldLabelRow(worldR);
          yParts.push(
            '<button type="button" class="tree-ruler-label' + (selLayoutRow === r ? ' is-active' : '') + (rowName ? ' is-named' : '')
            + '" data-axis="row" data-index="' + worldR + '" title="' + (rowName ? escapeHtmlText(rowName) : ('行 ' + label))
            + '" style="top:' + y.toFixed(1) + 'px' + (color ? ';background:' + color : '') + '">' + label + '</button>'
          );
        }
        const xTrack = '<div class="tree-ruler-track" style="width:' + Math.round(w) + 'px;height:100%">' + xParts.join('') + '</div>';
        const yTrack = '<div class="tree-ruler-track" style="width:100%;height:' + Math.round(h) + 'px">' + yParts.join('') + '</div>';
        top.innerHTML = xTrack;
        bottom.innerHTML = xTrack;
        left.innerHTML = yTrack;
        right.innerHTML = yTrack;
      }
      const sl = wrap.scrollLeft;
      const st = wrap.scrollTop;
      top.scrollLeft = sl;
      bottom.scrollLeft = sl;
      left.scrollTop = st;
      right.scrollTop = st;
      // 操作中はレーン帯の再生成もスキップ（スクロール追従のみ）
      if (!treeUiLite) treeRenderLanes();
    }

    /** ステージ寸法＋表示範囲の交点（treeCellCenter と同一座標で SVG 描画） */
    function treeRenderRailsOnly() {
      if (!treeState) return;
      if (treeUiLite) {
        treeSyncRulerScrollOnly();
        return;
      }
      treeRenderRulers();
      const stage = document.getElementById('tree-stage');
      const railsSvg = document.getElementById('tree-rails-svg');
      const edgesSvg = document.getElementById('tree-edges-svg');
      const layer = document.getElementById('tree-nodes-layer');
      const size = treeStageSize();
      const vr = treeViewportCellRange();
      const c0 = Math.max(0, Math.min(treeState.cols - 1, vr.c0));
      const c1 = Math.max(c0, Math.min(treeState.cols - 1, vr.c1));
      const r0 = Math.max(0, Math.min(treeState.rows - 1, vr.r0));
      const r1 = Math.max(r0, Math.min(treeState.rows - 1, vr.r1));
      const occupied = new Set((treeState.nodes || []).map((n) =>
        treeWorldToLayoutCol(n.col) + ',' + treeWorldToLayoutRow(n.row)
      ));
      let occBits = '';
      for (let r = r0; r <= r1; r++) {
        for (let c = c0; c <= c1; c++) {
          occBits += occupied.has(c + ',' + r) ? '1' : '0';
        }
      }
      const key = [treeState.cols, treeState.rows, treeOriginCol(), treeOriginRow(), size.w, size.h, c0, c1, r0, r1, occBits].join(':');
      if (key === treeLastRailsKey) return;
      treeLastRailsKey = key;

      if (stage) {
        stage.style.width = size.w + 'px';
        stage.style.height = size.h + 'px';
      }
      if (layer) {
        layer.style.width = size.w + 'px';
        layer.style.height = size.h + 'px';
      }
      [railsSvg, edgesSvg].forEach((svg) => {
        if (!svg) return;
        svg.setAttribute('width', String(size.w));
        svg.setAttribute('height', String(size.h));
        svg.setAttribute('viewBox', '0 0 ' + size.w + ' ' + size.h);
        svg.style.width = size.w + 'px';
        svg.style.height = size.h + 'px';
      });
      if (!railsSvg) return;
      const parts = [];
      for (let r = r0; r <= r1; r++) {
        for (let c = c0; c <= c1; c++) {
          if (occupied.has(c + ',' + r)) continue;
          const center = treeCellCenter(c, r);
          parts.push(
            '<circle class="tree-cross" cx="' + center.x.toFixed(1)
            + '" cy="' + center.y.toFixed(1)
            + '" r="6.5" data-col="' + c + '" data-row="' + r + '"></circle>'
          );
        }
      }
      railsSvg.innerHTML = parts.join('');
    }

    /** 空き交点のヒット（SVGサークルなし）。返す col/row は固有ワールド座標 */
    function treeHitEmptyCellAt(clientX, clientY) {
      if (!treeState) return null;
      const pt = treeClientToStage(clientX, clientY);
      const layoutCol = Math.round((pt.x - TREE_PAD - TREE_COL_W / 2) / TREE_COL_W);
      const layoutRow = Math.round((pt.y - TREE_PAD - TREE_ROW_H / 2) / TREE_ROW_H);
      if (layoutCol < 0 || layoutRow < 0 || layoutCol >= treeState.cols || layoutRow >= treeState.rows) return null;
      const center = treeCellCenter(layoutCol, layoutRow);
      if (Math.hypot(pt.x - center.x, pt.y - center.y) > 16) return null;
      const worldCol = treeLayoutToWorldCol(layoutCol);
      const worldRow = treeLayoutToWorldRow(layoutRow);
      if (treeNodeAtWorld(worldCol, worldRow)) return null;
      return { col: worldCol, row: worldRow };
    }

    function treeDedupePathPts(pts) {
      const out = [];
      for (let i = 0; i < pts.length; i++) {
        const p = pts[i];
        const prev = out[out.length - 1];
        if (prev && Math.abs(prev.x - p.x) < 0.75 && Math.abs(prev.y - p.y) < 0.75) continue;
        // 直前の折れが一直線なら中間点を省略
        if (out.length >= 2) {
          const a = out[out.length - 2];
          const b = prev;
          const colinear =
            (Math.abs(a.x - b.x) < 0.75 && Math.abs(b.x - p.x) < 0.75) ||
            (Math.abs(a.y - b.y) < 0.75 && Math.abs(b.y - p.y) < 0.75);
          if (colinear) out.pop();
        }
        out.push({ x: p.x, y: p.y });
      }
      return out;
    }

    function treeNodeRect(node, pad) {
      pad = Number(pad) || 0;
      const center = treeNodeCenter(node);
      const hw = TREE_NODE_W / 2 + pad;
      const hh = TREE_NODE_H / 2 + pad;
      return {
        left: center.x - hw,
        right: center.x + hw,
        top: center.y - hh,
        bottom: center.y + hh
      };
    }

    function treeSegIntersectsRect(a, b, rect) {
      const isVertical = Math.abs(a.x - b.x) < 0.75;
      const isHorizontal = Math.abs(a.y - b.y) < 0.75;
      if (!isVertical && !isHorizontal) return false;
      if (isVertical) {
        const x = a.x;
        const y1 = Math.min(a.y, b.y);
        const y2 = Math.max(a.y, b.y);
        return x > rect.left && x < rect.right && y2 > rect.top && y1 < rect.bottom;
      }
      const y = a.y;
      const x1 = Math.min(a.x, b.x);
      const x2 = Math.max(a.x, b.x);
      return y > rect.top && y < rect.bottom && x2 > rect.left && x1 < rect.right;
    }

    function treePathIntersectsNodes(pts, ignoreIds) {
      if (!treeState || !Array.isArray(treeState.nodes) || !pts || pts.length < 2) return false;
      const ignores = new Set((ignoreIds || []).map((id) => String(id)));
      for (let n = 0; n < treeState.nodes.length; n++) {
        const node = treeState.nodes[n];
        if (!node || ignores.has(String(node.id))) continue;
        const rect = treeNodeRect(node, 10);
        for (let i = 1; i < pts.length; i++) {
          if (treeSegIntersectsRect(pts[i - 1], pts[i], rect)) return true;
        }
      }
      return false;
    }

    function treePathLength(pts) {
      if (!pts || pts.length < 2) return Infinity;
      let len = 0;
      for (let i = 1; i < pts.length; i++) {
        len += Math.hypot(pts[i].x - pts[i - 1].x, pts[i].y - pts[i - 1].y);
      }
      return len;
    }

    // ===== 配線ルーター =====
    // 目的: ノードの内側を通らず、他の線とも交差・重複しにくい直交経路を選ぶ。
    // 行と行のあいだ（左の番号と番号のすき間）では、同じノードから分かれる束だけ同じ線に重ねる。
    // 端点を共有しない線は、その束に重ならずに迂回する。
    // その水平線は、上下の行の中央を通す。
    // 方針: 列／行から作った格子（レーン）の上で最短経路探索（A*）し、
    //       「距離 + 曲がり + 大回り + 他線との交差・重なり・接近」が最小の道を採用する。
    const TREE_ROUTE_MARGIN = 14;          // ノード外周からの離隔
    const TREE_PORT_CLEAR = 12;            // 接続点の中心から線端までの空き（点が矢印に隠れない）
    const TREE_ROUTE_STUB = 24;            // 接続点から出る助走（空き＋矢印が直線に収まる長さ）
    const TREE_ROUTE_BEND_COST = 24;       // 曲がり1回あたり
    const TREE_ROUTE_CROSS_COST = 100;     // 他の線と交差する（大回りしてまでは避けない）
    const TREE_ROUTE_OVERLAP_COST = 1600;  // 他の線と同じレーンを重なって走る
    const TREE_ROUTE_LANE_EPS = 5;         // 同一レーンとみなす距離
    const TREE_ROUTE_GAP = 20;             // 別の線とこれより近づけて並走しない
    const TREE_ROUTE_TOUCH_GAP = 14;       // 角や線端が別の線にこれより近い＝くっついて見える
    const TREE_ROUTE_ROOM_GAP = 30;        // 角や線端と別の線との、できれば空けたい間隔
    const TREE_ROUTE_NEAR_COST = 160;      // 間隔 TREE_ROUTE_GAP 未満で並走する
    const TREE_ROUTE_TOUCH_COST = 220;     // 角や端が別の線にくっつく（どの矢印か紛らわしい）
    const TREE_ROUTE_ROOM_COST = 30;       // 角や端が別の線に TREE_ROUTE_ROOM_GAP 未満まで寄る
    const TREE_ROUTE_GUTTER_SPREAD_COST = 280; // 行間で別レーンに分かれて並走する
    const TREE_ROUTE_OUTSIDE_GUTTER_COST = 0.7; // 行をまたぐ水平線が、行間の外を通る 1px あたり
    const TREE_ROUTE_GUTTER_CENTER_COST = 3;    // 行間の中央から 1px ずれた水平線の、区間あたりの追加コスト
    const TREE_ROUTE_DETOUR_FREE = 100;    // 端点の範囲からこれ以上外へ出る部分を「大回り」とみなす（隣の行・列の境目までは許す）
    const TREE_ROUTE_DETOUR_COST = 0.5;    // 大回り部分の 1px あたりの追加コスト
    const TREE_ROUTE_TIP_ZONE = TREE_ROUTE_STUB - TREE_PORT_CLEAR + 4; // 線端（矢印・出だし）からこの範囲を横切ると、その接続点につながって見える
    const TREE_ROUTE_SPAN = 2;             // 探索範囲を端点の外側へ広げるマス数
    const TREE_ROUTE_GUARD = 240000;       // 探索の打ち切り
    const TREE_ROUTE_REPASS = 2;           // 後から引いた線と関わる線を引き直す巡回数

    // 線分どうしの関係（コスト表の添字）
    const TREE_PAIR_NONE = 0;
    const TREE_PAIR_OVERLAP = 1;
    const TREE_PAIR_TOUCH = 2;
    const TREE_PAIR_NEAR = 3;
    const TREE_PAIR_CROSS = 4;
    const TREE_PAIR_HALF_CROSS = 5;
    const TREE_PAIR_ROOM = 6;
    const TREE_PAIR_HALF_TOUCH = 7;
    const TREE_PAIR_GUTTER_SPREAD = 8;
    const TREE_PAIR_COSTS = [
      0,
      TREE_ROUTE_OVERLAP_COST,
      TREE_ROUTE_TOUCH_COST,
      TREE_ROUTE_NEAR_COST,
      TREE_ROUTE_CROSS_COST,
      TREE_ROUTE_CROSS_COST / 2,
      TREE_ROUTE_ROOM_COST,
      TREE_ROUTE_TOUCH_COST / 2,
      TREE_ROUTE_GUTTER_SPREAD_COST
    ];

    function treeRouteIsOwnEnd(x, y, a1, b1) {
      return (Math.abs(x - a1.x) < 1.5 && Math.abs(y - a1.y) < 1.5)
        || (Math.abs(x - b1.x) < 1.5 && Math.abs(y - b1.y) < 1.5);
    }

    function treeRouteRowIndex(y) {
      return Math.round((y - TREE_PAD - TREE_ROW_H / 2) / TREE_ROW_H);
    }

    /** 行ノードの下端と、次の行の上端のあいだなら、その上側の行番号。否則 -1 */
    function treeRouteRowGutter(y) {
      const y0 = y - (TREE_PAD + TREE_ROW_H / 2);
      const half = TREE_NODE_H / 2;
      const r = Math.floor((y0 - half) / TREE_ROW_H);
      const openTop = r * TREE_ROW_H + half;
      const openBot = (r + 1) * TREE_ROW_H - half;
      return (y0 > openTop && y0 < openBot) ? r : -1;
    }

    /** 垂直線の両端が、同じ行間か隣り合う行間にある（行の横をまたぐ立ち上がり） */
    function treeRouteVertInGutters(lo, hi) {
      const ga = treeRouteRowGutter(lo);
      const gb = treeRouteRowGutter(hi);
      if (ga < 0 || gb < 0) return false;
      return ga === gb || Math.abs(ga - gb) === 1;
    }

    /** 水平なら両レーンが同じ行間。垂直なら両線とも行間をつなぐ立ち上がり */
    function treeRouteSameRowGutter(horiz, lane, lo, hi, oLane, oA, oB) {
      if (horiz) {
        const g = treeRouteRowGutter(lane);
        return g >= 0 && g === treeRouteRowGutter(oLane);
      }
      return treeRouteVertInGutters(lo, hi) && treeRouteVertInGutters(oA, oB);
    }

    /** 行をまたぐ線が、端点の行に挟まれた行間の外を水平に走る追加コスト */
    function treeRouteOutsideGutterExtra(horiz, lane, span, a1, b1) {
      if (!horiz || !a1 || !b1 || !(span > 0)) return 0;
      const ra = treeRouteRowIndex(a1.y);
      const rb = treeRouteRowIndex(b1.y);
      if (ra === rb) return 0;
      const g = treeRouteRowGutter(lane);
      const loR = ra < rb ? ra : rb;
      const hiR = ra < rb ? rb : ra;
      if (g >= loR && g < hiR) return 0;
      return TREE_ROUTE_OUTSIDE_GUTTER_COST * span;
    }

    /** 行をまたぐ水平線を、上下の行の中央に寄せる */
    function treeRouteGutterCenterExtra(horiz, lane, a1, b1) {
      if (!horiz || !a1 || !b1) return 0;
      const ra = treeRouteRowIndex(a1.y);
      const rb = treeRouteRowIndex(b1.y);
      if (ra === rb) return 0;
      const g = treeRouteRowGutter(lane);
      const loR = ra < rb ? ra : rb;
      const hiR = ra < rb ? rb : ra;
      if (!(g >= loR && g < hiR)) return 0;
      const mid = TREE_PAD + (g + 1) * TREE_ROW_H;
      const dist = Math.abs(lane - mid);
      if (dist <= TREE_ROUTE_LANE_EPS) return 0;
      return dist * TREE_ROUTE_GUTTER_CENTER_COST;
    }

    /** 2本の線が同じノードを端に持つか。不明なら重ねてよい束として扱う */
    function treeRouteSharesNode(aFrom, aTo, bFrom, bTo) {
      if (!aFrom || !aTo || !bFrom || !bTo) return true;
      return aFrom === bFrom || aFrom === bTo || aTo === bFrom || aTo === bTo;
    }

    /**
     * 線分（horiz/lane/lo..hi）と別の線の線分の関係。
     * 自分の接続点の助走端（a1/b1）での接触は避けようがないので数えない。
     * oTips: 相手の線分の端が線そのものの端か（1=oA 側, 2=oB 側）
     */
    function treeRoutePairKind(horiz, lane, lo, hi, oHoriz, oLane, oA, oB, a1, b1, oTips, shareBus) {
      if (shareBus == null) shareBus = true;
      if (horiz === oHoriz) {
        const d = oLane > lane ? oLane - lane : lane - oLane;
        const ov = Math.min(hi, oB) - Math.max(lo, oA);
        // 同じノードから分かれる束だけ、行間で1本に重ねる。
        // 端点を共有しない線はここを通さず、重なりを避けて迂回する。
        if (shareBus && treeRouteSameRowGutter(horiz, lane, lo, hi, oLane, oA, oB)) {
          if (d <= TREE_ROUTE_LANE_EPS && ov > -2) return TREE_PAIR_NONE;
          if (horiz && ov > 24) return TREE_PAIR_GUTTER_SPREAD;
        }
        if (d >= TREE_ROUTE_GAP) return TREE_PAIR_NONE;
        if (d <= TREE_ROUTE_LANE_EPS) {
          if (ov > 3) return TREE_PAIR_OVERLAP;
          // 同じレーンで端どうしが接する（1本につながって見える）。
          // 少し離れているだけなら、曲がった先の区間が直交側の判定で拾う
          if (ov <= -2) return TREE_PAIR_NONE;
          const at = oB <= (lo + hi) / 2 ? lo : hi;
          const own = horiz ? treeRouteIsOwnEnd(at, lane, a1, b1) : treeRouteIsOwnEnd(lane, at, a1, b1);
          return own ? TREE_PAIR_NONE : TREE_PAIR_TOUCH;
        }
        return ov > 0 ? TREE_PAIR_NEAR : TREE_PAIR_NONE;
      }
      const gap = TREE_ROUTE_ROOM_GAP;
      if (oLane < lo - gap || oLane > hi + gap || lane < oA - gap || lane > oB + gap) return TREE_PAIR_NONE;
      const inMine = oLane > lo + 1 && oLane < hi - 1;
      const inOther = lane > oA + 1 && lane < oB - 1;
      const atTip = ((oTips & 1) && lane - oA < TREE_ROUTE_TIP_ZONE) || ((oTips & 2) && oB - lane < TREE_ROUTE_TIP_ZONE);
      if (inMine && inOther) return atTip ? TREE_PAIR_TOUCH : TREE_PAIR_CROSS;
      if (inOther) {
        // 格子点での交差（区間の端が相手の線上）。前後2区間で1回分
        if (oLane < lo - 1 || oLane > hi + 1) return TREE_PAIR_NONE;
        const own = horiz ? treeRouteIsOwnEnd(oLane, lane, a1, b1) : treeRouteIsOwnEnd(lane, oLane, a1, b1);
        if (own) return TREE_PAIR_NONE;
        // 行間の水平線に端が乗って分かれるだけなら、交差ではない
        const atEnd = Math.abs(oLane - lo) <= 1 || Math.abs(oLane - hi) <= 1;
        const junctionY = horiz ? lane : oLane;
        if (atEnd && shareBus && treeRouteRowGutter(junctionY) >= 0) return TREE_PAIR_NONE;
        return atTip ? TREE_PAIR_HALF_TOUCH : TREE_PAIR_HALF_CROSS;
      }
      // 相手の線の端（角）がこの区間のそばにある
      const end = Math.abs(lane - oA) < Math.abs(lane - oB) ? oA : oB;
      const own = horiz ? treeRouteIsOwnEnd(oLane, end, a1, b1) : treeRouteIsOwnEnd(end, oLane, a1, b1);
      if (own) return TREE_PAIR_NONE;
      const along = oLane < lo ? lo - oLane : (oLane > hi ? oLane - hi : 0);
      const across = lane > end ? lane - end : end - lane;
      // 行間の水平線から上下へ分かれる枝は、重ねた1本の分かれ目なので接触に数えない
      const junctionY = horiz ? lane : oLane;
      if (along < 1 && across <= TREE_ROUTE_LANE_EPS && shareBus && treeRouteRowGutter(junctionY) >= 0) return TREE_PAIR_NONE;
      return Math.max(along, across) < TREE_ROUTE_TOUCH_GAP ? TREE_PAIR_TOUCH : TREE_PAIR_ROOM;
    }

    /** 端点（a1/b1）を囲む範囲から外へはみ出す長さ。box は TREE_ROUTE_DETOUR_FREE だけ広げてある */
    function treeRouteDetourLength(horiz, lane, lo, hi, box) {
      const laneMin = horiz ? box.minY : box.minX;
      const laneMax = horiz ? box.maxY : box.maxX;
      if (lane < laneMin || lane > laneMax) return hi - lo;
      const spanMin = horiz ? box.minX : box.minY;
      const spanMax = horiz ? box.maxX : box.maxY;
      let out = 0;
      if (lo < spanMin) out += Math.min(hi, spanMin) - lo;
      if (hi > spanMax) out += hi - Math.max(lo, spanMax);
      return out;
    }

    function treeRouteDetourBox(a1, b1) {
      const free = TREE_ROUTE_DETOUR_FREE;
      return {
        minX: Math.min(a1.x, b1.x) - free,
        maxX: Math.max(a1.x, b1.x) + free,
        minY: Math.min(a1.y, b1.y) - free,
        maxY: Math.max(a1.y, b1.y) + free
      };
    }

    /** 経路の両端を trim だけ縮めて、水平／垂直セグメントにする（線そのものの端は tips に印を付ける） */
    function treeRouteTrimmedSegments(pts, trim) {
      if (!pts || pts.length < 2) return [];
      let vis = treeRetractPolyline(pts, trim, true);
      vis = treeRetractPolyline(vis, trim, false);
      const segs = treeRouteSegments(vis, false);
      const markTip = (s, p) => {
        if (!s || !p) return;
        const at = s.horiz ? p.x : p.y;
        if (Math.abs(at - s.a) < 0.5) s.tips = (s.tips || 0) | 1;
        else if (Math.abs(at - s.b) < 0.5) s.tips = (s.tips || 0) | 2;
      };
      markTip(segs[0], vis[0]);
      markTip(segs[segs.length - 1], vis[vis.length - 1]);
      return segs;
    }

    /** 占有情報用: 接続点の空きを除いた、見えている線の全体 */
    function treeRouteOccSegments(pts) {
      return treeRouteTrimmedSegments(pts, TREE_PORT_CLEAR);
    }

    /** 他の線と交差・接触・並走・重なりのどれかがあるか */
    function treeRouteHasConflict(segs, others, a1, b1, fromId, toId) {
      for (let i = 0; i < segs.length; i++) {
        const s = segs[i];
        for (let j = 0; j < others.length; j++) {
          const o = others[j];
          const share = treeRouteSharesNode(fromId, toId, o.fromId, o.toId);
          if (treeRoutePairKind(s.horiz, s.lane, s.a, s.b, o.horiz, o.lane, o.a, o.b, a1, b1, o.tips || 0, share)) return true;
        }
      }
      return false;
    }

    /** 引き直し前後の比較用: 長さ・曲がり・大回り・他の線との関係をまとめた悪さ */
    function treeRouteScore(pts, others, a1, b1, fromId, toId) {
      let score = Math.max(0, pts.length - 2) * TREE_ROUTE_BEND_COST;
      const box = treeRouteDetourBox(a1, b1);
      const all = treeRouteSegments(pts, false);
      for (let i = 0; i < all.length; i++) {
        const s = all[i];
        score += s.b - s.a
          + TREE_ROUTE_DETOUR_COST * treeRouteDetourLength(s.horiz, s.lane, s.a, s.b, box)
          + treeRouteOutsideGutterExtra(s.horiz, s.lane, s.b - s.a, a1, b1)
          + treeRouteGutterCenterExtra(s.horiz, s.lane, a1, b1);
      }
      const core = treeRouteTrimmedSegments(pts, TREE_ROUTE_STUB);
      for (let i = 0; i < core.length; i++) {
        const s = core[i];
        for (let j = 0; j < others.length; j++) {
          const o = others[j];
          const share = treeRouteSharesNode(fromId, toId, o.fromId, o.toId);
          score += TREE_PAIR_COSTS[treeRoutePairKind(s.horiz, s.lane, s.a, s.b, o.horiz, o.lane, o.a, o.b, a1, b1, o.tips || 0, share)];
        }
      }
      return score;
    }

    function treeRouteObstacles() {
      const rects = [];
      const nodes = (treeState && treeState.nodes) || [];
      for (let i = 0; i < nodes.length; i++) {
        if (!nodes[i]) continue;
        rects.push(treeNodeRect(nodes[i], TREE_ROUTE_MARGIN - 2));
      }
      return rects;
    }

    /** 経路を「水平／垂直セグメント」の一覧にする（両端のスタブは除く） */
    function treeRouteSegments(pts, skipStubs) {
      const segs = [];
      if (!pts || pts.length < 2) return segs;
      const start = skipStubs ? 1 : 0;
      const end = skipStubs ? pts.length - 2 : pts.length - 1;
      for (let i = start; i < end; i++) {
        const a = pts[i];
        const b = pts[i + 1];
        if (!a || !b) continue;
        if (Math.abs(a.y - b.y) < 0.5) {
          segs.push({ horiz: true, lane: a.y, a: Math.min(a.x, b.x), b: Math.max(a.x, b.x) });
        } else if (Math.abs(a.x - b.x) < 0.5) {
          segs.push({ horiz: false, lane: a.x, a: Math.min(a.y, b.y), b: Math.max(a.y, b.y) });
        }
      }
      return segs;
    }

    /** 端点まわりの列・行から、配線に使えるレーン（格子線）を作る */
    function treeRouteGrid(a1, b1) {
      const cols = (treeState && treeState.cols) || TREE_DEFAULT_COLS;
      const rows = (treeState && treeState.rows) || TREE_DEFAULT_ROWS;
      const colOf = (x) => Math.max(0, Math.min(cols - 1, Math.floor((x - TREE_PAD) / TREE_COL_W)));
      const rowOf = (y) => Math.max(0, Math.min(rows - 1, Math.floor((y - TREE_PAD) / TREE_ROW_H)));
      const c0 = Math.max(0, Math.min(colOf(a1.x), colOf(b1.x)) - TREE_ROUTE_SPAN);
      const c1 = Math.min(cols - 1, Math.max(colOf(a1.x), colOf(b1.x)) + TREE_ROUTE_SPAN);
      const r0 = Math.max(0, Math.min(rowOf(a1.y), rowOf(b1.y)) - TREE_ROUTE_SPAN);
      const r1 = Math.min(rows - 1, Math.max(rowOf(a1.y), rowOf(b1.y)) + TREE_ROUTE_SPAN);
      const xs = [];
      const ys = [];
      const add = (arr, v) => {
        if (!Number.isFinite(v)) return;
        for (let i = 0; i < arr.length; i++) {
          if (Math.abs(arr[i] - v) < 1) return;
        }
        arr.push(v);
      };
      const offX = TREE_NODE_W / 2 + TREE_ROUTE_MARGIN;
      const offY = TREE_NODE_H / 2 + TREE_ROUTE_MARGIN;
      for (let c = c0; c <= c1; c++) {
        const cx = TREE_PAD + c * TREE_COL_W + TREE_COL_W / 2;
        add(xs, TREE_PAD + c * TREE_COL_W);
        add(xs, cx - offX);
        add(xs, cx);
        add(xs, cx + offX);
      }
      add(xs, TREE_PAD + (c1 + 1) * TREE_COL_W);
      for (let r = r0; r <= r1; r++) {
        const cy = TREE_PAD + r * TREE_ROW_H + TREE_ROW_H / 2;
        add(ys, TREE_PAD + r * TREE_ROW_H);
        add(ys, cy - offY);
        add(ys, cy);
        add(ys, cy + offY);
      }
      add(ys, TREE_PAD + (r1 + 1) * TREE_ROW_H);
      add(xs, a1.x);
      add(xs, b1.x);
      add(ys, a1.y);
      add(ys, b1.y);
      xs.sort((p, q) => p - q);
      ys.sort((p, q) => p - q);
      return { xs, ys };
    }

    function treeRouteNearestIndex(arr, v) {
      let best = 0;
      let bestD = Infinity;
      for (let i = 0; i < arr.length; i++) {
        const d = Math.abs(arr[i] - v);
        if (d < bestD) {
          bestD = d;
          best = i;
        }
      }
      return best;
    }

    /** 格子上の最小コスト経路。dir: 0=水平, 1=垂直。a0/b0 は接続点（助走の根元） */
    function treeRouteSolve(a1, b1, startDir, goalDir, occ, obstacles, a0, b0, fromId, toId) {
      const grid = treeRouteGrid(a1, b1);
      const xs = grid.xs;
      const ys = grid.ys;
      const nx = xs.length;
      const ny = ys.length;
      if (nx < 2 || ny < 2) return null;
      const sxi = treeRouteNearestIndex(xs, a1.x);
      const syi = treeRouteNearestIndex(ys, a1.y);
      const txi = treeRouteNearestIndex(xs, b1.x);
      const tyi = treeRouteNearestIndex(ys, b1.y);
      // 助走の先端からノード側へ折り返す一歩。許すと助走が短くなり、矢印が角に掛かる
      const backCell = (xi, yi, port, tip) => {
        if (!port || !tip) return -1;
        let bx = xi;
        let by = yi;
        if (port.x < tip.x - 0.5) bx--;
        else if (port.x > tip.x + 0.5) bx++;
        else if (port.y < tip.y - 0.5) by--;
        else if (port.y > tip.y + 0.5) by++;
        else return -1;
        if (bx < 0 || by < 0 || bx >= nx || by >= ny) return -1;
        return by * nx + bx;
      };
      const startCell = syi * nx + sxi;
      const startBack = backCell(sxi, syi, a0, a1);
      const goalBack = backCell(txi, tyi, b0, b1);
      const cells = nx * ny;
      const states = cells * 2;
      const dist = new Float64Array(states).fill(Infinity);
      const prev = new Int32Array(states).fill(-1);
      const done = new Uint8Array(states);
      const hCost = new Float64Array(cells).fill(-1);
      const vCost = new Float64Array(cells).fill(-1);

      // 探索範囲の外にあるノード・線は関係しないので除き、数値配列に展開しておく（線が多いときの重さ対策）
      const gap = TREE_ROUTE_GAP;
      const tgap = TREE_ROUTE_ROOM_GAP;
      const detourBox = treeRouteDetourBox(a1, b1);
      const minX = xs[0] - tgap;
      const maxX = xs[nx - 1] + tgap;
      const minY = ys[0] - tgap;
      const maxY = ys[ny - 1] + tgap;
      const obsList = obstacles.filter((o) => o.right > minX && o.left < maxX && o.bottom > minY && o.top < maxY);
      const obsN = obsList.length;
      const obsL = new Float64Array(obsN);
      const obsR = new Float64Array(obsN);
      const obsT = new Float64Array(obsN);
      const obsB = new Float64Array(obsN);
      for (let i = 0; i < obsN; i++) {
        obsL[i] = obsList[i].left;
        obsR[i] = obsList[i].right;
        obsT[i] = obsList[i].top;
        obsB[i] = obsList[i].bottom;
      }
      // 既存の線は向きごとに lane 順へ並べ、近い lane だけを二分探索で拾う
      const packOcc = (horiz) => {
        const list = occ
          .filter((o) => o && !!o.horiz === horiz && (horiz
            ? (o.lane >= minY && o.lane <= maxY && o.b >= minX && o.a <= maxX)
            : (o.lane >= minX && o.lane <= maxX && o.b >= minY && o.a <= maxY)))
          .sort((p, q) => p.lane - q.lane);
        const n = list.length;
        const lane = new Float64Array(n);
        const a = new Float64Array(n);
        const b = new Float64Array(n);
        const tips = new Uint8Array(n);
        const bus = new Uint8Array(n);
        for (let i = 0; i < n; i++) {
          lane[i] = list[i].lane;
          a[i] = list[i].a;
          b[i] = list[i].b;
          tips[i] = list[i].tips || 0;
          bus[i] = treeRouteSharesNode(fromId, toId, list[i].fromId, list[i].toId) ? 1 : 0;
        }
        return { n, lane, a, b, tips, bus };
      };
      const occHz = packOcc(true);
      const occVt = packOcc(false);
      const firstLaneAtLeast = (pack, v) => {
        let lo = 0;
        let hi = pack.n;
        while (lo < hi) {
          const mid = (lo + hi) >> 1;
          if (pack.lane[mid] < v) lo = mid + 1;
          else hi = mid;
        }
        return lo;
      };

      // horiz: lane=y, lo..hi=x / vert: lane=x, lo..hi=y
      const segWeight = (horiz, lane, lo, hi) => {
        for (let i = 0; i < obsN; i++) {
          if (horiz) {
            if (lane > obsT[i] && lane < obsB[i] && hi > obsL[i] && lo < obsR[i]) return Infinity;
          } else if (lane > obsL[i] && lane < obsR[i] && hi > obsT[i] && lo < obsB[i]) {
            return Infinity;
          }
        }
        let w = hi - lo + TREE_ROUTE_DETOUR_COST * treeRouteDetourLength(horiz, lane, lo, hi, detourBox);
        w += treeRouteOutsideGutterExtra(horiz, lane, hi - lo, a1, b1);
        w += treeRouteGutterCenterExtra(horiz, lane, a1, b1);
        const same = horiz ? occHz : occVt;
        // 行間はレーン間隔が GAP より広い。水平だけ、行間の幅まで隣レーンを見る
        const laneWindow = horiz ? Math.max(gap, TREE_ROW_H - TREE_NODE_H) : gap;
        for (let i = firstLaneAtLeast(same, lane - laneWindow + 0.01); i < same.n && same.lane[i] < lane + laneWindow; i++) {
          const kind = treeRoutePairKind(horiz, lane, lo, hi, horiz, same.lane[i], same.a[i], same.b[i], a1, b1, same.tips[i], same.bus[i] === 1);
          if (kind) w += TREE_PAIR_COSTS[kind];
        }
        const across = horiz ? occVt : occHz;
        for (let i = firstLaneAtLeast(across, lo - tgap); i < across.n && across.lane[i] <= hi + tgap; i++) {
          if (lane < across.a[i] - tgap || lane > across.b[i] + tgap) continue;
          const kind = treeRoutePairKind(horiz, lane, lo, hi, !horiz, across.lane[i], across.a[i], across.b[i], a1, b1, across.tips[i], across.bus[i] === 1);
          if (kind) w += TREE_PAIR_COSTS[kind];
        }
        return w;
      };

      const hWeight = (xi, yi) => {
        const k = yi * nx + xi;
        if (hCost[k] < 0) hCost[k] = segWeight(true, ys[yi], xs[xi], xs[xi + 1]);
        return hCost[k];
      };
      const vWeight = (xi, yi) => {
        const k = yi * nx + xi;
        if (vCost[k] < 0) vCost[k] = segWeight(false, xs[xi], ys[yi], ys[yi + 1]);
        return vCost[k];
      };

      const heapC = [];
      const heapS = [];
      const heapPush = (c, s) => {
        heapC.push(c);
        heapS.push(s);
        let i = heapC.length - 1;
        while (i > 0) {
          const p = (i - 1) >> 1;
          if (heapC[p] <= heapC[i]) break;
          const tc = heapC[p]; heapC[p] = heapC[i]; heapC[i] = tc;
          const ts = heapS[p]; heapS[p] = heapS[i]; heapS[i] = ts;
          i = p;
        }
      };
      const heapPop = () => {
        const topS = heapS[0];
        const lastC = heapC.pop();
        const lastS = heapS.pop();
        if (heapC.length) {
          heapC[0] = lastC;
          heapS[0] = lastS;
          let i = 0;
          for (; ;) {
            const l = i * 2 + 1;
            const r = l + 1;
            let m = i;
            if (l < heapC.length && heapC[l] < heapC[m]) m = l;
            if (r < heapC.length && heapC[r] < heapC[m]) m = r;
            if (m === i) break;
            const tc = heapC[m]; heapC[m] = heapC[i]; heapC[i] = tc;
            const ts = heapS[m]; heapS[m] = heapS[i]; heapS[i] = ts;
            i = m;
          }
        }
        return topS;
      };

      // A*: 残りのマンハッタン距離を下限見積もりにする（各区間のコストは長さ以上なので最適性は保たれる）
      const hx = new Float64Array(nx);
      const hy = new Float64Array(ny);
      for (let i = 0; i < nx; i++) hx[i] = Math.abs(xs[i] - xs[txi]);
      for (let i = 0; i < ny; i++) hy[i] = Math.abs(ys[i] - ys[tyi]);

      const startState = (syi * nx + sxi) * 2 + (startDir ? 1 : 0);
      const goalCell = tyi * nx + txi;
      const goalAxis = goalDir ? 1 : 0;
      dist[startState] = 0;
      heapPush(hx[sxi] + hy[syi], startState);
      let guard = 0;
      let bestGoal = Infinity;

      while (heapC.length) {
        if (heapC[0] >= bestGoal) break;
        const st = heapPop();
        if (done[st]) continue;
        done[st] = 1;
        if (++guard > TREE_ROUTE_GUARD) break;
        const cell = st >> 1;
        const dir = st & 1;
        if (cell === goalCell) {
          const c = dist[st] + (dir === goalAxis ? 0 : TREE_ROUTE_BEND_COST);
          if (c < bestGoal) bestGoal = c;
          continue;
        }
        const xi = cell % nx;
        const yi = (cell - xi) / nx;
        const base = dist[st];
        const relax = (nxi, nyi, ndir, w) => {
          if (!Number.isFinite(w)) return;
          const ncell = nyi * nx + nxi;
          if ((cell === startCell && ncell === startBack) || (ncell === goalCell && cell === goalBack)) return;
          const ns = ncell * 2 + ndir;
          if (done[ns]) return;
          const nc = base + w + (ndir === dir ? 0 : TREE_ROUTE_BEND_COST);
          if (nc < dist[ns] - 0.0001) {
            dist[ns] = nc;
            prev[ns] = st;
            heapPush(nc + hx[nxi] + hy[nyi], ns);
          }
        };
        if (xi + 1 < nx) relax(xi + 1, yi, 0, hWeight(xi, yi));
        if (xi > 0) relax(xi - 1, yi, 0, hWeight(xi - 1, yi));
        if (yi + 1 < ny) relax(xi, yi + 1, 1, vWeight(xi, yi));
        if (yi > 0) relax(xi, yi - 1, 1, vWeight(xi, yi - 1));
      }

      let goalState = -1;
      let goalCost = Infinity;
      for (let d = 0; d < 2; d++) {
        const st = (tyi * nx + txi) * 2 + d;
        const c = dist[st] + (d === (goalDir ? 1 : 0) ? 0 : TREE_ROUTE_BEND_COST);
        if (c < goalCost) {
          goalCost = c;
          goalState = st;
        }
      }
      if (goalState < 0 || !Number.isFinite(goalCost)) return null;

      const pts = [];
      let cur = goalState;
      let steps = 0;
      while (cur >= 0 && steps++ < states) {
        const cell = cur >> 1;
        const xi = cell % nx;
        const yi = (cell - xi) / nx;
        pts.push({ x: xs[xi], y: ys[yi] });
        cur = prev[cur];
      }
      pts.reverse();
      return { pts, cost: goalCost };
    }

    /**
     * 1本ぶんの経路点。occ に既存の線のセグメントを渡すと、それを避けて通る。
     */
    function treeRouteEdgePoints(fromNode, toNode, fromSide, toSide, occ) {
      if (!fromNode || !toNode) return [];
      if (!fromSide || !toSide) {
        const inferred = treeInferSides(fromNode, toNode);
        fromSide = fromSide || inferred.fromSide;
        toSide = toSide || inferred.toSide;
      }
      fromSide = treeNormalizeSide(fromSide) || 'r';
      toSide = treeNormalizeSide(toSide) || 'l';

      const a0 = treePortPoint(fromNode, fromSide);
      const b0 = treePortPoint(toNode, toSide);
      const a1 = treePortOut(a0, fromSide, TREE_ROUTE_STUB);
      const b1 = treePortOut(b0, toSide, TREE_ROUTE_STUB);
      const startDir = (fromSide === 'l' || fromSide === 'r') ? 0 : 1;
      const goalDir = (toSide === 'l' || toSide === 'r') ? 0 : 1;

      const solved = treeRouteSolve(a1, b1, startDir, goalDir, occ || [], treeRouteObstacles(), a0, b0, fromNode && fromNode.id, toNode && toNode.id);
      let mid;
      if (solved && solved.pts && solved.pts.length >= 2) {
        mid = solved.pts;
      } else {
        // 保険: 経路が見つからないときは単純なL字
        mid = startDir === 0
          ? [a1, { x: b1.x, y: a1.y }, b1]
          : [a1, { x: a1.x, y: b1.y }, b1];
      }
      return treeDedupePathPts([a0].concat(mid, [b0]));
    }

    function treeEdgePathPoints(fromNode, toNode, fromSide, toSide) {
      return treeRouteEdgePoints(fromNode, toNode, fromSide, toSide, []);
    }

    function treePointsToPath(pts) {
      if (!pts || !pts.length) return '';
      return pts.map((p, i) => (i === 0 ? 'M' : 'L') + ' ' + p.x + ' ' + p.y).join(' ');
    }

    function treePointsToRoundedPath(pts, radius, hops) {
      if (!pts || !pts.length) return '';
      if (pts.length < 2) return '';
      const r = Math.max(0, Number(radius) || 0);
      const hopW = 9;
      const hopH = 8;
      const n = pts.length;
      const cuts = new Array(n).fill(0);
      if (r >= 0.5 && n > 2) {
        for (let i = 1; i < n - 1; i++) {
          const prev = pts[i - 1];
          const curr = pts[i];
          const next = pts[i + 1];
          const len1 = Math.hypot(curr.x - prev.x, curr.y - prev.y);
          const len2 = Math.hypot(next.x - curr.x, next.y - curr.y);
          if (len1 < 0.01 || len2 < 0.01) continue;
          cuts[i] = Math.min(r, len1 * 0.5, len2 * 0.5);
        }
      }
      const num = (v) => (Math.round(v * 10) / 10);
      let d = 'M ' + num(pts[0].x) + ' ' + num(pts[0].y);
      for (let i = 0; i < n - 1; i++) {
        const a = pts[i];
        const b = pts[i + 1];
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const len = Math.hypot(dx, dy);
        if (len < 0.01) continue;
        const ux = dx / len;
        const uy = dy / len;
        const t0 = i === 0 ? 0 : cuts[i];
        const t1 = i === n - 2 ? len : len - cuts[i + 1];
        if (t1 < t0 + 0.5) {
          if (i < n - 2 && cuts[i + 1] >= 0.5) {
            const curr = b;
            const next = pts[i + 2];
            const v2x = next.x - curr.x;
            const v2y = next.y - curr.y;
            const len2 = Math.hypot(v2x, v2y) || 1;
            const cut = cuts[i + 1];
            d += ' Q ' + num(curr.x) + ' ' + num(curr.y)
              + ' ' + num(curr.x + (v2x / len2) * cut) + ' ' + num(curr.y + (v2y / len2) * cut);
          }
          continue;
        }
        const bumps = [];
        if (hops && hops.length && t1 - t0 > hopW * 2 + 2) {
          for (let h = 0; h < hops.length; h++) {
            const hop = hops[h];
            if (!hop) continue;
            const vx = hop.x - a.x;
            const vy = hop.y - a.y;
            const along = vx * ux + vy * uy;
            const off = Math.abs(vx * uy - vy * ux);
            if (off > 1.6) continue;
            if (along < t0 + hopW + 1 || along > t1 - hopW - 1) continue;
            bumps.push(along);
          }
          bumps.sort((p, q) => p - q);
        }
        const nx = -uy;
        const ny = ux;
        let cursor = t0;
        for (let h = 0; h < bumps.length; h++) {
          const along = bumps[h];
          if (along - hopW < cursor + 0.5) continue;
          const p1x = a.x + ux * (along - hopW);
          const p1y = a.y + uy * (along - hopW);
          const pcx = a.x + ux * along + nx * hopH;
          const pcy = a.y + uy * along + ny * hopH;
          const p2x = a.x + ux * (along + hopW);
          const p2y = a.y + uy * (along + hopW);
          d += ' L ' + num(p1x) + ' ' + num(p1y);
          d += ' Q ' + num(pcx) + ' ' + num(pcy) + ' ' + num(p2x) + ' ' + num(p2y);
          cursor = along + hopW;
        }
        if (i < n - 2 && cuts[i + 1] >= 0.5) {
          const curr = b;
          const next = pts[i + 2];
          const v2x = next.x - curr.x;
          const v2y = next.y - curr.y;
          const len2 = Math.hypot(v2x, v2y) || 1;
          const cut = cuts[i + 1];
          const inX = curr.x - ux * cut;
          const inY = curr.y - uy * cut;
          const outX = curr.x + (v2x / len2) * cut;
          const outY = curr.y + (v2y / len2) * cut;
          d += ' L ' + num(inX) + ' ' + num(inY);
          d += ' Q ' + num(curr.x) + ' ' + num(curr.y) + ' ' + num(outX) + ' ' + num(outY);
        } else {
          d += ' L ' + num(b.x) + ' ' + num(b.y);
        }
      }
      return d;
    }

    function treeArrowHeadPath(tip, back, size) {
      const s = size == null ? 9 : size;
      const dx = tip.x - back.x;
      const dy = tip.y - back.y;
      const len = Math.hypot(dx, dy) || 1;
      const ux = dx / len;
      const uy = dy / len;
      const baseX = tip.x - ux * s;
      const baseY = tip.y - uy * s;
      const px = -uy * s * 0.46;
      const py = ux * s * 0.46;
      return 'M ' + tip.x + ' ' + tip.y
        + ' L ' + (baseX + px) + ' ' + (baseY + py)
        + ' L ' + (baseX - px) + ' ' + (baseY - py)
        + ' Z';
    }

    /** 経路の端を、線に沿って dist だけ縮める（fromStart なら始点側） */
    function treeRetractPolyline(pts, dist, fromStart) {
      if (!pts || pts.length < 2 || !(dist > 0)) return pts ? pts.slice() : [];
      const seq = fromStart ? pts.slice().reverse() : pts.slice();
      let left = dist;
      while (seq.length >= 2 && left > 0.01) {
        const tip = seq[seq.length - 1];
        const prev = seq[seq.length - 2];
        const seg = Math.hypot(tip.x - prev.x, tip.y - prev.y);
        if (seg <= 0.01) {
          seq.pop();
          continue;
        }
        if (seg > left) {
          const t = left / seg;
          seq[seq.length - 1] = {
            x: tip.x - (tip.x - prev.x) * t,
            y: tip.y - (tip.y - prev.y) * t
          };
          left = 0;
        } else {
          seq.pop();
          left -= seg;
        }
      }
      return fromStart ? seq.reverse() : seq;
    }

    function treeEdgePath(fromNode, toNode, fromSide, toSide, opts) {
      opts = opts || {};
      let pts = opts.pts || treeEdgePathPoints(fromNode, toNode, fromSide, toSide);
      const withArrow = opts.arrow !== false;
      if (pts && pts.length >= 2) {
        pts = treeRetractPolyline(pts, TREE_PORT_CLEAR, true);
        pts = treeRetractPolyline(pts, TREE_PORT_CLEAR, false);
      }
      if (!withArrow || !pts || pts.length < 2) return treePointsToRoundedPath(pts, 12, opts.hops);
      const tip = pts[pts.length - 1];
      const prev = pts[pts.length - 2];
      const arrowLen = 9;
      const strokePts = treeRetractPolyline(pts, arrowLen, false);
      return {
        line: treePointsToRoundedPath(strokePts, 12, opts.hops),
        head: treeArrowHeadPath(tip, prev, arrowLen)
      };
    }

    /** 同じ出口から右（または左）へ分かれる線を、1本の縦幹線＋横枝にする */
    function treeFanCompatible(item) {
      const fromC = treeNodeCenter(item.from);
      const toC = treeNodeCenter(item.to);
      if (item.fromSide === 'r' && item.toSide === 'l') return toC.x > fromC.x + 24;
      if (item.fromSide === 'l' && item.toSide === 'r') return toC.x < fromC.x - 24;
      return false;
    }

    function treeFanPath(from, to, fromSide, toSide, busX) {
      const a0 = treePortPoint(from, fromSide);
      const b0 = treePortPoint(to, toSide);
      const a1 = treePortOut(a0, fromSide, TREE_ROUTE_STUB);
      const b1 = treePortOut(b0, toSide, TREE_ROUTE_STUB);
      if (Math.abs(a0.y - b0.y) < 1.5) return treeDedupePathPts([a0, b0]);
      const pts = treeDedupePathPts([
        a0, a1,
        { x: busX, y: a1.y },
        { x: busX, y: b1.y },
        b1, b0
      ]);
      if (treePathIntersectsNodes(pts, [from.id, to.id])) return null;
      return pts;
    }

    function treeFanBusX(from, fromSide, members) {
      const a1 = treePortOut(treePortPoint(from, fromSide), fromSide, TREE_ROUTE_STUB);
      const dir = fromSide === 'r' ? 1 : -1;
      let near = dir > 0 ? Infinity : -Infinity;
      members.forEach((m) => {
        const b1 = treePortOut(treePortPoint(m.to, m.toSide), m.toSide, TREE_ROUTE_STUB);
        if (dir > 0) near = Math.min(near, b1.x);
        else near = Math.max(near, b1.x);
      });
      const room = dir > 0 ? near - a1.x : a1.x - near;
      if (!(room > 16)) return null;
      const candidates = [a1.x + dir * 22, (a1.x + near) / 2, near - dir * 22];
      for (let i = 0; i < candidates.length; i++) {
        const x = candidates[i];
        if (dir > 0 && !(x > a1.x + 6 && x < near - 6)) continue;
        if (dir < 0 && !(x < a1.x - 6 && x > near + 6)) continue;
        const busX = Math.round(x);
        let clear = true;
        for (let m = 0; m < members.length; m++) {
          if (!treeFanPath(from, members[m].to, fromSide, members[m].toSide, busX)) {
            clear = false;
            break;
          }
        }
        if (clear) return busX;
      }
      return null;
    }

    /**
     * すべての接続を順番にルーティングする。
     * 同じノードから同じ側へ分かれる線は1本の幹線にまとめ、
     * それ以外は交差を避けて通す。
     */
    function treeBuildAllEdgeRoutes() {
      if (!treeState) return [];
      const nodeById = new Map(treeState.nodes.map((n) => [n.id, n]));
      const order = new Map((treeState.edges || []).map((e, i) => [e.id, i]));
      const pending = [];
      (treeState.edges || []).forEach((e) => {
        const from = nodeById.get(e.from);
        const to = nodeById.get(e.to);
        if (!from || !to) return;
        const fromSide = treeNormalizeSide(e.fromSide) || 'r';
        const toSide = treeNormalizeSide(e.toSide) || 'l';
        const a = treePortPoint(from, fromSide);
        const b = treePortPoint(to, toSide);
        pending.push({
          edge: e,
          from,
          to,
          fromSide,
          toSide,
          span: Math.abs(a.x - b.x) + Math.abs(a.y - b.y)
        });
      });
      // 短い線から確定させると、長い線が迂回しやすくなる
      pending.sort((p, q) => (p.span - q.span) || ((order.get(p.edge.id) || 0) - (order.get(q.edge.id) || 0)));

      const busPts = new Map();
      const busKeys = new Map();
      const fanGroups = new Map();
      pending.forEach((p) => {
        if (!treeFanCompatible(p)) return;
        const key = String(p.from.id) + '|' + p.fromSide + '|' + p.toSide;
        if (!fanGroups.has(key)) fanGroups.set(key, []);
        fanGroups.get(key).push(p);
      });
      fanGroups.forEach((members, key) => {
        if (members.length < 2) return;
        const busX = treeFanBusX(members[0].from, members[0].fromSide, members);
        if (busX == null) return;
        members.forEach((m) => {
          const pts = treeFanPath(m.from, m.to, m.fromSide, m.toSide, busX);
          if (!pts) return;
          busPts.set(m.edge.id, pts);
          busKeys.set(m.edge.id, key);
        });
      });

      const routes = [];
      const occ = [];
      let clock = 0;
      pending.forEach((p) => {
        let pts = busPts.get(p.edge.id) || null;
        if (!pts && treeFanCompatible(p)) {
          const busX = treeFanBusX(p.from, p.fromSide, [p]);
          if (busX != null) pts = treeFanPath(p.from, p.to, p.fromSide, p.toSide, busX);
        }
        if (!pts) pts = treeRouteEdgePoints(p.from, p.to, p.fromSide, p.toSide, occ);
        const segs = treeRouteOccSegments(pts);
        const fromId = p.from && p.from.id != null ? String(p.from.id) : '';
        const toId = p.to && p.to.id != null ? String(p.to.id) : '';
        segs.forEach((s) => {
          s.fromId = fromId;
          s.toId = toId;
          occ.push(s);
        });
        clock++;
        routes.push({
          edge: p.edge,
          from: p.from,
          to: p.to,
          fromSide: p.fromSide,
          toSide: p.toSide,
          pts,
          segs,
          routedAt: clock,
          changedAt: clock,
          busKey: busKeys.get(p.edge.id) || ''
        });
      });

      // 先に引いた線は後から引いた線を知らない。知らなかった線と関わるときだけ全線を見て引き直し、良くなったら採用する
      for (let pass = 0; pass < TREE_ROUTE_REPASS && routes.length > 1; pass++) {
        let changed = false;
        for (let i = 0; i < routes.length; i++) {
          const r = routes[i];
          if (r.busKey) continue;
          if (!routes.some((o) => o !== r && o.changedAt > r.routedAt)) continue;
          const a1 = treePortOut(treePortPoint(r.from, r.fromSide), r.fromSide, TREE_ROUTE_STUB);
          const b1 = treePortOut(treePortPoint(r.to, r.toSide), r.toSide, TREE_ROUTE_STUB);
          const others = [];
          const unseen = [];
          for (let j = 0; j < routes.length; j++) {
            if (j === i) continue;
            const segs = routes[j].segs;
            const fresh = routes[j].changedAt > r.routedAt;
            for (let k = 0; k < segs.length; k++) {
              others.push(segs[k]);
              if (fresh) unseen.push(segs[k]);
            }
          }
          // 助走部分（接続点の直前直後）は動かせないので、そこでの接触は数えない
          const core = treeRouteTrimmedSegments(r.pts, TREE_ROUTE_STUB);
          const fromId = r.from && r.from.id != null ? String(r.from.id) : '';
          const toId = r.to && r.to.id != null ? String(r.to.id) : '';
          if (!treeRouteHasConflict(core, unseen, a1, b1, fromId, toId)) continue;
          clock++;
          r.routedAt = clock;
          const pts = treeRouteEdgePoints(r.from, r.to, r.fromSide, r.toSide, others);
          if (treePointsToPath(pts) === treePointsToPath(r.pts)) continue;
          if (treeRouteScore(pts, others, a1, b1, fromId, toId) >= treeRouteScore(r.pts, others, a1, b1, fromId, toId) - 1) continue;
          r.pts = pts;
          r.segs = treeRouteOccSegments(pts);
          r.segs.forEach((s) => {
            s.fromId = fromId;
            s.toId = toId;
          });
          r.changedAt = clock;
          changed = true;
        }
        if (!changed) break;
      }
      routes.sort((a, b) => (order.get(a.edge.id) || 0) - (order.get(b.edge.id) || 0));
      treeSpreadSameDirection(routes);
      treeAssignCrossHops(routes);
      treeLastRoutes = routes;
      return routes;
    }

    /** 同じ向きで重なる矢印を、画面上およそ 1.5mm ずつずらす */
    function treeSpreadSameDirection(routes) {
      const gap = 8;
      const groups = new Map();
      const prepared = routes.map((r) => {
        const pts = r.pts || [];
        r.drawPts = pts.map((p) => ({ x: p.x, y: p.y }));
        return { r, pts };
      });
      prepared.forEach((item, ri) => {
        const pts = item.pts;
        for (let i = 0; i < pts.length - 1; i++) {
          const a = pts[i];
          const b = pts[i + 1];
          if (!a || !b) continue;
          const dx = b.x - a.x;
          const dy = b.y - a.y;
          let key = '';
          let lo = 0;
          let hi = 0;
          let horiz = false;
          if (Math.abs(dy) < 0.75 && Math.abs(dx) > 6) {
            horiz = true;
            key = 'h:' + Math.round(a.y) + ':' + (dx > 0 ? 1 : -1);
            lo = Math.min(a.x, b.x);
            hi = Math.max(a.x, b.x);
          } else if (Math.abs(dx) < 0.75 && Math.abs(dy) > 6) {
            key = 'v:' + Math.round(a.x) + ':' + (dy > 0 ? 1 : -1);
            lo = Math.min(a.y, b.y);
            hi = Math.max(a.y, b.y);
          } else continue;
          if (!groups.has(key)) groups.set(key, []);
          groups.get(key).push({ ri, i, lo, hi, horiz });
        }
      });
      groups.forEach((segs) => {
        const byRoute = new Map();
        segs.forEach((s) => {
          if (!byRoute.has(s.ri)) byRoute.set(s.ri, []);
          byRoute.get(s.ri).push(s);
        });
        const ids = Array.from(byRoute.keys());
        if (ids.length < 2) return;
        const overlaps = (a, b) => {
          const ka = prepared[a[0].ri].r.busKey;
          const kb = prepared[b[0].ri].r.busKey;
          if (ka && ka === kb) return false;
          return a.some((s) => b.some((o) => Math.min(s.hi, o.hi) - Math.max(s.lo, o.lo) > 8));
        };
        const colors = new Map();
        const used = [];
        ids.forEach((id) => {
          const mine = byRoute.get(id);
          let color = 0;
          while (used[color] && used[color].some((other) => overlaps(mine, byRoute.get(other)))) color++;
          if (!used[color]) used[color] = [];
          used[color].push(id);
          colors.set(id, color);
        });
        const n = used.length;
        if (n < 2) return;
        const mid = (n - 1) / 2;
        ids.forEach((id) => {
          const offset = (colors.get(id) - mid) * gap;
          if (Math.abs(offset) < 0.01) return;
          const item = prepared[id];
          const orig = item.pts;
          const draw = item.r.drawPts;
          const last = orig.length - 1;
          byRoute.get(id).forEach((s) => {
            [s.i, s.i + 1].forEach((pi) => {
              if (pi <= 0 || pi >= last) return;
              if (s.horiz) draw[pi].y = orig[pi].y + offset;
              else draw[pi].x = orig[pi].x + offset;
            });
          });
        });
      });
    }

    /** 後から引いた線が先の線を横切る点。またぐ側だけ小さなふくらみを付ける */
    function treeAssignCrossHops(routes) {
      const items = [];
      for (let i = 0; i < routes.length; i++) {
        const r = routes[i];
        r.hops = [];
        const segs = [];
        const pts = r.drawPts || r.pts || [];
        for (let k = 0; k < pts.length - 1; k++) {
          const a = pts[k];
          const b = pts[k + 1];
          if (!a || !b) continue;
          const horiz = Math.abs(a.y - b.y) < 0.75;
          const vert = Math.abs(a.x - b.x) < 0.75;
          if (horiz === vert) continue;
          if (Math.hypot(b.x - a.x, b.y - a.y) < 4) continue;
          segs.push({ a, b, horiz });
        }
        items.push({ r, when: r.routedAt || i, segs });
      }
      for (let i = 0; i < items.length; i++) {
        for (let j = i + 1; j < items.length; j++) {
          const over = items[i].when >= items[j].when ? items[i] : items[j];
          const under = over === items[i] ? items[j] : items[i];
          for (let s = 0; s < over.segs.length; s++) {
            const os = over.segs[s];
            for (let t = 0; t < under.segs.length; t++) {
              const us = under.segs[t];
              if (os.horiz === us.horiz) continue;
              const h = os.horiz ? os : us;
              const v = os.horiz ? us : os;
              const x = v.a.x;
              const y = h.a.y;
              const hx0 = Math.min(h.a.x, h.b.x);
              const hx1 = Math.max(h.a.x, h.b.x);
              const vy0 = Math.min(v.a.y, v.b.y);
              const vy1 = Math.max(v.a.y, v.b.y);
              if (x <= hx0 + 3 || x >= hx1 - 3 || y <= vy0 + 3 || y >= vy1 - 3) continue;
              over.r.hops.push({ x, y });
            }
          }
        }
      }
    }

    function treeEdgeIsHighlighted(edgeOrId) {
      const edge = (edgeOrId && edgeOrId.from)
        ? edgeOrId
        : ((treeState && treeState.edges) || []).find((e) => e && e.id === edgeOrId);
      if (!edge) return false;
      if (edge.id === treeSelectedEdgeId) return true;
      if (!treeSelectedNodeId) return false;
      const selected = new Set(treeCollectSelectedNodeIds());
      return selected.has(edge.from) || selected.has(edge.to);
    }

    function treeEdgeSvgHtml(edge, fromNode, toNode, prePts, hops) {
      if (!fromNode || !toNode) return '';
      const isLine = treeNormalizeEdgeStyle(edge.style) === 'line';
      const isDashed = treeNormalizeDashStyle(edge.dashStyle || edge.dashed) === 'dashed';
      const sel = treeEdgeIsHighlighted(edge) ? ' is-selected' : '';
      const dashedCls = isDashed ? ' is-dashed' : '';
      const fromSide = treeNormalizeSide(edge.fromSide) || 'r';
      const toSide = treeNormalizeSide(edge.toSide) || 'l';
      const pathOpts = { pts: prePts, hops: hops || [] };
      if (isLine) {
        const d = treeEdgePath(fromNode, toNode, fromSide, toSide, Object.assign({ arrow: false }, pathOpts));
        return '<g class="tree-edge-group' + sel + ' is-line' + dashedCls + '" data-edge-id="' + edge.id + '">'
          + '<path class="tree-edge' + sel + ' is-line' + dashedCls + '" data-edge-id="' + edge.id + '" d="' + d + '"></path>'
          + '</g>';
      }
      const geo = treeEdgePath(fromNode, toNode, fromSide, toSide, Object.assign({ arrow: true }, pathOpts));
      return '<g class="tree-edge-group' + sel + dashedCls + '" data-edge-id="' + edge.id + '">'
        + '<path class="tree-edge' + sel + dashedCls + '" data-edge-id="' + edge.id + '" d="' + geo.line + '"></path>'
        + '<path class="tree-edge-head" d="' + geo.head + '"></path>'
        + '</g>';
    }

    function treeClearLinkPreview() {
      const prev = document.getElementById('tree-link-preview');
      if (!prev) return;
      prev.classList.add('hidden');
      prev.setAttribute('d', '');
    }

    function treeShowLinkPreview(fromNode, fromSide, toX, toY) {
      const prev = document.getElementById('tree-link-preview');
      if (!prev || !fromNode) return;
      const a0 = treePortPoint(fromNode, fromSide);
      const a1 = treePortOut(a0, fromSide, TREE_ROUTE_STUB);
      const previewPts = treeDedupePathPts([treePortOut(a0, fromSide, TREE_PORT_CLEAR), a1, { x: toX, y: toY }]);
      prev.setAttribute('d', treePointsToRoundedPath(previewPts, 10));
      prev.classList.toggle('is-line', treeGetDrawStyle() === 'line');
      prev.classList.remove('hidden');
    }

    function treeFindEdgeByPort(nodeId, side) {
      if (!treeState || !nodeId) return null;
      side = treeNormalizeSide(side);
      const selected = treeSelectedEdgeId
        ? treeState.edges.find((e) => e.id === treeSelectedEdgeId)
        : null;
      if (selected) {
        if (selected.from === nodeId && (!side || selected.fromSide === side)) return { edge: selected, end: 'from' };
        if (selected.to === nodeId && (!side || selected.toSide === side)) return { edge: selected, end: 'to' };
        if (selected.from === nodeId) return { edge: selected, end: 'from' };
        if (selected.to === nodeId) return { edge: selected, end: 'to' };
      }
      if (!side) return null;
      for (let i = 0; i < treeState.edges.length; i++) {
        const e = treeState.edges[i];
        if (e.from === nodeId && e.fromSide === side) return { edge: e, end: 'from' };
        if (e.to === nodeId && e.toSide === side) return { edge: e, end: 'to' };
      }
      return null;
    }

    function treeApplyEdgeRebind(edgeId, end, nodeId, side) {
      if (!treeState) return false;
      const edge = treeState.edges.find((e) => e.id === edgeId);
      if (!edge) return false;
      side = treeNormalizeSide(side);
      nodeId = String(nodeId || '');
      if (!side || !nodeId) return false;
      const nextFrom = end === 'from' ? nodeId : edge.from;
      const nextTo = end === 'to' ? nodeId : edge.to;
      if (nextFrom === nextTo) {
        setTreeHint('始点と終点に同じノードは指定できません');
        return false;
      }
      const nextFromSide = end === 'from' ? side : edge.fromSide;
      const nextToSide = end === 'to' ? side : edge.toSide;
      treePushUndoSnapshot();
      // 完全に同一（from/to＋両ポート）の別線があるときだけ、そちらに寄せて重複を解消。
      // ポートが違えば別の線として残す（勝手に上書きしない）。
      const dup = treeState.edges.find((e) =>
        e.id !== edge.id && e.from === nextFrom && e.to === nextTo
        && e.fromSide === nextFromSide && e.toSide === nextToSide
      );
      if (dup) {
        treeState.edges = treeState.edges.filter((e) => e.id !== edge.id);
      } else {
        if (end === 'from') {
          edge.from = nodeId;
          edge.fromSide = side;
        } else {
          edge.to = nodeId;
          edge.toSide = side;
        }
      }
      // 確定後は選択を外す。残すと次の点タップがまたつなぎ直しになる。
      treeSelectedEdgeId = null;
      treeClearNodeSelection();
      treePortTap = null;
      treeEdgeRebind = null;
      treeEdgeRebindPending = null;
      scheduleTreeSave();
      renderTree();
      setTreeHint('つなぎ直しました（' + TREE_SIDE_LABEL[side] + '）。次は点どうしで新規接続');
      return true;
    }

    function treeCreateEdge(fromId, fromSide, toId, toSide) {
      if (!treeState || !fromId || !toId || fromId === toId) return false;
      fromSide = treeNormalizeSide(fromSide);
      toSide = treeNormalizeSide(toSide);
      if (!fromSide || !toSide) return false;

      // 完全に同一（from/to＋両ポート）の接続だけ重複扱い。
      // 同じ2ノード間でもポート（辺）が違えば別の線として共存させる
      // （既存の線を上書きしない＝つなぎ直しは線を選択してから行う）。
      const existing = treeState.edges.find((ed) =>
        ed.from === fromId && ed.to === toId
        && ed.fromSide === fromSide && ed.toSide === toSide
      );
      if (existing) {
        setTreeHint('同じ接続はすでにあります');
        // 選択は残さない（次の点がつなぎ直しになるのを防ぐ）
        treeSelectedEdgeId = null;
        renderTree();
        return false;
      }

      const style = treeGetDrawStyle();
      const dashStyle = treeGetDrawDashStyle();
      treePushUndoSnapshot();
      const id = 'e' + Date.now().toString(36) + Math.random().toString(36).slice(2, 4);
      treeState.edges.push({
        id,
        from: fromId,
        to: toId,
        fromSide,
        toSide,
        style,
        dashStyle
      });
      // 確定直後は選択を外す。選択のままだと次の点タップが端のつなぎ直しになってしまう。
      // つなぎ直しは「線をタップして選択 → 端の点を動かす」で行う。
      treeSelectedEdgeId = null;
      treeClearNodeSelection();
      treePortTap = null;
      treeEdgeRebind = null;
      treeEdgeRebindPending = null;
      scheduleTreeSave();
      const isDashed = dashStyle === 'dashed';
      const kindName = style === 'line' ? '線' : '矢印';
      const dashSuffix = isDashed ? '（点線）' : '';
      setTreeHint(style === 'line'
        ? (kindName + dashSuffix + 'を追加（' + TREE_SIDE_LABEL[fromSide] + ' — ' + TREE_SIDE_LABEL[toSide] + '）。次は点どうしで新規接続')
        : (kindName + dashSuffix + 'を追加（' + TREE_SIDE_LABEL[fromSide] + ' → ' + TREE_SIDE_LABEL[toSide] + '）。次は点どうしで新規接続'));
      renderTree();
      return true;
    }

    function treeUpdatePortActiveClass() {
      document.querySelectorAll('.tree-port.is-active').forEach((el) => el.classList.remove('is-active'));
      if (treePortTap) {
        const sel = `.tree-node[data-node-id="${treePortTap.nodeId}"] .tree-port-${treePortTap.side}`;
        const port = document.querySelector(sel);
        if (port) port.classList.add('is-active');
      }
      if (treeEdgeRebind && treeSelectedEdgeId) {
        const edge = treeState.edges.find((e) => e.id === treeSelectedEdgeId);
        if (edge) {
          const nodeId = treeEdgeRebind.end === 'from' ? edge.from : edge.to;
          const side = treeEdgeRebind.end === 'from' ? edge.fromSide : edge.toSide;
          const sel = `.tree-node[data-node-id="${nodeId}"] .tree-port-${side}`;
          const port = document.querySelector(sel);
          if (port) port.classList.add('is-active');
        }
      } else if (treeEdgeRebindPending) {
        const edge = treeState.edges.find((e) => e.id === treeEdgeRebindPending.edgeId);
        if (edge) {
          const nodeId = treeEdgeRebindPending.end === 'from' ? edge.from : edge.to;
          const side = treeEdgeRebindPending.end === 'from' ? edge.fromSide : edge.toSide;
          const sel = `.tree-node[data-node-id="${nodeId}"] .tree-port-${side}`;
          const port = document.querySelector(sel);
          if (port) port.classList.add('is-active');
        }
      }
    }

    function treeNodesForRender() {
      const nodes = treeState && treeState.nodes ? treeState.nodes : [];
      if (nodes.length <= TREE_NODE_VIRTUALIZE_AT) return nodes;
      const vr = treeViewportCellRange();
      const pad = 2;
      return nodes.filter((n) => {
        if (!n) return false;
        if (n.id === treeSelectedNodeId || treeNodeIsSelected(n.id)) return true;
        const lc = treeWorldToLayoutCol(n.col);
        const lr = treeWorldToLayoutRow(n.row);
        return lc >= vr.c0 - pad && lc <= vr.c1 + pad && lr >= vr.r0 - pad && lr <= vr.r1 + pad;
      });
    }

    function renderTree() {
      if (!treeState) return;
      const d = treeDom();
      const stage = d.stage || document.getElementById('tree-stage');
      const railsSvg = d.rails || document.getElementById('tree-rails-svg');
      const edgesG = document.getElementById('tree-edges-g');
      const layer = d.layer || document.getElementById('tree-nodes-layer');
      if (!stage || !railsSvg || !edgesG || !layer) return;

      treeEnsureCanvasBounds({ apply: false });
      treeLastRailsKey = '';

      const size = treeStageSize();
      stage.style.width = size.w + 'px';
      stage.style.height = size.h + 'px';
      layer.style.width = size.w + 'px';
      layer.style.height = size.h + 'px';

      [railsSvg, d.edges || document.getElementById('tree-edges-svg')].forEach((svg) => {
        if (!svg) return;
        svg.setAttribute('width', String(size.w));
        svg.setAttribute('height', String(size.h));
        svg.setAttribute('viewBox', `0 0 ${size.w} ${size.h}`);
        svg.style.width = size.w + 'px';
        svg.style.height = size.h + 'px';
      });

      treeRenderRailsOnly();

      const routes = treeBuildAllEdgeRoutes();
      edgesG.innerHTML = routes.map((r) =>
        treeEdgeSvgHtml(r.edge, r.from, r.to, r.drawPts || r.pts, r.hops)
      ).join('');

      const frag = document.createDocumentFragment();
      const linked = treeLinkedNodeSets();
      treeNodesForRender().forEach((n) => {
        const center = treeNodeCenter(n);
        const nid = String(n.id);
        const el = document.createElement('div');
        el.className = 'tree-node'
          + (treeNodeIsSelected(n.id) ? ' is-selected' : '')
          + (linked.from.has(nid) ? ' is-linked-from' : '')
          + (linked.to.has(nid) ? ' is-linked-to' : '')
          + (n.accent ? ' is-accent' : '');
        el.dataset.nodeId = n.id;
        el.style.left = (center.x - TREE_NODE_W / 2) + 'px';
        el.style.top = (center.y - TREE_NODE_H / 2) + 'px';
        el.style.width = TREE_NODE_W + 'px';
        el.style.height = TREE_NODE_H + 'px';
        el.style.minHeight = TREE_NODE_H + 'px';
        el.style.maxHeight = TREE_NODE_H + 'px';

        const label = document.createElement('span');
        label.className = 'tree-node-label';
        label.textContent = n.label;
        el.appendChild(label);

        TREE_PORT_SIDES.forEach((side) => {
          const port = document.createElement('button');
          port.type = 'button';
          port.className = 'tree-port tree-port-' + side
            + (treePortTap && treePortTap.nodeId === n.id && treePortTap.side === side ? ' is-active' : '');
          port.dataset.side = side;
          port.title = TREE_SIDE_LABEL[side] + 'から矢印';
          port.setAttribute('aria-label', TREE_SIDE_LABEL[side] + 'の接続点');
          el.appendChild(port);
        });

        frag.appendChild(el);
        treeFitNodeLabel(label);
      });
      layer.innerHTML = '';
      layer.appendChild(frag);
      if (treeUiLite) treeApplyZoomTransform({ sizeOnly: true });
      else treeApplyZoomTransform();
      treeUpdateLinkStyleButton();
      treeUpdateHistoryButtons();
      treePaintEdgeMemos();
    }

    function treeFitNodeLabel(labelEl) {
      if (!labelEl) return 14;
      const text = String(labelEl.textContent || '');
      const availW = Math.max(24, TREE_NODE_W - 20);
      const availH = Math.max(24, TREE_NODE_H - 20);
      labelEl.style.width = availW + 'px';
      labelEl.style.maxWidth = availW + 'px';
      labelEl.style.lineHeight = '1.15';
      labelEl.style.whiteSpace = 'normal';
      labelEl.style.wordBreak = 'break-word';
      labelEl.style.overflowWrap = 'anywhere';
      // 文字数から即決（scrollWidth 二分探索は全ノード描画で致命的に重い）
      const len = text.trim().length;
      let best = 16;
      if (!len) best = 16;
      else if (len <= 6) best = 18;
      else if (len <= 10) best = 15;
      else if (len <= 16) best = 13;
      else if (len <= 24) best = 11;
      else if (len <= 36) best = 10;
      else best = 8;
      labelEl.style.fontSize = best + 'px';
      return best;
    }

    /** 操作中用の簡易 L字経路（ダイクストラなし） */
    function treeSimpleEdgePoints(fromNode, toNode, fromSide, toSide) {
      const STUB = TREE_ROUTE_STUB;
      const a0 = treePortPoint(fromNode, fromSide);
      const b0 = treePortPoint(toNode, toSide);
      const a1 = treePortOut(a0, fromSide, STUB);
      const b1 = treePortOut(b0, toSide, STUB);
      const fromH = fromSide === 'l' || fromSide === 'r';
      if (fromH) return treeDedupePathPts([a0, a1, { x: b1.x, y: a1.y }, b1, b0]);
      return treeDedupePathPts([a0, a1, { x: a1.x, y: b1.y }, b1, b0]);
    }

    /** 既存 SVG path を更新。集合が変わったときだけ innerHTML を作り直す */
    function treeApplyRoutesToDom(routes) {
      const edgesG = document.getElementById('tree-edges-g');
      if (!edgesG) return;
      const groups = edgesG.querySelectorAll(':scope > .tree-edge-group');
      const byId = new Map();
      groups.forEach((g) => byId.set(g.getAttribute('data-edge-id'), g));
      let canPatch = groups.length === routes.length;
      if (canPatch) {
        for (let i = 0; i < routes.length; i++) {
          if (!byId.has(routes[i].edge.id)) { canPatch = false; break; }
        }
      }
      if (canPatch) {
        routes.forEach((r) => {
          const g = byId.get(r.edge.id);
          if (!g) return;
          const isLine = treeNormalizeEdgeStyle(r.edge.style) === 'line';
          const isDashed = treeNormalizeDashStyle(r.edge.dashStyle || r.edge.dashed) === 'dashed';
          const sel = treeEdgeIsHighlighted(r.edge);
          g.classList.toggle('is-selected', sel);
          g.classList.toggle('is-line', isLine);
          g.classList.toggle('is-dashed', isDashed);
          if (isLine) {
            const d = treeEdgePath(r.from, r.to, r.fromSide, r.toSide, { arrow: false, pts: r.drawPts || r.pts, hops: r.hops });
            const path = g.querySelector('.tree-edge');
            if (path) {
              path.setAttribute('d', d);
              path.classList.toggle('is-selected', sel);
              path.classList.toggle('is-dashed', isDashed);
              path.classList.add('is-line');
            }
            const head = g.querySelector('.tree-edge-head');
            if (head) head.remove();
          } else {
            const geo = treeEdgePath(r.from, r.to, r.fromSide, r.toSide, { arrow: true, pts: r.drawPts || r.pts, hops: r.hops });
            const path = g.querySelector('.tree-edge');
            if (path) {
              path.setAttribute('d', geo.line);
              path.classList.toggle('is-selected', sel);
              path.classList.toggle('is-dashed', isDashed);
              path.classList.remove('is-line');
            }
            let head = g.querySelector('.tree-edge-head');
            if (!head) {
              head = document.createElementNS('http://www.w3.org/2000/svg', 'path');
              head.setAttribute('class', 'tree-edge-head');
              g.appendChild(head);
            }
            head.setAttribute('d', geo.head);
          }
        });
        routes.forEach((r) => {
          if (!r.hops || !r.hops.length) return;
          const g = byId.get(r.edge.id);
          if (g && g.parentNode) g.parentNode.appendChild(g);
        });
        treePaintEdgeMemos();
        return;
      }
      edgesG.innerHTML = routes.map((r) =>
        treeEdgeSvgHtml(r.edge, r.from, r.to, r.drawPts || r.pts, r.hops)
      ).join('');
      treePaintEdgeMemos();
    }

    function treeRefreshEdgesOnly(opts) {
      opts = opts || {};
      if (!treeState) return;
      const live = opts.live || treeLiveRouting;
      if (live) {
        const nodeById = new Map(treeState.nodes.map((n) => [n.id, n]));
        const routes = [];
        (treeState.edges || []).forEach((e) => {
          const from = nodeById.get(e.from);
          const to = nodeById.get(e.to);
          if (!from || !to) return;
          const fromSide = treeNormalizeSide(e.fromSide) || 'r';
          const toSide = treeNormalizeSide(e.toSide) || 'l';
          routes.push({
            edge: e,
            from,
            to,
            fromSide,
            toSide,
            pts: treeSimpleEdgePoints(from, to, fromSide, toSide)
          });
        });
        treeLastRoutes = routes;
        treeApplyRoutesToDom(routes);
        treeEdgesDirty = true;
        return;
      }
      const routes = treeBuildAllEdgeRoutes();
      treeApplyRoutesToDom(routes);
      treeEdgesDirty = false;
    }

    /** ドラッグ中は毎フレーム1回。live=true なら簡易配線 */
    function treeScheduleEdgeRefresh(live) {
      if (live == null) live = treeLiveRouting;
      if (treeEdgeRefreshRaf) return;
      treeEdgeRefreshRaf = requestAnimationFrame(() => {
        treeEdgeRefreshRaf = 0;
        treeRefreshEdgesOnly({ live: !!live });
      });
    }

    function treeFinalizeEdgesIfDirty() {
      if (!treeEdgesDirty && !treeLiveRouting) return;
      treeLiveRouting = false;
      treeRefreshEdgesOnly({ live: false });
    }

    /** 選択状態だけ DOM に反映（全再描画しない） */
    function treeUpdateSelectionDom() {
      if (!treeEdgeMemoIsOpen(treeSelectedEdgeId)) {
        const pop = document.getElementById('tree-edge-memo-pop');
        if (pop && !pop.classList.contains('hidden')) treeCloseEdgeMemoPop();
      }
      const linked = treeLinkedNodeSets();
      document.querySelectorAll('#tree-nodes-layer .tree-node').forEach((el) => {
        const nid = String(el.dataset.nodeId || '');
        el.classList.toggle('is-selected', treeNodeIsSelected(el.dataset.nodeId));
        el.classList.toggle('is-linked-from', linked.from.has(nid));
        el.classList.toggle('is-linked-to', linked.to.has(nid));
      });
      document.querySelectorAll('#tree-edges-g .tree-edge-group').forEach((g) => {
        const id = g.getAttribute('data-edge-id');
        const sel = treeEdgeIsHighlighted(id);
        g.classList.toggle('is-selected', sel);
        const path = g.querySelector('.tree-edge');
        if (path) path.classList.toggle('is-selected', sel);
      });
      treeUpdatePortActiveClass();
      treeUpdateLinkStyleButton();
      treeRenderRulers();
      treePaintEdgeMemos();
    }

    function treeAddNodeAt(col, row, label, opts) {
      opts = opts || {};
      let historyPushed = false;
      const ensureHistory = () => {
        if (historyPushed) return;
        treePushUndoSnapshot();
        historyPushed = true;
      };
      // col/row は固有ワールド座標
      const occupied = treeNodeAtWorld(col, row);
      if (occupied) {
        if (opts.strict) {
          setTreeHint('この交点にはすでにノードがあります');
          return null;
        }
        let placed = false;
        for (let r = 0; r < treeState.rows && !placed; r++) {
          for (let c = 0; c < treeState.cols && !placed; c++) {
            const wc = treeLayoutToWorldCol(c);
            const wr = treeLayoutToWorldRow(r);
            if (!treeNodeAtWorld(wc, wr)) {
              col = wc; row = wr; placed = true;
            }
          }
        }
        if (!placed) {
          ensureHistory();
          treeEnsureCanvasBounds({
            includeCol: treeState.cols + TREE_EDGE_BUFFER,
            includeRow: 0,
            apply: true,
            rerender: true
          });
          let layoutCol = treeState.cols - TREE_EDGE_BUFFER - 1;
          let layoutRow = 0;
          col = treeLayoutToWorldCol(layoutCol);
          row = treeLayoutToWorldRow(layoutRow);
          while (treeNodeAtWorld(col, row)) {
            layoutRow += 1;
            row = treeLayoutToWorldRow(layoutRow);
            if (layoutRow >= treeState.rows) {
              treeEnsureCanvasBounds({ includeRow: treeState.rows + TREE_EDGE_BUFFER, apply: true, rerender: true });
            }
          }
        }
      } else {
        treeEnsureCanvasBounds({
          includeCol: treeWorldToLayoutCol(col),
          includeRow: treeWorldToLayoutRow(row),
          apply: true,
          rerender: false
        });
      }
      ensureHistory();
      const id = 'n' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5);
      treeState.nodes.push({
        id,
        label: label || '新しいノード',
        col,
        row,
        accent: false
      });
      treeSelectOnlyNode(id);
      treeSelectedEdgeId = null;
      treePortTap = null;
      scheduleTreeSave();
      renderTree();
      setTreeHint('ノード追加。名前を入力（外側クリックまたはEnterで確定）');
      if (opts.edit !== false && (label == null || opts.edit === true)) {
        requestAnimationFrame(() => {
          if (treeFindNode(id)) treeEditNodeLabel(id);
        });
      }
      return id;
    }

    function isTreeMemoDrawerOpen() {
      const mode = document.getElementById('tree-mode');
      return !!(mode && mode.classList.contains('is-memo-open'));
    }

    function openTreeMemoDrawer() {
      if (typeof closeTreeHistoryDrawer === 'function') closeTreeHistoryDrawer();
      if (!isTreeMemoDrawerOpen() && typeof pushAppNavLocation === 'function' && typeof getAppLocationKey === 'function') {
        pushAppNavLocation(getAppLocationKey());
      }
      const mode = document.getElementById('tree-mode');
      const drawer = document.getElementById('tree-memo-drawer');
      const backdrop = document.getElementById('tree-memo-backdrop');
      if (!mode) return;
      mode.classList.add('is-memo-open');
      if (drawer) drawer.setAttribute('aria-hidden', 'false');
      if (backdrop) backdrop.setAttribute('aria-hidden', 'false');
      paintTreeMemoBlocks();
      setTreeHint(treeSelectedEdgeId ? 'ブロックをタップして、選択中の矢印に封入' : 'ブロックをタップしてノード挿入');
    }

    function closeTreeMemoDrawer() {
      const mode = document.getElementById('tree-mode');
      const drawer = document.getElementById('tree-memo-drawer');
      const backdrop = document.getElementById('tree-memo-backdrop');
      if (mode) mode.classList.remove('is-memo-open');
      if (drawer) drawer.setAttribute('aria-hidden', 'true');
      if (backdrop) backdrop.setAttribute('aria-hidden', 'true');
      treeMemoPaintToken += 1;
      if (document.getElementById('tree-mode') && document.getElementById('tree-mode').classList.contains('active')) {
        treeResetInteractionHint();
      }
    }

    function toggleTreeMemoDrawer() {
      if (isTreeMemoDrawerOpen()) closeTreeMemoDrawer();
      else openTreeMemoDrawer();
    }

    function isTreeHistoryDrawerOpen() {
      const mode = document.getElementById('tree-mode');
      return !!(mode && mode.classList.contains('is-history-open'));
    }

    function closeTreeHistoryDrawer() {
      const mode = document.getElementById('tree-mode');
      const drawer = document.getElementById('tree-history-drawer');
      const backdrop = document.getElementById('tree-history-backdrop');
      if (mode) mode.classList.remove('is-history-open');
      if (drawer) drawer.setAttribute('aria-hidden', 'true');
      if (backdrop) backdrop.setAttribute('aria-hidden', 'true');
      treeHistoryLoadToken += 1;
      if (document.getElementById('tree-mode') && document.getElementById('tree-mode').classList.contains('active') && !isTreeMemoDrawerOpen()) {
        treeResetInteractionHint();
      }
    }

    function openTreeHistoryDrawer() {
      closeTreeMemoDrawer();
      const mode = document.getElementById('tree-mode');
      const drawer = document.getElementById('tree-history-drawer');
      const backdrop = document.getElementById('tree-history-backdrop');
      if (!mode) return;
      mode.classList.add('is-history-open');
      if (drawer) drawer.setAttribute('aria-hidden', 'false');
      if (backdrop) backdrop.setAttribute('aria-hidden', 'false');
      paintTreeHistoryList();
      setTreeHint('戻したい時点をタップ');
    }

    function toggleTreeHistoryDrawer() {
      if (isTreeHistoryDrawerOpen()) closeTreeHistoryDrawer();
      else openTreeHistoryDrawer();
    }

    function treeFormatHistoryTime(ms) {
      const d = new Date(ms);
      if (!Number.isFinite(d.getTime())) return '';
      const p = (n) => String(n).padStart(2, '0');
      return (d.getMonth() + 1) + '/' + d.getDate() + ' ' + p(d.getHours()) + ':' + p(d.getMinutes());
    }

    function treeHistoryActiveSummary(lib) {
      const pals = (lib && lib.palettes) || [];
      const active = pals.find((p) => p && p.id === lib.activeId) || pals[0] || null;
      const nodes = active && active.state && Array.isArray(active.state.nodes) ? active.state.nodes.length : 0;
      const edges = active && active.state && Array.isArray(active.state.edges) ? active.state.edges.length : 0;
      const name = active && active.name ? active.name : 'パレット';
      const extra = pals.length > 1 ? ' ほか' + (pals.length - 1) : '';
      return { name, nodes, edges, extra };
    }

    async function treeLoadHistorySnaps() {
      const items = await callAPI('getFolderFileItems', {
        folder: TREE_LIBRARY_FOLDER,
        file: TREE_LIBRARY_FILE
      }, { silent: true });
      if (!Array.isArray(items)) return [];
      const tail = items.slice(-300);
      const parsed = [];
      for (let i = 0; i < tail.length; i++) {
        const snap = parseTreeLibrarySnapshot(tail[i]);
        if (snap && snap.library) parsed.push(snap);
      }
      parsed.sort((a, b) => b.updatedAt - a.updatedAt);
      const seen = new Set();
      const out = [];
      for (let i = 0; i < parsed.length && out.length < 40; i++) {
        const sig = treeLibrarySignature(parsed[i].library);
        if (!sig || seen.has(sig)) continue;
        seen.add(sig);
        out.push(parsed[i]);
      }
      return out;
    }

    function paintTreeHistoryList() {
      const list = document.getElementById('tree-history-list');
      const countEl = document.getElementById('tree-history-count');
      if (!list) return;
      const token = ++treeHistoryLoadToken;
      if (countEl) countEl.textContent = '';
      list.innerHTML = '<div class="tree-memo-empty">読み込み中…</div>';
      treeLoadHistorySnaps().then((snaps) => {
        if (token !== treeHistoryLoadToken) return;
        treeHistorySnaps = snaps || [];
        if (countEl) countEl.textContent = treeHistorySnaps.length ? (treeHistorySnaps.length + '件') : '';
        list.innerHTML = '';
        const note = document.createElement('div');
        note.className = 'tree-history-note';
        note.textContent = '新しい順です。タップすると、その時点のパレットに戻します。';
        list.appendChild(note);
        if (!treeHistorySnaps.length) {
          const empty = document.createElement('div');
          empty.className = 'tree-memo-empty';
          empty.textContent = '履歴がありません';
          list.appendChild(empty);
          return;
        }
        treeHistorySnaps.forEach((snap, index) => {
          const sum = treeHistoryActiveSummary(snap.library);
          const btn = document.createElement('button');
          btn.type = 'button';
          btn.className = 'tree-memo-card';
          const time = document.createElement('div');
          time.className = 'tree-memo-card-time';
          time.textContent = treeFormatHistoryTime(snap.updatedAt);
          const body = document.createElement('div');
          body.className = 'tree-memo-card-body';
          body.style.fontFamily = 'inherit';
          body.style.webkitLineClamp = '2';
          body.textContent = sum.name + sum.extra + ' · ' + sum.nodes + 'ノード · ' + sum.edges + '線';
          btn.appendChild(time);
          btn.appendChild(body);
          btn.addEventListener('click', (e) => {
            e.preventDefault();
            treeRestoreHistorySnapshot(index);
          });
          list.appendChild(btn);
        });
      }).catch(() => {
        if (token !== treeHistoryLoadToken) return;
        list.innerHTML = '<div class="tree-memo-empty">履歴を読めませんでした</div>';
      });
    }

    function treeRestoreHistorySnapshot(index) {
      const snap = treeHistorySnaps[index];
      if (!snap || !snap.library) return;
      const sum = treeHistoryActiveSummary(snap.library);
      const when = treeFormatHistoryTime(snap.updatedAt);
      const ok = window.confirm(when + ' の「' + sum.name + '」（' + sum.nodes + 'ノード）に戻しますか？');
      if (!ok) return;
      const next = normalizeTreeLibraryObject(snap.library);
      if (!next) {
        setTreeHint('この履歴は戻せませんでした');
        return;
      }
      if (treeState) treePushUndoSnapshot();
      treeLibrary = next;
      const pal = treeActivePalette();
      treeState = treeCloneState(pal && pal.state ? pal.state : emptyTreeState());
      treeClearNodeSelection();
      treeSelectedEdgeId = null;
      treePortTap = null;
      treeEdgeRebind = null;
      treeEdgeRebindPending = null;
      treeClearLinkPreview();
      saveTreeState();
      treeRenderPaletteSelect();
      renderTree();
      closeTreeHistoryDrawer();
      setTreeHint('「' + sum.name + '」の ' + when + ' に戻しました');
    }

    function getTreeMemoEntries() {
      if (typeof getCheckBlocksEntries === 'function') {
        try { return getCheckBlocksEntries() || []; } catch (_) { }
      }
      const raw = typeof getLocalInputHistory === 'function' ? (getLocalInputHistory() || []) : [];
      return raw
        .filter((e) => e && String(e.content || '').trim())
        .slice()
        .sort((a, b) => {
          const ta = typeof getSearchTimestampMs === 'function' ? getSearchTimestampMs(a) : new Date(a.timestamp || 0).getTime();
          const tb = typeof getSearchTimestampMs === 'function' ? getSearchTimestampMs(b) : new Date(b.timestamp || 0).getTime();
          return (tb || 0) - (ta || 0);
        });
    }

    function createTreeMemoCard(entry) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'tree-memo-card';
      const time = document.createElement('div');
      time.className = 'tree-memo-card-time';
      time.textContent = typeof formatInputHistoryTime === 'function'
        ? formatInputHistoryTime(entry.timestamp)
        : (entry.timestamp || '');
      const body = document.createElement('div');
      body.className = 'tree-memo-card-body';
      if (typeof setDumpContentDisplay === 'function') setDumpContentDisplay(body, entry.content || '');
      else body.textContent = String(entry.content || '');
      btn.appendChild(time);
      btn.appendChild(body);
      btn.addEventListener('click', (e) => {
        e.preventDefault();
        if (treeSelectedEdgeId) treeEncloseMemoInSelectedEdge(entry);
        else treeInsertMemoAsNode(entry);
      });
      return btn;
    }

    function paintTreeMemoBlocks() {
      const list = document.getElementById('tree-memo-list');
      const countEl = document.getElementById('tree-memo-count');
      if (!list) return;
      const token = ++treeMemoPaintToken;
      const entries = getTreeMemoEntries();
      if (countEl) countEl.textContent = `${entries.length}件`;
      list.innerHTML = '';
      if (treeSelectedEdgeId) {
        const note = document.createElement('div');
        note.className = 'tree-memo-empty';
        note.textContent = '選択中の矢印に封入します';
        list.appendChild(note);
      }
      if (!entries.length) {
        list.innerHTML = '<div class="tree-memo-empty">まだ登録チェックはありません<br><span style="font-size:0.7rem;opacity:0.8">DUMPするとここに表示されます</span></div>';
        return;
      }
      let idx = 0;
      const appendChunk = () => {
        if (token !== treeMemoPaintToken) return;
        const frag = document.createDocumentFragment();
        const end = Math.min(idx + TREE_MEMO_PAINT_CHUNK, entries.length);
        for (; idx < end; idx++) {
          frag.appendChild(createTreeMemoCard(entries[idx]));
        }
        list.appendChild(frag);
        if (idx < entries.length) {
          if (typeof requestIdleCallback === 'function') {
            requestIdleCallback(appendChunk, { timeout: 48 });
          } else {
            setTimeout(appendChunk, 0);
          }
        }
      };
      appendChunk();
    }

    function treeViewportCenterCell() {
      const wrap = document.getElementById('tree-canvas-wrap');
      if (!wrap || !treeState) return { col: 0, row: 0 };
      const zoom = treeGetZoom() || 1;
      const x = (wrap.scrollLeft + Math.max(wrap.clientWidth, 1) / 2) / zoom;
      const y = (wrap.scrollTop + Math.max(wrap.clientHeight, 1) / 2) / zoom;
      let col = Math.round((x - TREE_PAD - TREE_COL_W / 2) / TREE_COL_W);
      let row = Math.round((y - TREE_PAD - TREE_ROW_H / 2) / TREE_ROW_H);
      col = Math.max(0, Math.min(Math.max((treeState.cols || 1) - 1, 0), col));
      row = Math.max(0, Math.min(Math.max((treeState.rows || 1) - 1, 0), row));
      return { col, row };
    }

    function treeMemoLabelFromEntry(entry) {
      const raw = String((entry && entry.content) || '').replace(/\r\n/g, '\n').trim();
      const firstLine = (raw.split('\n')[0] || '').trim();
      const label = (firstLine || 'メモ').slice(0, 40);
      return label || 'メモ';
    }

    function treeEdgeMemoPreview(text) {
      const line = String(text || '').replace(/\s+/g, ' ').trim();
      if (!line) return 'メモ';
      return line.length > 18 ? line.slice(0, 17) + '…' : line;
    }

    function treePolylineMidpoint(pts) {
      if (!pts || pts.length < 2) return null;
      let total = 0;
      const seg = [];
      for (let i = 1; i < pts.length; i++) {
        const len = Math.hypot(pts[i].x - pts[i - 1].x, pts[i].y - pts[i - 1].y);
        seg.push(len);
        total += len;
      }
      if (total < 1) return { x: pts[0].x, y: pts[0].y };
      let remain = total / 2;
      for (let i = 1; i < pts.length; i++) {
        const len = seg[i - 1];
        if (remain <= len || i === pts.length - 1) {
          const t = len > 0 ? Math.max(0, Math.min(1, remain / len)) : 0;
          return {
            x: pts[i - 1].x + (pts[i].x - pts[i - 1].x) * t,
            y: pts[i - 1].y + (pts[i].y - pts[i - 1].y) * t
          };
        }
        remain -= len;
      }
      return { x: pts[0].x, y: pts[0].y };
    }

    function treePaintEdgeMemos() {
      const layer = document.getElementById('tree-edge-memos');
      if (!layer) return;
      layer.innerHTML = '';
      if (!treeState) return;
      const byId = new Map((treeLastRoutes || []).map((r) => [r.edge && r.edge.id, r]));
      (treeState.edges || []).forEach((edge) => {
        if (!edge || !String(edge.memo || '').trim()) return;
        const route = byId.get(edge.id);
        const pts = (route && (route.drawPts || route.pts)) || [];
        const mid = treePolylineMidpoint(pts);
        if (!mid) return;
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'tree-edge-memo' + (edge.id === treeSelectedEdgeId ? ' is-selected' : '');
        btn.dataset.edgeId = edge.id;
        btn.textContent = treeEdgeMemoPreview(edge.memo);
        btn.title = String(edge.memo || '').slice(0, 240);
        btn.style.left = mid.x + 'px';
        btn.style.top = mid.y + 'px';
        btn.addEventListener('pointerdown', (e) => {
          e.stopPropagation();
        });
        btn.addEventListener('click', (e) => {
          e.preventDefault();
          e.stopPropagation();
          treeSelectEdgeById(edge.id);
          treeOpenEdgeMemo(edge.id);
        });
        layer.appendChild(btn);
      });
      treeSyncEdgeMemoPop();
    }

    function treeSyncEdgeMemoPop() {
      const pop = document.getElementById('tree-edge-memo-pop');
      if (!pop || pop.classList.contains('hidden')) return;
      const edge = treeState && (treeState.edges || []).find((e) => e.id === pop.dataset.edgeId);
      const body = document.getElementById('tree-edge-memo-pop-body');
      if (!edge || !String(edge.memo || '').trim() || edge.id !== treeSelectedEdgeId) {
        treeCloseEdgeMemoPop();
        return;
      }
      if (body) body.textContent = edge.memo;
    }

    function treeEdgeMemoIsOpen(edgeId) {
      const pop = document.getElementById('tree-edge-memo-pop');
      return !!(pop && !pop.classList.contains('hidden') && pop.dataset.edgeId === String(edgeId || ''));
    }

    function treeOpenEdgeMemo(edgeId) {
      const edge = treeState && (treeState.edges || []).find((e) => e.id === edgeId);
      const pop = document.getElementById('tree-edge-memo-pop');
      const body = document.getElementById('tree-edge-memo-pop-body');
      if (!pop || !body || !edge || !String(edge.memo || '').trim()) {
        treeCloseEdgeMemoPop();
        return;
      }
      pop.dataset.edgeId = edge.id;
      body.textContent = edge.memo;
      pop.classList.remove('hidden');
    }

    function treeCloseEdgeMemoPop() {
      const pop = document.getElementById('tree-edge-memo-pop');
      if (!pop) return;
      pop.classList.add('hidden');
      delete pop.dataset.edgeId;
    }

    function treeClearSelectedEdgeMemo() {
      const pop = document.getElementById('tree-edge-memo-pop');
      const id = (pop && pop.dataset.edgeId) || treeSelectedEdgeId;
      const edge = treeState && (treeState.edges || []).find((e) => e.id === id);
      if (!edge || !edge.memo) {
        treeCloseEdgeMemoPop();
        return;
      }
      treePushUndoSnapshot();
      delete edge.memo;
      scheduleTreeSave();
      treeCloseEdgeMemoPop();
      treePaintEdgeMemos();
      setTreeHint('矢印のメモを外しました');
    }

    function treeEncloseMemoInSelectedEdge(entry) {
      if (!treeState || !treeSelectedEdgeId) return;
      const edge = (treeState.edges || []).find((e) => e.id === treeSelectedEdgeId);
      if (!edge) return;
      const text = String((entry && entry.content) || '').replace(/\r\n/g, '\n').trim().slice(0, 4000);
      if (!text) {
        setTreeHint('空のメモは封入できません');
        return;
      }
      if (edge.memo && edge.memo !== text && !window.confirm('この矢印に入っているメモを差し替えますか？')) return;
      treePushUndoSnapshot();
      edge.memo = text;
      scheduleTreeSave();
      closeTreeMemoDrawer();
      treePaintEdgeMemos();
      treeOpenEdgeMemo(edge.id);
      setTreeHint('矢印にメモを封入しました');
    }

    function treeInsertMemoAsNode(entry) {
      if (!treeState) {
        setTreeHint('ツリーを開いてから挿入してください');
        return null;
      }
      if (!entry || !String(entry.content || '').trim()) {
        setTreeHint('空のメモは挿入できません');
        return null;
      }
      const cell = treeViewportCenterCell();
      const label = treeMemoLabelFromEntry(entry);
      const id = treeAddNodeAt(cell.col, cell.row, label);
      if (id) setTreeHint('メモを挿入しました');
      return id;
    }

    function treeOnCrossPointerDown(e) {
      // 互換: 交差SVGはもう描かない。空き交点は座標ヒットで処理する
      if (!treeState) return;
      const hit = treeHitEmptyCellAt(e.clientX, e.clientY);
      if (!hit) return;
      e.preventDefault();
      e.stopPropagation();
      treePortTap = null;
      treeClearLinkPreview();
      treeAddNodeAt(hit.col, hit.row, null, { strict: true });
    }

    function treeDeleteSelection() {
      if (!treeState) return;
      if (treeSelectedEdgeId) {
        treePushUndoSnapshot();
        treeCloseEdgeMemoPop();
        treeState.edges = treeState.edges.filter((e) => e.id !== treeSelectedEdgeId);
        treeSelectedEdgeId = null;
        scheduleTreeSave();
        renderTree();
        setTreeHint('矢印を削除しました');
        return;
      }
      const selectedIds = treeCollectSelectedNodeIds();
      if (selectedIds.length) {
        treePushUndoSnapshot();
        const drop = new Set(selectedIds);
        treeState.nodes = treeState.nodes.filter((n) => !drop.has(n.id));
        treeState.edges = treeState.edges.filter((e) => !drop.has(e.from) && !drop.has(e.to));
        if (treePortTap && drop.has(treePortTap.nodeId)) treePortTap = null;
        treeClearNodeSelection();
        scheduleTreeSave();
        renderTree();
        setTreeHint(selectedIds.length > 1 ? selectedIds.length + '件のノードを削除しました' : 'ノードを削除しました');
        return;
      }
      setTreeHint('削除するノードまたは矢印を選んでください');
    }

    function treeToggleAccent() {
      if (!treeSelectedNodeId) {
        setTreeHint('色を変えるノードを選んでください');
        return;
      }
      const n = treeFindNode(treeSelectedNodeId);
      if (!n) return;
      treePushUndoSnapshot();
      n.accent = !n.accent;
      scheduleTreeSave();
      const el = document.querySelector('#tree-nodes-layer .tree-node[data-node-id="' + n.id + '"]');
      if (el) el.classList.toggle('is-accent', !!n.accent);
      else renderTree();
    }

    function treeEditSelectedLabel() {
      if (!treeSelectedNodeId) {
        setTreeHint('先にノードを選んでから「名前編集」を押してください');
        return;
      }
      treeEditNodeLabel(treeSelectedNodeId);
    }

    function closeTreeInlineEdit(save) {
      if (!treeInlineEdit) return true;
      const edit = treeInlineEdit;
      const id = edit.nodeId;
      const n = id ? treeFindNode(id) : null;
      const nodeEl = edit.input && edit.input.parentNode;
      document.removeEventListener('pointerdown', treeOnDocumentPointerDownWhileEdit, true);
      if (save) {
        let label = String((edit.input && edit.input.value) || '').trim().slice(0, 40);
        if (!label) label = (n && n.label) || '新しいノード';
        if (n && n.label !== label) treePushUndoSnapshot();
        if (n) n.label = label;
        treeSelectOnlyNode(id);
        scheduleTreeSave();
        treeInlineEdit = null;
        treeEditTargetId = null;
        renderTree();
        setTreeHint('名前を更新しました');
        treeMaybeSyncAfterIdle();
        return true;
      }
      if (nodeEl && nodeEl.classList) nodeEl.classList.remove('is-editing');
      if (edit.labelEl) {
        edit.labelEl.style.visibility = '';
        edit.labelEl.style.display = '';
      }
      if (edit.input && edit.input.parentNode) edit.input.parentNode.removeChild(edit.input);
      treeInlineEdit = null;
      treeEditTargetId = null;
      treeMaybeSyncAfterIdle();
      return true;
    }

    function treeOnDocumentPointerDownWhileEdit(e) {
      if (!treeInlineEdit) return;
      const input = treeInlineEdit.input;
      if (input && e.target && (e.target === input || (e.target.closest && e.target.closest('.tree-node-edit-input')))) {
        return;
      }
      closeTreeInlineEdit(true);
    }

    function treeEditNodeLabel(nodeId) {
      const n = treeFindNode(nodeId);
      if (!n) return;
      if (!closeTreeInlineEdit(true)) return;
      treeEditTargetId = nodeId;
      treeScrollNodeIntoView(nodeId);
      const nodeEl = document.querySelector(`.tree-node[data-node-id="${nodeId}"]`);
      const labelEl = nodeEl ? nodeEl.querySelector('.tree-node-label') : null;
      if (!nodeEl || !labelEl) return;
      nodeEl.classList.add('is-editing');
      const prevSize = labelEl.style.fontSize || window.getComputedStyle(labelEl).fontSize;
      const input = document.createElement('input');
      input.type = 'text';
      input.maxLength = 40;
      input.className = 'tree-node-edit-input';
      input.value = n.label || '';
      input.style.fontSize = prevSize;
      input.setAttribute('aria-label', 'ノード名を編集');
      const syncEditFit = () => {
        const probe = document.createElement('span');
        probe.className = 'tree-node-label';
        probe.textContent = input.value || ' ';
        probe.style.visibility = 'hidden';
        probe.style.position = 'absolute';
        probe.style.left = '-9999px';
        probe.style.top = '0';
        nodeEl.appendChild(probe);
        const px = treeFitNodeLabel(probe);
        if (probe.parentNode) probe.parentNode.removeChild(probe);
        input.style.setProperty('font-size', px + 'px', 'important');
      };
      input.addEventListener('input', syncEditFit);
      input.addEventListener('keydown', (ev) => {
        if (ev.key === 'Enter') {
          ev.preventDefault();
          ev.stopPropagation();
          closeTreeInlineEdit(true);
        } else if (ev.key === 'Escape') {
          ev.preventDefault();
          ev.stopPropagation();
          closeTreeInlineEdit(false);
        } else {
          ev.stopPropagation();
        }
      });
      input.addEventListener('pointerdown', (ev) => {
        ev.stopPropagation();
      });
      input.addEventListener('blur', () => {
        // 外側クリックは document capture 側でも確定。blur は保険
        if (treeInlineEdit && treeInlineEdit.input === input) {
          closeTreeInlineEdit(true);
        }
      });
      nodeEl.appendChild(input);
      treeInlineEdit = { nodeId, input, labelEl };
      document.addEventListener('pointerdown', treeOnDocumentPointerDownWhileEdit, true);
      syncEditFit();
      requestAnimationFrame(() => {
        input.focus();
        input.select();
      });
      setTreeHint('名前を編集中（外側クリックまたはEnterで確定 / Escでキャンセル）');
    }

    function closeTreeEditModal() {
      closeTreeInlineEdit(false);
      const modal = document.getElementById('tree-edit-modal');
      if (modal) modal.classList.add('hidden');
      treeEditTargetId = null;
    }

    function confirmTreeEditLabel() {
      if (treeInlineEdit) {
        closeTreeInlineEdit(true);
        return;
      }
      const input = document.getElementById('tree-edit-input');
      const id = treeEditTargetId;
      const n = id ? treeFindNode(id) : null;
      if (!n || !input) {
        closeTreeEditModal();
        return;
      }
      const label = String(input.value || '').trim().slice(0, 40);
      if (!label) {
        setTreeHint('名前を入力してください');
        input.focus();
        return;
      }
      n.label = label;
      treeSelectOnlyNode(id);
      closeTreeEditModal();
      scheduleTreeSave();
      renderTree();
      setTreeHint('名前を更新しました');
    }

    function treePortFromPoint(clientX, clientY) {
      const els = (typeof document.elementsFromPoint === 'function')
        ? document.elementsFromPoint(clientX, clientY)
        : [document.elementFromPoint(clientX, clientY)].filter(Boolean);
      for (let i = 0; i < els.length; i++) {
        const el = els[i];
        if (!el || !el.closest) continue;
        const port = el.classList && el.classList.contains('tree-port') ? el : el.closest('.tree-port');
        if (!port) continue;
        const nodeEl = port.closest('.tree-node');
        if (!nodeEl) continue;
        return { nodeId: nodeEl.dataset.nodeId, side: port.dataset.side, port, nodeEl };
      }
      // ズーム・タッチずれ対策: ステージ座標で最寄りポート
      if (!treeState || !treeState.nodes.length) return null;
      const pt = treeClientToStage(clientX, clientY);
      const zoom = treeGetZoom() || 1;
      const threshold = 16 / zoom;
      let best = null;
      let bestDist = threshold;
      for (let i = 0; i < treeState.nodes.length; i++) {
        const n = treeState.nodes[i];
        for (let s = 0; s < TREE_PORT_SIDES.length; s++) {
          const side = TREE_PORT_SIDES[s];
          const p = treePortPoint(n, side);
          const d = Math.hypot(pt.x - p.x, pt.y - p.y);
          if (d < bestDist) {
            bestDist = d;
            const nodeEl = document.querySelector(`.tree-node[data-node-id="${n.id}"]`);
            const port = nodeEl ? nodeEl.querySelector('.tree-port-' + side) : null;
            best = { nodeId: n.id, side, port, nodeEl };
          }
        }
      }
      return best;
    }

    function treeOnPortPointerDown(e) {
      const port = e.target.closest && e.target.closest('.tree-port');
      if (!port || !treeState) return false;
      e.preventDefault();
      e.stopPropagation();
      const nodeEl = port.closest('.tree-node');
      if (!nodeEl) return false;
      const id = nodeEl.dataset.nodeId;
      const side = treeNormalizeSide(port.dataset.side);
      treeDrag = null;
      treeEdgeRebind = null;

      // 端を選んだあとの2点目タップ → 付け替え確定
      if (treeEdgeRebindPending) {
        const ok = treeApplyEdgeRebind(
          treeEdgeRebindPending.edgeId,
          treeEdgeRebindPending.end,
          id,
          side
        );
        treeEdgeRebindPending = null;
        treePortTap = null;
        treeClearLinkPreview();
        if (!ok) treeUpdatePortActiveClass();
        return true;
      }

      // 選択中の線の端ノードの点 → その端のつなぎ直し開始（別の点へドラッグ／タップ）
      if (treeSelectedEdgeId) {
        const selected = treeState.edges.find((ed) => ed.id === treeSelectedEdgeId);
        if (selected) {
          if (selected.from === id || selected.to === id) {
            const end = selected.from === id ? 'from' : 'to';
            // 同じ端の別ポートをタップしたら即付け替え
            if (end === 'from' && selected.fromSide !== side) {
              treeApplyEdgeRebind(selected.id, 'from', id, side);
              treePortTap = null;
              treeClearLinkPreview();
              return true;
            }
            if (end === 'to' && selected.toSide !== side) {
              treeApplyEdgeRebind(selected.id, 'to', id, side);
              treePortTap = null;
              treeClearLinkPreview();
              return true;
            }
            // 今ついている点（または同じ端）からドラッグつなぎ直し
            treePortTap = null;
            treePortLink = null;
            treeEdgeRebindPending = { edgeId: selected.id, end };
            treeEdgeRebind = {
              edgeId: selected.id,
              end,
              pointerId: e.pointerId,
              startX: e.clientX,
              startY: e.clientY,
              moved: false
            };
            treeClearNodeSelection();
            try { port.setPointerCapture(e.pointerId); } catch (_) { }
            treeUpdatePortActiveClass();
            setTreeHint('つなぎ直し: 別の点へドラッグ／タップ');
            return true;
          }
          // 選択中の線がある状態で別ノードの点をタップした場合:
          // 通常は新規接続操作を優先し、Shift時のみ付け替えを実行
          if (e.shiftKey) {
            treeApplyEdgeRebind(selected.id, 'from', id, side);
            treePortTap = null;
            treeClearLinkPreview();
            return true;
          }
          treeSelectedEdgeId = null;
          treeEdgeRebindPending = null;
          treeClearLinkPreview();
        }
      }

      // 点タップは常に「新規追加」扱い（同じ点から複数接続を許可）
      // 付け替え編集は「線を選択してから」行う
      treeSelectedEdgeId = null;
      treeEdgeRebindPending = null;
      treeSelectOnlyNode(id);

      if (treePortTap && (treePortTap.nodeId !== id || treePortTap.side !== side)) {
        treeCreateEdge(treePortTap.nodeId, treePortTap.side, id, side);
        treePortTap = null;
        treeClearLinkPreview();
        return true;
      }

      treePortTap = { nodeId: id, side };
      treePortLink = {
        fromId: id,
        fromSide: side,
        pointerId: e.pointerId,
        startX: e.clientX,
        startY: e.clientY,
        moved: false
      };
      try { port.setPointerCapture(e.pointerId); } catch (_) { }
      treeUpdatePortActiveClass();
      setTreeHint('別ノードの点へドラッグ／タップで接続');
      return true;
    }

    function treeDistPointToSeg(px, py, ax, ay, bx, by) {
      const dx = bx - ax;
      const dy = by - ay;
      const len2 = dx * dx + dy * dy;
      if (len2 < 1e-6) return Math.hypot(px - ax, py - ay);
      let t = ((px - ax) * dx + (py - ay) * dy) / len2;
      t = Math.max(0, Math.min(1, t));
      return Math.hypot(px - (ax + dx * t), py - (ay + dy * t));
    }

    function treeDistToPolyline(pt, pts) {
      if (!pts || pts.length < 2) return Infinity;
      let best = Infinity;
      for (let i = 1; i < pts.length; i++) {
        const d = treeDistPointToSeg(pt.x, pt.y, pts[i - 1].x, pts[i - 1].y, pts[i].x, pts[i].y);
        if (d < best) best = d;
      }
      return best;
    }

    function treeHitEdgeAt(clientX, clientY) {
      if (!treeState || !treeState.edges.length) return null;
      const pt = treeClientToStage(clientX, clientY);
      const zoom = treeGetZoom() || 1;
      const threshold = 12 / zoom;
      let best = null;
      let bestDist = threshold;
      // 描画済みの経路を使う（再ルーティングは重いので行わない）
      const routes = (treeLastRoutes && treeLastRoutes.length)
        ? treeLastRoutes
        : treeBuildAllEdgeRoutes();
      for (let i = 0; i < routes.length; i++) {
        const r = routes[i];
        if (!r || !r.edge) continue;
        const d = treeDistToPolyline(pt, r.pts);
        if (d < bestDist) {
          bestDist = d;
          best = r.edge;
        }
      }
      return best;
    }

    function treeSelectEdgeById(edgeId) {
      if (!edgeId) return;
      treeSelectedEdgeId = edgeId;
      treeClearNodeSelection();
      treePortTap = null;
      treeEdgeRebindPending = null;
      treeClearLinkPreview();
      if (!treeEdgeMemoIsOpen(edgeId)) treeCloseEdgeMemoPop();
      setTreeHint('接続を選択中。端の点を別の点へドラッグ／タップで付け替え（Shiftで始点固定）。メモボタンでこの矢印に封入');
      treeUpdateSelectionDom();
    }

    /** キャンバスのパンを開始する（空き地の左ドラッグ／どこでも右ドラッグ） */
    function treeStartPan(e, button) {
      const wrap = document.getElementById('tree-canvas-wrap');
      if (!wrap) return false;
      treeEnterUiLite();
      treePan = {
        pointerId: e.pointerId,
        startX: e.clientX,
        startY: e.clientY,
        scrollLeft: wrap.scrollLeft,
        scrollTop: wrap.scrollTop,
        moved: false,
        button: button == null ? 0 : button
      };
      try { wrap.setPointerCapture(e.pointerId); } catch (_) { }
      wrap.classList.add('is-panning');
      return true;
    }

    /** ピンチ開始時など、進行中の操作を打ち切る */
    function treeCancelActiveGestures() {
      const wrap = document.getElementById('tree-canvas-wrap');
      if (treePan) {
        treePan = null;
        if (wrap) wrap.classList.remove('is-panning');
      }
      if (treeDrag) {
        const members = treeDrag.members && treeDrag.members.length
          ? treeDrag.members
          : [{ id: treeDrag.id, el: treeDrag.el, originCol: treeDrag.originCol, originRow: treeDrag.originRow }];
        members.forEach((m) => {
          const node = treeFindNode(m.id);
          const el = m.el || document.querySelector(`.tree-node[data-node-id="${m.id}"]`);
          if (node && m.originCol != null && m.originRow != null) {
            node.col = m.originCol;
            node.row = m.originRow;
          }
          if (el) {
            el.classList.remove('is-dragging');
            if (node) treePlaceNodeEl(el, node);
          }
        });
        treeDrag = null;
        treeLiveRouting = false;
        treeFinalizeEdgesIfDirty();
      }
      if (treePortLink) {
        treePortLink = null;
        treeClearLinkPreview();
      }
      if (treeEdgeRebind) {
        treeEdgeRebind = null;
        treeClearLinkPreview();
      }
      treeExitUiLite();
    }

    /**
     * キャプチャ段階で拾う入力:
     * - 右ボタンドラッグ（ノードの上でもキャンバス移動）
     * - 2本指ピンチ（全体の拡大縮小）
     */
    function treeOnCanvasPointerDownCapture(e) {
      if (!treeState) return;
      if (e.pointerType === 'touch') {
        treeTouchPoints.set(e.pointerId, { x: e.clientX, y: e.clientY });
        if (treeTouchPoints.size === 2) {
          const pts = Array.from(treeTouchPoints.values());
          const dist = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y) || 1;
          treeCancelActiveGestures();
          treePinch = { startDist: dist, startZoom: treeGetZoom() };
          e.preventDefault();
          e.stopPropagation();
        }
        return;
      }
      if (e.button === 2 || (e.buttons & 2) === 2) {
        if (treeStartPan(e, 2)) {
          e.preventDefault();
          e.stopPropagation();
        }
      }
    }

    function treeOnCanvasPointerMoveCapture(e) {
      if (e.pointerType !== 'touch') return;
      if (!treeTouchPoints.has(e.pointerId)) return;
      treeTouchPoints.set(e.pointerId, { x: e.clientX, y: e.clientY });
      if (!treePinch || treeTouchPoints.size < 2) return;
      e.preventDefault();
      e.stopPropagation();
      const pts = Array.from(treeTouchPoints.values());
      const dist = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y) || 1;
      const midX = (pts[0].x + pts[1].x) / 2;
      const midY = (pts[0].y + pts[1].y) / 2;
      treeZoomTo(treePinch.startZoom * (dist / treePinch.startDist), midX, midY);
    }

    function treeOnCanvasPointerUpCapture(e) {
      if (e.pointerType !== 'touch') return;
      treeTouchPoints.delete(e.pointerId);
      if (treeTouchPoints.size < 2) {
        if (treePinch) {
          treePinch = null;
          treeScheduleGrowNearEdges();
          treeFlushDeferredSave();
        }
      }
    }

    function treeOnCanvasContextMenu(e) {
      // 右ドラッグ移動を邪魔しないようメニューは出さない
      e.preventDefault();
    }

    function treeOnCanvasPointerDown(e) {
      if (!treeState) return;
      if (treePinch) return;
      if (treePan && treePan.pointerId === e.pointerId) {
        // 右ドラッグは capture 段階で開始済み
        e.preventDefault();
        return;
      }
      const target = e.target;

      if (target.closest && target.closest('.tree-edge-memo')) return;

      // 矢印は pointer-events:none なので、座標ヒットで選択
      if (!(target.closest && (target.closest('.tree-port') || target.closest('.tree-node')))) {
        const hitEdge = treeHitEdgeAt(e.clientX, e.clientY);
        if (hitEdge) {
          e.preventDefault();
          e.stopPropagation();
          treeSelectEdgeById(hitEdge.id);
          return;
        }
      }

      if (target.closest && target.closest('.tree-port')) return;
      if (target.closest && target.closest('.tree-node')) return;
      if (target.closest && target.closest('.tree-edge, .tree-edge-group')) return;

      // 空き交点（座標ヒット）— パン開始より優先
      const empty = treeHitEmptyCellAt(e.clientX, e.clientY);
      if (empty) {
        e.preventDefault();
        e.stopPropagation();
        treePortTap = null;
        treeClearLinkPreview();
        treeAddNodeAt(empty.col, empty.row, null, { strict: true });
        return;
      }

      // 空き地ドラッグでパレットをパン（コマンドバーは固定）
      if (treeStartPan(e, e.button)) e.preventDefault();
    }

    function treeOnCanvasPointerMove(e) {
      if (!treePan || treePan.pointerId !== e.pointerId) return;
      const wrap = treeDom().wrap;
      if (!wrap) return;
      const dx = e.clientX - treePan.startX;
      const dy = e.clientY - treePan.startY;
      if (Math.abs(dx) + Math.abs(dy) > 4) treePan.moved = true;
      if (!treePan.moved) return;
      wrap.scrollLeft = treePan.scrollLeft - dx;
      wrap.scrollTop = treePan.scrollTop - dy;
      treeScheduleRulerScrollSync();
      treeScheduleGrowNearEdges();
      e.preventDefault();
    }

    function treeOnCanvasPointerUp(e) {
      if (!treePan || treePan.pointerId !== e.pointerId) return;
      const wrap = document.getElementById('tree-canvas-wrap');
      const moved = !!treePan.moved;
      const button = treePan.button;
      treePan = null;
      if (wrap) {
        wrap.classList.remove('is-panning');
        try { wrap.releasePointerCapture(e.pointerId); } catch (_) { }
      }
      treeExitUiLite();
      treeFinalizeEdgesIfDirty();
      treeFlushDeferredSave();
      // 右ボタンは移動専用。選択状態には触れない
      if (button === 2) return;
      // ほぼ動かしていないタップは選択解除
      if (!moved) {
        treeClearNodeSelection();
        treeSelectedEdgeId = null;
        treePortTap = null;
        treeEdgeRebindPending = null;
        treeClearLinkPreview();
        treeUpdateSelectionDom();
      }
    }

    function treeOnKeyDown(e) {
      const mode = document.getElementById('tree-mode');
      if (!mode || !mode.classList.contains('active')) return;
      const tag = (e.target && e.target.tagName) ? e.target.tagName.toLowerCase() : '';
      if (tag === 'input' || tag === 'textarea' || (e.target && e.target.isContentEditable)) return;
      if (e.key === 'Escape' && isTreeMemoDrawerOpen()) {
        e.preventDefault();
        closeTreeMemoDrawer();
        return;
      }
      if (e.key === 'Escape' && isTreeHistoryDrawerOpen()) {
        e.preventDefault();
        closeTreeHistoryDrawer();
        return;
      }
      if ((e.ctrlKey || e.metaKey) && !e.altKey && (e.key === 'z' || e.key === 'Z')) {
        e.preventDefault();
        if (e.shiftKey) treeRedo();
        else treeUndo();
        return;
      }
      if ((e.ctrlKey || e.metaKey) && !e.altKey && (e.key === 'y' || e.key === 'Y')) {
        e.preventDefault();
        treeRedo();
        return;
      }
      if (e.key !== 'Delete' && e.key !== 'Backspace') return;
      const modal = document.getElementById('tree-edit-modal');
      if (modal && !modal.classList.contains('hidden')) return;
      if (!treeCollectSelectedNodeIds().length && !treeSelectedEdgeId) return;
      e.preventDefault();
      treeDeleteSelection();
    }

    function treeOnNodePointerDown(e) {
      if (!treeState) return;
      if (e.target && e.target.closest && e.target.closest('.tree-node-edit-input')) return;
      const directPort = e.target.closest && e.target.closest('.tree-port');
      if (directPort) {
        treeOnPortPointerDown(e);
        return;
      }
      const nodeEl = e.target.closest('.tree-node');
      if (!nodeEl) {
        // タッチずれ対策: ノード外タップ時だけ最寄り接続点を補完
        const portHit = treePortFromPoint(e.clientX, e.clientY);
        if (portHit && portHit.port) {
          const fake = {
            preventDefault() { e.preventDefault(); },
            stopPropagation() { e.stopPropagation(); },
            pointerId: e.pointerId,
            clientX: e.clientX,
            clientY: e.clientY,
            target: portHit.port
          };
          treeOnPortPointerDown(fake);
          try { portHit.port.setPointerCapture(e.pointerId); } catch (_) { }
        }
        return;
      }
      e.preventDefault();
      e.stopPropagation();
      const id = nodeEl.dataset.nodeId;
      const n = treeFindNode(id);
      if (!n) return;
      treeSelectedEdgeId = null;
      treePortTap = null;
      treeEdgeRebindPending = null;
      treeClearLinkPreview();
      if (e.ctrlKey || e.metaKey) {
        treeToggleNodeInSelection(id);
        treeLastTap = { id: '', at: 0 };
        treeUpdateSelectionDom();
        const count = treeCollectSelectedNodeIds().length;
        setTreeHint(count ? count + '件を選択中（ドラッグでまとめて移動）' : '選択を解除しました');
        return;
      }
      const selectedIds = treeCollectSelectedNodeIds();
      const keepGroup = selectedIds.length > 1 && selectedIds.indexOf(String(id)) >= 0;
      if (!keepGroup) treeSelectOnlyNode(id);

      const now = Date.now();
      if (treeLastTap.id === id && (now - treeLastTap.at) < 560) {
        treeLastTap = { id: '', at: 0 };
        treeSelectOnlyNode(id);
        treeEditNodeLabel(id);
        return;
      }
      treeLastTap = { id, at: now };

      const memberIds = keepGroup ? selectedIds : [String(id)];
      const anchor = treeNodeCenter(n);
      const members = memberIds.map((mid) => {
        const node = treeFindNode(mid);
        if (!node) return null;
        const center = treeNodeCenter(node);
        return {
          id: String(node.id),
          originCol: node.col,
          originRow: node.row,
          baseX: center.x,
          baseY: center.y,
          el: document.querySelector(`.tree-node[data-node-id="${node.id}"]`)
        };
      }).filter(Boolean);
      treeEnterUiLite();
      treeDrag = {
        id,
        pointerId: e.pointerId,
        startX: e.clientX,
        startY: e.clientY,
        originCol: n.col,
        originRow: n.row,
        anchorX: anchor.x,
        anchorY: anchor.y,
        moved: false,
        beforeState: treeCloneState(treeState),
        el: nodeEl,
        members
      };
      treeLiveRouting = true;
      try { nodeEl.setPointerCapture(e.pointerId); } catch (_) { }
      members.forEach((m) => { if (m.el) m.el.classList.add('is-dragging'); });
      treeSelectedEdgeId = null;
      treeUpdateSelectionDom();
    }

    function treeDragFollowMembers(clientX, clientY) {
      if (!treeDrag) return;
      const pt = treeClientToStage(clientX, clientY);
      const dx = pt.x - (treeDrag.anchorX || pt.x);
      const dy = pt.y - (treeDrag.anchorY || pt.y);
      const members = treeDrag.members && treeDrag.members.length
        ? treeDrag.members
        : [{ el: treeDrag.el, baseX: pt.x, baseY: pt.y }];
      members.forEach((m) => {
        if (!m.el) return;
        const baseX = Number.isFinite(m.baseX) ? m.baseX : pt.x;
        const baseY = Number.isFinite(m.baseY) ? m.baseY : pt.y;
        m.el.style.left = (baseX + dx - TREE_NODE_W / 2 - treeLiteOriginTx) + 'px';
        m.el.style.top = (baseY + dy - TREE_NODE_H / 2 - treeLiteOriginTy) + 'px';
      });
      const pos = treeSnapColRow(clientX, clientY);
      treeDrag.hoverCol = pos.col;
      treeDrag.hoverRow = pos.row;
    }

    /** 選択中のノードを同じマス数だけ動かす。他のノードと重なるときは動かさない */
    function treeMoveNodeGroup(members, dCol, dRow) {
      const list = (members || []).filter((m) => m && treeFindNode(m.id));
      const ids = new Set(list.map((m) => String(m.id)));
      const plans = list.map((m) => {
        const node = treeFindNode(m.id);
        return {
          node,
          el: m.el,
          col: m.originCol + dCol,
          row: m.originRow + dRow,
          originCol: m.originCol,
          originRow: m.originRow
        };
      });
      const restore = () => {
        plans.forEach((p) => {
          p.node.col = p.originCol;
          p.node.row = p.originRow;
          treePlaceNodeEl(p.el || document.querySelector(`.tree-node[data-node-id="${p.node.id}"]`), p.node);
        });
      };
      if (!dCol && !dRow) {
        restore();
        return 'same';
      }
      const blocked = plans.some((p) => (treeState.nodes || []).some((x) =>
        x && !ids.has(String(x.id)) && x.col === p.col && x.row === p.row
      ));
      if (blocked) {
        restore();
        return 'blocked';
      }
      plans.forEach((p) => {
        treeEnsureCanvasBounds({
          includeCol: treeWorldToLayoutCol(p.col),
          includeRow: treeWorldToLayoutRow(p.row),
          apply: true,
          rerender: false,
          skipViewport: true,
          skipRulers: true
        });
      });
      plans.forEach((p) => {
        p.node.col = p.col;
        p.node.row = p.row;
        treePlaceNodeEl(p.el || document.querySelector(`.tree-node[data-node-id="${p.node.id}"]`), p.node);
      });
      return 'moved';
    }

    let treeEdgeScroll = null;
    const TREE_EDGE_SCROLL_ZONE = 64;
    const TREE_EDGE_SCROLL_MIN = 90;
    const TREE_EDGE_SCROLL_MAX = 1000;

    function treeEdgeScrollGesture() {
      if (treeDrag && treeDrag.moved) return true;
      if (treePortLink && treePortLink.moved) return true;
      if (treeEdgeRebind && treeEdgeRebind.moved) return true;
      return false;
    }

    function treeStopEdgeScroll() {
      if (treeEdgeScroll && treeEdgeScroll.raf) cancelAnimationFrame(treeEdgeScroll.raf);
      treeEdgeScroll = null;
    }

    /** 端からの食い込み量 → 速さ（px/秒）。端に近いほど速い */
    function treeEdgeScrollSpeed(depth, zone) {
      if (depth <= 0) return 0;
      const t = Math.min(1, depth / zone);
      return TREE_EDGE_SCROLL_MIN + (TREE_EDGE_SCROLL_MAX - TREE_EDGE_SCROLL_MIN) * t * t;
    }

    /** 1軸ぶんの速さ。lo/hi は掴んでいる物の手前側／奥側の端 */
    function treeEdgeScrollAxis(lo, hi, min, max, zone) {
      const back = (min + zone) - lo;
      const fwd = hi - (max - zone);
      if (back <= 0 && fwd <= 0) return 0;
      return back >= fwd ? -treeEdgeScrollSpeed(back, zone) : treeEdgeScrollSpeed(fwd, zone);
    }

    /** 実際に見えている範囲（画面外・下部ナビの裏は端に数えない） */
    function treeEdgeScrollViewRect(wrap) {
      const r = wrap.getBoundingClientRect();
      const vv = window.visualViewport;
      const vl = vv ? vv.offsetLeft : 0;
      const vt = vv ? vv.offsetTop : 0;
      const vw = vv ? vv.width : window.innerWidth;
      const vh = vv ? vv.height : window.innerHeight;
      const view = {
        left: Math.max(r.left, vl),
        top: Math.max(r.top, vt),
        right: Math.min(r.right, vl + vw),
        bottom: Math.min(r.bottom, vt + vh)
      };
      ['memo-sub-nav', 'app-bottom-nav'].forEach((id) => {
        const nav = document.getElementById(id);
        if (!nav) return;
        const nr = nav.getBoundingClientRect();
        if (nr.width <= 0 || nr.height <= 0) return;
        if (nr.top > view.top + 120 && nr.top < view.bottom) view.bottom = nr.top;
      });
      return view;
    }

    /** ドラッグ中のノード／矢印先を、スクロール後のカーソル位置へ合わせ直す */
    function treeFollowPointerDuringGesture(clientX, clientY) {
      if (treeDrag && treeDrag.moved) {
        if (!treeFindNode(treeDrag.id)) return;
        treeDragFollowMembers(clientX, clientY);
        return;
      }
      if (treePortLink && treePortLink.moved) {
        const from = treeFindNode(treePortLink.fromId);
        if (!from) return;
        const pt = treeClientToStage(clientX, clientY);
        treeShowLinkPreview(from, treePortLink.fromSide, pt.x, pt.y);
        return;
      }
      if (treeEdgeRebind && treeEdgeRebind.moved) {
        const edge = treeState && treeState.edges.find((ed) => ed.id === treeEdgeRebind.edgeId);
        if (!edge) return;
        const fixedId = treeEdgeRebind.end === 'from' ? edge.to : edge.from;
        const fixedSide = treeEdgeRebind.end === 'from' ? edge.toSide : edge.fromSide;
        const fixed = treeFindNode(fixedId);
        if (!fixed) return;
        const pt = treeClientToStage(clientX, clientY);
        treeShowLinkPreview(fixed, fixedSide, pt.x, pt.y);
      }
    }

    /**
     * 画面端に近いほど速くキャンバスを送る。端まで来ていれば余白を足して続ける。
     * ノードは本体の端、矢印は先端（ポインタ）で判定する。
     * @returns {boolean} 次のフレームも続けるか
     */
    function treeApplyEdgeScroll(s, dt) {
      const wrap = treeDom().wrap || document.getElementById('tree-canvas-wrap');
      if (!wrap) return false;
      const view = treeEdgeScrollViewRect(wrap);
      const zone = Math.max(24, Math.min(TREE_EDGE_SCROLL_ZONE, (view.right - view.left) / 5, (view.bottom - view.top) / 5));
      let leadX = 0;
      let leadY = 0;
      if (treeDrag && treeDrag.moved) {
        const zoom = treeGetZoom() || 1;
        leadX = Math.min(96, TREE_NODE_W * zoom / 2);
        leadY = Math.min(96, TREE_NODE_H * zoom / 2);
      }
      const vx = treeEdgeScrollAxis(s.clientX - leadX, s.clientX + leadX, view.left, view.right, zone);
      const vy = treeEdgeScrollAxis(s.clientY - leadY, s.clientY + leadY, view.top, view.bottom, zone);
      if (!vx && !vy) {
        s.accX = 0;
        s.accY = 0;
        return false;
      }
      s.accX = vx ? s.accX + vx * dt : 0;
      s.accY = vy ? s.accY + vy * dt : 0;
      const dx = Math.trunc(s.accX);
      const dy = Math.trunc(s.accY);
      if (!dx && !dy) return true;
      s.accX -= dx;
      s.accY -= dy;
      const beforeL = wrap.scrollLeft;
      const beforeT = wrap.scrollTop;
      if (dx) wrap.scrollLeft = beforeL + dx;
      if (dy) wrap.scrollTop = beforeT + dy;
      const stuckX = !!dx && Math.abs(wrap.scrollLeft - beforeL) < 0.5;
      const stuckY = !!dy && Math.abs(wrap.scrollTop - beforeT) < 0.5;
      if ((stuckX || stuckY) && !s.growBlocked) {
        if (treeGrowNearEdges()) {
          if (stuckX) wrap.scrollLeft += dx;
          if (stuckY) wrap.scrollTop += dy;
        } else {
          s.growBlocked = true;
        }
      }
      const moved = Math.abs(wrap.scrollLeft - beforeL) > 0.5 || Math.abs(wrap.scrollTop - beforeT) > 0.5;
      if (moved) treeFollowPointerDuringGesture(s.clientX, s.clientY);
      return moved;
    }

    function treeEdgeScrollFrame(now) {
      const s = treeEdgeScroll;
      if (!s) return;
      s.raf = 0;
      if (!treeEdgeScrollGesture() || document.hidden) {
        treeEdgeScroll = null;
        return;
      }
      const dt = s.lastAt ? Math.min(0.05, Math.max(0, (now - s.lastAt) / 1000)) : 1 / 60;
      s.lastAt = now;
      if (treeApplyEdgeScroll(s, dt)) s.raf = requestAnimationFrame(treeEdgeScrollFrame);
      else s.lastAt = 0;
    }

    function treeNoteEdgeScrollPointer(clientX, clientY) {
      if (!treeEdgeScrollGesture()) {
        treeStopEdgeScroll();
        return;
      }
      let s = treeEdgeScroll;
      if (!s) {
        s = treeEdgeScroll = { clientX, clientY, raf: 0, lastAt: 0, accX: 0, accY: 0, growBlocked: false };
      } else {
        if (Math.abs(clientX - s.clientX) + Math.abs(clientY - s.clientY) > 2) s.growBlocked = false;
        s.clientX = clientX;
        s.clientY = clientY;
      }
      if (!s.raf) s.raf = requestAnimationFrame(treeEdgeScrollFrame);
    }

    function treeOnNodePointerMove(e) {
      if (treeEdgeRebind && treeEdgeRebind.pointerId === e.pointerId) {
        if (Math.abs(e.clientX - treeEdgeRebind.startX) + Math.abs(e.clientY - treeEdgeRebind.startY) > 6) {
          treeEdgeRebind.moved = true;
        }
        const edge = treeState.edges.find((ed) => ed.id === treeEdgeRebind.edgeId);
        if (!edge) return;
        const fixedId = treeEdgeRebind.end === 'from' ? edge.to : edge.from;
        const fixedSide = treeEdgeRebind.end === 'from' ? edge.toSide : edge.fromSide;
        const fixed = treeFindNode(fixedId);
        if (!fixed) return;
        const pt = treeClientToStage(e.clientX, e.clientY);
        // 固定端からカーソルへプレビュー（向きは見た目用）
        if (treeEdgeRebind.end === 'from') {
          treeShowLinkPreview(fixed, fixedSide, pt.x, pt.y);
        } else {
          treeShowLinkPreview(fixed, fixedSide, pt.x, pt.y);
        }
        treeNoteEdgeScrollPointer(e.clientX, e.clientY);
        return;
      }
      if (treePortLink && treePortLink.pointerId === e.pointerId) {
        if (Math.abs(e.clientX - treePortLink.startX) + Math.abs(e.clientY - treePortLink.startY) > 6) {
          treePortLink.moved = true;
        }
        const from = treeFindNode(treePortLink.fromId);
        if (!from) return;
        const pt = treeClientToStage(e.clientX, e.clientY);
        treeShowLinkPreview(from, treePortLink.fromSide, pt.x, pt.y);
        treeNoteEdgeScrollPointer(e.clientX, e.clientY);
        return;
      }
      if (!treeDrag || treeDrag.pointerId !== e.pointerId) return;
      const n = treeFindNode(treeDrag.id);
      if (!n) return;
      if (Math.abs(e.clientX - treeDrag.startX) + Math.abs(e.clientY - treeDrag.startY) > 6) {
        treeDrag.moved = true;
      }
      if (!treeDrag.moved) return;
      treeDragFollowMembers(e.clientX, e.clientY);
      treeNoteEdgeScrollPointer(e.clientX, e.clientY);
    }

    function treeOnNodePointerUp(e) {
      treeStopEdgeScroll();
      if (treeEdgeRebind && treeEdgeRebind.pointerId === e.pointerId) {
        const reb = treeEdgeRebind;
        treeEdgeRebind = null;
        treeClearLinkPreview();
        try {
          const portEl = e.target.closest && e.target.closest('.tree-port');
          if (portEl) portEl.releasePointerCapture(e.pointerId);
        } catch (_) { }
        const hit = treePortFromPoint(e.clientX, e.clientY);
        if (hit) {
          const sameStart = (() => {
            const edge = treeState.edges.find((ed) => ed.id === reb.edgeId);
            if (!edge) return false;
            const startId = reb.end === 'from' ? edge.from : edge.to;
            const startSide = reb.end === 'from' ? edge.fromSide : edge.toSide;
            return hit.nodeId === startId && treeNormalizeSide(hit.side) === startSide;
          })();
          if (!sameStart) {
            treeApplyEdgeRebind(reb.edgeId, reb.end, hit.nodeId, hit.side);
            return;
          }
        }
        if (reb.moved) {
          treeEdgeRebindPending = null;
          setTreeHint('つなぎ直しをキャンセルしました');
        } else {
          treeEdgeRebindPending = { edgeId: reb.edgeId, end: reb.end };
          setTreeHint('付け替え先の点をタップ（またはドラッグ）');
        }
        treeUpdatePortActiveClass();
        renderTree();
        return;
      }

      if (treePortLink && treePortLink.pointerId === e.pointerId) {
        const link = treePortLink;
        treePortLink = null;
        treeClearLinkPreview();
        try {
          const portEl = e.target.closest && e.target.closest('.tree-port');
          if (portEl) portEl.releasePointerCapture(e.pointerId);
        } catch (_) { }

        const hit = treePortFromPoint(e.clientX, e.clientY);
        if (hit && (hit.nodeId !== link.fromId || hit.side !== link.fromSide)) {
          treeCreateEdge(link.fromId, link.fromSide, hit.nodeId, hit.side);
          treePortTap = null;
          return;
        }
        if (link.moved) {
          // ドラッグしたが着地できず → 始点キャンセル
          treePortTap = null;
          treeUpdatePortActiveClass();
          setTreeHint('接続をキャンセルしました');
          return;
        }
        // タップ: 始点を保持（次の点タップで接続）
        treePortTap = { nodeId: link.fromId, side: link.fromSide };
        treeUpdatePortActiveClass();
        setTreeHint('終点の点をタップしてください');
        return;
      }

      if (!treeDrag || treeDrag.pointerId !== e.pointerId) return;
      const nodeEl = treeDrag.el || (e.target.closest && e.target.closest('.tree-node'));
      const members = treeDrag.members && treeDrag.members.length
        ? treeDrag.members
        : [{ id: treeDrag.id, el: nodeEl, originCol: treeDrag.originCol, originRow: treeDrag.originRow }];
      if (nodeEl) {
        try { nodeEl.releasePointerCapture(e.pointerId); } catch (_) { }
      }
      members.forEach((m) => {
        const el = m.el || document.querySelector(`.tree-node[data-node-id="${m.id}"]`);
        if (el) el.classList.remove('is-dragging');
        m.el = el;
      });
      const moved = !!treeDrag.moved;
      const beforeState = treeDrag.beforeState ? treeCloneState(treeDrag.beforeState) : null;
      const originCol = treeDrag.originCol;
      const originRow = treeDrag.originRow;
      const hoverCol = treeDrag.hoverCol;
      const hoverRow = treeDrag.hoverRow;
      const dragId = treeDrag.id;
      treeDrag = null;
      treeLiveRouting = false;

      const n = treeFindNode(dragId);
      if (moved && n) {
        const pos = (hoverCol != null && hoverRow != null)
          ? { col: hoverCol, row: hoverRow }
          : treeSnapColRow(e.clientX, e.clientY);
        if (members.length > 1) {
          const result = treeMoveNodeGroup(members, pos.col - originCol, pos.row - originRow);
          if (result === 'moved' && beforeState) treePushUndoSnapshot(beforeState);
          treeExitUiLite();
          treeFinalizeEdgesIfDirty();
          if (result === 'moved') treeFlushDeferredSave();
          if (result === 'blocked') setTreeHint('重なる場所があるため移動できません');
          else if (result === 'moved') setTreeHint(members.length + '件のノードを移動しました');
          return;
        }
        if (pos.col === originCol && pos.row === originRow) {
          n.col = originCol;
          n.row = originRow;
          treePlaceNodeEl(nodeEl || document.querySelector(`.tree-node[data-node-id="${n.id}"]`), n);
          treeExitUiLite();
          treeFinalizeEdgesIfDirty();
          return;
        }
        const other = treeState.nodes.find((x) => x.id !== n.id && x.col === pos.col && x.row === pos.row);
        if (other) {
          // ドロップ時だけ入れ替え（ドラッグ中は他ノードを動かさない）
          other.col = originCol;
          other.row = originRow;
          const otherEl = document.querySelector(`.tree-node[data-node-id="${other.id}"]`);
          treePlaceNodeEl(otherEl, other);
        }
        n.col = pos.col;
        n.row = pos.row;
        treePlaceNodeEl(nodeEl || document.querySelector(`.tree-node[data-node-id="${n.id}"]`), n);
        if (beforeState) treePushUndoSnapshot(beforeState);
        treeExitUiLite();
        treeFinalizeEdgesIfDirty();
        treeFlushDeferredSave();
        setTreeHint(other ? 'ノードを入れ替えました' : 'ノードを移動しました');
        return;
      }
      if (n) {
        treePlaceNodeEl(nodeEl || document.querySelector(`.tree-node[data-node-id="${n.id}"]`), n);
      }
      if (!moved && members.length > 1) {
        treeSelectOnlyNode(dragId);
        treeUpdateSelectionDom();
      }
      treeExitUiLite();
      treeFinalizeEdgesIfDirty();
    }

    function treeOnEdgeClick(e) {
      // 互換: 直接クリックが来た場合
      const path = e.target.closest && e.target.closest('.tree-edge, .tree-edge-group');
      if (!path || path.id === 'tree-link-preview') return;
      e.stopPropagation();
      const id = path.getAttribute('data-edge-id');
      if (id) treeSelectEdgeById(id);
    }

    function bindTreeEvents() {
      if (treeBound) return;
      const wrap = document.getElementById('tree-canvas-wrap');
      const layer = document.getElementById('tree-nodes-layer');
      const edgesG = document.getElementById('tree-edges-g');
      const railsSvg = document.getElementById('tree-rails-svg');
      const editInput = document.getElementById('tree-edit-input');
      if (!wrap || !layer || !edgesG) return;
      const board = document.getElementById('tree-board');
      if (board) {
        board.addEventListener('click', (e) => {
          const btn = e.target.closest && e.target.closest('.tree-ruler-label');
          if (!btn || !board.contains(btn)) return;
          e.preventDefault();
          e.stopPropagation();
          treeRenameLane(btn.dataset.axis, Number(btn.dataset.index));
        });
      }
      wrap.addEventListener('pointerdown', treeOnCanvasPointerDownCapture, true);
      wrap.addEventListener('pointermove', treeOnCanvasPointerMoveCapture, true);
      wrap.addEventListener('pointerup', treeOnCanvasPointerUpCapture, true);
      wrap.addEventListener('pointercancel', treeOnCanvasPointerUpCapture, true);
      wrap.addEventListener('pointerdown', treeOnCanvasPointerDown);
      wrap.addEventListener('pointermove', treeOnCanvasPointerMove);
      wrap.addEventListener('pointerup', treeOnCanvasPointerUp);
      wrap.addEventListener('pointercancel', treeOnCanvasPointerUp);
      wrap.addEventListener('wheel', treeOnCanvasWheel, { passive: false });
      wrap.addEventListener('contextmenu', treeOnCanvasContextMenu);
      wrap.addEventListener('scroll', () => {
        treeScheduleGrowNearEdges();
        if (treeUiLite || treeIsInteractBusy()) {
          treeScheduleRulerScrollSync();
        } else {
          treeScheduleRailsRefresh();
        }
      }, { passive: true });
      layer.addEventListener('pointerdown', treeOnNodePointerDown);
      layer.addEventListener('pointermove', treeOnNodePointerMove);
      layer.addEventListener('pointerup', treeOnNodePointerUp);
      layer.addEventListener('pointercancel', treeOnNodePointerUp);
      edgesG.addEventListener('click', treeOnEdgeClick);
      document.addEventListener('keydown', treeOnKeyDown);
      if (editInput) {
        editInput.addEventListener('keydown', (ev) => {
          if (ev.key === 'Enter') {
            ev.preventDefault();
            confirmTreeEditLabel();
          } else if (ev.key === 'Escape') {
            ev.preventDefault();
            closeTreeEditModal();
          }
        });
      }
      treeBound = true;
    }

    function initTreeMode() {
      treeState = loadTreeState();
      treeResetHistory();
      if (!treeState.linkStyle) treeState.linkStyle = 'arrow';
      if (!treeState.dashStyle) treeState.dashStyle = 'solid';
      if (treeState.zoom == null) treeState.zoom = 1;
      treeRenderPaletteSelect();
      bindTreeEvents();
      // 端末内データを先に描画し、クラウド同期完了後に差し替える
      renderTree();
      treeOpenAtOrigin();
      treeUpdateLinkStyleButton();
      if (typeof startTreeLibraryPoll === 'function') startTreeLibraryPoll();
      const gen = ++treeInitSyncGen;
      setTreeHint('クラウドと同期中…');
      const sync = (typeof syncTreeLibrary === 'function')
        ? syncTreeLibrary({ render: true })
        : Promise.resolve();
      sync.then(() => {
        if (gen !== treeInitSyncGen) return;
        treeOpenAtOrigin();
        treeResetInteractionHint();
      }).catch(() => {
        if (gen !== treeInitSyncGen) return;
        setTreeHint('同期に失敗したため端末内データを表示中');
      });
    }

    // ========== QRカメラ ==========
    let qrStream = null;
    let qrRafId = 0;
    let qrDetector = null;
    let qrJsQRReady = false;
    let qrJsQRLoading = null;
    let qrLastRaw = '';
    let qrLastAt = 0;
    let qrCooldownUntil = 0;
    let qrTorchOn = false;
    let qrRunning = false;
    let qrStartSeq = 0;
    const QR_AUTO_OPEN_KEY = 'setting_qr_auto_open';
    const QR_COOLDOWN_MS = 2800;
    const QR_DUP_MS = 4500;

    function isQrAutoOpenEnabled() {
      try {
        return localStorage.getItem(QR_AUTO_OPEN_KEY) === 'true';
      } catch (_) {
        return false;
      }
    }

    function setQrAutoOpenEnabled(enabled) {
      try {
        localStorage.setItem(QR_AUTO_OPEN_KEY, enabled ? 'true' : 'false');
      } catch (_) { }
    }

    function syncQrAutoOpenToggle() {
      const toggle = document.getElementById('qr-auto-open-toggle');
      if (toggle) toggle.checked = isQrAutoOpenEnabled();
    }

    function setQrStatus(text) {
      const el = document.getElementById('qr-status');
      if (el) el.textContent = text || '';
    }

    function setQrLastDisplay(text) {
      const el = document.getElementById('qr-last');
      if (el) el.textContent = text || 'まだ読み取り結果がありません';
      const url = text ? normalizeQrOpenTarget(text) : null;
      const openBtn = document.getElementById('qr-open-last-btn');
      if (openBtn) openBtn.disabled = !url;
      const copyBtn = document.getElementById('qr-copy-last-btn');
      if (copyBtn) copyBtn.disabled = !text;
      const dumpBtn = document.getElementById('qr-dump-last-btn');
      if (dumpBtn) dumpBtn.disabled = !text;
    }

    function normalizeQrOpenTarget(raw) {
      const text = String(raw || '').trim();
      if (!text) return null;
      if (/^(https?:|mailto:|tel:|sms:|geo:)/i.test(text)) return text;
      if (/^www\./i.test(text)) return 'https://' + text;
      // domain.tld/... or domain.tld
      if (/^[a-z0-9][a-z0-9.-]+\.[a-z]{2,}([/:?#].*)?$/i.test(text) && !/\s/.test(text)) {
        return 'https://' + text;
      }
      return null;
    }

    function openQrTarget(raw, opts) {
      opts = opts || {};
      const text = String(raw || '').trim();
      if (!text) return false;
      setQrLastDisplay(text);
      const url = normalizeQrOpenTarget(text);
      if (url) {
        if (!opts.reopen && !isQrAutoOpenEnabled()) {
          setQrStatus('URLを読み取りました（下の「🔗 開く」または「📥 INBOXへDUMP」を選べます）');
          return false;
        }
        setQrStatus(opts.reopen ? '新しいタブで開いています…' : '読み取り → 開いています');
        try {
          const opened = window.open(url, '_blank', 'noopener,noreferrer');
          if (!opened) {
            setQrStatus('ポップアップがブロックされました。下の「🔗 開く」を押してください');
            return false;
          }
        } catch (e) {
          setQrStatus('URLを開けませんでした。下の「🔗 開く」または「📋 コピー」をお使いください');
          return false;
        }
        return true;
      }
      setQrStatus('テキストを読み取りました（コピー・INBOX保存できます）');
      return false;
    }

    function handleQrDecode(raw) {
      const text = String(raw || '').trim();
      if (!text) return;
      const now = Date.now();
      if (now < qrCooldownUntil) return;
      if (text === qrLastRaw && (now - qrLastAt) < QR_DUP_MS) return;
      qrLastRaw = text;
      qrLastAt = now;
      qrCooldownUntil = now + QR_COOLDOWN_MS;
      try {
        if (navigator.vibrate) navigator.vibrate(40);
      } catch (_) { }
      const frame = document.getElementById('qr-scan-frame');
      if (frame) {
        frame.style.borderColor = 'rgba(52, 211, 153, 0.95)';
        setTimeout(() => { frame.style.borderColor = ''; }, 700);
      }
      openQrTarget(text);
    }

    function openLastQrResult() {
      if (!qrLastRaw) return;
      qrCooldownUntil = 0;
      openQrTarget(qrLastRaw, { reopen: true });
    }

    async function copyLastQrResult() {
      if (!qrLastRaw) return;
      try {
        if (navigator.clipboard && navigator.clipboard.writeText) {
          await navigator.clipboard.writeText(qrLastRaw);
        } else {
          const ta = document.createElement('textarea');
          ta.value = qrLastRaw;
          ta.style.cssText = 'position:fixed;opacity:0;';
          document.body.appendChild(ta);
          ta.select();
          document.execCommand('copy');
          document.body.removeChild(ta);
        }
        setQrStatus('📋 クリップボードにコピーしました');
      } catch (_) {
        setQrStatus('コピーに失敗しました');
      }
    }

    function dumpLastQrToInbox() {
      const text = String(qrLastRaw || '').trim();
      if (!text) return;
      try {
        if (typeof appendLocalInputHistory === 'function') {
          appendLocalInputHistory([text], 'INBOX', '未整理');
        }
        if (typeof rememberDumpedItems === 'function' && typeof makeTempId === 'function') {
          rememberDumpedItems([{
            id: makeTempId(),
            content: text,
            timestamp: new Date().toISOString(),
            folder: '📥 INBOX',
            file: '未整理',
            isInbox: true,
            _pending: true
          }]);
        }
        if (typeof bumpBadgeOptimistic === 'function') bumpBadgeOptimistic(1);
        const historyId = typeof logOperation === 'function'
          ? logOperation('ADD', 'QRから 1件を INBOX に追加', { folder: 'INBOX', file: '未整理', contents: [text] })
          : '';
        if (typeof addPendingInboxWrite === 'function' && typeof enqueueInboxWrite === 'function') {
          const dumpJob = {
            id: makePendingWriteId(),
            type: 'dump_add',
            addedChunks: [text],
            replaceDupChunks: [],
            destFolder: 'INBOX',
            destFile: '未整理',
            isInboxDest: true,
            directFolder: '',
            historyId,
            pendingReplaceId: ''
          };
          addPendingInboxWrite(dumpJob);
          markPendingWriteQueued(dumpJob.id);
          enqueueInboxWrite(async () => {
            pendingWriteRunningIds.add(dumpJob.id);
            try {
              await executeDumpAddJob(dumpJob);
              removePendingInboxWrite(dumpJob.id);
              setQrStatus('✅ INBOXへDUMPしました');
            } catch (err) {
              if (typeof handlePendingWriteError === 'function') {
                handlePendingWriteError(dumpJob, err);
              }
              setQrStatus('⚠️ 端末に記録しました（後で自動再送されます）');
            } finally {
              pendingWriteRunningIds.delete(dumpJob.id);
            }
          });
          setQrStatus('📥 INBOXへ保存を受け付けました');
          return;
        }
        callAPI('addInbox', { content: text }, { silent: true }).then((res) => {
          if (res && res.success) setQrStatus('✅ INBOXへDUMPしました');
          else setQrStatus('⚠️ INBOX保存に失敗しました');
        });
      } catch (e) {
        console.warn('dumpLastQrToInbox failed', e);
        setQrStatus('⚠️ INBOX保存に失敗しました');
      }
    }

    function loadJsQRLibrary() {
      if (qrJsQRReady || (typeof jsQR === 'function')) {
        qrJsQRReady = true;
        return Promise.resolve();
      }
      if (qrJsQRLoading) return qrJsQRLoading;
      qrJsQRLoading = new Promise((resolve, reject) => {
        const s = document.createElement('script');
        s.src = 'https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.min.js';
        s.async = true;
        s.onload = () => {
          qrJsQRReady = typeof jsQR === 'function';
          if (qrJsQRReady) {
            resolve();
          } else {
            qrJsQRLoading = null;
            if (s.parentNode) s.parentNode.removeChild(s);
            reject(new Error('jsQR load failed'));
          }
        };
        s.onerror = () => {
          qrJsQRLoading = null;
          if (s.parentNode) s.parentNode.removeChild(s);
          reject(new Error('jsQR network error'));
        };
        document.head.appendChild(s);
      });
      return qrJsQRLoading;
    }

    async function ensureQrDetector() {
      if (typeof BarcodeDetector === 'function') {
        try {
          const formats = await BarcodeDetector.getSupportedFormats();
          if (formats && formats.includes('qr_code')) {
            qrDetector = new BarcodeDetector({ formats: ['qr_code'] });
            return 'native';
          }
        } catch (_) { }
      }
      await loadJsQRLibrary();
      return 'jsqr';
    }

    function stopQrScanLoop() {
      if (qrRafId) {
        cancelAnimationFrame(qrRafId);
        qrRafId = 0;
      }
    }

    function qrScanTickNative() {
      if (!qrRunning || !qrDetector) return;
      const video = document.getElementById('qr-video');
      if (!video || video.readyState < 2) {
        qrRafId = requestAnimationFrame(qrScanTickNative);
        return;
      }
      qrDetector.detect(video).then((codes) => {
        if (codes && codes.length) {
          const raw = codes[0].rawValue || '';
          if (raw) handleQrDecode(raw);
        }
      }).catch(() => { }).finally(() => {
        if (qrRunning) qrRafId = requestAnimationFrame(qrScanTickNative);
      });
    }

    function qrScanTickJsQR() {
      if (!qrRunning || typeof jsQR !== 'function') return;
      const video = document.getElementById('qr-video');
      if (!video || video.readyState < 2) {
        qrRafId = requestAnimationFrame(qrScanTickJsQR);
        return;
      }
      const w = video.videoWidth;
      const h = video.videoHeight;
      if (w && h) {
        let canvas = document.getElementById('qr-scan-canvas');
        if (!canvas) {
          canvas = document.createElement('canvas');
          canvas.id = 'qr-scan-canvas';
          canvas.width = w;
          canvas.height = h;
          canvas.className = 'hidden';
          document.body.appendChild(canvas);
        }
        if (canvas.width !== w) canvas.width = w;
        if (canvas.height !== h) canvas.height = h;
        const ctx = canvas.getContext('2d', { willReadFrequently: true });
        ctx.drawImage(video, 0, 0, w, h);
        const imageData = ctx.getImageData(0, 0, w, h);
        const code = jsQR(imageData.data, w, h, { inversionAttempts: 'dontInvert' });
        if (code && code.data) handleQrDecode(code.data);
      }
      qrRafId = requestAnimationFrame(qrScanTickJsQR);
    }

    async function updateQrTorchButton() {
      const btn = document.getElementById('qr-torch-btn');
      if (!btn) return;
      const track = qrStream && qrStream.getVideoTracks()[0];
      const caps = track && typeof track.getCapabilities === 'function' ? track.getCapabilities() : null;
      if (caps && caps.torch) {
        btn.classList.remove('hidden');
        btn.textContent = qrTorchOn ? 'ライトOFF' : 'ライトON';
      } else {
        btn.classList.add('hidden');
        qrTorchOn = false;
      }
    }

    async function toggleQrTorch() {
      const track = qrStream && qrStream.getVideoTracks()[0];
      if (!track || typeof track.applyConstraints !== 'function') return;
      try {
        qrTorchOn = !qrTorchOn;
        await track.applyConstraints({ advanced: [{ torch: qrTorchOn }] });
        await updateQrTorchButton();
      } catch (e) {
        qrTorchOn = false;
        setQrStatus('ライトを使えませんでした');
        await updateQrTorchButton();
      }
    }

    async function startQrScanner() {
      syncQrAutoOpenToggle();
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        setQrStatus('この環境ではカメラを使えません（HTTPSが必要な場合があります）');
        return;
      }
      if (qrRunning && qrStream) {
        setQrStatus('スキャン中… 枠内にQRを合わせてください');
        return;
      }
      const seq = ++qrStartSeq;
      stopQrScanLoop();
      setQrStatus('カメラを起動しています…');
      try {
        if (qrStream) {
          qrStream.getTracks().forEach((t) => t.stop());
          qrStream = null;
        }
        const stream = await navigator.mediaDevices.getUserMedia({
          audio: false,
          video: {
            facingMode: { ideal: 'environment' },
            width: { ideal: 1280 },
            height: { ideal: 720 }
          }
        });
        const isStillQrTab = () => {
          const qrEl = document.getElementById('qr-mode');
          return !!(qrEl && qrEl.classList.contains('active'));
        };
        if (seq !== qrStartSeq || !isStillQrTab()) {
          try { stream.getTracks().forEach((t) => t.stop()); } catch (_) { }
          return;
        }
        qrStream = stream;
        const video = document.getElementById('qr-video');
        if (!video) {
          try { stream.getTracks().forEach((t) => t.stop()); } catch (_) { }
          qrStream = null;
          return;
        }
        video.srcObject = stream;
        await video.play().catch(() => { });
        if (seq !== qrStartSeq || !isStillQrTab()) {
          stopQrScanner({ silent: true });
          return;
        }
        const mode = await ensureQrDetector();
        if (seq !== qrStartSeq || !isStillQrTab()) {
          stopQrScanner({ silent: true });
          return;
        }
        qrRunning = true;
        qrTorchOn = false;
        await updateQrTorchButton();
        setQrStatus('スキャン中… 枠内にQRを合わせてください');
        if (mode === 'native') qrScanTickNative();
        else qrScanTickJsQR();
      } catch (e) {
        if (seq !== qrStartSeq) return;
        qrRunning = false;
        const name = (e && e.name) || '';
        if (name === 'NotAllowedError' || name === 'PermissionDeniedError') {
          setQrStatus('カメラ権限が拒否されています。ブラウザ設定で許可してください');
        } else if (name === 'NotFoundError' || name === 'DevicesNotFoundError') {
          setQrStatus('カメラが見つかりません');
        } else {
          setQrStatus('カメラ起動に失敗しました');
        }
      }
    }

    function stopQrScanner(opts) {
      opts = opts || {};
      qrStartSeq++;
      qrRunning = false;
      stopQrScanLoop();
      qrTorchOn = false;
      if (qrStream) {
        try { qrStream.getTracks().forEach((t) => t.stop()); } catch (_) { }
        qrStream = null;
      }
      const video = document.getElementById('qr-video');
      if (video) {
        try { video.srcObject = null; } catch (_) { }
      }
      const torchBtn = document.getElementById('qr-torch-btn');
      if (torchBtn) torchBtn.classList.add('hidden');
      if (!opts.silent) setQrStatus('カメラ停止中');
    }

    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'hidden' && qrRunning) {
        stopQrScanner({ silent: true });
        setQrStatus('バックグラウンドのためカメラを停止しました');
      }
    });

    function getMainTabId(tabId) {
      if (MEMO_SUB_TABS.includes(tabId) || tabId === 'memo-mode' || RETIRED_MEMO_SUB_TABS.includes(tabId)) return 'memo-mode';
      if (MAIN_TAB_IDS.includes(tabId)) return tabId;
      return tabId;
    }

    function showMemoSubNav(show) {
      const nav = document.getElementById('memo-sub-nav');
      if (nav) nav.classList.toggle('hidden', !show);
      document.body.classList.toggle('memo-sub-visible', show);
    }

    function updateMemoSubNavHighlight(subTabId) {
      document.querySelectorAll('.memo-sub-btn').forEach((el) => el.classList.remove('active'));
      const btn = document.getElementById('memo-sub-' + subTabId);
      if (btn) btn.classList.add('active');
    }

    function switchMemoSubTab(subTabId) {
      if (RETIRED_MEMO_SUB_TABS.includes(subTabId)) {
        switchTab(subTabId === 'diary-mode' ? 'gantt-mode' : 'input-mode');
        return;
      }
      if (subTabId === 'gantt-mode') {
        switchTab('gantt-mode');
        return;
      }
      if (subTabId === 'tree-mode') {
        switchTab('tree-mode');
        return;
      }
      if (subTabId === 'favorites-mode') {
        switchTab('favorites-mode');
        return;
      }
      if (subTabId === 'blocks-mode') {
        switchTab('blocks-mode');
        initCheckBlocksMode();
        return;
      }
      switchTab(subTabId);
    }

    function switchTab(tabId, options = {}) {
      // サプリタブ以外への移動時は直ちにサプリ関連モーダルを完全クローズ
      try {
        const _destMain = typeof getMainTabId === 'function' ? getMainTabId(tabId) : tabId;
        const _sFabTop = document.getElementById('supple-fab-add');
        if (_sFabTop) {
          _sFabTop.style.setProperty('display', _destMain === 'supplement-mode' ? 'flex' : 'none', 'important');
        }
        const _syncBtnTop = document.getElementById('cross-device-sync-btn');
        if (_syncBtnTop) {
          if (_destMain === 'supplement-mode') {
            _syncBtnTop.style.setProperty('display', 'none', 'important');
          } else {
            _syncBtnTop.style.removeProperty('display');
          }
        }
        if (_destMain !== 'supplement-mode') {
          if (typeof closeSuppleAllModals === 'function') {
            closeSuppleAllModals();
          } else {
            ['modal-supple-intake', 'modal-supple-master', 'modal-supple-scanner'].forEach(id => {
              const el = document.getElementById(id);
              if (el) {
                el.classList.add('hidden');
                el.classList.remove('flex');
                el.style.setProperty('display', 'none', 'important');
              }
            });
          }
        }
      } catch (_) { }

      const prevLoc = (!options.fromBack && typeof getAppLocationKey === 'function')
        ? getAppLocationKey()
        : '';
      if (tabId !== 'input-mode' && typeof closeCaptureOverlay === 'function') {
        closeCaptureOverlay({ force: true });
      }
      let targetTab = tabId;
      if (tabId === 'memo-mode') {
        try {
          targetTab = localStorage.getItem('memo_sub_tab') || 'input-mode';
        } catch (e) {
          targetTab = 'input-mode';
        }
        if (!MEMO_SUB_TABS.includes(targetTab)) targetTab = 'input-mode';
      }
      if (RETIRED_MEMO_SUB_TABS.includes(targetTab)) {
        targetTab = targetTab === 'diary-mode' ? 'gantt-mode' : 'input-mode';
      }
      if (targetTab !== 'blocks-mode' && typeof closeCheckBlockExpand === 'function') {
        closeCheckBlockExpand({ silent: true });
      }
      if (targetTab !== 'tree-mode' && typeof closeTreeMemoDrawer === 'function') {
        closeTreeMemoDrawer();
      }
      if (targetTab !== 'tree-mode' && typeof closeTreeHistoryDrawer === 'function') {
        closeTreeHistoryDrawer();
      }
      const mainTab = getMainTabId(targetTab);
      if (mainTab !== 'qr-mode' && typeof stopQrScanner === 'function') {
        stopQrScanner({ silent: true });
      }
      if (isReviewSelectMode && targetTab !== 'confirm-mode') toggleReviewSelectMode(false);
      if (isSearchSelectMode && targetTab !== 'search-mode') toggleSearchSelectMode(false);
      document.querySelectorAll('.tab-content').forEach(el => el.classList.remove('active'));
      if (mainTab === 'memo-mode') {
        const subEl = document.getElementById(targetTab);
        if (subEl) subEl.classList.add('active');
        try { localStorage.setItem('memo_sub_tab', targetTab); } catch (e) { }
        showMemoSubNav(true);
        updateMemoSubNavHighlight(targetTab);
        document.body.classList.remove('fortune-tab-active');
      } else {
        const mainEl = document.getElementById(mainTab);
        if (mainEl) mainEl.classList.add('active');
        showMemoSubNav(false);
        document.body.classList.toggle('fortune-tab-active', mainTab === 'fortune-mode');
        if (mainTab === 'settings-mode' || mainTab === 'fortune-mode' || mainTab === 'abstinence-mode') {
          loadSettings();
        }
        if (mainTab === 'abstinence-mode') {
          if (typeof initMainTabLayout === 'function') initMainTabLayout();
          if (typeof initAbstinenceHub === 'function') initAbstinenceHub();
          const am = document.getElementById('abstinence-mode');
          if (am) am.scrollTop = 0;
        }
        if (mainTab === 'fortune-mode') {
          if (typeof initMainTabLayout === 'function') initMainTabLayout();
          if (typeof initFortuneHub === 'function') initFortuneHub();
          const fm = document.getElementById('fortune-mode');
          if (fm) fm.scrollTop = 0;
        }


        // サプリタブ時はくるくるボタン（同期ボタン）を非表示
        const _syncBtn = document.getElementById('cross-device-sync-btn');
        if (_syncBtn) {
          if (mainTab === 'supplement-mode') {
            _syncBtn.style.setProperty('display', 'none', 'important');
          } else {
            _syncBtn.style.removeProperty('display');
          }
        }
        // サプリFABの表示制御
        if (typeof syncSuppleFabVisibility === 'function') {
          syncSuppleFabVisibility();
        } else {
          const _sFab = document.getElementById('supple-fab-add');
          if (_sFab) {
            _sFab.style.setProperty('display', mainTab === 'supplement-mode' ? 'flex' : 'none', 'important');
          }
        }
        // サプリタブ以外に移動したときはサプリモーダルをすべて閉じる
        if (mainTab !== 'supplement-mode') {
          if (typeof closeSuppleAllModals === 'function') {
            closeSuppleAllModals();
          } else {
            if (typeof closeSuppleIntakeModal === 'function') closeSuppleIntakeModal();
            if (typeof closeSuppleMasterModal === 'function') closeSuppleMasterModal();
            if (typeof closeSupplementBarcodeScanner === 'function') closeSupplementBarcodeScanner();
          }
        }
        if (mainTab === 'supplement-mode') {
          if (typeof initSupplementTab === 'function') initSupplementTab();
          const sm = document.getElementById('supplement-mode');
          if (sm) sm.scrollTop = 0;
        }
        if (mainTab === 'qr-mode') {
          if (typeof startQrScanner === 'function') startQrScanner();
        }
      }
      document.querySelectorAll('#app-bottom-nav [id^="tab-"]').forEach(el => {
        el.classList.remove('text-cyan-300', 'drop-shadow-[0_0_10px_rgba(34,211,238,0.8)]');
        el.classList.add('text-cyan-900/60');
      });
      const navId = mainTab === 'memo-mode' ? 'tab-memo-mode' : 'tab-' + mainTab;
      const activeTab = document.getElementById(navId);
      if (activeTab) {
        activeTab.classList.remove('text-cyan-900/60');
        activeTab.classList.add('text-cyan-300', 'drop-shadow-[0_0_10px_rgba(34,211,238,0.8)]');
      }
      window.scrollTo(0, 0);
      closeContextHelp();
      if (targetTab === 'search-mode') {
        const kw = document.getElementById('search-keyword');
        const keyword = kw ? kw.value.trim() : '';
        if (!keyword) {
          searchViewNeedsRefresh = false;
          if (typeof showOperationHistory === 'function') showOperationHistory();
        } else if (searchViewNeedsRefresh) {
          // お気に入り編集中は検索一覧を作り直さない。戻ったときにだけ反映する
          searchViewNeedsRefresh = false;
          if (typeof renderSearchResultsView === 'function') renderSearchResultsView();
        }
      }
      if (targetTab === 'favorites-mode') {
        renderFavoritesList();
      }
      if (targetTab === 'gantt-mode' && typeof initGanttMode === 'function') {
        initGanttMode();
      }
      if (targetTab === 'tree-mode' && typeof initTreeMode === 'function') {
        initTreeMode();
      }
      if (targetTab === 'input-mode') {
        if (typeof ensureInputTopPreferenceApplied === 'function') {
          ensureInputTopPreferenceApplied({
            skipAutoFocus: !!(options && options.skipAutoFocus),
            skipHistoryCloudSync: !!(options && options.skipHistoryCloudSync),
            skipHistoryPaint: !!(options && options.skipHistoryPaint)
          });
        }
        // 他のタブで編集した分は、入力タブを開いたときにまとめて描く
        if (inputTabHistoryDirty && typeof paintInputTabHistory === 'function') {
          paintInputTabHistory(typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : [], { force: true });
        }
      }
      if (prevLoc && typeof pushAppNavLocation === 'function') {
        const nextLoc = typeof getAppLocationKey === 'function' ? getAppLocationKey() : '';
        if (nextLoc && nextLoc !== prevLoc) pushAppNavLocation(prevLoc);
      }
    }

    const APP_NAV_STACK_MAX = 40;
    let appNavStack = [];
    let appNavSilent = false;

    function isCaptureOverlayOpen() {
      const inputMode = document.getElementById('input-mode');
      return !!(inputMode && inputMode.classList.contains('active'));
    }

    function isModalOpenById(id) {
      const el = document.getElementById(id);
      if (!el) return false;
      if (el.classList.contains('hidden')) return false;
      if (el.classList.contains('pointer-events-none')) return false;
      if (el.getAttribute('aria-hidden') === 'true') return false;
      return true;
    }

    function getAppLocationKey() {
      if (isModalOpenById('input-dup-modal')) return 'modal:dup';
      if (isModalOpenById('tab-help-modal')) return 'modal:help';
      if (isModalOpenById('abstinence-reset-modal')) return 'modal:abstinence-reset';
      if (isModalOpenById('move-file-modal')) return 'modal:move-file';
      const review = document.getElementById('review-detail-overlay');
      if (review && !review.classList.contains('hidden')) return 'overlay:review';
      if (typeof checkBlocksExpandState !== 'undefined' && checkBlocksExpandState) return 'overlay:blocks-expand';
      if (typeof isTreeMemoDrawerOpen === 'function' && isTreeMemoDrawerOpen()) return 'overlay:tree-memo';
      if (typeof isSearchSelectMode !== 'undefined' && isSearchSelectMode) return 'mode:search-select';
      const active = document.querySelector('.tab-content.active');
      return active && active.id ? ('tab:' + active.id) : 'tab:input-mode';
    }

    function pushAppNavLocation(loc) {
      if (appNavSilent || !loc) return;
      if (appNavStack[appNavStack.length - 1] === loc) return;
      appNavStack.push(loc);
      if (appNavStack.length > APP_NAV_STACK_MAX) appNavStack.shift();
    }

    function tryCloseAppTopLayer() {
      const scm = document.getElementById('modal-supple-scanner');
      if (scm && !scm.classList.contains('hidden') && scm.style.display !== 'none') {
        if (typeof closeSupplementBarcodeScanner === 'function') closeSupplementBarcodeScanner();
        return true;
      }
      const smm = document.getElementById('modal-supple-master');
      if (smm && !smm.classList.contains('hidden') && smm.style.display !== 'none') {
        if (typeof closeSuppleMasterModal === 'function') closeSuppleMasterModal();
        return true;
      }
      const sim = document.getElementById('modal-supple-intake');
      if (sim && !sim.classList.contains('hidden') && sim.style.display !== 'none') {
        if (typeof closeSuppleIntakeModal === 'function') closeSuppleIntakeModal();
        return true;
      }
      if (isModalOpenById('input-dup-modal') && typeof closeInputDupModal === 'function') {
        closeInputDupModal();
        return true;
      }
      if (isModalOpenById('tab-help-modal') && typeof closeContextHelp === 'function') {
        closeContextHelp();
        return true;
      }
      if (isModalOpenById('abstinence-reset-modal')) {
        const modal = document.getElementById('abstinence-reset-modal');
        if (modal) {
          modal.classList.add('opacity-0', 'pointer-events-none');
          modal.setAttribute('aria-hidden', 'true');
          try { modal.setAttribute('inert', ''); } catch (_) { }
        }
        return true;
      }
      if (isModalOpenById('move-file-modal') && typeof closeMoveModal === 'function') {
        closeMoveModal();
        return true;
      }
      const review = document.getElementById('review-detail-overlay');
      if (review && !review.classList.contains('hidden') && typeof closeReviewDetail === 'function') {
        closeReviewDetail();
        // 未保存確認でキャンセルされた場合は閉じない
        return review.classList.contains('hidden');
      }
      if (typeof checkBlocksExpandState !== 'undefined' && checkBlocksExpandState && typeof closeCheckBlockExpand === 'function') {
        return closeCheckBlockExpand() !== false && !checkBlocksExpandState;
      }
      if (typeof isTreeMemoDrawerOpen === 'function' && isTreeMemoDrawerOpen() && typeof closeTreeMemoDrawer === 'function') {
        closeTreeMemoDrawer();
        return true;
      }
      if (typeof isTreeHistoryDrawerOpen === 'function' && isTreeHistoryDrawerOpen() && typeof closeTreeHistoryDrawer === 'function') {
        closeTreeHistoryDrawer();
        return true;
      }
      if (typeof isSearchSelectMode !== 'undefined' && isSearchSelectMode && typeof toggleSearchSelectMode === 'function') {
        toggleSearchSelectMode(false);
        return true;
      }
      if (typeof isReviewSelectMode !== 'undefined' && isReviewSelectMode && typeof toggleReviewSelectMode === 'function') {
        toggleReviewSelectMode(false);
        return true;
      }
      if (typeof closeCheckBlockMenu === 'function') {
        const hadMenu = typeof checkBlockMenuEl !== 'undefined' && !!checkBlockMenuEl;
        closeCheckBlockMenu();
        if (hadMenu) return true;
      }
      return false;
    }

    function restoreAppLocation(loc) {
      if (!loc) return false;
      if (loc.indexOf('tab:') === 0) {
        const tabId = loc.slice(4);
        appNavSilent = true;
        try {
          if (typeof MEMO_SUB_TABS !== 'undefined' && MEMO_SUB_TABS.includes(tabId) && typeof switchMemoSubTab === 'function') {
            switchMemoSubTab(tabId);
          } else if (typeof switchTab === 'function') {
            switchTab(tabId, { skipHelp: true, fromBack: true });
          } else {
            return false;
          }
        } finally {
          appNavSilent = false;
        }
        return true;
      }
      return false;
    }

    function hasAppTopLayer() {
      // サプリモーダルが開いている場合はトップレイヤーとして処理
      const sim = document.getElementById('modal-supple-intake');
      if (sim && !sim.classList.contains('hidden') && sim.style.display !== 'none') return true;
      const smm = document.getElementById('modal-supple-master');
      if (smm && !smm.classList.contains('hidden') && smm.style.display !== 'none') return true;
      const scm = document.getElementById('modal-supple-scanner');
      if (scm && !scm.classList.contains('hidden') && scm.style.display !== 'none') return true;
      if (isModalOpenById('input-dup-modal')) return true;
      if (isModalOpenById('tab-help-modal')) return true;
      if (isModalOpenById('abstinence-reset-modal')) return true;
      if (isModalOpenById('move-file-modal')) return true;
      const review = document.getElementById('review-detail-overlay');
      if (review && !review.classList.contains('hidden')) return true;
      if (typeof checkBlocksExpandState !== 'undefined' && checkBlocksExpandState) return true;
      if (typeof isTreeMemoDrawerOpen === 'function' && isTreeMemoDrawerOpen()) return true;
      if (typeof isSearchSelectMode !== 'undefined' && isSearchSelectMode) return true;
      if (typeof isReviewSelectMode !== 'undefined' && isReviewSelectMode) return true;
      if (typeof checkBlockMenuEl !== 'undefined' && checkBlockMenuEl) return true;
      return false;
    }

    function appGoBack() {
      // オーバーレイ表示中はタブ履歴へ進まず、閉じる／キャンセルだけ扱う
      if (hasAppTopLayer()) return tryCloseAppTopLayer();
      while (appNavStack.length) {
        const prev = appNavStack.pop();
        if (!prev || prev === getAppLocationKey()) continue;
        if (restoreAppLocation(prev)) return true;
      }
      return false;
    }

    function ensureAppBackGestureHint() {
      let el = document.getElementById('app-back-gesture-hint');
      if (el) return el;
      el = document.createElement('div');
      el.id = 'app-back-gesture-hint';
      el.setAttribute('aria-hidden', 'true');
      document.body.appendChild(el);
      return el;
    }

    function isAppBackSwipeExcludedTarget(target) {
      if (!target || !target.closest) return false;
      if (target.closest('input, textarea, select, [contenteditable="true"], [contenteditable=""], .tree-node-edit-input')) {
        return true;
      }
      if (target.closest('[data-no-back-swipe="1"]')) return true;
      // 横スクロール中の領域は奪わない
      let el = target;
      for (let i = 0; i < 6 && el && el !== document.body; i++) {
        if (el instanceof HTMLElement) {
          const style = window.getComputedStyle(el);
          const ox = style.overflowX;
          if ((ox === 'auto' || ox === 'scroll') && el.scrollWidth > el.clientWidth + 8) {
            if (el.scrollLeft > 2) return true;
          }
        }
        el = el.parentElement;
      }
      return false;
    }

    function canAppGoBackNow() {
      if (typeof hasAppTopLayer === 'function' && hasAppTopLayer()) return true;
      return !!(appNavStack && appNavStack.length);
    }

    function bindAppEdgeBackGesture() {
      if (window.__appEdgeBackBound) return;
      window.__appEdgeBackBound = true;
      // 左端は軽く、画面内ははっきり右へスワイプしたときだけ戻る
      const EDGE_PX = 56;
      const EDGE_ARM_PX = 12;
      const EDGE_COMMIT_PX = 64;
      const SCREEN_ARM_PX = 28;
      const SCREEN_COMMIT_PX = 108;
      let tracking = null;

      const clearTracking = () => {
        tracking = null;
        const hint = document.getElementById('app-back-gesture-hint');
        if (hint) {
          hint.classList.remove('is-on');
          hint.style.width = '0px';
        }
      };

      const onDown = (e) => {
        if (e.pointerType === 'mouse') return;
        if (e.isPrimary === false) return;
        if (typeof checkBlockDrag !== 'undefined' && checkBlockDrag) return;
        if (typeof treePan !== 'undefined' && treePan) return;
        if (typeof treeDrag !== 'undefined' && treeDrag) return;
        if (typeof treePinch !== 'undefined' && treePinch) return;
        const fromEdge = e.clientX <= EDGE_PX;
        if (!fromEdge && isAppBackSwipeExcludedTarget(e.target)) return;
        // 戻れる先が無いときは、端以外のスワイプを始めない（誤反応防止）
        if (!fromEdge && !canAppGoBackNow()) return;
        tracking = {
          id: e.pointerId,
          x0: e.clientX,
          y0: e.clientY,
          fromEdge,
          armed: false
        };
      };

      const onMove = (e) => {
        if (!tracking || e.pointerId !== tracking.id) return;
        const dx = e.clientX - tracking.x0;
        const dy = e.clientY - tracking.y0;
        const armPx = tracking.fromEdge ? EDGE_ARM_PX : SCREEN_ARM_PX;
        if (!tracking.armed) {
          if (Math.hypot(dx, dy) < armPx) return;
          // 右方向の水平スワイプだけ。縦スクロール優先なら解除
          const verticalBias = tracking.fromEdge ? 0.95 : 0.65;
          if (dx < armPx || Math.abs(dy) > Math.abs(dx) * verticalBias) {
            clearTracking();
            return;
          }
          tracking.armed = true;
          ensureAppBackGestureHint();
        }
        if (e.cancelable) e.preventDefault();
        const hint = ensureAppBackGestureHint();
        const w = Math.max(0, Math.min(148, dx));
        hint.style.width = w + 'px';
        hint.classList.toggle('is-on', w > 8);
      };

      const onUp = (e) => {
        if (!tracking || e.pointerId !== tracking.id) return;
        const dx = e.clientX - tracking.x0;
        const armed = tracking.armed;
        const fromEdge = tracking.fromEdge;
        clearTracking();
        if (!armed) return;
        const need = fromEdge ? EDGE_COMMIT_PX : SCREEN_COMMIT_PX;
        if (dx < need) return;
        if (!canAppGoBackNow()) return;
        appGoBack();
      };

      document.addEventListener('pointerdown', onDown, { capture: true, passive: true });
      document.addEventListener('pointermove', onMove, { capture: true, passive: false });
      document.addEventListener('pointerup', onUp, { capture: true, passive: true });
      document.addEventListener('pointercancel', onUp, { capture: true, passive: true });
    }

    function bindAppBrowserBack() {
      if (window.__appBrowserBackBound) return;
      window.__appBrowserBackBound = true;
      try {
        if (!history.state || !history.state.dumpNav) {
          history.replaceState({ dumpNav: 0 }, '');
        }
      } catch (_) { }
      window.addEventListener('popstate', () => {
        const handled = canAppGoBackNow() && appGoBack();
        if (handled) {
          try { history.pushState({ dumpNav: 1 }, ''); } catch (_) { }
        }
      });
    }

    (function wrapPushAppNavForHistory() {
      const orig = pushAppNavLocation;
      pushAppNavLocation = function (loc) {
        const before = appNavStack.length;
        orig(loc);
        if (appNavStack.length > before) {
          try { history.pushState({ dumpNav: 1, loc: String(loc || '') }, ''); } catch (_) { }
        }
      };
    })();
    const nameCollator = new Intl.Collator('ja', {
      sensitivity: 'base',
      numeric: true
    });
    function sortNames(names) {
      return [...names]
        .filter(name => name && name !== '__SYSTEM__')
        .sort((a, b) => nameCollator.compare(a, b));
    }
    function renderDirectFolderOptions(selectedFolder = '') {
      const folderSelect = document.getElementById('direct-folder');
      folderSelect.innerHTML = '<option value="">未選択 (INBOXへ)</option>';
      sortNames(Object.keys(configData)).forEach(folder => {
        folderSelect.innerHTML += `<option value="${folder}">${folder}</option>`;
      });
      folderSelect.innerHTML += '<option value="_new_">➕ 新規フォルダを作成...</option>';
      if (Object.prototype.hasOwnProperty.call(configData, selectedFolder)) {
        folderSelect.value = selectedFolder;
      }
    }
    function renderDirectFileOptions(folder, selectedFile = '') {
      const fileSelect = document.getElementById('direct-file');
      fileSelect.innerHTML = '<option value="">未選択</option>';
      if (folder && configData[folder]) {
        sortNames(configData[folder]).forEach(file => {
          fileSelect.innerHTML += `<option value="${file}">${file}</option>`;
        });
        fileSelect.innerHTML += '<option value="_new_">➕ 新規ファイルを作成...</option>';
        if (configData[folder].includes(selectedFile)) {
          fileSelect.value = selectedFile;
        }
      }
    }
    function updateBadge() {
      fetchOrganizerDataShared({ silent: true }).then((data) => {
        applyOrganizerData(data);
      });
    }
    let inputHistoryLaneFilter = '';

    function paintDumpLaneCurrent() {
      const pending = typeof pendingInputHistoryReplace !== 'undefined' ? pendingInputHistoryReplace : null;
      const editLane = pending ? historyEntryLane(pending) : '';
      const filterLane = (!pending && inputHistoryLaneFilter) ? inputHistoryLaneFilter : '';
      document.querySelectorAll('#capture-dump-bar .dump-lane-btn').forEach((btn) => {
        const btnLane = btn.id === 'submit-todo-btn' ? 'todo' : (btn.id === 'submit-log-btn' ? 'log' : 'inbox');
        const onEdit = !!editLane && btnLane === editLane;
        const onFilter = !!filterLane && btnLane === filterLane;
        btn.classList.toggle('is-current-lane', onEdit);
        btn.classList.toggle('is-lane-filter', onFilter);
        if (onEdit) btn.setAttribute('aria-current', 'true');
        else btn.removeAttribute('aria-current');
      });
    }
    function applySubmitInboxEnabledState() {
      document.querySelectorAll('.dump-lane-btn').forEach((btn) => {
        btn.disabled = false;
        btn.removeAttribute('disabled');
        btn.classList.remove('opacity-60', 'pointer-events-none');
        btn.setAttribute('aria-disabled', 'false');
      });
    }

    function clearSubmitInboxLocks(reason) {
      const hadLock = !!(isSubmittingInbox || historyReplaceSubmitLock);
      isSubmittingInbox = false;
      submitInboxBusyStartedAt = 0;
      historyReplaceSubmitLock = false;
      historyReplaceLockStartedAt = 0;
      if (hadLock && reason) console.warn('submit inbox locks cleared:', reason);
      applySubmitInboxEnabledState();
      return hadLock;
    }

    function checkStuckSubmitLocks() {
      const now = Date.now();
      let recovered = false;
      if (historyReplaceSubmitLock && historyReplaceLockStartedAt
        && (now - historyReplaceLockStartedAt) > HISTORY_REPLACE_LOCK_STUCK_MS) {
        clearSubmitInboxLocks('history_replace_stuck');
        recovered = true;
      }
      if (isSubmittingInbox && submitInboxBusyStartedAt
        && (now - submitInboxBusyStartedAt) > SUBMIT_INBOX_BUSY_STUCK_MS) {
        clearSubmitInboxLocks('submit_busy_stuck');
        recovered = true;
      }
      return recovered;
    }

    /** 入力画面での DUMP 優先。残留ローダー／ロックを解除して押せる状態にする */
    function ensureSubmitInboxReady(options) {
      options = options || {};
      const force = options.force !== false;
      checkStuckLoader();
      checkStuckSubmitLocks();
      if (force) {
        if (isLoaderVisible()) forceHideLoader();
        if (isSubmittingInbox || historyReplaceSubmitLock) {
          clearSubmitInboxLocks(options.reason || 'ensure_ready');
        }
      }
      applySubmitInboxEnabledState();
      return !(isLoaderVisible() || isSubmittingInbox || historyReplaceSubmitLock);
    }

    function updateDirectSaveButton() {
      const folderEl = document.getElementById('direct-folder');
      const fileEl = document.getElementById('direct-file');
      const btn = document.getElementById('submit-inbox-btn');
      if (!folderEl || !fileEl || !btn) return;
      const folder = isDirectDestinationEnabled() ? folderEl.value : '';
      const file = isDirectDestinationEnabled() ? fileEl.value : '';
      const editing = !!pendingInputHistoryReplace;

      if (btn.classList.contains('dump-lane-btn')) {
        applySubmitInboxEnabledState();
        paintDumpLaneCurrent();
        return;
      }

      if (folder && file) {
        btn.textContent = editing ? '編集を直接保存' : '直接保存';
        btn.className = "w-full bg-gradient-to-r from-emerald-500 to-teal-600 hover:from-emerald-400 hover:to-teal-500 active:scale-[0.98] text-white font-extrabold h-12 sm:h-14 rounded-xl transition duration-150 text-base sm:text-lg shadow-[0_0_20px_rgba(16,185,129,0.3)] border border-emerald-400/20";
      } else {
        btn.textContent = editing ? '編集を INBOX へ保存' : 'INBOXへDUMP';
        btn.className = "w-full bg-gradient-to-r from-cyan-500 to-indigo-600 hover:from-cyan-400 hover:to-indigo-500 active:scale-[0.98] text-white font-extrabold h-12 sm:h-14 rounded-xl transition duration-150 text-base sm:text-lg shadow-[0_0_20px_rgba(34,211,238,0.3)] border border-cyan-400/20";
      }
      applySubmitInboxEnabledState();
    }

    // 何らかの理由でロックが残った場合の自動復帰
    function refreshSubmitInboxAvailability() {
      checkStuckSubmitLocks();
      updateDirectSaveButton();
    }
    async function onDirectFolderChange() {
      const folderSelect = document.getElementById('direct-folder');
      let folder = folderSelect.value;
      const fileSelect = document.getElementById('direct-file');

      if (folder === '_new_') {
        const newFolder = prompt("新しいフォルダ名を入力してください:");
        if (newFolder && newFolder.trim()) {
          folder = newFolder.trim();
          if (!configData[folder]) {
            configData[folder] = [];
            showLoader("フォルダを作成中...");
            await callAPI('addConfigRecord', { folder: folder, file: '' });
            hideLoader();
          }
          renderDirectFolderOptions(folder);
        } else {
          folderSelect.value = "";
          folder = "";
        }
      }

      renderDirectFileOptions(folder);

      const folderDelBtn = document.getElementById('direct-folder-del-btn');
      const folderRenBtn = document.getElementById('direct-folder-ren-btn');
      if (folder && folder !== '_new_') { folderDelBtn.classList.remove('hidden'); folderRenBtn.classList.remove('hidden'); }
      else { folderDelBtn.classList.add('hidden'); folderRenBtn.classList.add('hidden'); }

      document.getElementById('direct-file-del-btn').classList.add('hidden');
      document.getElementById('direct-file-ren-btn').classList.add('hidden');
      updateDirectSaveButton();
    }
    async function onDirectFileChange() {
      const fileSelect = document.getElementById('direct-file');
      let file = fileSelect.value;
      const folder = document.getElementById('direct-folder').value;

      if (file === '_new_') {
        const newFile = prompt(`「${folder}」の中に作成する新しいファイル名を入力してください:`);
        if (newFile && newFile.trim()) {
          file = newFile.trim();
          if (!configData[folder].includes(file)) {
            configData[folder].push(file);
            showLoader("ファイルを作成中...");
            await callAPI('addConfigRecord', { folder: folder, file: file });
            hideLoader();
          }
          renderDirectFileOptions(folder, file);
        } else {
          fileSelect.value = "";
          file = "";
        }
      }

      const fileDelBtn = document.getElementById('direct-file-del-btn');
      const fileRenBtn = document.getElementById('direct-file-ren-btn');
      if (file && file !== '_new_') { fileDelBtn.classList.remove('hidden'); fileRenBtn.classList.remove('hidden'); }
      else { fileDelBtn.classList.add('hidden'); fileRenBtn.classList.add('hidden'); }

      updateDirectSaveButton();
    }
    async function renameDirectFolder() {
      const folderSelect = document.getElementById('direct-folder');
      const oldFolder = folderSelect.value;
      if (!oldFolder || oldFolder === '_new_') return;
      const newFolder = prompt(`「${oldFolder}」の新しいフォルダ名を入力してください:`, oldFolder);
      if (!newFolder || !newFolder.trim() || newFolder.trim() === oldFolder) return;
      const targetFolder = newFolder.trim();
      showLoader("フォルダ名を変更中...");
      try {
        const files = configData[oldFolder] || [];
        if (files.length === 0) {
          await callAPI('updateConfigRecord', { oldFolder, oldFile: '', newFolder: targetFolder, newFile: '' });
        } else {
          await callBatch(
            files.map(file => ({
              action: 'updateConfigRecord',
              oldFolder,
              oldFile: file,
              newFolder: targetFolder,
              newFile: file
            }))
          );
        }
        const data = await callAPI('getOrganizerData');
        configData = data.config || {};
        renderDirectFolderOptions(targetFolder);
        await onDirectFolderChange();
      } catch (err) {
        alert("エラーが発生しました");
      }
      hideLoader();
    }
    async function renameDirectFile() {
      const folder = document.getElementById('direct-folder').value;
      const fileSelect = document.getElementById('direct-file');
      const oldFile = fileSelect.value;
      if (!folder || !oldFile || oldFile === '_new_') return;
      const newFile = prompt(`「${folder} ＞ ${oldFile}」の新しいファイル名を入力してください:`, oldFile);
      if (!newFile || !newFile.trim() || newFile.trim() === oldFile) return;
      const targetFile = newFile.trim();
      showLoader("ファイル名を変更中...");
      try {
        const res = await callAPI('updateConfigRecord', { oldFolder: folder, oldFile: oldFile, newFolder: folder, newFile: targetFile });
        if (res && res.success !== false) {
          const data = await callAPI('getOrganizerData');
          configData = data.config || {};
          await onDirectFolderChange();
          fileSelect.value = targetFile;
          await onDirectFileChange();
        }
      } catch (err) {
        alert("エラーが発生しました");
      }
      hideLoader();
    }
    async function deleteDirectFolder() {
      const folderSelect = document.getElementById('direct-folder');
      const folder = folderSelect.value;
      if (!folder || folder === '_new_') return;
      if (await deleteConfigAndMoveToTrash(folder, null)) {
        renderDirectFolderOptions();
        onDirectFolderChange();
        updateBadge();
      }
    }
    async function deleteDirectFile() {
      const folderSelect = document.getElementById('direct-folder');
      const fileSelect = document.getElementById('direct-file');
      const folder = folderSelect.value;
      const file = fileSelect.value;
      if (!folder || !file || file === '_new_') return;
      if (await deleteConfigAndMoveToTrash(folder, file)) {
        onDirectFolderChange();
        updateBadge();
      }
    }
    function commitInputComposition() {
      const textarea = document.getElementById('input-content');
      if (textarea && document.activeElement === textarea) textarea.blur();
    }

    let inputContentComposing = false;
    function bindInputContentCompositionWatch() {
      const ta = document.getElementById('input-content');
      if (!ta || ta.dataset.compWatch === '1') return;
      ta.dataset.compWatch = '1';
      ta.addEventListener('compositionstart', () => { inputContentComposing = true; });
      ta.addEventListener('compositionend', () => {
        inputContentComposing = false;
        if (!pendingInputHistoryReplace && typeof applyDeferredCloudLiveInputDraft === 'function') {
          if (applyDeferredCloudLiveInputDraft()) return;
        }
        if (!pendingInputHistoryReplace && typeof onLiveInputDraftChanged === 'function') {
          onLiveInputDraftChanged({ reason: 'compositionend' });
        }
      });
    }

    async function commitInputCompositionAsync() {
      const textarea = document.getElementById('input-content');
      if (!textarea || document.activeElement !== textarea) return;
      // 変換中でなければ blur 待ちをしない（保存の体感が 160ms 遅れる）
      if (!inputContentComposing) return;
      await new Promise((resolve) => {
        let settled = false;
        const finish = () => {
          if (settled) return;
          settled = true;
          textarea.removeEventListener('compositionend', finish);
          resolve();
        };
        textarea.addEventListener('compositionend', finish, { once: true });
        try { textarea.blur(); } catch (_) { }
        // スマホIMEは blur 後に compositionend が遅れることがある
        setTimeout(finish, 160);
      });
      // 確定文字が value に載るまで一拍
      await new Promise((r) => setTimeout(r, 0));
    }

    let inboxInputClearToken = 0;

    /** DUMP／編集保存直後に入力欄を確実に空にする（IME遅延で文字が戻る対策） */
    function clearInboxInputAfterDump(textarea, dumpedRaw, options) {
      options = options || {};
      const ta = textarea || document.getElementById('input-content');
      if (!ta) return;
      const token = ++inboxInputClearToken;
      const dumped = String(dumpedRaw || '');
      const dumpedTrim = dumped.trim();
      if (typeof activateLiveDraftSubmitEchoGuard === 'function') {
        activateLiveDraftSubmitEchoGuard(dumpedRaw);
      }
      if (!pendingInputHistoryReplace && typeof clearLiveInputDraft === 'function') {
        clearLiveInputDraft({ immediateCloud: true });
      }

      const forceEmpty = () => {
        if (token !== inboxInputClearToken) return;
        if (ta.value !== '') ta.value = '';
        try { ta.setSelectionRange(0, 0); } catch (_) { }
        if (typeof clearDumpComposeImages === 'function' && dumpComposeImages && dumpComposeImages.length) {
          clearDumpComposeImages({ skipDraftSync: true });
        }
      };

      const looksLikeDumpedEcho = (value) => {
        const v = String(value || '');
        if (!v) return false;
        if (!dumpedTrim) return true;
        const vt = v.trim();
        if (!vt) return true;
        if (v === dumped || vt === dumpedTrim) return true;
        if (typeof dumpContentEquals === 'function' && dumpContentEquals(v, dumped)) return true;
        // ダンプ本文の接頭辞としてまとまって戻った場合（短い新規入力は消さない）
        const minEcho = Math.min(8, dumpedTrim.length);
        if (vt.length >= minEcho && (dumpedTrim.startsWith(vt) || dumped.startsWith(v))) return true;
        if (vt.length >= Math.ceil(dumpedTrim.length * 0.6)
          && (dumped.includes(v) || dumpedTrim.includes(vt))) return true;
        return false;
      };

      const scrub = () => {
        if (token !== inboxInputClearToken) return;
        if (looksLikeDumpedEcho(ta.value)) forceEmpty();
      };

      forceEmpty();
      const onCompEnd = () => scrub();
      const onInput = () => scrub();
      ta.addEventListener('compositionend', onCompEnd);
      ta.addEventListener('input', onInput);
      // 直後〜100ms は強制クリア（IME遅延の主戦場）
      [0, 40, 100].forEach((ms) => setTimeout(forceEmpty, ms));
      // その後は「ダンプ内容のエコー」だけ消し込む
      [220, 400].forEach((ms) => setTimeout(scrub, ms));
      setTimeout(() => {
        ta.removeEventListener('compositionend', onCompEnd);
        ta.removeEventListener('input', onInput);
        scrub();
        if (typeof syncInputTabHistoryLock === 'function') syncInputTabHistoryLock();
      }, 480);

      if (typeof syncInputTabHistoryLock === 'function') syncInputTabHistoryLock();
      try { ta.dispatchEvent(new Event('input', { bubbles: true })); } catch (_) { }

      if (options.focus !== false) {
        try { ta.focus({ preventScroll: true }); } catch (_) {
          try { ta.focus(); } catch (__) { }
        }
        setTimeout(forceEmpty, 0);
        setTimeout(scrub, 60);
      }
    }

    function shieldHistoryFromGhostTap(ms = 450) {
      window.__suppressHistoryTapUntil = Date.now() + ms;
      const nodes = [
        document.getElementById('input-tab-history-list'),
        document.getElementById('input-tab-history-recent')
      ].filter(Boolean);
      nodes.forEach((el) => el.classList.add('ghost-tap-shield'));
      setTimeout(() => {
        nodes.forEach((el) => el.classList.remove('ghost-tap-shield'));
      }, ms);
    }

    let captureOpenShieldTimer = null;
    function shieldCaptureOpenFromGhostTap(ms = 550) {
      const overlay = document.getElementById('capture-overlay');
      const nodes = [
        document.getElementById('input-tab-history-list'),
        document.getElementById('input-tab-history-recent')
      ].filter(Boolean);
      window.__suppressHistoryTapUntil = Date.now() + ms;
      nodes.forEach((el) => el.classList.add('ghost-tap-shield'));
      if (overlay) overlay.classList.add('capture-open-shield');
      if (captureOpenShieldTimer) clearTimeout(captureOpenShieldTimer);
      captureOpenShieldTimer = setTimeout(() => {
        captureOpenShieldTimer = null;
        nodes.forEach((el) => el.classList.remove('ghost-tap-shield'));
        if (overlay) overlay.classList.remove('capture-open-shield');
      }, ms);
    }

    const INPUT_EDITOR_TAB = '\t';
    const INPUT_EDITOR_TAB_SPACES = 2;

    function textareaLineBounds(text, index) {
      const safe = Math.max(0, Math.min(index, text.length));
      const start = text.lastIndexOf('\n', safe - 1) + 1;
      const nextBreak = text.indexOf('\n', safe);
      const end = nextBreak === -1 ? text.length : nextBreak;
      return { start, end };
    }

    function textareaBlockBounds(text, selStart, selEnd) {
      const start = text.lastIndexOf('\n', selStart - 1) + 1;
      const endIdx = text.indexOf('\n', Math.max(selStart, selEnd - 1));
      const end = endIdx === -1 ? text.length : endIdx;
      return { start, end };
    }

    function removeOneIndentLevel(line) {
      if (line.startsWith('\t')) return { line: line.slice(1), removed: 1 };
      if (line.startsWith(' ')) {
        let remove = 0;
        while (remove < INPUT_EDITOR_TAB_SPACES && line[remove] === ' ') remove++;
        if (remove > 0) return { line: line.slice(remove), removed: remove };
      }
      return { line, removed: 0 };
    }

    function insertAtTextarea(textarea, insertText, replaceStart, replaceEnd) {
      const value = textarea.value;
      textarea.value = value.slice(0, replaceStart) + insertText + value.slice(replaceEnd);
      const pos = replaceStart + insertText.length;
      textarea.selectionStart = pos;
      textarea.selectionEnd = pos;
    }

    function indentTextareaSelection(textarea) {
      const value = textarea.value;
      const selStart = textarea.selectionStart;
      const selEnd = textarea.selectionEnd;
      const hasSelection = selStart !== selEnd;

      if (!hasSelection) {
        const line = textareaLineBounds(value, selStart);
        const lineText = value.slice(line.start, line.end);
        const col = selStart - line.start;
        const canIndentLine = col === 0 || lineText.slice(0, col).trim() === '';
        if (canIndentLine) {
          textarea.value = value.slice(0, line.start) + INPUT_EDITOR_TAB + value.slice(line.start);
          const pos = selStart + 1;
          textarea.selectionStart = pos;
          textarea.selectionEnd = pos;
        } else {
          insertAtTextarea(textarea, INPUT_EDITOR_TAB, selStart, selEnd);
        }
        return;
      }

      const block = textareaBlockBounds(value, selStart, selEnd);
      const blockText = value.slice(block.start, block.end);
      const lines = blockText.split('\n');
      const indented = lines.map((line) => INPUT_EDITOR_TAB + line).join('\n');
      textarea.value = value.slice(0, block.start) + indented + value.slice(block.end);
      textarea.selectionStart = selStart + 1;
      textarea.selectionEnd = selEnd + lines.length;
    }

    function outdentTextareaSelection(textarea) {
      const value = textarea.value;
      const selStart = textarea.selectionStart;
      const selEnd = textarea.selectionEnd;
      const block = textareaBlockBounds(value, selStart, selEnd);
      const blockText = value.slice(block.start, block.end);
      const lines = blockText.split('\n');

      let removedBeforeStart = 0;
      let removedBeforeEnd = 0;
      let removedTotal = 0;
      let lineStart = 0;
      const outdentedLines = lines.map((line, index) => {
        const result = removeOneIndentLevel(line);
        removedTotal += result.removed;
        const absLineStart = block.start + lineStart;
        if (selStart > absLineStart) removedBeforeStart += result.removed;
        if (selEnd > absLineStart) removedBeforeEnd += result.removed;
        lineStart += line.length + (index < lines.length - 1 ? 1 : 0);
        return result.line;
      });

      if (removedTotal === 0) return;

      const outdented = outdentedLines.join('\n');
      textarea.value = value.slice(0, block.start) + outdented + value.slice(block.end);
      textarea.selectionStart = Math.max(block.start, selStart - removedBeforeStart);
      textarea.selectionEnd = Math.max(textarea.selectionStart, selEnd - removedBeforeEnd);
    }

    function handleInputContentEditorKeydown(event) {
      if (event.key !== 'Tab' || event.ctrlKey || event.altKey || event.metaKey) return;
      const textarea = event.target;
      if (!textarea || textarea.id !== 'input-content') return;
      if (event.isComposing) return;

      event.preventDefault();
      if (event.shiftKey) outdentTextareaSelection(textarea);
      else indentTextareaSelection(textarea);
      textarea.dispatchEvent(new Event('input', { bubbles: true }));
    }

    function bindInputContentEditorKeys() {
      const ta = document.getElementById('input-content');
      if (!ta || ta.dataset.editorKeysBound === '1') return;
      ta.dataset.editorKeysBound = '1';
      ta.addEventListener('keydown', handleInputContentEditorKeydown);
    }

    function bindSubmitInboxImeCommit() {
      const btn = document.getElementById('submit-inbox-btn');
      if (!btn || btn.dataset.imeBound === '1') return;
      btn.dataset.imeBound = '1';
      btn.addEventListener('pointerdown', (e) => {
        shieldHistoryFromGhostTap(450);
        if (typeof ensureSubmitInboxReady === 'function') {
          ensureSubmitInboxReady({ force: true, reason: 'pointerdown' });
        } else {
          if (typeof checkStuckSubmitLocks === 'function') checkStuckSubmitLocks();
          if (typeof applySubmitInboxEnabledState === 'function') applySubmitInboxEnabledState();
        }
        e.stopPropagation();
      }, { capture: true });
    }

    function historyDestIsInbox(folder) {
      const f = String(folder || '').replace(/^📥\s*/, '').trim();
      return !f || f === 'INBOX';
    }

    function normalizeHistoryFolder(folder) {
      return historyDestIsInbox(folder) ? 'INBOX' : String(folder || '').replace(/^📥\s*/, '').trim();
    }

    function dumpContentKey(s) {
      return String(s || '').replace(/\r\n/g, '\n').replace(/\u00a0/g, ' ').trim();
    }

    function dumpContentEquals(a, b) {
      return dumpContentKey(a) === dumpContentKey(b);
    }

    function searchKeywordForDump(content) {
      const key = dumpContentKey(content);
      if (!key) return '';
      const line = key.split('\n').map((s) => s.trim()).find((s) => s.length >= 8);
      const src = line || key.replace(/\s+/g, ' ').trim();
      return src.slice(0, 80);
    }

    function isNonUserDumpItem(item) {
      if (!item) return true;
      const folder = String(item.folder || '');
      const file = String(item.file || '');
      if (folder === '__SYSTEM__' || folder.indexOf('__SYSTEM__') !== -1) return true;
      if (folder.indexOf('ゴミ箱') !== -1 || file === '削除履歴') return true;
      return false;
    }

    function isUsableDumpHit(item, content) {
      if (!item || isNonUserDumpItem(item) || isTempId(item.id)) return false;
      const id = String(item.id || '');
      if (!id || id.startsWith('local-') || id.startsWith('mig-')) return false;
      return dumpContentEquals(item.content, content);
    }

    function toDumpMatch(item) {
      const isInbox = !!(item && (item.isInbox || historyDestIsInbox(item.folder)));
      return {
        ...item,
        folder: isInbox ? 'INBOX' : normalizeHistoryFolder(item.folder),
        file: isInbox ? '未整理' : (item.file || '未整理'),
        isInbox
      };
    }

    function suppressReplacedHistoryContent(content) {
      const key = dumpContentKey(content);
      if (key) inputHistorySuppressedContents.add(key);
    }

    function unsuppressReplacedHistoryContent(content) {
      const key = dumpContentKey(content);
      if (key) inputHistorySuppressedContents.delete(key);
    }

    function unsuppressReplacedHistoryContents(contents) {
      (contents || []).forEach((c) => unsuppressReplacedHistoryContent(c));
    }

    function sameInputHistoryId(a, b) {
      if (a == null || b == null || a === '' || b === '') return false;
      return String(a) === String(b);
    }

    function dropInputHistoryEntries(matcher) {
      const pending = typeof getPendingInputHistoryIds === 'function' ? getPendingInputHistoryIds() : null;
      const next = getLocalInputHistory().filter((e) => {
        if (!e || matcher(e)) {
          if (e && pending && e.id != null) pending.delete(String(e.id));
          return false;
        }
        return true;
      });
      if (pending && typeof savePendingInputHistoryIds === 'function') savePendingInputHistoryIds(pending);
      cacheLocalInputHistory(next);
      if (Array.isArray(inputHistoryView)) {
        inputHistoryView = inputHistoryView.filter((e) => e && !matcher(e));
      }
      return next;
    }

    function findCachedDumpForHistory(entry) {
      if (!entry || !entry.content) return null;
      if (entry.dumpId && !isTempId(entry.dumpId)) {
        const cachedById = typeof mergePendingDumpsInto === 'function'
          ? mergePendingDumpsInto((storedItemsCache && storedItemsCache.items) || [])
          : [];
        const byId = (cachedById || []).find((r) => r && String(r.id) === String(entry.dumpId) && !isNonUserDumpItem(r));
        if (byId && !isTempId(byId.id)) return byId;
      }
      const cached = typeof mergePendingDumpsInto === 'function'
        ? mergePendingDumpsInto((storedItemsCache && storedItemsCache.items) || [])
        : [];
      const folder = normalizeHistoryFolder(entry.folder);
      const file = entry.file || '未整理';
      const wantInbox = historyDestIsInbox(folder);
      const destHit = (cached || []).find((r) => {
        if (!isUsableDumpHit(r, entry.content)) return false;
        if (wantInbox) return !!(r.isInbox || historyDestIsInbox(r.folder));
        return !r.isInbox && normalizeHistoryFolder(r.folder) === folder && (r.file || '未整理') === file;
      });
      if (destHit) return destHit;
      return (cached || []).find((r) => isUsableDumpHit(r, entry.content)) || null;
    }

    function resolveInputHistoryItemFromCache(entry) {
      if (!entry) return null;
      const wantInbox = historyDestIsInbox(entry.folder);
      const content = String(entry.content || '');
      const folder = normalizeHistoryFolder(entry.folder);
      const file = entry.file || '未整理';
      const destOk = (r) => {
        if (wantInbox) return !!(r.isInbox || historyDestIsInbox(r.folder));
        return !r.isInbox && normalizeHistoryFolder(r.folder) === folder && (r.file || '未整理') === file;
      };
      const cached = typeof mergePendingDumpsInto === 'function'
        ? mergePendingDumpsInto((storedItemsCache && storedItemsCache.items) || [])
        : [];
      if (entry.dumpId && !isTempId(entry.dumpId)) {
        const byId = (cached || []).find((r) => r && String(r.id) === String(entry.dumpId) && !isNonUserDumpItem(r));
        if (byId && !isTempId(byId.id)) return toDumpMatch(byId);
      }
      const localHit = (cached || []).find((r) => isUsableDumpHit(r, content) && destOk(r));
      return localHit ? toDumpMatch(localHit) : null;
    }

    function buildDumpMatchFromPending(pendingReplace) {
      if (!pendingReplace || !pendingReplace.dumpId || isTempId(pendingReplace.dumpId)) return null;
      const origInbox = historyDestIsInbox(normalizeHistoryFolder(pendingReplace.folder));
      const isInbox = pendingReplace.dumpIsInbox != null ? !!pendingReplace.dumpIsInbox : origInbox;
      return {
        id: pendingReplace.dumpId,
        content: pendingReplace.content,
        folder: isInbox ? 'INBOX' : normalizeHistoryFolder(pendingReplace.folder),
        file: isInbox ? '未整理' : (pendingReplace.file || '未整理'),
        isInbox
      };
    }

    function buildPendingDumpResolveEntry(pendingReplace) {
      if (!pendingReplace) return null;
      return {
        content: String(pendingReplace.content || '').trim(),
        folder: normalizeHistoryFolder(pendingReplace.folder),
        file: pendingReplace.file || '未整理',
        dumpId: pendingReplace.dumpId
      };
    }

    async function resolvePendingDumpMatch(pendingReplace, opts = {}) {
      if (!pendingReplace) return null;
      const flush = opts.flush !== false;
      if (flush) await flushInboxWriteChain();
      const resolveEntry = buildPendingDumpResolveEntry(pendingReplace);
      if (!resolveEntry || !resolveEntry.content) return null;
      let match = resolveInputHistoryItemFromCache(resolveEntry)
        || buildDumpMatchFromPending(pendingReplace);
      if (!match || !match.id || isTempId(match.id)) {
        match = await resolveInputHistoryItem(resolveEntry);
      }
      if ((!match || !match.id || isTempId(match.id)) && pendingReplace.dumpId && !isTempId(pendingReplace.dumpId)) {
        match = await resolveDumpByIdFresh(pendingReplace.dumpId, pendingReplace.dumpIsInbox);
      }
      if (match && match.id && !isTempId(match.id)) {
        pendingReplace.dumpId = String(match.id);
        pendingReplace.dumpIsInbox = !!(match.isInbox || historyDestIsInbox(match.folder));
        return match;
      }
      return null;
    }

    function releaseHistoryReplaceSubmitUi(btn) {
      clearSubmitInboxLocks();
      refreshSubmitInboxAvailability();
    }

    async function submitInboxHistoryReplace(rawTyped, lane) {
      const textarea = document.getElementById('input-content');
      const status = document.getElementById('input-status');
      const btn = document.getElementById('submit-inbox-btn');
      const pendingReplace = pendingInputHistoryReplace ? { ...pendingInputHistoryReplace } : null;
      if (!pendingReplace) return;
      if (!String(rawTyped || '').trim() && !dumpComposeImages.length) return;

      const hasImages = dumpComposeImages.length > 0;
      const imagesToUpload = hasImages ? dumpComposeImages.map((img) => ({ ...img })) : [];
      if (hasImages) {
        imagesToUpload.forEach((img) => {
          localPendingImagesMap.set(img.id, img);
        });
        clearDumpComposeImages({ keepBlobs: true, skipDraftSync: true });
      }

      const built = hasImages
        ? appendDumpImagePlaceholders(stripDumpImageTokens(rawTyped), imagesToUpload)
        : rawTyped;
      const newContent = String(built || '').trim();
      if (!newContent) return;
      ensureSubmitInboxReady({ force: true, reason: 'history_replace_start' });

      const origFolder = normalizeHistoryFolder(pendingReplace.folder);
      const origFile = pendingReplace.file || '未整理';
      const origInbox = historyDestIsInbox(origFolder);
      const laneDest = dumpLaneDest(typeof lane === 'string' ? lane : historyEntryLane(pendingReplace));
      const destChanged = laneDest.lane !== historyEntryLane({ folder: origFolder });
      const oldContent = String(pendingReplace.content || '').trim();
      const effectiveIsInboxDest = laneDest.isInbox;
      const effectiveDestFolder = laneDest.folder;
      const effectiveDestFile = laneDest.file;

      if (dumpContentEquals(newContent, oldContent) && !destChanged) {
        if (textarea) {
          textarea.value = '';
          clearInboxInputAfterDump(textarea, newContent, { focus: true });
        }
        enterNewInputModeAfterHistoryEdit({ releaseLocks: true });
        void resetDirectDestUiForNewInput();
        paintInputTabHistory(getLocalInputHistory());
        if (status) {
          status.textContent = '変更がないため保存をスキップしました';
          status.className = 'text-base mt-2 text-center font-bold text-slate-300';
          setTimeout(() => {
            if (status.textContent.includes('スキップ')) status.textContent = '';
          }, 2200);
        }
        return;
      }

      const locationOnly = destChanged && dumpContentEquals(newContent, oldContent);
      ensureSubmitInboxReady({ force: true, reason: 'history_replace' });

      const prevInput = textarea ? textarea.value : '';
      textarea.value = '';
      clearInboxInputAfterDump(textarea, newContent, { focus: true });
      if (typeof textUndoRemember === 'function') textUndoRemember(textarea, prevInput);
      pauseInputHistoryCloudSync();
      let cloudPauseHeld = true;
      const releaseCloudPause = () => {
        if (!cloudPauseHeld) return;
        cloudPauseHeld = false;
        resumeInputHistoryCloudSync();
      };
      try {
        // 編集枠をすぐ消すため、先に編集モードを解除してから楽観更新を描画する
        enterNewInputModeAfterHistoryEdit({ releaseLocks: true });
        if (inputHistoryLaneFilter) {
          inputHistoryLaneFilter = laneDest.lane;
          paintDumpLaneCurrent();
        }
        applyOptimisticInputHistoryReplace(
          pendingReplace,
          newContent,
          oldContent,
          effectiveDestFolder,
          effectiveDestFile
        );
        void resetDirectDestUiForNewInput();
        // clearInboxInputAfterDump 側で focus + 再クリア済み

        const replaceJob = {
          id: makePendingWriteId(),
          type: 'history_replace',
          pendingReplace,
          oldContent,
          newContent,
          destFolder: effectiveDestFolder,
          destFile: effectiveDestFile,
          isInboxDest: effectiveIsInboxDest,
          destChanged,
          origFolder,
          origFile,
          origInbox,
          preResolvedDumpId: pendingReplace.dumpId && !isTempId(pendingReplace.dumpId)
            ? String(pendingReplace.dumpId)
            : '',
          preResolvedDumpIsInbox: pendingReplace.dumpIsInbox,
          pendingImages: imagesToUpload.length ? imagesToUpload : undefined
        };
        const dumpIdForLog = replaceJob.preResolvedDumpId || '';
        const origLabel = origInbox ? 'INBOX' : `${origFolder} > ${origFile}`;
        const destLabel = effectiveIsInboxDest ? 'INBOX' : `${effectiveDestFolder} > ${effectiveDestFile}`;
        let lastHistoryId = '';
        if (locationOnly) {
          lastHistoryId = logOperation('MOVE', `${origLabel} から ${destLabel} へ移動`, {
            oldFolder: origFolder,
            oldFile: origFile,
            newFolder: effectiveDestFolder,
            newFile: effectiveDestFile,
            content: newContent,
            historyEntryId: pendingReplace.id,
            dumpId: dumpIdForLog,
            dumpIsInbox: pendingReplace.dumpIsInbox,
            replaceJobId: replaceJob.id
          });
        } else if (destChanged) {
          lastHistoryId = logOperation('MOVE_EDIT', `${origLabel} から ${destLabel} へ編集して移動`, {
            oldFolder: origFolder,
            oldFile: origFile,
            newFolder: effectiveDestFolder,
            newFile: effectiveDestFile,
            oldContent,
            newContent,
            content: newContent,
            historyEntryId: pendingReplace.id,
            dumpId: dumpIdForLog,
            dumpIsInbox: pendingReplace.dumpIsInbox,
            replaceJobId: replaceJob.id
          });
        } else {
          lastHistoryId = logOperation('EDIT', '登録チェックを編集', {
            folder: effectiveDestFolder,
            file: effectiveDestFile,
            oldContent,
            newContent,
            historyEntryId: pendingReplace.id,
            dumpId: dumpIdForLog,
            dumpIsInbox: pendingReplace.dumpIsInbox,
            replaceJobId: replaceJob.id
          });
        }
        replaceJob.historyId = lastHistoryId;
        if (status) {
          const photoExtraMs = imagesToUpload.length * 4500;
          addSyncGaugeJob(status, {
            id: replaceJob.id,
            historyId: lastHistoryId,
            label: locationOnly ? '✓ 場所の移動を受け付けました' : (imagesToUpload.length ? '✓ 編集を受け付けました (写真アップロード中)' : '✓ 編集を受け付けました'),
            estimateMs: syncGaugeEstimateMs(String(newContent || '').length) + photoExtraMs,
            count: 1,
            undoHtml: syncUndoButtonHtml(lastHistoryId)
          });
        }
        addPendingInboxWrite(replaceJob);
        markPendingWriteQueued(replaceJob.id);

        enqueueInboxWrite(async () => {
          pendingWriteRunningIds.add(replaceJob.id);
          try {
            if (lastHistoryId && cancelledDumpHistoryIds.has(lastHistoryId)) {
              removePendingInboxWrite(replaceJob.id);
              dropSyncGaugeByHistory(lastHistoryId);
              return;
            }
            // 直前DUMPの同期待ち → 実ID取得（閉じてすぐ編集した場合の上書き失敗を防ぐ）
            if (!replaceJob.preResolvedDumpId && oldContent) {
              try {
                await waitForPendingDumpWrites(oldContent, 3000);
              } catch (e) {
                console.warn('waitForPendingDumpWrites failed', e);
              }
              // bindDumpIds が付けた実IDをジョブへ反映（編集UIは既に新規入力へ戻っている）
              if (!replaceJob.preResolvedDumpId) {
                const cached = typeof mergePendingDumpsInto === 'function'
                  ? mergePendingDumpsInto((storedItemsCache && storedItemsCache.items) || [])
                  : (typeof pendingDumpCache !== 'undefined' ? pendingDumpCache : []);
                const hit = (cached || []).find((r) => r && isUsableDumpHit(r, oldContent));
                const fromHistory = getLocalInputHistory().find((e) => e && (
                  (dumpContentEquals(e.content, oldContent) || dumpContentEquals(e.content, newContent))
                  && e.dumpId && !isTempId(e.dumpId)
                ));
                const boundId = (hit && hit.id) ? String(hit.id)
                  : (fromHistory ? String(fromHistory.dumpId) : '');
                if (boundId) {
                  replaceJob.preResolvedDumpId = boundId;
                  replaceJob.preResolvedDumpIsInbox = hit
                    ? !!(hit.isInbox || historyDestIsInbox(hit.folder))
                    : (fromHistory.dumpIsInbox != null ? !!fromHistory.dumpIsInbox : true);
                  pendingReplace.dumpId = boundId;
                  pendingReplace.dumpIsInbox = replaceJob.preResolvedDumpIsInbox;
                }
              }
            }
            // ジョブ内で dump を解決（タイムアウト付き）。UIは既に新規入力へ戻済み。
            if (!replaceJob.preResolvedDumpId) {
              try {
                const resolved = await withTimeout(
                  resolvePendingDumpMatch(pendingReplace, { flush: false }),
                  3500,
                  'resolve_pending_dump'
                );
                if (resolved && resolved.id && !isTempId(resolved.id)) {
                  replaceJob.preResolvedDumpId = String(resolved.id);
                  replaceJob.preResolvedDumpIsInbox = !!(resolved.isInbox || historyDestIsInbox(resolved.folder));
                  pendingReplace.dumpId = replaceJob.preResolvedDumpId;
                  pendingReplace.dumpIsInbox = replaceJob.preResolvedDumpIsInbox;
                }
              } catch (e) {
                console.warn('resolvePendingDumpMatch timed out in job', e);
              }
            }
            if (lastHistoryId && cancelledDumpHistoryIds.has(lastHistoryId)) {
              removePendingInboxWrite(replaceJob.id);
              dropSyncGaugeByHistory(lastHistoryId);
              return;
            }
            const replaceResult = await executeHistoryReplaceJob(replaceJob);
            removePendingInboxWrite(replaceJob.id);
            if (replaceResult && replaceResult.cancelled) {
              if (lastHistoryId) dropSyncGaugeByHistory(lastHistoryId);
              return;
            }
            if (lastHistoryId && cancelledDumpHistoryIds.has(lastHistoryId)) {
              // 同期完了前に取り消し済み → サーバー側を元へ戻す
              if (lastHistoryId) dropSyncGaugeByHistory(lastHistoryId);
              try {
                await reverseHistoryReplaceOnServer(replaceJob);
              } catch (e) {
                console.warn('reverse cancelled history replace', e);
              }
              return;
            }
            if (lastHistoryId) markHistoryOpApplied(lastHistoryId);
            if (status) {
              finishSyncEtaBar(
                status,
                locationOnly ? '✓ 場所を移しました' : '✓ 編集内容を保存しました',
                'text-base mt-2 text-center font-bold text-emerald-400',
                replaceJob.id
              );
              setTimeout(() => {
                if (status.textContent.includes('保存') || status.textContent.includes('移し')) status.textContent = '';
              }, 3000);
            }
          } finally {
            pendingWriteRunningIds.delete(replaceJob.id);
            clearPendingWriteQueued(replaceJob.id);
            const cancelled = !!(lastHistoryId && cancelledDumpHistoryIds.has(lastHistoryId));
            if (!cancelled) {
              upsertLocalInputHistoryReplace({
                fromId: pendingReplace.id,
                toId: pendingReplace.id,
                oldContent,
                newContent,
                folder: effectiveDestFolder,
                file: effectiveDestFile,
                persistTombstone: !dumpContentEquals(oldContent, newContent)
              });
            }
            // 旧本文は suppress/tombstone 維持。ここで外すとクラウド同期で新旧が並ぶ
            inputTabDupToken++;
            inputTabDupMap = Object.create(null);
            // prune 経由だと一瞬消えることがあるので getLocal を直接描画
            if (typeof paintInputTabHistory === 'function') {
              paintInputTabHistory(getLocalInputHistory(), { force: true, skipDupSchedule: true });
            }
            // 描画後に少し待ってから同期再開（直後のクラウドマージで消えないように）
            setTimeout(() => {
              releaseCloudPause();
              if (typeof scheduleInputTabDupEnrichment === 'function') {
                scheduleInputTabDupEnrichment(getLocalInputHistory());
              }
            }, 400);
            ensureSubmitInboxReady({ force: true, reason: 'history_replace_done' });
          }
        }, {
          onError: (err) => {
            if (lastHistoryId && cancelledDumpHistoryIds.has(lastHistoryId)) return;
            clearPendingWriteQueued(replaceJob.id);
            bumpPendingInboxWriteAttempt(replaceJob.id);
            releaseCloudPause();
            const isTimeoutOrNetwork = err && (
              err.isTimeout === true
              || err.name === 'AbortError'
              || String(err.message).includes('timeout')
              || String(err.message).includes('aborted')
              || !navigator.onLine
            );
            if (isTimeoutOrNetwork) {
              console.warn('History replace deferred to pending writes (timeout/offline):', replaceJob.id);
              if (status) {
                settleSyncGaugeJob(status, replaceJob.id, {
                  doneText: `✓ 端末に保存しました（電波回復時に自動送信）`,
                  className: 'text-base mt-2 text-center font-bold text-cyan-300'
                });
              }
              ensureSubmitInboxReady({ force: true, reason: 'replace_timeout_saved' });
              return;
            }
            inboxInputClearToken++;
            replaceLocalInputHistoryEntry(pendingReplace.id, oldContent, origFolder, origFile);
            unsuppressReplacedHistoryContent(oldContent);
            if (!dumpContentEquals(oldContent, newContent)) suppressReplacedHistoryContent(newContent);
            forgetDumpedItemsByContents([newContent], { includeStored: true });
            if (oldContent) {
              rememberDumpedItems([{
                id: pendingReplace.dumpId || undefined,
                content: oldContent,
                folder: origInbox ? '📥 INBOX' : origFolder,
                file: origFile,
                isInbox: origInbox
              }]);
            }
            pendingInputHistoryReplace = { ...pendingReplace };
            inputHistoryReplaceBackup = '';
            setInputHistoryReplaceHint(true);
            paintInputHistoryListNow({ skipDupSchedule: true });
            ensureSubmitInboxReady({ force: true, reason: 'history_replace_error' });
            if (!textarea.value.trim()) textarea.value = rawTyped;
            else textarea.value = rawTyped + '\n\n' + textarea.value;
            const reason = err && err.message === 'write'
              ? 'サーバーへの保存に失敗しました'
              : (err && err.message ? String(err.message) : '通信エラー');
            if (status) {
              settleSyncGaugeJob(status, replaceJob.id, {
                failed: true,
                doneText: `エラー（${reason}）。編集内容を復元しました（再開時に再同期します）`,
                className: 'text-base mt-2 text-center font-bold text-rose-400'
              });
            }
          }
        });
      } catch (e) {
        releaseCloudPause();
        ensureSubmitInboxReady({ force: true, reason: 'history_replace_throw' });
        throw e;
      }
    }

    async function syncDirectDestUiForHistoryEntry(entry) {
      const empty = { uiFolder: '', uiFile: '' };
      if (!entry || !isDirectDestinationEnabled()) return empty;
      const folderEl = document.getElementById('direct-folder');
      const fileEl = document.getElementById('direct-file');
      if (!folderEl || !fileEl) return empty;
      const wantInbox = historyDestIsInbox(entry.folder);
      if (wantInbox) {
        folderEl.value = '';
        await onDirectFolderChange();
      } else {
        const folder = normalizeHistoryFolder(entry.folder);
        if (folder && Object.prototype.hasOwnProperty.call(configData, folder)) {
          folderEl.value = folder;
          await onDirectFolderChange();
          const file = entry.file || '未整理';
          if (configData[folder] && configData[folder].includes(file)) {
            fileEl.value = file;
          }
          void onDirectFileChange();
        } else {
          folderEl.value = '';
          await onDirectFolderChange();
        }
      }
      return { uiFolder: folderEl.value || '', uiFile: fileEl.value || '' };
    }

    async function moveDumpMatchToDest(match, destFolder, destFile, isInboxDest) {
      if (!match || !match.id || isTempId(match.id)) return false;
      const curInbox = !!(match.isInbox || historyDestIsInbox(match.folder));
      const targetFolder = isInboxDest ? 'INBOX' : destFolder;
      const targetFile = isInboxDest ? '未整理' : destFile;
      if (curInbox && isInboxDest) return true;
      if (!curInbox && !isInboxDest
        && normalizeHistoryFolder(match.folder) === normalizeHistoryFolder(targetFolder)
        && (match.file || '未整理') === targetFile) return true;

      // DATA -> INBOX への移動（GASの moveDataRecord は DATA内で folder を変えるだけのため、確実に INBOX へ移す）
      if (!curInbox && isInboxDest) {
        let content = match.content;
        if (!content && typeof resolveDumpByIdFresh === 'function') {
          try {
            const fresh = await resolveDumpByIdFresh(match.id, false);
            if (fresh && fresh.content) content = fresh.content;
          } catch (_) { }
        }
        if (!content && typeof storedItemsCache !== 'undefined' && Array.isArray(storedItemsCache.items)) {
          const hit = storedItemsCache.items.find((i) => i && String(i.id) === String(match.id));
          if (hit && hit.content) content = hit.content;
        }
        const ops = [
          { action: 'deleteDataRecords', ids: [String(match.id)] },
          { action: 'addInbox', content: String(content || '') }
        ];
        const res = await callBatch(ops, { silent: true });
        if (isApiFailure(res)) return false;
        match.isInbox = true;
        match.folder = 'INBOX';
        match.file = '未整理';
        return true;
      }

      const payload = { id: match.id, folder: targetFolder, file: targetFile };
      const res = curInbox
        ? await callAPI('moveInboxItem', payload, { silent: true })
        : await callAPI('moveDataRecord', payload, { silent: true });
      if (isApiFailure(res)) {
        const fallback = curInbox
          ? await callAPI('moveDataRecord', payload, { silent: true })
          : await callAPI('moveInboxItem', payload, { silent: true });
        if (isApiFailure(fallback)) return false;
        match.isInbox = !curInbox;
      } else {
        match.isInbox = isInboxDest;
      }
      match.folder = isInboxDest ? 'INBOX' : targetFolder;
      match.file = targetFile;
      return true;
    }

    async function resolveDumpByIdFresh(id, preferInbox) {
      if (!id || isTempId(id)) return null;
      const target = String(id);
      const tryInbox = preferInbox !== false;
      const tryData = preferInbox !== true;

      if (tryInbox) {
        try {
          const data = await callAPI('getOrganizerData', { fresh: true }, { silent: true });
          if (data && Array.isArray(data.inbox)) {
            const inboxHit = data.inbox.find((r) => r && String(r.id) === target);
            if (inboxHit) {
              return toDumpMatch({ ...inboxHit, folder: 'INBOX', file: '未整理', isInbox: true });
            }
          }
        } catch (e) {
          console.warn('resolveDumpByIdFresh inbox lookup failed', e);
        }
      }

      const cached = typeof mergePendingDumpsInto === 'function'
        ? mergePendingDumpsInto((storedItemsCache && storedItemsCache.items) || [])
        : [];
      const cacheHit = (cached || []).find((r) => r && String(r.id) === target && !isNonUserDumpItem(r));
      if (cacheHit) return toDumpMatch(cacheHit);

      // preferInbox でも見つからないときは DATA 側も探す（フラグ誤りで新規追加になるのを防ぐ）
      try {
        const keyword = target.length > 8 ? target.slice(0, 8) : target;
        const results = await callAPI('searchData', { keyword }, { silent: true });
        const searchHit = (Array.isArray(results) ? results : []).find((r) => r && String(r.id) === target);
        if (searchHit) return toDumpMatch(searchHit);
      } catch (e) {
        console.warn('resolveDumpByIdFresh search fallback failed', e);
      }
      if (!tryData) return null;
      return null;
    }

    async function updateDumpByKnownId(dumpId, newContent, preferInbox) {
      if (!dumpId || isTempId(dumpId) || !String(newContent || '').trim()) {
        return { success: false, error: 'invalid' };
      }
      const id = String(dumpId);
      const inboxFirst = preferInbox !== false;
      const order = inboxFirst
        ? ['updateInbox', 'updateDataRecord']
        : ['updateDataRecord', 'updateInbox'];
      let last = null;
      for (const action of order) {
        const res = action === 'updateInbox'
          ? await callAPI('updateInbox', { id, content: newContent }, { silent: true })
          : await callAPI('updateDataRecord', { id, content: newContent }, { silent: true });
        last = res;
        if (!isApiFailure(res)) {
          return { success: true, id, isInbox: action === 'updateInbox', res };
        }
      }
      return { success: false, error: (last && last.error) || 'not_found', id };
    }

    async function findExactDumpHitsOnServer(content, scope) {
      const hits = [];
      const seen = new Set();
      const pushHit = (row, isInbox) => {
        if (!row || row.id == null || isTempId(row.id) || isNonUserDumpItem(row)) return;
        if (!dumpContentEquals(row.content, content)) return;
        const id = String(row.id);
        if (seen.has(id)) return;
        seen.add(id);
        hits.push(toDumpMatch({
          ...row,
          folder: isInbox ? 'INBOX' : (row.folder || scope && scope.folder),
          file: isInbox ? '未整理' : (row.file || scope && scope.file || '未整理'),
          isInbox: !!isInbox
        }));
      };
      const opts = scope || {};
      if (opts.inbox !== false) {
        try {
          const data = await callAPI('getOrganizerData', { fresh: true }, { silent: true });
          if (data && Array.isArray(data.inbox)) data.inbox.forEach((r) => pushHit(r, true));
        } catch (e) {
          console.warn('findExactDumpHitsOnServer inbox scan failed', e);
        }
      }
      if (opts.folder && opts.file) {
        try {
          const items = await callAPI('getFolderFileItems', { folder: opts.folder, file: opts.file }, { silent: true });
          if (Array.isArray(items)) items.forEach((r) => pushHit(r, false));
        } catch (e) {
          console.warn('findExactDumpHitsOnServer folder scan failed', e);
        }
      }
      if (opts.anywhere) {
        try {
          const keyword = searchKeywordForDump(content);
          if (keyword) {
            const results = await callAPI('searchData', { keyword }, { silent: true });
            (Array.isArray(results) ? results : []).forEach((r) => pushHit(r, !!(r.isInbox || historyDestIsInbox(r.folder))));
          }
        } catch (e) {
          console.warn('findExactDumpHitsOnServer search fallback failed', e);
        }
      }
      return hits;
    }

    async function trashExactDumpHits(hits, exceptId) {
      const keep = exceptId != null ? String(exceptId) : null;
      for (const hit of hits || []) {
        if (!hit || hit.id == null || isTempId(hit.id)) continue;
        if (keep && String(hit.id) === keep) continue;
        await trashDumpMatch(hit);
      }
    }

    async function replaceStoredDumpOnServer({
      oldContent,
      newContent,
      destFolder,
      destFile,
      isInboxDest,
      pendingReplace,
      preResolvedMatch
    }) {
      const origFolder = normalizeHistoryFolder(pendingReplace.folder);
      const origFile = pendingReplace.file || '未整理';
      const origInbox = historyDestIsInbox(origFolder);
      const destSame = (isInboxDest && origInbox) || (
        !isInboxDest && !origInbox
        && normalizeHistoryFolder(destFolder) === origFolder
        && destFile === origFile
      );

      const knownDumpId = (preResolvedMatch && preResolvedMatch.id && !isTempId(preResolvedMatch.id)
        ? String(preResolvedMatch.id)
        : '')
        || (pendingReplace.dumpId && !isTempId(pendingReplace.dumpId)
          ? String(pendingReplace.dumpId)
          : '');
      const knownIsInbox = preResolvedMatch
        ? !!(preResolvedMatch.isInbox || historyDestIsInbox(preResolvedMatch.folder))
        : (pendingReplace.dumpIsInbox != null ? !!pendingReplace.dumpIsInbox : origInbox);

      // 1) dumpId があるなら本文一致を待たず ID で上書き（スマホで最優先）
      if (knownDumpId) {
        const byId = await updateDumpByKnownId(knownDumpId, newContent, knownIsInbox);
        if (byId.success) {
          const match = {
            id: knownDumpId,
            content: newContent,
            folder: isInboxDest ? 'INBOX' : destFolder,
            file: isInboxDest ? '未整理' : destFile,
            isInbox: byId.isInbox != null ? byId.isInbox : isInboxDest
          };
          if (!destSame) {
            await moveDumpMatchToDest(match, destFolder, destFile, isInboxDest);
          }
          patchStoredDumpById(knownDumpId, {
            content: newContent,
            folder: isInboxDest ? '📥 INBOX' : destFolder,
            file: isInboxDest ? '未整理' : destFile,
            isInbox: isInboxDest
          });
          // 同本文の別コピーがあれば掃除
          try {
            const oldHits = await findExactDumpHitsOnServer(oldContent, {
              inbox: true,
              folder: origInbox ? null : origFolder,
              file: origInbox ? null : origFile,
              anywhere: true
            });
            await trashExactDumpHits(oldHits, knownDumpId);
          } catch (e) {
            console.warn('trash leftover after id-update failed', e);
          }
          return { updatedInPlace: true, match, keptId: knownDumpId, isInboxDest, destSame };
        }
      }

      let oldHits = [];
      try {
        oldHits = await findExactDumpHitsOnServer(oldContent, {
          inbox: true,
          folder: origInbox ? null : origFolder,
          file: origInbox ? null : origFile,
          anywhere: true
        });
      } catch (e) {
        console.warn('findExactDumpHitsOnServer(old) failed', e);
      }

      let match = preResolvedMatch || null;
      if ((!match || !match.id || isTempId(match.id)) && knownDumpId) {
        match = {
          id: knownDumpId,
          content: oldContent,
          folder: knownIsInbox ? 'INBOX' : origFolder,
          file: knownIsInbox ? '未整理' : origFile,
          isInbox: knownIsInbox
        };
      }
      if (!match || !match.id || isTempId(match.id)) {
        match = await resolvePendingDumpMatch(pendingReplace, { flush: false });
      }
      if (knownDumpId) {
        const byId = oldHits.find((h) => String(h.id) === String(knownDumpId));
        if (byId) match = byId;
        else if (!match || String(match.id) !== String(knownDumpId)) {
          try {
            const idHit = await withTimeout(
              resolveDumpByIdFresh(knownDumpId, null),
              6000,
              'resolve_dump_id'
            );
            if (idHit) {
              match = idHit;
              if (!oldHits.some((h) => String(h.id) === String(idHit.id))) oldHits.push(idHit);
            }
          } catch (e) {
            console.warn('resolveDumpByIdFresh timed out', e);
          }
        }
      }
      if (!match) {
        try {
          match = await withTimeout(
            resolveInputHistoryItem({
              content: oldContent,
              folder: origFolder,
              file: origFile,
              dumpId: pendingReplace.dumpId
            }),
            6000,
            'resolve_history_item'
          );
          if (match && !oldHits.some((h) => String(h.id) === String(match.id))) oldHits.push(match);
        } catch (e) {
          console.warn('resolveInputHistoryItem timed out', e);
        }
      }
      if (!match && oldHits.length) match = oldHits[0];

      let updatedInPlace = false;
      let keptId = null;

      async function applyInPlaceUpdate(hit) {
        if (!hit || !hit.id || isTempId(hit.id)) return false;
        const preferInbox = !!(hit.isInbox || historyDestIsInbox(hit.folder));
        let resolvedIsInbox = preferInbox;
        const byId = await updateDumpByKnownId(hit.id, newContent, preferInbox);
        if (byId && byId.success) {
          if (byId.isInbox != null) resolvedIsInbox = !!byId.isInbox;
        } else {
          const res = await updateDumpContent(hit, newContent);
          if (isApiFailure(res)) return false;
          if (hit.isInbox != null) resolvedIsInbox = !!hit.isInbox;
        }
        updatedInPlace = true;
        keptId = String(hit.id);
        match = hit;
        if (!destSame) {
          await moveDumpMatchToDest({
            ...hit,
            isInbox: resolvedIsInbox
          }, destFolder, destFile, isInboxDest);
        }
        patchStoredDumpById(hit.id, {
          content: newContent,
          folder: isInboxDest ? '📥 INBOX' : destFolder,
          file: isInboxDest ? '未整理' : destFile,
          isInbox: isInboxDest
        });
        return true;
      }

      if (match && match.id && !isTempId(match.id)) {
        await applyInPlaceUpdate(match);
      }

      // 旧本文ヒットがある限り、必ずそのIDで上書きを試みる（新規追加に落とさない）
      if (!updatedInPlace && oldHits.length) {
        for (const hit of oldHits) {
          if (match && hit && String(hit.id) === String(match.id)) continue;
          if (await applyInPlaceUpdate(hit)) break;
        }
      }

      // addManyInbox は旧ヒット0件のときだけ許可。ヒットありで update 失敗なら再試行させる
      if (!updatedInPlace) {
        if (oldHits.length > 0) {
          throw new Error('update_inplace_failed');
        }
        // 他端末が既に新本文を書いていれば新規追加せずそのIDを採用
        let existingNew = [];
        try {
          existingNew = await findExactDumpHitsOnServer(newContent, {
            inbox: isInboxDest,
            folder: isInboxDest ? null : destFolder,
            file: isInboxDest ? null : destFile,
            anywhere: false
          });
        } catch (e) {
          console.warn('existing newContent scan failed', e);
        }
        if (existingNew.length) {
          keptId = String(existingNew[0].id);
          updatedInPlace = true;
          match = existingNew[0];
        } else {
          const written = await writeNewDumpForReplace(newContent, destFolder, destFile, isInboxDest);
          if (written && written.id) keptId = String(written.id);
          if (written && written.alreadyExisted) updatedInPlace = true;
        }
        if (knownDumpId && !updatedInPlace) {
          await trashDumpMatch({
            id: knownDumpId,
            isInbox: knownIsInbox,
            folder: knownIsInbox ? 'INBOX' : origFolder,
            file: knownIsInbox ? '未整理' : origFile
          });
        }
      }

      await trashExactDumpHits(oldHits, updatedInPlace ? keptId : null);

      if (keptId && pendingReplace) {
        pendingReplace.dumpId = String(keptId);
        pendingReplace.dumpIsInbox = isInboxDest;
      }

      return { updatedInPlace, match, keptId, isInboxDest, destSame };
    }

    async function refreshPendingDumpBinding(entry) {
      if (!entry || !pendingInputHistoryReplace) return;
      const pending = pendingInputHistoryReplace;
      const sameEntry = (entry.id && sameInputHistoryId(entry.id, pending.id))
        || dumpContentEquals(entry.content, pending.content);
      if (!sameEntry) return;
      const match = await resolvePendingDumpMatch(pending);
      if (!match || !match.id || isTempId(match.id)) return;
      if (!pendingInputHistoryReplace || !sameInputHistoryId(entry.id, pendingInputHistoryReplace.id)) return;
      pendingInputHistoryReplace.dumpId = String(match.id);
      pendingInputHistoryReplace.dumpIsInbox = !!(match.isInbox || historyDestIsInbox(match.folder));
    }

    async function updateDumpContent(match, newContent) {
      if (!match || !match.id) return { success: false, error: 'invalid' };
      const inboxFirst = !!match.isInbox;
      const first = inboxFirst
        ? await callAPI('updateInbox', { id: match.id, content: newContent }, { silent: true })
        : await callAPI('updateDataRecord', { id: match.id, content: newContent }, { silent: true });
      if (!isApiFailure(first)) return first;
      const second = inboxFirst
        ? await callAPI('updateDataRecord', { id: match.id, content: newContent }, { silent: true })
        : await callAPI('updateInbox', { id: match.id, content: newContent }, { silent: true });
      if (!isApiFailure(second)) {
        match.isInbox = !inboxFirst;
        return second;
      }
      return first;
    }

    function rollbackOptimisticUndoDelete(op) {
      const contents = deleteContentsFromUndoPayload((op && op.payload) || {});
      if (typeof dropInputHistoryEntries === 'function' && contents.length) {
        dropInputHistoryEntries((e) => contents.some((c) => dumpContentEquals(e.content, c)));
      }
      contents.forEach((content) => {
        if (typeof suppressReplacedHistoryContent === 'function') suppressReplacedHistoryContent(content);
      });
      if (typeof paintInputTabHistory === 'function') {
        paintInputTabHistory(typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : [], { force: true });
      }
      if (typeof refreshCheckBlocksListIfVisible === 'function') refreshCheckBlocksListIfVisible();
    }

    async function trashDumpMatch(match) {
      if (!match || !match.id || isTempId(match.id)) return false;
      if (match.content && isDumpContentShieldedFromTrash(match.content)) return false;
      const payload = { id: String(match.id), folder: '🗑️ ゴミ箱', file: '削除履歴' };
      const preferInbox = !!(match.isInbox || (typeof historyDestIsInbox === 'function' && historyDestIsInbox(match.folder)));
      const order = preferInbox
        ? ['moveInboxItem', 'moveDataRecord']
        : ['moveDataRecord', 'moveInboxItem'];
      for (let i = 0; i < order.length; i++) {
        const res = await callAPI(order[i], payload, { silent: true });
        if (!isApiFailure(res)) return true;
      }
      console.warn('failed to trash dump match', match && match.id);
      return false;
    }

    async function trashRemainingDumpsByContent(oldContent) {
      const hits = await findDumpHitsByContent(oldContent);
      for (const hit of hits) {
        await trashDumpMatch(hit);
      }
    }

    async function writeNewDumpForReplace(content, destFolder, destFile, isInboxDest) {
      // 他端末が先に同本文を保存済みなら新規追加しない（PC常時起動×スマホ編集の増殖防止）
      try {
        const existing = await findExactDumpHitsOnServer(content, {
          inbox: isInboxDest,
          folder: isInboxDest ? null : destFolder,
          file: isInboxDest ? null : destFile,
          anywhere: false
        });
        if (existing && existing.length) {
          const hit = existing[0];
          return {
            id: hit && hit.id != null ? String(hit.id) : '',
            isInbox: !!(hit && (hit.isInbox || historyDestIsInbox(hit.folder))),
            alreadyExisted: true
          };
        }
      } catch (e) {
        console.warn('writeNewDumpForReplace existing check failed', e);
      }
      if (isInboxDest) {
        // 二重投稿の最後の歯止め
        if (typeof filterDumpChunksMissingOnServer === 'function') {
          const missing = await filterDumpChunksMissingOnServer([content], { inbox: true });
          if (!missing.length) {
            const again = await findExactDumpHitsOnServer(content, { inbox: true, anywhere: false });
            if (again && again[0] && again[0].id != null) {
              return { id: String(again[0].id), isInbox: true, alreadyExisted: true };
            }
          }
        }
        const writeRes = await callAPI('addManyInbox', { contents: [content] }, { silent: true });
        assertWriteResult(writeRes, 1);
        const id = Array.isArray(writeRes && writeRes.ids) && writeRes.ids[0]
          ? String(writeRes.ids[0])
          : '';
        return { id, isInbox: true };
      }
      if (!configData[destFolder]) configData[destFolder] = [];
      if (!configData[destFolder].includes(destFile)) {
        configData[destFolder].push(destFile);
        await callAPI('addConfigRecord', { folder: destFolder, file: destFile }, { silent: true });
      }
      const writeRes = await callAPI('addManyDataRecords', {
        items: [{ folder: destFolder, file: destFile, content }]
      }, { silent: true });
      assertWriteResult(writeRes, 1);
      const id = Array.isArray(writeRes && writeRes.ids) && writeRes.ids[0]
        ? String(writeRes.ids[0])
        : '';
      return { id, isInbox: false };
    }

    function replaceLocalInputHistoryEntry(id, content, folder, file) {
      upsertLocalInputHistoryReplace({
        fromId: id,
        toId: id,
        oldContent: null,
        newContent: content,
        folder,
        file
      });
    }

    /** 編集中ジョブの「変更前本文」キー（クラウドマージ／backfill で旧行を戻さない） */
    function pendingHistoryReplaceOldContentKeys() {
      const keys = new Set();
      if (typeof getPendingInboxWrites !== 'function') return keys;
      getPendingInboxWrites().forEach((j) => {
        if (!j || j.type !== 'history_replace') return;
        if (dumpContentEquals(j.oldContent, j.newContent)) return;
        const k = dumpContentKey(j.oldContent);
        if (k) keys.add(k);
      });
      return keys;
    }

    /** 編集置き換え後は「旧本文／新本文／旧ID／新ID」を1件に畳む（二重表示防止） */
    function upsertLocalInputHistoryReplace({ fromId, toId, oldContent, newContent, folder, file, persistTombstone, skipPaint, onlyIfExists }) {
      const content = String(newContent || '').trim();
      if (!isUsableInputHistoryContent(content)) return null;
      const oldKey = oldContent != null ? dumpContentKey(oldContent) : '';
      const newKey = dumpContentKey(content);
      const laneOnly = !!(oldKey && newKey && oldKey === newKey);
      // 本文が変わった編集は、クラウド反映前でも旧本文を永続的に隠す（新旧並び防止）
      const shouldPersistTombstone = persistTombstone === true
        || (persistTombstone !== false && !laneOnly && !!oldKey);
      if (laneOnly) {
        // 本文が同じ場所移動。suppress / tombstone すると移動先の行ごと消える
        inputHistorySuppressedContents.delete(newKey);
        inputHistoryTombstoneKeys.delete(newKey);
        if (typeof persistHistoryTombstones === 'function') persistHistoryTombstones();
      } else if (oldKey) {
        inputHistorySuppressedContents.add(oldKey);
        if (shouldPersistTombstone) {
          // 復活保護が付いていると tombstone が無視され、編集前の本文が登録チェックに残る
          if (typeof clearInputHistoryResurrected === 'function') clearInputHistoryResurrected(oldContent);
          inputHistoryTombstoneKeys.add(oldKey);
          if (typeof persistHistoryTombstones === 'function') persistHistoryTombstones();
        }
      }

      if (newKey && newKey !== oldKey) {
        inputHistorySuppressedContents.delete(newKey);
        inputHistoryTombstoneKeys.delete(newKey);
      }

      let local = getLocalInputHistory();
      let keptMeta = null;
      const considerMeta = (e) => {
        if (!e) return;
        if (!keptMeta || historyEntryTimestampMs(e) >= historyEntryTimestampMs(keptMeta)) keptMeta = e;
      };
      const wantIds = new Set([fromId, toId].filter(Boolean).map(String));
      const absorb = (e) => {
        if (!e) return;
        const id = e.id != null ? String(e.id) : '';
        const ck = dumpContentKey(e.content);
        if ((id && wantIds.has(id)) || (oldKey && ck === oldKey) || (newKey && ck === newKey)) considerMeta(e);
      };
      if (Array.isArray(localInputHistoryCache)) localInputHistoryCache.forEach(absorb);
      try {
        const raw = JSON.parse(localStorage.getItem(INPUT_HISTORY_KEY) || '[]');
        (Array.isArray(raw) ? raw : []).map(sanitizeInputHistoryEntry).filter(Boolean).forEach(absorb);
      } catch (_) { }
      local = local.filter((e) => {
        if (!e || !e.content) return false;
        const id = e.id != null ? String(e.id) : '';
        const ck = dumpContentKey(e.content);
        const drop = (oldKey && ck === oldKey)
          || (newKey && ck === newKey)
          || (fromId && id === String(fromId))
          || (toId && id === String(toId));
        if (drop) {
          if (!keptMeta || historyEntryTimestampMs(e) >= historyEntryTimestampMs(keptMeta)) {
            keptMeta = e;
          }
          return false;
        }
        return true;
      });

      const preferId = (toId && String(toId))
        || (fromId && String(fromId))
        || (keptMeta && keptMeta.id != null ? String(keptMeta.id) : '')
        || `local-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
      if (preferId && inputHistoryTombstoneIds.has(String(preferId))) {
        inputHistoryTombstoneIds.delete(String(preferId));
        if (typeof persistHistoryTombstones === 'function') persistHistoryTombstones();
      }

      // 編集後は旧 dump 本文をキャッシュから落とし、重複バッジの誤表示を防ぐ
      if (oldKey && typeof forgetDumpedItemsByContents === 'function') {
        forgetDumpedItemsByContents([oldContent], { includeStored: true });
      }
      if (onlyIfExists && !keptMeta && !fromId) {
        saveLocalInputHistory(local);
        if (!skipPaint) {
          if (typeof renderInputTabHistory === 'function') renderInputTabHistory();
          if (typeof renderInputHistoryView === 'function' && currentSearchTabMode === 'input_history') {
            renderInputHistoryView();
          }
        }
        return null;
      }

      const next = {
        ...(keptMeta || {}),
        id: preferId,
        timestamp: (keptMeta && keptMeta.timestamp) || new Date().toISOString(),
        content,
        folder: folder || (keptMeta && keptMeta.folder) || 'INBOX',
        file: file || (keptMeta && keptMeta.file) || '未整理',
        dumpIsInbox: historyDestIsInbox(folder || (keptMeta && keptMeta.folder) || 'INBOX')
      };
      if (keptMeta && keptMeta.dumpId && !next.dumpId) next.dumpId = keptMeta.dumpId;
      if (keptMeta && keptMeta.dumpIsInbox != null && next.dumpIsInbox == null) {
        next.dumpIsInbox = keptMeta.dumpIsInbox;
      }
      // 同期完了前に閉じても、編集後本文が端末キャッシュに残るようにする
      if (typeof rememberDumpedItems === 'function' && next.dumpId && !isTempId(next.dumpId)) {
        const isInbox = next.dumpIsInbox != null
          ? !!next.dumpIsInbox
          : historyDestIsInbox(next.folder);
        rememberDumpedItems([{
          id: String(next.dumpId),
          content,
          timestamp: next.timestamp || new Date().toISOString(),
          folder: isInbox ? '📥 INBOX' : (next.folder || 'INBOX'),
          file: isInbox ? '未整理' : (next.file || '未整理'),
          isInbox,
          _pending: true
        }]);
      } else if (typeof rememberDumpedItems === 'function') {
        rememberDumpedItems([{
          id: makeTempId(),
          content,
          timestamp: next.timestamp || new Date().toISOString(),
          folder: historyDestIsInbox(next.folder) ? '📥 INBOX' : (next.folder || 'INBOX'),
          file: historyDestIsInbox(next.folder) ? '未整理' : (next.file || '未整理'),
          isInbox: historyDestIsInbox(next.folder),
          _pending: true
        }]);
      }
      local.unshift(next);
      cacheLocalInputHistory(local);
      if (!skipPaint) {
        if (typeof refreshInputTabHistoryAfterLocalChange === 'function') {
          refreshInputTabHistoryAfterLocalChange([next], {
            removeContents: oldContent ? [oldContent] : [],
            skipDupSchedule: true
          });
        } else if (typeof paintInputTabHistory === 'function') {
          paintInputTabHistory(getLocalInputHistory(), { skipDupSchedule: true });
        }
      }
      return next;
    }

    function dedupeInputHistoryEntriesByContent(entries) {
      const seen = new Set();
      const out = [];
      (entries || []).forEach((e) => {
        if (!e || !e.content) return;
        const k = dumpContentKey(e.content);
        if (!k || seen.has(k)) return;
        seen.add(k);
        out.push(e);
      });
      return out;
    }

    const DUMP_LANE_LABEL_KEY = 'dump_lane_labels_v1';
    const DUMP_LANE_LABEL_DEFAULT = { inbox: 'INBOX', todo: 'やることリスト', log: 'ログ' };
    const DUMP_LANE_LABEL_SHORT = { inbox: 'INBOX', todo: 'やること', log: 'ログ' };
    const DUMP_LANE_LABEL_MAX = 16;
    let dumpLaneCustomLabels = {};

    function normalizeDumpLaneKey(lane) {
      return lane === 'todo' || lane === 'log' ? lane : 'inbox';
    }

    function loadDumpLaneCustomLabels() {
      try {
        const raw = JSON.parse(localStorage.getItem(DUMP_LANE_LABEL_KEY) || '{}');
        const out = {};
        ['inbox', 'todo', 'log'].forEach((lane) => {
          const name = String(raw && raw[lane] || '').replace(/\s+/g, ' ').trim().slice(0, DUMP_LANE_LABEL_MAX);
          if (name && name !== DUMP_LANE_LABEL_DEFAULT[lane]) out[lane] = name;
        });
        return out;
      } catch (e) {
        return {};
      }
    }

    function dumpLaneLabel(lane, opts) {
      const key = normalizeDumpLaneKey(lane);
      if (dumpLaneCustomLabels[key]) return dumpLaneCustomLabels[key];
      if (opts && opts.short) return DUMP_LANE_LABEL_SHORT[key];
      return DUMP_LANE_LABEL_DEFAULT[key];
    }

    function applyDumpLaneLabels() {
      [
        ['submit-inbox-btn', 'inbox'],
        ['submit-todo-btn', 'todo'],
        ['submit-log-btn', 'log']
      ].forEach(([id, lane]) => {
        const btn = document.getElementById(id);
        if (!btn) return;
        btn.textContent = dumpLaneLabel(lane);
        btn.title = '長押しで名前を変更';
        bindLaneLabelLongPress(btn, lane);
      });
      document.querySelectorAll('.blocks-lane-tab').forEach((btn) => {
        const lane = normalizeDumpLaneKey(btn.getAttribute('data-blocks-lane'));
        btn.textContent = dumpLaneLabel(lane);
        btn.title = '長押しで名前を変更';
        bindLaneLabelLongPress(btn, lane);
      });
      [
        ['search-bulk-lane-inbox', 'inbox'],
        ['search-bulk-lane-todo', 'todo'],
        ['search-bulk-lane-log', 'log']
      ].forEach(([id, lane]) => {
        const btn = document.getElementById(id);
        if (btn) btn.textContent = dumpLaneLabel(lane, { short: true }) + 'へ';
      });
    }

    function saveDumpLaneLabel(lane, name) {
      const key = normalizeDumpLaneKey(lane);
      const next = String(name || '').replace(/\s+/g, ' ').trim().slice(0, DUMP_LANE_LABEL_MAX);
      if (!next || next === DUMP_LANE_LABEL_DEFAULT[key]) delete dumpLaneCustomLabels[key];
      else dumpLaneCustomLabels[key] = next;
      try {
        localStorage.setItem(DUMP_LANE_LABEL_KEY, JSON.stringify(dumpLaneCustomLabels));
      } catch (e) { }
      applyDumpLaneLabels();
      if (typeof paintInputTabHistory === 'function' && typeof getLocalInputHistory === 'function') {
        paintInputTabHistory(getLocalInputHistory(), { skipDupSchedule: true });
      }
      const searchMode = document.getElementById('search-mode');
      if (searchMode && searchMode.classList.contains('active') && typeof renderSearchResultsView === 'function' && searchResults && searchResults.length) {
        renderSearchResultsView();
      }
    }

    function editDumpLaneLabel(lane) {
      const key = normalizeDumpLaneKey(lane);
      const current = dumpLaneLabel(key);
      const next = window.prompt('ボタン名を入力（空欄で元の名前に戻します）', current);
      if (next == null) return;
      saveDumpLaneLabel(key, next);
    }

    function bindLaneLabelLongPress(btn, lane) {
      if (!btn || btn.dataset.laneLabelBound === '1') return;
      btn.dataset.laneLabelBound = '1';
      let timer = 0;
      let startX = 0;
      let startY = 0;
      const clearTimer = () => {
        if (!timer) return;
        clearTimeout(timer);
        timer = 0;
      };
      btn.addEventListener('pointerdown', (e) => {
        if (e.button != null && e.button !== 0) return;
        clearTimer();
        startX = e.clientX;
        startY = e.clientY;
        timer = setTimeout(() => {
          timer = 0;
          btn.dataset.laneLabelHold = '1';
          try { if (navigator.vibrate) navigator.vibrate(12); } catch (_) { }
          editDumpLaneLabel(lane);
          setTimeout(() => { delete btn.dataset.laneLabelHold; }, 700);
        }, 560);
      });
      btn.addEventListener('pointermove', (e) => {
        if (!timer) return;
        if (Math.hypot(e.clientX - startX, e.clientY - startY) > 14) clearTimer();
      });
      btn.addEventListener('pointerup', clearTimer);
      btn.addEventListener('pointercancel', clearTimer);
      btn.addEventListener('contextmenu', (e) => e.preventDefault());
      btn.addEventListener('click', (e) => {
        if (btn.dataset.laneLabelHold !== '1') return;
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        delete btn.dataset.laneLabelHold;
      }, true);
    }

    function initDumpLaneLabels() {
      dumpLaneCustomLabels = loadDumpLaneCustomLabels();
      applyDumpLaneLabels();
    }
    initDumpLaneLabels();

    function dumpLaneDest(lane) {
      if (lane === 'todo') {
        return { lane: 'todo', folder: 'やることリスト', file: '未整理', isInbox: false, label: dumpLaneLabel('todo') };
      }
      if (lane === 'log') {
        return { lane: 'log', folder: 'ログ', file: '未整理', isInbox: false, label: dumpLaneLabel('log') };
      }
      return { lane: 'inbox', folder: 'INBOX', file: '未整理', isInbox: true, label: dumpLaneLabel('inbox') };
    }

    function historyEntryLane(entry) {
      const folder = String((entry && (entry.folder || entry.destFolder)) || '').replace(/^📥\s*/, '').trim();
      if (folder === 'やることリスト') return 'todo';
      if (folder === 'ログ') return 'log';
      return 'inbox';
    }

    function inputHistoryLaneShortLabel(lane) {
      if (lane !== 'todo' && lane !== 'log' && lane !== 'inbox') return '';
      return dumpLaneLabel(lane, { short: true });
    }

    function toggleInputHistoryLaneFilter(lane, status) {
      const next = lane === 'todo' || lane === 'log' ? lane : 'inbox';
      inputHistoryLaneFilter = inputHistoryLaneFilter === next ? '' : next;
      paintDumpLaneCurrent();
      if (status) {
        const label = inputHistoryLaneShortLabel(inputHistoryLaneFilter);
        status.textContent = label ? (label + ' の登録チェックを表示しています') : '登録チェックをすべて表示しています';
        status.className = 'text-base mt-2 text-center font-bold text-cyan-300';
        const shown = status.textContent;
        setTimeout(() => {
          if (status.textContent === shown) status.textContent = '';
        }, 1800);
      }
      paintInputTabHistory(getLocalInputHistory(), { force: true, resetScroll: true });
    }

    const DUMP_COMPOSE_IMAGE_MAX = 6;
    const DUMP_IMAGE_B64_TARGET = 320000; // メモ用途として鮮明かつ高速送信できる目標サイズ
    // GAS Webアプリはリダイレクトがあり、大きすぎる単発POSTは失敗時は分割へフォールバック
    const DUMP_IMAGE_SINGLE_SHOT_MAX = 90000;
    const DUMP_IMAGE_CHUNK_CHARS = 40000; // 分割数削減とGASリダイレクト耐性のバランス
    const DUMP_IMAGE_TOKEN_RE = /📷\s*(https:\/\/(?:drive\.google\.com\/(?:uc\?export=view&id=|thumbnail\?id=|file\/d\/)[A-Za-z0-9_-]+[^\s]*|dump-media\.hatterisk3\.workers\.dev\/img\/[A-Za-z0-9._/-]+[^\s]*))/g;
    const DUMP_IMAGE_PLACEHOLDER_RE = /📷‹(dimg-[A-Za-z0-9-]+)›/g;
    let dumpComposeImages = [];
    const localPendingImagesMap = new Map();

    function appendDumpImagePlaceholders(text, images) {
      const tokens = (images || []).map((img) => {
        if (!img) return '';
        if (img.remoteUrl) return '📷 ' + img.remoteUrl;
        return '📷‹' + img.id + '›';
      }).filter(Boolean);
      if (!tokens.length) return String(text || '');
      const base = String(text || '').replace(/\s+$/, '');
      return base ? (base + '\n' + tokens.join('\n')) : tokens.join('\n');
    }

    function replaceDumpImagePlaceholders(text, byId) {
      if (!text || !byId) return String(text || '');
      return String(text).replace(DUMP_IMAGE_PLACEHOLDER_RE, (match, id) => {
        const url = byId[id];
        return url ? ('📷 ' + url) : match;
      });
    }

    function listDumpImagePlaceholders(text) {
      const ids = [];
      const src = String(text || '');
      DUMP_IMAGE_PLACEHOLDER_RE.lastIndex = 0;
      let m;
      while ((m = DUMP_IMAGE_PLACEHOLDER_RE.exec(src))) {
        if (m[1] && !ids.includes(m[1])) ids.push(m[1]);
      }
      return ids;
    }

    function replaceImagePlaceholdersInLocalHistoryAndCache(byId) {
      if (!byId || !Object.keys(byId).length) return;
      try {
        const history = getLocalInputHistory();
        let changed = false;
        history.forEach((entry) => {
          if (entry && entry.content && /📷‹dimg-/.test(entry.content)) {
            const next = replaceDumpImagePlaceholders(entry.content, byId);
            if (next !== entry.content) {
              entry.content = next;
              changed = true;
            }
          }
        });
        if (changed) {
          cacheLocalInputHistory(history);
          if (typeof paintInputTabHistory === 'function') {
            paintInputTabHistory(history, { skipDupSchedule: true });
          }
        }
      } catch (e) {
        console.warn('replaceImagePlaceholders in history failed', e);
      }
      try {
        if (typeof dumpedItemsStore !== 'undefined' && Array.isArray(dumpedItemsStore)) {
          dumpedItemsStore.forEach((item) => {
            if (item && item.content && /📷‹dimg-/.test(item.content)) {
              item.content = replaceDumpImagePlaceholders(item.content, byId);
            }
          });
        }
      } catch (_) { }
    }

    async function uploadPendingImagesForJob(pendingImages, onProgress) {
      const byId = {};
      const total = (pendingImages || []).length;
      for (let i = 0; i < total; i++) {
        const img = pendingImages[i];
        if (!img) continue;
        if (img.remoteUrl) {
          byId[img.id] = img.remoteUrl;
          continue;
        }
        if (!img.dataUrl && localPendingImagesMap.has(img.id)) {
          const cached = localPendingImagesMap.get(img.id);
          img.dataUrl = img.dataUrl || (cached && cached.dataUrl);
          img.mimeType = img.mimeType || (cached && cached.mimeType);
        }
        if (!img.dataUrl) throw new Error('empty');
        const m = String(img.dataUrl).match(/^data:([^;]+);base64,(.+)$/i);
        const mimeType = (m && m[1]) || img.mimeType || 'image/jpeg';
        const b64 = m ? m[2] : String(img.dataUrl || '');
        const url = await uploadDumpImagePayload(b64, mimeType, null, i + 1, total, (phase) => {
          if (typeof onProgress === 'function') {
            onProgress({ index: i + 1, total, phase });
          }
        });
        img.remoteUrl = url;
        byId[img.id] = url;
      }
      return byId;
    }

    function makeDumpComposeImageId() {
      return 'dimg-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7);
    }

    function extractDriveFileIdFromUrl(url) {
      const u = String(url || '');
      let m = u.match(/[?&]id=([A-Za-z0-9_-]+)/);
      if (m) return m[1];
      m = u.match(/\/d\/([A-Za-z0-9_-]+)/);
      return m ? m[1] : '';
    }

    function driveImageThumbUrl(id) {
      return 'https://drive.google.com/thumbnail?id=' + id + '&sz=w1000';
    }

    function driveImageOpenUrl(id) {
      return 'https://drive.google.com/file/d/' + id + '/view';
    }

    function listDumpImageUrls(text) {
      const urls = [];
      const seen = new Set();
      const src = String(text || '');
      DUMP_IMAGE_TOKEN_RE.lastIndex = 0;
      let m;
      while ((m = DUMP_IMAGE_TOKEN_RE.exec(src))) {
        const u = m[1];
        if (u && !seen.has(u)) {
          seen.add(u);
          urls.push(u);
        }
      }
      return urls;
    }

    function stripDumpImageTokens(text) {
      return String(text || '')
        .replace(DUMP_IMAGE_TOKEN_RE, '')
        .replace(DUMP_IMAGE_PLACEHOLDER_RE, '')
        .replace(/\n{3,}/g, '\n\n')
        .trim();
    }

    function scrubDumpImageArtifactsFromInput() {
      const ta = document.getElementById('input-content');
      if (!ta) return;
      const prev = ta.value;
      const next = String(prev || '')
        .replace(DUMP_IMAGE_PLACEHOLDER_RE, '')
        .replace(DUMP_IMAGE_TOKEN_RE, '')
        .replace(/\n{3,}/g, '\n\n');
      if (next === prev) return;
      ta.value = next;
      try { ta.dispatchEvent(new Event('input', { bubbles: true })); } catch (_) { }
    }

    function appendDumpImageTokens(text, urls) {
      const lines = (urls || []).map((u) => '📷 ' + u).filter(Boolean);
      if (!lines.length) return String(text || '');
      const base = String(text || '').replace(/\s+$/, '');
      return base ? (base + '\n' + lines.join('\n')) : lines.join('\n');
    }

    function setDumpContentDisplay(el, content) {
      if (!el) return;
      const raw = String(content || '');
      if (!raw) {
        el.textContent = '';
        return;
      }
      const hasDrive = /📷\s*https:\/\/drive\.google\.com\//.test(raw);
      const hasR2 = /📷\s*https:\/\/dump-media\.hatterisk3\.workers\.dev\/img\//.test(raw);
      const hasPlaceholder = /📷‹(dimg-[A-Za-z0-9-]+)›/.test(raw);
      if (!hasDrive && !hasR2 && !hasPlaceholder) {
        el.textContent = raw;
        return;
      }
      const esc = typeof escapeHtmlText === 'function' ? escapeHtmlText(raw) : raw
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
      let html = esc;
      if (hasDrive) {
        html = html.replace(
          /📷\s*(https:\/\/drive\.google\.com\/(?:uc\?export=view&amp;id=|thumbnail\?id=|file\/d\/)[A-Za-z0-9_-]+(?:\/view)?(?:&amp;sz=w\d+)?)/g,
          (full, urlEscaped) => {
            const url = String(urlEscaped || '').replace(/&amp;/g, '&');
            const id = extractDriveFileIdFromUrl(url);
            if (!id) return full;
            const thumb = driveImageThumbUrl(id);
            const open = driveImageOpenUrl(id);
            return '<div class="dump-content-image-wrap">'
              + '<a class="dump-content-image-link" href="' + open + '" target="_blank" rel="noopener noreferrer" title="写真を開く">'
              + '<img class="dump-content-image" src="' + thumb + '" alt="" data-drive-id="' + id + '" loading="lazy" decoding="async">'
              + '</a>'
              + '<button type="button" class="dump-content-image-copy-btn input-tab-history-icon-btn" data-image-url="' + url + '" title="この写真をコピー" aria-label="この写真をコピー">📋</button>'
              + '</div>';
          }
        );
      }
      if (hasR2) {
        html = html.replace(
          /📷\s*(https:\/\/dump-media\.hatterisk3\.workers\.dev\/img\/[A-Za-z0-9._/-]+)/g,
          (full, urlEscaped) => {
            const url = String(urlEscaped || '').replace(/&amp;/g, '&');
            return '<div class="dump-content-image-wrap">'
              + '<a class="dump-content-image-link" href="' + url + '" target="_blank" rel="noopener noreferrer" title="写真を開く">'
              + '<img class="dump-content-image" src="' + url + '" alt="" data-r2-url="' + url + '" loading="lazy" decoding="async">'
              + '</a>'
              + '<button type="button" class="dump-content-image-copy-btn input-tab-history-icon-btn" data-image-url="' + url + '" title="この写真をコピー" aria-label="この写真をコピー">📋</button>'
              + '</div>';
          }
        );
      }
      if (hasPlaceholder) {
        html = html.replace(/📷‹(dimg-[A-Za-z0-9-]+)›/g, (full, id) => {
          const item = localPendingImagesMap.get(id);
          const previewUrl = (item && (item.blobUrl || item.dataUrl)) || '';
          if (!previewUrl) {
            return '<div class="my-1 px-2.5 py-1 rounded-lg bg-cyan-950/60 border border-cyan-700/50 text-xs text-cyan-300 font-mono inline-flex items-center gap-1.5 animate-pulse">📷 写真送信中…</div>';
          }
          return '<div class="dump-content-image-wrap is-pending-upload relative cursor-pointer" data-pending-id="' + id + '">'
            + '<img class="dump-content-image opacity-85" src="' + previewUrl + '" alt="写真送信中" loading="lazy" decoding="async">'
            + '<span class="absolute bottom-1 right-1 bg-black/80 text-[10px] text-cyan-300 font-bold px-1.5 py-0.5 rounded shadow pointer-events-none animate-pulse">送信中…</span>'
            + '</div>';
        });
      }
      el.innerHTML = html;
      el.querySelectorAll('.dump-content-image-wrap.is-pending-upload').forEach((wrap) => {
        wrap.addEventListener('click', (e) => {
          e.stopPropagation();
          const img = wrap.querySelector('img');
          if (img && img.src && typeof openDumpImageModal === 'function') {
            openDumpImageModal(img.src);
          }
        });
      });
      el.querySelectorAll('.dump-content-image-link').forEach((link) => {
        link.addEventListener('click', (e) => {
          e.stopPropagation();
        });
      });
      el.querySelectorAll('.dump-content-image-copy-btn').forEach((btn) => {
        bindInputHistoryActionButton(btn, () => {
          const imgUrl = btn.getAttribute('data-image-url') || '';
          if (imgUrl && typeof copySingleDumpImageUrl === 'function') {
            copySingleDumpImageUrl(imgUrl, btn);
          }
        });
      });
      el.querySelectorAll('img.dump-content-image').forEach((img) => {
        img.addEventListener('error', function onImgErr() {
          img.removeEventListener('error', onImgErr);
          const id = img.getAttribute('data-drive-id') || '';
          const r2Url = img.getAttribute('data-r2-url') || '';
          const href = id ? driveImageOpenUrl(id) : r2Url;
          const fallback = document.createElement(href ? 'a' : 'span');
          fallback.className = 'dump-content-image-fallback';
          fallback.textContent = '📷 写真を開く';
          if (href && fallback.tagName === 'A') {
            fallback.href = href;
            fallback.target = '_blank';
            fallback.rel = 'noopener noreferrer';
          }
          const wrap = img.closest('.dump-content-image-wrap');
          if (wrap) wrap.replaceWith(fallback);
          else img.replaceWith(fallback);
        });
      });
    }

    /** 画像貼付け時に一緒に来るファイル名・パスを入力欄へ入れない */
    function isClipboardImageFileLabel(text) {
      const t = String(text || '').replace(/^\uFEFF/, '').trim();
      if (!t) return true;
      if (/^file:\/\//i.test(t)) return true;
      const lines = t.split(/\r?\n/).map((s) => s.trim()).filter(Boolean);
      if (!lines.length) return true;
      const looksLikeName = (line) => {
        if (line.length > 320) return false;
        if (/^(https?:|data:)/i.test(line)) return false;
        if (/[\\\/]/.test(line) && /\.(png|jpe?g|gif|webp|heic|bmp|tiff?)$/i.test(line)) return true;
        if (/^[^\s]+\.(png|jpe?g|gif|webp|heic|bmp|tiff?)$/i.test(line)) return true;
        if (/^image\.(png|jpe?g|gif|webp)$/i.test(line)) return true;
        return false;
      };
      return lines.every(looksLikeName);
    }

    function dataUrlBase64Length(dataUrl) {
      const m = String(dataUrl || '').match(/^data:[^;]+;base64,(.*)$/i);
      return m ? m[1].length : String(dataUrl || '').length;
    }

    function resolveDumpImagePreviewUrl(url) {
      const src = String(url || '');
      if (!src) return '';
      const driveId = typeof extractDriveFileIdFromUrl === 'function' ? extractDriveFileIdFromUrl(src) : '';
      if (driveId) {
        return 'https://drive.google.com/thumbnail?id=' + driveId + '&sz=w2000';
      }
      return src;
    }

    function openDumpImageModal(url) {
      if (!url) return;
      const modal = document.getElementById('dump-image-modal');
      const img = document.getElementById('dump-image-modal-img');
      if (!modal || !img) return;
      const displayUrl = resolveDumpImagePreviewUrl(url);
      img.src = displayUrl;
      modal.classList.remove('opacity-0', 'pointer-events-none');
      document.addEventListener('keydown', onDumpImageModalKeydown);
    }

    function closeDumpImageModal() {
      const modal = document.getElementById('dump-image-modal');
      const img = document.getElementById('dump-image-modal-img');
      if (!modal) return;
      modal.classList.add('opacity-0', 'pointer-events-none');
      if (img) img.src = '';
      document.removeEventListener('keydown', onDumpImageModalKeydown);
    }

    function onDumpImageModalKeydown(e) {
      if (e.key === 'Escape') {
        closeDumpImageModal();
      }
    }

    function paintDumpComposeImages() {
      const wrap = document.getElementById('dump-compose-images');
      if (!wrap) return;
      wrap.innerHTML = '';
      if (!dumpComposeImages.length) {
        wrap.classList.remove('is-on');
        return;
      }
      wrap.classList.add('is-on');
      dumpComposeImages.forEach((img, index) => {
        const chip = document.createElement('div');
        chip.className = 'dump-compose-image-chip';
        chip.title = '添付写真 ' + (index + 1) + '（タップで拡大）';
        const imgUrl = img.blobUrl || img.remoteUrl || '';
        const preview = document.createElement('img');
        preview.src = imgUrl;
        preview.alt = '添付写真 ' + (index + 1);
        preview.draggable = false;
        chip.addEventListener('click', () => {
          openDumpImageModal(imgUrl);
        });
        const rm = document.createElement('button');
        rm.type = 'button';
        rm.setAttribute('aria-label', '写真を外す');
        rm.textContent = '×';
        rm.onclick = (e) => {
          e.preventDefault();
          e.stopPropagation();
          removeDumpComposeImage(img.id);
        };
        chip.appendChild(preview);
        chip.appendChild(rm);
        wrap.appendChild(chip);
      });
      if (typeof syncInputTabHistoryLock === 'function') syncInputTabHistoryLock();
    }

    function clearDumpComposeImages(opts) {
      opts = opts || {};
      if (!opts.keepBlobs) {
        dumpComposeImages.forEach((img) => {
          if (img && img.blobUrl && String(img.blobUrl).indexOf('blob:') === 0) {
            try { URL.revokeObjectURL(img.blobUrl); } catch (_) { }
          }
        });
      }
      dumpComposeImages = [];
      paintDumpComposeImages();
      if (!opts.skipDraftSync && !pendingInputHistoryReplace && typeof onLiveInputDraftChanged === 'function') {
        onLiveInputDraftChanged({ reason: 'clear_images' });
      }
    }

    function removeDumpComposeImage(id) {
      const idx = dumpComposeImages.findIndex((x) => x && x.id === id);
      if (idx < 0) return;
      const img = dumpComposeImages[idx];
      if (img && img.blobUrl && String(img.blobUrl).indexOf('blob:') === 0) {
        try { URL.revokeObjectURL(img.blobUrl); } catch (_) { }
      }
      dumpComposeImages.splice(idx, 1);
      paintDumpComposeImages();
      if (!pendingInputHistoryReplace && typeof onLiveInputDraftChanged === 'function') {
        onLiveInputDraftChanged({ reason: 'remove_image' });
      }
    }

    function hydrateDumpComposeFromContent(content) {
      clearDumpComposeImages({ skipDraftSync: true });
      const src = String(content || '');
      listDumpImageUrls(src).forEach((url) => {
        dumpComposeImages.push({
          id: makeDumpComposeImageId(),
          blobUrl: url,
          remoteUrl: url,
          fileName: 'photo.jpg',
          mimeType: 'image/jpeg'
        });
      });
      paintDumpComposeImages();
      return stripDumpImageTokens(src);
    }

    function pickDumpComposeImages() {
      const input = document.getElementById('dump-compose-image-input');
      if (!input) return;
      input.value = '';
      input.click();
    }

    function onDumpComposeImageInputChange(input) {
      const files = input && input.files ? Array.from(input.files) : [];
      if (files.length) void addDumpComposeImageFiles(files);
      if (input) input.value = '';
    }

    async function loadImageElementFromBlob(file) {
      let bitmap = null;
      try {
        if (typeof createImageBitmap === 'function') {
          bitmap = await createImageBitmap(file);
          return {
            width: bitmap.width,
            height: bitmap.height,
            draw: (ctx, w, h) => ctx.drawImage(bitmap, 0, 0, w, h),
            close: () => { try { bitmap.close(); } catch (_) { } }
          };
        }
      } catch (_) { }
      const objectUrl = URL.createObjectURL(file);
      try {
        const img = await new Promise((resolve, reject) => {
          const el = new Image();
          el.onload = () => resolve(el);
          el.onerror = () => reject(new Error('image_load'));
          el.src = objectUrl;
        });
        return {
          width: img.naturalWidth || img.width,
          height: img.naturalHeight || img.height,
          draw: (ctx, w, h) => ctx.drawImage(img, 0, 0, w, h),
          close: () => { try { URL.revokeObjectURL(objectUrl); } catch (_) { } }
        };
      } catch (err) {
        try { URL.revokeObjectURL(objectUrl); } catch (_) { }
        throw err;
      }
    }

    async function compressDumpImageBlob(file) {
      const source = await loadImageElementFromBlob(file);
      try {
        const sides = [960, 800, 640, 512];
        const qualities = [0.65, 0.55, 0.45, 0.35, 0.28];
        let best = null;
        for (let si = 0; si < sides.length; si++) {
          const maxSide = sides[si];
          const scale = Math.min(1, maxSide / Math.max(source.width, source.height, 1));
          const w = Math.max(1, Math.round(source.width * scale));
          const h = Math.max(1, Math.round(source.height * scale));
          const canvas = document.createElement('canvas');
          canvas.width = w;
          canvas.height = h;
          const ctx = canvas.getContext('2d', { alpha: false });
          if (!ctx) throw new Error('canvas');
          ctx.fillStyle = '#000';
          ctx.fillRect(0, 0, w, h);
          source.draw(ctx, w, h);
          for (let qi = 0; qi < qualities.length; qi++) {
            const dataUrl = canvas.toDataURL('image/jpeg', qualities[qi]);
            const len = dataUrlBase64Length(dataUrl);
            best = { dataUrl, mimeType: 'image/jpeg', fileName: 'dump.jpg', b64Len: len };
            if (len <= DUMP_IMAGE_B64_TARGET) return best;
          }
        }
        if (!best || best.b64Len > DUMP_IMAGE_B64_TARGET * 1.35) {
          throw new Error('too_large_after_compress');
        }
        return best;
      } finally {
        source.close();
      }
    }

    async function addDumpComposeImageFiles(files) {
      scrubDumpImageArtifactsFromInput();
      const list = Array.from(files || []).filter((f) => f && String(f.type || '').indexOf('image/') === 0);
      if (!list.length) return;
      const room = DUMP_COMPOSE_IMAGE_MAX - dumpComposeImages.length;
      if (room <= 0) {
        alert('写真は最大' + DUMP_COMPOSE_IMAGE_MAX + '枚までです');
        return;
      }
      const take = list.slice(0, room);
      if (list.length > room) {
        alert('写真は最大' + DUMP_COMPOSE_IMAGE_MAX + '枚までです（残り' + room + '枚のみ追加）');
      }
      for (const file of take) {
        try {
          const compressed = await compressDumpImageBlob(file);
          let blobUrl = '';
          try { blobUrl = URL.createObjectURL(file); } catch (_) { }
          dumpComposeImages.push({
            id: makeDumpComposeImageId(),
            blobUrl: blobUrl || compressed.dataUrl,
            dataUrl: compressed.dataUrl,
            remoteUrl: '',
            fileName: 'dump.jpg',
            mimeType: compressed.mimeType
          });
        } catch (err) {
          console.warn('dump image compress failed', err);
          alert(err && err.message === 'too_large_after_compress'
            ? '写真が大きすぎて追加できませんでした'
            : 'この画像は追加できませんでした');
        }
      }
      paintDumpComposeImages();
      if (!pendingInputHistoryReplace && typeof onLiveInputDraftChanged === 'function') {
        onLiveInputDraftChanged({ reason: 'add_images' });
      }
      if (!pendingInputHistoryReplace && typeof preuploadLiveDraftComposeImages === 'function') {
        void preuploadLiveDraftComposeImages();
      }
      const ta = document.getElementById('input-content');
      if (ta) {
        try { ta.focus({ preventScroll: true }); } catch (_) {
          try { ta.focus(); } catch (__) { }
        }
      }
    }

    function sleepMs(ms) {
      return new Promise((resolve) => setTimeout(resolve, ms));
    }

    function dumpImageApiErrorCode(res) {
      if (!res) return 'network';
      if (res.error === true) return res.message || 'network';
      if (typeof res.error === 'string') {
        if (/Unknown action/i.test(res.error)) return 'need_redeploy';
        return res.error;
      }
      if (res.success === false) return res.error || res.message || 'upload_failed';
      return '';
    }

    async function callDumpImageApi(action, data, extraOpts) {
      return callAPI(action, data, Object.assign({ silent: true, keepalive: false }, extraOpts || {}));
    }

    /** GAS Webアプリ向け: 大きい画像は分割して送る（単発POSTは構造的に欠ける） */
    async function uploadDumpImagePayload(b64, mimeType, statusEl, index, total, onProgress) {
      const raw = String(b64 || '').replace(/\s+/g, '');
      if (!raw) throw Object.assign(new Error('empty'), { code: 'empty' });
      if (raw.length > DUMP_IMAGE_B64_TARGET * 1.25) {
        throw Object.assign(new Error('too_large'), { code: 'too_large' });
      }

      const setStatus = (extra) => {
        if (typeof onProgress === 'function') {
          onProgress(extra);
        }
        if (statusEl) {
          statusEl.textContent = '写真をアップロード中… (' + index + '/' + total + ')'
            + (extra ? ' · ' + extra : '');
          statusEl.className = 'text-base mt-2 text-center font-bold text-cyan-300';
        }
      };

      // R2 Worker は大容量でも単発POSTで保存可能（失敗時のみGAS分割へフォールバック）
      {
        setStatus('');
        const res = await callDumpImageApi('uploadDumpImage', {
          data: raw,
          mimeType: mimeType || 'image/jpeg',
          fileName: 'dump.jpg'
        });
        if (res && res.url && res.success !== false && !res.error) return res.url;
        const code = dumpImageApiErrorCode(res);
        if (code === 'need_redeploy') {
          throw Object.assign(new Error(code), { code });
        }
        // 単発失敗時は分割へフォールバック
      }

      const runChunkedOnce = async () => {
        const parts = [];
        for (let i = 0; i < raw.length; i += DUMP_IMAGE_CHUNK_CHARS) {
          parts.push(raw.slice(i, i + DUMP_IMAGE_CHUNK_CHARS));
        }
        const uploadId = ('u' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8)).slice(0, 40);
        setStatus('準備');
        const begin = await callDumpImageApi('uploadDumpImageBegin', {
          uploadId,
          total: parts.length,
          mimeType: mimeType || 'image/jpeg',
          fileName: 'dump.jpg',
          length: raw.length
        });
        const beginCode = dumpImageApiErrorCode(begin);
        if (beginCode === 'need_redeploy' || (begin && begin.error && /Unknown action/i.test(String(begin.error)))) {
          throw Object.assign(new Error('need_redeploy'), { code: 'need_redeploy' });
        }
        if (!begin || begin.success === false || begin.error) {
          throw Object.assign(new Error(beginCode || 'begin_failed'), { code: beginCode || 'begin_failed' });
        }

        let nextIdx = 0;
        let doneChunks = 0;
        const workerCount = Math.min(3, parts.length);
        const uploadChunkWorker = async () => {
          while (true) {
            const i = nextIdx++;
            if (i >= parts.length) break;
            let ok = false;
            let lastErr = '';
            for (let attempt = 1; attempt <= 3; attempt++) {
              setStatus('分割 ' + Math.min(parts.length, doneChunks + 1) + '/' + parts.length + (attempt > 1 ? ' 再送' : ''));
              const chunkRes = await callDumpImageApi('uploadDumpImageChunk', {
                uploadId,
                index: i,
                total: parts.length,
                chunk: parts[i]
              });
              if (chunkRes && chunkRes.success !== false && !chunkRes.error) {
                ok = true;
                doneChunks++;
                setStatus('分割 ' + doneChunks + '/' + parts.length);
                break;
              }
              lastErr = dumpImageApiErrorCode(chunkRes) || 'chunk_failed';
              if (lastErr === 'need_redeploy') {
                throw Object.assign(new Error(lastErr), { code: lastErr });
              }
              await sleepMs(250 * attempt);
            }
            if (!ok) {
              throw Object.assign(new Error(lastErr || 'chunk_failed'), { code: lastErr || 'chunk_failed' });
            }
          }
        };
        await Promise.all(Array.from({ length: workerCount }, () => uploadChunkWorker()));

        setStatus('結合');
        let finish = null;
        for (let attempt = 1; attempt <= 3; attempt++) {
          finish = await callDumpImageApi('uploadDumpImageFinish', { uploadId }, { timeoutMs: 45000 });
          if (finish && finish.url && finish.success !== false && !finish.error) {
            return finish.url;
          }
          const code = dumpImageApiErrorCode(finish);
          if (code === 'need_redeploy' || code === 'missing_chunk' || code === 'expired' || code === 'bad_base64') {
            throw Object.assign(new Error(code), { code });
          }
          await sleepMs(400 * attempt);
        }
        const finCode = dumpImageApiErrorCode(finish) || 'finish_failed';
        throw Object.assign(new Error(finCode), { code: finCode });
      };

      // missing_chunk / expired は最初からやり直す（1回）
      try {
        return await runChunkedOnce();
      } catch (err) {
        const code = err && err.code;
        if (code === 'missing_chunk' || code === 'expired') {
          setStatus('やり直し');
          await sleepMs(500);
          return await runChunkedOnce();
        }
        throw err;
      }
    }

    async function uploadOneDumpComposeImage(img, statusEl, index, total) {
      if (img.remoteUrl) return img.remoteUrl;
      if (!img.dataUrl) throw new Error('empty');
      const m = String(img.dataUrl).match(/^data:([^;]+);base64,(.+)$/i);
      const mimeType = (m && m[1]) || img.mimeType || 'image/jpeg';
      const b64 = m ? m[2] : String(img.dataUrl || '');
      const url = await uploadDumpImagePayload(b64, mimeType, statusEl, index, total);
      img.remoteUrl = url;
      return url;
    }

    async function uploadDumpComposeImages(statusEl) {
      const byId = {};
      const total = dumpComposeImages.length;
      for (let i = 0; i < dumpComposeImages.length; i++) {
        const img = dumpComposeImages[i];
        if (!img) continue;
        try {
          byId[img.id] = await uploadOneDumpComposeImage(img, statusEl, i + 1, total);
        } catch (err) {
          console.warn('dump image upload failed', err);
          const code = String((err && (err.code || err.message)) || '');
          let reason = '';
          if (code === 'need_redeploy' || /Unknown action/i.test(code)) {
            reason = '\n\nいま接続しているGASに画像APIがありません。'
              + '\n1) DUMP用スプレッドシートの Apps Script に gas/コード.js を全部貼って保存'
              + '\n2) 「デプロイを管理」→ このアプリの URL と同じデプロイを編集 → 新バージョン'
              + '\n   （新規デプロイでURLが変わった場合は index.html の GAS_API_URL も更新）';
          } else if (code === 'too_large') reason = '（サイズ过大）';
          else if (code === 'drive_write') reason = '（Drive書き込みエラー）';
          else if (code === 'expired' || code === 'missing_chunk') reason = '（分割転送が途切れました）';
          else if (code) reason = '\n（詳細: ' + code + '）';
          alert('写真のアップロードに失敗しました' + reason);
          return null;
        }
      }
      return byId;
    }

    async function buildDumpContentWithComposeImages(rawText, statusEl) {
      const cleaned = String(rawText || '')
        .replace(DUMP_IMAGE_PLACEHOLDER_RE, '')
        .replace(/\n{3,}/g, '\n\n');
      if (!dumpComposeImages.length) return cleaned;
      // プレビュー側の写真を正とし、本文中の旧トークンと二重にならないよう付け直す
      const text = stripDumpImageTokens(cleaned);
      const byId = await uploadDumpComposeImages(statusEl);
      if (!byId) return null;
      const urls = dumpComposeImages.map((img) => img && byId[img.id]).filter(Boolean);
      return appendDumpImageTokens(text, urls);
    }

    function bindDumpComposeImageUi() {
      if (bindDumpComposeImageUi._bound) return;
      bindDumpComposeImageUi._bound = true;
      scrubDumpImageArtifactsFromInput();
      const ta = document.getElementById('input-content');
      if (ta) {
        ta.addEventListener('paste', (e) => {
          const cd = e.clipboardData;
          if (!cd || !cd.items) return;
          const files = [];
          const seen = new Set();
          const pushFile = (f) => {
            if (!f || String(f.type || '').indexOf('image/') !== 0) return;
            // items と files で同一画像が二重に来るので size+type で除外
            const key = String(f.type) + ':' + String(f.size || 0);
            if (seen.has(key)) return;
            seen.add(key);
            files.push(f);
          };

          // 画像ソースは1系統だけ使う（HTML data URL と image/png を混ぜると同じ写真が2枚になる）
          const customFiles = typeof readDumpClipboardImagesFromPaste === 'function'
            ? readDumpClipboardImagesFromPaste(cd)
            : [];
          const html = String(cd.getData('text/html') || '');
          const htmlFiles = (!customFiles.length && typeof filesFromHtmlClipboard === 'function')
            ? filesFromHtmlClipboard(html)
            : [];
          if (customFiles.length) {
            customFiles.forEach((f) => pushFile(f));
          } else if (htmlFiles.length) {
            htmlFiles.forEach((f) => pushFile(f));
          } else {
            let fromItems = 0;
            for (let i = 0; i < cd.items.length; i++) {
              const it = cd.items[i];
              if (it && it.type && it.type.indexOf('image/') === 0) {
                const before = files.length;
                pushFile(it.getAsFile());
                if (files.length > before) fromItems += 1;
              }
            }
            if (!fromItems && cd.files && cd.files.length) {
              Array.from(cd.files).forEach((f) => pushFile(f));
            }
          }
          let plain = String(cd.getData('text/plain') || '');
          if (plain && typeof stripDumpImageTokens === 'function') {
            plain = stripDumpImageTokens(plain);
          }

          let customItem = null;
          for (let i = 0; i < cd.items.length; i++) {
            const it = cd.items[i];
            const t = String((it && it.type) || '');
            if (t.indexOf('x-dump-images') >= 0 && typeof it.getAsString === 'function') {
              customItem = it;
              break;
            }
          }

          const insertPlain = () => {
            if (!(plain && !isClipboardImageFileLabel(plain))) return;
            const start = typeof ta.selectionStart === 'number' ? ta.selectionStart : ta.value.length;
            const end = typeof ta.selectionEnd === 'number' ? ta.selectionEnd : start;
            const prev = ta.value;
            ta.value = prev.slice(0, start) + plain + prev.slice(end);
            const pos = start + plain.length;
            try { ta.setSelectionRange(pos, pos); } catch (_) { }
            try { ta.dispatchEvent(new Event('input', { bubbles: true })); } catch (_) { }
          };

          const htmlForDrive = String(cd.getData('text/html') || '');
          const driveHtmlUrls = typeof listDriveImageUrlsFromHtml === 'function'
            ? listDriveImageUrlsFromHtml(htmlForDrive)
            : [];

          // getData でカスタムが取れず item だけある → 非同期で全枚取得
          if (customItem && !customFiles.length) {
            e.preventDefault();
            customItem.getAsString((str) => {
              const extra = typeof filesFromDumpClipboardJson === 'function'
                ? filesFromDumpClipboardJson(str)
                : [];
              if (extra.length) {
                files.length = 0;
                seen.clear();
                extra.forEach((f) => pushFile(f));
              }
              insertPlain();
              if (files.length) void addDumpComposeImageFiles(files);
            });
            return;
          }

          // HTML に Drive サムネだけある場合（他アプリ向けコピーの DUMP 再貼り付け）
          if (!files.length && driveHtmlUrls.length && typeof filesFromDriveHtmlClipboard === 'function') {
            e.preventDefault();
            insertPlain();
            void filesFromDriveHtmlClipboard(htmlForDrive).then((extra) => {
              if (extra && extra.length) void addDumpComposeImageFiles(extra);
            });
            return;
          }

          if (!files.length) return;
          e.preventDefault();
          insertPlain();
          void addDumpComposeImageFiles(files);
        });
      }
      const dropTargets = [
        document.getElementById('dump-compose-shell'),
        document.getElementById('capture-compose'),
        document.getElementById('capture-overlay-panel'),
        ta
      ].filter(Boolean);
      dropTargets.forEach((el) => {
        el.addEventListener('dragover', (e) => {
          if (!e.dataTransfer) return;
          const types = Array.from(e.dataTransfer.types || []);
          if (types.indexOf('Files') >= 0) {
            e.preventDefault();
            e.dataTransfer.dropEffect = 'copy';
          }
        });
        el.addEventListener('drop', (e) => {
          const files = e.dataTransfer && e.dataTransfer.files
            ? Array.from(e.dataTransfer.files)
            : [];
          const images = files.filter((f) => f && String(f.type || '').indexOf('image/') === 0);
          if (!images.length) return;
          e.preventDefault();
          e.stopPropagation();
          void addDumpComposeImageFiles(images);
        });
      });
    }

    const SUBMIT_INBOX_COOLDOWN_MS = 750;
    let lastSubmitInboxTapAt = 0;
    let lastDumpSubmissionSig = '';
    let lastDumpSubmissionAt = 0;

    async function submitInbox(lane) {
      const tapNow = Date.now();
      if (tapNow - lastSubmitInboxTapAt < SUBMIT_INBOX_COOLDOWN_MS) {
        console.warn('submitInbox rapid tap ignored (cooldown)');
        return;
      }
      lastSubmitInboxTapAt = tapNow;
      // ボタンの即時ロック（連打・二重タップ防止ガード）
      document.querySelectorAll('.dump-lane-btn').forEach((b) => {
        b.classList.add('pointer-events-none');
      });
      setTimeout(() => {
        applySubmitInboxEnabledState();
      }, SUBMIT_INBOX_COOLDOWN_MS);

      // 押せない状態を残さない: ローダー／ロック残留は強制解除して続行
      ensureSubmitInboxReady({ force: true, reason: 'submit_inbox' });
      resetInputHistoryCloudSyncPause();
      window.__suppressHistoryTapUntil = 0;
      const historyList = document.getElementById('input-tab-history-list');
      if (historyList) historyList.classList.remove('ghost-tap-shield');
      await commitInputCompositionAsync();
      const textarea = document.getElementById('input-content');
      const status = document.getElementById('input-status');
      const btn = document.getElementById('submit-inbox-btn');
      // composition 確定後にもう一度読む（IME最終文字の取りこぼし防止）
      const rawTyped = textarea ? String(textarea.value || '') : '';
      if (pendingInputHistoryReplace) {
        return submitInboxHistoryReplace(rawTyped, typeof lane === 'string' ? lane : 'inbox');
      }
      const laneDest = dumpLaneDest(typeof lane === 'string' ? lane : 'inbox');
      const directFolder = '';
      const directFile = '';
      const destFolder = laneDest.folder;
      const destFile = laneDest.file;
      const isInboxDest = laneDest.isInbox;

      if (!rawTyped.trim() && !dumpComposeImages.length) {
        toggleInputHistoryLaneFilter(laneDest.lane, status);
        return;
      }

      const hasImages = dumpComposeImages.length > 0;
      const imagesToUpload = hasImages ? dumpComposeImages.map((img) => ({ ...img })) : [];
      if (hasImages) {
        imagesToUpload.forEach((img) => {
          localPendingImagesMap.set(img.id, img);
        });
        clearDumpComposeImages({ keepBlobs: true, skipDraftSync: true });
      }

      const rawContent = hasImages
        ? appendDumpImagePlaceholders(stripDumpImageTokens(rawTyped), imagesToUpload)
        : rawTyped;

      const chunks = splitDumpContent(rawContent);
      if (chunks.length === 0) {
        if (textarea) clearInboxInputAfterDump(textarea, rawContent, { focus: true });
        return;
      }

      const preventDuplicates = localStorage.getItem('setting_prevent_duplicates') !== 'false';
      const pendingReplace = pendingInputHistoryReplace ? { ...pendingInputHistoryReplace } : null;

      const dupCheckStart = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
      const knownContents = typeof getKnownContentsForDest === 'function'
        ? getKnownContentsForDest(destFolder, destFile, isInboxDest, pendingReplace && pendingReplace.id)
        : new Set();

      let addedChunks = [];
      let replacedDupChunks = [];
      const seenThisDump = new Set();
      const knownKeys = new Set();
      knownContents.forEach((c) => {
        const k = typeof dumpContentKey === 'function' ? dumpContentKey(c) : c;
        if (k) knownKeys.add(k);
      });
      chunks.forEach((chunk) => {
        const isReplaceSource = pendingReplace && dumpContentEquals(chunk, pendingReplace.content);
        const key = typeof dumpContentKey === 'function' ? dumpContentKey(chunk) : chunk;
        if (key && seenThisDump.has(key)) return;
        if (key) seenThisDump.add(key);
        if (preventDuplicates && !isReplaceSource && key && knownKeys.has(key)) {
          replacedDupChunks.push(chunk);
        }
        if (key) knownKeys.add(key);
        knownContents.add(chunk);
        addedChunks.push(chunk);
      });

      // 直前入力と同一内容の二重登録ブロック（ミリ秒単位の連続送信防止）
      const dumpSig = `${laneDest.lane}|${destFolder}|${destFile}|${addedChunks.join('\u0000')}`;
      if (dumpSig === lastDumpSubmissionSig && (tapNow - lastDumpSubmissionAt < 5000)) {
        console.warn('Duplicate dump submission ignored within 5s:', dumpSig);
        if (textarea) clearInboxInputAfterDump(textarea, rawContent, { focus: true });
        return;
      }
      lastDumpSubmissionSig = dumpSig;
      lastDumpSubmissionAt = tapNow;

      // 実書き込みは enqueue するため、ボタンはロックしない（入力クリア中のみ瞬間フラグ）
      isSubmittingInbox = true;
      submitInboxBusyStartedAt = Date.now();
      try {
        clearInboxInputAfterDump(textarea, rawContent, { focus: true });
        if (directFolder && localStorage.getItem('setting_keep_direct_destination') !== 'true') {
          document.getElementById('direct-folder').value = '';
          void onDirectFolderChange();
        }
      } finally {
        clearSubmitInboxLocks();
      }
      refreshSubmitInboxAvailability();

      lastDupCheckMs = Math.max(0, ((typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now()) - dupCheckStart);

      if (addedChunks.length === 0) {
        clearInboxInputAfterDump(textarea, rawContent, { focus: true });
        status.textContent = '保存する内容がありません';
        status.className = 'text-base mt-2 text-center font-bold text-yellow-400';
        setTimeout(() => {
          if (status.textContent.includes('ありません')) status.innerHTML = '';
        }, 4000);
        return;
      }

      // 重複は過去分をローカル索引から落とし、登録チェックは新しい行として先頭へ
      if (replacedDupChunks.length && typeof forgetDumpedItemsByContents === 'function') {
        forgetDumpedItemsByContents(replacedDupChunks, { includeStored: true });
      }
      if (inputHistoryLaneFilter) {
        inputHistoryLaneFilter = laneDest.lane;
        paintDumpLaneCurrent();
      }
      const addedHistory = appendLocalInputHistory(addedChunks, destFolder, destFile);
      if (typeof scheduleInputTabPartialOverlaps === 'function') {
        scheduleInputTabPartialOverlaps(addedHistory);
      }
      lastDupCheckMs = Math.max(0, ((typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now()) - dupCheckStart);
      if (pendingReplace && pendingReplace.id) {
        cacheLocalInputHistory(getLocalInputHistory().filter((e) => e.id !== pendingReplace.id));
        pendingInputHistoryReplace = null;
        inputHistoryReplaceBackup = '';
        setInputHistoryReplaceHint(false);
      }
      if (typeof refreshInputTabHistoryAfterLocalChange === 'function') {
        refreshInputTabHistoryAfterLocalChange(addedHistory, {
          removeContents: replacedDupChunks,
          skipDupSchedule: true
        });
      } else {
        paintInputTabHistory(getLocalInputHistory(), { skipDupSchedule: true });
      }
      setTimeout(() => {
        if (typeof scheduleInputTabDupEnrichment === 'function') {
          scheduleInputTabDupEnrichment(typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : []);
        }
      }, 800);

      const optimisticItems = addedChunks.map((content) => ({
        id: makeTempId(),
        content,
        timestamp: new Date().toISOString(),
        folder: isInboxDest ? '📥 INBOX' : destFolder,
        file: destFile,
        isInbox: isInboxDest,
        _pending: true
      }));
      rememberDumpedItems(optimisticItems);
      const netNewCount = Math.max(0, addedChunks.length - replacedDupChunks.length);
      if (isInboxDest && netNewCount > 0) bumpBadgeOptimistic(netNewCount);

      const lastHistoryId = logOperation(
        'ADD',
        isInboxDest
          ? `${addedChunks.length}件を INBOX に追加`
          : `${addedChunks.length}件を ${destFolder} > ${destFile} に追加`,
        { folder: destFolder, file: destFile, contents: addedChunks, replaced: replacedDupChunks }
      );
      localStorage.setItem('lastDumpTime', new Date().toISOString());
      if (typeof recordDumpVolume === 'function') recordDumpVolume(addedChunks);
      setTimeout(() => { loadStats({ skipFetch: true }); }, 500);

      let label = `✓ ${addedChunks.length}件を受け付けました`;
      if (replacedDupChunks.length > 0) label += ` (同一 ${replacedDupChunks.length}件は過去を削除して更新)`;
      const undoHtml = lastHistoryId
        ? `<button onclick="document.getElementById('input-status').innerHTML=''; undoOperation('${lastHistoryId}', true)" class="mt-1 px-3 py-1 bg-gray-800 hover:bg-gray-700 text-gray-200 text-sm font-normal rounded-full border border-gray-600 transition-colors shadow-lg active:scale-95 inline-flex items-center gap-1"><span class="text-lg leading-none -mt-0.5">↺</span> 取り消す</button>`
        : '';
      const dumpChars = addedChunks.reduce((n, c) => n + String(c || '').length, 0);

      const dumpJob = {
        id: makePendingWriteId(),
        type: 'dump_add',
        addedChunks: addedChunks.slice(),
        replaceDupChunks: replacedDupChunks.slice(),
        destFolder,
        destFile,
        isInboxDest,
        directFolder,
        historyId: lastHistoryId,
        pendingReplaceId: pendingReplace && pendingReplace.id ? pendingReplace.id : '',
        pendingImages: imagesToUpload.length ? imagesToUpload : undefined
      };
      if (status) {
        const photoExtraMs = imagesToUpload.length * 4500;
        addSyncGaugeJob(status, {
          id: dumpJob.id,
          historyId: lastHistoryId,
          label: imagesToUpload.length ? `✓ ${addedChunks.length}件を受け付けました (写真アップロード中)` : label,
          estimateMs: syncGaugeEstimateMs(dumpChars) + photoExtraMs,
          count: addedChunks.length,
          undoHtml
        });
      }
      addPendingInboxWrite(dumpJob);
      markPendingWriteQueued(dumpJob.id);

      enqueueInboxWrite(async () => {
        pendingWriteRunningIds.add(dumpJob.id);
        try {
          const result = await executeDumpAddJob(dumpJob);
          removePendingInboxWrite(dumpJob.id);
          const purgedInboxCount = (result && result.purgedInboxCount) || 0;
          const replacedDupCount = (result && result.replacedDupCount) || replacedDupChunks.length;
          let doneMsg = appendDupCheckTiming(`✓ ${addedChunks.length}件の保存が完了しました`);
          if (replacedDupChunks.length > 0) doneMsg += ` (同一 ${replacedDupChunks.length}件は過去を削除して更新)`;
          if (purgedInboxCount > 0) doneMsg += ` (INBOX重複 ${purgedInboxCount}件を自動削除)`;
          if (replacedDupCount > 0 && replacedDupChunks.length === 0) {
            doneMsg += ` (過去 ${replacedDupCount}件を削除)`;
          }
          if (cancelledDumpHistoryIds.has(lastHistoryId)) {
            dropSyncGaugeByHistory(lastHistoryId);
          } else if (status) {
            settleSyncGaugeJob(status, dumpJob.id, {
              doneText: doneMsg,
              className: 'text-base mt-2 text-center font-bold text-emerald-400'
            });
          }
        } finally {
          pendingWriteRunningIds.delete(dumpJob.id);
          clearPendingWriteQueued(dumpJob.id);
          ensureSubmitInboxReady({ force: true, reason: 'dump_add_done' });
        }
      }, {
        historyId: lastHistoryId,
        onError: (err) => {
          clearPendingWriteQueued(dumpJob.id);
          bumpPendingInboxWriteAttempt(dumpJob.id);
          const isTimeoutOrNetwork = err && (
            err.isTimeout === true
            || err.name === 'AbortError'
            || String(err.message).includes('timeout')
            || String(err.message).includes('aborted')
            || !navigator.onLine
          );
          if (isTimeoutOrNetwork) {
            console.warn('Dump write deferred to pending writes queue (timeout/offline):', dumpJob.id);
            if (status) {
              settleSyncGaugeJob(status, dumpJob.id, {
                doneText: `✓ 端末に保存しました（電波回復時に自動送信）`,
                className: 'text-base mt-2 text-center font-bold text-cyan-300'
              });
            }
            ensureSubmitInboxReady({ force: true, reason: 'timeout_offline_saved' });
            return;
          }
          if (cancelledDumpHistoryIds.has(lastHistoryId)) return;
          inboxInputClearToken++;
          forgetDumpedItemsByContents(addedChunks);
          cacheLocalInputHistory(getLocalInputHistory().filter((e) => !addedChunks.includes(e.content)));
          if (pendingReplace && pendingReplace.content) {
            appendLocalInputHistory([pendingReplace.content], destFolder, destFile);
          }
          paintInputTabHistory(getLocalInputHistory());
          if (isInboxDest && netNewCount > 0) bumpBadgeOptimistic(-netNewCount);
          if (typeof resetLiveDraftSubmitEchoGuard === 'function') resetLiveDraftSubmitEchoGuard();
          if (!textarea.value.trim()) {
            textarea.value = rawContent;
          } else {
            textarea.value = rawContent + '\n\n' + textarea.value;
          }
          if (!pendingInputHistoryReplace && typeof onLiveInputDraftChanged === 'function') {
            onLiveInputDraftChanged({ immediateCloud: true, reason: 'submit_rollback' });
          }
          const reason = err && err.message === 'write'
            ? 'サーバーへの保存に失敗しました'
            : (err && err.message ? String(err.message) : '通信エラー');
          settleSyncGaugeJob(status, dumpJob.id, {
            failed: true,
            doneText: `エラー（${reason}）。入力を復元しました（再開時に再同期します）`,
            className: 'text-base mt-2 text-center font-bold text-rose-400'
          });
        }
      });
    }
    function getCaptureNavReservePx() {
      if (document.body.classList.contains('capture-keyboard-open')
        && !document.body.classList.contains('capture-keyboard-keep-memo')) {
        return 0;
      }
      const sig = (document.body.className || '') + '|' + (document.getElementById('memo-sub-nav') ? document.getElementById('memo-sub-nav').className : '');
      const now = Date.now();
      if (getCaptureNavReservePx._cache
        && getCaptureNavReservePx._cache.sig === sig
        && (now - getCaptureNavReservePx._cache.at) < 500) {
        return getCaptureNavReservePx._cache.h;
      }
      let total = 0;
      const mainNav = document.getElementById('app-bottom-nav');
      if (mainNav && !mainNav.classList.contains('invisible')) {
        const h = Math.ceil(mainNav.getBoundingClientRect().height);
        if (Number.isFinite(h) && h > 0) total += h;
      }
      const memoNav = document.getElementById('memo-sub-nav');
      if (memoNav && !memoNav.classList.contains('hidden') && !memoNav.classList.contains('invisible') && getComputedStyle(memoNav).display !== 'none') {
        const h = Math.ceil(memoNav.getBoundingClientRect().height);
        if (Number.isFinite(h) && h > 0) total += h;
      }
      const height = total > 0 ? total : 80;
      getCaptureNavReservePx._cache = { sig, h: height, at: now };
      return height;
    }

    function setCaptureKeyboardChromeHidden(hidden, opts) {
      opts = opts || {};
      const hideParent = !!hidden;
      const keepMemoSub = !!(hideParent && opts.keepMemoSub);
      const sig = hideParent ? (keepMemoSub ? 'keep' : 'hide') : 'show';
      const nav = document.getElementById('app-bottom-nav');
      const memoNav = document.getElementById('memo-sub-nav');
      const hideMemo = hideParent && !keepMemoSub;
      // 表示に戻すときはキャッシュ一致でも、実クラスが残っていたら必ず直す
      const needsRepair = !hideParent && (
        document.body.classList.contains('capture-keyboard-open')
        || document.body.classList.contains('capture-keyboard-keep-memo')
        || (nav && nav.classList.contains('invisible'))
        || (memoNav && memoNav.classList.contains('invisible') && document.body.classList.contains('memo-sub-visible'))
      );
      if (document.body.dataset.captureChrome === sig && !needsRepair) return;
      document.body.dataset.captureChrome = sig;
      document.body.classList.toggle('capture-keyboard-open', hideParent);
      document.body.classList.toggle('capture-keyboard-keep-memo', keepMemoSub);
      if (nav) {
        nav.classList.toggle('invisible', hideParent);
        nav.classList.toggle('pointer-events-none', hideParent);
        nav.setAttribute('aria-hidden', hideParent ? 'true' : 'false');
        if (!hideParent) nav.style.opacity = '';
      }
      if (memoNav) {
        memoNav.classList.toggle('invisible', hideMemo);
        memoNav.classList.toggle('pointer-events-none', hideMemo);
        memoNav.setAttribute('aria-hidden', hideMemo ? 'true' : 'false');
        if (!hideMemo) memoNav.style.opacity = '';
      }
    }

    const CAPTURE_DECOR_IDS = [
      'portal-container',
      'floating-icons-container',
      'space-background',
      'input-floating-elements',
      'input-nebulas'
    ];

    function setCaptureDecorHidden(hidden) {
      CAPTURE_DECOR_IDS.forEach((id) => {
        const el = document.getElementById(id);
        if (!el) return;
        if (hidden) {
          if (el.dataset.captureDecorDisplay === undefined) {
            el.dataset.captureDecorDisplay = el.style.display || '';
          }
          el.style.display = 'none';
          el.style.visibility = 'hidden';
          el.style.opacity = '0';
          el.setAttribute('aria-hidden', 'true');
        } else {
          el.style.display = el.dataset.captureDecorDisplay || '';
          el.style.visibility = '';
          el.style.opacity = '';
          delete el.dataset.captureDecorDisplay;
          el.removeAttribute('aria-hidden');
        }
      });
      document.querySelectorAll('.spacetime-tunnel').forEach((el) => {
        if (hidden) {
          if (el.dataset.captureDecorDisplay === undefined) {
            el.dataset.captureDecorDisplay = el.style.display || '';
          }
          el.style.display = 'none';
          el.style.visibility = 'hidden';
          el.style.opacity = '0';
        } else {
          el.style.display = el.dataset.captureDecorDisplay || '';
          el.style.visibility = '';
          el.style.opacity = '';
          delete el.dataset.captureDecorDisplay;
        }
      });
    }

    function setCaptureChrome(open) {
      document.documentElement.classList.toggle('capture-overlay-open', !!open);
      document.body.classList.toggle('capture-overlay-open', !!open);
      setCaptureDecorHidden(!!open);
      const nav = document.getElementById('app-bottom-nav');
      const memoNav = document.getElementById('memo-sub-nav');
      const inputMode = document.getElementById('input-mode');
      const fabSync = document.getElementById('cross-device-sync-btn');
      const overlay = document.getElementById('capture-overlay');
      const keepTabsVisible = !!(typeof isSkipInputTopEnabled === 'function' && isSkipInputTopEnabled());
      if (!open) setCaptureKeyboardChromeHidden(false);
      // 入力オーバーレイをナビより前面に（DUMPが下タブに隠れない）
      // 高さは nav 分だけ縮めるので、下タブは隙間から操作できる
      // トップ非表示時はタブバーを常に前面へ（閉じる手段がタブ移動のみのため）
      if (overlay) {
        overlay.classList.toggle('z-[80]', !!open && !keepTabsVisible);
        overlay.classList.toggle('z-[60]', !open || keepTabsVisible);
      }
      if (nav) {
        nav.classList.toggle('z-[90]', !!open && keepTabsVisible);
        nav.classList.toggle('z-50', !(open && keepTabsVisible));
        nav.classList.remove('z-[70]');
        // キーボードで親タブを隠している最中は強制表示しない
        if (!open || !document.body.classList.contains('capture-keyboard-open')) {
          nav.classList.remove('invisible', 'pointer-events-none');
          nav.setAttribute('aria-hidden', 'false');
        }
      }
      if (memoNav) {
        memoNav.classList.toggle('z-[85]', !!open && keepTabsVisible);
        memoNav.classList.toggle('z-[48]', !(open && keepTabsVisible));
        memoNav.classList.remove('z-[70]');
        // キーボードで隠している最中は強制表示しない
        if (!open || !document.body.classList.contains('capture-keyboard-open')) {
          memoNav.classList.remove('invisible', 'pointer-events-none');
          memoNav.setAttribute('aria-hidden', 'false');
        }
      }
      if (inputMode) {
        inputMode.classList.toggle('z-[60]', open);
        inputMode.classList.toggle('z-40', !open);
      }
      // CAPTURE中はヘッダー内の同期アイコンを使うのでFABは隠す
      if (fabSync) {
        fabSync.classList.toggle('invisible', open);
        fabSync.classList.toggle('pointer-events-none', open);
      }
    }

    let inputCaretRevealToken = 0;
    /** 入力欄の表示位置をカーソルに合わせる。先頭なら上端まで戻す。 */
    function revealInputCaret(input) {
      const ta = (input && input.id === 'input-content')
        ? input
        : document.getElementById('input-content');
      if (!ta) return;
      const token = ++inputCaretRevealToken;
      const apply = () => {
        if (token !== inputCaretRevealToken || !ta.isConnected) return;
        const start = typeof ta.selectionStart === 'number' ? ta.selectionStart : 0;
        const end = typeof ta.selectionEnd === 'number' ? ta.selectionEnd : start;
        if (start === 0 && end === 0) {
          if (ta.scrollTop !== 0) ta.scrollTop = 0;
          return;
        }
        const style = getComputedStyle(ta);
        const parsed = parseFloat(style.lineHeight);
        const lineHeight = Number.isFinite(parsed) && parsed > 0 ? parsed : 24;
        const caretLine = String(ta.value || '').slice(0, end).split('\n').length - 1;
        const caretTop = Math.max(0, caretLine * lineHeight);
        const caretBottom = caretTop + lineHeight;
        const viewBottom = ta.scrollTop + Math.max(0, ta.clientHeight - 6);
        if (caretTop < ta.scrollTop) ta.scrollTop = caretTop;
        else if (caretBottom > viewBottom) ta.scrollTop = Math.max(0, caretBottom - ta.clientHeight + 6);
      };
      apply();
      requestAnimationFrame(apply);
      [80, 240, 520, 900, 1400].forEach((ms) => setTimeout(apply, ms));
    }

    function resetCaptureOverlayViewport() {
      const overlay = document.getElementById('capture-overlay');
      if (!overlay) return;
      overlay.style.top = '';
      overlay.style.left = '';
      overlay.style.width = '';
      overlay.style.height = '';
      overlay.style.bottom = '';
      overlay.style.right = '';
      overlay.style.paddingBottom = '';
      overlay.classList.remove('is-keyboard-open');
      delete overlay.dataset.vvGeom;
      delete overlay.dataset.vvMaxH;
    }

    function syncCaptureOverlayViewport() {
      const overlay = document.getElementById('capture-overlay');
      if (!overlay || !isCaptureOverlayOpen()) {
        setCaptureKeyboardChromeHidden(false);
        resetCaptureOverlayViewport();
        return;
      }
      const input = document.getElementById('input-content');
      const inputFocused = !!(input && document.activeElement === input);
      const narrow = window.matchMedia('(max-width: 640px)').matches;
      const vv = window.visualViewport;
      let covered = 0;
      if (vv) {
        // innerHeight 基準（screen.height はブラウザUI分で常に「キーボードあり」扱いになりやすい）
        const layoutCovered = Math.max(0, window.innerHeight - vv.height - (vv.offsetTop || 0));
        covered = layoutCovered;
        // オーバーレイ表示中の最大 vv 高さを基準に、大きく縮んだらキーボードとみなす
        const prevMax = Number(overlay.dataset.vvMaxH || 0);
        if (layoutCovered < 48) {
          const nextMax = Math.max(prevMax, Math.round(vv.height));
          if (nextMax > 0) overlay.dataset.vvMaxH = String(nextMax);
        } else if (!prevMax && vv.height > 0) {
          overlay.dataset.vvMaxH = String(Math.round(Math.max(vv.height, window.innerHeight)));
        }
        const baseline = Number(overlay.dataset.vvMaxH || 0);
        if (baseline > 0) {
          const shrink = baseline - vv.height;
          if (shrink > 110) covered = Math.max(covered, shrink);
        }
      } else if (inputFocused && narrow) {
        // visualViewport 非対応端末のみ、フォーカス中は控えめにキーボード扱い
        covered = 100;
      }
      // 実カバーがあるときだけキーボード扱い（フォーカスだけではタブを消さない）
      const realKeyboard = covered > 90;
      const keyboardOpen = realKeyboard;
      const wasKeyboard = overlay.classList.contains('is-keyboard-open');
      if (wasKeyboard !== keyboardOpen) overlay.classList.toggle('is-keyboard-open', keyboardOpen);
      if (!wasKeyboard && keyboardOpen && input) revealInputCaret(input);

      // キーボードが閉じたら必ず下タブを戻す（狭い画面のみキーボード中は隠す）
      const hideBottomChrome = keyboardOpen && narrow;
      setCaptureKeyboardChromeHidden(hideBottomChrome);

      const navH = hideBottomChrome ? 0 : getCaptureNavReservePx();
      if (vv) {
        const top = Math.round(vv.offsetTop) + 'px';
        const left = Math.round(vv.offsetLeft) + 'px';
        const width = Math.round(vv.width) + 'px';
        const height = Math.max(140, Math.round(vv.height - navH)) + 'px';
        const pad = hideBottomChrome ? '0.5rem' : '0.35rem';
        const geom = top + '|' + left + '|' + width + '|' + height + '|' + pad;
        if (overlay.dataset.vvGeom !== geom) {
          overlay.dataset.vvGeom = geom;
          overlay.style.top = top;
          overlay.style.left = left;
          overlay.style.width = width;
          overlay.style.height = height;
          overlay.style.paddingBottom = pad;
          overlay.style.right = 'auto';
          overlay.style.bottom = 'auto';
        }
      }
      if (wasKeyboard !== keyboardOpen && typeof syncInputTabHistoryLock === 'function') syncInputTabHistoryLock();
    }

    function bindCaptureOverlayViewport() {
      if (bindCaptureOverlayViewport._bound) return;
      bindCaptureOverlayViewport._bound = true;
      let viewportSyncRaf = 0;
      const sync = () => {
        if (viewportSyncRaf) return;
        viewportSyncRaf = requestAnimationFrame(() => {
          viewportSyncRaf = 0;
          syncCaptureOverlayViewport();
        });
      };
      if (window.visualViewport) {
        window.visualViewport.addEventListener('resize', sync);
        window.visualViewport.addEventListener('scroll', sync);
      }
      window.addEventListener('resize', sync);
      document.addEventListener('focusin', (e) => {
        if (e.target && e.target.id === 'input-content') {
          sync();
          revealInputCaret(e.target);
        }
      });
      document.addEventListener('focusout', (e) => {
        if (e.target && e.target.id === 'input-content') {
          // キーボード収納アニメのあとにタブを戻す
          setTimeout(sync, 80);
          setTimeout(sync, 280);
        }
      });
    }

    function openCaptureOverlay(evOrOpts) {
      const isEvent = !!(evOrOpts && (typeof evOrOpts.preventDefault === 'function' || evOrOpts.target));
      const ev = isEvent ? evOrOpts : null;
      const opts = isEvent ? {} : (evOrOpts || {});
      if (ev && typeof ev.preventDefault === 'function') {
        try { ev.preventDefault(); } catch (_) { }
        try { ev.stopPropagation(); } catch (_) { }
      }
      document.documentElement.classList.add('pause-animations');
      setCaptureChrome(true);
      const overlay = document.getElementById('capture-overlay');
      if (!overlay) return;
      overlay.classList.remove('opacity-0', 'pointer-events-none');
      overlay.classList.add('opacity-100');
      updateSkipInputTopUI();
      toggleDirectDestinationUI();
      bindSubmitInboxImeCommit();
      bindCaptureOverlayViewport();
      syncCaptureOverlayViewport();
      const input = document.getElementById('input-content');
      if (input) {
        input.removeAttribute('readonly');
        input.removeAttribute('disabled');
      }
      resetInputHistoryCloudSyncPause();
      if (typeof forceHideLoader === 'function') forceHideLoader();
      if (!opts.skipHistoryPaint && typeof purgeCorruptLocalInputHistory === 'function') purgeCorruptLocalInputHistory();
      ensureSubmitInboxReady({ force: true, reason: 'open_capture' });
      setInputHistoryReplaceHint(!!pendingInputHistoryReplace);
      if (typeof restoreLiveInputDraftSync === 'function') restoreLiveInputDraftSync();
      bindInputContentHistoryLock();
      bindInputContentEditorKeys();
      if (typeof restoreLiveInputDraftFromCacheStorage === 'function') {
        void restoreLiveInputDraftFromCacheStorage();
      }
      if (!opts.skipHistoryCloudSync && typeof syncLiveInputDraftWithCloud === 'function') {
        runInBackground(() => syncLiveInputDraftWithCloud({ reason: 'open_capture' }));
      }
      if (!opts.skipHistoryPaint) {
        try {
          renderInputTabHistory({ skipCloudSync: !!opts.skipHistoryCloudSync });
        } catch (e) {
          console.error('renderInputTabHistory failed', e);
        }
      }
      // 既にキュー済みの保存は再表示しない（「未同期を送信中」が長く見えるのを防ぐ）
      if (typeof resumePendingInboxWrites === 'function') {
        resumePendingInboxWrites({ silent: true });
      }
      syncInputTabHistoryLock();
      updateSkipInputTopUI();
      setTimeout(() => {
        syncCaptureOverlayViewport();
        ensureSubmitInboxReady({ force: true, reason: 'open_capture_settle' });
        syncCaptureOverlayViewport();
      }, 50);
      revealInputCaret(input);
      if (!opts.skipAutoFocus) {
        const focusDelay = opts.quickFocus ? 80 : 150;
        setTimeout(() => {
          ensureSubmitInboxReady({ force: true, reason: 'open_capture_late' });
          syncCaptureOverlayViewport();
          if (input) {
            try { input.focus({ preventScroll: true }); } catch (_) {
              try { input.focus(); } catch (__) { }
            }
            revealInputCaret(input);
          }
        }, focusDelay);
      } else {
        setTimeout(() => {
          ensureSubmitInboxReady({ force: true, reason: 'open_capture_late' });
          syncCaptureOverlayViewport();
          revealInputCaret(input);
        }, 120);
      }
    }
    window.addEventListener('pageshow', () => {
      if (isCaptureOverlayOpen()) revealInputCaret();
    });
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible' && isCaptureOverlayOpen()) revealInputCaret();
    });
    function closeCaptureOverlay(opts) {
      opts = opts || {};
      const inputMode = document.getElementById('input-mode');
      if (!opts.force && inputMode && inputMode.classList.contains('active')) {
        updateSkipInputTopUI(true);
        return;
      }
      document.documentElement.classList.remove('pause-animations');
      resetCaptureOverlayViewport();
      setCaptureChrome(false);
      // 入力→即閉じでも未同期を裏送信（表示は出さない）
      if (typeof flushPendingWritesOnLeave === 'function') flushPendingWritesOnLeave();
    }

    // 表示件数の打ち切りはしない（全件スクロール表示）※描画はチャンク分割で軽量化
    const INPUT_TAB_HISTORY_MAX = 5000;
    const INPUT_TAB_PAINT_CHUNK = 36;
    const INPUT_TAB_DUP_ENRICH_MAX = 48; // 重複バッジは新しい順にこの件数まで
    const INPUT_TAB_OVERLAP_MIN_LEN = 8;
    let inputTabPaintToken = 0;
    let inputTabLastPaintSig = '';
    let inputTabHistoryDirty = false;
    let inputTabLockTimer = null;

    function hasInputContentDraft() {
      const ta = document.getElementById('input-content');
      if (ta && String(ta.value || '').trim()) return true;
      return !!(typeof dumpComposeImages !== 'undefined' && dumpComposeImages.length);
    }

    function isInputHistoryLoadLocked() {
      if (pendingInputHistoryReplace) return false;
      return hasInputContentDraft();
    }

    function syncInputTabHistoryLockNow() {
      const locked = isInputHistoryLoadLocked();
      const hint = document.getElementById('input-tab-history-lock-hint');
      const list = document.getElementById('input-tab-history-list');
      // キーボード表示中もヒントを出す（隠すと「読み込まれない」に見える）
      if (hint && hint.classList.contains('hidden') === locked) {
        hint.classList.toggle('hidden', !locked);
      }
      const recent = document.getElementById('input-tab-history-recent');
      [list, recent].forEach((el) => {
        if (!el) return;
        if (el.classList.contains('is-history-locked') === locked) return;
        el.classList.toggle('is-history-locked', locked);
      });
    }

    function syncInputTabHistoryLock() {
      if (inputTabLockTimer) return;
      inputTabLockTimer = setTimeout(() => {
        inputTabLockTimer = null;
        syncInputTabHistoryLockNow();
      }, 100);
    }

    const LIVE_INPUT_DRAFT_STORAGE_KEY = 'dump_live_input_draft_v1';
    const LIVE_INPUT_DRAFT_CLOUD_ID_KEY = 'dump_live_input_draft_cloud_id_v1';
    const LIVE_INPUT_DRAFT_INSTANCE_KEY = 'dump_live_input_draft_instance_v1';
    const LIVE_INPUT_DRAFT_CLOUD_FOLDER = '__SYSTEM__';
    const LIVE_INPUT_DRAFT_CLOUD_FILE = 'input_draft_sync';
    const LIVE_INPUT_DRAFT_SUPERSEDED_FILE = 'input_draft_superseded';
    const LIVE_INPUT_DRAFT_CACHE_NAME = 'dump-input-draft-v1';
    const LIVE_INPUT_DRAFT_CACHE_URL = './__live_input_draft.json';
    const LIVE_INPUT_DRAFT_DEBOUNCE_MS = 650;
    const LIVE_INPUT_DRAFT_MAX_WAIT_MS = 2500;

    let liveDraftMemoryInstanceId = '';
    let liveDraftCloudTimer = null;
    let liveDraftMaxWaitTimer = null;
    let liveDraftStoreReady = false;
    let liveDraftCloudPushing = false;
    let liveDraftCloudPushQueued = false;
    let liveDraftCloudSyncing = false;
    let liveDraftCloudSyncQueued = false;
    let liveDraftMutationVersion = 0;
    let liveDraftCacheSeq = 0;
    let liveDraftLastSeenCloudMs = 0;
    let liveDraftRestoredSyncOnce = false;
    let liveDraftRestoredCacheOnce = false;
    let liveDraftUserTouchedBeforeRestore = false;
    let liveDraftImageUploadRunning = false;
    let liveDraftDeferredCloudApply = null;
    let liveDraftSubmitEchoUntil = 0;
    let liveDraftSubmitEchoRaw = '';
    let liveDraftLastKeepaliveSig = '';
    let liveDraftLastKeepaliveAt = 0;

    function getLiveInputDraftInstanceId() {
      try {
        const existing = localStorage.getItem(LIVE_INPUT_DRAFT_INSTANCE_KEY);
        if (existing) return existing;
        const created = 'inst-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
        localStorage.setItem(LIVE_INPUT_DRAFT_INSTANCE_KEY, created);
        return created;
      } catch (_) {
        if (!liveDraftMemoryInstanceId) {
          liveDraftMemoryInstanceId = 'inst-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
        }
        return liveDraftMemoryInstanceId;
      }
    }

    function getCachedLiveInputDraftCloudId() {
      try {
        const id = localStorage.getItem(LIVE_INPUT_DRAFT_CLOUD_ID_KEY);
        return id ? String(id) : '';
      } catch (_) {
        return '';
      }
    }

    function cacheLiveInputDraftCloudId(id) {
      try {
        if (id) localStorage.setItem(LIVE_INPUT_DRAFT_CLOUD_ID_KEY, String(id));
        else localStorage.removeItem(LIVE_INPUT_DRAFT_CLOUD_ID_KEY);
      } catch (_) { }
    }

    function normalizeLiveDraftRemoteUrls(urls) {
      const out = [];
      const seen = new Set();
      (Array.isArray(urls) ? urls : []).forEach((u) => {
        const s = String(u || '').trim();
        if (!s || seen.has(s)) return;
        seen.add(s);
        out.push(s);
      });
      return out;
    }

    function liveDraftContentSignature(draftText, remoteUrls) {
      return String(draftText || '') + '\u0000' + normalizeLiveDraftRemoteUrls(remoteUrls).join('\u0001');
    }

    function nextLiveDraftTimestampMs(prevLocalMs) {
      const prev = Number(prevLocalMs) || 0;
      const seen = Number(liveDraftLastSeenCloudMs) || 0;
      return Math.max(Date.now(), prev + 1, seen + 1);
    }

    function readLocalLiveInputDraft() {
      try {
        const raw = localStorage.getItem(LIVE_INPUT_DRAFT_STORAGE_KEY);
        if (!raw) return null;
        const p = JSON.parse(raw);
        if (!p || typeof p !== 'object') return null;
        const updatedAtMs = Number(p.updatedAtMs);
        if (!Number.isFinite(updatedAtMs) || updatedAtMs < 0) return null;
        return {
          v: 1,
          draftText: p.draftText != null ? String(p.draftText) : '',
          remoteUrls: normalizeLiveDraftRemoteUrls(p.remoteUrls),
          localImageCount: Math.max(0, Number(p.localImageCount) || 0),
          updatedAtMs,
          updatedAt: p.updatedAt ? String(p.updatedAt) : new Date(updatedAtMs).toISOString(),
          instanceId: p.instanceId ? String(p.instanceId) : getLiveInputDraftInstanceId(),
          dirty: !!p.dirty
        };
      } catch (_) {
        return null;
      }
    }

    function writeLocalLiveInputDraft(draft) {
      if (!draft || typeof draft !== 'object') return;
      const updatedAtMs = Number(draft.updatedAtMs) || Date.now();
      const payload = {
        v: 1,
        draftText: String(draft.draftText || ''),
        remoteUrls: normalizeLiveDraftRemoteUrls(draft.remoteUrls),
        localImageCount: Math.max(0, Number(draft.localImageCount) || 0),
        updatedAtMs,
        updatedAt: draft.updatedAt ? String(draft.updatedAt) : new Date(updatedAtMs).toISOString(),
        instanceId: draft.instanceId ? String(draft.instanceId) : getLiveInputDraftInstanceId(),
        dirty: !!draft.dirty
      };
      try {
        localStorage.setItem(LIVE_INPUT_DRAFT_STORAGE_KEY, JSON.stringify(payload));
      } catch (e) {
        console.warn('writeLocalLiveInputDraft failed', e);
      }
    }

    function activateLiveDraftSubmitEchoGuard(dumpedRaw) {
      liveDraftSubmitEchoRaw = String(dumpedRaw || '');
      liveDraftSubmitEchoUntil = Date.now() + 700;
    }

    function resetLiveDraftSubmitEchoGuard() {
      liveDraftSubmitEchoRaw = '';
      liveDraftSubmitEchoUntil = 0;
    }

    function liveDraftMatchesSubmitEcho(value) {
      if (!liveDraftSubmitEchoUntil || Date.now() > liveDraftSubmitEchoUntil) {
        resetLiveDraftSubmitEchoGuard();
        return false;
      }
      const dumped = String(liveDraftSubmitEchoRaw || '');
      const dumpedTrim = dumped.trim();
      if (!dumpedTrim) return false;
      const v = String(value || '');
      const vt = v.trim();
      if (!vt) return false;
      if (v === dumped || vt === dumpedTrim) return true;
      if (typeof dumpContentEquals === 'function' && dumpContentEquals(v, dumped)) return true;
      const minEcho = Math.min(8, dumpedTrim.length);
      if (vt.length >= minEcho && (dumpedTrim.startsWith(vt) || dumped.startsWith(v))) return true;
      if (vt.length >= Math.ceil(dumpedTrim.length * 0.6)
        && (dumped.includes(v) || dumpedTrim.includes(vt))) return true;
      resetLiveDraftSubmitEchoGuard();
      return false;
    }

    function collectLiveComposeDraftImagesSnapshot() {
      const list = Array.isArray(typeof dumpComposeImages !== 'undefined' ? dumpComposeImages : null)
        ? dumpComposeImages
        : [];
      const remoteUrls = [];
      const seenUrls = new Set();
      const compactPendingImages = [];
      let localImageCount = 0;
      list.forEach((img) => {
        if (!img) return;
        const rUrl = img.remoteUrl ? String(img.remoteUrl).trim() : '';
        if (rUrl && !seenUrls.has(rUrl)) {
          seenUrls.add(rUrl);
          remoteUrls.push(rUrl);
        }
        if (!rUrl) localImageCount += 1;
        compactPendingImages.push({
          id: String(img.id || makeDumpComposeImageId()),
          dataUrl: !rUrl && img.dataUrl ? String(img.dataUrl) : '',
          remoteUrl: rUrl,
          fileName: img.fileName || 'dump.jpg',
          mimeType: img.mimeType || 'image/jpeg'
        });
      });
      return { remoteUrls, compactPendingImages, localImageCount };
    }

    function buildLiveDraftCloudPayload(draft) {
      const updatedAtMs = Number(draft && draft.updatedAtMs) || Date.now();
      return JSON.stringify({
        v: 1,
        updatedAt: (draft && draft.updatedAt) ? String(draft.updatedAt) : new Date(updatedAtMs).toISOString(),
        updatedAtMs,
        instanceId: (draft && draft.instanceId) ? String(draft.instanceId) : getLiveInputDraftInstanceId(),
        draftText: String((draft && draft.draftText) || ''),
        remoteUrls: normalizeLiveDraftRemoteUrls(draft && draft.remoteUrls)
      });
    }

    async function mirrorLiveInputDraftToCacheStorage(draft, pendingImagesSnapshot) {
      if (typeof caches === 'undefined' || !draft) return;
      const seq = ++liveDraftCacheSeq;
      try {
        const snap = Array.isArray(pendingImagesSnapshot)
          ? pendingImagesSnapshot
          : collectLiveComposeDraftImagesSnapshot().compactPendingImages;
        const cache = await caches.open(LIVE_INPUT_DRAFT_CACHE_NAME);
        if (seq !== liveDraftCacheSeq) return;
        const payload = {
          v: 1,
          draftText: String(draft.draftText || ''),
          remoteUrls: normalizeLiveDraftRemoteUrls(draft.remoteUrls),
          pendingImages: snap,
          updatedAtMs: Number(draft.updatedAtMs) || Date.now(),
          updatedAt: draft.updatedAt || new Date().toISOString(),
          instanceId: draft.instanceId || getLiveInputDraftInstanceId(),
          dirty: !!draft.dirty,
          cloudId: getCachedLiveInputDraftCloudId(),
          gasUrl: typeof GAS_API_URL === 'string' ? GAS_API_URL : '',
          supabaseRpcUrl: typeof SUPABASE_RPC_URL === 'string' ? SUPABASE_RPC_URL : '',
          supabaseAnonKey: typeof SUPABASE_ANON_KEY === 'string' ? SUPABASE_ANON_KEY : ''
        };
        await cache.put(
          LIVE_INPUT_DRAFT_CACHE_URL,
          new Response(JSON.stringify(payload), {
            headers: { 'Content-Type': 'application/json' }
          })
        );
        if (seq === liveDraftCacheSeq && draft.dirty && 'serviceWorker' in navigator) {
          navigator.serviceWorker.ready.then((reg) => {
            if (reg && reg.sync && typeof reg.sync.register === 'function') {
              return reg.sync.register('dump-live-input-draft').catch(() => { });
            }
          }).catch(() => { });
        }
      } catch (e) {
        console.warn('mirrorLiveInputDraftToCacheStorage failed', e);
      }
    }

    function applyLiveInputDraftToUi(draft, opts) {
      opts = opts || {};
      if (!draft) return false;
      if (pendingInputHistoryReplace || inputContentComposing) {
        liveDraftDeferredCloudApply = draft;
        return false;
      }
      const ta = document.getElementById('input-content');
      if (!ta) return false;
      const nextText = String(draft.draftText || '');
      const nextRemoteUrls = normalizeLiveDraftRemoteUrls(draft.remoteUrls);
      const changedText = ta.value !== nextText;
      if (changedText) {
        ta.value = nextText;
      }
      if (typeof dumpComposeImages !== 'undefined' && Array.isArray(dumpComposeImages)) {
        const curRemoteUrls = dumpComposeImages.map((x) => (x && x.remoteUrl) || '').filter(Boolean);
        const curLocalImages = dumpComposeImages.filter((x) => x && !x.remoteUrl);
        const remoteDiff = nextRemoteUrls.join('\n') !== curRemoteUrls.join('\n');
        const shouldClearAll = opts.allowClearImages && nextRemoteUrls.length === 0 && nextText === '';
        if (shouldClearAll && dumpComposeImages.length > 0) {
          clearDumpComposeImages({ skipDraftSync: true });
        } else if (opts.replaceAllImages || remoteDiff) {
          const preservedLocals = opts.replaceAllImages ? [] : curLocalImages.slice();
          if (opts.replaceAllImages) {
            dumpComposeImages.forEach((img) => {
              if (img && img.blobUrl && String(img.blobUrl).indexOf('blob:') === 0) {
                try { URL.revokeObjectURL(img.blobUrl); } catch (_) { }
              }
            });
          }
          const restoredRemotes = nextRemoteUrls.map((url) => ({
            id: makeDumpComposeImageId(),
            blobUrl: url,
            remoteUrl: url,
            fileName: 'photo.jpg',
            mimeType: 'image/jpeg'
          }));
          dumpComposeImages = restoredRemotes.concat(preservedLocals).slice(0, DUMP_COMPOSE_IMAGE_MAX);
          if (typeof paintDumpComposeImages === 'function') paintDumpComposeImages();
        }
      }
      if (typeof ensureTextUndo === 'function') {
        const store = ensureTextUndo(ta);
        if (store) {
          store.last = ta.value;
          if (typeof updateTextUndoButtons === 'function') updateTextUndoButtons(ta);
        }
      }
      if (typeof syncInputTabHistoryLockNow === 'function') syncInputTabHistoryLockNow();
      if (typeof refreshSubmitInboxAvailability === 'function') refreshSubmitInboxAvailability();
      liveDraftDeferredCloudApply = null;
      return true;
    }

    function applyDeferredCloudLiveInputDraft() {
      if (!liveDraftDeferredCloudApply) return false;
      const pending = liveDraftDeferredCloudApply;
      if (pendingInputHistoryReplace || inputContentComposing) return false;
      const local = readLocalLiveInputDraft();
      if (local && local.dirty && local.updatedAtMs > Number(pending.updatedAtMs || 0)) {
        liveDraftDeferredCloudApply = null;
        return false;
      }
      const next = {
        v: 1,
        draftText: String(pending.draftText || ''),
        remoteUrls: normalizeLiveDraftRemoteUrls(pending.remoteUrls),
        localImageCount: 0,
        updatedAtMs: Number(pending.updatedAtMs) || Date.now(),
        updatedAt: pending.updatedAt || new Date().toISOString(),
        instanceId: pending.instanceId || getLiveInputDraftInstanceId(),
        dirty: false
      };
      if (applyLiveInputDraftToUi(next, { allowClearImages: true })) {
        writeLocalLiveInputDraft(next);
        void mirrorLiveInputDraftToCacheStorage(next);
        return true;
      }
      return false;
    }

    function restoreLiveInputDraftSync() {
      if (liveDraftRestoredSyncOnce) return false;
      if (pendingInputHistoryReplace || liveDraftUserTouchedBeforeRestore) return false;
      const ta = document.getElementById('input-content');
      if (!ta) return false;
      liveDraftRestoredSyncOnce = true;
      if (ta.value !== '' || (typeof dumpComposeImages !== 'undefined' && dumpComposeImages.length > 0)) {
        return false;
      }
      const local = readLocalLiveInputDraft();
      if (!local || (!local.draftText && !(local.remoteUrls && local.remoteUrls.length))) {
        return false;
      }
      return applyLiveInputDraftToUi(local, { replaceAllImages: true });
    }

    async function restoreLiveInputDraftFromCacheStorage() {
      if (liveDraftRestoredCacheOnce || typeof caches === 'undefined') return false;
      liveDraftRestoredCacheOnce = true;
      try {
        const cache = await caches.open(LIVE_INPUT_DRAFT_CACHE_NAME);
        const res = await cache.match(LIVE_INPUT_DRAFT_CACHE_URL);
        if (!res) return false;
        const cached = await res.json().catch(() => null);
        if (!cached || typeof cached !== 'object') return false;
        if (cached.cloudId && !getCachedLiveInputDraftCloudId()) {
          cacheLiveInputDraftCloudId(String(cached.cloudId));
        }
        const cachedUpdatedMs = Number(cached.updatedAtMs) || 0;
        const local = readLocalLiveInputDraft();
        let restoredAny = false;
        if (!local && !pendingInputHistoryReplace && !liveDraftUserTouchedBeforeRestore) {
          const ta = document.getElementById('input-content');
          if (ta && ta.value === '' && (!Array.isArray(dumpComposeImages) || dumpComposeImages.length === 0)) {
            const hasContent = !!(String(cached.draftText || '') || (Array.isArray(cached.remoteUrls) && cached.remoteUrls.length));
            if (hasContent) {
              const recovered = {
                v: 1,
                draftText: String(cached.draftText || ''),
                remoteUrls: normalizeLiveDraftRemoteUrls(cached.remoteUrls),
                localImageCount: 0,
                updatedAtMs: cachedUpdatedMs || Date.now(),
                updatedAt: cached.updatedAt || new Date().toISOString(),
                instanceId: cached.instanceId || getLiveInputDraftInstanceId(),
                dirty: cached.dirty !== false
              };
              writeLocalLiveInputDraft(recovered);
              if (applyLiveInputDraftToUi(recovered, { replaceAllImages: true })) {
                restoredAny = true;
              }
            }
          }
        }
        const pendingImgs = Array.isArray(cached.pendingImages) ? cached.pendingImages : [];
        const localImgsToRestore = pendingImgs.filter((p) => p && !p.remoteUrl && p.dataUrl);
        if (localImgsToRestore.length && !pendingInputHistoryReplace
          && (!local || cachedUpdatedMs >= Number(local.updatedAtMs || 0))) {
          const existingIds = new Set((dumpComposeImages || []).map((x) => x && x.id).filter(Boolean));
          let added = 0;
          localImgsToRestore.forEach((p) => {
            if (dumpComposeImages.length >= DUMP_COMPOSE_IMAGE_MAX) return;
            if (p.id && existingIds.has(String(p.id))) return;
            dumpComposeImages.push({
              id: p.id ? String(p.id) : makeDumpComposeImageId(),
              blobUrl: String(p.dataUrl),
              dataUrl: String(p.dataUrl),
              remoteUrl: '',
              fileName: p.fileName || 'dump.jpg',
              mimeType: p.mimeType || 'image/jpeg'
            });
            added += 1;
          });
          if (added > 0) {
            if (typeof paintDumpComposeImages === 'function') paintDumpComposeImages();
            if (typeof syncInputTabHistoryLockNow === 'function') syncInputTabHistoryLockNow();
            restoredAny = true;
            void preuploadLiveDraftComposeImages();
          }
        }
        if (restoredAny && local && local.dirty) {
          scheduleLiveInputDraftCloudSync({ immediate: false });
        }
        return restoredAny;
      } catch (e) {
        console.warn('restoreLiveInputDraftFromCacheStorage failed', e);
        return false;
      }
    }

    async function preuploadLiveDraftComposeImages() {
      if (liveDraftImageUploadRunning || pendingInputHistoryReplace) return false;
      if (typeof navigator !== 'undefined' && navigator.onLine === false) return false;
      const snapshot = Array.isArray(dumpComposeImages)
        ? dumpComposeImages.filter((img) => img && !img.remoteUrl && img.dataUrl)
        : [];
      if (!snapshot.length) return false;
      liveDraftImageUploadRunning = true;
      let uploadedCount = 0;
      try {
        for (let i = 0; i < snapshot.length; i++) {
          const img = snapshot[i];
          if (pendingInputHistoryReplace) break;
          if (!Array.isArray(dumpComposeImages) || !dumpComposeImages.includes(img)) continue;
          if (img.remoteUrl || !img.dataUrl) continue;
          try {
            const m = String(img.dataUrl).match(/^data:([^;]+);base64,(.+)$/i);
            const mimeType = (m && m[1]) || img.mimeType || 'image/jpeg';
            const b64 = m ? m[2] : String(img.dataUrl || '');
            const url = await uploadDumpImagePayload(b64, mimeType, null, i + 1, snapshot.length);
            if (url && Array.isArray(dumpComposeImages) && dumpComposeImages.includes(img)) {
              img.remoteUrl = url;
              uploadedCount += 1;
            }
          } catch (_) {
            // 失敗しても次回オンライン／送信時に再送されるためサイレント維持
          }
        }
      } finally {
        liveDraftImageUploadRunning = false;
      }
      if (uploadedCount > 0 && !pendingInputHistoryReplace) {
        onLiveInputDraftChanged({ immediateCloud: true, reason: 'image_preupload' });
      }
      return uploadedCount > 0;
    }

    function clearLiveInputDraftTimers() {
      if (liveDraftCloudTimer) {
        clearTimeout(liveDraftCloudTimer);
        liveDraftCloudTimer = null;
      }
      if (liveDraftMaxWaitTimer) {
        clearTimeout(liveDraftMaxWaitTimer);
        liveDraftMaxWaitTimer = null;
      }
    }

    function scheduleLiveInputDraftCloudSync(opts) {
      opts = opts || {};
      if (liveDraftCloudTimer) {
        clearTimeout(liveDraftCloudTimer);
        liveDraftCloudTimer = null;
      }
      if (opts.immediate) {
        if (liveDraftMaxWaitTimer) {
          clearTimeout(liveDraftMaxWaitTimer);
          liveDraftMaxWaitTimer = null;
        }
        liveDraftCloudTimer = setTimeout(() => {
          liveDraftCloudTimer = null;
          void pushLiveInputDraftToCloud();
        }, 20);
        return;
      }
      liveDraftCloudTimer = setTimeout(() => {
        liveDraftCloudTimer = null;
        if (liveDraftMaxWaitTimer) {
          clearTimeout(liveDraftMaxWaitTimer);
          liveDraftMaxWaitTimer = null;
        }
        void pushLiveInputDraftToCloud();
      }, LIVE_INPUT_DRAFT_DEBOUNCE_MS);
      if (!liveDraftMaxWaitTimer) {
        liveDraftMaxWaitTimer = setTimeout(() => {
          liveDraftMaxWaitTimer = null;
          if (liveDraftCloudTimer) {
            clearTimeout(liveDraftCloudTimer);
            liveDraftCloudTimer = null;
          }
          void pushLiveInputDraftToCloud();
        }, LIVE_INPUT_DRAFT_MAX_WAIT_MS);
      }
    }

    function onLiveInputDraftChanged(opts) {
      opts = opts || {};
      if (pendingInputHistoryReplace) return false;
      const ta = document.getElementById('input-content');
      if (!ta) return false;
      const rawText = String(ta.value || '');
      if (liveDraftMatchesSubmitEcho(rawText)) return false;
      liveDraftUserTouchedBeforeRestore = true;
      liveDraftDeferredCloudApply = null;

      const { remoteUrls, compactPendingImages, localImageCount } = collectLiveComposeDraftImagesSnapshot();
      const prev = readLocalLiveInputDraft();
      const nextSig = liveDraftContentSignature(rawText, remoteUrls);
      const prevSig = prev ? liveDraftContentSignature(prev.draftText, prev.remoteUrls) : '';

      if (!prev && !rawText && !remoteUrls.length && localImageCount === 0) {
        return false;
      }
      if (!opts.force && prev && nextSig === prevSig && Number(prev.localImageCount || 0) === localImageCount) {
        if (!opts.skipCloudSchedule && opts.immediateCloud && prev.dirty) {
          scheduleLiveInputDraftCloudSync({ immediate: true });
        }
        return false;
      }

      liveDraftMutationVersion += 1;
      const updatedAtMs = nextLiveDraftTimestampMs(prev && prev.updatedAtMs);
      const next = {
        v: 1,
        draftText: rawText,
        remoteUrls,
        localImageCount,
        updatedAtMs,
        updatedAt: new Date(updatedAtMs).toISOString(),
        instanceId: getLiveInputDraftInstanceId(),
        dirty: true
      };
      writeLocalLiveInputDraft(next);
      void mirrorLiveInputDraftToCacheStorage(next, compactPendingImages);
      if (!opts.skipCloudSchedule) {
        scheduleLiveInputDraftCloudSync({ immediate: !!opts.immediateCloud });
      }
      return true;
    }

    function clearLiveInputDraft(opts) {
      opts = opts || {};
      const prev = readLocalLiveInputDraft();
      const cloudId = getCachedLiveInputDraftCloudId();
      if (!prev && !cloudId) {
        liveDraftDeferredCloudApply = null;
        return false;
      }
      if (prev && prev.draftText === '' && !(prev.remoteUrls && prev.remoteUrls.length)
        && !prev.localImageCount && !prev.dirty) {
        liveDraftDeferredCloudApply = null;
        return false;
      }
      liveDraftUserTouchedBeforeRestore = true;
      liveDraftDeferredCloudApply = null;
      liveDraftMutationVersion += 1;
      const updatedAtMs = nextLiveDraftTimestampMs(prev && prev.updatedAtMs);
      const next = {
        v: 1,
        draftText: '',
        remoteUrls: [],
        localImageCount: 0,
        updatedAtMs,
        updatedAt: new Date(updatedAtMs).toISOString(),
        instanceId: getLiveInputDraftInstanceId(),
        dirty: true
      };
      writeLocalLiveInputDraft(next);
      void mirrorLiveInputDraftToCacheStorage(next, []);
      if (!opts.skipCloudSchedule) {
        scheduleLiveInputDraftCloudSync({ immediate: opts.immediateCloud !== false });
      }
      return true;
    }

    async function ensureLiveInputDraftStore() {
      if (liveDraftStoreReady) return;
      await callAPI('addConfigRecord', {
        folder: LIVE_INPUT_DRAFT_CLOUD_FOLDER,
        file: LIVE_INPUT_DRAFT_CLOUD_FILE
      }, { silent: true });
      liveDraftStoreReady = true;
    }

    function parseLiveInputDraftSnapshot(row) {
      if (!row || row.content == null) return null;
      try {
        const p = JSON.parse(row.content);
        if (!p || typeof p !== 'object') return null;
        let updatedAtMs = Number(p.updatedAtMs);
        if (!Number.isFinite(updatedAtMs) && p.updatedAt) {
          updatedAtMs = new Date(p.updatedAt).getTime();
        }
        if (!Number.isFinite(updatedAtMs)) updatedAtMs = 0;
        return {
          cloudId: row.id != null ? String(row.id) : '',
          draftText: p.draftText != null ? String(p.draftText) : '',
          remoteUrls: normalizeLiveDraftRemoteUrls(p.remoteUrls),
          updatedAtMs,
          updatedAt: p.updatedAt ? String(p.updatedAt) : new Date(updatedAtMs || Date.now()).toISOString(),
          instanceId: p.instanceId ? String(p.instanceId) : ''
        };
      } catch (_) {
        return null;
      }
    }

    function retireExtraLiveInputDraftRecords(extraIds) {
      const ids = (Array.isArray(extraIds) ? extraIds : [])
        .map((id) => String(id || ''))
        .filter(Boolean);
      if (!ids.length) return;
      // ゴミ箱肥大化を避けるため、__SYSTEM__ 内の別ファイルへ退避して無効化
      callAPI('moveDataRecords', {
        items: ids.map((id) => ({
          id,
          folder: LIVE_INPUT_DRAFT_CLOUD_FOLDER,
          file: LIVE_INPUT_DRAFT_SUPERSEDED_FILE
        }))
      }, { silent: true }).catch(() => { });
    }

    async function fetchCloudLiveInputDraftSnapshot() {
      const items = await callAPI('getFolderFileItems', {
        folder: LIVE_INPUT_DRAFT_CLOUD_FOLDER,
        file: LIVE_INPUT_DRAFT_CLOUD_FILE
      }, { silent: true });
      if (!Array.isArray(items) || !items.length) return null;
      const parsed = items
        .map(parseLiveInputDraftSnapshot)
        .filter(Boolean)
        .sort((a, b) => b.updatedAtMs - a.updatedAtMs);
      if (!parsed.length) return null;
      const primary = parsed[0];
      const extraIds = parsed.slice(1).map((x) => x.cloudId).filter((id) => id && id !== primary.cloudId);
      if (primary.cloudId) cacheLiveInputDraftCloudId(primary.cloudId);
      liveDraftStoreReady = true;
      liveDraftLastSeenCloudMs = Math.max(liveDraftLastSeenCloudMs, Number(primary.updatedAtMs) || 0);
      if (extraIds.length) retireExtraLiveInputDraftRecords(extraIds);
      return { ...primary, extraIds };
    }

    function mergeConflictingLiveDrafts(local, cloud) {
      const myInstanceId = getLiveInputDraftInstanceId();
      const cloudText = String((cloud && cloud.draftText) || '');
      const localText = String((local && local.draftText) || '');
      const cloudUrls = normalizeLiveDraftRemoteUrls(cloud && cloud.remoteUrls);
      const localUrls = normalizeLiveDraftRemoteUrls(local && local.remoteUrls);
      const mergedUrls = normalizeLiveDraftRemoteUrls(cloudUrls.concat(localUrls));
      let mergedText = localText;
      const ct = cloudText.trim();
      const lt = localText.trim();
      if (ct && lt && ct !== lt) {
        if (lt.includes(ct)) mergedText = localText;
        else if (ct.includes(lt)) mergedText = cloudText;
        else mergedText = cloudText + '\n\n' + localText;
      } else if (ct && !lt) {
        mergedText = cloudText;
      }
      const updatedAtMs = nextLiveDraftTimestampMs(Math.max(Number(local && local.updatedAtMs) || 0, Number(cloud && cloud.updatedAtMs) || 0));
      return {
        v: 1,
        draftText: mergedText,
        remoteUrls: mergedUrls,
        localImageCount: Math.max(0, Number(local && local.localImageCount) || 0),
        updatedAtMs,
        updatedAt: new Date(updatedAtMs).toISOString(),
        instanceId: myInstanceId,
        dirty: true
      };
    }

    function markLocalLiveInputDraftCleanIfUnchanged(targetUpdatedAtMs, targetSig) {
      const cur = readLocalLiveInputDraft();
      if (!cur) return;
      const curSig = liveDraftContentSignature(cur.draftText, cur.remoteUrls);
      if (cur.updatedAtMs === targetUpdatedAtMs && curSig === targetSig && cur.dirty) {
        cur.dirty = false;
        writeLocalLiveInputDraft(cur);
        void mirrorLiveInputDraftToCacheStorage(cur);
      }
    }

    async function pushLiveInputDraftToCloud() {
      if (typeof navigator !== 'undefined' && navigator.onLine === false) return false;
      if (liveDraftCloudPushing) {
        liveDraftCloudPushQueued = true;
        return false;
      }
      liveDraftCloudPushing = true;
      try {
        const localSnapshot = readLocalLiveInputDraft();
        if (!localSnapshot || !localSnapshot.dirty) return true;
        const startVersion = liveDraftMutationVersion;
        let toWrite = localSnapshot;
        await ensureLiveInputDraftStore();

        let cloudId = getCachedLiveInputDraftCloudId();
        if (!cloudId) {
          const cloud = await fetchCloudLiveInputDraftSnapshot();
          if (cloud && cloud.cloudId) {
            cloudId = cloud.cloudId;
            const myId = getLiveInputDraftInstanceId();
            const cloudSig = liveDraftContentSignature(cloud.draftText, cloud.remoteUrls);
            const localSig = liveDraftContentSignature(localSnapshot.draftText, localSnapshot.remoteUrls);
            if (cloud.updatedAtMs > localSnapshot.updatedAtMs
              && cloud.instanceId !== myId
              && cloudSig !== localSig
              && String(cloud.draftText || '').trim()
              && String(localSnapshot.draftText || '').trim()) {
              toWrite = mergeConflictingLiveDrafts(localSnapshot, cloud);
              if (liveDraftMutationVersion === startVersion) {
                writeLocalLiveInputDraft(toWrite);
                void mirrorLiveInputDraftToCacheStorage(toWrite);
                applyLiveInputDraftToUi(toWrite);
              }
            }
          }
        }

        const content = buildLiveDraftCloudPayload(toWrite);
        if (cloudId) {
          const upd = await callAPI('updateDataRecord', {
            id: cloudId,
            folder: LIVE_INPUT_DRAFT_CLOUD_FOLDER,
            file: LIVE_INPUT_DRAFT_CLOUD_FILE,
            content
          }, { silent: true });
          if (upd && upd.success && !upd.error) {
            const sig = liveDraftContentSignature(toWrite.draftText, toWrite.remoteUrls);
            markLocalLiveInputDraftCleanIfUnchanged(toWrite.updatedAtMs, sig);
            return true;
          }
          if (!upd || upd.error !== 'not_found') {
            return false;
          }
          cacheLiveInputDraftCloudId('');
          cloudId = '';
        }

        const hasBody = !!(String(toWrite.draftText || '').trim() || (toWrite.remoteUrls && toWrite.remoteUrls.length));
        if (!hasBody) {
          const sig = liveDraftContentSignature(toWrite.draftText, toWrite.remoteUrls);
          markLocalLiveInputDraftCleanIfUnchanged(toWrite.updatedAtMs, sig);
          return true;
        }
        const addRes = await callAPI('addDataRecord', {
          folder: LIVE_INPUT_DRAFT_CLOUD_FOLDER,
          file: LIVE_INPUT_DRAFT_CLOUD_FILE,
          content
        }, { silent: true });
        if (addRes && addRes.success && addRes.id) {
          cacheLiveInputDraftCloudId(String(addRes.id));
          const sig = liveDraftContentSignature(toWrite.draftText, toWrite.remoteUrls);
          markLocalLiveInputDraftCleanIfUnchanged(toWrite.updatedAtMs, sig);
          return true;
        }
        return false;
      } catch (e) {
        console.warn('pushLiveInputDraftToCloud failed', e);
        return false;
      } finally {
        liveDraftCloudPushing = false;
        if (liveDraftCloudPushQueued) {
          liveDraftCloudPushQueued = false;
          const latest = readLocalLiveInputDraft();
          if (latest && latest.dirty) {
            scheduleLiveInputDraftCloudSync({ immediate: true });
          }
        }
      }
    }

    async function syncLiveInputDraftWithCloud(options) {
      options = options || {};
      if (typeof navigator !== 'undefined' && navigator.onLine === false) return false;
      if (liveDraftCloudSyncing) {
        liveDraftCloudSyncQueued = true;
        return false;
      }
      liveDraftCloudSyncing = true;
      try {
        const startVersion = liveDraftMutationVersion;
        const cloud = await fetchCloudLiveInputDraftSnapshot();
        if (liveDraftMutationVersion !== startVersion) {
          const cur = readLocalLiveInputDraft();
          if (cur && cur.dirty) scheduleLiveInputDraftCloudSync({ immediate: true });
          return false;
        }

        const local = readLocalLiveInputDraft();
        if (!cloud) {
          if (local && (local.dirty || local.draftText || (local.remoteUrls && local.remoteUrls.length))) {
            if (!local.dirty) {
              local.dirty = true;
              writeLocalLiveInputDraft(local);
            }
            await pushLiveInputDraftToCloud();
          }
          return true;
        }

        const myId = getLiveInputDraftInstanceId();
        const cloudSig = liveDraftContentSignature(cloud.draftText, cloud.remoteUrls);
        const localSig = local ? liveDraftContentSignature(local.draftText, local.remoteUrls) : '';

        if (local && local.updatedAtMs === cloud.updatedAtMs && localSig === cloudSig) {
          if (local.dirty) {
            local.dirty = false;
            writeLocalLiveInputDraft(local);
            void mirrorLiveInputDraftToCacheStorage(local);
          }
          return true;
        }

        const shouldPullCloud = !local || (!local.dirty && (
          cloud.updatedAtMs > local.updatedAtMs
          || (cloud.updatedAtMs === local.updatedAtMs && cloudSig !== localSig)
        ));

        if (shouldPullCloud) {
          if (liveDraftMatchesSubmitEcho(cloud.draftText)) {
            return true;
          }
          const appliedRecord = {
            v: 1,
            draftText: String(cloud.draftText || ''),
            remoteUrls: normalizeLiveDraftRemoteUrls(cloud.remoteUrls),
            localImageCount: 0,
            updatedAtMs: cloud.updatedAtMs,
            updatedAt: cloud.updatedAt,
            instanceId: cloud.instanceId || myId,
            dirty: false
          };
          const ta = document.getElementById('input-content');
          const curUiText = ta ? String(ta.value || '') : '';
          const curUiUrls = (typeof dumpComposeImages !== 'undefined' && Array.isArray(dumpComposeImages))
            ? dumpComposeImages.map((x) => (x && x.remoteUrl) || '').filter(Boolean)
            : [];
          const uiSig = liveDraftContentSignature(curUiText, curUiUrls);
          if (pendingInputHistoryReplace || inputContentComposing) {
            liveDraftDeferredCloudApply = appliedRecord;
            return true;
          }
          writeLocalLiveInputDraft(appliedRecord);
          void mirrorLiveInputDraftToCacheStorage(appliedRecord);
          if (uiSig !== cloudSig || !local) {
            applyLiveInputDraftToUi(appliedRecord, { allowClearImages: true });
          }
          return true;
        }

        if (local && local.dirty) {
          const remoteNewerFromOther = cloud.updatedAtMs > local.updatedAtMs
            && cloud.instanceId !== myId
            && cloudSig !== localSig;
          if (remoteNewerFromOther) {
            const ct = String(cloud.draftText || '').trim();
            const lt = String(local.draftText || '').trim();
            if (ct && lt && !liveDraftMatchesSubmitEcho(cloud.draftText)) {
              const merged = mergeConflictingLiveDrafts(local, cloud);
              if (!pendingInputHistoryReplace && !inputContentComposing) {
                writeLocalLiveInputDraft(merged);
                void mirrorLiveInputDraftToCacheStorage(merged);
                applyLiveInputDraftToUi(merged);
              }
              await pushLiveInputDraftToCloud();
              return true;
            }
            if (!lt && !(local.remoteUrls && local.remoteUrls.length) && !local.localImageCount
              && (ct || (cloud.remoteUrls && cloud.remoteUrls.length))
              && !liveDraftMatchesSubmitEcho(cloud.draftText)) {
              const nextFromCloud = {
                v: 1,
                draftText: String(cloud.draftText || ''),
                remoteUrls: normalizeLiveDraftRemoteUrls(cloud.remoteUrls),
                localImageCount: 0,
                updatedAtMs: cloud.updatedAtMs,
                updatedAt: cloud.updatedAt,
                instanceId: cloud.instanceId || myId,
                dirty: false
              };
              if (!pendingInputHistoryReplace && !inputContentComposing) {
                writeLocalLiveInputDraft(nextFromCloud);
                void mirrorLiveInputDraftToCacheStorage(nextFromCloud);
                applyLiveInputDraftToUi(nextFromCloud, { allowClearImages: true });
              } else {
                liveDraftDeferredCloudApply = nextFromCloud;
              }
              return true;
            }
          }
          await pushLiveInputDraftToCloud();
        }
        return true;
      } catch (e) {
        console.warn('syncLiveInputDraftWithCloud failed', e);
        return false;
      } finally {
        liveDraftCloudSyncing = false;
        if (liveDraftCloudSyncQueued) {
          liveDraftCloudSyncQueued = false;
          runInBackground(() => syncLiveInputDraftWithCloud({ reason: 'queued' }));
        }
      }
    }

    function flushLiveInputDraftOnLeave() {
      try {
        if (!pendingInputHistoryReplace) {
          onLiveInputDraftChanged({ skipCloudSchedule: true, reason: 'leave' });
        }
        const local = readLocalLiveInputDraft();
        if (!local || !local.dirty) return false;
        if (typeof navigator !== 'undefined' && navigator.onLine === false) return false;
        const sig = String(local.updatedAtMs) + '|' + liveDraftContentSignature(local.draftText, local.remoteUrls);
        if (sig === liveDraftLastKeepaliveSig && (Date.now() - liveDraftLastKeepaliveAt) < 2500) {
          return false;
        }
        const content = buildLiveDraftCloudPayload(local);
        const cloudId = getCachedLiveInputDraftCloudId();
        if (typeof dispatchKeepalivePost !== 'function') return false;
        let dispatched = false;
        if (cloudId) {
          dispatched = dispatchKeepalivePost({
            action: 'updateDataRecord',
            id: cloudId,
            folder: LIVE_INPUT_DRAFT_CLOUD_FOLDER,
            file: LIVE_INPUT_DRAFT_CLOUD_FILE,
            content
          });
        } else if (String(local.draftText || '').trim() || (local.remoteUrls && local.remoteUrls.length)) {
          dispatched = dispatchKeepalivePost({
            action: 'addDataRecord',
            folder: LIVE_INPUT_DRAFT_CLOUD_FOLDER,
            file: LIVE_INPUT_DRAFT_CLOUD_FILE,
            content
          });
        }
        if (dispatched) {
          liveDraftLastKeepaliveSig = sig;
          liveDraftLastKeepaliveAt = Date.now();
        }
        return dispatched;
      } catch (e) {
        console.warn('flushLiveInputDraftOnLeave failed', e);
        return false;
      }
    }

    window.onLiveInputDraftChanged = onLiveInputDraftChanged;
    window.clearLiveInputDraft = clearLiveInputDraft;
    window.flushLiveInputDraftOnLeave = flushLiveInputDraftOnLeave;
    window.syncLiveInputDraftWithCloud = syncLiveInputDraftWithCloud;
    window.preuploadLiveDraftComposeImages = preuploadLiveDraftComposeImages;

    function bindInputContentHistoryLock() {
      const ta = document.getElementById('input-content');
      if (!ta || ta.dataset.historyLockBound === '1') return;
      ta.dataset.historyLockBound = '1';
      restoreLiveInputDraftSync();
      if (typeof bindInputContentCompositionWatch === 'function') bindInputContentCompositionWatch();
      const handleDraftSync = (reason) => {
        syncInputTabHistoryLock();
        onLiveInputDraftChanged({ reason });
      };
      ta.addEventListener('input', () => handleDraftSync('input'));
      ta.addEventListener('change', () => handleDraftSync('change'));
      ta.addEventListener('blur', () => {
        if (!pendingInputHistoryReplace && !inputContentComposing) {
          onLiveInputDraftChanged({ immediateCloud: true, reason: 'blur' });
        }
      });
      if (typeof ensureTextUndo === 'function') ensureTextUndo(ta);
    }

    function normalizeOverlapText(s) {
      return String(s || '').toLowerCase().replace(/[\s\r\n\t　]+/g, ' ').trim();
    }

    function historyOverlapKey(entry) {
      if (!entry) return '';
      if (typeof historyEntryKey === 'function') return historyEntryKey(entry);
      return `${entry.folder || 'INBOX'}::${entry.file || '未整理'}::${entry.content || ''}`;
    }

    function describePartialContentOverlap(a, b, queryRec, candRec) {
      const ta = String(a || '').trim();
      const tb = String(b || '').trim();
      if (!ta || !tb || ta === tb) return null;
      const na = normalizeOverlapText(ta);
      const nb = normalizeOverlapText(tb);
      if (!na || !nb || na === nb) {
        if (na && nb && na === nb) return { reason: '表記ゆれの同一', score: 0.98, kind: 'near_exact' };
        return null;
      }
      if (na.length >= INPUT_TAB_OVERLAP_MIN_LEN && nb.includes(na)) {
        return { reason: '今回が過去に含まれる', score: 0.92, kind: 'new_in_old' };
      }
      if (nb.length >= INPUT_TAB_OVERLAP_MIN_LEN && na.includes(nb)) {
        return { reason: '過去が今回に含まれる', score: 0.92, kind: 'old_in_new' };
      }
      const linesA = ta.split(/\n+/).map((s) => s.trim()).filter((s) => s.length >= INPUT_TAB_OVERLAP_MIN_LEN);
      if (linesA.length) {
        const linesB = new Set(tb.split(/\n+/).map((s) => s.trim()).filter((s) => s.length >= INPUT_TAB_OVERLAP_MIN_LEN));
        const shared = linesA.filter((l) => linesB.has(l));
        if (shared.length >= 1) {
          const cover = shared.join('').length / Math.max(ta.length, 1);
          if (shared.length >= 2 || cover >= 0.18) {
            return { reason: `共通の行 ${shared.length}`, score: Math.min(0.9, 0.68 + shared.length * 0.06), kind: 'lines' };
          }
        }
      }
      if (typeof scoreIndexedSimilarity === 'function') {
        const query = queryRec || (typeof makeSimilarityRecordFromText === 'function' ? makeSimilarityRecordFromText(ta) : null);
        const cand = candRec || (typeof makeSimilarityRecordFromText === 'function' ? makeSimilarityRecordFromText(tb) : null);
        if (query && cand) {
          const score = scoreIndexedSimilarity(query, cand);
          if (score >= INPUT_TAB_DUP_MIN_SCORE) {
            return { reason: `類似 ${Math.round(score * 100)}%`, score, kind: 'similar' };
          }
        }
      }
      return null;
    }

    function getInputTabOverlapPairs() {
      try {
        const raw = JSON.parse(localStorage.getItem(INPUT_TAB_OVERLAP_KEY) || '[]');
        return Array.isArray(raw) ? raw.filter((p) => p && p.newKey && p.oldKey) : [];
      } catch (e) {
        return [];
      }
    }

    function storedOverlapKey(item) {
      if (!item) return '';
      if (item.id != null && typeof isTempId === 'function' && !isTempId(item.id)) {
        return `stored::id::${item.id}`;
      }
      const folder = item.isInbox || item.folder === '📥 INBOX' || item.folder === 'INBOX'
        ? 'INBOX'
        : (item.folder || '');
      const contentKey = typeof dumpContentKey === 'function' ? dumpContentKey(item.content) : String(item.content || '');
      return `stored::${folder}::${item.file || '未整理'}::${contentKey}`;
    }

    function saveInputTabOverlapPairs(pairs) {
      const seen = new Set();
      const cleaned = [];
      (pairs || []).forEach((p) => {
        if (!p || !p.newKey) return;
        const isStored = p.source === 'stored' || !!p.storedSnap;
        if (!isStored && (!p.oldKey || p.newKey === p.oldKey)) return;
        if (isStored && !p.storedSnap && !p.oldKey) return;
        const oldPart = isStored ? (p.oldKey || storedOverlapKey(p.storedSnap)) : p.oldKey;
        const k = `${p.newKey}::${oldPart}`;
        if (seen.has(k)) return;
        seen.add(k);
        cleaned.push({
          newKey: String(p.newKey),
          oldKey: oldPart ? String(oldPart) : '',
          storedId: p.storedId ? String(p.storedId) : '',
          storedSnap: p.storedSnap && p.storedSnap.content ? {
            id: p.storedSnap.id,
            content: p.storedSnap.content,
            folder: p.storedSnap.folder,
            file: p.storedSnap.file,
            isInbox: !!p.storedSnap.isInbox
          } : null,
          source: isStored ? 'stored' : 'history',
          reason: p.reason || (isStored ? '保存済みと類似' : '一部重複'),
          score: Number(p.score) || 0,
          kind: p.kind || '',
          at: p.at || Date.now()
        });
      });
      localStorage.setItem(INPUT_TAB_OVERLAP_KEY, JSON.stringify(cleaned.slice(0, INPUT_TAB_OVERLAP_MAX)));
      return cleaned.slice(0, INPUT_TAB_OVERLAP_MAX);
    }

    function registerInputTabStoredOverlaps(newEntries, pairs, hitCountRef) {
      const added = (newEntries || []).filter((e) => e && e.content);
      if (!added.length || typeof getOrBuildSimilarityBundle !== 'function') return 0;
      const storedItems = typeof mergePendingDumpsInto === 'function'
        ? mergePendingDumpsInto(storedItemsCache.items || [])
        : (storedItemsCache.items || []);
      if (!storedItems.length) return 0;
      const bundle = getOrBuildSimilarityBundle(storedItems);
      let storedHits = 0;
      added.forEach((neu) => {
        const newKey = historyOverlapKey(neu);
        const query = typeof makeSimilarityRecordFromText === 'function' ? makeSimilarityRecordFromText(neu.content) : null;
        let perNew = 0;
        const similar = typeof findSimilarItemsForContent === 'function'
          ? findSimilarItemsForContent(neu, bundle, 8, INPUT_TAB_DUP_MIN_SCORE)
          : [];
        for (let i = 0; i < similar.length && perNew < 3; i++) {
          const match = similar[i];
          if (!match || !match.content) continue;
          if (typeof dumpContentEquals === 'function' && dumpContentEquals(neu.content, match.content)) continue;
          const matchKey = typeof dumpContentKey === 'function' ? dumpContentKey(match.content) : '';
          if (matchKey && typeof inputHistorySuppressedContents !== 'undefined'
            && inputHistorySuppressedContents.has(matchKey)) continue;
          if (match._pending && typeof dumpContentKey === 'function'
            && added.some((e) => dumpContentKey(e.content) === dumpContentKey(match.content))) continue;
          const oldKey = storedOverlapKey(match);
          if (pairs.some((p) => p.newKey === newKey && p.oldKey === oldKey)) continue;
          const hit = describePartialContentOverlap(neu.content, match.content, query,
            typeof makeSimilarityRecordFromText === 'function' ? makeSimilarityRecordFromText(match.content) : null);
          const reason = hit ? hit.reason : `類似 ${Math.round((match.matchScore || 0) * 100)}%`;
          const score = hit ? hit.score : (match.matchScore || INPUT_TAB_DUP_MIN_SCORE);
          pairs.unshift({
            newKey,
            oldKey,
            storedId: match.id != null ? String(match.id) : '',
            storedSnap: {
              id: match.id,
              content: match.content,
              folder: match.folder,
              file: match.file,
              isInbox: !!(match.isInbox || (typeof isSearchInboxItem === 'function' && isSearchInboxItem(match)))
            },
            source: 'stored',
            reason,
            score,
            kind: hit ? hit.kind : 'stored_similar',
            at: Date.now()
          });
          perNew += 1;
          storedHits += 1;
        }
      });
      return storedHits;
    }

    let inputTabStoredOverlapRefreshToken = 0;

    function scheduleInputTabStoredOverlapRefresh(newEntries) {
      const added = (newEntries || []).filter((e) => e && e.content);
      if (!added.length || typeof collectAllStoredItems !== 'function') return;
      const token = ++inputTabStoredOverlapRefreshToken;
      runInBackground(async () => {
        try {
          const items = await collectAllStoredItems(true);
          if (token !== inputTabStoredOverlapRefreshToken) return;
          const pairs = getInputTabOverlapPairs();
          const before = pairs.length;
          registerInputTabStoredOverlaps(added, pairs, 0);
          if (pairs.length === before) return;
          saveInputTabOverlapPairs(pairs);
          paintInputTabHistory(typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : []);
        } catch (e) {
          console.warn('input tab stored overlap refresh', e);
        }
      });
    }

    function scheduleInputTabPartialOverlaps(newEntries) {
      const added = (newEntries || []).filter((e) => e && e.content);
      if (!added.length || typeof registerInputTabPartialOverlaps !== 'function') return;
      setTimeout(() => {
        runInBackground(() => { registerInputTabPartialOverlaps(added); });
      }, 800);
    }

    function registerInputTabPartialOverlaps(newEntries) {
      const added = (newEntries || []).filter((e) => e && e.content);
      if (!added.length) return 0;
      const history = typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : [];
      const addedKeys = new Set(added.map(historyOverlapKey));
      const pairs = getInputTabOverlapPairs();
      const oldRecords = [];
      history.forEach((old) => {
        if (!old || !old.content) return;
        const oldKey = historyOverlapKey(old);
        if (!oldKey || addedKeys.has(oldKey)) return;
        oldRecords.push({
          old,
          oldKey,
          rec: typeof makeSimilarityRecordFromText === 'function' ? makeSimilarityRecordFromText(old.content) : null
        });
      });
      let hitCount = 0;
      added.forEach((neu) => {
        const newKey = historyOverlapKey(neu);
        const query = typeof makeSimilarityRecordFromText === 'function' ? makeSimilarityRecordFromText(neu.content) : null;
        let perNew = 0;
        for (let i = 0; i < oldRecords.length && perNew < 3; i++) {
          const row = oldRecords[i];
          if (!row.oldKey || row.oldKey === newKey) continue;
          const hit = describePartialContentOverlap(neu.content, row.old.content, query, row.rec);
          if (!hit) continue;
          pairs.unshift({
            newKey,
            oldKey: row.oldKey,
            reason: hit.reason,
            score: hit.score,
            kind: hit.kind,
            at: Date.now()
          });
          perNew += 1;
          hitCount += 1;
        }
      });
      hitCount += registerInputTabStoredOverlaps(added, pairs, hitCount);
      saveInputTabOverlapPairs(pairs);
      const cacheEmpty = !(storedItemsCache.items && storedItemsCache.items.length);
      if (cacheEmpty || !(Date.now() - (storedItemsCache.fetchedAt || 0) < STORED_ITEMS_CACHE_MS)) {
        scheduleInputTabStoredOverlapRefresh(added);
      }
      return hitCount;
    }

    function overlapPairKey(pair) {
      if (!pair) return '';
      return `${pair.newKey || ''}::${pair.oldKey || ''}::${pair.storedId || ''}`;
    }

    function dismissInputTabOverlapPair(newKey, oldKey, event) {
      if (event) event.stopPropagation();
      saveInputTabOverlapPairs(getInputTabOverlapPairs().filter((p) => !(p.newKey === newKey && p.oldKey === oldKey)));
      paintInputTabHistory(typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : []);
    }

    function pruneInputTabOverlapPairs(entries) {
      const keys = new Set((entries || []).map(historyOverlapKey));
      const next = getInputTabOverlapPairs().filter((p) => {
        if (!keys.has(p.newKey)) return false;
        if (p.source === 'stored' || p.storedSnap) return true;
        return keys.has(p.oldKey);
      });
      if (next.length !== getInputTabOverlapPairs().length) saveInputTabOverlapPairs(next);
      return next;
    }

    function findHistoryEntryByKey(entries, key) {
      return (entries || []).find((e) => historyOverlapKey(e) === key) || null;
    }

    /** 登録チェック操作ボタン: キーボード表示中でも1タップで反応させる */
    function bindInputHistoryActionButton(btn, handler) {
      if (!btn || typeof handler !== 'function') return;
      let activePointer = null;
      let startX = 0;
      let startY = 0;
      const clearPressed = () => {
        activePointer = null;
        btn.classList.remove('is-pressed');
      };
      btn.addEventListener('pointerdown', (e) => {
        if (e.pointerType === 'mouse' && e.button !== 0) return;
        // preventDefault で入力欄フォーカス維持 → キーボード閉じ・レイアウトずれでクリックが空振りするのを防ぐ
        e.preventDefault();
        e.stopPropagation();
        activePointer = e.pointerId;
        startX = e.clientX;
        startY = e.clientY;
        btn.classList.add('is-pressed');
        // 写真の読み込みでボタンが動いても pointerup を受け取れるようにする
        try { btn.setPointerCapture(e.pointerId); } catch (_) { }
      });
      btn.addEventListener('pointerup', (e) => {
        if (activePointer == null || e.pointerId !== activePointer) return;
        const moved = Math.hypot(e.clientX - startX, e.clientY - startY) > 14;
        clearPressed();
        e.preventDefault();
        e.stopPropagation();
        try { btn.releasePointerCapture(e.pointerId); } catch (_) { }
        if (moved) return;
        try { handler(e); } catch (err) { console.warn('history action failed', err); }
      });
      btn.addEventListener('pointercancel', (e) => {
        clearPressed();
        try { btn.releasePointerCapture(e.pointerId); } catch (_) { }
      });
      // 二重発火防止。キーボード非表示時のフォールバックは pointerup で足りる
      btn.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
      });
    }

    function createInputTabDupCountButton(entry, matches) {
      const list = Array.isArray(matches) ? matches : [];
      const dupBtn = document.createElement('button');
      dupBtn.type = 'button';
      dupBtn.className = 'input-tab-history-dup-btn';
      dupBtn.setAttribute('data-dup-count-btn', '1');
      dupBtn.textContent = String(list.length);
      dupBtn.title = `重複 ${list.length}件（一致率30%以上）`;
      dupBtn.setAttribute('aria-label', `重複 ${list.length}件を表示`);
      bindInputHistoryActionButton(dupBtn, () => {
        const key = typeof historyOverlapKey === 'function' ? historyOverlapKey(entry) : '';
        const latest = (key && inputTabDupMap[key]) || list;
        openInputDupModal(entry, latest);
      });
      return dupBtn;
    }

    /** 重複バッジだけ差し替え（一覧の全再描画でボタンがちらつくのを防ぐ） */
    function syncInputTabDupBadgesInDom() {
      const list = document.getElementById('input-tab-history-list');
      if (!list) return;
      const localByKey = new Map();
      (typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : []).forEach((e) => {
        if (!e) return;
        const k = typeof historyOverlapKey === 'function' ? historyOverlapKey(e) : '';
        if (k) localByKey.set(k, e);
      });
      list.querySelectorAll('[data-history-card="1"][data-history-key]').forEach((card) => {
        if (card.getAttribute('data-stored-match') === '1') return;
        const key = card.getAttribute('data-history-key') || '';
        const actions = card.querySelector('.input-tab-history-actions');
        if (!actions) return;
        const matches = (key && inputTabDupMap[key]) || [];
        let dupBtn = actions.querySelector('[data-dup-count-btn]');
        if (!matches.length) {
          if (dupBtn) dupBtn.remove();
          return;
        }
        const count = String(matches.length);
        if (dupBtn) {
          if (dupBtn.textContent !== count) {
            dupBtn.textContent = count;
            dupBtn.title = `重複 ${count}件（一致率30%以上）`;
            dupBtn.setAttribute('aria-label', `重複 ${count}件を表示`);
          }
          return;
        }
        const entry = localByKey.get(key) || {
          id: card.getAttribute('data-history-id') || undefined,
          content: (card.querySelector('.whitespace-pre-wrap') || {}).textContent || '',
          folder: card.getAttribute('data-history-folder') || 'INBOX',
          file: card.getAttribute('data-history-file') || '未整理',
          timestamp: card.getAttribute('data-history-ts') || ''
        };
        dupBtn = createInputTabDupCountButton(entry, matches);
        const copyBtn = actions.querySelector('[aria-label="コピー"]');
        if (copyBtn) actions.insertBefore(dupBtn, copyBtn);
        else actions.insertBefore(dupBtn, actions.firstChild);
      });
    }

    function createInputTabHistoryCard(entry, opts) {
      opts = opts || {};
      const item = document.createElement('div');
      item.setAttribute('data-history-card', '1');
      const editing = pendingInputHistoryReplace && sameInputHistoryId(pendingInputHistoryReplace.id, entry.id);
      const tone = opts.tone || (editing ? 'edit' : 'normal');
      const lane = typeof historyEntryLane === 'function' ? historyEntryLane(entry) : 'inbox';
      const laneClass = lane === 'todo' ? 'is-lane-todo' : (lane === 'log' ? 'is-lane-log' : 'is-lane-inbox');
      if (tone === 'new') {
        item.className = 'ith-tone-new bg-emerald-950/30 border-2 border-emerald-500/50 rounded-2xl p-2.5 text-base text-cyan-100 font-mono flex flex-col gap-1.5 shadow-[inset_0_0_15px_rgba(0,0,0,0.5)] cursor-pointer min-w-0 ' + laneClass;
      } else if (tone === 'old') {
        item.className = 'ith-tone-old bg-amber-950/25 border-2 border-amber-500/50 rounded-2xl p-2.5 text-base text-cyan-100 font-mono flex flex-col gap-1.5 shadow-[inset_0_0_15px_rgba(0,0,0,0.5)] cursor-pointer min-w-0 ' + laneClass;
      } else if (editing) {
        item.className = 'ith-tone-edit border-2 rounded-2xl p-2.5 text-base text-cyan-100 font-mono flex flex-col gap-1.5 cursor-pointer ' + laneClass + ' is-history-editing';
        item.dataset.editing = '1';
      } else {
        item.className = 'ith-tone-normal border-2 rounded-2xl p-2.5 text-base text-cyan-100 font-mono flex flex-col gap-1.5 shadow-[inset_0_0_15px_rgba(0,0,0,0.5)] cursor-pointer ' + laneClass;
      }
      // カード全体の title はボタン上でツールチップが競合して押しにくくなるため付けない
      item.removeAttribute('title');
      item.onclick = () => {
        loadInputHistoryIntoQuickInput(entry);
      };

      const entryKey = typeof historyOverlapKey === 'function' ? historyOverlapKey(entry) : '';
      const dupMatches = (entryKey && inputTabDupMap[entryKey]) || [];
      const hasDups = Array.isArray(dupMatches) && dupMatches.length > 0;
      if (entryKey) item.setAttribute('data-history-key', entryKey);
      if (entry && entry.id != null) item.setAttribute('data-history-id', String(entry.id));
      if (entry && entry.folder) item.setAttribute('data-history-folder', String(entry.folder));
      if (entry && entry.file) item.setAttribute('data-history-file', String(entry.file));
      if (entry && entry.timestamp) item.setAttribute('data-history-ts', String(entry.timestamp));

      const toolbar = document.createElement('div');
      toolbar.className = 'input-tab-history-toolbar flex items-center justify-between gap-2 min-w-0';
      // ツールバー操作がカード全体タップ（読み込み）と衝突しないようにする
      toolbar.addEventListener('click', (e) => e.stopPropagation());
      toolbar.addEventListener('pointerdown', (e) => e.stopPropagation());
      const toolbarLeft = document.createElement('div');
      toolbarLeft.className = 'flex items-center gap-1.5 min-w-0 flex-1 overflow-hidden';

      if (opts.badge) {
        const badge = document.createElement('span');
        badge.className = tone === 'new'
          ? 'shrink-0 text-[10px] font-extrabold text-emerald-200 bg-emerald-950/60 px-1.5 py-0.5 rounded border border-emerald-700/50'
          : 'shrink-0 text-[10px] font-extrabold text-amber-200 bg-amber-950/60 px-1.5 py-0.5 rounded border border-amber-700/50';
        badge.textContent = opts.badge;
        toolbarLeft.appendChild(badge);
      }
      if (editing) {
        const editTag = document.createElement('span');
        editTag.className = 'shrink-0 text-[10px] text-amber-300 font-extrabold bg-amber-950/50 px-1.5 py-0.5 rounded border border-amber-600/40';
        editTag.textContent = '編集中';
        toolbarLeft.appendChild(editTag);
      }
      const laneBadge = document.createElement('span');
      laneBadge.className = 'ith-lane-badge ' + laneClass;
      laneBadge.textContent = inputHistoryLaneShortLabel(lane) || 'INBOX';
      toolbarLeft.appendChild(laneBadge);
      const time = document.createElement('span');
      time.className = 'shrink-0 text-xs sm:text-[13px] text-cyan-400/90 font-bold tabular-nums tracking-wide';
      time.textContent = typeof formatInputHistoryTime === 'function'
        ? formatInputHistoryTime(entry.timestamp)
        : (entry.timestamp || '');
      toolbarLeft.appendChild(time);
      toolbar.appendChild(toolbarLeft);

      const rawContent = String((entry && entry.content) || '');
      const hasImages = (typeof listDumpImageUrls === 'function' ? listDumpImageUrls(rawContent).length > 0 : false)
        || /📷\s*https:\/\/drive\.google\.com\//.test(rawContent)
        || /📷‹dimg-/.test(rawContent);
      if (hasImages) item.classList.add('has-image');
      const plainText = typeof stripDumpImageTokens === 'function'
        ? stripDumpImageTokens(rawContent)
        : rawContent;
      const hasText = !!String(plainText || '').trim();

      const toolbarRight = document.createElement('div');
      toolbarRight.className = 'input-tab-history-actions';
      if (hasDups) {
        toolbarRight.appendChild(createInputTabDupCountButton(entry, dupMatches));
      }
      const favBtn = document.createElement('button');
      favBtn.type = 'button';
      favBtn.className = 'input-tab-history-icon-btn bg-amber-950/50 text-amber-200 border border-amber-700/60';
      favBtn.dataset.favLabelOn = '★';
      favBtn.dataset.favLabelOff = '☆';
      favBtn.setAttribute('aria-label', 'お気に入り');
      const favorited = opts.favLookup
        ? isHistoryEntryFavoritedWithLookup(entry, opts.favLookup)
        : (typeof isHistoryEntryFavorited === 'function' && isHistoryEntryFavorited(entry));
      styleFavoriteButton(favBtn, !!favorited);
      bindInputHistoryActionButton(favBtn, () => {
        toggleFavoriteFromInputHistory(entry, favBtn);
      });

      const copyBtn = document.createElement('button');
      copyBtn.type = 'button';
      copyBtn.className = 'input-tab-history-icon-btn bg-slate-800/80 text-slate-100 border border-slate-500/70';
      copyBtn.textContent = '📋';
      copyBtn.title = 'コピー';
      copyBtn.setAttribute('aria-label', 'コピー');
      bindInputHistoryActionButton(copyBtn, () => {
        copyTextToClipboard(entry.content || '', copyBtn);
      });

      const deleteBtn = document.createElement('button');
      deleteBtn.type = 'button';
      deleteBtn.className = 'input-tab-history-icon-btn bg-rose-950/60 text-rose-200 border border-rose-700/60';
      deleteBtn.textContent = '🗑️';
      deleteBtn.title = '削除';
      deleteBtn.setAttribute('aria-label', '削除');
      bindInputHistoryActionButton(deleteBtn, () => {
        deleteInputTabHistoryEntry(entry, { fromOverlap: !!opts.fromOverlap });
      });
      toolbarRight.appendChild(favBtn);
      toolbarRight.appendChild(copyBtn);
      toolbarRight.appendChild(deleteBtn);
      toolbar.appendChild(toolbarRight);

      const preview = document.createElement('div');
      preview.className = hasImages
        ? 'ith-preview whitespace-pre-wrap text-sm leading-relaxed bg-[#02040a]/60 p-2.5 border border-cyan-900/50 rounded-xl'
        : 'ith-preview whitespace-pre-wrap line-clamp-8 text-sm leading-relaxed bg-[#02040a]/60 p-2.5 border border-cyan-900/50 rounded-xl';
      preview.title = editing ? '編集中（タップで再読込）' : 'タップで入力欄へ';

      if (hasImages && hasText) {
        const textWrap = document.createElement('div');
        textWrap.className = 'dump-content-text-wrap';

        const textBody = document.createElement('div');
        textBody.className = 'dump-content-text-body';
        textBody.textContent = plainText;
        textWrap.appendChild(textBody);

        const textCopyBtn = document.createElement('button');
        textCopyBtn.type = 'button';
        textCopyBtn.className = 'dump-content-text-copy-btn input-tab-history-icon-btn';
        textCopyBtn.textContent = '📋';
        textCopyBtn.title = '文字をコピー';
        textCopyBtn.setAttribute('aria-label', '文字をコピー');
        bindInputHistoryActionButton(textCopyBtn, async () => {
          try {
            const ok = typeof copyPlainTextRobust === 'function'
              ? await copyPlainTextRobust(plainText)
              : false;
            flashCopyButton(textCopyBtn, !!ok);
          } catch (_) {
            flashCopyButton(textCopyBtn, false);
          }
        });
        textWrap.appendChild(textCopyBtn);
        preview.appendChild(textWrap);

        const imgArea = document.createElement('div');
        const imageUrls = typeof listDumpImageUrls === 'function' ? listDumpImageUrls(rawContent) : [];
        const placeholders = (typeof listDumpImagePlaceholders === 'function' ? listDumpImagePlaceholders(rawContent) : [])
          .map((id) => '📷‹' + id + '›');
        const allTokens = [...imageUrls.map((u) => '📷 ' + u), ...placeholders];
        const imageTokens = allTokens.length > 0
          ? allTokens.join('\n')
          : (rawContent.match(/📷\s*(?:https:\/\/drive\.google\.com\/[^\s]+|‹dimg-[^›]+›)/g) || []).join('\n');
        if (typeof setDumpContentDisplay === 'function') {
          setDumpContentDisplay(imgArea, imageTokens);
        }
        while (imgArea.firstChild) {
          preview.appendChild(imgArea.firstChild);
        }
      } else {
        if (typeof setDumpContentDisplay === 'function') setDumpContentDisplay(preview, entry.content || '');
        else preview.textContent = entry.content || '';
      }

      item.appendChild(toolbar);
      item.appendChild(preview);
      return item;
    }

    function createInputTabStoredMatchCard(stored, opts) {
      opts = opts || {};
      const item = document.createElement('div');
      item.setAttribute('data-history-card', '1');
      item.setAttribute('data-stored-match', '1');
      item.className = 'ith-tone-old bg-amber-950/25 border-2 border-amber-500/50 rounded-2xl p-2.5 text-base text-cyan-100 font-mono flex flex-col gap-1.5 shadow-[inset_0_0_15px_rgba(0,0,0,0.5)] cursor-pointer transition min-w-0';
      item.title = '重複情報（開くときは📂）';
      item.onclick = (e) => {
        e.stopPropagation();
      };

      const toolbar = document.createElement('div');
      toolbar.className = 'input-tab-history-toolbar flex items-center justify-between gap-2 min-w-0';
      toolbar.addEventListener('click', (e) => e.stopPropagation());
      toolbar.addEventListener('pointerdown', (e) => e.stopPropagation());
      const toolbarLeft = document.createElement('div');
      toolbarLeft.className = 'flex items-center gap-1.5 min-w-0 flex-1 overflow-hidden';
      const label = document.createElement('span');
      label.className = 'shrink-0 text-[10px] text-amber-300/90 font-extrabold bg-amber-950/60 px-1.5 py-0.5 rounded border border-amber-700/50';
      label.textContent = opts.badge || '保存済み';
      toolbarLeft.appendChild(label);
      toolbar.appendChild(toolbarLeft);

      const toolbarRight = document.createElement('div');
      toolbarRight.className = 'input-tab-history-actions';
      const favBtn = document.createElement('button');
      favBtn.type = 'button';
      favBtn.className = 'input-tab-history-icon-btn bg-amber-950/50 text-amber-200 border border-amber-700/60';
      favBtn.dataset.favLabelOn = '★';
      favBtn.dataset.favLabelOff = '☆';
      favBtn.setAttribute('aria-label', 'お気に入り');
      styleFavoriteButton(favBtn, !!(
        (stored && stored.id && typeof isFavoriteId === 'function' && isFavoriteId(stored.id))
        || (stored && stored.content && typeof getFavorites === 'function'
          && getFavorites().some((f) => f && dumpContentEquals(f.content, stored.content)))
      ));
      bindInputHistoryActionButton(favBtn, () => {
        if (!stored || stored.id == null || (typeof isTempId === 'function' && isTempId(stored.id))) {
          alert('同期完了までお気に入りに登録できません');
          return;
        }
        const nowOn = toggleFavorite(stored, {
          folder: stored.folder,
          file: stored.file,
          isInbox: !!(stored.isInbox || historyDestIsInbox(stored.folder))
        });
        styleFavoriteButton(favBtn, nowOn);
        const favTab = document.getElementById('favorites-mode');
        if (favTab && favTab.classList.contains('active') && typeof renderFavoritesList === 'function') {
          renderFavoritesList();
        }
      });
      const openBtn = document.createElement('button');
      openBtn.type = 'button';
      openBtn.className = 'input-tab-history-icon-btn is-wide bg-cyan-950/60 hover:bg-cyan-900/70 text-cyan-100 border border-cyan-600/60';
      openBtn.innerHTML = '<span aria-hidden="true">📂</span><span>開く</span>';
      openBtn.title = '開く';
      openBtn.setAttribute('aria-label', '開く');
      bindInputHistoryActionButton(openBtn, () => {
        if (typeof openSearchResultLocationItem === 'function') {
          openSearchResultLocationItem(stored, { openDetail: true, instant: true });
        }
      });
      const deleteBtn = document.createElement('button');
      deleteBtn.type = 'button';
      deleteBtn.className = 'input-tab-history-icon-btn bg-rose-950/60 text-rose-200 border border-rose-700/60';
      deleteBtn.textContent = '🗑️';
      deleteBtn.title = '削除';
      deleteBtn.setAttribute('aria-label', '削除');
      bindInputHistoryActionButton(deleteBtn, () => {
        deleteInputTabStoredMatch(stored, opts.pair);
      });
      toolbarRight.appendChild(favBtn);
      toolbarRight.appendChild(openBtn);
      toolbarRight.appendChild(deleteBtn);
      toolbar.appendChild(toolbarRight);

      const preview = document.createElement('div');
      preview.className = 'whitespace-pre-wrap line-clamp-8 text-sm leading-relaxed bg-[#02040a]/60 p-2.5 border border-cyan-900/50 rounded-xl';
      if (typeof setDumpContentDisplay === 'function') setDumpContentDisplay(preview, stored.content || '');
      else preview.textContent = stored.content || '';

      item.appendChild(toolbar);
      item.appendChild(preview);
      return item;
    }

    function purgeDupMatchFromLocalUi(match) {
      if (!match || !match.content) return null;
      const content = match.content;
      const matchId = match.id != null && match.id !== '' ? String(match.id) : '';
      // 削除中に届く古い取得結果（ゴミ箱移動前の読み取り）で復活させない
      rememberRecentDumpTrash({ ids: matchId ? [matchId] : [], contents: [content] });
      // 同じ本文の登録チェックも消す（非表示だけだと再起動・他端末で戻る）
      const historyHits = getLocalInputHistory().filter((e) => e && dumpContentEquals(e.content, content));
      if (historyHits.some((e) => isEditingInputHistoryEntry(e))) {
        clearInputHistoryEditState({ clearTextarea: true });
      }
      const historyHit = historyHits.find((e) => e.id != null && !isLocalOnlyHistoryId(e.id));
      const historyId = historyHit ? String(historyHit.id) : '';
      dropInputHistoryEntries((e) => dumpContentEquals(e.content, content));
      if (typeof suppressReplacedHistoryContent === 'function') {
        suppressReplacedHistoryContent(content);
      }
      rememberInputHistoryTombstone(historyId, content);
      if (typeof forgetDumpedItemsByContents === 'function') {
        forgetDumpedItemsByContents([content], { includeStored: true });
      }
      if (storedItemsCache && Array.isArray(storedItemsCache.items)) {
        storedItemsCache.items = storedItemsCache.items.filter((r) => {
          if (!r) return false;
          if (matchId && String(r.id) === matchId) return false;
          return !dumpContentEquals(r.content, content);
        });
      }
      if (typeof pendingDumpCache !== 'undefined' && Array.isArray(pendingDumpCache)) {
        pendingDumpCache = pendingDumpCache.filter((r) => {
          if (!r) return false;
          if (matchId && String(r.id) === matchId) return false;
          return !dumpContentEquals(r.content, content);
        });
      }
      Object.keys(inputTabDupMap || {}).forEach((k) => {
        const list = inputTabDupMap[k] || [];
        inputTabDupMap[k] = list.filter((m) => {
          if (!m) return false;
          if (matchId && m.id != null && String(m.id) === matchId) return false;
          return !dumpContentEquals(m.content, content);
        });
      });
      if (typeof saveInputTabOverlapPairs === 'function' && typeof getInputTabOverlapPairs === 'function') {
        saveInputTabOverlapPairs(getInputTabOverlapPairs().filter((p) => {
          if (!p) return false;
          if (matchId && p.storedId && String(p.storedId) === matchId) return false;
          if (p.storedSnap && dumpContentEquals(p.storedSnap.content, content)) return false;
          return true;
        }));
      }
      // ここではサーバー再取得しない（ゴミ箱移動前の一覧を掴んで復活するため）。再取得は移動完了後
      forgetStoredCacheEntries({
        ids: matchId ? [matchId] : [],
        contents: [content]
      });
      // 進行中の重複再スキャンがゴミ箱前の結果で復活させるのを止める
      if (typeof inputTabDupToken === 'number') inputTabDupToken += 1;
      return { historyId };
    }

    async function trashDupMatchReliably(match) {
      if (!match || !match.content) return false;
      const content = match.content;
      const matchId = match.id != null && match.id !== '' && !(typeof isTempId === 'function' && isTempId(match.id))
        ? String(match.id)
        : '';
      // 未送信の DUMP が残っていると、ゴミ箱後にサーバーへ届いて復活する
      if (typeof flushInboxWriteChain === 'function') {
        try { await flushInboxWriteChain(); } catch (_) { }
      }
      let ok = false;
      const trashedIds = [];
      if (matchId) {
        ok = !!(await trashDumpMatch({
          id: matchId,
          content,
          folder: match.folder,
          file: match.file,
          isInbox: !!(match.isInbox || (typeof historyDestIsInbox === 'function' && historyDestIsInbox(match.folder)))
        }));
        if (!ok && typeof resolveDumpByIdFresh === 'function') {
          try {
            const fresh = await resolveDumpByIdFresh(matchId, null);
            if (fresh && fresh.id) {
              ok = !!(await trashDumpMatch(fresh));
            }
          } catch (e) { }
        }
        if (ok) trashedIds.push(matchId);
      }
      // 同本文の別コピーもまとめてゴミ箱へ（IDずれ／片方だけ残るのを防ぐ）
      let leftover = false;
      try {
        if (typeof findExactDumpHitsOnServer === 'function') {
          const hits = await findExactDumpHitsOnServer(content, {
            inbox: true,
            anywhere: true
          });
          for (let i = 0; i < (hits || []).length; i++) {
            const hit = hits[i];
            if (!hit || hit.id == null) continue;
            if (await trashDumpMatch(hit)) {
              trashedIds.push(String(hit.id));
              ok = true;
            } else {
              leftover = true;
            }
          }
        }
      } catch (e) {
        console.warn('trashDupMatchReliably content scan failed', e);
      }
      if (trashedIds.length) rememberRecentDumpTrash({ ids: trashedIds, contents: [content] });
      if (leftover) return false;
      return ok || !matchId;
    }

    /** 重複情報の削除をクラウドへ反映（直列・再試行）。保存一覧の取り直しはゴミ箱移動の後 */
    async function syncDupMatchDeleteToCloud(match, purged) {
      if (!match || !match.content) return false;
      const content = match.content;
      const matchId = match.id != null && match.id !== '' ? String(match.id) : '';
      const historyId = purged && purged.historyId ? purged.historyId : '';
      let synced = true;
      try {
        await enqueueInputHistoryDeleteSync(async () => {
          const ok = await trashDupMatchReliably(match);
          if (!ok) throw new Error('dup_trash');
          await removeInputHistoryEntry(historyId, content);
        }, {
          label: '重複削除',
          onFinalFail: () => {
            if (typeof queuePendingInputHistoryDelete === 'function') {
              queuePendingInputHistoryDelete(historyId, content);
            }
            showInputHistoryDeleteStatus(
              '削除は端末に反映済みです。クラウド同期は後で再試行されます',
              'error'
            );
          }
        });
      } catch (e) {
        synced = false;
      }
      invalidateStoredItemsCache({
        ids: matchId ? [matchId] : [],
        contents: [content]
      });
      if (typeof updateBadge === 'function') updateBadge();
      if (typeof scheduleInputTabDupEnrichment === 'function') {
        scheduleInputTabDupEnrichment(typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : []);
      }
      return synced;
    }

    async function deleteInputTabStoredMatch(stored, pair) {
      if (!stored || !stored.content) return;
      const preview = String(stored.content || '').trim().slice(0, 40);
      if (!confirm(`保存済みの重複・類似データをゴミ箱へ移しますか？\n登録チェックからも消えます。\n\n${preview}${preview.length >= 40 ? '…' : ''}`)) return;
      let purged = null;
      try {
        purged = purgeDupMatchFromLocalUi(stored);
        if (pair && pair.newKey && pair.oldKey) {
          dismissInputTabOverlapPair(pair.newKey, pair.oldKey);
        } else {
          paintInputTabHistory(typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : []);
        }
        if (typeof syncInputTabDupBadgesInDom === 'function') syncInputTabDupBadgesInDom();
      } catch (e) {
        console.error('Failed to purge stored match locally', e);
      }
      await syncDupMatchDeleteToCloud(stored, purged);
    }

    function buildInputTabFavLookup() {
      const ids = new Set();
      const contentKeys = new Set();
      if (typeof getFavorites !== 'function') return { ids, contentKeys };
      try {
        (getFavorites() || []).forEach((f) => {
          if (!f) return;
          if (f.id != null && f.id !== '') ids.add(String(f.id));
          if (Array.isArray(f.ids)) f.ids.forEach((id) => { if (id != null && id !== '') ids.add(String(id)); });
          if (f.content) contentKeys.add(dumpContentKey(f.content));
        });
      } catch (_) { }
      return { ids, contentKeys };
    }

    // お気に入り ID を持つ保存データの本文（保存データが変わったら作り直す）
    function favoritedDumpContentKeys(lookup) {
      const items = (storedItemsCache && storedItemsCache.items) || [];
      const pending = typeof pendingDumpCache !== 'undefined' && Array.isArray(pendingDumpCache) ? pendingDumpCache : [];
      const src = lookup.dumpKeysSrc;
      if (!lookup.dumpKeys || !src || src.items !== items || src.itemsLen !== items.length
        || src.pending !== pending || src.pendingLen !== pending.length) {
        const keys = new Set();
        const scan = (r) => {
          if (r && r.id != null && lookup.ids.has(String(r.id))) keys.add(dumpContentKey(r.content));
        };
        items.forEach(scan);
        pending.forEach(scan);
        lookup.dumpKeys = keys;
        lookup.dumpKeysSrc = { items, itemsLen: items.length, pending, pendingLen: pending.length };
      }
      return lookup.dumpKeys;
    }

    function isHistoryEntryFavoritedWithLookup(entry, lookup) {
      if (!lookup) {
        return typeof isHistoryEntryFavorited === 'function' && isHistoryEntryFavorited(entry);
      }
      if (!entry) return false;
      if (entry.content && lookup.contentKeys.has(dumpContentKey(entry.content))) return true;
      if (!lookup.ids.size) return false;
      // ID で一致し得るのは dumpId・代替 ID・同じ本文の保存データの ID だけ。どれにも当たらなければ保存データ全件の照合（1件ごとに数ms）を省く
      const maybe = (entry.dumpId != null && entry.dumpId !== '' && lookup.ids.has(String(entry.dumpId)))
        || lookup.ids.has(favoriteFallbackId(entry))
        || (!!entry.content && favoritedDumpContentKeys(lookup).has(dumpContentKey(entry.content)));
      if (!maybe) return false;
      const target = typeof getDumpFavoriteTargetFromHistory === 'function'
        ? getDumpFavoriteTargetFromHistory(entry)
        : null;
      return !!(target && target.id != null && lookup.ids.has(String(target.id)));
    }

    function inputTabHistoryPaintSig(entries) {
      // id・時刻は同期で入れ替わるので含めない（本文＋レーンだけ。同じ一覧なら再描画しない）
      return (entries || []).map((e) => {
        if (!e) return '';
        const key = typeof dumpContentKey === 'function'
          ? dumpContentKey(e.content)
          : String(e.content || '');
        return key + '\t' + (typeof historyEntryLane === 'function' ? historyEntryLane(e) : '');
      }).join('\n');
    }

    function currentInputTabLaneFilter() {
      return inputHistoryLaneFilter === 'todo' || inputHistoryLaneFilter === 'log' || inputHistoryLaneFilter === 'inbox'
        ? inputHistoryLaneFilter
        : '';
    }

    function visibleInputTabHistoryEntries(entries) {
      const safeEntries = dedupeInputHistoryEntriesByContent(
        (entries || []).map(sanitizeInputHistoryEntry).filter(Boolean)
      );
      const sorted = safeEntries.slice().sort((a, b) => {
        const ta = typeof getSearchTimestampMs === 'function' ? getSearchTimestampMs(a) : new Date(a.timestamp || 0).getTime();
        const tb = typeof getSearchTimestampMs === 'function' ? getSearchTimestampMs(b) : new Date(b.timestamp || 0).getTime();
        return (tb || 0) - (ta || 0);
      });
      const laneFilter = currentInputTabLaneFilter();
      return laneFilter
        ? sorted.filter((e) => historyEntryLane(e) === laneFilter)
        : sorted;
    }

    function syncInputTabHistoryPaintSigFromLocal() {
      const laneFilter = currentInputTabLaneFilter();
      const visible = visibleInputTabHistoryEntries(
        typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : []
      );
      inputTabLastPaintSig = laneFilter + '\n' + inputTabHistoryPaintSig(visible);
      const countEl = document.getElementById('input-tab-history-count');
      if (countEl) {
        const label = inputHistoryLaneShortLabel(laneFilter);
        countEl.textContent = label ? `${label} ${visible.length}件` : `${visible.length}件`;
      }
      return visible;
    }

    function removeInputTabHistoryCardsByContents(contents) {
      const roots = [
        document.getElementById('input-tab-history-recent'),
        document.getElementById('input-tab-history-list')
      ].filter(Boolean);
      if (!roots.length || !contents || !contents.length) return 0;
      const keys = new Set((contents || []).map((c) => dumpContentKey(c)).filter(Boolean));
      if (!keys.size) return 0;
      let n = 0;
      roots.forEach((root) => {
        root.querySelectorAll('[data-history-card="1"]').forEach((card) => {
          const preview = card.querySelector('.whitespace-pre-wrap');
          const key = dumpContentKey(preview ? preview.textContent : '');
          if (!key || !keys.has(key)) return;
          const wrap = card.closest('[data-overlap-pair]') || card;
          wrap.remove();
          n += 1;
        });
      });
      return n;
    }

    /** 削除直後、再描画が飛ばされてもカードを画面から外す */
    function removeInputTabHistoryCardsForEntry(entry) {
      if (!entry) return 0;
      const roots = [
        document.getElementById('input-tab-history-recent'),
        document.getElementById('input-tab-history-list')
      ].filter(Boolean);
      if (!roots.length) return 0;
      const id = entry.id != null && entry.id !== '' ? String(entry.id) : '';
      const key = dumpContentKey(entry.content);
      let n = 0;
      roots.forEach((root) => {
        root.querySelectorAll('[data-history-card="1"]').forEach((card) => {
          const sameId = !!(id && card.getAttribute('data-history-id') === id);
          const preview = card.querySelector('.whitespace-pre-wrap');
          const cardKey = dumpContentKey(preview ? preview.textContent : '');
          const sameKey = !!(key && cardKey && cardKey === key);
          if (!sameId && !sameKey) return;
          const wrap = card.closest('[data-overlap-pair]') || card;
          wrap.remove();
          n += 1;
        });
      });
      return n;
    }

    function prependInputTabHistoryEntries(newEntries, opts) {
      opts = opts || {};
      const list = document.getElementById('input-tab-history-list');
      const recent = document.getElementById('input-tab-history-recent');
      if (!list) return false;
      const inputTab = document.getElementById('input-mode');
      if (!inputTab || !inputTab.classList.contains('active')) {
        inputTabHistoryDirty = true;
        return false;
      }
      const added = (newEntries || []).map(sanitizeInputHistoryEntry).filter(Boolean);
      const removeContents = opts.removeContents || [];
      if (!added.length && !removeContents.length) return false;
      const hasPaintedDom = !!(list.querySelector('[data-history-card]') || list.querySelector('[data-history-empty]') || (recent && recent.querySelector('[data-history-card]')));
      if (!hasPaintedDom) return false;

      // 同じID／同じ本文の既存カードを先に外す（連続 upsert で recent に二重差し込みしない）
      added.forEach((entry) => removeInputTabHistoryCardsForEntry(entry));
      if (removeContents.length) removeInputTabHistoryCardsByContents(removeContents);
      const empty = list.querySelector('[data-history-empty]');
      if (empty) empty.remove();

      const laneFilter = currentInputTabLaneFilter();
      const visibleAdded = laneFilter
        ? added.filter((e) => historyEntryLane(e) === laneFilter)
        : added;
      if (visibleAdded.length) {
        const favLookup = opts.favLookup || buildInputTabFavLookup();
        const frag = document.createDocumentFragment();
        visibleAdded.forEach((entry) => {
          frag.appendChild(createInputTabHistoryCard(entry, { favLookup }));
        });
        // 本一覧へ差し込むと数千件の再レイアウトで固まる。直前の保存分だけ上枠へ出す
        const host = recent || list;
        if (host && frag.childNodes.length) host.insertBefore(frag, host.firstChild);
      }
      const visible = syncInputTabHistoryPaintSigFromLocal();
      syncInputTabHistoryLock();
      if (!opts.skipDupSchedule) scheduleInputTabDupEnrichment(visible);
      if (typeof refreshCheckBlocksListIfVisible === 'function') refreshCheckBlocksListIfVisible();
      if (typeof updateDumpDepthDisplay === 'function') updateDumpDepthDisplay();
      return true;
    }

    function refreshInputTabHistoryAfterLocalChange(newEntries, opts) {
      opts = opts || {};
      if (prependInputTabHistoryEntries(newEntries, opts)) return true;
      if (opts.skipPaint) return false;
      paintInputTabHistory(
        typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : [],
        { skipDupSchedule: !!opts.skipDupSchedule, force: !!opts.force }
      );
      return true;
    }

    function paintInputTabHistory(entries, paintOpts) {
      paintOpts = paintOpts || {};
      const list = document.getElementById('input-tab-history-list');
      const countEl = document.getElementById('input-tab-history-count');
      if (!list) {
        // 入力タブDOMが無くてもブロック一覧は更新する（ブロックタブからの削除用）
        if (typeof refreshCheckBlocksListIfVisible === 'function') refreshCheckBlocksListIfVisible();
        return;
      }
      const inputTab = document.getElementById('input-mode');
      if (!inputTab || !inputTab.classList.contains('active')) {
        inputTabHistoryDirty = true;
        // 入力タブ非表示でもブロックタブの削除反映は行う
        if (typeof refreshCheckBlocksListIfVisible === 'function') refreshCheckBlocksListIfVisible();
        return;
      }
      inputTabHistoryDirty = false;
      const safeEntries = dedupeInputHistoryEntriesByContent(
        (entries || []).map(sanitizeInputHistoryEntry).filter(Boolean)
      );
      const sorted = safeEntries.slice().sort((a, b) => {
        const ta = typeof getSearchTimestampMs === 'function' ? getSearchTimestampMs(a) : new Date(a.timestamp || 0).getTime();
        const tb = typeof getSearchTimestampMs === 'function' ? getSearchTimestampMs(b) : new Date(b.timestamp || 0).getTime();
        return (tb || 0) - (ta || 0);
      });
      const laneFilter = inputHistoryLaneFilter === 'todo' || inputHistoryLaneFilter === 'log' || inputHistoryLaneFilter === 'inbox'
        ? inputHistoryLaneFilter
        : '';
      const visible = laneFilter
        ? sorted.filter((e) => historyEntryLane(e) === laneFilter)
        : sorted;

      if (countEl) {
        const label = inputHistoryLaneShortLabel(laneFilter);
        countEl.textContent = label ? `${label} ${visible.length}件` : `${visible.length}件`;
      }

      // 同期ポーリング等で中身が同じなら再描画しない（スクロール飛び防止）
      // ただし初期「読み込み中...」のままスキップしない（カード or 空表示マーカーが必要）
      const sig = laneFilter + '\n' + inputTabHistoryPaintSig(visible);
      const hasPaintedDom = !!(list.querySelector('[data-history-card]') || list.querySelector('[data-history-empty]'));
      if (!paintOpts.force && sig === inputTabLastPaintSig && hasPaintedDom) {
        syncInputTabHistoryLock();
        return;
      }
      inputTabLastPaintSig = sig;
      const recent = document.getElementById('input-tab-history-recent');
      if (recent) recent.innerHTML = '';

      const token = ++inputTabPaintToken;
      // 既定でスクロール位置を維持（明示的に resetScroll のときだけ先頭へ）
      const preserveScroll = paintOpts.resetScroll !== true;
      const scroller = document.getElementById('input-tab-history-scroll') || list;
      list.style.minHeight = '';
      const savedScrollTop = preserveScroll ? scroller.scrollTop : 0;
      let userMovedScroll = false;
      const onUserScroll = () => {
        if (Math.abs(scroller.scrollTop - savedScrollTop) > 2) userMovedScroll = true;
      };
      if (preserveScroll) {
        const active = document.activeElement;
        if (active && active !== document.body && list.contains(active) && typeof active.blur === 'function') {
          active.blur();
        }
        scroller.style.scrollBehavior = 'auto';
        scroller.style.overflowAnchor = 'none';
        scroller.addEventListener('scroll', onUserScroll, { passive: true });
      }
      const restoreScroll = () => {
        if (!preserveScroll || token !== inputTabPaintToken || userMovedScroll) return;
        scroller.style.scrollBehavior = 'auto';
        if (scroller.scrollTop !== savedScrollTop) scroller.scrollTop = savedScrollTop;
      };
      const releaseScrollPin = () => {
        if (token !== inputTabPaintToken) return;
        scroller.removeEventListener('scroll', onUserScroll);
        list.style.minHeight = '';
        scroller.style.overflowAnchor = '';
        scroller.style.scrollBehavior = '';
        restoreScroll();
      };

      if (visible.length === 0) {
        const label = inputHistoryLaneShortLabel(laneFilter);
        list.innerHTML = label
          ? '<div data-history-empty="1" class="text-center py-6 text-cyan-700/80 text-sm font-bold">' + label + ' の登録チェックはまだありません</div>'
          : '<div data-history-empty="1" class="text-center py-6 text-cyan-700/80 text-sm font-bold">まだ登録チェックはありません<br><span class="text-xs text-cyan-800/80 mt-1 inline-block">DUMPするとここに残り、重複・類似も表示されます</span></div>';
        syncInputTabHistoryLock();
        if (!paintOpts.skipDupSchedule) {
          inputTabDupMap = Object.create(null);
          inputTabDupAnalyzing = false;
        }
        releaseScrollPin();
        if (typeof refreshCheckBlocksListIfVisible === 'function') refreshCheckBlocksListIfVisible();
        if (typeof updateDumpDepthDisplay === 'function') updateDumpDepthDisplay();
        return;
      }
      list.innerHTML = '';
      restoreScroll();
      if (scroller._dumpHistoryTail) {
        scroller.removeEventListener('scroll', scroller._dumpHistoryTail);
        scroller._dumpHistoryTail = null;
      }
      pruneInputTabOverlapPairs(visible);
      const favLookup = buildInputTabFavLookup();
      let idx = 0;
      let tailArmed = false;
      const finishPaint = () => {
        if (token !== inputTabPaintToken) return;
        if (scroller._dumpHistoryTail) {
          scroller.removeEventListener('scroll', scroller._dumpHistoryTail);
          scroller._dumpHistoryTail = null;
        }
        restoreScroll();
        releaseScrollPin();
        syncInputTabHistoryLock();
        if (!paintOpts.skipDupSchedule) scheduleInputTabDupEnrichment(visible);
        if (typeof refreshCheckBlocksListIfVisible === 'function') refreshCheckBlocksListIfVisible();
        if (typeof updateDumpDepthDisplay === 'function') updateDumpDepthDisplay();
      };
      const armHistoryTail = () => {
        if (tailArmed || token !== inputTabPaintToken) return;
        tailArmed = true;
        syncInputTabHistoryLock();
        releaseScrollPin();
        if (!paintOpts.skipDupSchedule) scheduleInputTabDupEnrichment(visible);
        if (typeof refreshCheckBlocksListIfVisible === 'function') refreshCheckBlocksListIfVisible();
        if (typeof updateDumpDepthDisplay === 'function') updateDumpDepthDisplay();
        const onScroll = () => {
          if (token !== inputTabPaintToken) {
            scroller.removeEventListener('scroll', onScroll);
            return;
          }
          if (scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight < 700) appendChunk();
        };
        scroller._dumpHistoryTail = onScroll;
        scroller.addEventListener('scroll', onScroll, { passive: true });
      };
      const appendChunk = () => {
        if (token !== inputTabPaintToken) return;
        const frag = document.createDocumentFragment();
        const end = Math.min(idx + INPUT_TAB_PAINT_CHUNK, visible.length);
        for (; idx < end; idx++) {
          frag.appendChild(createInputTabHistoryCard(visible[idx], { favLookup }));
        }
        list.appendChild(frag);
        restoreScroll();
        if (idx >= visible.length) {
          finishPaint();
          return;
        }
        // 画面に入る分だけ先に作り、残りは下までスクロールしたときに足す
        const canMeasure = scroller.clientHeight > 80;
        const filled = canMeasure && scroller.scrollHeight > scroller.clientHeight + 48;
        if (!filled && canMeasure) {
          requestAnimationFrame(appendChunk);
          return;
        }
        if (!tailArmed) {
          armHistoryTail();
          return;
        }
        if (scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight < 700) {
          requestAnimationFrame(appendChunk);
        }
      };
      appendChunk();
    }

    let checkBlocksExpandState = null;
    let checkBlocksLane = 'inbox';
    let checkBlockDrag = null;

    function setCheckBlocksLane(lane) {
      checkBlocksLane = lane === 'todo' || lane === 'log' ? lane : 'inbox';
      document.querySelectorAll('.blocks-lane-tab').forEach((btn) => {
        const on = btn.getAttribute('data-blocks-lane') === checkBlocksLane;
        btn.classList.toggle('is-active', on);
        btn.setAttribute('aria-selected', on ? 'true' : 'false');
      });
      renderCheckBlocksList();
    }

    function isCheckBlocksModeActive() {
      const el = document.getElementById('blocks-mode');
      return !!(el && el.classList.contains('active'));
    }

    function refreshCheckBlocksListIfVisible() {
      if (!isCheckBlocksModeActive()) return;
      if (checkBlocksExpandState) return;
      renderCheckBlocksList();
    }

    function initCheckBlocksMode() {
      closeCheckBlockExpand({ silent: true });
      renderCheckBlocksList();
      runInBackground(() => {
        if (typeof syncInputTabHistoryFromCloud === 'function') {
          return syncInputTabHistoryFromCloud().then(() => {
            if (isCheckBlocksModeActive() && !checkBlocksExpandState) renderCheckBlocksList();
          });
        }
      });
    }

    function getCheckBlocksEntries() {
      const entries = typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : [];
      const deduped = typeof dedupeInputHistoryEntriesByContent === 'function'
        ? dedupeInputHistoryEntriesByContent(entries)
        : (entries || []);
      const lane = checkBlocksLane || 'inbox';
      return (deduped || [])
        .filter((e) => e && isUsableInputHistoryContent(e.content))
        .filter((e) => !(typeof isInputHistoryTombstoned === 'function' && isInputHistoryTombstoned(e)))
        .filter((e) => historyEntryLane(e) === lane)
        .slice()
        .sort((a, b) => {
          const ta = typeof getSearchTimestampMs === 'function' ? getSearchTimestampMs(a) : new Date(a.timestamp || 0).getTime();
          const tb = typeof getSearchTimestampMs === 'function' ? getSearchTimestampMs(b) : new Date(b.timestamp || 0).getTime();
          return (tb || 0) - (ta || 0);
        });
    }

    function bindBlocksListWheelGlide() {
      const list = document.getElementById('check-blocks-list');
      if (!list || list.dataset.wheelGlide === '1') return;
      list.dataset.wheelGlide = '1';
      let target = list.scrollTop;
      let raf = 0;
      let selfScroll = false; // 慣性側が scrollTop を動かしているとき true

      const stopGlide = () => {
        if (raf) {
          cancelAnimationFrame(raf);
          raf = 0;
        }
        target = list.scrollTop;
      };

      // スクロールバー／タッチ操作中に慣性へ引き戻されないようにする
      list.addEventListener('pointerdown', () => stopGlide(), { passive: true });
      list.addEventListener('scroll', () => {
        if (selfScroll) return;
        stopGlide();
      }, { passive: true });

      list.addEventListener('wheel', (e) => {
        if (e.ctrlKey || e.metaKey) return;
        const max = Math.max(0, list.scrollHeight - list.clientHeight);
        if (max <= 0) return;
        let dy = e.deltaY;
        if (e.deltaMode === 1) dy *= 32;
        else if (e.deltaMode === 2) dy *= list.clientHeight || 0;
        if (!dy) return;
        if (e.deltaMode === 0 && Math.abs(dy) < 48) return;
        e.preventDefault();
        target = Math.max(0, Math.min(max, target + dy));
        if (raf) return;
        const step = () => {
          const limit = Math.max(0, list.scrollHeight - list.clientHeight);
          if (target > limit) target = limit;
          const diff = target - list.scrollTop;
          if (Math.abs(diff) < 0.6) {
            selfScroll = true;
            list.scrollTop = target;
            selfScroll = false;
            raf = 0;
            return;
          }
          selfScroll = true;
          list.scrollTop += diff * 0.34;
          selfScroll = false;
          raf = requestAnimationFrame(step);
        };
        raf = requestAnimationFrame(step);
      }, { passive: false });
    }

    function renderCheckBlocksList() {
      bindBlocksListWheelGlide();
      closeCheckBlockMenu();
      const list = document.getElementById('check-blocks-list');
      if (!list) return;
      const entries = getCheckBlocksEntries();
      if (!entries.length) {
        const label = dumpLaneDest(checkBlocksLane).label;
        const laneClass = checkBlocksLane === 'todo' ? 'is-lane-todo' : (checkBlocksLane === 'log' ? 'is-lane-log' : 'is-lane-inbox');
        list.innerHTML = '<div class="check-blocks-empty text-center py-10 font-bold text-sm border-2 border-dashed rounded-2xl ' + laneClass + '">' + label + 'はまだありません</div>';
        return;
      }
      list.innerHTML = '';
      entries.forEach((entry) => {
        list.appendChild(createCheckBlockCard(entry));
      });
    }

    let checkBlockMenuEl = null;

    function closeCheckBlockMenu() {
      if (checkBlockMenuEl && checkBlockMenuEl.parentNode) checkBlockMenuEl.parentNode.removeChild(checkBlockMenuEl);
      checkBlockMenuEl = null;
    }

    function openCheckBlockMenu(anchor, items) {
      if (!anchor || !items || !items.length) return;
      const reopen = checkBlockMenuEl && checkBlockMenuEl.dataset.anchorId && anchor.dataset.menuAnchorId && checkBlockMenuEl.dataset.anchorId === anchor.dataset.menuAnchorId;
      closeCheckBlockMenu();
      if (reopen) return;
      if (!anchor.dataset.menuAnchorId) anchor.dataset.menuAnchorId = 'bm-' + Math.random().toString(36).slice(2);
      const menu = document.createElement('div');
      menu.className = 'check-block-menu';
      menu.dataset.anchorId = anchor.dataset.menuAnchorId;
      menu.setAttribute('role', 'menu');
      items.forEach((item) => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'check-block-menu-item' + (item.danger ? ' is-danger' : '');
        btn.setAttribute('role', 'menuitem');
        btn.textContent = item.label;
        btn.addEventListener('click', (e) => {
          e.preventDefault();
          e.stopPropagation();
          closeCheckBlockMenu();
          if (typeof item.onSelect === 'function') item.onSelect();
        });
        menu.appendChild(btn);
      });
      document.body.appendChild(menu);
      const rect = anchor.getBoundingClientRect();
      const width = Math.max(menu.offsetWidth, 184);
      let left = rect.right - width;
      if (left < 8) left = 8;
      if (left + width > window.innerWidth - 8) left = Math.max(8, window.innerWidth - width - 8);
      let top = rect.bottom + 6;
      menu.style.left = left + 'px';
      menu.style.top = top + 'px';
      const menuRect = menu.getBoundingClientRect();
      if (menuRect.bottom > window.innerHeight - 8) {
        menu.style.top = Math.max(8, rect.top - menuRect.height - 6) + 'px';
      }
      checkBlockMenuEl = menu;
    }

    document.addEventListener('pointerdown', (e) => {
      if (!checkBlockMenuEl) return;
      if (checkBlockMenuEl.contains(e.target)) return;
      if (e.target && e.target.closest && e.target.closest('[data-menu-anchor-id]')) return;
      closeCheckBlockMenu();
    }, true);
    window.addEventListener('scroll', () => closeCheckBlockMenu(), true);

    function createCheckBlockCard(entry) {
      const card = document.createElement('div');
      const laneClass = checkBlocksLane === 'todo' ? 'is-lane-todo' : (checkBlocksLane === 'log' ? 'is-lane-log' : 'is-lane-inbox');
      card.className = 'check-block-card w-full text-left rounded-2xl border-2 px-3.5 py-3 transition active:scale-[0.99] ' + laneClass;
      const body = document.createElement('div');
      body.className = 'check-block-card-body whitespace-pre-wrap line-clamp-5 text-sm leading-relaxed font-mono';
      if (typeof setDumpContentDisplay === 'function') setDumpContentDisplay(body, entry.content || '');
      else body.textContent = String(entry.content || '');
      const actions = document.createElement('div');
      actions.className = 'check-block-actions';
      actions.addEventListener('pointerdown', (e) => e.stopPropagation());
      actions.addEventListener('click', (e) => e.stopPropagation());

      const moreBtn = document.createElement('button');
      moreBtn.type = 'button';
      moreBtn.className = 'check-block-icon-btn bg-black/40 text-cyan-100 border border-cyan-800/60';
      moreBtn.textContent = '…';
      moreBtn.title = '操作';
      moreBtn.setAttribute('aria-label', '操作');
      moreBtn.setAttribute('aria-haspopup', 'menu');
      moreBtn.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        const favorited = typeof isHistoryEntryFavorited === 'function' && isHistoryEntryFavorited(entry);
        openCheckBlockMenu(moreBtn, [
          {
            label: '📋 コピー',
            onSelect: () => copyTextToClipboard(entry.content || '')
          },
          {
            label: favorited ? '★ お気に入り解除' : '☆ お気に入り',
            onSelect: () => toggleFavoriteFromInputHistory(entry)
          },
          {
            label: '🗑️ 削除',
            danger: true,
            onSelect: () => deleteInputTabHistoryEntry(entry, { fromOverlap: false })
          }
        ]);
      });

      actions.appendChild(moreBtn);
      card.appendChild(body);
      card.appendChild(actions);
      bindCheckBlockDrag(card, entry);
      card.addEventListener('click', (e) => {
        if (e.target.closest('.check-block-actions')) return;
        if (card.dataset.suppressClick === '1') {
          e.preventDefault();
          e.stopPropagation();
          card.dataset.suppressClick = '';
          return;
        }
        openCheckBlockEdit(entry);
      });
      return card;
    }

    function blockLaneFromPoint(x, y) {
      const tabs = document.querySelectorAll('.blocks-lane-tab');
      let best = '';
      let bestDist = Infinity;
      tabs.forEach((tab) => {
        const r = tab.getBoundingClientRect();
        const left = r.left - 16;
        const right = r.right + 16;
        const top = r.top - 36;
        const bottom = r.bottom + 96;
        if (x < left || x > right || y < top || y > bottom) return;
        const cx = Math.max(r.left, Math.min(x, r.right));
        const cy = Math.max(r.top, Math.min(y, r.bottom));
        const dist = Math.hypot(x - cx, y - cy);
        if (dist < bestDist) {
          bestDist = dist;
          best = tab.getAttribute('data-blocks-lane') || '';
        }
      });
      return best;
    }

    function paintBlockDragTarget(lane) {
      document.querySelectorAll('.blocks-lane-tab').forEach((tab) => {
        tab.classList.toggle('is-drop-target', !!lane && tab.getAttribute('data-blocks-lane') === lane);
      });
    }

    let checkBlockScrollLockBound = false;
    function ensureCheckBlockScrollLockListeners() {
      if (checkBlockScrollLockBound) return;
      checkBlockScrollLockBound = true;
      window.addEventListener('touchmove', (ev) => {
        if (!checkBlockDrag || !checkBlockDrag.started) return;
        if (ev.cancelable) ev.preventDefault();
        const t = ev.touches && ev.touches[0];
        if (t) {
          checkBlockDrag.lastX = t.clientX;
          checkBlockDrag.lastY = t.clientY;
          moveCheckBlockDrag({
            clientX: t.clientX,
            clientY: t.clientY,
            preventDefault: () => {}
          });
        }
      }, { capture: true, passive: false });
      window.addEventListener('wheel', (ev) => {
        if (!checkBlockDrag || !checkBlockDrag.started) return;
        if (ev.cancelable) ev.preventDefault();
      }, { capture: true, passive: false });
    }

    function cancelCheckBlockDrag() {
      if (!checkBlockDrag) return;
      const drag = checkBlockDrag;
      checkBlockDrag = null;
      if (drag.timer) clearTimeout(drag.timer);
      if (drag.card) {
        drag.card.classList.remove('is-dragging-block');
        drag.card.style.touchAction = '';
      }
      document.documentElement.classList.remove('is-block-lane-drag');
      document.body.classList.remove('is-block-lane-drag');
      const list = document.getElementById('check-blocks-list');
      if (list) {
        list.classList.remove('is-block-dragging');
        if (drag.onListScroll) list.removeEventListener('scroll', drag.onListScroll);
      }
      if (drag.ghost && drag.ghost.parentNode) drag.ghost.parentNode.removeChild(drag.ghost);
      paintBlockDragTarget('');
    }

    function moveCheckBlockDrag(e) {
      if (!checkBlockDrag || !checkBlockDrag.started) return;
      e.preventDefault();
      const ghost = checkBlockDrag.ghost;
      if (ghost) {
        ghost.style.left = Math.max(8, e.clientX - 28) + 'px';
        ghost.style.top = Math.max(8, e.clientY - 64) + 'px';
      }
      const lane = blockLaneFromPoint(e.clientX, e.clientY);
      checkBlockDrag.hoverLane = lane;
      paintBlockDragTarget(lane);
    }

    function startCheckBlockDrag(e) {
      if (!checkBlockDrag || checkBlockDrag.started) return;
      ensureCheckBlockScrollLockListeners();
      const drag = checkBlockDrag;
      drag.started = true;
      if (drag.timer) {
        clearTimeout(drag.timer);
        drag.timer = null;
      }
      if (drag.card) {
        drag.card.dataset.suppressClick = '1';
        drag.card.classList.add('is-dragging-block');
        drag.card.style.touchAction = 'none';
        try { drag.card.setPointerCapture(e.pointerId); } catch (_) { }
      }
      const list = document.getElementById('check-blocks-list');
      if (list) {
        drag.lockedScrollTop = list.scrollTop;
        drag.onListScroll = () => {
          if (checkBlockDrag === drag && drag.started && list.scrollTop !== drag.lockedScrollTop) {
            list.scrollTop = drag.lockedScrollTop;
          }
        };
        list.addEventListener('scroll', drag.onListScroll, { passive: true });
        list.classList.add('is-block-dragging');
      }
      document.documentElement.classList.add('is-block-lane-drag');
      document.body.classList.add('is-block-lane-drag');
      const ghost = document.createElement('div');
      ghost.className = 'blocks-drag-ghost';
      ghost.textContent = String((drag.entry && drag.entry.content) || '').slice(0, 80);
      ghost.style.left = Math.max(8, e.clientX - 28) + 'px';
      ghost.style.top = Math.max(8, e.clientY - 64) + 'px';
      document.body.appendChild(ghost);
      drag.ghost = ghost;
      try { if (navigator.vibrate) navigator.vibrate(12); } catch (_) { }
    }

    function finishCheckBlockDrag(e) {
      if (!checkBlockDrag) return;
      const drag = checkBlockDrag;
      const started = drag.started;
      const entry = drag.entry;
      const x = e && e.clientX != null ? e.clientX : drag.lastX;
      const y = e && e.clientY != null ? e.clientY : drag.lastY;
      const lane = started ? (blockLaneFromPoint(x, y) || drag.hoverLane || '') : '';
      cancelCheckBlockDrag();
      if (!started || !entry || !lane) return;
      if (historyEntryLane(entry) === (lane === 'todo' || lane === 'log' ? lane : 'inbox')) return;
      moveCheckBlockToLane(entry, lane);
    }

    function bindCheckBlockDrag(card, entry) {
      ensureCheckBlockScrollLockListeners();
      card.addEventListener('pointerdown', (e) => {
        if (e.pointerType === 'mouse' && e.button !== 0) return;
        if (checkBlockDrag) cancelCheckBlockDrag();
        const drag = {
          pointerId: e.pointerId,
          entry,
          card,
          startX: e.clientX,
          startY: e.clientY,
          lastX: e.clientX,
          lastY: e.clientY,
          started: false,
          scrolling: false,
          hoverLane: '',
          ghost: null,
          timer: null
        };
        checkBlockDrag = drag;
        const onMove = (ev) => {
          if (!checkBlockDrag || checkBlockDrag !== drag || ev.pointerId !== drag.pointerId) return;
          const dist = Math.hypot(ev.clientX - drag.startX, ev.clientY - drag.startY);
          drag.lastX = ev.clientX;
          drag.lastY = ev.clientY;
          if (!drag.started) {
            if (!drag.scrolling && dist > 8) {
              drag.scrolling = true;
              if (drag.card) drag.card.dataset.suppressClick = '1';
              if (drag.timer) clearTimeout(drag.timer);
              drag.timer = null;
            }
            return;
          }
          ev.preventDefault();
          moveCheckBlockDrag(ev);
        };
        const onUp = (ev) => {
          if (ev.pointerId !== drag.pointerId) return;
          document.removeEventListener('pointermove', onMove, true);
          document.removeEventListener('pointerup', onUp, true);
          document.removeEventListener('pointercancel', onUp, true);
          if (checkBlockDrag !== drag) return;
          if (drag.scrolling || (ev.type === 'pointercancel' && !drag.started)) {
            cancelCheckBlockDrag();
            return;
          }
          finishCheckBlockDrag(ev);
        };
        document.addEventListener('pointermove', onMove, true);
        document.addEventListener('pointerup', onUp, true);
        document.addEventListener('pointercancel', onUp, true);
        drag.timer = setTimeout(() => {
          if (checkBlockDrag !== drag || drag.started || drag.scrolling) return;
          startCheckBlockDrag({
            pointerId: drag.pointerId,
            clientX: drag.lastX,
            clientY: drag.lastY
          });
        }, 160);
      });
      card.addEventListener('contextmenu', (e) => {
        e.preventDefault();
      });
    }

    const pendingHistoryLaneMoves = new Map();
    let historyLaneMoveGen = 0;
    let historyLaneMoveChain = Promise.resolve();

    function rememberPendingHistoryLaneMove(entry, dest, timestamp) {
      const id = entry && entry.id != null ? String(entry.id) : '';
      const contentKey = typeof dumpContentKey === 'function' ? dumpContentKey(entry && entry.content) : '';
      const gen = ++historyLaneMoveGen;
      const rec = {
        gen,
        id,
        contentKey,
        folder: dest.folder,
        file: dest.file,
        dumpIsInbox: dest.isInbox,
        timestamp,
        entry: entry ? { ...entry } : null
      };
      if (id) pendingHistoryLaneMoves.set('id:' + id, rec);
      if (contentKey) pendingHistoryLaneMoves.set('ck:' + contentKey, rec);
      return rec;
    }

    function pendingHistoryLaneMoveFor(entry) {
      if (!entry || !pendingHistoryLaneMoves.size) return null;
      const id = entry.id != null ? String(entry.id) : '';
      const contentKey = typeof dumpContentKey === 'function' ? dumpContentKey(entry.content) : '';
      return (id && pendingHistoryLaneMoves.get('id:' + id))
        || (contentKey && pendingHistoryLaneMoves.get('ck:' + contentKey))
        || null;
    }

    function clearPendingHistoryLaneMove(rec) {
      if (!rec) return;
      const idHit = rec.id ? pendingHistoryLaneMoves.get('id:' + rec.id) : null;
      const ckHit = rec.contentKey ? pendingHistoryLaneMoves.get('ck:' + rec.contentKey) : null;
      if (idHit && idHit.gen === rec.gen) pendingHistoryLaneMoves.delete('id:' + rec.id);
      if (ckHit && ckHit.gen === rec.gen) pendingHistoryLaneMoves.delete('ck:' + rec.contentKey);
    }

    function applyPendingHistoryLaneMoves(entries) {
      const list = Array.isArray(entries) ? entries.slice() : [];
      if (!pendingHistoryLaneMoves.size) return list;
      const seen = new Set();
      const out = list.map((e) => {
        const hit = pendingHistoryLaneMoveFor(e);
        if (!hit) return e;
        const id = e && e.id != null ? String(e.id) : '';
        const ck = typeof dumpContentKey === 'function' ? dumpContentKey(e.content) : '';
        if (id) seen.add('id:' + id);
        if (ck) seen.add('ck:' + ck);
        return {
          ...e,
          folder: hit.folder,
          file: hit.file,
          dumpIsInbox: hit.dumpIsInbox,
          timestamp: hit.timestamp || e.timestamp
        };
      });
      pendingHistoryLaneMoves.forEach((hit, key) => {
        if (!hit || !String(key).startsWith('id:')) return;
        const idKey = hit.id ? ('id:' + hit.id) : '';
        const ckKey = hit.contentKey ? ('ck:' + hit.contentKey) : '';
        if ((idKey && seen.has(idKey)) || (ckKey && seen.has(ckKey))) return;
        if (!hit.entry) return;
        seen.add(idKey);
        if (ckKey) seen.add(ckKey);
        out.unshift({
          ...hit.entry,
          id: hit.id || hit.entry.id,
          content: hit.entry.content,
          folder: hit.folder,
          file: hit.file,
          dumpIsInbox: hit.dumpIsInbox,
          timestamp: hit.timestamp || hit.entry.timestamp
        });
      });
      return out;
    }

    function moveCheckBlockToLane(entry, lane) {
      const dest = dumpLaneDest(lane);
      if (!entry || historyEntryLane(entry) === dest.lane) return;
      const now = new Date().toISOString();
      const rec = rememberPendingHistoryLaneMove(entry, dest, now);
      if (rec.contentKey && typeof inputHistorySuppressedContents !== 'undefined') {
        inputHistorySuppressedContents.delete(rec.contentKey);
      }
      if (rec.contentKey && typeof inputHistoryTombstoneKeys !== 'undefined') {
        inputHistoryTombstoneKeys.delete(rec.contentKey);
      }
      const next = applyPendingHistoryLaneMoves(
        typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : []
      );
      if (typeof cacheLocalInputHistory === 'function') cacheLocalInputHistory(next);
      if (typeof flushLocalInputHistoryCache === 'function') flushLocalInputHistoryCache();
      renderCheckBlocksList();
      if (typeof paintInputTabHistory === 'function') {
        paintInputTabHistory(typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : [], { skipDupSchedule: true });
      }
      if (typeof pauseInputHistoryCloudSync === 'function') pauseInputHistoryCloudSync();
      historyLaneMoveChain = historyLaneMoveChain.then(async () => {
        const latestId = rec.id ? pendingHistoryLaneMoves.get('id:' + rec.id) : null;
        const latestCk = rec.contentKey ? pendingHistoryLaneMoves.get('ck:' + rec.contentKey) : null;
        const latest = latestId || latestCk;
        if (!latest || latest.gen !== rec.gen) return;
        try {
          const id = rec.id;
          if (id && typeof isLocalOnlyHistoryId === 'function' && !isLocalOnlyHistoryId(id) && typeof encodeInputHistoryPayload === 'function') {
            const payload = encodeInputHistoryPayload(entry.content, rec.folder, rec.file, rec.timestamp);
            if (payload) {
              await callAPI('updateDataRecord', { id, content: payload }, { silent: true });
            }
          }
          const dumpId = entry.dumpId && !(typeof isTempId === 'function' && isTempId(entry.dumpId)) ? String(entry.dumpId) : '';
          if (dumpId) {
            await callAPI('moveInboxItem', {
              id: dumpId,
              folder: rec.dumpIsInbox ? 'INBOX' : rec.folder,
              file: rec.file
            }, { silent: true });
          }
        } catch (err) {
          console.warn('move check block lane', err);
        } finally {
          clearPendingHistoryLaneMove(rec);
        }
      }).finally(() => {
        if (typeof resumeInputHistoryCloudSync === 'function') resumeInputHistoryCloudSync();
      });
    }

    function setCheckBlocksExpandVisible(show) {
      const listView = document.getElementById('check-blocks-list-view');
      const expandView = document.getElementById('check-blocks-expand-view');
      // flex と hidden が同居すると Tailwind の順序で display:flex が勝ち、一覧が残る
      if (listView) {
        listView.classList.toggle('hidden', !!show);
        listView.style.display = show ? 'none' : '';
      }
      if (expandView) expandView.classList.toggle('hidden', !show);
    }

    function setCheckBlocksExpandStatus(text, tone) {
      const el = document.getElementById('check-blocks-expand-status');
      if (!el) return;
      el.textContent = text || '';
      el.className = tone === 'error'
        ? 'text-center text-xs font-bold text-rose-400 min-h-[1rem]'
        : tone === 'ok'
          ? 'text-center text-xs font-bold text-emerald-400 min-h-[1rem]'
          : 'text-center text-xs font-bold text-cyan-400/80 min-h-[1rem]';
    }

    function syncCheckBlockExpandActions() {
      closeCheckBlockMenu();
      const delBtn = document.getElementById('check-blocks-expand-delete');
      const favBtn = document.getElementById('check-blocks-expand-fav');
      const copyBtn = document.getElementById('check-blocks-expand-copy');
      const clearBtn = document.getElementById('check-blocks-expand-clear');
      const state = checkBlocksExpandState;
      const editing = !!(state && state.mode === 'edit' && state.entry);
      const isNew = !!(state && state.mode === 'new');
      if (delBtn) delBtn.classList.toggle('hidden', !editing);
      if (copyBtn) copyBtn.classList.toggle('hidden', !editing);
      if (clearBtn) clearBtn.classList.toggle('hidden', !isNew);
      if (!favBtn) return;
      favBtn.classList.toggle('hidden', !editing);
      if (!editing) return;
      favBtn.dataset.favLabelOn = '★';
      favBtn.dataset.favLabelOff = '☆';
      const on = typeof isHistoryEntryFavorited === 'function' && isHistoryEntryFavorited(state.entry);
      styleFavoriteButton(favBtn, !!on);
    }

    function copyCheckBlockExpand() {
      const editor = document.getElementById('check-blocks-editor');
      const btn = document.getElementById('check-blocks-expand-copy');
      copyTextToClipboard(editor ? editor.value : '', btn);
    }

    function clearCheckBlockExpand() {
      const state = checkBlocksExpandState;
      if (!state || state.mode !== 'new') return;
      const editor = document.getElementById('check-blocks-editor');
      if (!editor) return;
      if (!String(editor.value || '').trim()) {
        setCheckBlocksExpandStatus('');
        return;
      }
      editor.value = '';
      if (typeof textUndoReset === 'function') textUndoReset(editor);
      setCheckBlocksExpandStatus('入力をクリアしました', 'ok');
      try { editor.focus({ preventScroll: true }); } catch (_) { }
    }

    function toggleCheckBlockExpandFavorite() {
      const state = checkBlocksExpandState;
      if (!state || state.mode !== 'edit' || !state.entry) return;
      const btn = document.getElementById('check-blocks-expand-fav');
      toggleFavoriteFromInputHistory(state.entry, btn);
    }

    function openCheckBlockNew() {
      if (!checkBlocksExpandState && typeof pushAppNavLocation === 'function' && typeof getAppLocationKey === 'function') {
        pushAppNavLocation(getAppLocationKey());
      }
      checkBlocksExpandState = { mode: 'new', entry: null };
      const editor = document.getElementById('check-blocks-editor');
      if (editor) {
        editor.value = '';
        if (typeof textUndoReset === 'function') textUndoReset(editor);
        editor.focus({ preventScroll: true });
      }
      syncCheckBlockExpandActions();
      setCheckBlocksExpandStatus('');
      setCheckBlocksExpandVisible(true);
    }

    function openCheckBlockEdit(entry) {
      if (!entry) return;
      if (!checkBlocksExpandState && typeof pushAppNavLocation === 'function' && typeof getAppLocationKey === 'function') {
        pushAppNavLocation(getAppLocationKey());
      }
      checkBlocksExpandState = { mode: 'edit', entry: { ...entry } };
      const editor = document.getElementById('check-blocks-editor');
      if (editor) {
        editor.value = String(entry.content || '');
        if (typeof textUndoReset === 'function') textUndoReset(editor);
        editor.focus({ preventScroll: true });
      }
      syncCheckBlockExpandActions();
      setCheckBlocksExpandStatus('');
      setCheckBlocksExpandVisible(true);
    }

    function closeCheckBlockExpand(opts) {
      opts = opts || {};
      const editor = document.getElementById('check-blocks-editor');
      const state = checkBlocksExpandState;
      if (!opts.silent && state && editor) {
        const current = String(editor.value || '');
        const original = state.mode === 'edit' ? String((state.entry && state.entry.content) || '') : '';
        const dirty = state.mode === 'new'
          ? !!current.trim()
          : current !== original;
        if (dirty && !confirm('編集内容を破棄して一覧へ戻りますか？')) return false;
      }
      checkBlocksExpandState = null;
      setCheckBlocksExpandStatus('');
      setCheckBlocksExpandVisible(false);
      if (isCheckBlocksModeActive()) renderCheckBlocksList();
      return true;
    }

    function saveCheckBlockExpand() {
      const state = checkBlocksExpandState;
      const editor = document.getElementById('check-blocks-editor');
      if (!state || !editor) return;
      const content = String(editor.value || '').trim();
      if (!content) {
        setCheckBlocksExpandStatus('内容を入力してください', 'error');
        return;
      }
      try {
        if (state.mode === 'new') {
          queueCheckBlockAsNewDump(content);
        } else {
          queueCheckBlockAsReplace(state.entry, content);
        }
        // ローカル反映だけ待ってすぐ一覧へ（クラウド同期は裏で）
        checkBlocksExpandState = null;
        setCheckBlocksExpandStatus('');
        setCheckBlocksExpandVisible(false);
        renderCheckBlocksList();
        if (typeof paintInputTabHistory === 'function') {
          paintInputTabHistory(getLocalInputHistory(), { skipDupSchedule: true });
        }
      } catch (e) {
        console.warn('saveCheckBlockExpand failed', e);
        setCheckBlocksExpandStatus('保存に失敗しました', 'error');
      }
    }

    function queueCheckBlockAsNewDump(content) {
      const chunks = typeof splitDumpContent === 'function' ? splitDumpContent(content) : [content];
      const addedChunks = (chunks || []).filter((c) => c && String(c).trim());
      if (!addedChunks.length) throw new Error('empty');
      const laneDest = dumpLaneDest(checkBlocksLane);
      const destFolder = laneDest.folder;
      const destFile = laneDest.file;
      const isInboxDest = laneDest.isInbox;
      appendLocalInputHistory(addedChunks, destFolder, destFile);
      const optimisticItems = addedChunks.map((c) => ({
        id: makeTempId(),
        content: c,
        timestamp: new Date().toISOString(),
        folder: isInboxDest ? '📥 INBOX' : destFolder,
        file: destFile,
        isInbox: isInboxDest,
        _pending: true
      }));
      rememberDumpedItems(optimisticItems);
      if (isInboxDest && typeof bumpBadgeOptimistic === 'function') bumpBadgeOptimistic(addedChunks.length);
      const historyId = logOperation('ADD', `${addedChunks.length}件を INBOX に追加`, {
        folder: destFolder,
        file: destFile,
        contents: addedChunks
      });
      const dumpJob = {
        id: makePendingWriteId(),
        type: 'dump_add',
        addedChunks: addedChunks.slice(),
        replaceDupChunks: [],
        destFolder,
        destFile,
        isInboxDest,
        directFolder: '',
        historyId,
        pendingReplaceId: ''
      };
      addPendingInboxWrite(dumpJob);
      markPendingWriteQueued(dumpJob.id);
      const inputStatus = document.getElementById('input-status');
      if (inputStatus) {
        const dumpChars = addedChunks.reduce((n, c) => n + String(c || '').length, 0);
        addSyncGaugeJob(inputStatus, {
          id: dumpJob.id,
          historyId,
          label: `✓ ${addedChunks.length}件を受け付けました`,
          estimateMs: syncGaugeEstimateMs(dumpChars),
          count: addedChunks.length
        });
      }
      enqueueInboxWrite(async () => {
        pendingWriteRunningIds.add(dumpJob.id);
        try {
          await executeDumpAddJob(dumpJob);
          removePendingInboxWrite(dumpJob.id);
          const statusEl = document.getElementById('input-status');
          if (historyId && cancelledDumpHistoryIds.has(historyId)) {
            dropSyncGaugeByHistory(historyId);
          } else if (statusEl) {
            settleSyncGaugeJob(statusEl, dumpJob.id, {
              doneText: `✓ ${addedChunks.length}件の保存が完了しました`,
              className: 'text-base mt-2 text-center font-bold text-emerald-400'
            });
          }
        } catch (err) {
          bumpPendingInboxWriteAttempt(dumpJob.id);
          const statusEl = document.getElementById('input-status');
          if (statusEl) {
            settleSyncGaugeJob(statusEl, dumpJob.id, {
              failed: true,
              doneText: '保存に失敗しました。再開時に再同期します',
              className: 'text-base mt-2 text-center font-bold text-rose-400'
            });
          }
          throw err;
        } finally {
          pendingWriteRunningIds.delete(dumpJob.id);
          clearPendingWriteQueued(dumpJob.id);
        }
      }, {
        historyId,
        onError: () => clearPendingWriteQueued(dumpJob.id)
      });
    }

    function queueCheckBlockAsReplace(entry, newContent) {
      if (!entry) throw new Error('no_entry');
      const oldContent = String(entry.content || '').trim();
      const folder = historyDestIsInbox(entry.folder) ? 'INBOX' : (entry.folder || 'INBOX');
      const file = entry.file || '未整理';
      const isInboxDest = historyDestIsInbox(folder);
      if (dumpContentEquals(newContent, oldContent)) return;
      let historyId = entry.id;
      if (!historyId) {
        historyId = `local-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
        const local = getLocalInputHistory();
        const idx = local.findIndex((e) => e && (
          e === entry || historyEntryKey(e) === historyEntryKey(entry)
        ));
        if (idx >= 0) {
          local[idx] = { ...local[idx], id: historyId };
          cacheLocalInputHistory(local);
        }
      }
      const pendingReplace = {
        id: historyId,
        content: oldContent,
        folder,
        file,
        dumpId: entry.dumpId || '',
        dumpIsInbox: entry.dumpIsInbox != null ? entry.dumpIsInbox : isInboxDest
      };
      // 入力タブ編集と同じく、同期完了までクラウド再取得を止め新旧並びを防ぐ
      pauseInputHistoryCloudSync();
      let cloudPauseHeld = true;
      const releaseCloudPause = () => {
        if (!cloudPauseHeld) return;
        cloudPauseHeld = false;
        resumeInputHistoryCloudSync();
      };
      applyOptimisticInputHistoryReplace(pendingReplace, newContent, oldContent, folder, file);
      const replaceJob = {
        id: makePendingWriteId(),
        type: 'history_replace',
        pendingReplace,
        oldContent,
        newContent,
        destFolder: folder,
        destFile: file,
        isInboxDest,
        destChanged: false,
        origFolder: folder,
        origFile: file,
        origInbox: isInboxDest,
        preResolvedDumpId: pendingReplace.dumpId && !isTempId(pendingReplace.dumpId)
          ? String(pendingReplace.dumpId)
          : '',
        preResolvedDumpIsInbox: pendingReplace.dumpIsInbox
      };
      addPendingInboxWrite(replaceJob);
      markPendingWriteQueued(replaceJob.id);
      enqueueInboxWrite(async () => {
        pendingWriteRunningIds.add(replaceJob.id);
        try {
          await executeHistoryReplaceJob(replaceJob);
          removePendingInboxWrite(replaceJob.id);
        } catch (err) {
          bumpPendingInboxWriteAttempt(replaceJob.id);
          throw err;
        } finally {
          pendingWriteRunningIds.delete(replaceJob.id);
          clearPendingWriteQueued(replaceJob.id);
          // 旧本文の suppress/tombstone を維持したまま再確定
          upsertLocalInputHistoryReplace({
            fromId: pendingReplace.id,
            toId: pendingReplace.id,
            oldContent,
            newContent,
            folder,
            file,
            persistTombstone: !dumpContentEquals(oldContent, newContent)
          });
          if (typeof paintInputTabHistory === 'function') {
            paintInputTabHistory(getLocalInputHistory(), { force: true, skipDupSchedule: true });
          } else if (typeof renderCheckBlocksList === 'function' && isCheckBlocksModeActive()) {
            renderCheckBlocksList();
          }
          setTimeout(() => releaseCloudPause(), 400);
        }
      }, {
        onError: () => {
          clearPendingWriteQueued(replaceJob.id);
          releaseCloudPause();
        }
      });
    }

    async function deleteCheckBlockExpand() {
      const state = checkBlocksExpandState;
      if (!state || state.mode !== 'edit' || !state.entry) return;
      const entry = state.entry;
      await deleteInputTabHistoryEntry(entry, { fromOverlap: false });
      const stillThere = getCheckBlocksEntries().some((e) =>
        (entry.id && sameInputHistoryId(e.id, entry.id))
        || dumpContentEquals(e.content, entry.content)
      );
      if (!stillThere) {
        checkBlocksExpandState = null;
        setCheckBlocksExpandVisible(false);
        renderCheckBlocksList();
      }
    }

    function scheduleInputTabDupEnrichment(entries) {
      const token = ++inputTabDupToken;
      // 新しい順の先頭だけスキャン（全件は重い）
      const targets = (entries || [])
        .filter((e) => e && e.content)
        .slice(0, INPUT_TAB_DUP_ENRICH_MAX);
      if (targets.length === 0) {
        inputTabDupMap = Object.create(null);
        inputTabDupAnalyzing = false;
        return;
      }
      inputTabDupAnalyzing = true;
      runInBackground(async () => {
        try {
          const allItems = await collectAllStoredItems();
          if (token !== inputTabDupToken) return;
          const bundle = getOrBuildSimilarityBundle(allItems);
          const nextMap = Object.create(null);
          let changed = false;
          for (let i = 0; i < targets.length; i++) {
            if (token !== inputTabDupToken) return;
            const entry = targets[i];
            const key = historyOverlapKey(entry);
            if (!key) continue;
            const matches = findSimilarItemsForContent(
              entry,
              bundle,
              INPUT_TAB_DUP_LIMIT,
              INPUT_TAB_DUP_MIN_SCORE
            );
            nextMap[key] = matches;
            const prev = inputTabDupMap[key] || [];
            if (prev.length !== matches.length
              || prev.some((m, idx) => String(m.id) !== String(matches[idx] && matches[idx].id)
                || Math.round((m.matchScore || 0) * 100) !== Math.round((matches[idx].matchScore || 0) * 100))) {
              changed = true;
            }
            if (i === 0 || (i + 1) % 5 === 0 || i === targets.length - 1) {
              // 既存マップを残しつつ今回分だけ上書き（古い履歴のバッジを消さない）
              inputTabDupMap = Object.assign(Object.create(null), inputTabDupMap, nextMap);
              if (changed || i === targets.length - 1) {
                if (changed) {
                  // 全カード再描画せずバッジだけ更新（操作中のちらつき・押しにくさを防ぐ）
                  syncInputTabDupBadgesInDom();
                  if (inputDupModalSourceKey && document.getElementById('input-dup-modal')
                    && !document.getElementById('input-dup-modal').classList.contains('pointer-events-none')) {
                    const refreshed = nextMap[inputDupModalSourceKey] || inputTabDupMap[inputDupModalSourceKey] || [];
                    inputDupModalMatches = refreshed;
                    renderInputDupModalList();
                  }
                }
                changed = false;
              }
              await new Promise((resolve) => setTimeout(resolve, 0));
            }
          }
          if (token === inputTabDupToken) {
            inputTabDupMap = Object.assign(Object.create(null), inputTabDupMap, nextMap);
          }
        } catch (e) {
          console.warn('input tab dup enrich', e);
        } finally {
          if (token === inputTabDupToken) inputTabDupAnalyzing = false;
        }
      });
    }

    function openInputDupModal(entry, matches) {
      const modal = document.getElementById('input-dup-modal');
      if (!modal || !entry) return;
      inputDupModalSourceKey = historyOverlapKey(entry);
      inputDupModalMatches = Array.isArray(matches) ? matches.slice() : [];
      const sourceEl = document.getElementById('input-dup-source-text');
      if (sourceEl) {
        if (typeof setDumpContentDisplay === 'function') setDumpContentDisplay(sourceEl, entry.content || '');
        else sourceEl.textContent = entry.content || '';
      }
      const sub = document.getElementById('input-dup-subtitle');
      if (sub) {
        sub.textContent = `一致率30%以上 · ${inputDupModalMatches.length}件`;
      }
      renderInputDupModalList();
      modal.classList.remove('opacity-0', 'pointer-events-none', 'scale-[0.98]');
      modal.setAttribute('aria-hidden', 'false');
      modal.removeAttribute('inert');
      const dialog = document.getElementById('input-dup-dialog');
      setTimeout(() => { if (dialog) dialog.focus(); }, 30);
      if (!modal.dataset.escBound) {
        modal.dataset.escBound = '1';
        document.addEventListener('keydown', (event) => {
          if (event.key === 'Escape' && modal.getAttribute('aria-hidden') === 'false') {
            closeInputDupModal();
          }
        });
      }
    }

    function closeInputDupModal() {
      const modal = document.getElementById('input-dup-modal');
      if (!modal) return;
      modal.classList.add('opacity-0', 'pointer-events-none', 'scale-[0.98]');
      modal.setAttribute('aria-hidden', 'true');
      modal.setAttribute('inert', '');
      inputDupModalSourceKey = '';
      inputDupModalMatches = [];
    }

    function inputDupFolderLabel(match) {
      if (!match) return 'INBOX';
      if (match.isInbox || match.folder === 'INBOX' || match.folder === '📥 INBOX' || !match.folder) return 'INBOX';
      return String(match.folder).replace(/^📥\s*/, '');
    }

    function renderInputDupModalList() {
      const list = document.getElementById('input-dup-list');
      if (!list) return;
      if (!inputDupModalMatches.length) {
        list.innerHTML = '<div class="text-center py-8 text-slate-500 text-sm font-bold">一致率30%以上の過去情報はありません</div>';
        return;
      }
      list.innerHTML = '';
      inputDupModalMatches.forEach((match, idx) => {
        const row = document.createElement('div');
        row.className = 'rounded-2xl border border-amber-700/40 bg-black/40 p-3 space-y-2';
        const head = document.createElement('div');
        head.className = 'flex flex-wrap items-center justify-between gap-2';
        const loc = document.createElement('div');
        loc.className = 'text-[11px] font-extrabold text-amber-200 min-w-0';
        loc.textContent = `${inputDupFolderLabel(match)} ＞ ${match.file || '未整理'}`;
        const score = document.createElement('span');
        score.className = 'text-[10px] font-black text-amber-100 bg-amber-950/70 border border-amber-600/50 px-2 py-0.5 rounded-lg font-mono';
        score.textContent = `一致率 ${Math.round((match.matchScore || 0) * 100)}%`;
        head.appendChild(loc);
        head.appendChild(score);

        const preview = document.createElement('div');
        preview.className = 'text-xs text-cyan-100/90 font-mono whitespace-pre-wrap line-clamp-4 leading-relaxed bg-[#02040a]/50 border border-cyan-900/40 rounded-xl p-2.5 cursor-pointer';
        if (typeof setDumpContentDisplay === 'function') setDumpContentDisplay(preview, match.content || '');
        else preview.textContent = match.content || '';
        preview.title = 'タップで全文表示';
        preview.onclick = () => {
          const clamped = preview.classList.toggle('line-clamp-4');
          preview.title = clamped ? 'タップで全文表示' : 'タップで折りたたむ';
        };

        const actions = document.createElement('div');
        actions.className = 'grid grid-cols-3 gap-2';
        const editBtn = document.createElement('button');
        editBtn.type = 'button';
        editBtn.className = 'h-10 rounded-xl text-[11px] font-extrabold bg-cyan-900/50 text-cyan-100 border border-cyan-700/50 hover:bg-cyan-800/60 transition active:scale-95';
        editBtn.textContent = '✏️ 編集';
        editBtn.onclick = () => {
          closeInputDupModal();
          if (typeof openSearchResultLocationItem === 'function') {
            openSearchResultLocationItem(match, { openDetail: true, instant: true });
            setTimeout(() => {
              if (typeof startEditReviewItem === 'function') startEditReviewItem();
            }, 80);
          }
        };
        const openBtn = document.createElement('button');
        openBtn.type = 'button';
        openBtn.className = 'h-10 rounded-xl text-[11px] font-extrabold bg-slate-800/70 text-slate-100 border border-slate-600/60 hover:bg-slate-700/70 transition active:scale-95';
        openBtn.textContent = '📂 開く';
        openBtn.onclick = () => {
          closeInputDupModal();
          if (typeof openSearchResultLocationItem === 'function') {
            openSearchResultLocationItem(match, { openDetail: true, instant: true });
          }
        };
        const delBtn = document.createElement('button');
        delBtn.type = 'button';
        delBtn.className = 'h-10 rounded-xl text-[11px] font-extrabold bg-rose-950/50 text-rose-300 border border-rose-800/50 hover:bg-rose-900/60 transition active:scale-95';
        delBtn.textContent = '🗑️ 削除';
        delBtn.onclick = async () => {
          await deleteInputDupMatch(match, idx);
        };
        actions.appendChild(editBtn);
        actions.appendChild(openBtn);
        actions.appendChild(delBtn);

        row.appendChild(head);
        row.appendChild(preview);
        row.appendChild(actions);
        list.appendChild(row);
      });
    }

    async function deleteInputDupMatch(match, idx) {
      if (!match || !match.content) return;
      const preview = String(match.content || '').trim().slice(0, 40);
      if (!confirm(`この重複情報をゴミ箱へ移しますか？\n登録チェックからも消えます。\n\n${preview}${preview.length >= 40 ? '…' : ''}`)) return;
      const matchId = match.id != null && match.id !== '' ? String(match.id) : '';
      const content = match.content;
      let purged = null;
      try {
        purged = purgeDupMatchFromLocalUi(match);
        inputDupModalMatches = inputDupModalMatches.filter((m, i) => {
          if (!m) return false;
          if (idx != null && i === idx) return false;
          if (matchId && m.id != null && String(m.id) === matchId) return false;
          return !dumpContentEquals(m.content, content);
        });
        if (inputDupModalSourceKey) {
          inputTabDupMap[inputDupModalSourceKey] = inputDupModalMatches.slice();
        }
        const sub = document.getElementById('input-dup-subtitle');
        if (sub) sub.textContent = `一致率30%以上 · ${inputDupModalMatches.length}件`;
        renderInputDupModalList();
        if (typeof syncInputTabDupBadgesInDom === 'function') syncInputTabDupBadgesInDom();
        const scroller = document.getElementById('input-tab-history-scroll') || document.getElementById('input-tab-history-list');
        const scrollTop = scroller ? scroller.scrollTop : 0;
        paintInputTabHistory(typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : [], {
          skipDupSchedule: true
        });
        if (scroller) scroller.scrollTop = scrollTop;
        if (inputDupModalMatches.length === 0) closeInputDupModal();
      } catch (e) {
        console.error('Failed to purge dup match locally', e);
      }
      await syncDupMatchDeleteToCloud(match, purged);
    }

    function setInputHistoryReplaceHint(visible) {
      const bar = document.getElementById('input-history-replace-bar');
      const hint = document.getElementById('input-history-replace-hint');
      const cancelBtn = document.getElementById('capture-cancel-replace-btn');
      if (bar) bar.classList.toggle('hidden', !visible);
      if (hint) hint.classList.toggle('hidden', !visible);
      if (cancelBtn) cancelBtn.classList.toggle('hidden', !visible);
      if (typeof updateDirectSaveButton === 'function') updateDirectSaveButton();
      if (typeof paintDumpLaneCurrent === 'function') paintDumpLaneCurrent();
    }

    function isEditingInputHistoryEntry(entry) {
      if (!entry || !pendingInputHistoryReplace) return false;
      return (
        (entry.id && sameInputHistoryId(pendingInputHistoryReplace.id, entry.id)) ||
        dumpContentEquals(pendingInputHistoryReplace.content, entry.content)
      );
    }

    function clearInputHistoryEditState(opts) {
      opts = opts || {};
      pendingInputHistoryReplace = null;
      inputHistoryReplaceBackup = '';
      setInputHistoryReplaceHint(false);
      const textarea = document.getElementById('input-content');
      if (textarea && opts.clearTextarea) textarea.value = '';
      if (opts.clearTextarea && typeof clearDumpComposeImages === 'function') clearDumpComposeImages({ skipDraftSync: true });
      if (opts.clearTextarea && typeof clearLiveInputDraft === 'function') clearLiveInputDraft({ immediateCloud: true });
      if (typeof syncInputTabHistoryLock === 'function') syncInputTabHistoryLock();
      if (opts.focus && textarea) textarea.focus();
    }

    function cancelInputHistoryReplace() {
      const pending = pendingInputHistoryReplace;
      if (!pending) {
        setInputHistoryReplaceHint(false);
        return;
      }
      const textarea = document.getElementById('input-content');
      const backup = inputHistoryReplaceBackup || '';
      const pendingText = typeof stripDumpImageTokens === 'function'
        ? stripDumpImageTokens(pending.content || '')
        : String(pending.content || '');
      const pendingUrls = typeof listDumpImageUrls === 'function'
        ? listDumpImageUrls(pending.content || '').join('\n')
        : '';
      const currentUrls = (dumpComposeImages || []).map((x) => x.remoteUrl || '').filter(Boolean).join('\n');
      const hasNewLocalImages = (dumpComposeImages || []).some((x) => x && !x.remoteUrl);
      const dirty = !!(textarea && (
        String(textarea.value || '') !== pendingText
        || pendingUrls !== currentUrls
        || hasNewLocalImages
      ));
      if (dirty) {
        if (!confirm('編集内容を破棄して、登録チェックを読み込む前の入力に戻しますか？')) return;
      }
      pendingInputHistoryReplace = null;
      if (textarea) {
        if (typeof hydrateDumpComposeFromContent === 'function') {
          textarea.value = hydrateDumpComposeFromContent(backup);
        } else {
          textarea.value = backup;
        }
        textarea.focus();
      }
      inputHistoryReplaceBackup = '';
      setInputHistoryReplaceHint(false);
      if (typeof onLiveInputDraftChanged === 'function') {
        if (textarea && (String(textarea.value || '').trim() || (dumpComposeImages && dumpComposeImages.length))) {
          onLiveInputDraftChanged({ immediateCloud: true, reason: 'cancel_history_replace' });
        } else if (typeof clearLiveInputDraft === 'function') {
          clearLiveInputDraft({ immediateCloud: true });
        }
      }
      paintInputTabHistory(typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : []);
      const status = document.getElementById('input-status');
      if (status) {
        status.textContent = '編集を取り消しました';
        status.className = 'text-base mt-2 text-center font-bold text-slate-300';
        setTimeout(() => {
          if (status.textContent === '編集を取り消しました') status.textContent = '';
        }, 1600);
      }
    }

    function clearQuickInput() {
      const textarea = document.getElementById('input-content');
      if (!textarea) return;
      const hasContent = !!String(textarea.value || '').trim() || !!(dumpComposeImages && dumpComposeImages.length);
      if (!hasContent) {
        textarea.focus();
        return;
      }
      const prevInput = textarea.value;
      textarea.value = '';
      if (typeof clearDumpComposeImages === 'function') clearDumpComposeImages({ skipDraftSync: true });
      if (!pendingInputHistoryReplace && typeof clearLiveInputDraft === 'function') {
        clearLiveInputDraft({ immediateCloud: true });
      }
      if (typeof textUndoRemember === 'function') textUndoRemember(textarea, prevInput);
      if (typeof syncInputTabHistoryLock === 'function') syncInputTabHistoryLock();
      paintInputTabHistory(typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : []);
      const status = document.getElementById('input-status');
      if (status) {
        status.textContent = '入力欄をクリアしました';
        status.className = 'text-sm sm:text-base mt-1 text-center font-bold text-slate-300';
        setTimeout(() => {
          if (status.textContent === '入力欄をクリアしました') status.textContent = '';
        }, 1400);
      }
      textarea.focus();
    }

    function isDumpComposeDirtyVs(content) {
      const pendingText = typeof stripDumpImageTokens === 'function'
        ? stripDumpImageTokens(content || '')
        : String(content || '');
      const pendingUrls = typeof listDumpImageUrls === 'function'
        ? listDumpImageUrls(content || '').join('\n')
        : '';
      const ta = document.getElementById('input-content');
      const currentText = ta ? String(ta.value || '') : '';
      const currentUrls = (dumpComposeImages || []).map((x) => x.remoteUrl || '').filter(Boolean).join('\n');
      const hasLocal = (dumpComposeImages || []).some((x) => x && !x.remoteUrl);
      return currentText !== pendingText || currentUrls !== pendingUrls || hasLocal;
    }

    async function loadInputHistoryIntoQuickInput(entry) {
      const textarea = document.getElementById('input-content');
      if (!textarea || !entry) return;
      if (window.__suppressHistoryTapUntil && Date.now() < window.__suppressHistoryTapUntil) return;
      const incoming = entry.content || '';
      const pending = pendingInputHistoryReplace;
      const sameItem = !!(pending && (
        (entry.id && pending.id === entry.id) ||
        dumpContentEquals(pending.content, incoming)
      ));
      if (pending) {
        const dirty = isDumpComposeDirtyVs(pending.content || '');
        const sameIncoming = !isDumpComposeDirtyVs(incoming);
        if (dirty && !sameIncoming) {
          const msg = sameItem
            ? '編集中の内容を捨てて、登録チェックを読み直しますか？'
            : '編集中の内容を捨てて、別の項目を開きますか？';
          if (!confirm(msg)) return;
        } else if (!dirty && sameItem && sameIncoming) {
          textarea.focus();
          ensureSubmitInboxReady({ force: true, reason: 'edit_refocus' });
          return;
        }
      } else if (isInputHistoryLoadLocked()) {
        // 入力中でも確認すれば読み込める（以前は黙って拒否→「読み込まれない」に見えた）
        if (!confirm('入力中の内容を捨てて、この登録チェックを読み込みますか？')) {
          const status = document.getElementById('input-status');
          if (status) {
            status.textContent = '読み込みをキャンセルしました';
            status.className = 'text-base mt-2 text-center font-bold text-slate-300';
            setTimeout(() => {
              if (status.textContent === '読み込みをキャンセルしました') status.textContent = '';
            }, 1400);
          }
          return;
        }
      }
      if (!pendingInputHistoryReplace) {
        inputHistoryReplaceBackup = typeof appendDumpImageTokens === 'function'
          ? appendDumpImageTokens(
            textarea.value,
            (dumpComposeImages || []).map((x) => x.remoteUrl || '').filter(Boolean)
          )
          : textarea.value;
      }
      const prevInput = textarea.value;
      const displayText = typeof hydrateDumpComposeFromContent === 'function'
        ? hydrateDumpComposeFromContent(incoming)
        : incoming;
      textarea.value = displayText;
      if (typeof textUndoRemember === 'function') textUndoRemember(textarea, prevInput);

      // 編集モードを先に確定（await 前）。これがないとボタンが通常DUMPのままになり保存できない
      let historyId = entry.id;
      if (!historyId) {
        historyId = `local-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
        const local = getLocalInputHistory();
        const idx = local.findIndex((e) => e && (
          e === entry || historyEntryKey(e) === historyEntryKey(entry)
        ));
        if (idx >= 0) {
          local[idx] = { ...local[idx], id: historyId };
          cacheLocalInputHistory(local);
        }
      }
      const folderEl = document.getElementById('direct-folder');
      const fileEl = document.getElementById('direct-file');
      const cachedDump = findCachedDumpForHistory(entry);
      const knownDumpId = (cachedDump && cachedDump.id && !isTempId(cachedDump.id) ? String(cachedDump.id) : '')
        || (entry.dumpId && !isTempId(entry.dumpId) ? String(entry.dumpId) : '');
      pendingInputHistoryReplace = {
        id: historyId,
        content: incoming,
        folder: entry.folder || 'INBOX',
        file: entry.file || '未整理',
        uiFolderAtLoad: folderEl ? (folderEl.value || '') : '',
        uiFileAtLoad: fileEl ? (fileEl.value || '') : '',
        dumpId: knownDumpId,
        dumpIsInbox: cachedDump
          ? !!(cachedDump.isInbox || historyDestIsInbox(cachedDump.folder))
          : (entry.dumpIsInbox != null
            ? !!entry.dumpIsInbox
            : (historyDestIsInbox(entry.folder) ? true : null))
      };
      setInputHistoryReplaceHint(true);
      ensureSubmitInboxReady({ force: true, reason: 'edit_load' });
      paintInputTabHistory(typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : []);
      textarea.focus();
      try { textarea.setSelectionRange(textarea.value.length, textarea.value.length); } catch (_) { }

      // 保存先UIの同期・dumpId 紐付けは裏で行う（UIを待たせない）
      void (async () => {
        try {
          const uiDest = await syncDirectDestUiForHistoryEntry(entry);
          if (pendingInputHistoryReplace && sameInputHistoryId(pendingInputHistoryReplace.id, historyId)) {
            pendingInputHistoryReplace.uiFolderAtLoad = uiDest.uiFolder;
            pendingInputHistoryReplace.uiFileAtLoad = uiDest.uiFile;
            setInputHistoryReplaceHint(true);
          }
        } catch (e) {
          console.warn('syncDirectDestUiForHistoryEntry failed', e);
        }
        try {
          // 直前DUMPの同期待ち → 実ID取得
          await waitForPendingDumpWrites(incoming, 8000);
          if (!pendingInputHistoryReplace || !sameInputHistoryId(pendingInputHistoryReplace.id, historyId)) return;
          if (pendingInputHistoryReplace.dumpId && !isTempId(pendingInputHistoryReplace.dumpId)) {
            ensureSubmitInboxReady({ force: true, reason: 'edit_bound' });
            return;
          }
          const match = await withTimeout(
            resolvePendingDumpMatch(pendingInputHistoryReplace, { flush: false }),
            8000,
            'bind_dump'
          );
          if (!match || !match.id || isTempId(match.id)) return;
          if (!pendingInputHistoryReplace || !sameInputHistoryId(pendingInputHistoryReplace.id, historyId)) return;
          pendingInputHistoryReplace.dumpId = String(match.id);
          pendingInputHistoryReplace.dumpIsInbox = !!(match.isInbox || historyDestIsInbox(match.folder));
          // 登録チェック側にも残す
          const local = getLocalInputHistory();
          const idx = local.findIndex((e) => e && sameInputHistoryId(e.id, historyId));
          if (idx >= 0) {
            local[idx].dumpId = String(match.id);
            local[idx].dumpIsInbox = pendingInputHistoryReplace.dumpIsInbox;
            cacheLocalInputHistory(local);
          }
          ensureSubmitInboxReady({ force: true, reason: 'edit_bound' });
        } catch (e) {
          console.warn('background dump binding failed', e);
          ensureSubmitInboxReady({ force: true, reason: 'edit_bind_fail' });
        }
      })();
    }

    async function logInputHistoryAndReplaceSource(chunks, folder, file) {
      const added = appendLocalInputHistory(chunks, folder, file);
      if (typeof registerInputTabPartialOverlaps === 'function') registerInputTabPartialOverlaps(added);
      const pending = pendingInputHistoryReplace;
      if (pending && pending.id) {
        cacheLocalInputHistory(getLocalInputHistory().filter((e) => e.id !== pending.id));
        pendingInputHistoryReplace = null;
        inputHistoryReplaceBackup = '';
        setInputHistoryReplaceHint(false);
      }
      paintInputTabHistory(getLocalInputHistory());
      try {
        await syncInputHistoryToCloud(chunks, folder, file);
        if (pending && pending.id) await removeInputHistoryEntry(pending.id);
      } catch (e) {
        console.warn(e);
      }
      paintInputTabHistory(getLocalInputHistory());
    }

    async function deleteInputTabHistoryEntry(entry, opts) {
      if (!entry || (!entry.id && !entry.content)) return;
      const fromOverlap = !!(opts && opts.fromOverlap);
      const preview = String(entry.content || '').trim().slice(0, 40);
      const confirmMsg = fromOverlap
        ? `重複・類似のこちらを削除しますか？\n登録チェックから消し、同じ本文の保存があればゴミ箱へ移します。\n\n${preview}${preview.length >= 40 ? '…' : ''}`
        : `この登録チェック項目を削除しますか？\n同じ本文の INBOX／保存データがあればゴミ箱へ移します。\n\n${preview}${preview.length >= 40 ? '…' : ''}`;
      if (!confirm(confirmMsg)) return;

      // confirm の直後は、一部の端末で一覧の描き直しが画面に出ない。ダイアログが閉じてから反映する
      await new Promise((resolve) => {
        const run = () => {
          try { commitInputTabHistoryDelete(entry, fromOverlap); }
          finally { resolve(); }
        };
        if (typeof requestAnimationFrame === 'function') requestAnimationFrame(run);
        else setTimeout(run, 0);
      });
    }

    function commitInputTabHistoryDelete(entry, fromOverlap) {
      const editingDeleted = isEditingInputHistoryEntry(entry);
      unshieldDumpContentFromTrash(entry && entry.content);

      suppressReplacedHistoryContent(entry.content);
      if (typeof rememberInputHistoryTombstone === 'function') {
        rememberInputHistoryTombstone(entry.id, entry.content);
      }
      dropInputHistoryEntries((e) => {
        if (entry.id && sameInputHistoryId(e.id, entry.id)) return true;
        return dumpContentEquals(e.content, entry.content);
      });
      saveInputTabOverlapPairs(getInputTabOverlapPairs().filter((p) => {
        const key = historyOverlapKey(entry);
        return p.newKey !== key && p.oldKey !== key;
      }));
      if (editingDeleted) {
        clearInputHistoryEditState({ clearTextarea: true });
      }
      removeInputTabHistoryCardsForEntry(entry);
      paintInputTabHistory(typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : [], { force: true });
      // ブロックタブ表示中は paint が早期 return しても一覧を必ず落とす
      if (typeof isCheckBlocksModeActive === 'function' && isCheckBlocksModeActive()) {
        if (checkBlocksExpandState && checkBlocksExpandState.entry
          && (
            (entry.id && sameInputHistoryId(checkBlocksExpandState.entry.id, entry.id))
            || dumpContentEquals(checkBlocksExpandState.entry.content, entry.content)
          )) {
          checkBlocksExpandState = null;
          if (typeof setCheckBlocksExpandVisible === 'function') setCheckBlocksExpandVisible(false);
        }
        if (typeof renderCheckBlocksList === 'function') renderCheckBlocksList();
      }
      if (typeof bumpBadgeOptimistic === 'function' && historyDestIsInbox(entry.folder)) {
        bumpBadgeOptimistic(-1);
      }

      logOperation('DELETE', fromOverlap ? '登録チェックの重複から削除' : '登録チェックから削除', {
        oldFolder: entry.folder || 'INBOX',
        oldFile: entry.file || '未整理',
        newFolder: '🗑️ ゴミ箱',
        newFile: '削除履歴',
        content: entry.content,
        id: entry.dumpId || null,
        historyId: entry.id || null
      });

      // 連続削除でも API 競合しないよう直列＋再試行。失敗しても一覧は戻さない（tombstone 済み）
      enqueueInputHistoryDeleteSync(async () => {
        await removeInputHistoryEntry(entry.id, entry.content);
        await trashStoredDumpsMatchingHistory(entry);
      }, {
        label: '削除',
        onFinalFail: () => {
          if (typeof queuePendingInputHistoryDelete === 'function') {
            queuePendingInputHistoryDelete(entry.id, entry.content);
          }
          showInputHistoryDeleteStatus(
            '削除は端末に反映済みです。クラウド同期は後で再試行されます',
            'error'
          );
        }
      });
    }

    async function collectDumpHitsForHistoryTrash(entry) {
      if (!entry || !entry.content) return [];
      const folder = normalizeHistoryFolder(entry.folder);
      const file = entry.file || '未整理';
      const wantInbox = historyDestIsInbox(folder);
      const seen = new Set();
      const hits = [];
      const push = (match) => {
        if (!match || match.id == null || isTempId(match.id) || isNonUserDumpItem(match)) return;
        if (!dumpContentEquals(match.content, entry.content)) return;
        const id = String(match.id);
        if (seen.has(id)) return;
        seen.add(id);
        hits.push(toDumpMatch(match));
      };
      if (typeof findExactDumpHitsOnServer === 'function') {
        const serverHits = await findExactDumpHitsOnServer(entry.content, {
          inbox: true,
          folder: wantInbox ? null : folder,
          file: wantInbox ? null : file,
          anywhere: true
        });
        (serverHits || []).forEach(push);
      }
      if (!hits.length && typeof findDumpHitsByContent === 'function') {
        (await findDumpHitsByContent(entry.content) || []).forEach(push);
      }
      if (!hits.length && typeof resolveInputHistoryItem === 'function') {
        const one = await resolveInputHistoryItem(entry);
        if (one) push(one);
      }
      if (!hits.length && typeof findExactItemsForUndo === 'function') {
        const undoHits = await findExactItemsForUndo(folder, file, [entry.content]);
        (undoHits || []).forEach((row) => push({ ...row, content: entry.content }));
      }
      return hits;
    }

    async function trashStoredDumpsMatchingHistory(entry) {
      if (!entry || !entry.content) return;
      if (typeof flushInboxWriteChain === 'function') {
        try { await flushInboxWriteChain(); } catch (_) { }
      }
      let hits = [];
      try {
        hits = await collectDumpHitsForHistoryTrash(entry);
        if (!hits.length) {
          await new Promise((resolve) => setTimeout(resolve, 350));
          hits = await collectDumpHitsForHistoryTrash(entry);
        }
      } catch (e) {
        console.warn('collectDumpHitsForHistoryTrash failed', e);
        hits = [];
      }
      if (isDumpContentShieldedFromTrash(entry.content)) return;
      rememberRecentDumpTrash({
        ids: (hits || []).map((h) => h && h.id),
        contents: [entry.content]
      });
      const inboxMoves = [];
      const dataMoves = [];
      (hits || []).forEach((match) => {
        if (!match || match.id == null || (typeof isTempId === 'function' && isTempId(match.id))) return;
        if (match.content && isDumpContentShieldedFromTrash(match.content)) return;
        const move = { id: String(match.id), folder: '🗑️ ゴミ箱', file: '削除履歴' };
        if (typeof isSearchInboxItem === 'function' ? isSearchInboxItem(match) : match.isInbox) inboxMoves.push(move);
        else dataMoves.push(move);
      });
      if (inboxMoves.length || dataMoves.length) {
        let moved = false;
        for (let attempt = 0; attempt < 3 && !moved; attempt++) {
          try {
            if (typeof syncBulkTrashMoves === 'function') {
              await syncBulkTrashMoves(inboxMoves, dataMoves, { silent: true });
            } else {
              for (const m of inboxMoves) {
                const res = await callAPI('moveInboxItem', m, { silent: true });
                if (res && res.error) throw new Error('inbox_trash');
              }
              for (const m of dataMoves) {
                const res = await callAPI('moveDataRecord', m, { silent: true });
                if (res && res.error) throw new Error('data_trash');
              }
            }
            moved = true;
          } catch (e) {
            console.warn(`trash move attempt ${attempt + 1} failed`, e);
            if (attempt < 2) await new Promise((r) => setTimeout(r, 300 + attempt * 250));
            else throw e;
          }
        }
      }
      if (typeof forgetDumpedItemsByContents === 'function') {
        forgetDumpedItemsByContents([entry.content], { includeStored: true });
      }
      if (typeof invalidateStoredItemsCache === 'function') {
        invalidateStoredItemsCache({
          ids: (hits || []).map((h) => h && h.id).filter(Boolean),
          contents: [entry.content]
        });
      }
      if (typeof updateBadge === 'function') updateBadge();
    }

    async function trashStoredItemMatchingHistory(entry) {
      return trashStoredDumpsMatchingHistory(entry);
    }

    function hasPendingHistoryReplaceJobs() {
      if (typeof getPendingInboxWrites !== 'function') return false;
      return getPendingInboxWrites().some((j) => j && j.type === 'history_replace' && j.pendingReplace);
    }

    function isPendingHistoryReplaceJob(job, historyId, content) {
      if (!job || job.type !== 'history_replace' || !job.pendingReplace) return false;
      // keepaliveSent でもジョブが残っている間は未完了扱い（閉じた瞬間の送出は完了保証がない）
      if (historyId != null && String(job.pendingReplace.id) === String(historyId)) return true;
      if (content && (
        dumpContentEquals(job.newContent, content)
        || dumpContentEquals(job.oldContent, content)
      )) return true;
      return false;
    }

    function hasPendingHistoryReplaceForId(historyId) {
      if (historyId == null || typeof getPendingInboxWrites !== 'function') return false;
      return getPendingInboxWrites().some((j) => isPendingHistoryReplaceJob(j, historyId));
    }

    function hasPendingHistoryReplaceForContent(content) {
      if (!content || typeof getPendingInboxWrites !== 'function') return false;
      return getPendingInboxWrites().some((j) => isPendingHistoryReplaceJob(j, null, content));
    }

    /**
     * INBOX／保存済み本体が新しいのに登録チェックが古い場合を治癒（他端末編集の取りこぼし対策）
     */
    function reconcileLocalHistoryWithDumpSources(organizerData) {
      if (typeof getLocalInputHistory !== 'function' || typeof cacheLocalInputHistory !== 'function') return false;
      const byDumpId = new Map();
      const pushDump = (row, isInbox) => {
        if (!row || row.id == null || typeof isTempId === 'function' && isTempId(row.id)) return;
        if (typeof isNonUserDumpItem === 'function' && isNonUserDumpItem(row)) return;
        const content = String(row.content || '').trim();
        if (!content) return;
        byDumpId.set(String(row.id), {
          content,
          isInbox: !!isInbox,
          folder: isInbox ? 'INBOX' : (row.folder || 'INBOX'),
          file: isInbox ? '未整理' : (row.file || '未整理'),
          timestamp: row.timestamp || ''
        });
      };
      const inbox = organizerData && Array.isArray(organizerData.inbox) ? organizerData.inbox : [];
      inbox.forEach((r) => pushDump(r, true));
      if (typeof mergePendingDumpsInto === 'function') {
        const cached = mergePendingDumpsInto((storedItemsCache && storedItemsCache.items) || []);
        (cached || []).forEach((r) => pushDump(r, !!(r && (r.isInbox || historyDestIsInbox(r.folder)))));
      } else if (storedItemsCache && Array.isArray(storedItemsCache.items)) {
        storedItemsCache.items.forEach((r) => pushDump(r, !!(r && (r.isInbox || historyDestIsInbox(r.folder)))));
      }
      if (!byDumpId.size) return false;

      let changed = false;
      const healCloud = [];
      const next = getLocalInputHistory().map((e) => {
        if (!e || !e.dumpId || (typeof isTempId === 'function' && isTempId(e.dumpId))) return e;
        if (hasPendingHistoryReplaceForId(e.id) || hasPendingHistoryReplaceForContent(e.content)) return e;
        const hit = byDumpId.get(String(e.dumpId));
        if (!hit || !hit.content) return e;
        if (dumpContentEquals(e.content, hit.content)) return e;
        // 同期前に閉じた編集: サーバーに旧本文が残っていても、旧本文は tombstone 済み。
        // ここに戻すと「新旧どちらも非表示」になるので治癒しない。
        const hitKey = dumpContentKey(hit.content);
        if (hitKey && (
          (typeof inputHistoryTombstoneKeys !== 'undefined' && inputHistoryTombstoneKeys.has(hitKey))
          || (typeof inputHistorySuppressedContents !== 'undefined' && inputHistorySuppressedContents.has(hitKey))
        )) {
          return e;
        }
        changed = true;
        healCloud.push({
          id: e.id,
          oldContent: e.content,
          newContent: hit.content,
          folder: e.folder || hit.folder,
          file: e.file || hit.file
        });
        return {
          ...e,
          content: hit.content,
          timestamp: new Date().toISOString(),
          dumpIsInbox: hit.isInbox
        };
      });
      if (!changed) return false;
      cacheLocalInputHistory(next);
      // 登録チェッククラウドも本体に合わせて直す（他端末へも届ける）
      if (healCloud.length && typeof replaceCloudInputHistoryEntry === 'function') {
        runInBackground(async () => {
          for (const item of healCloud) {
            try {
              await replaceCloudInputHistoryEntry(
                item.id,
                item.oldContent,
                item.newContent,
                item.folder,
                item.file,
                { skipPaint: true }
              );
            } catch (err) {
              console.warn('heal cloud history from dump failed', err);
            }
          }
        });
      }
      return true;
    }

    let inputHistoryCloudSyncChain = Promise.resolve();
    async function syncInputTabHistoryFromCloud(options) {
      options = options || {};
      const run = async () => {
        const force = !!options.force;
        if (typeof fetchCloudInputHistory !== 'function') return null;
        if (inputHistoryCloudSyncPaused > 0 || (typeof pendingHistoryLaneMoves !== 'undefined' && pendingHistoryLaneMoves.size > 0)) {
          // 編集同期中は prune せずローカルをそのまま描画（編集直後の行が消えないように）
          if (typeof paintInputTabHistory === 'function') {
            paintInputTabHistory(getLocalInputHistory(), { skipDupSchedule: true });
          }
          return getLocalInputHistory();
        }
        // 未同期の編集置き換えがある間はクラウドで上書きしない（閉じた直後の再起動で消えるのを防ぐ）
        if (typeof hasPendingHistoryReplaceJobs === 'function' && hasPendingHistoryReplaceJobs()) {
          if (typeof paintInputTabHistory === 'function') {
            paintInputTabHistory(getLocalInputHistory(), { skipDupSchedule: true });
          }
          return getLocalInputHistory();
        }
        // 削除同期中はクラウド再取得で一覧が揺れるのを避ける（強制同期以外）
        if (!force && typeof inputHistoryDeleteRunning === 'number' && inputHistoryDeleteRunning > 0) {
          if (typeof paintInputTabHistory === 'function') {
            paintInputTabHistory(getLocalInputHistory(), { skipDupSchedule: true });
          }
          return getLocalInputHistory();
        }
        // 未完了の削除同期を先に流す（他端末へ削除マーカーを届ける）
        if (typeof flushPendingInputHistoryDeletes === 'function') {
          try { await flushPendingInputHistoryDeletes({ silent: true }); } catch (e) {
            console.warn('flush pending history deletes', e);
          }
        }
        if (force && typeof invalidateCloudInputHistoryCache === 'function') {
          invalidateCloudInputHistoryCache();
        }
        const cloud = await fetchCloudInputHistory({ force });
        // fetch 待ちのあいだに編集が始まった場合はマージせずローカル優先
        if (inputHistoryCloudSyncPaused > 0 || (typeof pendingHistoryLaneMoves !== 'undefined' && pendingHistoryLaneMoves.size > 0)) {
          if (typeof paintInputTabHistory === 'function') {
            paintInputTabHistory(getLocalInputHistory(), { skipDupSchedule: true });
          }
          return getLocalInputHistory();
        }
        if (!cloud) return null;
        const merged = mergeLocalAndCloudHistory(cloud);
        // 検索にはあるが登録チェックに無いダンプを履歴へ戻す
        try {
          if (typeof backfillInputHistoryFromLiveDumps === 'function') {
            await backfillInputHistoryFromLiveDumps({ forceStored: !!force });
          }
        } catch (e) {
          console.warn('backfill input history from dumps', e);
        }
        const next = typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : merged;
        paintInputTabHistory(next);
        return next;
      };
      // 並行同期で merge が復活行を上書きしないよう直列化
      const next = inputHistoryCloudSyncChain.then(run, run);
      inputHistoryCloudSyncChain = next.then(() => { }, () => { });
      return next;
    }

    function renderInputTabHistory(options) {
      options = options || {};
      const local = typeof pruneStaleLocalInputHistory === 'function'
        ? pruneStaleLocalInputHistory()
        : (typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : []);
      // CAPTURE オープン時は必ず描画（初期「読み込み中...」放置／スキップ事故を防ぐ）
      paintInputTabHistory(local, { force: true, skipDupSchedule: !!options.skipDupSchedule });
      if (!options.skipCloudSync) {
        runInBackground(() => syncInputTabHistoryFromCloud({ force: true }));
      }
    }

    async function migrateDraftsToInbox() {
      if (localStorage.getItem('drafts_to_inbox_migrated') === 'true') return;
      try {
        const contents = [];
        let cloudItems = [];
        const cloudRes = await callAPI('getFolderFileItems', { folder: '__SYSTEM__', file: 'drafts' }, { silent: true });
        if (Array.isArray(cloudRes) && cloudRes.length > 0) {
          cloudItems = cloudRes;
          cloudItems.forEach((item) => {
            if (item && item.content && String(item.content).trim()) {
              contents.push(String(item.content).trim());
            }
          });
        }

        const localDraftsStr = localStorage.getItem('dump_drafts');
        if (localDraftsStr) {
          try {
            const localDrafts = JSON.parse(localDraftsStr);
            if (Array.isArray(localDrafts)) {
              localDrafts.forEach((content) => {
                if (content && typeof content === 'string' && content.trim()) {
                  contents.push(content.trim());
                }
              });
            }
          } catch (e) { /* ignore */ }
        }

        if (contents.length > 0) {
          const writeRes = await callAPI('addManyInbox', { contents }, { silent: true });
          if (writeRes && writeRes.error) throw new Error('inbox write failed');
          if (typeof logInputHistory === 'function') {
            logInputHistory(contents, 'INBOX', '未整理');
          }
          updateBadge();
        }

        // 書き込み成功後に drafts を削除
        const ids = cloudItems.map((item) => item && item.id).filter(Boolean);
        if (ids.length > 0) {
          await callAPI('deleteDataRecords', { ids }, { silent: true });
        }
        localStorage.removeItem('dump_drafts');
        localStorage.setItem('drafts_to_inbox_migrated', 'true');
      } catch (e) {
        console.error('Failed to migrate drafts to inbox', e);
      }
    }
    function loadStats(options) {
      options = options || {};
      if (!options.skipFetch) {
        fetchOrganizerDataShared({ silent: true }).then((data) => {
          applyOrganizerData(data);
        });
      }
      const lastDump = localStorage.getItem('lastDumpTime');
      if (lastDump) {
        const diffMs = new Date() - new Date(lastDump);
        const diffMins = Math.floor(diffMs / 60000);
        let timeText = "Just now";
        if (diffMins > 0 && diffMins < 60) timeText = diffMins + " mins ago";
        else if (diffMins >= 60 && diffMins < 24 * 60) timeText = Math.floor(diffMins / 60) + " hrs ago";
        else if (diffMins >= 24 * 60) timeText = Math.floor(diffMins / (24 * 60)) + " days ago";
        const lastEl = document.getElementById('stat-last-dump');
        if (lastEl) lastEl.textContent = timeText;
      } else {
        const lastEl = document.getElementById('stat-last-dump');
        if (lastEl) lastEl.textContent = "-";
      }
      updateDumpDepthDisplay();
    }

    const DUMP_VOLUME_KEY = 'dump_lifetime_volume';
    const DUMP_DEPTH_TIERS = [
      { min: 0, key: 'surface', label: '表層', meters: 3 },
      { min: 8, key: 'shoal', label: '浅瀬', meters: 18 },
      { min: 30, key: 'mid', label: '中層', meters: 55 },
      { min: 90, key: 'deep', label: '深層', meters: 140 },
      { min: 250, key: 'abyss', label: '深海', meters: 420 },
      { min: 600, key: 'trench', label: '海溝', meters: 1100 },
      { min: 1500, key: 'hadal', label: 'アビス', meters: 3800 }
    ];

    function getDumpVolumeState() {
      try {
        const raw = JSON.parse(localStorage.getItem(DUMP_VOLUME_KEY) || '{}');
        return {
          pieces: Math.max(0, Math.round(Number(raw.pieces) || 0)),
          chars: Math.max(0, Math.round(Number(raw.chars) || 0)),
          seeded: !!raw.seeded
        };
      } catch (e) {
        return { pieces: 0, chars: 0, seeded: false };
      }
    }

    function saveDumpVolumeState(state) {
      try {
        localStorage.setItem(DUMP_VOLUME_KEY, JSON.stringify({
          pieces: Math.max(0, Math.round(Number(state.pieces) || 0)),
          chars: Math.max(0, Math.round(Number(state.chars) || 0)),
          seeded: !!state.seeded
        }));
      } catch (e) { }
    }

    function seedDumpVolumeFromLocalIfNeeded() {
      const state = getDumpVolumeState();
      let pieces = 0;
      let chars = 0;
      try {
        if (typeof getLocalInputHistory === 'function') {
          const hist = getLocalInputHistory() || [];
          hist.forEach((e) => {
            if (!e || !e.content) return;
            pieces += 1;
            chars += String(e.content).length;
          });
        }
      } catch (e) { }
      if (!state.seeded) {
        state.pieces = Math.max(state.pieces, pieces);
        state.chars = Math.max(state.chars, chars);
        if (typeof getLocalInputHistory === 'function') state.seeded = true;
      } else if (pieces > 0 && state.pieces === 0 && state.chars === 0) {
        // 起動直後に空でシードされた場合の救済
        state.pieces = pieces;
        state.chars = chars;
      }
      saveDumpVolumeState(state);
      return state;
    }

    function computeDumpDepthInfo(state) {
      const pieces = state && state.pieces ? state.pieces : 0;
      const chars = state && state.chars ? state.chars : 0;
      const score = pieces + Math.floor(chars / 180);
      let tier = DUMP_DEPTH_TIERS[0];
      let tierIdx = 0;
      for (let i = 0; i < DUMP_DEPTH_TIERS.length; i++) {
        if (score >= DUMP_DEPTH_TIERS[i].min) {
          tier = DUMP_DEPTH_TIERS[i];
          tierIdx = i;
        }
      }
      const next = DUMP_DEPTH_TIERS[tierIdx + 1];
      let meters = tier.meters;
      if (next) {
        const span = Math.max(1, next.min - tier.min);
        const prog = Math.max(0, Math.min(1, (score - tier.min) / span));
        meters = Math.round(tier.meters + (next.meters - tier.meters) * prog);
      } else {
        meters = Math.round(tier.meters + Math.min(2200, (score - tier.min) * 1.8));
      }
      return { score, tier, meters, pieces, chars };
    }

    function updateDumpDepthDisplay() {
      const state = seedDumpVolumeFromLocalIfNeeded();
      const info = computeDumpDepthInfo(state);
      const depthEl = document.getElementById('stat-dump-depth');
      const labelEl = document.getElementById('stat-dump-depth-label');
      const tagEl = document.getElementById('portal-depth-tag');
      const ring = document.querySelector('.dump-portal-ring');
      if (depthEl) depthEl.textContent = info.meters.toLocaleString() + 'm';
      if (labelEl) labelEl.textContent = info.tier.label;
      if (tagEl) tagEl.textContent = 'DEPTH · ' + info.tier.label;
      if (ring) ring.setAttribute('data-dump-depth', info.tier.key);
      const portal = document.getElementById('portal-container');
      if (portal) {
        portal.setAttribute('data-dump-depth', info.tier.key);
        portal.style.setProperty('--dump-depth-level', String(Math.max(0, Math.min(1, info.score / 1500))));
      }
      return info;
    }

    function recordDumpVolume(chunks) {
      const list = (chunks || []).map((c) => String(c || '')).filter((c) => c.trim());
      if (!list.length) return null;
      const state = seedDumpVolumeFromLocalIfNeeded();
      state.pieces += list.length;
      state.chars += list.reduce((n, c) => n + c.length, 0);
      saveDumpVolumeState(state);
      return updateDumpDepthDisplay();
    }

    // ========== ガント ==========
    const GANTT_FOLDER = '__SYSTEM__';
    const GANTT_FILE = 'gantt';
    const GANTT_CACHE_KEY = 'gantt_tasks_v1';
    const GANTT_UPDATED_AT_KEY = 'gantt_updated_at';
    const GANTT_DIRTY_KEY = 'gantt_dirty';
    const GANTT_VIEW_DAYS = 21;
    const GANTT_DAY_W = 36;
    const GANTT_LABEL_W = 108;
    const GANTT_COLORS = ['#22d3ee', '#34d399', '#a78bfa', '#fbbf24', '#fb7185', '#60a5fa'];

    let ganttTasks = [];
    let ganttViewStart = '';
    let ganttDirty = false;
    try { ganttDirty = localStorage.getItem(GANTT_DIRTY_KEY) === '1'; } catch (e) { }
    let ganttSyncing = false;
    let ganttSyncPromise = null;
    let ganttCloudTimer = null;
    let ganttLocalEditGen = 0;
    let ganttLastLocalEditAt = 0;
    const GANTT_EDIT_GRACE_MS = 6000;

    function ganttPad2(n) {
      return String(n).padStart(2, '0');
    }
    function formatJaDateLabel(dateStr) {
      if (!dateStr) return '';
      const [y, m, d] = String(dateStr).split('-').map(Number);
      if (!y || !m || !d) return dateStr;
      const week = ['日', '月', '火', '水', '木', '金', '土'];
      const dt = new Date(y, m - 1, d);
      return `${y}年${m}月${d}日（${week[dt.getDay()]}）`;
    }
    function ganttTodayStr() {
      const d = new Date();
      return d.getFullYear() + '-' + ganttPad2(d.getMonth() + 1) + '-' + ganttPad2(d.getDate());
    }
    function ganttParseDate(str) {
      const m = String(str || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
      if (!m) return null;
      const dt = new Date(+m[1], +m[2] - 1, +m[3]);
      return Number.isNaN(dt.getTime()) ? null : dt;
    }
    function ganttDateToStr(dt) {
      return dt.getFullYear() + '-' + ganttPad2(dt.getMonth() + 1) + '-' + ganttPad2(dt.getDate());
    }
    function ganttAddDays(dateStr, days) {
      const dt = ganttParseDate(dateStr);
      if (!dt) return ganttTodayStr();
      dt.setDate(dt.getDate() + days);
      return ganttDateToStr(dt);
    }
    function ganttDiffDays(aStr, bStr) {
      const a = ganttParseDate(aStr);
      const b = ganttParseDate(bStr);
      if (!a || !b) return 0;
      return Math.round((b.getTime() - a.getTime()) / 86400000);
    }
    function ganttMondayOf(dateStr) {
      const dt = ganttParseDate(dateStr) || new Date();
      const day = dt.getDay();
      const offset = day === 0 ? -6 : 1 - day;
      dt.setDate(dt.getDate() + offset);
      return ganttDateToStr(dt);
    }
    function ganttNewId() {
      return 'g' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    }
    function normalizeGanttTask(raw, i) {
      if (!raw || typeof raw !== 'object') return null;
      const title = String(raw.title || '').trim().slice(0, 60);
      let start = String(raw.start || '').slice(0, 10);
      let end = String(raw.end || '').slice(0, 10);
      if (!ganttParseDate(start)) start = ganttTodayStr();
      if (!ganttParseDate(end)) end = start;
      if (end < start) { const t = start; start = end; end = t; }
      const color = String(raw.color || GANTT_COLORS[(i || 0) % GANTT_COLORS.length]);
      return {
        id: String(raw.id || ganttNewId()),
        title: title || '無題',
        start,
        end,
        color,
        done: !!raw.done,
        googleEventId: raw.googleEventId ? String(raw.googleEventId) : ''
      };
    }
    function normalizeGanttTasks(list) {
      return (Array.isArray(list) ? list : []).map(normalizeGanttTask).filter(Boolean)
        .sort((a, b) => (a.start + a.title).localeCompare(b.start + b.title));
    }
    function ganttNoteLocalEdit() {
      ganttLocalEditGen += 1;
      ganttLastLocalEditAt = Date.now();
      ganttDirty = true;
      try { localStorage.setItem(GANTT_DIRTY_KEY, '1'); } catch (e) { }
    }
    function ganttShouldProtectLocal() {
      if (ganttDirty) return true;
      if (ganttLocalEditGen > 0 && (Date.now() - ganttLastLocalEditAt) < GANTT_EDIT_GRACE_MS) return true;
      return false;
    }
    function ganttClearDirty() {
      ganttDirty = false;
      try { localStorage.removeItem(GANTT_DIRTY_KEY); } catch (e) { }
    }
    function loadGanttCache() {
      try {
        const raw = JSON.parse(localStorage.getItem(GANTT_CACHE_KEY) || '[]');
        return normalizeGanttTasks(raw);
      } catch (e) {
        return [];
      }
    }
    function saveGanttCache(tasks, opts) {
      opts = opts || {};
      const next = normalizeGanttTasks(tasks);
      ganttTasks = next;
      try {
        localStorage.setItem(GANTT_CACHE_KEY, JSON.stringify(next));
        if (opts.touch !== false) {
          localStorage.setItem(GANTT_UPDATED_AT_KEY, new Date().toISOString());
          ganttNoteLocalEdit();
          if (opts.queueCloud !== false) queueGanttCloudSync();
        }
      } catch (e) { }
      return next;
    }
    function ganttLocalUpdatedAtMs() {
      const t = new Date(localStorage.getItem(GANTT_UPDATED_AT_KEY) || 0).getTime();
      return Number.isFinite(t) ? t : 0;
    }
    let ganttStoreReady = false;
    async function ensureGanttStore() {
      if (ganttStoreReady) return;
      await callAPI('addConfigRecord', { folder: GANTT_FOLDER, file: GANTT_FILE }, { silent: true });
      ganttStoreReady = true;
    }
    function parseGanttSnapshot(row) {
      if (!row || row.content == null) return null;
      try {
        const payload = JSON.parse(row.content);
        const tasks = normalizeGanttTasks(payload && payload.tasks);
        const updatedAt = new Date(payload && payload.updatedAt).getTime();
        if (!Number.isFinite(updatedAt)) return null;
        return {
          cloudId: row.id != null ? String(row.id) : '',
          tasks,
          updatedAt,
          updatedAtIso: new Date(updatedAt).toISOString()
        };
      } catch (e) {
        return null;
      }
    }
    async function fetchCloudGanttSnapshot() {
      const items = await callAPI('getFolderFileItems', {
        folder: GANTT_FOLDER,
        file: GANTT_FILE
      }, { silent: true });
      if (!Array.isArray(items) || !items.length) return null;
      const list = items.map(parseGanttSnapshot).filter(Boolean)
        .sort((a, b) => b.updatedAt - a.updatedAt);
      if (!list.length) return null;
      list[0].extraIds = list.slice(1).map((x) => x.cloudId).filter(Boolean);
      return list[0];
    }
    function applyGanttFromCloud(tasks, updatedAtIso) {
      if (ganttShouldProtectLocal()) return false;
      ganttTasks = normalizeGanttTasks(tasks);
      try {
        localStorage.setItem(GANTT_CACHE_KEY, JSON.stringify(ganttTasks));
        if (updatedAtIso) localStorage.setItem(GANTT_UPDATED_AT_KEY, updatedAtIso);
      } catch (e) { }
      ganttClearDirty();
      return true;
    }
    async function publishGanttLibrary(prefetched) {
      await ensureGanttStore();
      if (!ganttTasks.length) ganttTasks = loadGanttCache();
      let localUpdatedAt = ganttLocalUpdatedAtMs();
      if (!localUpdatedAt) {
        const nowIso = new Date().toISOString();
        localStorage.setItem(GANTT_UPDATED_AT_KEY, nowIso);
        localUpdatedAt = new Date(nowIso).getTime();
      }
      const existing = prefetched === undefined ? await fetchCloudGanttSnapshot() : prefetched;
      if (existing && existing.updatedAt > localUpdatedAt && !ganttShouldProtectLocal()) {
        if (applyGanttFromCloud(existing.tasks, existing.updatedAtIso)) renderGanttAll();
        return;
      }
      const updatedAt = new Date(Math.max(localUpdatedAt, Date.now())).toISOString();
      localStorage.setItem(GANTT_UPDATED_AT_KEY, updatedAt);
      const payload = JSON.stringify({ v: 1, updatedAt, tasks: ganttTasks });
      try {
        await upsertSystemSnapshotRecord({
          cloudId: existing && existing.cloudId,
          extraIds: existing && existing.extraIds,
          folder: GANTT_FOLDER,
          file: GANTT_FILE,
          content: payload
        });
      } catch (_) {
        throw new Error('gantt_sync');
      }
      ganttClearDirty();
    }
    function queueGanttCloudSync() {
      if (ganttCloudTimer) clearTimeout(ganttCloudTimer);
      ganttCloudTimer = setTimeout(() => {
        publishGanttLibrary().catch(() => { });
      }, 280);
    }
    async function syncGanttLibrary(options) {
      options = options || {};
      const wantRender = options.render !== false;
      if (ganttSyncPromise) {
        try { await ganttSyncPromise; } catch (_) { }
        if (wantRender) renderGanttAll();
        return ganttTasks;
      }
      ganttSyncing = true;
      ganttSyncPromise = (async () => {
        if (!ganttTasks.length) ganttTasks = loadGanttCache();
        const startGen = ganttLocalEditGen;
        let cloud = null;
        try { cloud = await fetchCloudGanttSnapshot(); } catch (_) { cloud = null; }
        const editedDuringFetch = ganttLocalEditGen !== startGen;
        if (ganttShouldProtectLocal() || editedDuringFetch) {
          if (ganttDirty || editedDuringFetch) {
            try { await publishGanttLibrary(cloud); } catch (_) { }
          }
          return ganttTasks;
        }
        const localUpdatedAt = ganttLocalUpdatedAtMs();
        if (cloud && cloud.updatedAt > localUpdatedAt) {
          if (applyGanttFromCloud(cloud.tasks, cloud.updatedAtIso) && wantRender) renderGanttAll();
        } else if (ganttDirty || (!cloud && ganttTasks.length)) {
          await publishGanttLibrary(cloud);
        } else if (!cloud) {
          ensureGanttStore().catch(() => { });
        }
        return ganttTasks;
      })();
      try {
        await ganttSyncPromise;
        if (wantRender) renderGanttAll();
        return ganttTasks;
      } catch (e) {
        return ganttTasks;
      } finally {
        ganttSyncPromise = null;
        ganttSyncing = false;
      }
    }
    function setGanttSyncStatus(text, cls) {
      const el = document.getElementById('gantt-sync-status');
      if (!el) return;
      el.textContent = text || '';
      el.className = 'text-[10px] font-bold min-h-[14px] ' + (cls || 'text-cyan-600/80');
    }
    function initGanttMode() {
      ganttTasks = loadGanttCache();
      if (!ganttViewStart) ganttViewStart = ganttMondayOf(ganttTodayStr());
      const startEl = document.getElementById('gantt-new-start');
      const endEl = document.getElementById('gantt-new-end');
      const today = ganttTodayStr();
      if (startEl && !startEl.value) startEl.value = today;
      if (endEl && !endEl.value) endEl.value = ganttAddDays(today, 2);
      const gcalToggle = document.getElementById('gantt-gcal-sync-toggle');
      if (gcalToggle) gcalToggle.checked = isGanttGCalSyncEnabled();
      renderGanttAll();
      renderGanttTodoCandidates();
      setGanttSyncStatus('同期中…');
      runInBackground(async () => {
        try {
          if (typeof syncInputTabHistoryFromCloud === 'function') {
            syncInputTabHistoryFromCloud().then(() => {
              renderGanttTodoCandidates();
            }).catch(() => { });
          }
          await syncGanttLibrary({ render: true });
          setGanttSyncStatus('同期済み', 'text-emerald-500/80');
          setTimeout(() => setGanttSyncStatus(''), 1600);
        } catch (_) {
          setGanttSyncStatus('オフライン（端末のみ）', 'text-amber-400/90');
        }
      });
    }
    function jumpGanttToToday() {
      ganttViewStart = ganttMondayOf(ganttTodayStr());
      renderGanttChart();
    }
    function shiftGanttView(days) {
      if (!ganttViewStart) ganttViewStart = ganttMondayOf(ganttTodayStr());
      ganttViewStart = ganttAddDays(ganttViewStart, days);
      renderGanttChart();
    }
    function renderGanttAll() {
      renderGanttChart();
      renderGanttTaskList();
      renderGanttTodoCandidates();
    }
    function renderGanttChart() {
      const chart = document.getElementById('gantt-chart');
      const labelEl = document.getElementById('gantt-range-label');
      if (!chart) return;
      if (!ganttViewStart) ganttViewStart = ganttMondayOf(ganttTodayStr());
      const days = [];
      for (let i = 0; i < GANTT_VIEW_DAYS; i++) days.push(ganttAddDays(ganttViewStart, i));
      const viewEnd = days[days.length - 1];
      if (labelEl) {
        labelEl.textContent = formatJaDateLabel(ganttViewStart) + ' 〜 ' + formatJaDateLabel(viewEnd);
      }
      const today = ganttTodayStr();
      const width = GANTT_LABEL_W + days.length * GANTT_DAY_W;
      const headCells = days.map((d) => {
        const dt = ganttParseDate(d);
        const isToday = d === today;
        const isSun = dt && dt.getDay() === 0;
        const isSat = dt && dt.getDay() === 6;
        let cls = 'gantt-day-head';
        if (isToday) cls += ' is-today';
        if (isSun) cls += ' is-sun';
        if (isSat) cls += ' is-sat';
        return '<div class="' + cls + '" style="width:' + GANTT_DAY_W + 'px">'
          + (dt ? (dt.getMonth() + 1) + '/' + dt.getDate() : '') + '</div>';
      }).join('');

      const sorted = normalizeGanttTasks(ganttTasks);
      let body = '';
      if (!sorted.length) {
        body = '<div class="gantt-empty">タスクがありません。下のフォームから追加できます。</div>';
      } else {
        body = sorted.map((task) => {
          const startOff = ganttDiffDays(ganttViewStart, task.start);
          const endOff = ganttDiffDays(ganttViewStart, task.end);
          const barStart = Math.max(0, startOff);
          const barEnd = Math.min(GANTT_VIEW_DAYS - 1, endOff);
          const visible = barEnd >= 0 && barStart < GANTT_VIEW_DAYS;
          let barHtml = '';
          if (visible) {
            const left = GANTT_LABEL_W + barStart * GANTT_DAY_W + 3;
            const w = Math.max(GANTT_DAY_W - 6, (barEnd - barStart + 1) * GANTT_DAY_W - 6);
            barHtml = '<button type="button" class="gantt-bar' + (task.done ? ' is-done' : '')
              + '" style="left:' + left + 'px;width:' + w + 'px;background:' + task.color
              + '" data-id="' + escapeHtmlText(task.id) + '" title="'
              + escapeHtmlText(task.title + '（' + task.start + '〜' + task.end + '）') + '">'
              + escapeHtmlText(task.title) + '</button>';
          }
          const grid = days.map((d) => {
            let cls = 'gantt-day-cell';
            if (d === today) cls += ' is-today';
            return '<div class="' + cls + '" style="width:' + GANTT_DAY_W + 'px"></div>';
          }).join('');
          return '<div class="gantt-row' + (task.done ? ' is-done' : '') + '" data-id="'
            + escapeHtmlText(task.id) + '">'
            + '<button type="button" class="gantt-row-label" data-id="' + escapeHtmlText(task.id) + '">'
            + escapeHtmlText(task.title) + '</button>'
            + '<div class="gantt-row-track" style="width:' + (days.length * GANTT_DAY_W) + 'px">' + grid + '</div>'
            + barHtml + '</div>';
        }).join('');
      }

      chart.style.minWidth = width + 'px';
      chart.innerHTML = '<div class="gantt-head" style="width:' + width + 'px">'
        + '<div class="gantt-corner" style="width:' + GANTT_LABEL_W + 'px">タスク</div>'
        + headCells + '</div><div class="gantt-body">' + body + '</div>';

      chart.querySelectorAll('.gantt-bar, .gantt-row-label').forEach((el) => {
        el.addEventListener('click', (ev) => {
          ev.preventDefault();
          const id = el.getAttribute('data-id');
          if (id) focusGanttTaskInList(id);
        });
      });
    }
    function focusGanttTaskInList(id) {
      const row = document.querySelector('#gantt-task-list .gantt-list-item[data-id="' + id + '"]');
      if (!row) return;
      try { row.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); } catch (_) { }
      const titleInput = row.querySelector('.gantt-list-title-input');
      if (titleInput) {
        try { titleInput.focus(); titleInput.select(); } catch (_) { }
      }
    }

    function updateGanttTaskField(id, field, value) {
      const task = ganttTasks.find((t) => t.id === id);
      if (!task) return;
      const patch = { ...task };
      if (field === 'title') {
        const nextTitle = String(value || '').trim().slice(0, 60);
        if (!nextTitle) {
          alert('名前を空にはできません');
          renderGanttTaskList();
          return;
        }
        if (nextTitle === task.title) return;
        patch.title = nextTitle;
      } else if (field === 'start' || field === 'end') {
        const next = String(value || '').slice(0, 10);
        if (!ganttParseDate(next)) {
          alert('日付の形式が不正です');
          renderGanttTaskList();
          return;
        }
        if (next === task[field]) return;
        patch[field] = next;
      } else {
        return;
      }
      const updated = normalizeGanttTask(patch);
      if (!updated) {
        alert('日付の形式が不正です');
        renderGanttTaskList();
        return;
      }
      saveGanttCache(ganttTasks.map((t) => t.id === id ? updated : t));
      renderGanttAll();
      setGanttSyncStatus('保存しました', 'text-emerald-500/80');
      if (isGanttGCalSyncEnabled()) {
        syncTaskToGCal(updated);
      }
    }

    function renderGanttTaskList() {
      const list = document.getElementById('gantt-task-list');
      if (!list) return;
      const active = document.activeElement;
      const keepFocus = active && list.contains(active)
        ? {
          id: active.getAttribute('data-id') || (active.closest && active.closest('[data-id]') && active.closest('[data-id]').getAttribute('data-id')),
          field: active.getAttribute('data-field') || '',
          start: typeof active.selectionStart === 'number' ? active.selectionStart : null,
          end: typeof active.selectionEnd === 'number' ? active.selectionEnd : null
        }
        : null;
      const sorted = normalizeGanttTasks(ganttTasks);
      if (!sorted.length) {
        list.innerHTML = '<div class="text-center py-4 text-cyan-700/80 text-xs font-bold border border-dashed border-cyan-900/40 rounded-xl">まだタスクがありません</div>';
        return;
      }
      list.innerHTML = '';
      sorted.forEach((task) => {
        const row = document.createElement('div');
        row.className = 'gantt-list-item' + (task.done ? ' is-done' : '');
        row.setAttribute('data-id', task.id);

        const swatch = document.createElement('span');
        swatch.className = 'gantt-list-swatch';
        swatch.style.background = task.color;

        const titleInput = document.createElement('input');
        titleInput.type = 'text';
        titleInput.className = 'gantt-list-title-input';
        titleInput.maxLength = 60;
        titleInput.value = task.title;
        titleInput.setAttribute('list', 'gantt-todo-datalist');
        titleInput.setAttribute('data-id', task.id);
        titleInput.setAttribute('data-field', 'title');
        titleInput.setAttribute('aria-label', 'タスク名');
        titleInput.onchange = () => updateGanttTaskField(task.id, 'title', titleInput.value);
        titleInput.onkeydown = (ev) => {
          if (ev.key === 'Enter') {
            ev.preventDefault();
            titleInput.blur();
          }
        };

        const actions = document.createElement('div');
        actions.className = 'gantt-list-actions items-center';
        if (task.googleEventId) {
          const calBadge = document.createElement('span');
          calBadge.className = 'text-xs select-none cursor-default px-0.5';
          calBadge.title = 'Googleカレンダー連携済み';
          calBadge.textContent = '📅';
          actions.appendChild(calBadge);
        }
        const doneBtn = document.createElement('button');
        doneBtn.type = 'button';
        doneBtn.className = 'gantt-list-action';
        doneBtn.textContent = task.done ? '未完' : '完了';
        doneBtn.onclick = () => toggleGanttTaskDone(task.id);
        const delBtn = document.createElement('button');
        delBtn.type = 'button';
        delBtn.className = 'gantt-list-action is-danger';
        delBtn.textContent = '削除';
        delBtn.onclick = () => deleteGanttTask(task.id);
        actions.appendChild(doneBtn);
        actions.appendChild(delBtn);

        const dates = document.createElement('div');
        dates.className = 'gantt-list-dates-row';
        [['start', '開始'], ['end', '終了']].forEach(([field, label]) => {
          const wrap = document.createElement('label');
          wrap.className = 'gantt-list-date-field';
          const caption = document.createElement('span');
          caption.textContent = label;
          const input = document.createElement('input');
          input.type = 'date';
          input.className = 'gantt-list-date-input';
          input.value = task[field];
          input.setAttribute('data-id', task.id);
          input.setAttribute('data-field', field);
          input.setAttribute('aria-label', label + '日');
          input.onchange = () => updateGanttTaskField(task.id, field, input.value);
          wrap.appendChild(caption);
          wrap.appendChild(input);
          dates.appendChild(wrap);
        });

        row.appendChild(swatch);
        row.appendChild(titleInput);
        row.appendChild(actions);
        row.appendChild(dates);
        list.appendChild(row);
      });

      if (keepFocus && keepFocus.id && keepFocus.field) {
        const el = list.querySelector('[data-id="' + keepFocus.id + '"][data-field="' + keepFocus.field + '"]');
        if (el) {
          try {
            el.focus();
            if (keepFocus.start != null && typeof el.setSelectionRange === 'function') {
              el.setSelectionRange(keepFocus.start, keepFocus.end != null ? keepFocus.end : keepFocus.start);
            }
          } catch (_) { }
        }
      }
    }
    function scrollGanttToTop() {
      requestAnimationFrame(() => {
        setTimeout(() => {
          try {
            const chartWrap = document.getElementById('gantt-chart-wrap');
            if (chartWrap) {
              chartWrap.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
            }
            window.scrollTo({ top: 0, behavior: 'smooth' });
            const ganttMode = document.getElementById('gantt-mode');
            if (ganttMode && ganttMode.scrollTop > 0) {
              ganttMode.scrollTo({ top: 0, behavior: 'smooth' });
            }
          } catch (_) {
            window.scrollTo(0, 0);
          }
        }, 80);
      });
    }

    function addGanttTaskFromForm() {
      const titleEl = document.getElementById('gantt-new-title');
      const startEl = document.getElementById('gantt-new-start');
      const endEl = document.getElementById('gantt-new-end');
      const title = String(titleEl && titleEl.value || '').trim().slice(0, 60);
      const start = String(startEl && startEl.value || '').slice(0, 10);
      const end = String(endEl && endEl.value || '').slice(0, 10);
      if (!title) {
        alert('タスク名を入力してください');
        return;
      }
      if (!ganttParseDate(start) || !ganttParseDate(end)) {
        alert('開始日と終了日を指定してください');
        return;
      }
      const task = normalizeGanttTask({
        id: ganttNewId(),
        title,
        start,
        end,
        color: GANTT_COLORS[ganttTasks.length % GANTT_COLORS.length],
        done: false
      });
      saveGanttCache(ganttTasks.concat([task]));
      if (titleEl) {
        titleEl.value = '';
        try { titleEl.blur(); } catch (_) { }
      }
      if (startEl) {
        try { startEl.blur(); } catch (_) { }
      }
      if (endEl) {
        try { endEl.blur(); } catch (_) { }
      }

      // 追加したタスクの開始日が表示範囲外なら、その週へ自動ジャンプ
      if (!ganttViewStart) ganttViewStart = ganttMondayOf(ganttTodayStr());
      const startDiff = ganttDiffDays(ganttViewStart, task.start);
      if (startDiff < 0 || startDiff >= GANTT_VIEW_DAYS) {
        ganttViewStart = ganttMondayOf(task.start);
      }

      renderGanttAll();
      scrollGanttToTop();
      setGanttSyncStatus('保存しました', 'text-emerald-500/80');

      if (isGanttGCalSyncEnabled()) {
        setGanttSyncStatus('📅 Googleカレンダーに同期中…', 'text-sky-400 font-bold');
        syncTaskToGCal(task).then((res) => {
          if (res && res.success) {
            setGanttSyncStatus('📅 Googleカレンダーに反映しました', 'text-sky-400 font-bold');
            setTimeout(() => setGanttSyncStatus(''), 2500);
          } else {
            setGanttSyncStatus('カレンダー同期失敗: ' + formatGanttGCalError(res), 'text-amber-400 font-bold');
            setTimeout(() => setGanttSyncStatus(''), 5000);
          }
        });
      }
    }
    function toggleGanttTaskDone(id) {
      const next = ganttTasks.map((t) => t.id === id ? { ...t, done: !t.done } : t);
      saveGanttCache(next);
      renderGanttAll();
      if (isGanttGCalSyncEnabled()) {
        const updated = next.find((t) => t.id === id);
        if (updated) syncTaskToGCal(updated);
      }
    }
    function deleteGanttTask(id) {
      const task = ganttTasks.find((t) => t.id === id);
      if (!task) return;
      if (!confirm('「' + task.title + '」を削除しますか？')) return;
      if (isGanttGCalSyncEnabled() && task.googleEventId) {
        deleteTaskFromGCal(task.googleEventId);
      }
      saveGanttCache(ganttTasks.filter((t) => t.id !== id));
      renderGanttAll();
    }
    function editGanttTask(id) {
      focusGanttTaskInList(id);
    }
    window.focusGanttTaskInList = focusGanttTaskInList;
    window.updateGanttTaskField = updateGanttTaskField;

    const GANTT_GCAL_SYNC_KEY = 'gantt_gcal_sync';

    function isGanttGCalSyncEnabled() {
      try {
        return localStorage.getItem(GANTT_GCAL_SYNC_KEY) === '1';
      } catch (_) {
        return false;
      }
    }

    function setGanttGCalSyncEnabled(val) {
      try {
        localStorage.setItem(GANTT_GCAL_SYNC_KEY, val ? '1' : '0');
      } catch (_) { }
    }

    function formatGanttGCalError(err) {
      const raw = err == null ? '' : String(err.message || err.error || err);
      if (!raw) return 'カレンダー同期に失敗しました';
      if (/permission|Required permissions|Authorization|権限が未許可|authorizeGanttCalendar/i.test(raw)) {
        return 'カレンダー権限が未許可です。GASで authorizeGanttCalendar を実行して許可してください';
      }
      return raw.length > 120 ? raw.slice(0, 120) + '…' : raw;
    }

    async function syncTaskToGCal(task) {
      if (!task || !task.title) return null;
      try {
        const res = await callAPI('syncGanttCalendarEvent', { task }, { silent: true });
        if (res && res.success && res.googleEventId) {
          task.googleEventId = res.googleEventId;
          ganttTasks = ganttTasks.map((t) => t.id === task.id ? { ...t, googleEventId: res.googleEventId } : t);
          saveGanttCache(ganttTasks, { rawCloud: true });
          renderGanttTaskList();
        }
        return res;
      } catch (err) {
        console.warn('syncTaskToGCal failed:', err);
        return null;
      }
    }

    async function deleteTaskFromGCal(googleEventId) {
      if (!googleEventId) return;
      try {
        await callAPI('deleteGanttCalendarEvent', { googleEventId }, { silent: true });
      } catch (err) {
        console.warn('deleteTaskFromGCal failed:', err);
      }
    }

    async function syncAllGanttTasksToGCal() {
      if (!ganttTasks.length) {
        setGanttSyncStatus('同期するタスクがありません', 'text-amber-400/90');
        setTimeout(() => setGanttSyncStatus(''), 2000);
        return;
      }
      setGanttSyncStatus('📅 Googleカレンダーに同期中…', 'text-sky-400 font-bold');
      const btn = document.getElementById('gantt-gcal-sync-all-btn');
      if (btn) btn.disabled = true;
      try {
        const res = await callAPI('syncAllGanttToCalendar', { tasks: ganttTasks }, { silent: true });
        const results = (res && Array.isArray(res.results)) ? res.results : [];
        const map = {};
        let okCount = 0;
        results.forEach((r) => {
          if (r && r.id && r.success && r.googleEventId) {
            map[r.id] = r.googleEventId;
            okCount++;
          }
        });
        if (okCount > 0) {
          ganttTasks = ganttTasks.map((t) => {
            if (map[t.id]) return { ...t, googleEventId: map[t.id] };
            return t;
          });
          saveGanttCache(ganttTasks, { rawCloud: true });
          renderGanttTaskList();
        }
        const failCount = typeof res?.fail === 'number'
          ? res.fail
          : Math.max(0, results.length - okCount);
        if (okCount > 0 && failCount === 0) {
          setGanttSyncStatus(`📅 Googleカレンダーに同期しました（${okCount}件）`, 'text-emerald-400 font-bold');
          setTimeout(() => setGanttSyncStatus(''), 3000);
        } else if (okCount > 0) {
          setGanttSyncStatus(`📅 一部同期（成功${okCount} / 失敗${failCount}）`, 'text-amber-400 font-bold');
          setTimeout(() => setGanttSyncStatus(''), 4500);
        } else {
          setGanttSyncStatus('カレンダー同期エラー: ' + formatGanttGCalError(res && (res.error || results[0])), 'text-rose-400 font-bold');
          setTimeout(() => setGanttSyncStatus(''), 6000);
        }
      } catch (err) {
        setGanttSyncStatus('カレンダー同期通信エラー', 'text-rose-400 font-bold');
        setTimeout(() => setGanttSyncStatus(''), 3000);
      } finally {
        if (btn) btn.disabled = false;
      }
    }

    function toggleGanttGCalSync(enabled) {
      setGanttGCalSyncEnabled(enabled);
      const statusText = enabled ? 'Googleカレンダー自動連動: ON' : 'Googleカレンダー自動連動: OFF';
      setGanttSyncStatus(statusText, enabled ? 'text-sky-400 font-bold' : 'text-slate-400 font-bold');
      setTimeout(() => setGanttSyncStatus(''), 2500);
      if (enabled && ganttTasks.length) {
        syncAllGanttTasksToGCal();
      }
    }

    window.toggleGanttGCalSync = toggleGanttGCalSync;
    window.syncAllGanttTasksToGCal = syncAllGanttTasksToGCal;

    function extractGanttTodoTitle(raw) {
      if (!raw || typeof raw !== 'string') return '';
      const lines = raw.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
      if (!lines.length) return '';
      let line = lines[0];
      line = line.replace(/^[-*・■□▶︎▷\s]*(?:\[[ xX]?\])?\s*/, '').trim();
      line = line.replace(/^(\d+[.)]\s*)/, '').trim();
      if (/^!\[.*?\]\(.*?\)$/.test(line)) return '';
      if (/^https?:\/\/\S+$/i.test(line)) return '';
      return line.slice(0, 60);
    }

    function getGanttTodoCandidates() {
      const seen = new Set();
      const results = [];

      const addCandidate = (text) => {
        const title = extractGanttTodoTitle(text);
        if (!title) return;
        const key = title.toLowerCase();
        if (seen.has(key)) return;
        seen.add(key);
        results.push(title);
      };

      if (typeof pendingDumpCache !== 'undefined' && Array.isArray(pendingDumpCache)) {
        pendingDumpCache.forEach((p) => {
          if (!p || !p.content) return;
          const folder = String(p.destFolder || p.folder || '').trim();
          const lane = p.lane || (folder === 'やることリスト' ? 'todo' : '');
          if (lane === 'todo' || folder === 'やることリスト') {
            addCandidate(p.content);
          }
        });
      }

      if (typeof getLocalInputHistory === 'function') {
        const entries = getLocalInputHistory();
        const deduped = typeof dedupeInputHistoryEntriesByContent === 'function'
          ? dedupeInputHistoryEntriesByContent(entries)
          : (entries || []);
        const sorted = (deduped || []).slice().sort((a, b) => {
          const ta = typeof getSearchTimestampMs === 'function' ? getSearchTimestampMs(a) : new Date(a.timestamp || 0).getTime();
          const tb = typeof getSearchTimestampMs === 'function' ? getSearchTimestampMs(b) : new Date(b.timestamp || 0).getTime();
          return (tb || 0) - (ta || 0);
        });
        sorted.forEach((e) => {
          if (!e || !e.content) return;
          if (typeof isInputHistoryTombstoned === 'function' && isInputHistoryTombstoned(e)) return;
          if (typeof isUsableInputHistoryContent === 'function' && !isUsableInputHistoryContent(e.content)) return;
          const lane = (typeof historyEntryLane === 'function' ? historyEntryLane(e) : '') || e.lane;
          const folder = String(e.destFolder || e.folder || '').replace(/^📥\s*/, '').trim();
          if (lane === 'todo' || folder === 'やることリスト') {
            addCandidate(e.content);
          }
        });
      }

      if (typeof storedItemsCache !== 'undefined' && Array.isArray(storedItemsCache.items)) {
        const items = storedItemsCache.items.slice().sort((a, b) => {
          const ta = new Date(a.timestamp || 0).getTime();
          const tb = new Date(b.timestamp || 0).getTime();
          return (tb || 0) - (ta || 0);
        });
        items.forEach((item) => {
          if (item && item.content) {
            const folder = String(item.folder || '').trim();
            if (folder === 'やることリスト') {
              addCandidate(item.content);
            }
          }
        });
      }

      return results;
    }

    function renderGanttTodoCandidates() {
      const candidates = getGanttTodoCandidates();

      const datalist = document.getElementById('gantt-todo-datalist');
      if (datalist) {
        datalist.innerHTML = candidates.map((c) => '<option value="' + escapeHtmlText(c) + '"></option>').join('');
      }
    }

    window.renderGanttTodoCandidates = renderGanttTodoCandidates;



    let organizeSourceType = 'inbox';
    let organizeCustomItems = [];
    let organizeCustomIndex = 0;
    let organizeInboxItems = [];
    async function loadOrganizeData(options) {
      options = options || {};
      const silent = !!options.silent;
      const hasCache = configData && typeof configData === 'object' && Object.keys(configData).length > 0;
      if (!silent && !hasCache) showLoader("データを読み込み中...");
      else if (!silent && hasCache) setOrganizeSyncStatus('更新中...');
      const sourceContainer = document.getElementById('organize-source-buttons');

      const data = await callAPI('getOrganizerData', {}, silent || hasCache ? { silent: true } : {});
      if (!data || data.error || !data.config) {
        if (!silent && !hasCache) hideLoader();
        if (!silent && hasCache) setOrganizeSyncStatus('更新に失敗しました');
        return;
      }
      configData = data.config;
      const serverInbox = data.inbox || [];
      const pendingInbox = pendingDumpCache
        .filter((i) => i && i.isInbox && i.content)
        .map((i) => ({ id: i.id, content: i.content, timestamp: i.timestamp, _pending: true }));
      const seenInbox = new Set(pendingInbox.map((i) => i.content));
      organizeInboxItems = pendingInbox.concat(serverInbox.filter((i) => i && i.content && !seenInbox.has(i.content)));

      if (sourceContainer) {
        let validSources = ['inbox'];
        const fetchPromises = [];
        const foldersToTest = [];
        Object.keys(configData).forEach(folder => {
          if (configData[folder].includes('未整理')) {
            fetchPromises.push(callAPI('getFolderFileItems', { folder, file: '未整理' }, { silent: true }));
            foldersToTest.push(folder);
          }
        });

        const results = await Promise.all(fetchPromises);
        results.forEach((items, i) => {
          if (items && items.length > 0) {
            validSources.push(foldersToTest[i]);
          }
        });

        if (!validSources.includes(organizeSourceType)) {
          organizeSourceType = 'inbox';
        }

        sourceContainer.innerHTML = '';
        const sortedSources = [
          ...(validSources.includes('inbox') ? ['inbox'] : []),
          ...sortNames(validSources.filter(src => src !== 'inbox'))
        ];
        sortedSources.forEach(src => {
          const btn = document.createElement('button');
          const isSelected = src === organizeSourceType;
          btn.className = isSelected
            ? "bg-cyan-700 border-2 border-cyan-400 text-cyan-50 font-bold py-2 px-3 rounded-lg text-xs shadow-[0_0_10px_rgba(34,211,238,0.3)] transition text-left h-10 truncate"
            : "bg-slate-800/80 border-2 border-slate-700 text-slate-300 hover:bg-slate-700 font-bold py-2 px-3 rounded-lg text-xs transition active:scale-95 text-left h-10 truncate";
          btn.textContent = src === 'inbox' ? '📥 INBOX (未整理)' : `📁 ${src} (未整理)`;
          btn.onclick = () => {
            if (organizeSourceType !== src) {
              organizeSourceType = src;
              loadOrganizeData();
            }
          };
          sourceContainer.appendChild(btn);
        });
      }
      if (organizeSourceType === 'inbox') {
        if (organizeInboxItems.length > 0) {
          renderOrganizer({
            config: configData,
            count: organizeInboxItems.length,
            nextItem: organizeInboxItems[0]
          });
        } else {
          renderOrganizer({ config: configData, count: 0 });
        }
      } else {
        const items = await callAPI('getFolderFileItems', { folder: organizeSourceType, file: '未整理' }, { silent: true }) || [];
        organizeCustomItems = items;
        organizeCustomIndex = 0;

        if (organizeCustomItems.length > 0) {
          const fakeData = {
            config: configData,
            count: organizeCustomItems.length,
            nextItem: organizeCustomItems[0]
          };
          renderOrganizer(fakeData);
        } else {
          renderOrganizer({ config: configData, count: 0 });
        }
      }
      setOrganizeSyncStatus('');
      if (!silent && !hasCache) hideLoader();
    }

    function advanceOrganizeQueueAfterRemove(removedFromInbox) {
      if (removedFromInbox) {
        bumpBadgeOptimistic(-1);
        if (organizeInboxItems.length > 0) {
          renderOrganizer({
            config: configData,
            count: organizeInboxItems.length,
            nextItem: organizeInboxItems[0]
          });
        } else {
          renderOrganizer({ config: configData, count: 0 });
        }
      } else {
        if (organizeCustomItems.length > 0) {
          if (organizeCustomIndex >= organizeCustomItems.length) organizeCustomIndex = 0;
          renderOrganizer({
            config: configData,
            count: organizeCustomItems.length,
            nextItem: organizeCustomItems[organizeCustomIndex]
          });
        } else {
          renderOrganizer({ config: configData, count: 0 });
        }
      }
    }

    function restoreOrganizeItem(item, fromInbox) {
      if (!item) return;
      if (fromInbox) {
        organizeInboxItems.unshift(item);
        bumpBadgeOptimistic(1);
        renderOrganizer({
          config: configData,
          count: organizeInboxItems.length,
          nextItem: organizeInboxItems[0]
        });
      } else {
        organizeCustomItems.splice(organizeCustomIndex, 0, item);
        renderOrganizer({
          config: configData,
          count: organizeCustomItems.length,
          nextItem: organizeCustomItems[organizeCustomIndex]
        });
      }
    }
    function renderOrganizer(data) {
      document.getElementById('remain-count').textContent = data.count;
      const badge = document.getElementById('badge-count');
      if (badge) {
        badge.textContent = data.count;
        badge.classList.add('hidden');
        badge.setAttribute('hidden', '');
        badge.style.display = 'none';
      }
      if (data.count === 0) {
        document.getElementById('organize-container').classList.add('hidden');
        document.getElementById('organize-empty').classList.remove('hidden');
        return;
      }
      document.getElementById('organize-container').classList.remove('hidden');
      document.getElementById('organize-empty').classList.add('hidden');
      document.getElementById('current-content').value = data.nextItem.content;
      document.getElementById('current-original-content').value = data.nextItem.content;
      document.getElementById('current-id').value = data.nextItem.id;
      const folderSelect = document.getElementById('select-folder');
      const cachedFolder = folderSelect.value;
      folderSelect.innerHTML = '';

      sortNames(Object.keys(configData)).forEach(folder => {
        const opt = document.createElement('option'); opt.value = folder; opt.textContent = folder;
        folderSelect.appendChild(opt);
      });

      const newFolderOpt = document.createElement('option'); newFolderOpt.value = '__NEW__'; newFolderOpt.textContent = '＋ 新規フォルダを追加';
      folderSelect.appendChild(newFolderOpt);
      if (cachedFolder && configData[cachedFolder]) folderSelect.value = cachedFolder;
      onFolderChange();
    }
    function onFolderChange() {
      const folderSelect = document.getElementById('select-folder');
      const fileSelect = document.getElementById('select-file');
      const selectedFolder = folderSelect.value;

      if (selectedFolder === '__NEW__') {
        const newFolder = prompt("新しいフォルダ名（大分類）を入力してください:");
        if (!newFolder || !newFolder.trim()) {
          loadOrganizeData(); // revert
          return;
        }
        const newFile = prompt(`「${newFolder.trim()}」内に作成する新しいファイル名（小分類）を入力してください:`);
        if (!newFile || !newFile.trim()) {
          loadOrganizeData(); // revert
          return;
        }
        callAPI('addConfigRecord', { folder: newFolder.trim(), file: newFile.trim() }).then(res => {
          if (res.success) {
            callAPI('getOrganizerData').then(data => {
              configData = data.config;
              renderOrganizer(data);
              document.getElementById('select-folder').value = newFolder.trim();
              onFolderChange();
              document.getElementById('select-file').value = newFile.trim();
            });
          }
        });
        return;
      }
      fileSelect.innerHTML = '';
      if (configData[selectedFolder]) {
        sortNames(configData[selectedFolder]).forEach(file => {
          const opt = document.createElement('option'); opt.value = file; opt.textContent = file;
          fileSelect.appendChild(opt);
        });
        const newFileOpt = document.createElement('option'); newFileOpt.value = '__NEW__'; newFileOpt.textContent = '＋ 新規ファイルを追加';
        fileSelect.appendChild(newFileOpt);
      }
    }
    function onFileChange() {
      const folderSelect = document.getElementById('select-folder');
      const fileSelect = document.getElementById('select-file');
      const selectedFolder = folderSelect.value;
      const selectedFile = fileSelect.value;
      if (selectedFile === '__NEW__') {
        const newFile = prompt(`「${selectedFolder}」内に作成する新しいファイル名（小分類）を入力してください:`);
        if (!newFile || !newFile.trim()) {
          onFolderChange(); // revert
          return;
        }
        callAPI('addConfigRecord', { folder: selectedFolder, file: newFile.trim() }).then(res => {
          if (res.success) {
            callAPI('getOrganizerData').then(data => {
              configData = data.config;
              renderOrganizer(data);
              document.getElementById('select-folder').value = selectedFolder;
              onFolderChange();
              document.getElementById('select-file').value = newFile.trim();
            });
          }
        });
      }
    }
    function renameCurrentOrganizeConfig() {
      const folderSelect = document.getElementById('select-folder');
      const fileSelect = document.getElementById('select-file');
      const oldFolder = folderSelect.value;
      const oldFile = fileSelect.value;

      if (!oldFolder || !oldFile || oldFolder === '__NEW__' || oldFile === '__NEW__') {
        alert("変更するフォルダ・ファイルが選択されていません");
        return;
      }
      const newFolder = prompt(`「${oldFolder} ＞ ${oldFile}」の名前を変更します。\n\n新しいフォルダ名:`, oldFolder);
      if (newFolder === null) return;

      const newFile = prompt(`新しいファイル名:`, oldFile);
      if (newFile === null) return;

      if (!newFolder.trim() || !newFile.trim()) return;
      if (newFolder === oldFolder && newFile === oldFile) return;
      callAPI('updateConfigRecord', { oldFolder, oldFile, newFolder: newFolder.trim(), newFile: newFile.trim() }).then(res => {
        if (res.success) {
          callAPI('getOrganizerData').then(data => {
            configData = data.config;
            renderOrganizer(data);
            document.getElementById('select-folder').value = newFolder.trim();
            onFolderChange();
            document.getElementById('select-file').value = newFile.trim();
          });
        }
      });
    }
    function openSplitOrganize() {
      const content = document.getElementById('current-content').value;
      const chunks = content.split(/\n\s*\n/).map(chunk => chunk.trim()).filter(Boolean);
      if (chunks.length < 2) {
        alert("空行で区切られた情報が2件以上ありません。\n情報と情報の間に空行を入れてください。");
        return;
      }
      const overlay = document.getElementById('split-organize-overlay');
      // main の z-10 スタッキングコンテキスト内だと下部ナビ(z-50)に隠れるため body 直下へ移動
      if (overlay.parentElement !== document.body) {
        document.body.appendChild(overlay);
      }
      const list = document.getElementById('split-organize-list');
      list.innerHTML = '';
      const folders = sortNames(Object.keys(configData));
      chunks.forEach((chunk, index) => {
        const card = document.createElement('div');
        card.className = 'split-organize-item bg-[#0b1021]/90 border border-cyan-900/60 rounded-2xl p-4 shadow-lg';
        const header = document.createElement('div');
        header.className = 'text-xs font-black text-cyan-400 mb-2';
        header.textContent = `情報 ${index + 1} / ${chunks.length}`;
        const textarea = document.createElement('textarea');
        textarea.className = 'split-content w-full min-h-[110px] p-3 bg-black/40 border border-cyan-800/60 text-cyan-50 rounded-xl font-mono text-sm leading-relaxed resize-y focus:outline-none focus:border-cyan-400';
        textarea.value = chunk;
        const selects = document.createElement('div');
        selects.className = 'grid grid-cols-1 sm:grid-cols-2 gap-3 mt-3';
        const folderSelect = document.createElement('select');
        folderSelect.className = 'split-folder w-full h-12 px-3 bg-black/40 border border-cyan-800/60 rounded-xl text-cyan-50 font-bold focus:outline-none focus:border-cyan-400';
        const folderPlaceholder = document.createElement('option');
        folderPlaceholder.value = '';
        folderPlaceholder.textContent = 'フォルダを選択';
        folderSelect.appendChild(folderPlaceholder);
        folders.forEach(folder => {
          const option = document.createElement('option');
          option.value = folder;
          option.textContent = folder;
          folderSelect.appendChild(option);
        });
        const fileSelect = document.createElement('select');
        fileSelect.className = 'split-file w-full h-12 px-3 bg-black/40 border border-cyan-800/60 rounded-xl text-cyan-50 font-bold focus:outline-none focus:border-cyan-400';
        fileSelect.disabled = true;
        const filePlaceholder = document.createElement('option');
        filePlaceholder.value = '';
        filePlaceholder.textContent = '先にフォルダを選択';
        fileSelect.appendChild(filePlaceholder);
        folderSelect.addEventListener('change', () => {
          fileSelect.innerHTML = '';
          const placeholder = document.createElement('option');
          placeholder.value = '';
          placeholder.textContent = 'ファイルを選択';
          fileSelect.appendChild(placeholder);
          sortNames(configData[folderSelect.value] || []).forEach(file => {
            const option = document.createElement('option');
            option.value = file;
            option.textContent = file;
            fileSelect.appendChild(option);
          });
          fileSelect.disabled = !folderSelect.value;
        });
        selects.appendChild(folderSelect);
        selects.appendChild(fileSelect);
        card.appendChild(header);
        card.appendChild(textarea);
        card.appendChild(selects);
        list.appendChild(card);
      });
      overlay.classList.remove('hidden');
      document.documentElement.classList.add('review-detail-open');
      document.body.style.overflow = 'hidden';
    }
    function closeSplitOrganize() {
      document.getElementById('split-organize-overlay').classList.add('hidden');
      document.body.style.overflow = '';
    }
    async function saveSplitOrganize() {
      const id = document.getElementById('current-id').value;
      if (!id) return;
      const cards = Array.from(document.querySelectorAll('.split-organize-item'));
      const items = [];
      for (let i = 0; i < cards.length; i++) {
        const content = cards[i].querySelector('.split-content').value.trim();
        const folder = cards[i].querySelector('.split-folder').value;
        const file = cards[i].querySelector('.split-file').value;
        if (!content) {
          alert(`情報 ${i + 1} の内容が空です。`);
          return;
        }
        if (!folder || !file) {
          alert(`情報 ${i + 1} の保存先を選択してください。`);
          cards[i].scrollIntoView({ behavior: 'smooth', block: 'center' });
          return;
        }
        items.push({ folder, file, content });
      }
      const button = document.getElementById('split-save-btn');
      button.disabled = true;
      button.textContent = '保存中...';
      try {
        const finishOperation = organizeSourceType === 'inbox'
          ? { action: 'moveInboxItem', id, folder: '🗑️ ゴミ箱', file: '削除履歴' }
          : { action: 'deleteDataRecord', id };
        const response = await callBatch([
          { action: 'addManyDataRecords', items },
          finishOperation
        ]);
        if (response.error || (response.results || []).some(result => result && result.error)) {
          throw new Error('分割保存に失敗しました');
        }
        closeSplitOrganize();
        if (organizeSourceType === 'inbox') {
          const idx = organizeInboxItems.findIndex(i => String(i.id) === String(id));
          if (idx >= 0) organizeInboxItems.splice(idx, 1);
          bumpBadgeOptimistic(-1);
          if (organizeInboxItems.length > 0) {
            renderOrganizer({
              config: configData,
              count: organizeInboxItems.length,
              nextItem: organizeInboxItems[0]
            });
          } else {
            renderOrganizer({ config: configData, count: 0 });
          }
          updateBadge();
        } else {
          organizeCustomItems = await callAPI('getFolderFileItems', {
            folder: organizeSourceType,
            file: '未整理'
          }) || [];
          organizeCustomIndex = 0;
          renderOrganizer({
            config: configData,
            count: organizeCustomItems.length,
            nextItem: organizeCustomItems[0] || null
          });
        }
      } catch (error) {
        console.error('Split organize error:', error);
        alert("分割保存に失敗しました。もう一度お試しください。");
      } finally {
        button.disabled = false;
        button.textContent = 'すべて保存して次へ';
      }
    }
    async function moveItem() {
      const id = document.getElementById('current-id').value;
      const folder = document.getElementById('select-folder').value;
      const file = document.getElementById('select-file').value;
      if (!id || !folder || !file) return;
      const content = document.getElementById('current-content').value;
      const originalContentEl = document.getElementById('current-original-content');
      const originalContent = originalContentEl ? originalContentEl.value : content;
      const fromInbox = organizeSourceType === 'inbox';
      let removedItem = null;

      if (fromInbox) {
        const idx = organizeInboxItems.findIndex(i => String(i.id) === String(id));
        removedItem = idx >= 0
          ? organizeInboxItems.splice(idx, 1)[0]
          : { id, content: originalContent, timestamp: '' };
        if (removedItem) removedItem = { ...removedItem, content };
        advanceOrganizeQueueAfterRemove(true);
      } else {
        removedItem = organizeCustomItems[organizeCustomIndex]
          ? { ...organizeCustomItems[organizeCustomIndex], content }
          : { id, content };
        organizeCustomItems.splice(organizeCustomIndex, 1);
        advanceOrganizeQueueAfterRemove(false);
      }

      setOrganizeSyncStatus('同期中...');
      runInBackground(async () => {
        if (fromInbox) {
          if (content === originalContent) {
            const res = await callAPI('moveInboxItem', { id, folder, file }, { silent: true });
            if (res && res.error) throw new Error('move');
            logOperation('MOVE', `INBOXから ${folder} > ${file} へ移動`, { oldFolder: "INBOX", oldFile: "未整理", newFolder: folder, newFile: file, content: content });
          } else {
            const batchRes = await callBatch([
              { action: 'addDataRecord', folder, file, content },
              { action: 'moveInboxItem', id, folder: '🗑️ ゴミ箱', file: '削除履歴' }
            ], { silent: true });
            if (batchRes && (batchRes.error || batchRes.success === false)) throw new Error('move');
            logOperation('MOVE_EDIT', `INBOXから ${folder} > ${file} へ編集して移動`, { oldFolder: "INBOX", oldFile: "未整理", newFolder: folder, newFile: file, oldContent: originalContent, content: content });
          }
        } else {
          if (content === originalContent) {
            const res = await callAPI('moveDataRecord', { id, folder, file }, { silent: true });
            if (res && res.error) throw new Error('move');
          } else {
            const batchRes = await callBatch([
              { action: 'addDataRecord', folder, file, content },
              { action: 'deleteDataRecord', id }
            ], { silent: true });
            if (batchRes && (batchRes.error || batchRes.success === false)) throw new Error('move');
          }
          logOperation('MOVE', `${organizeSourceType} から ${folder} > ${file} へ移動`, { oldFolder: organizeSourceType, oldFile: "未整理", newFolder: folder, newFile: file, content: content });
        }
        await purgeInboxExactDuplicatesIfEnabled();
        updateBadge();
        setOrganizeSyncStatus('');
      }, {
        onError: () => {
          restoreOrganizeItem(removedItem, fromInbox);
          setOrganizeSyncStatus('同期に失敗しました。復元しました');
          alert('移動の同期に失敗しました。カードを復元しました。');
        }
      });
    }
    async function discardInboxItem() {
      const id = document.getElementById('current-id').value;
      if (!id) return;
      if (!confirm("このINBOXの情報を破棄（削除）しますか？\n（※破棄されたデータは「🗑️ ゴミ箱」フォルダの「削除履歴」ファイルへ移動します）")) return;
      const content = document.getElementById('current-content').value;
      const fromInbox = organizeSourceType === 'inbox';
      let removedItem = null;

      if (fromInbox) {
        const idx = organizeInboxItems.findIndex(i => String(i.id) === String(id));
        removedItem = idx >= 0
          ? organizeInboxItems.splice(idx, 1)[0]
          : { id, content };
        advanceOrganizeQueueAfterRemove(true);
      } else {
        removedItem = organizeCustomItems[organizeCustomIndex]
          ? { ...organizeCustomItems[organizeCustomIndex] }
          : { id, content };
        organizeCustomItems.splice(organizeCustomIndex, 1);
        advanceOrganizeQueueAfterRemove(false);
      }

      setOrganizeSyncStatus('同期中...');
      const deleteLogId = logOperation('DELETE', fromInbox ? 'INBOXのデータを削除' : `${organizeSourceType} のデータを削除`, {
        oldFolder: fromInbox ? 'INBOX' : organizeSourceType,
        oldFile: '未整理',
        newFolder: '🗑️ ゴミ箱',
        newFile: '削除履歴',
        content: content,
        id: id
      });
      runInBackground(async () => {
        if (fromInbox) {
          const res = await callAPI('moveInboxItem', { id, folder: '🗑️ ゴミ箱', file: '削除履歴' }, { silent: true });
          if (res && res.error) throw new Error('discard');
        } else {
          const res = await callAPI('moveDataRecord', { id, folder: '🗑️ ゴミ箱', file: '削除履歴' }, { silent: true });
          if (res && res.error) throw new Error('discard');
        }
        updateBadge();
        setOrganizeSyncStatus('');
      }, {
        onError: () => {
          rollbackLoggedOperation(deleteLogId);
          restoreOrganizeItem(removedItem, fromInbox);
          setOrganizeSyncStatus('同期に失敗しました。復元しました');
          alert('削除の同期に失敗しました。カードを復元しました。');
        }
      });
    }
    let isReviewingInbox = false;
    function initReviewMode() {
      if (isReviewSelectMode) toggleReviewSelectMode(false);
      reviewSelectedFolder = ""; reviewSelectedFile = ""; reviewItems = []; reviewCurrentIndex = 0;
      isReviewingInbox = false;
      closeReviewDetail({ force: true });
      document.getElementById('review-step-folder').classList.remove('hidden');
      document.getElementById('review-step-file').classList.add('hidden');
      document.getElementById('review-step-viewer').classList.add('hidden');
      const folderListContainer = document.getElementById('review-folder-list');
      if (folderListContainer) {
        folderListContainer.innerHTML = '<div class="text-center py-8 text-cyan-400 font-bold animate-pulse">読み込み中...</div>';
      }
      callAPI('getReviewOverview', {}, { silent: true }).then(data => {
        const organizer = data.organizer || {};
        const pendingByFolder = data.pendingByFolder || {};
        configData = organizer.config || {};
        folderListContainer.innerHTML = '';

        const inboxBtn = document.createElement('button');
        inboxBtn.type = 'button';
        inboxBtn.className = "w-full bg-gradient-to-r from-emerald-900/50 to-teal-900/50 border-2 border-emerald-700/50 hover:bg-emerald-800/60 text-emerald-300 font-black h-[4.5rem] rounded-xl text-left px-5 flex items-center justify-between transition active:scale-[0.99] shadow-sm text-lg mb-3";
        inboxBtn.innerHTML = `<span>📥 INBOX (未整理) を確認</span> <span class="text-base text-emerald-400 font-bold">${organizer.inbox ? organizer.inbox.length : 0}件</span>`;
        inboxBtn.onclick = () => selectReviewInbox(organizer.inbox || []);
        folderListContainer.appendChild(inboxBtn);
        const folders = sortNames(Object.keys(configData));
        sortNames(Object.keys(pendingByFolder)).forEach(folder => {
          const items = pendingByFolder[folder];
          if (!Array.isArray(items) || items.length === 0) return;
          const dynInboxBtn = document.createElement('button');
          dynInboxBtn.type = 'button';
          dynInboxBtn.className = "w-full bg-gradient-to-r from-teal-900/40 to-cyan-900/40 border-2 border-teal-700/50 hover:bg-teal-800/50 text-teal-300 font-black h-[4.5rem] rounded-xl text-left px-5 flex items-center justify-between transition active:scale-[0.99] shadow-sm text-lg mb-3";
          const labelSpan = document.createElement('span');
          labelSpan.textContent = `📁 ${folder} (未整理) を確認`;
          const countSpan = document.createElement('span');
          countSpan.className = 'text-base text-teal-400 font-bold';
          countSpan.textContent = `${items.length}件`;
          dynInboxBtn.appendChild(labelSpan);
          dynInboxBtn.appendChild(countSpan);
          dynInboxBtn.onclick = () => selectReviewFolderInbox(folder, items);
          folderListContainer.appendChild(dynInboxBtn);
        });
        if (folders.length === 0) {
          const emptyDiv = document.createElement('div');
          emptyDiv.className = 'text-center py-8 text-slate-400 font-bold';
          emptyDiv.textContent = 'フォルダがありません';
          folderListContainer.appendChild(emptyDiv);
        } else {
          folders.forEach(folder => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = "w-full bg-cyan-950/40 border-2 border-cyan-800/50 hover:bg-cyan-900/60 text-cyan-100 font-black h-[4.5rem] rounded-xl text-left px-5 flex items-center justify-between transition active:scale-[0.99] shadow-sm text-lg mb-2";
            const left = document.createElement('div');
            left.className = 'flex items-center gap-1';
            const titleSpan = document.createElement('span');
            titleSpan.textContent = `📁 ${folder}`;
            const renameSpan = document.createElement('span');
            renameSpan.className = 'text-sm bg-slate-800/80 hover:bg-slate-700 text-slate-300 px-2.5 py-1.5 rounded-md ml-2 border border-slate-600/50 transition active:scale-95';
            renameSpan.textContent = '✏️変更';
            renameSpan.addEventListener('click', (ev) => renameReviewFolder(folder, ev));
            const deleteSpan = document.createElement('span');
            deleteSpan.className = 'text-sm bg-rose-950/60 hover:bg-rose-900/70 text-rose-400 px-2.5 py-1.5 rounded-md border border-rose-800/50 transition active:scale-95';
            deleteSpan.textContent = '🗑️削除';
            deleteSpan.addEventListener('click', (ev) => deleteReviewFolder(folder, ev));
            left.appendChild(titleSpan);
            left.appendChild(renameSpan);
            left.appendChild(deleteSpan);

            const right = document.createElement('span');
            right.className = 'text-base text-cyan-500/70 font-bold';
            right.textContent = `${configData[folder].length} Files`;

            btn.appendChild(left);
            btn.appendChild(right);
            btn.onclick = () => selectReviewFolder(folder);
            folderListContainer.appendChild(btn);
          });
        }

        const newFolderBtn = document.createElement('button');
        newFolderBtn.type = 'button';
        newFolderBtn.className = "w-full bg-cyan-950/40 border-2 border-cyan-800/50 hover:bg-cyan-900/60 text-cyan-300 font-black h-[4.5rem] rounded-xl text-left px-5 flex items-center justify-between transition active:scale-[0.99] shadow-sm text-lg mt-2";
        newFolderBtn.innerHTML = `<span>➕ 新規フォルダを追加</span>`;
        newFolderBtn.onclick = () => createNewReviewFolder();
        folderListContainer.appendChild(newFolderBtn);
      }).catch(() => {
        if (folderListContainer) {
          folderListContainer.innerHTML = '<div class="text-center py-8 text-rose-400 font-bold">読み込みに失敗しました</div>';
        }
      });
    }
    function createNewReviewFolder() {
      const newFolder = prompt("新しく作成するフォルダ名（大分類）を入力してください:");
      if (!newFolder || !newFolder.trim()) return;

      const newFile = prompt(`「${newFolder.trim()}」内に作成する最初のファイル名（小分類）を入力してください:\n(例: メモ, タスク)`);
      if (!newFile || !newFile.trim()) return;

      callAPI('addConfigRecord', { folder: newFolder.trim(), file: newFile.trim() }).then(res => {
        if (res.success) {
          initReviewMode();
        }
      });
    }
    async function renameReviewFolder(oldFolder, e) {
      if (e) e.stopPropagation();
      const newFolder = prompt(`「${oldFolder}」の新しいフォルダ名を入力してください:`, oldFolder);
      if (!newFolder || !newFolder.trim() || newFolder.trim() === oldFolder) return;

      const targetFolder = newFolder.trim();

      try {
        const res = await callAPI('updateConfigRecord', {
          oldFolder,
          oldFile: '',
          newFolder: targetFolder,
          newFile: ''
        });
        if (!res || res.error || res.success === false) {
          alert('フォルダ名の変更に失敗しました');
          return;
        }
        initReviewMode();
      } catch (err) {
        alert("エラーが発生しました");
      }
    }
    async function deleteReviewFolder(folder, e) {
      e.stopPropagation();
      if (await deleteConfigAndMoveToTrash(folder, null)) {
        initReviewMode();
      }
    }
    async function deleteReviewFile(file, e) {
      e.stopPropagation();
      if (await deleteConfigAndMoveToTrash(reviewSelectedFolder, file)) {
        callAPI('getOrganizerData').then(data => {
          configData = data.config;
          selectReviewFolder(reviewSelectedFolder);
        });
      }
    }
    function selectReviewFolder(folder) {
      reviewSelectedFolder = folder;
      document.getElementById('review-step-folder').classList.add('hidden');
      document.getElementById('review-step-file').classList.remove('hidden');
      const fileListContainer = document.getElementById('review-file-list');
      fileListContainer.innerHTML = '';
      const files = sortNames(configData[folder] || []);
      if (files.length === 0) {
        fileListContainer.innerHTML = '<div class="text-center py-8 text-slate-400 font-bold">ファイルがありません</div>';
        return;
      }
      files.forEach(file => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = "w-full bg-cyan-950/40 border-2 border-cyan-800/50 hover:bg-cyan-900/60 text-cyan-100 font-black h-[4.5rem] rounded-xl text-left px-5 flex items-center justify-between transition active:scale-[0.99] shadow-sm text-lg";
        const left = document.createElement('div');
        left.className = 'flex items-center gap-1 flex-wrap';
        const titleSpan = document.createElement('span');
        titleSpan.textContent = `📄 ${file}`;
        const renameSpan = document.createElement('span');
        renameSpan.className = 'text-sm bg-slate-800/80 hover:bg-slate-700 text-slate-300 px-2.5 py-1.5 rounded-md ml-2 border border-slate-600/50 transition active:scale-95';
        renameSpan.textContent = '✏️変更';
        renameSpan.addEventListener('click', (ev) => renameReviewFile(file, ev));
        const moveSpan = document.createElement('span');
        moveSpan.className = 'text-sm bg-indigo-950/60 hover:bg-indigo-900/70 text-indigo-300 px-2.5 py-1.5 rounded-md border border-indigo-800/50 transition active:scale-95';
        moveSpan.textContent = '📁移動';
        moveSpan.addEventListener('click', (ev) => moveReviewFile(file, ev));
        const deleteSpan = document.createElement('span');
        deleteSpan.className = 'text-sm bg-rose-950/60 hover:bg-rose-900/70 text-rose-400 px-2.5 py-1.5 rounded-md border border-rose-800/50 transition active:scale-95';
        deleteSpan.textContent = '🗑️削除';
        deleteSpan.addEventListener('click', (ev) => deleteReviewFile(file, ev));
        left.appendChild(titleSpan);
        left.appendChild(renameSpan);
        left.appendChild(moveSpan);
        left.appendChild(deleteSpan);

        const arrow = document.createElement('span');
        arrow.className = 'text-cyan-500/70 text-lg';
        arrow.textContent = '→';

        btn.appendChild(left);
        btn.appendChild(arrow);
        btn.onclick = () => selectReviewFile(file);
        fileListContainer.appendChild(btn);
      });
      const newFileBtn = document.createElement('button');
      newFileBtn.className = "w-full bg-cyan-950/40 border-2 border-cyan-800/50 hover:bg-cyan-900/60 text-cyan-300 font-black h-[4.5rem] rounded-xl text-left px-5 flex items-center justify-between transition active:scale-[0.99] shadow-sm text-lg mt-2";
      newFileBtn.innerHTML = `<span>➕ 新規ファイルを追加</span>`;
      newFileBtn.onclick = () => createNewReviewFile();
      fileListContainer.appendChild(newFileBtn);
    }
    function createNewReviewFile() {
      const newFile = prompt(`「${reviewSelectedFolder}」内に作成する新しいファイル名（小分類）を入力してください:`);
      if (!newFile || !newFile.trim()) return;

      callAPI('addConfigRecord', { folder: reviewSelectedFolder, file: newFile.trim() }).then(res => {
        if (res.success) {
          callAPI('getOrganizerData').then(data => {
            configData = data.config;
            selectReviewFolder(reviewSelectedFolder);
          });
        }
      });
    }
    function renameReviewFile(oldFile, e) {
      e.stopPropagation();
      const newFile = prompt(`「${reviewSelectedFolder} ＞ ${oldFile}」の新しいファイル名を入力してください:`, oldFile);
      if (!newFile || !newFile.trim() || newFile === oldFile) return;

      showLoader("名前を変更中...");
      callAPI('updateConfigRecord', {
        oldFolder: reviewSelectedFolder,
        oldFile: oldFile,
        newFolder: reviewSelectedFolder,
        newFile: newFile.trim()
      }).then(res => {
        if (res.success) {
          callAPI('getOrganizerData').then(data => {
            configData = data.config;
            selectReviewFolder(reviewSelectedFolder);
            hideLoader();
          });
        } else {
          hideLoader();
        }
      });
    }
    let movingFileTarget = "";
    function moveReviewFile(oldFile, e) {
      e.stopPropagation();
      movingFileTarget = oldFile;

      const selectEl = document.getElementById('move-folder-select');
      selectEl.innerHTML = '';

      const folders = sortNames(Object.keys(configData)).filter(f => f !== reviewSelectedFolder);
      if (folders.length === 0) {
        selectEl.innerHTML = '<option value="">(他のフォルダがありません)</option>';
      } else {
        folders.forEach(f => {
          const opt = document.createElement('option');
          opt.value = f;
          opt.textContent = `📁 ${f}`;
          selectEl.appendChild(opt);
        });
      }

      const newOpt = document.createElement('option');
      newOpt.value = "_new_";
      newOpt.textContent = "➕ 新しいフォルダを作成...";
      selectEl.appendChild(newOpt);

      document.getElementById('move-file-name').textContent = `📄 ${oldFile}`;

      const modal = document.getElementById('move-file-modal');
      modal.classList.remove('opacity-0', 'pointer-events-none', 'scale-[0.98]');
      modal.classList.add('opacity-100', 'scale-100');
    }
    function closeMoveModal() {
      const modal = document.getElementById('move-file-modal');
      modal.classList.remove('opacity-100', 'scale-100');
      modal.classList.add('opacity-0', 'pointer-events-none', 'scale-[0.98]');
    }
    function executeMoveFile() {
      let newFolder = document.getElementById('move-folder-select').value;
      if (!newFolder) return;

      if (newFolder === "_new_") {
        const inputNewFolder = prompt("新しいフォルダ名を入力してください:");
        if (!inputNewFolder || !inputNewFolder.trim() || inputNewFolder.trim() === reviewSelectedFolder) {
          return;
        }
        newFolder = inputNewFolder.trim();
      }

      closeMoveModal();
      showLoader("ファイルを移動中...");
      callAPI('updateConfigRecord', {
        oldFolder: reviewSelectedFolder,
        oldFile: movingFileTarget,
        newFolder: newFolder,
        newFile: movingFileTarget
      }).then(res => {
        if (res.success) {
          callAPI('getOrganizerData').then(data => {
            configData = data.config;
            selectReviewFolder(reviewSelectedFolder);
            hideLoader();
          });
        } else {
          hideLoader();
        }
      });
    }
    function selectReviewFolderInbox(folder, items) {
      isReviewingInbox = false;
      reviewSelectedFolder = folder;
      reviewSelectedFile = "未整理";
      document.getElementById('review-step-folder').classList.add('hidden');
      document.getElementById('review-step-viewer').classList.remove('hidden');
      document.getElementById('review-path-indicator').textContent = `📁 ${folder} (未整理)`;
      reviewItems = items || [];
      reviewCurrentIndex = 0;
      setupReviewViewerChrome();
      renderReviewItemsList();
    }
    function selectReviewInbox(inboxData) {
      isReviewingInbox = true;
      reviewSelectedFolder = "INBOX";
      reviewSelectedFile = "未整理";
      document.getElementById('review-step-folder').classList.add('hidden');
      document.getElementById('review-step-viewer').classList.remove('hidden');
      document.getElementById('review-path-indicator').textContent = `📥 INBOX (未整理)`;
      reviewItems = inboxData || [];
      reviewCurrentIndex = 0;
      setupReviewViewerChrome();
      renderReviewItemsList();
    }
    function selectReviewFile(file) {
      isReviewingInbox = false;
      reviewSelectedFile = file;
      document.getElementById('review-step-file').classList.add('hidden');
      document.getElementById('review-step-viewer').classList.remove('hidden');
      document.getElementById('review-path-indicator').textContent = `${reviewSelectedFolder} ＞ ${reviewSelectedFile}`;
      loadReviewItems();
    }
    function setupReviewViewerChrome() {
      const isPending = reviewSelectedFile === '未整理';
      document.getElementById('review-add-section').classList.toggle('hidden', isPending);
      if (!isPending) {
        document.getElementById('review-add-content').value = '';
      }
    }
    function loadReviewItems() {
      return loadReviewItemsAsync();
    }
    async function loadReviewItemsAsync() {
      setupReviewViewerChrome();
      const listEl = document.getElementById('review-items-list');
      const countEl = document.getElementById('review-items-count');
      listEl.innerHTML = '<div class="text-cyan-400 font-bold animate-pulse py-6 text-center">⏳ データを読み込んでいます...</div>';
      countEl.textContent = '---';
      try {
        if (isReviewingInbox) {
          const data = await callAPI('getOrganizerData', {}, { silent: true });
          reviewItems = (data && data.inbox) || [];
        } else {
          const items = await callAPI('getFolderFileItems', { folder: reviewSelectedFolder, file: reviewSelectedFile }, { silent: true });
          reviewItems = items || [];
        }
        reviewCurrentIndex = 0;
        if (isReviewSelectMode) toggleReviewSelectMode(false);
        renderReviewItemsList();
        return reviewItems;
      } catch (e) {
        listEl.innerHTML = '<div class="text-rose-400 font-bold py-6 text-center">読み込みに失敗しました</div>';
        countEl.textContent = '0件';
        reviewItems = [];
        return reviewItems;
      }
    }
    function renderReviewItemsList() {
      const listEl = document.getElementById('review-items-list');
      const countEl = document.getElementById('review-items-count');
      if (!listEl) return;
      // 確認タブは撤去済み。お気に入りや検索の編集中に全件を作ると、戻るまで数秒固まる
      const confirmTab = document.getElementById('confirm-mode');
      if (!confirmTab || !confirmTab.classList.contains('active')) return;
      listEl.innerHTML = '';
      countEl.textContent = `${reviewItems.length}件`;
      if (reviewItems.length === 0) {
        listEl.innerHTML = '<div class="text-center py-8 text-slate-400 font-bold border-2 border-dashed border-cyan-900/40 rounded-2xl">このファイル内は空っぽです</div>';
        return;
      }
      const frag = document.createDocumentFragment();
      reviewItems.forEach((item, index) => {
        const row = document.createElement('div');
        const isSelected = reviewSelectedIndices.has(index);
        if (isReviewSelectMode) {
          row.className = `w-full text-left bg-black/40 border-2 ${isSelected ? 'border-rose-500 bg-rose-950/20' : 'border-cyan-900/50 hover:border-cyan-600/60 hover:bg-cyan-950/30'} rounded-2xl p-5 shadow-[inset_0_0_15px_rgba(0,0,0,0.5)] transition active:scale-[0.99] flex items-start gap-3 cursor-pointer`;
        } else {
          row.className = 'w-full text-left bg-black/40 border-2 border-cyan-900/50 hover:border-cyan-600/60 hover:bg-cyan-950/30 rounded-2xl p-5 shadow-[inset_0_0_15px_rgba(0,0,0,0.5)] transition active:scale-[0.99] flex items-start gap-3 cursor-pointer';
        }
        let pressTimer = null;
        let isLongPress = false;
        const startPress = () => {
          isLongPress = false;
          pressTimer = setTimeout(() => {
            isLongPress = true;
            if (!isReviewSelectMode) {
              toggleReviewSelectMode(true);
              toggleReviewItemSelection(index);
              if (navigator && navigator.vibrate) navigator.vibrate(50);
            }
          }, 500);
        };
        const cancelPress = () => {
          if (pressTimer) {
            clearTimeout(pressTimer);
            pressTimer = null;
          }
        };
        row.addEventListener('touchstart', startPress, { passive: true });
        row.addEventListener('touchend', cancelPress);
        row.addEventListener('touchmove', cancelPress);
        row.addEventListener('touchcancel', cancelPress);
        row.addEventListener('mousedown', startPress);
        row.addEventListener('mouseup', cancelPress);
        row.addEventListener('mouseleave', cancelPress);
        row.addEventListener('mousemove', cancelPress);
        row.onclick = (e) => {
          if (isLongPress) {
            e.preventDefault();
            return;
          }
          if (isReviewSelectMode) {
            toggleReviewItemSelection(index);
          } else {
            openReviewDetail(index);
          }
        };
        if (isReviewSelectMode) {
          const checkWrapper = document.createElement('div');
          checkWrapper.className = 'pt-0.5 flex-shrink-0';
          checkWrapper.innerHTML = `
            <div class="w-6 h-6 rounded-lg border-2 ${isSelected ? 'bg-rose-500 border-rose-400 text-white font-black' : 'border-cyan-700 bg-black/50'} flex items-center justify-center text-sm transition-all shadow-inner">
              ${isSelected ? '✓' : ''}
            </div>
          `;
          row.appendChild(checkWrapper);
        }
        const contentCol = document.createElement('div');
        contentCol.className = 'flex-1 min-w-0';
        const meta = document.createElement('div');
        meta.className = 'flex justify-between items-center mb-2 gap-2';
        const time = document.createElement('span');
        time.className = 'text-[11px] text-cyan-500/80 font-mono font-bold';
        time.textContent = item.timestamp ? `登録: ${item.timestamp}` : '';
        if (item._pending || isTempId(item.id)) {
          const pending = document.createElement('span');
          pending.className = 'text-[11px] text-amber-400 font-bold';
          pending.textContent = '同期中';
          meta.appendChild(pending);
        } else {
          meta.appendChild(time);
        }
        if (!isReviewSelectMode) {
          const arrow = document.createElement('span');
          arrow.className = 'text-cyan-500/70 text-sm font-black';
          arrow.textContent = '→';
          meta.appendChild(arrow);
        }
        const preview = document.createElement('div');
        preview.className = 'whitespace-pre-wrap font-mono text-base text-cyan-50 leading-relaxed bg-[#02040a]/60 p-3 border border-cyan-900/50 rounded-xl shadow-inner line-clamp-8';
        if (typeof setDumpContentDisplay === 'function') setDumpContentDisplay(preview, item.content || '');
        else preview.textContent = item.content || '';
        contentCol.appendChild(meta);
        contentCol.appendChild(preview);
        row.appendChild(contentCol);
        if (!isReviewSelectMode) {
          const sideActions = document.createElement('div');
          sideActions.className = 'flex-shrink-0 self-center flex flex-col gap-1.5';
          const copyBtn = document.createElement('button');
          copyBtn.type = 'button';
          copyBtn.className = 'text-xs bg-slate-800/70 hover:bg-slate-700 text-slate-200 px-2.5 py-2 rounded-xl border border-slate-600/60 transition active:scale-95 font-bold';
          copyBtn.textContent = '📋';
          copyBtn.title = 'コピー';
          copyBtn.onclick = (e) => {
            e.stopPropagation();
            e.preventDefault();
            cancelPress();
            copyTextToClipboard(item.content || '', copyBtn);
          };
          const deleteBtn = document.createElement('button');
          deleteBtn.type = 'button';
          deleteBtn.className = 'text-xs bg-rose-950/60 hover:bg-rose-900/70 text-rose-400 px-2.5 py-2 rounded-xl border border-rose-800/50 transition active:scale-95 font-bold';
          deleteBtn.textContent = '🗑️';
          deleteBtn.title = '削除';
          deleteBtn.setAttribute('aria-label', '削除');
          if (item._pending || isTempId(item.id)) {
            deleteBtn.disabled = true;
            deleteBtn.classList.add('opacity-40', 'pointer-events-none');
            deleteBtn.title = '同期完了まで削除できません';
          }
          deleteBtn.onclick = (e) => {
            e.stopPropagation();
            e.preventDefault();
            cancelPress();
            deleteReviewItemAt(index);
          };
          sideActions.appendChild(createFavoriteButton(item, {
            folder: isReviewingInbox ? 'INBOX' : reviewSelectedFolder,
            file: isReviewingInbox ? '未整理' : reviewSelectedFile,
            isInbox: !!isReviewingInbox || reviewSelectedFile === '未整理'
          }));
          sideActions.appendChild(copyBtn);
          sideActions.appendChild(deleteBtn);
          row.appendChild(sideActions);
        }
        frag.appendChild(row);
      });
      listEl.appendChild(frag);
    }
    async function deleteReviewItemAt(index) {
      if (!reviewItems[index]) return;
      if (isTempId(reviewItems[index].id) || reviewItems[index]._pending) {
        alert('同期完了まで削除できません');
        return;
      }
      if (!confirm('このデータを削除しますか？')) return;
      const item = reviewItems[index];
      const targetId = item.id;
      removeFavoriteById(targetId);
      const deletedContent = item.content;
      const snapshot = reviewItems.slice();
      const prevIndex = reviewCurrentIndex;
      const folder = reviewSelectedFolder;
      const file = reviewSelectedFile;
      const fromInbox = isReviewingInbox;

      reviewItems.splice(index, 1);
      if (reviewCurrentIndex >= reviewItems.length && reviewCurrentIndex > 0) {
        reviewCurrentIndex = reviewItems.length - 1;
      }
      renderReviewItemsList();
      if (fromInbox) bumpBadgeOptimistic(-1);

      const statusEl = document.getElementById('review-items-count');
      const prevCountText = statusEl ? statusEl.textContent : '';
      if (statusEl) statusEl.textContent = '削除同期中...';

      const deleteLogId = logOperation('DELETE', fromInbox ? 'INBOXのデータを削除' : `${folder} のデータを削除`, {
        oldFolder: fromInbox ? 'INBOX' : folder,
        oldFile: fromInbox ? '未整理' : file,
        newFolder: '🗑️ ゴミ箱',
        newFile: '削除履歴',
        content: deletedContent,
        id: targetId
      });

      runInBackground(async () => {
        if (fromInbox) {
          const res = await callAPI('moveInboxItem', { id: targetId, folder: '🗑️ ゴミ箱', file: '削除履歴' }, { silent: true });
          if (res && res.error) throw new Error('delete');
        } else {
          const res = await callAPI('moveDataRecord', { id: targetId, folder: '🗑️ ゴミ箱', file: '削除履歴' }, { silent: true });
          if (res && res.error) throw new Error('delete');
        }
        await removeInputHistoryByContent(deletedContent);
        updateBadge();
        invalidateStoredItemsCache({ ids: [targetId], contents: [deletedContent] });
        if (statusEl) statusEl.textContent = `${reviewItems.length}件`;
      }, {
        onError: () => {
          rollbackLoggedOperation(deleteLogId);
          reviewItems = snapshot;
          reviewCurrentIndex = prevIndex;
          renderReviewItemsList();
          if (fromInbox) bumpBadgeOptimistic(1);
          if (statusEl) statusEl.textContent = prevCountText || `${reviewItems.length}件`;
          alert('削除の同期に失敗しました。一覧を復元しました。');
        }
      });
    }
    function toggleReviewSelectMode(forceState) {
      if (typeof forceState === 'boolean') {
        isReviewSelectMode = forceState;
      } else {
        isReviewSelectMode = !isReviewSelectMode;
      }

      if (!isReviewSelectMode) {
        reviewSelectedIndices.clear();
        const bar = document.getElementById('review-bulk-action-bar');
        if (bar) bar.classList.add('hidden');
      } else {
        const bar = document.getElementById('review-bulk-action-bar');
        if (bar) bar.classList.remove('hidden');
      }

      const toggleBtn = document.getElementById('review-select-toggle-btn');
      if (toggleBtn) {
        if (isReviewSelectMode) {
          toggleBtn.className = "text-xs bg-rose-900/60 hover:bg-rose-800 border border-rose-500 text-rose-200 px-2.5 py-1 rounded-lg font-bold transition active:scale-95";
          toggleBtn.textContent = "✕ 選択解除";
        } else {
          toggleBtn.className = "text-xs bg-cyan-950/60 hover:bg-cyan-900 border border-cyan-700/50 text-cyan-300 px-2.5 py-1 rounded-lg font-bold transition active:scale-95";
          toggleBtn.textContent = "☑️ 複数選択";
        }
      }

      updateReviewBulkActionBar();
      renderReviewItemsList();
    }
    function toggleReviewItemSelection(index) {
      if (reviewSelectedIndices.has(index)) {
        reviewSelectedIndices.delete(index);
      } else {
        reviewSelectedIndices.add(index);
      }
      updateReviewBulkActionBar();
      renderReviewItemsList();
    }
    function selectAllReviewItems(selectAll) {
      if (selectAll) {
        reviewItems.forEach((_, idx) => reviewSelectedIndices.add(idx));
      } else {
        reviewSelectedIndices.clear();
      }
      updateReviewBulkActionBar();
      renderReviewItemsList();
    }
    function updateReviewBulkActionBar() {
      const countEl = document.getElementById('review-selected-count');
      const delBtn = document.getElementById('review-bulk-delete-btn');
      if (countEl) countEl.textContent = reviewSelectedIndices.size;
      if (delBtn) delBtn.disabled = reviewSelectedIndices.size === 0;
    }
    async function executeBulkDeleteReviewItems() {
      if (reviewSelectedIndices.size === 0) return;
      const count = reviewSelectedIndices.size;
      if (!confirm(`選択した ${count} 件の情報を削除しますか？\n（削除されたデータは「ゴミ箱」に移動されます）`)) return;
      const itemsToDelete = Array.from(reviewSelectedIndices).map(idx => reviewItems[idx]).filter(Boolean);
      if (itemsToDelete.length === 0) return;
      const deletedContents = itemsToDelete.map(i => i.content);
      const deleteIds = new Set(itemsToDelete.map(i => String(i.id)));
      const snapshot = reviewItems.slice();

      // 即反映
      reviewItems = reviewItems.filter(i => !deleteIds.has(String(i.id)));
      if (reviewCurrentIndex >= reviewItems.length && reviewCurrentIndex > 0) {
        reviewCurrentIndex = reviewItems.length - 1;
      }
      toggleReviewSelectMode(false);
      renderReviewItemsList();
      if (isReviewingInbox) bumpBadgeOptimistic(-itemsToDelete.length);

      const searchSnapshot = reviewOpenedFromSearch
        ? {
          history: currentSearchTabMode === 'input_history' ? inputHistoryView.slice() : null,
          results: currentSearchTabMode === 'search' ? (searchResults || []).slice() : null
        }
        : null;

      if (reviewOpenedFromSearch) {
        if (currentSearchTabMode === 'input_history') {
          deletedContents.forEach((c) => suppressReplacedHistoryContent(c));
          dropInputHistoryEntries((e) => deletedContents.some((c) => dumpContentEquals(e.content, c)));
          renderInputHistoryView();
        } else if (currentSearchTabMode === 'search' || (document.getElementById('search-keyword') || {}).value) {
          deletedContents.forEach((c) => suppressReplacedHistoryContent(c));
          dropInputHistoryEntries((e) => deletedContents.some((c) => dumpContentEquals(e.content, c)));
          searchResults = (searchResults || []).filter((r) => {
            if (!r) return false;
            if (r.id != null && deleteIds.has(String(r.id))) return false;
            if (deletedContents.some((c) => dumpContentEquals(r.content, c))) return false;
            return true;
          });
          if (currentSearchTabMode === 'search') renderSearchResultsView();
        }
      }

      const statusEl = document.getElementById('review-items-count');
      const prevCountText = statusEl ? statusEl.textContent : '';
      if (statusEl) statusEl.textContent = `削除同期中...`;

      const deleteLogId = logOperation('DELETE', isReviewingInbox
        ? `INBOXのデータ ${count}件を削除`
        : `${reviewSelectedFolder} のデータ ${count}件を削除`, {
        oldFolder: isReviewingInbox ? 'INBOX' : reviewSelectedFolder,
        oldFile: isReviewingInbox ? '未整理' : reviewSelectedFile,
        newFolder: '🗑️ ゴミ箱',
        newFile: '削除履歴',
        contents: deletedContents
      });

      runInBackground(async () => {
        const inboxMoves = [];
        const dataMoves = [];
        itemsToDelete.forEach((item) => {
          if (!item || item.id == null || isTempId(item.id)) return;
          const move = { id: String(item.id), folder: '🗑️ ゴミ箱', file: '削除履歴' };
          if (isReviewingInbox) inboxMoves.push(move);
          else dataMoves.push(move);
        });
        await syncBulkTrashMoves(inboxMoves, dataMoves, { silent: true });

        try {
          for (const content of deletedContents) {
            await removeInputHistoryByContent(content);
          }
        } catch (histErr) {
          console.warn('input history cleanup after bulk delete', histErr);
        }

        updateBadge();
        invalidateStoredItemsCache({
          ids: itemsToDelete.map((i) => i && i.id).filter((id) => id != null),
          contents: deletedContents
        });
        if (statusEl) statusEl.textContent = `${reviewItems.length}件`;
      }, {
        onError: (err) => {
          rollbackLoggedOperation(deleteLogId);
          reviewItems = snapshot;
          renderReviewItemsList();
          if (isReviewingInbox) bumpBadgeOptimistic(itemsToDelete.length);
          if (statusEl) statusEl.textContent = prevCountText || `${reviewItems.length}件`;
          unsuppressReplacedHistoryContents(deletedContents);
          if (searchSnapshot) {
            if (searchSnapshot.history) {
              inputHistoryView = searchSnapshot.history;
              renderInputHistoryView();
            }
            if (searchSnapshot.results) {
              searchResults = searchSnapshot.results;
              renderSearchResultsView();
            }
          }
          const reason = err && err.message ? String(err.message) : '通信エラー';
          alert(`まとめて削除の同期に失敗しました（${reason}）。一覧を復元しました。`);
        }
      });
    }
    function ensureReviewDetailOnBody() {
      const overlay = document.getElementById('review-detail-overlay');
      if (overlay.parentElement !== document.body) {
        document.body.appendChild(overlay);
      }
      return overlay;
    }
    function openReviewDetail(index) {
      if (!reviewItems[index]) return;
      if (isTempId(reviewItems[index].id) || reviewItems[index]._pending) {
        alert('同期完了まで詳細操作はできません');
        return;
      }
      const reviewOverlay = document.getElementById('review-detail-overlay');
      if (reviewOverlay && reviewOverlay.classList.contains('hidden')
        && typeof pushAppNavLocation === 'function' && typeof getAppLocationKey === 'function') {
        pushAppNavLocation(getAppLocationKey());
      }
      reviewCurrentIndex = index;
      const item = reviewItems[index];
      const overlay = ensureReviewDetailOnBody();
      const pathLabel = isReviewingInbox ? 'INBOX ＞ 未整理' : `${reviewSelectedFolder} ＞ ${reviewSelectedFile}`;
      document.getElementById('review-detail-path').textContent = pathLabel;
      document.getElementById('review-detail-time').textContent = item.timestamp ? `登録: ${item.timestamp}` : '';
      const textarea = document.getElementById('review-edit-textarea');
      if (textarea) {
        textarea.value = item.content || '';
        textarea.dataset.originalContent = item.content || '';
      }
      updateReviewDetailFavoriteButton();
      const view = document.getElementById('review-detail-view');
      if (view) {
        view.classList.remove('hidden');
        view.classList.add('flex');
      }
      // フォルダ分類廃止: 移動UIは出さない
      const moveSection = document.getElementById('review-move-section');
      if (moveSection) moveSection.classList.add('hidden');
      overlay.classList.remove('hidden');
      document.documentElement.classList.add('review-detail-open');
      document.body.style.overflow = 'hidden';
      requestAnimationFrame(() => {
        if (textarea) {
          textarea.focus({ preventScroll: true });
          try {
            const len = textarea.value.length;
            textarea.setSelectionRange(len, len);
          } catch (e) { }
        }
      });
    }
    function closeReviewDetail(options) {
      const force = !!(options && options.force);
      const textarea = document.getElementById('review-edit-textarea');
      if (!force && textarea && reviewItems[reviewCurrentIndex]) {
        const original = textarea.dataset.originalContent != null
          ? textarea.dataset.originalContent
          : (reviewItems[reviewCurrentIndex].content || '');
        if (String(textarea.value) !== String(original)) {
          if (!confirm('編集内容が保存されていません。閉じますか？')) return;
        }
      }
      document.getElementById('review-detail-overlay').classList.add('hidden');
      document.documentElement.classList.remove('review-detail-open');
      const hint = document.getElementById('review-detail-hydrate-hint');
      if (hint) hint.classList.add('hidden');
      document.body.style.overflow = '';
      reviewOpenedFromSearch = false;
      if (typeof refreshFavoritesUi === 'function') refreshFavoritesUi();
    }
    function backToFolders() {
      if (isReviewSelectMode) toggleReviewSelectMode(false);
      closeReviewDetail({ force: true });
      document.getElementById('review-step-folder').classList.remove('hidden');
      document.getElementById('review-step-file').classList.add('hidden');
    }
    function backToFiles() {
      if (isReviewSelectMode) toggleReviewSelectMode(false);
      closeReviewDetail({ force: true });
      if (isReviewingInbox || reviewSelectedFile === '未整理' || !configData[reviewSelectedFolder]) {
        initReviewMode();
      } else {
        document.getElementById('review-step-file').classList.remove('hidden');
        document.getElementById('review-step-viewer').classList.add('hidden');
      }
    }
    async function submitReviewAdd() {
      const textarea = document.getElementById('review-add-content');
      const rawContent = textarea.value;
      if (!rawContent.trim()) return;
      const chunks = splitDumpContent(rawContent);
      if (chunks.length === 0) return;
      const preventDuplicates = localStorage.getItem('setting_prevent_duplicates') !== 'false';
      const existingKeys = new Set();
      if (preventDuplicates) {
        reviewItems.forEach((i) => {
          const k = i && (typeof dumpContentKey === 'function' ? dumpContentKey(i.content) : i.content);
          if (k) existingKeys.add(k);
        });
      }
      let addedChunks = [];
      let replacedDupChunks = [];
      const seenThisAdd = new Set();
      for (const chunk of chunks) {
        const key = typeof dumpContentKey === 'function' ? dumpContentKey(chunk) : chunk;
        if (key && seenThisAdd.has(key)) continue;
        if (key) seenThisAdd.add(key);
        if (preventDuplicates && key && existingKeys.has(key)) {
          replacedDupChunks.push(chunk);
        } else if (preventDuplicates && key) {
          existingKeys.add(key);
        }
        addedChunks.push(chunk);
      }
      if (addedChunks.length === 0) {
        alert('保存する内容がありません');
        return;
      }

      const nowLabel = new Date().toLocaleString('ja-JP', {
        year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit'
      });
      const tempItems = addedChunks.map(content => ({
        id: makeTempId(),
        content,
        timestamp: nowLabel,
        _pending: true
      }));
      // 同一本文の古い表示を落として新規として先頭へ
      if (replacedDupChunks.length) {
        const replaceKeys = new Set(replacedDupChunks.map((c) => (typeof dumpContentKey === 'function' ? dumpContentKey(c) : c)));
        reviewItems = reviewItems.filter((i) => !i || !replaceKeys.has(typeof dumpContentKey === 'function' ? dumpContentKey(i.content) : i.content));
        if (typeof forgetDumpedItemsByContents === 'function') {
          forgetDumpedItemsByContents(replacedDupChunks, { includeStored: true });
        }
      }
      reviewItems = tempItems.concat(reviewItems);
      textarea.value = "";
      renderReviewItemsList();
      const netNewCount = Math.max(0, tempItems.length - replacedDupChunks.length);
      if (isReviewingInbox && netNewCount > 0) bumpBadgeOptimistic(netNewCount);
      if (replacedDupChunks.length > 0) {
        console.info(`review add replacing duplicates: ${replacedDupChunks.length}`);
      }

      const folderSnap = reviewSelectedFolder;
      const fileSnap = reviewSelectedFile;
      const inboxSnap = isReviewingInbox;
      const tempIds = new Set(tempItems.map(t => t.id));
      const replaceSnap = replacedDupChunks.slice();

      runInBackground(async () => {
        if (replaceSnap.length) {
          try {
            await trashExactDumpContentsInScope(replaceSnap, inboxSnap
              ? { inbox: true, anywhere: false }
              : { inbox: false, folder: folderSnap, file: fileSnap, anywhere: false });
          } catch (e) {
            console.warn('review replace trash failed', e);
          }
        }
        let writeRes;
        if (inboxSnap) {
          writeRes = await callAPI('addManyInbox', { contents: addedChunks }, { silent: true });
          assertWriteResult(writeRes, addedChunks.length);
          logOperation('ADD', `${addedChunks.length}件を INBOX に追加`, { folder: "INBOX", file: "未整理", contents: addedChunks });
        } else {
          writeRes = await callAPI('addManyDataRecords', {
            items: addedChunks.map(content => ({
              folder: folderSnap,
              file: fileSnap,
              content
            }))
          }, { silent: true });
          assertWriteResult(writeRes, addedChunks.length);
          logOperation('ADD', `${addedChunks.length}件を ${folderSnap} > ${fileSnap} に追加`, { folder: folderSnap, file: fileSnap, contents: addedChunks });
          purgeInboxExactDuplicatesIfEnabled();
        }
        // 本IDで差し替え（軽い再取得）
        if (inboxSnap) {
          const data = await callAPI('getOrganizerData', {}, { silent: true });
          if (data && !data.error) reviewItems = data.inbox || [];
        } else if (reviewSelectedFolder === folderSnap && reviewSelectedFile === fileSnap) {
          const items = await callAPI('getFolderFileItems', { folder: folderSnap, file: fileSnap }, { silent: true });
          if (items && !items.error) reviewItems = items || [];
        }
        renderReviewItemsList();
        updateBadge();
        rememberDumpedItems(addedChunks.map((content) => ({
          content,
          folder: inboxSnap ? '📥 INBOX' : folderSnap,
          file: inboxSnap ? '未整理' : fileSnap,
          isInbox: inboxSnap
        })));
      }, {
        onError: () => {
          reviewItems = reviewItems.filter(i => !tempIds.has(i.id));
          if (inboxSnap && netNewCount > 0) bumpBadgeOptimistic(-netNewCount);
          if (!textarea.value.trim()) {
            textarea.value = rawContent;
          } else {
            textarea.value = rawContent + '\n\n' + textarea.value;
          }
          renderReviewItemsList();
          alert('保存に失敗しました。入力を復元しました。');
        }
      });
    }
    async function onReviewMoveFolderChange() {
      const folderSelect = document.getElementById('review-move-folder');
      const fileSelect = document.getElementById('review-move-file');
      const selectedFolder = folderSelect.value;

      if (selectedFolder === '__NEW__') {
        const newFolder = prompt("新しいフォルダ名（大分類）を入力してください:");
        if (!newFolder || !newFolder.trim()) {
          folderSelect.value = folderSelect.options[0].value;
          return;
        }
        const newFile = prompt(`「${newFolder.trim()}」内に作成する新しいファイル名（小分類）を入力してください:`);
        if (!newFile || !newFile.trim()) {
          folderSelect.value = folderSelect.options[0].value;
          return;
        }
        await callAPI('addConfigRecord', { folder: newFolder.trim(), file: newFile.trim() });
        const data = await callAPI('getOrganizerData');
        configData = data.config;

        folderSelect.innerHTML = '';
        sortNames(Object.keys(configData)).forEach(folder => {
          const opt = document.createElement('option'); opt.value = folder; opt.textContent = folder;
          folderSelect.appendChild(opt);
        });
        const newFolderOpt = document.createElement('option'); newFolderOpt.value = '__NEW__'; newFolderOpt.textContent = '＋ 新規フォルダを追加';
        folderSelect.appendChild(newFolderOpt);

        folderSelect.value = newFolder.trim();
        await onReviewMoveFolderChange();
        fileSelect.value = newFile.trim();
        return;
      }

      fileSelect.innerHTML = '';
      if (configData[selectedFolder]) {
        sortNames(configData[selectedFolder]).forEach(file => {
          const opt = document.createElement('option'); opt.value = file; opt.textContent = file;
          fileSelect.appendChild(opt);
        });
        const newFileOpt = document.createElement('option'); newFileOpt.value = '__NEW__'; newFileOpt.textContent = '＋ 新規ファイルを追加';
        fileSelect.appendChild(newFileOpt);
      }
    }

    async function onReviewMoveFileChange() {
      const folderSelect = document.getElementById('review-move-folder');
      const fileSelect = document.getElementById('review-move-file');
      const selectedFolder = folderSelect.value;
      const selectedFile = fileSelect.value;

      if (selectedFile === '__NEW__') {
        const newFile = prompt(`「${selectedFolder}」内に作成する新しいファイル名（小分類）を入力してください:`);
        if (!newFile || !newFile.trim()) {
          await onReviewMoveFolderChange();
          return;
        }
        await callAPI('addConfigRecord', { folder: selectedFolder, file: newFile.trim() });
        const data = await callAPI('getOrganizerData');
        configData = data.config;
        await onReviewMoveFolderChange();
        fileSelect.value = newFile.trim();
      }
    }

    async function reviewMoveItem() {
      if (reviewItems.length === 0) return;
      const idx = reviewCurrentIndex;
      const currentItem = reviewItems[idx];
      if (!currentItem) return;
      if (isTempId(currentItem.id) || currentItem._pending) {
        alert('同期完了まで移動できません');
        return;
      }
      const targetId = currentItem.id;
      const content = currentItem.content;

      const newFolder = document.getElementById('review-move-folder').value;
      const newFile = document.getElementById('review-move-file').value;

      if (!newFolder || !newFile || newFolder === '__NEW__' || newFile === '__NEW__') return;

      const snapshot = reviewItems.slice();
      const fromInbox = isReviewingInbox;
      const oldFolder = fromInbox ? 'INBOX' : reviewSelectedFolder;
      const oldFile = fromInbox ? '未整理' : reviewSelectedFile;

      reviewItems.splice(idx, 1);
      closeReviewDetail({ force: true });
      renderReviewItemsList();
      if (fromInbox) bumpBadgeOptimistic(-1);

      runInBackground(async () => {
        if (fromInbox) {
          const res = await callAPI('moveInboxItem', { id: targetId, folder: newFolder, file: newFile }, { silent: true });
          if (res && res.error) throw new Error('move');
          logOperation('MOVE', `INBOXから ${newFolder} > ${newFile} へ移動`, { oldFolder: "INBOX", oldFile: "未整理", newFolder: newFolder, newFile: newFile, content: content });
        } else {
          const res = await callAPI('moveDataRecord', { id: targetId, folder: newFolder, file: newFile }, { silent: true });
          if (res && res.error) throw new Error('move');
          logOperation('MOVE', `${oldFolder} から ${newFolder} > ${newFile} へ移動`, { oldFolder, oldFile, newFolder: newFolder, newFile: newFile, content: content });
        }
        updateBadge();
      }, {
        onError: () => {
          reviewItems = snapshot;
          if (fromInbox) bumpBadgeOptimistic(1);
          renderReviewItemsList();
          alert('移動の同期に失敗しました。一覧を復元しました。');
        }
      });
    }
    function startEditReviewItem() {
      // 互換: 開いた時点で常に編集可能なので、フォーカスだけ当てる
      const textarea = document.getElementById('review-edit-textarea');
      if (!textarea || reviewItems.length === 0) return;
      if (reviewItems[reviewCurrentIndex]) {
        textarea.value = reviewItems[reviewCurrentIndex].content || '';
        textarea.dataset.originalContent = reviewItems[reviewCurrentIndex].content || '';
      }
      setTimeout(() => textarea.focus({ preventScroll: true }), 30);
    }
    function cancelEditReviewItem() {
      closeReviewDetail();
    }
    function isFavoriteSyntheticId(id) {
      const s = String(id || '');
      return s.startsWith('hist:') || s.startsWith('favc:');
    }

    function favoriteUsableDumpId(favOrItem) {
      if (!favOrItem) return '';
      const candidates = [];
      const push = (v) => {
        if (v == null || v === '') return;
        const s = String(v);
        if (typeof isTempId === 'function' && isTempId(s)) return;
        if (isFavoriteSyntheticId(s)) return;
        if (!candidates.includes(s)) candidates.push(s);
      };
      push(favOrItem.id);
      if (Array.isArray(favOrItem.ids)) favOrItem.ids.forEach(push);
      return candidates[0] || '';
    }

    async function resolveReviewEditWriteTarget(item, oldContent, fromInbox, folder, file) {
      const usable = favoriteUsableDumpId(item);
      if (usable && typeof resolveDumpByIdFresh === 'function') {
        try {
          const fresh = await resolveDumpByIdFresh(usable, fromInbox ? true : null);
          if (fresh && fresh.id && !(typeof isTempId === 'function' && isTempId(fresh.id))) {
            return {
              id: String(fresh.id),
              isInbox: !!(fresh.isInbox || historyDestIsInbox(fresh.folder)),
              folder: fresh.isInbox || historyDestIsInbox(fresh.folder)
                ? 'INBOX'
                : (fresh.folder || folder),
              file: fresh.isInbox || historyDestIsInbox(fresh.folder)
                ? '未整理'
                : (fresh.file || file || '未整理')
            };
          }
        } catch (e) { }
        return { id: usable, isInbox: !!fromInbox, folder, file };
      }
      if (oldContent && typeof findExactDumpHitsOnServer === 'function') {
        try {
          const hits = await findExactDumpHitsOnServer(oldContent, {
            inbox: true,
            folder: fromInbox ? null : folder,
            file: fromInbox ? null : file,
            anywhere: true
          });
          if (hits && hits[0] && hits[0].id) {
            return {
              id: String(hits[0].id),
              isInbox: !!hits[0].isInbox,
              folder: hits[0].isInbox ? 'INBOX' : (hits[0].folder || folder),
              file: hits[0].isInbox ? '未整理' : (hits[0].file || file || '未整理')
            };
          }
        } catch (e) { }
      }
      return null;
    }

    function sendTextToGanttQuick(rawText, opts) {
      opts = opts || {};
      const lines = String(rawText || '').split(/\r?\n/).map((s) => s.trim()).filter(Boolean);
      const title = (lines[0] || '').slice(0, 60);
      if (!title) {
        alert('ガントへ送る内容が空です');
        return null;
      }
      if (!ganttTasks.length && typeof loadGanttCache === 'function') {
        ganttTasks = loadGanttCache();
      }
      const today = typeof ganttTodayStr === 'function' ? ganttTodayStr() : new Date().toISOString().slice(0, 10);
      const end = typeof ganttAddDays === 'function' ? ganttAddDays(today, 2) : today;
      const task = normalizeGanttTask({
        id: ganttNewId(),
        title,
        start: today,
        end,
        color: GANTT_COLORS[ganttTasks.length % GANTT_COLORS.length],
        done: false
      });
      if (!task) return null;
      saveGanttCache(ganttTasks.concat([task]));
      if (!ganttViewStart && typeof ganttMondayOf === 'function') ganttViewStart = ganttMondayOf(today);
      if (typeof renderGanttAll === 'function') renderGanttAll();
      if (typeof isGanttGCalSyncEnabled === 'function' && isGanttGCalSyncEnabled() && typeof syncTaskToGCal === 'function') {
        syncTaskToGCal(task).catch(() => { });
      }
      if (opts.statusEl) {
        opts.statusEl.textContent = `📅 ガントに追加: ${task.title}`;
        opts.statusEl.className = 'text-center text-xs font-bold text-emerald-300 min-h-[1rem]';
      }
      if (opts.btnEl) {
        const btn = opts.btnEl;
        const origText = btn.dataset.origLabel || btn.textContent;
        btn.dataset.origLabel = origText;
        btn.textContent = '✓ ガントに追加しました';
        setTimeout(() => { btn.textContent = origText; }, 1800);
      }
      if (confirm(`ガントにタスクを追加しました：\n「${task.title}」\n\n今すぐガントタブを開きますか？`)) {
        let canClose = true;
        if (typeof opts.closeOverlayFn === 'function') {
          canClose = opts.closeOverlayFn() !== false;
        }
        if (canClose && typeof switchTab === 'function') {
          switchTab('gantt-mode');
        }
      }
      return task;
    }

    function sendTextToTreeQuick(rawText, closeOverlayFn) {
      const content = String(rawText || '').trim();
      if (!content) {
        alert('ツリーへ送る内容が空です');
        return false;
      }
      if (typeof closeOverlayFn === 'function') {
        if (closeOverlayFn() === false) return false;
      }
      if (typeof switchTab === 'function') switchTab('tree-mode');
      requestAnimationFrame(() => {
        if (typeof initTreeMode === 'function' && (!treeState)) initTreeMode();
        if (typeof treeInsertMemoAsNode === 'function') {
          treeInsertMemoAsNode({ content });
        }
      });
      return true;
    }

    function sendReviewDetailToGantt(btnEl) {
      const textarea = document.getElementById('review-edit-textarea');
      const raw = textarea ? textarea.value : '';
      sendTextToGanttQuick(raw, {
        btnEl,
        closeOverlayFn: () => {
          const overlay = document.getElementById('review-detail-overlay');
          closeReviewDetail();
          return !overlay || overlay.classList.contains('hidden');
        }
      });
    }

    function sendReviewDetailToTree() {
      const textarea = document.getElementById('review-edit-textarea');
      const raw = textarea ? textarea.value : '';
      sendTextToTreeQuick(raw, () => {
        const overlay = document.getElementById('review-detail-overlay');
        closeReviewDetail();
        return !overlay || overlay.classList.contains('hidden');
      });
    }

    async function saveEditReviewItem() {
      const textarea = document.getElementById('review-edit-textarea');
      if (textarea && document.activeElement === textarea) textarea.blur();
      const newContent = String((textarea && textarea.value) || '').trim();
      if (!newContent) return;

      const currentItem = reviewItems[reviewCurrentIndex];
      if (!currentItem) return;
      if (isTempId(currentItem.id) || currentItem._pending) {
        alert('同期完了まで編集できません');
        return;
      }
      if (newContent === String(currentItem.content || '').trim()) {
        if (textarea) textarea.dataset.originalContent = currentItem.content || '';
        return;
      }

      const btn = document.getElementById('btn-save-edit');
      const prevLabel = btn ? btn.textContent : '';
      const idx = reviewCurrentIndex;
      const oldContent = currentItem.content;
      const snapshotItem = { ...currentItem };
      const fromSearch = reviewOpenedFromSearch;
      let fromInbox = isReviewingInbox;
      let folder = fromInbox ? 'INBOX' : reviewSelectedFolder;
      let file = fromInbox ? '未整理' : reviewSelectedFile;
      const stamp = new Date().toLocaleString('ja-JP', {
        year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit'
      });
      const priorId = currentItem.id != null ? String(currentItem.id) : '';
      const resolvedHint = favoriteUsableDumpId(currentItem);
      const writeIdHint = resolvedHint || (!isFavoriteSyntheticId(priorId) ? priorId : '');
      if (writeIdHint && writeIdHint !== priorId) {
        currentItem.id = writeIdHint;
        reviewItems[idx] = { ...currentItem, id: writeIdHint };
      }

      reviewItems[idx] = { ...reviewItems[idx], content: newContent, timestamp: stamp };
      if (textarea) {
        textarea.value = newContent;
        textarea.dataset.originalContent = newContent;
      }
      forgetDumpedItemsByContents([oldContent], { includeStored: true });
      if (typeof patchStoredDumpById === 'function' && (writeIdHint || priorId)) {
        patchStoredDumpById(writeIdHint || priorId, {
          content: newContent,
          timestamp: stamp,
          folder: fromInbox ? '📥 INBOX' : folder,
          file: fromInbox ? '未整理' : file,
          isInbox: fromInbox
        });
      }
      rememberDumpedItems([{
        ...reviewItems[idx],
        folder: fromInbox ? '📥 INBOX' : folder,
        file: fromInbox ? '未整理' : file,
        isInbox: fromInbox
      }]);
      try {
        if (typeof syncFavoriteAfterEdit === 'function') {
          syncFavoriteAfterEdit({
            oldId: priorId || writeIdHint,
            newId: writeIdHint || priorId,
            oldContent,
            newContent,
            folder,
            file,
            isInbox: fromInbox,
            timestamp: stamp
          });
        }
      } catch (e) { }
      if (Array.isArray(searchResults) && searchResults.length) {
        searchResults = searchResults.map((r) => {
          if (!r) return r;
          const sameId = (priorId && String(r.id) === priorId) || (writeIdHint && String(r.id) === writeIdHint);
          const sameContent = oldContent && dumpContentEquals(r.content, oldContent);
          return (sameId || sameContent) ? { ...r, content: newContent, timestamp: stamp, id: writeIdHint || r.id } : r;
        });
      }
      // 登録チェックの編集前本文を先に置き換える（同期が旧本文を戻す前に隠す）
      updateInputHistoryContent(oldContent, newContent, folder, file, writeIdHint || priorId).catch(() => { });
      renderReviewItemsList();
      if (fromSearch) {
        reviewOpenedFromSearch = false;
        closeReviewDetail({ force: true });
        const searchVisible = document.getElementById('search-mode')
          && document.getElementById('search-mode').classList.contains('active');
        if (searchVisible) {
          if (currentSearchTabMode === 'search') renderSearchResultsView();
          else if (currentSearchTabMode === 'input_history') renderInputHistoryView();
        } else if (currentSearchTabMode === 'search' || currentSearchTabMode === 'input_history') {
          searchViewNeedsRefresh = true;
        }
      } else {
        const timeEl = document.getElementById('review-detail-time');
        if (timeEl) timeEl.textContent = `登録: ${stamp}`;
        updateReviewDetailFavoriteButton();
      }
      if (btn) btn.textContent = '同期中...';

      runInBackground(async () => {
        let target = await resolveReviewEditWriteTarget(
          { ...currentItem, id: writeIdHint || priorId, ids: currentItem.ids },
          oldContent,
          fromInbox,
          folder,
          file
        );
        let keptId = target && target.id ? String(target.id) : (writeIdHint || '');
        let writeInbox = target ? !!target.isInbox : fromInbox;
        if (target) {
          folder = target.folder || folder;
          file = target.file || file;
          fromInbox = writeInbox;
        }

        let updatedInPlace = false;
        if (keptId && !isFavoriteSyntheticId(keptId) && !isTempId(keptId)) {
          const upd = await updateDumpByKnownId(keptId, newContent, writeInbox);
          if (upd && upd.success) {
            updatedInPlace = true;
            keptId = String(upd.id || keptId);
            writeInbox = upd.isInbox != null ? !!upd.isInbox : writeInbox;
          }
        }

        if (!updatedInPlace) {
          // 旧本文の実体を探して上書き（新規追加を避ける）
          let oldHits = [];
          try {
            oldHits = await findExactDumpHitsOnServer(oldContent, {
              inbox: true,
              folder: writeInbox ? null : folder,
              file: writeInbox ? null : file,
              anywhere: true
            });
          } catch (e) { }
          if (oldHits && oldHits[0] && oldHits[0].id) {
            const hit = oldHits[0];
            const upd = await updateDumpByKnownId(hit.id, newContent, !!hit.isInbox);
            if (upd && upd.success) {
              updatedInPlace = true;
              keptId = String(upd.id || hit.id);
              writeInbox = upd.isInbox != null ? !!upd.isInbox : !!hit.isInbox;
            }
          }
        }

        if (!updatedInPlace) {
          // どうしても実体が無いときだけ新規。旧本文ヒットはゴミ箱へ
          const addRes = writeInbox
            ? await callAPI('addInbox', { content: newContent }, { silent: true })
            : await callAPI('addDataRecord', {
              folder: folder || reviewSelectedFolder,
              file: file || reviewSelectedFile || '未整理',
              content: newContent
            }, { silent: true });
          if (isApiFailure(addRes)) throw new Error('write');
          keptId = addRes && addRes.id != null ? String(addRes.id) : keptId;
          if (!keptId) throw new Error('write');
          try {
            const oldHits = await findExactDumpHitsOnServer(oldContent, {
              inbox: true,
              anywhere: true
            });
            await trashExactDumpHits(oldHits, keptId);
          } catch (e) { }
        }

        if (typeof syncFavoriteAfterEdit === 'function') {
          syncFavoriteAfterEdit({
            oldId: priorId || keptId,
            newId: keptId,
            oldContent,
            newContent,
            folder: writeInbox ? 'INBOX' : folder,
            file: writeInbox ? '未整理' : file,
            isInbox: writeInbox,
            timestamp: stamp
          });
        }
        if (typeof patchStoredDumpById === 'function') {
          patchStoredDumpById(keptId, {
            content: newContent,
            timestamp: stamp,
            folder: writeInbox ? '📥 INBOX' : folder,
            file: writeInbox ? '未整理' : file,
            isInbox: writeInbox
          });
        }
        if (reviewItems[idx] && (String(reviewItems[idx].id) === priorId
          || String(reviewItems[idx].id) === writeIdHint
          || dumpContentEquals(reviewItems[idx].content, newContent))) {
          reviewItems[idx] = {
            ...reviewItems[idx],
            id: keptId,
            content: newContent,
            timestamp: stamp,
            isInbox: writeInbox
          };
        }
        if (typeof refreshFavoritesUi === 'function') refreshFavoritesUi();
        if (typeof invalidateStoredItemsCache === 'function') {
          invalidateStoredItemsCache({ ids: [keptId, priorId].filter(Boolean), contents: [oldContent, newContent] });
        }
        logOperation('EDIT', writeInbox ? 'INBOXのテキストを編集' : `テキストを編集 (${folder})`, {
          folder: writeInbox ? 'INBOX' : folder,
          file: writeInbox ? '未整理' : file,
          oldContent,
          newContent
        });
        if (btn) btn.textContent = prevLabel || '💾 保存';
      }, {
        onError: () => {
          const stillHere = reviewItems[idx] && (
            String(reviewItems[idx].id) === String(priorId || writeIdHint)
            || dumpContentEquals(reviewItems[idx].content, newContent)
          );
          if (stillHere) reviewItems[idx] = snapshotItem;
          else reviewItems.splice(Math.min(idx, reviewItems.length), 0, snapshotItem);
          if (Array.isArray(searchResults) && searchResults.length) {
            searchResults = searchResults.map((r) =>
              (r && (String(r.id) === String(priorId || writeIdHint) || dumpContentEquals(r.content, newContent)))
                ? { ...r, content: oldContent, id: snapshotItem.id }
                : r
            );
          }
          rememberDumpedItems([{
            ...snapshotItem,
            folder: snapshotItem.isInbox || historyDestIsInbox(snapshotItem.folder) ? '📥 INBOX' : (snapshotItem.folder || folder),
            file: snapshotItem.isInbox || historyDestIsInbox(snapshotItem.folder) ? '未整理' : (snapshotItem.file || file),
            isInbox: !!(snapshotItem.isInbox || historyDestIsInbox(snapshotItem.folder))
          }]);
          if (typeof syncFavoriteAfterEdit === 'function') {
            syncFavoriteAfterEdit({
              oldId: writeIdHint || priorId,
              newId: priorId || writeIdHint,
              oldContent: newContent,
              newContent: oldContent,
              folder,
              file,
              isInbox: fromInbox,
              timestamp: snapshotItem.timestamp || ''
            });
          }
          renderReviewItemsList();
          if (currentSearchTabMode === 'search') renderSearchResultsView();
          if (typeof renderFavoritesList === 'function') {
            const favTab = document.getElementById('favorites-mode');
            if (favTab && favTab.classList.contains('active')) renderFavoritesList();
          }
          if (btn) btn.textContent = prevLabel || '💾 保存';
          alert('保存の同期に失敗しました。内容を元に戻しました。');
        }
      });
    }
    async function deleteReviewItem() {
      if (reviewItems.length === 0) return;
      if (!confirm("このデータを削除しますか？")) return;
      const idx = reviewCurrentIndex;
      const item = reviewItems[idx];
      if (!item) return;
      if (isTempId(item.id) || item._pending) {
        alert('同期完了まで削除できません');
        return;
      }
      const targetId = item.id;
      removeFavoriteById(targetId);
      const fromSearch = reviewOpenedFromSearch;
      const deletedContent = item.content;
      const snapshot = reviewItems.slice();
      const folder = reviewSelectedFolder;
      const file = reviewSelectedFile;
      const fromInbox = isReviewingInbox;
      const searchSnapshot = fromSearch
        ? {
          history: currentSearchTabMode === 'input_history' ? inputHistoryView.slice() : null,
          results: currentSearchTabMode === 'search' ? searchResults.slice() : null
        }
        : null;

      reviewItems.splice(idx, 1);
      reviewOpenedFromSearch = false;
      closeReviewDetail({ force: true });
      renderReviewItemsList();
      if (fromInbox) bumpBadgeOptimistic(-1);

      if (fromSearch) {
        if (currentSearchTabMode === 'input_history') {
          suppressReplacedHistoryContent(deletedContent);
          dropInputHistoryEntries((e) => dumpContentEquals(e.content, deletedContent));
          renderInputHistoryView();
        } else if (currentSearchTabMode === 'search') {
          removeFromSearchResultsOptimistic(targetId, deletedContent);
        } else {
          const keyword = document.getElementById('search-keyword').value;
          if (!keyword.trim()) {
            suppressReplacedHistoryContent(deletedContent);
            dropInputHistoryEntries((e) => dumpContentEquals(e.content, deletedContent));
            renderInputHistoryView();
          } else {
            removeFromSearchResultsOptimistic(targetId, deletedContent);
          }
        }
      }

      const deleteLogId = logOperation('DELETE', fromInbox ? 'INBOXのデータを削除' : `${folder} のデータを削除`, {
        oldFolder: fromInbox ? 'INBOX' : folder,
        oldFile: fromInbox ? '未整理' : file,
        newFolder: '🗑️ ゴミ箱',
        newFile: '削除履歴',
        content: deletedContent,
        id: targetId
      });

      runInBackground(async () => {
        if (fromInbox) {
          const res = await callAPI('moveInboxItem', { id: targetId, folder: '🗑️ ゴミ箱', file: '削除履歴' }, { silent: true });
          if (res && res.error) throw new Error('delete');
        } else {
          const res = await callAPI('moveDataRecord', { id: targetId, folder: '🗑️ ゴミ箱', file: '削除履歴' }, { silent: true });
          if (res && res.error) throw new Error('delete');
        }
        removeInputHistoryByContent(deletedContent);
        updateBadge();
        invalidateStoredItemsCache({ ids: [targetId], contents: [deletedContent] });
      }, {
        onError: () => {
          rollbackLoggedOperation(deleteLogId);
          reviewItems = snapshot;
          reviewCurrentIndex = Math.min(idx, Math.max(0, reviewItems.length - 1));
          renderReviewItemsList();
          if (fromInbox) bumpBadgeOptimistic(1);
          unsuppressReplacedHistoryContent(deletedContent);
          if (searchSnapshot) {
            if (searchSnapshot.history) {
              inputHistoryView = searchSnapshot.history;
              renderInputHistoryView();
            }
            if (searchSnapshot.results) {
              searchResults = searchSnapshot.results;
              renderSearchResultsView();
            }
          }
          alert('削除の同期に失敗しました。一覧を復元しました。');
        }
      });
    }
    let localInputHistoryCache = null;
    let localInputHistorySaveTimer = null;

    function getLocalInputHistory() {
      if (!Array.isArray(localInputHistoryCache)) {
        try {
          const raw = JSON.parse(localStorage.getItem(INPUT_HISTORY_KEY) || '[]');
          localInputHistoryCache = Array.isArray(raw)
            ? raw.map(sanitizeInputHistoryEntry).filter(Boolean)
            : [];
        } catch (e) {
          localInputHistoryCache = [];
        }
      }
      const replaceOldKeys = typeof pendingHistoryReplaceOldContentKeys === 'function'
        ? pendingHistoryReplaceOldContentKeys()
        : null;
      return localInputHistoryCache
        .filter((e) => e && !(typeof isInputHistoryTombstoned === 'function' && isInputHistoryTombstoned(e)))
        .filter((e) => {
          const k = dumpContentKey(e && e.content);
          if (!k) return false;
          if (inputHistorySuppressedContents.has(k)) return false;
          if (replaceOldKeys && replaceOldKeys.has(k)) return false;
          return true;
        });
    }

    function flushLocalInputHistoryCache() {
      if (localInputHistorySaveTimer) {
        clearTimeout(localInputHistorySaveTimer);
        localInputHistorySaveTimer = null;
      }
      if (!Array.isArray(localInputHistoryCache)) return;
      try {
        localStorage.setItem(INPUT_HISTORY_KEY, JSON.stringify(localInputHistoryCache.slice(0, INPUT_HISTORY_MAX)));
      } catch (e) { }
    }

    function cacheLocalInputHistory(history) {
      const cleaned = (history || [])
        .map(sanitizeInputHistoryEntry)
        .filter(Boolean)
        .filter((e) => !(typeof isInputHistoryTombstoned === 'function' && isInputHistoryTombstoned(e)))
        .filter((e) => !inputHistorySuppressedContents.has(dumpContentKey(e.content)));
      // 同じ本文は1件に畳む（先勝ち＝呼び出し側が新しいものを先頭にしている想定）
      const seenContent = new Set();
      const deduped = [];
      cleaned.forEach((e) => {
        const k = dumpContentKey(e && e.content);
        if (!k || seenContent.has(k)) return;
        seenContent.add(k);
        deduped.push(e);
      });
      localInputHistoryCache = deduped.slice(0, INPUT_HISTORY_MAX);
      if (localInputHistorySaveTimer) clearTimeout(localInputHistorySaveTimer);
      localInputHistorySaveTimer = setTimeout(() => {
        localInputHistorySaveTimer = null;
        try {
          localStorage.setItem(INPUT_HISTORY_KEY, JSON.stringify(localInputHistoryCache));
        } catch (e) { }
      }, 400);
    }
    function getPendingInputHistoryIds() {
      try {
        const raw = JSON.parse(localStorage.getItem(INPUT_HISTORY_PENDING_KEY) || '[]');
        return new Set((Array.isArray(raw) ? raw : []).map(String).filter(Boolean));
      } catch (e) {
        return new Set();
      }
    }
    function savePendingInputHistoryIds(ids) {
      const list = [...(ids || [])].map(String).filter(Boolean).slice(0, INPUT_HISTORY_MAX);
      localStorage.setItem(INPUT_HISTORY_PENDING_KEY, JSON.stringify(list));
    }
    function addPendingInputHistoryIds(ids) {
      const next = getPendingInputHistoryIds();
      (ids || []).forEach((id) => {
        if (id) next.add(String(id));
      });
      savePendingInputHistoryIds(next);
    }
    function clearPendingInputHistoryByContent(contents) {
      const keys = new Set((contents || []).map((c) => dumpContentKey(c)).filter(Boolean));
      if (!keys.size) return;
      const pending = getPendingInputHistoryIds();
      getLocalInputHistory().forEach((e) => {
        if (!e || e.id == null) return;
        if (pending.has(String(e.id)) && keys.has(dumpContentKey(e.content))) {
          pending.delete(String(e.id));
        }
      });
      savePendingInputHistoryIds(pending);
    }
    function persistHistoryTombstones() {
      try {
        localStorage.setItem(INPUT_HISTORY_TOMBSTONE_STORE, JSON.stringify({
          ids: [...inputHistoryTombstoneIds].slice(-300),
          keys: [...inputHistoryTombstoneKeys].slice(-300)
        }));
      } catch (e) { }
    }
    function loadHistoryTombstones() {
      try {
        const raw = JSON.parse(localStorage.getItem(INPUT_HISTORY_TOMBSTONE_STORE) || '{}');
        (Array.isArray(raw.ids) ? raw.ids : []).forEach((id) => inputHistoryTombstoneIds.add(String(id)));
        (Array.isArray(raw.keys) ? raw.keys : []).forEach((k) => inputHistoryTombstoneKeys.add(String(k)));
      } catch (e) { }
    }
    function persistInputHistoryResurrectedKeys() {
      try {
        localStorage.setItem(
          INPUT_HISTORY_RESURRECTED_STORE,
          JSON.stringify([...inputHistoryResurrectedKeys].slice(-500))
        );
      } catch (e) { }
    }
    function loadInputHistoryResurrectedKeys() {
      try {
        const raw = JSON.parse(localStorage.getItem(INPUT_HISTORY_RESURRECTED_STORE) || '[]');
        (Array.isArray(raw) ? raw : []).forEach((k) => {
          if (k) inputHistoryResurrectedKeys.add(String(k));
        });
      } catch (e) { }
      // 復活済み本文はローカル tombstone / suppress を外す
      inputHistoryResurrectedKeys.forEach((k) => {
        inputHistoryTombstoneKeys.delete(k);
        inputHistorySuppressedContents.delete(k);
      });
    }
    function markInputHistoryResurrected(content) {
      const key = dumpContentKey(content);
      if (!key) return;
      inputHistoryResurrectedKeys.add(key);
      inputHistoryTombstoneKeys.delete(key);
      inputHistorySuppressedContents.delete(key);
      persistInputHistoryResurrectedKeys();
      if (typeof persistHistoryTombstones === 'function') persistHistoryTombstones();
    }
    function clearInputHistoryResurrected(content) {
      const key = dumpContentKey(content);
      if (!key) return;
      if (!inputHistoryResurrectedKeys.has(key)) return;
      inputHistoryResurrectedKeys.delete(key);
      persistInputHistoryResurrectedKeys();
    }
    function isInputHistoryResurrectedKey(keyOrContent) {
      if (!keyOrContent) return false;
      if (inputHistoryResurrectedKeys.has(String(keyOrContent))) return true;
      const key = dumpContentKey(keyOrContent);
      return !!(key && inputHistoryResurrectedKeys.has(key));
    }

    function getPendingInputHistoryDeletes() {
      try {
        const raw = JSON.parse(localStorage.getItem(INPUT_HISTORY_DELETE_PENDING_KEY) || '[]');
        return (Array.isArray(raw) ? raw : [])
          .filter((e) => e && (e.id || e.content))
          .slice(-80);
      } catch (e) {
        return [];
      }
    }
    function savePendingInputHistoryDeletes(list) {
      try {
        localStorage.setItem(
          INPUT_HISTORY_DELETE_PENDING_KEY,
          JSON.stringify((list || []).filter((e) => e && (e.id || e.content)).slice(-80))
        );
      } catch (e) { }
    }
    function queuePendingInputHistoryDelete(historyId, content) {
      const id = historyId != null ? String(historyId) : '';
      const contentKey = dumpContentKey(content);
      if (!id && !contentKey) return;
      const next = getPendingInputHistoryDeletes().filter((e) => {
        if (id && e.id && sameInputHistoryId(e.id, id)) return false;
        if (contentKey && dumpContentKey(e.content) === contentKey) return false;
        return true;
      });
      next.push({
        id: id && !isLocalOnlyHistoryId(id) ? id : '',
        content: content || '',
        contentKey,
        queuedAt: new Date().toISOString()
      });
      savePendingInputHistoryDeletes(next);
    }
    function clearPendingInputHistoryDelete(historyId, content) {
      const id = historyId != null ? String(historyId) : '';
      const contentKey = dumpContentKey(content);
      const next = getPendingInputHistoryDeletes().filter((e) => {
        if (id && e.id && sameInputHistoryId(e.id, id)) return false;
        if (contentKey && (dumpContentKey(e.content) === contentKey || e.contentKey === contentKey)) return false;
        return true;
      });
      savePendingInputHistoryDeletes(next);
    }

    /** クラウド上の input_history を直接走査し、本文一致の実IDを集める（キャッシュ非依存） */
    async function findCloudInputHistoryIdsByContent(content) {
      const contentKey = dumpContentKey(content);
      if (!contentKey) return [];
      const items = await callAPI('getFolderFileItems', { folder: '__SYSTEM__', file: 'input_history' }, { silent: true });
      if (!Array.isArray(items)) throw new Error('cloud_history_lookup');
      const ids = [];
      items.forEach((row) => {
        if (!row || row.id == null) return;
        const parsed = parseInputHistoryRecord(row);
        if (!parsed || parsed.tombstone) return;
        const safe = sanitizeInputHistoryEntry(parsed);
        if (!safe || !safe.id || isLocalOnlyHistoryId(safe.id)) return;
        if (dumpContentEquals(safe.content, content)) ids.push(String(safe.id));
      });
      return [...new Set(ids)];
    }

    async function flushPendingInputHistoryDeletes(options) {
      options = options || {};
      const pending = getPendingInputHistoryDeletes();
      if (!pending.length) return;
      const keep = [];
      for (const item of pending) {
        const ck = item.contentKey || dumpContentKey(item.content || '');
        // 検索ダンプから復活させた本文は、古い削除キューで再 tombstone しない
        if (ck && typeof isInputHistoryResurrectedKey === 'function' && isInputHistoryResurrectedKey(ck)) {
          clearPendingInputHistoryDelete(item.id, item.content || item.contentKey);
          continue;
        }
        try {
          await syncInputHistoryDeleteToCloud(item.id, item.content || item.contentKey);
          clearPendingInputHistoryDelete(item.id, item.content || item.contentKey);
        } catch (e) {
          console.warn('pending history delete retry failed', e);
          keep.push(item);
          if (!options.silent) throw e;
        }
      }
      if (keep.length !== pending.length) savePendingInputHistoryDeletes(keep);
    }
    function encodeInputHistoryPayload(content, folder, file, updatedAt) {
      if (!isUsableInputHistoryContent(content)) return '';
      return JSON.stringify({
        content: content,
        folder: folder || 'INBOX',
        file: file || '未整理',
        updatedAt: updatedAt || new Date().toISOString()
      });
    }

    /** 削除マーカーJSONが本文として混入しているかを検出 */
    function parseInputHistoryTombstonePayload(text) {
      if (text && typeof text === 'object' && !Array.isArray(text)) {
        if (text.deleted) return text;
        return null;
      }
      let raw = String(text || '').trim();
      if (!raw) return null;
      // 前後にゴミが付いていても最初の JSON オブジェクトを拾う
      if (raw.charAt(0) !== '{') {
        const start = raw.indexOf('{');
        const end = raw.lastIndexOf('}');
        if (start < 0 || end <= start) return null;
        raw = raw.slice(start, end + 1);
      }
      if (raw.indexOf('deleted') === -1) return null;
      try {
        const obj = JSON.parse(raw);
        if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return null;
        if (!(obj.deleted === true || obj.deleted === 'true' || obj.deleted === 1)) return null;
        return obj;
      } catch (e) {
        return null;
      }
    }

    function looksLikeInputHistoryTombstoneText(text) {
      if (parseInputHistoryTombstonePayload(text)) return true;
      const raw = String(text || '');
      if (!raw) return false;
      // パース不能でも削除マーカーっぽい文字列は本文扱いにしない
      if (/[{,]\s*"deleted"\s*:\s*true\b/.test(raw)
        && (/[{,]\s*"contentKey"\s*:/.test(raw) || /[{,]\s*"deletedAt"\s*:/.test(raw))) {
        return true;
      }
      return false;
    }

    function isInputHistoryTombstoneText(text) {
      return looksLikeInputHistoryTombstoneText(text);
    }

    function isUsableInputHistoryContent(content) {
      if (content && typeof content === 'object' && !Array.isArray(content)) {
        if (content.deleted) return false;
        if (Object.prototype.hasOwnProperty.call(content, 'content')) {
          return isUsableInputHistoryContent(content.content);
        }
        return false;
      }
      const text = String(content || '').trim();
      if (!text) return false;
      if (isInputHistoryTombstoneText(text)) return false;
      return true;
    }

    /** 表示・保存前に履歴1件を正規化。削除マーカーなら null */
    function sanitizeInputHistoryEntry(entry) {
      if (!entry || typeof entry !== 'object') return null;
      if (entry.tombstone) return null;
      let content = entry.content;
      if (content && typeof content === 'object' && !Array.isArray(content)) {
        if (content.deleted) {
          rememberInputHistoryTombstone(content.id || entry.id, content.contentKey || content.content || '');
          return null;
        }
        content = content.content != null ? content.content : '';
      }
      content = String(content || '');
      if (!isUsableInputHistoryContent(content)) {
        const nest = parseInputHistoryTombstonePayload(content);
        if (nest) {
          rememberInputHistoryTombstone(nest.id || entry.id, nest.contentKey || nest.content || '');
        }
        return null;
      }
      return { ...entry, content };
    }

    /** localStorage に残った削除マーカー本文を強制掃除 */
    function purgeCorruptLocalInputHistory() {
      try {
        const raw = JSON.parse(localStorage.getItem(INPUT_HISTORY_KEY) || '[]');
        if (!Array.isArray(raw)) {
          localStorage.setItem(INPUT_HISTORY_KEY, '[]');
          return [];
        }
        let changed = false;
        const cleaned = [];
        raw.forEach((e) => {
          const safe = sanitizeInputHistoryEntry(e);
          if (!safe) {
            changed = true;
            return;
          }
          if (safe.content !== e.content) changed = true;
          cleaned.push(safe);
        });
        if (changed || cleaned.length !== raw.length) {
          localStorage.setItem(INPUT_HISTORY_KEY, JSON.stringify(cleaned.slice(0, INPUT_HISTORY_MAX)));
        }
        return cleaned;
      } catch (e) {
        try { localStorage.setItem(INPUT_HISTORY_KEY, '[]'); } catch (_) { }
        return [];
      }
    }

    function parseInputHistoryRecord(row) {
      if (!row) return null;
      let payload = null;
      try {
        payload = JSON.parse(row.content);
      } catch (e) {
        payload = null;
      }
      if (payload && typeof payload === 'object' && payload.deleted) {
        let nestedKey = payload.contentKey || '';
        // contentKey 自体が tombstone JSON になっている二重マーカーをほどく
        const nested = parseInputHistoryTombstonePayload(nestedKey);
        if (nested) {
          nestedKey = nested.contentKey || dumpContentKey(nested.content || '') || '';
        }
        return {
          tombstone: true,
          id: row.id,
          deletedId: payload.id || (nested && nested.id) || '',
          contentKey: nestedKey || dumpContentKey(payload.content || ''),
          timestamp: payload.deletedAt || row.timestamp || ''
        };
      }
      if (payload && typeof payload === 'object' && Object.prototype.hasOwnProperty.call(payload, 'content')) {
        // encodeInputHistoryPayload で tombstone 文字列が本文に包まれたケース
        if (isInputHistoryTombstoneText(payload.content)) {
          const nested = parseInputHistoryTombstonePayload(payload.content);
          return {
            tombstone: true,
            id: row.id,
            deletedId: (nested && nested.id) || '',
            contentKey: (nested && (nested.contentKey || dumpContentKey(nested.content || ''))) || '',
            timestamp: payload.updatedAt || (nested && nested.deletedAt) || row.timestamp || ''
          };
        }
        if (!String(payload.content || '').trim()) return null;
        return {
          id: row.id,
          timestamp: payload.updatedAt || row.timestamp || '',
          content: payload.content,
          folder: payload.folder || 'INBOX',
          file: payload.file || '未整理'
        };
      }
      // 旧ローカル形式やプレーンテキストのフォールバック
      if (isInputHistoryTombstoneText(row.content)) {
        const nested = parseInputHistoryTombstonePayload(row.content);
        return {
          tombstone: true,
          id: row.id,
          deletedId: (nested && nested.id) || '',
          contentKey: (nested && (nested.contentKey || dumpContentKey(nested.content || ''))) || '',
          timestamp: (nested && nested.deletedAt) || row.timestamp || ''
        };
      }
      return {
        id: row.id,
        timestamp: row.timestamp || '',
        content: row.content || '',
        folder: 'INBOX',
        file: '未整理'
      };
    }
    function rememberInputHistoryTombstone(historyId, content) {
      const sid = historyId != null ? String(historyId) : '';
      if (sid && !isLocalOnlyHistoryId(sid)) inputHistoryTombstoneIds.add(sid);
      const key = dumpContentKey(content);
      if (key) {
        // ユーザーが明示削除したときは復活保護を外す
        if (typeof clearInputHistoryResurrected === 'function') clearInputHistoryResurrected(content);
        inputHistoryTombstoneKeys.add(key);
      }
      persistHistoryTombstones();
    }
    function rememberFetchedInputHistoryTombstones(tombstones) {
      let changed = false;
      (tombstones || []).forEach((t) => {
        if (!t) return;
        if (t.deletedId) {
          inputHistoryTombstoneIds.add(String(t.deletedId));
          changed = true;
        }
        if (t.contentKey) {
          const ck = String(t.contentKey);
          // 生きているダンプから戻した本文は、クラウドの古い削除マーカーで再隠蔽しない
          if (typeof isInputHistoryResurrectedKey === 'function' && isInputHistoryResurrectedKey(ck)) return;
          inputHistoryTombstoneKeys.add(ck);
          changed = true;
        }
      });
      if (changed) persistHistoryTombstones();
    }
    function clearInputHistoryTombstoneForContent(content) {
      const key = dumpContentKey(content);
      if (!key) return;
      inputHistoryTombstoneKeys.delete(key);
      inputHistorySuppressedContents.delete(key);
    }
    function isInputHistoryTombstoned(entry) {
      if (!entry) return false;
      const key = dumpContentKey(entry.content);
      if (key && typeof isInputHistoryResurrectedKey === 'function' && isInputHistoryResurrectedKey(key)) {
        return false;
      }
      const id = entry.id != null ? String(entry.id) : '';
      if (id && inputHistoryTombstoneIds.has(id)) return true;
      return !!(key && inputHistoryTombstoneKeys.has(key));
    }
    async function pushInputHistoryTombstone(historyId, content) {
      // 削除マーカー自体を contentKey にすると二重 tombstone が増殖する
      if (isInputHistoryTombstoneText(content)) {
        const nested = parseInputHistoryTombstonePayload(content);
        const nestedKey = nested && (nested.contentKey || dumpContentKey(nested.content || ''));
        if (nestedKey) rememberInputHistoryTombstone(historyId || (nested && nested.id), nestedKey);
        return;
      }
      rememberInputHistoryTombstone(historyId, content);
      const contentKey = dumpContentKey(content);
      if (!contentKey && isLocalOnlyHistoryId(historyId)) return;
      await ensureInputHistoryStore();
      const res = await callAPI('addDataRecord', {
        folder: '__SYSTEM__',
        file: 'input_history',
        content: JSON.stringify({
          deleted: true,
          id: isLocalOnlyHistoryId(historyId) ? '' : String(historyId || ''),
          contentKey,
          deletedAt: new Date().toISOString()
        })
      }, { silent: true });
      if (isApiFailure(res)) throw new Error('tombstone_push');
      invalidateCloudInputHistoryCache();
    }
    let inputHistoryStoreEnsured = false;
    async function ensureInputHistoryStore() {
      if (isInputHistoryStoreReadyLocally()) return;
      await callAPI('addConfigRecord', { folder: '__SYSTEM__', file: 'input_history' }, { silent: true });
      markInputHistoryStoreReady();
    }

    let cloudInputHistoryCache = { at: 0, live: null, promise: null };
    const CLOUD_INPUT_HISTORY_TTL_MS = 2800;

    function invalidateCloudInputHistoryCache() {
      cloudInputHistoryCache = { at: 0, live: null, promise: null };
    }

    async function fetchCloudInputHistory(options) {
      options = options || {};
      const force = !!options.force;
      const includeSuppressedContent = !!options.includeSuppressedContent;
      const maxAge = options.maxAgeMs != null ? Number(options.maxAgeMs) : CLOUD_INPUT_HISTORY_TTL_MS;
      // includeSuppressedContent は置換用の未フィルタ取得。通常キャッシュは使わない
      if (!includeSuppressedContent && !force && cloudInputHistoryCache.live
        && (Date.now() - cloudInputHistoryCache.at) < maxAge) {
        return cloudInputHistoryCache.live;
      }
      if (!includeSuppressedContent && !force && cloudInputHistoryCache.promise) {
        return cloudInputHistoryCache.promise;
      }

      const promise = (async () => {
        const items = await callAPI('getFolderFileItems', { folder: '__SYSTEM__', file: 'input_history' }, { silent: true });
        if (!Array.isArray(items)) {
          if (!includeSuppressedContent) invalidateCloudInputHistoryCache();
          return null;
        }
        const parsed = items.map(parseInputHistoryRecord).filter(Boolean);
        rememberFetchedInputHistoryTombstones(parsed.filter((e) => e && e.tombstone));

        // 削除マーカーが本文として保存された壊れたレコードを掃除
        const corruptIds = [];
        (items || []).forEach((row) => {
          if (!row || row.id == null || !row.content) return;
          let payload = null;
          try {
            payload = JSON.parse(row.content);
          } catch (e) {
            payload = null;
          }
          // 正規の tombstone（deleted:true）はクラウドに残す（同期用）が、二重マーカーは削除
          if (payload && typeof payload === 'object' && (payload.deleted === true || payload.deleted === 'true')) {
            if (isInputHistoryTombstoneText(payload.contentKey) || isInputHistoryTombstoneText(payload.content)) {
              corruptIds.push(String(row.id));
            }
            return;
          }
          // encode 済み履歴の本文が tombstone JSON → 表示に出る壊れた行なので削除
          if (payload && typeof payload === 'object' && isInputHistoryTombstoneText(payload.content)) {
            corruptIds.push(String(row.id));
            return;
          }
          // プレーン本文が tombstone JSON なのに deleted フラグ無し／パース不能 → 削除
          if (isInputHistoryTombstoneText(row.content)) {
            // 上で正規 tombstone は return 済み。ここに来るのは壊れた行のみ
            corruptIds.push(String(row.id));
          }
        });
        if (corruptIds.length) {
          runInBackground(async () => {
            try {
              if (corruptIds.length === 1) {
                await callAPI('deleteDataRecord', { id: corruptIds[0] }, { silent: true });
              } else {
                await callAPI('deleteDataRecords', { ids: corruptIds }, { silent: true });
              }
              invalidateCloudInputHistoryCache();
            } catch (e) {
              console.warn('Failed to purge corrupt input history tombstone rows', e);
            }
          });
        }

        const live = parsed
          .map((e) => (e && e.tombstone ? null : sanitizeInputHistoryEntry(e)))
          .filter(Boolean)
          .filter((e) => {
            if (!e) return false;
            const id = e.id != null ? String(e.id) : '';
            // 削除済み ID は常に除外。置換用取得では本文 tombstone で落とさない（旧行を update するため）
            if (id && inputHistoryTombstoneIds.has(id)) return false;
            if (includeSuppressedContent) return true;
            return !(typeof isInputHistoryTombstoned === 'function' && isInputHistoryTombstoned(e));
          });
        // 新しい順（timestamp 降順）。同値なら末尾の方が新しい想定で reverse 後に sort
        live.sort((a, b) => {
          const ta = getSearchTimestampMs(a);
          const tb = getSearchTimestampMs(b);
          return tb - ta;
        });
        const sliced = live.slice(0, INPUT_HISTORY_MAX);
        if (!includeSuppressedContent) {
          cloudInputHistoryCache = { at: Date.now(), live: sliced, promise: null };
        }
        return sliced;
      })();

      if (!includeSuppressedContent) {
        cloudInputHistoryCache.promise = promise;
      }
      try {
        return await promise;
      } catch (e) {
        if (!includeSuppressedContent) invalidateCloudInputHistoryCache();
        throw e;
      } finally {
        if (!includeSuppressedContent && cloudInputHistoryCache.promise === promise) {
          cloudInputHistoryCache.promise = null;
        }
      }
    }
    async function getInputHistory() {
      try {
        const cloud = await fetchCloudInputHistory({ force: true });
        if (cloud) return mergeLocalAndCloudHistory(cloud);
      } catch (e) { }
      return getLocalInputHistory().filter((e) => {
        if (!e || !e.content) return false;
        return !inputHistorySuppressedContents.has(dumpContentKey(e.content));
      });
    }
    function saveInputHistory(history) {
      // 互換用: ローカルキャッシュのみ更新（クラウドへの一括上書きはしない）
      cacheLocalInputHistory(history);
    }
    async function migrateInputHistoryFromOperations() {
      if (localStorage.getItem('input_history_migrated') === 'true') return;
      try {
        const ops = JSON.parse(localStorage.getItem('operation_history') || '[]');
        const entries = [];
        (Array.isArray(ops) ? ops : []).forEach(op => {
          if (op.type !== 'ADD' || !op.payload || !Array.isArray(op.payload.contents)) return;
          op.payload.contents.forEach((content, i) => {
            if (!content || !String(content).trim()) return;
            entries.push({
              id: `mig-${op.id}-${i}`,
              timestamp: op.timestamp || new Date().toISOString(),
              content,
              folder: op.payload.folder || 'INBOX',
              file: op.payload.file || '未整理'
            });
          });
        });
        if (entries.length > 0) {
          cacheLocalInputHistory(entries.concat(getLocalInputHistory()));
        }
      } catch (e) { }
      localStorage.setItem('input_history_migrated', 'true');
    }

    async function migrateLocalInputHistoryToCloud() {
      if (localStorage.getItem('input_history_cloud_migrated') === 'true') return;
      const local = getLocalInputHistory();
      if (local.length === 0) {
        localStorage.setItem('input_history_cloud_migrated', 'true');
        return;
      }
      try {
        await ensureInputHistoryStore();
        let cloud = [];
        try {
          cloud = (await fetchCloudInputHistory()) || [];
        } catch (e) {
          cloud = [];
        }
        const existingKeys = new Set(cloud.map(e => `${e.folder}::${e.file}::${e.content}`));
        const toUpload = [...local].reverse().filter(e => {
          if (!e || !isUsableInputHistoryContent(e.content)) return false;
          if (isInputHistoryTombstoned(e)) return false;
          // クラウドID付きは同期済み。欠落は他端末での削除なので再アップロードしない
          if (!isLocalOnlyHistoryId(e.id)) return false;
          const key = `${e.folder || 'INBOX'}::${e.file || '未整理'}::${e.content}`;
          if (existingKeys.has(key)) return false;
          existingKeys.add(key);
          return true;
        });
        if (toUpload.length > 0) {
          const items = toUpload.map(e => {
            const encoded = encodeInputHistoryPayload(e.content, e.folder, e.file);
            if (!encoded) return null;
            return { folder: '__SYSTEM__', file: 'input_history', content: encoded };
          }).filter(Boolean);
          if (items.length) {
            await callAPI('addManyDataRecords', { items }, { silent: true });
          }
        }
        localStorage.setItem('input_history_cloud_migrated', 'true');
      } catch (e) {
        console.error('Failed to migrate input history to cloud', e);
      }
    }

    function appendLocalInputHistory(contents, folder, file) {
      const chunks = (contents || [])
        .filter((c) => c && String(c).trim())
        .filter((c) => isUsableInputHistoryContent(c));
      if (chunks.length === 0) return [];
      const now = new Date().toISOString();
      chunks.forEach((content) => clearInputHistoryTombstoneForContent(content));
      const localEntries = chunks.map((content, i) => ({
        id: `local-${Date.now()}-${i}-${Math.random().toString(36).slice(2, 7)}`,
        timestamp: now,
        content,
        folder: folder || 'INBOX',
        file: file || '未整理'
      }));
      addPendingInputHistoryIds(localEntries.map((e) => e.id));
      cacheLocalInputHistory(localEntries.concat(getLocalInputHistory()));
      return localEntries;
    }

    /**
     * 検索（INBOX/DATA）にあるのに登録チェック（input_history）から欠けた分を補完する。
     * 誤 tombstone も、実データが生きていれば取り消す。
     */
    async function backfillInputHistoryFromLiveDumps(options) {
      options = options || {};
      if (typeof collectAllStoredItems !== 'function') return 0;
      let items = [];
      try {
        items = await collectAllStoredItems(!!options.forceStored);
      } catch (e) {
        console.warn('backfillInputHistoryFromLiveDumps collect', e);
        return 0;
      }
      if (!Array.isArray(items) || !items.length) return 0;

      const existingKeys = new Set();
      // 表示中・生存中の履歴本文だけを「既にある」とみなす（tombstone 済みは再取り込み対象）
      const rawHist = Array.isArray(localInputHistoryCache) ? localInputHistoryCache : [];
      rawHist.forEach((e) => {
        if (!e || !isUsableInputHistoryContent(e.content)) return;
        if (typeof isInputHistoryTombstoned === 'function' && isInputHistoryTombstoned(e)) return;
        const k = dumpContentKey(e.content);
        if (k && inputHistorySuppressedContents.has(k)) return;
        if (k) existingKeys.add(k);
      });
      getLocalInputHistory().forEach((e) => {
        const k = dumpContentKey(e && e.content);
        if (k) existingKeys.add(k);
      });

      const cutoffMs = Date.now() - (180 * 86400000);
      const candidates = [];
      for (let i = 0; i < items.length; i++) {
        const item = items[i];
        if (!item || typeof isNonUserDumpItem === 'function' && isNonUserDumpItem(item)) continue;
        if (typeof isTempId === 'function' && isTempId(item.id)) continue;
        if (!isUsableInputHistoryContent(item.content)) continue;
        const key = dumpContentKey(item.content);
        if (!key || existingKeys.has(key)) continue;
        // 編集で隠した本文／編集中の変更前本文は、サーバーに残っていても登録チェックへ戻さない
        if (inputHistorySuppressedContents.has(key)) continue;
        if (typeof pendingHistoryReplaceOldContentKeys === 'function'
          && pendingHistoryReplaceOldContentKeys().has(key)) continue;
        if (inputHistoryTombstoneKeys.has(key)
          && !(typeof isInputHistoryResurrectedKey === 'function' && isInputHistoryResurrectedKey(key))) continue;
        const ts = (typeof getSearchTimestampMs === 'function' ? getSearchTimestampMs(item) : 0) || 0;
        if (ts && ts < cutoffMs) continue;
        candidates.push(item);
      }
      if (!candidates.length) return 0;

      candidates.sort((a, b) => {
        const ta = (typeof getSearchTimestampMs === 'function' ? getSearchTimestampMs(a) : 0) || 0;
        const tb = (typeof getSearchTimestampMs === 'function' ? getSearchTimestampMs(b) : 0) || 0;
        return tb - ta;
      });
      const batch = candidates.slice(0, 120);
      const revokeContents = [];
      const localEntries = [];
      const cloudItems = [];

      batch.forEach((item) => {
        const key = dumpContentKey(item.content);
        if (!key || existingKeys.has(key)) return;
        existingKeys.add(key);
        revokeContents.push(item.content);
        const isInbox = !!(item.isInbox || (typeof historyDestIsInbox === 'function' && historyDestIsInbox(item.folder)));
        const folder = isInbox
          ? 'INBOX'
          : (typeof normalizeHistoryFolder === 'function' ? normalizeHistoryFolder(item.folder) : String(item.folder || 'INBOX'));
        const file = isInbox ? '未整理' : (item.file || '未整理');
        const tsMs = (typeof getSearchTimestampMs === 'function' ? getSearchTimestampMs(item) : 0) || Date.now();
        let timestamp = item.timestamp;
        if (!timestamp || typeof timestamp !== 'string') {
          try { timestamp = new Date(tsMs).toISOString(); } catch (_) { timestamp = new Date().toISOString(); }
        }
        const entry = {
          id: `local-bf-${String(item.id)}-${Math.random().toString(36).slice(2, 6)}`,
          timestamp,
          content: item.content,
          folder,
          file,
          dumpId: item.id,
          dumpIsInbox: isInbox
        };
        localEntries.push(entry);
        const encoded = typeof encodeInputHistoryPayload === 'function'
          ? encodeInputHistoryPayload(item.content, folder, file, timestamp)
          : '';
        if (encoded) {
          cloudItems.push({ folder: '__SYSTEM__', file: 'input_history', content: encoded });
        }
      });

      if (!localEntries.length) return 0;

      // 先に復活保護＋削除キュー除去（並行同期が tombstone を戻しても消えないように）
      revokeContents.forEach((c) => {
        if (typeof markInputHistoryResurrected === 'function') markInputHistoryResurrected(c);
        else clearInputHistoryTombstoneForContent(c);
        if (typeof clearPendingInputHistoryDelete === 'function') {
          clearPendingInputHistoryDelete('', c);
        }
      });

      if (revokeContents.length && typeof revokeInputHistoryTombstonesForContents === 'function') {
        try {
          await revokeInputHistoryTombstonesForContents(revokeContents);
          // revoke 後も復活フラグは維持（クラウド削除が遅延しても再隠蔽されない）
          revokeContents.forEach((c) => {
            if (typeof markInputHistoryResurrected === 'function') markInputHistoryResurrected(c);
          });
        } catch (e) {
          console.warn('backfill revoke tombstones', e);
          revokeContents.forEach((c) => {
            clearInputHistoryTombstoneForContent(c);
            if (typeof markInputHistoryResurrected === 'function') markInputHistoryResurrected(c);
          });
          if (typeof persistHistoryTombstones === 'function') persistHistoryTombstones();
        }
      }

      addPendingInputHistoryIds(localEntries.map((e) => e.id));
      cacheLocalInputHistory(localEntries.concat(
        Array.isArray(localInputHistoryCache) ? localInputHistoryCache : getLocalInputHistory()
      ));
      if (typeof flushLocalInputHistoryCache === 'function') flushLocalInputHistoryCache();

      if (cloudItems.length) {
        try {
          await ensureInputHistoryStore();
          const writeRes = await callAPI('addManyDataRecords', { items: cloudItems }, { silent: true });
          if (!isApiFailure(writeRes)) {
            invalidateCloudInputHistoryCache();
          }
        } catch (e) {
          console.warn('backfill history cloud write', e);
        }
      }
      return localEntries.length;
    }

    function historyEntryKey(entry) {
      return `${entry.folder || 'INBOX'}::${entry.file || '未整理'}::${entry.content || ''}`;
    }

    function historyEntryTimestampMs(entry) {
      if (!entry) return 0;
      if (typeof getSearchTimestampMs === 'function') return getSearchTimestampMs(entry) || 0;
      const ms = new Date(entry.timestamp || 0).getTime();
      return Number.isFinite(ms) ? ms : 0;
    }

    function isLocalOnlyHistoryId(id) {
      const s = String(id || '');
      return !s || s.startsWith('local-') || s.startsWith('mig-');
    }

    function pickNewerHistoryEntry(localEntry, cloudEntry) {
      const localMs = historyEntryTimestampMs(localEntry);
      const cloudMs = historyEntryTimestampMs(cloudEntry);
      const cloudId = cloudEntry && cloudEntry.id != null ? String(cloudEntry.id) : '';
      if (cloudMs > localMs) {
        return { ...cloudEntry, id: cloudId || localEntry.id };
      }
      if (localMs > cloudMs) {
        return { ...localEntry, id: cloudId || localEntry.id };
      }
      if (!isLocalOnlyHistoryId(cloudId) && isLocalOnlyHistoryId(localEntry.id)) {
        return { ...cloudEntry, id: cloudId || localEntry.id };
      }
      return { ...localEntry, id: cloudId || localEntry.id };
    }

    function pruneStaleLocalInputHistory() {
      const pending = getPendingInputHistoryIds();
      // getLocalInputHistory は tombstone/suppress 済みを既に除外する。
      // 生キャッシュを見て、クラウドID版が揃った local-* だけ捨てる（同期失敗で登録チェックから消えるのを防ぐ）
      const raw = Array.isArray(localInputHistoryCache)
        ? localInputHistoryCache
        : (typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : []);
      const cloudLikeKeys = new Set();
      raw.forEach((e) => {
        if (!e || !isUsableInputHistoryContent(e.content)) return;
        const id = e.id != null ? String(e.id) : '';
        if (isLocalOnlyHistoryId(id)) return;
        if (typeof isInputHistoryTombstoned === 'function' && isInputHistoryTombstoned(e)) return;
        const k = dumpContentKey(e.content);
        if (k) cloudLikeKeys.add(k);
      });
      const next = raw.filter((e) => {
        if (!e || !isUsableInputHistoryContent(e.content)) return false;
        if (inputHistorySuppressedContents.has(dumpContentKey(e.content))) return false;
        if (isInputHistoryTombstoned(e)) return false;
        const id = e.id != null ? String(e.id) : '';
        if (isLocalOnlyHistoryId(id) && !pending.has(id)) {
          const k = dumpContentKey(e.content);
          // 同じ本文のクラウドID行があるときだけ local-* を捨てる
          if (k && cloudLikeKeys.has(k)) return false;
          return true;
        }
        return true;
      });
      if (next.length !== raw.length) cacheLocalInputHistory(next);
      return typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : next;
    }

    function mergeLocalAndCloudHistory(cloud) {
      const replaceOldKeys = pendingHistoryReplaceOldContentKeys();
      const cloudList = (Array.isArray(cloud) ? cloud : []).map(sanitizeInputHistoryEntry).filter(Boolean)
        .filter((e) => {
          if (!e) return false;
          const ck = dumpContentKey(e.content);
          if (ck && (inputHistorySuppressedContents.has(ck) || replaceOldKeys.has(ck))) return false;
          if (typeof isInputHistoryTombstoned === 'function' && isInputHistoryTombstoned(e)) return false;
          return true;
        });
      const cloudById = new Map();
      const cloudContentKeys = new Set();
      cloudList.forEach((e) => {
        if (e.id != null) cloudById.set(String(e.id), e);
        const ck = dumpContentKey(e.content);
        if (ck) cloudContentKeys.add(ck);
      });

      const local = getLocalInputHistory().filter((e) => {
        if (!e || !isUsableInputHistoryContent(e.content)) return false;
        const ck = dumpContentKey(e.content);
        if (ck && (inputHistorySuppressedContents.has(ck) || replaceOldKeys.has(ck))) return false;
        if (typeof isInputHistoryTombstoned === 'function' && isInputHistoryTombstoned(e)) return false;
        return true;
      });
      const localById = new Map();
      local.forEach((e) => {
        if (e.id != null) localById.set(String(e.id), e);
      });

      const pendingIds = getPendingInputHistoryIds();
      const stillPending = new Set();
      const usedContent = new Set();
      const usedIds = new Set();
      const localContentOverrides = new Map();
      const out = [];

      const pushEntry = (e) => {
        if (!e || !e.content) return;
        const id = e.id != null ? String(e.id) : '';
        const k = dumpContentKey(e.content);
        if (k && (usedContent.has(k) || replaceOldKeys.has(k) || inputHistorySuppressedContents.has(k))) return;
        if (id && usedIds.has(id)) return;
        if (k) usedContent.add(k);
        if (id) usedIds.add(id);
        out.push(e);
      };

      local.forEach((e) => {
        const id = e.id != null ? String(e.id) : '';
        if (!isLocalOnlyHistoryId(id) || !pendingIds.has(id)) return;
        const contentKey = dumpContentKey(e.content);
        if (contentKey && cloudContentKeys.has(contentKey)) {
          // 同じ本文がクラウドにある場合でも、振り分け直後のローカル場所を優先するため残す
          const prev = localContentOverrides.get(contentKey);
          if (!prev || historyEntryTimestampMs(e) >= historyEntryTimestampMs(prev)) {
            localContentOverrides.set(contentKey, e);
          }
          pendingIds.delete(id);
          return;
        }
        if (isInputHistoryTombstoned(e)) {
          pendingIds.delete(id);
          return;
        }
        stillPending.add(id);
        pushEntry(e);
      });
      savePendingInputHistoryIds(stillPending);

      cloudList.forEach((cloudEntry) => {
        const id = cloudEntry.id != null ? String(cloudEntry.id) : '';
        const localSameId = id ? localById.get(id) : null;
        const contentKey = dumpContentKey(cloudEntry.content);
        const laneOverride = contentKey ? localContentOverrides.get(contentKey) : null;
        if (localSameId && !isLocalOnlyHistoryId(id)) {
          const localMs = historyEntryTimestampMs(localSameId);
          const cloudMs = historyEntryTimestampMs(cloudEntry);
          const contentsDiffer = dumpContentKey(localSameId.content) !== dumpContentKey(cloudEntry.content);
          const cloudContentKey = dumpContentKey(cloudEntry.content);
          const cloudIsReplacedOld = !!(cloudContentKey && (
            replaceOldKeys.has(cloudContentKey)
            || inputHistorySuppressedContents.has(cloudContentKey)
            || inputHistoryTombstoneKeys.has(cloudContentKey)
          ));
          const hasPendingReplace = typeof getPendingInboxWrites === 'function'
            && getPendingInboxWrites().some((j) => isPendingHistoryReplaceJob(j, id));
          // 未同期のローカル編集中だけローカル優先。それ以外は新しい方、同刻なら他端末のクラウドを優先
          let merged;
          if (contentsDiffer && (hasPendingReplace || cloudIsReplacedOld)) {
            merged = {
              ...cloudEntry,
              ...localSameId,
              id: cloudEntry.id,
              content: localSameId.content,
              folder: localSameId.folder || cloudEntry.folder,
              file: localSameId.file || cloudEntry.file,
              timestamp: localSameId.timestamp || cloudEntry.timestamp,
              dumpId: localSameId.dumpId || cloudEntry.dumpId,
              dumpIsInbox: localSameId.dumpIsInbox != null ? localSameId.dumpIsInbox : cloudEntry.dumpIsInbox
            };
          } else if (contentsDiffer && cloudMs >= localMs) {
            merged = {
              ...localSameId,
              ...cloudEntry,
              id: cloudEntry.id,
              content: cloudEntry.content,
              folder: cloudEntry.folder || localSameId.folder,
              file: cloudEntry.file || localSameId.file,
              timestamp: cloudEntry.timestamp || localSameId.timestamp,
              dumpId: localSameId.dumpId || cloudEntry.dumpId,
              dumpIsInbox: localSameId.dumpIsInbox != null ? localSameId.dumpIsInbox : cloudEntry.dumpIsInbox
            };
          } else if (contentsDiffer && localMs > cloudMs) {
            merged = {
              ...cloudEntry,
              ...localSameId,
              id: cloudEntry.id,
              content: localSameId.content,
              folder: localSameId.folder || cloudEntry.folder,
              file: localSameId.file || cloudEntry.file,
              timestamp: localSameId.timestamp || cloudEntry.timestamp,
              dumpId: localSameId.dumpId || cloudEntry.dumpId,
              dumpIsInbox: localSameId.dumpIsInbox != null ? localSameId.dumpIsInbox : cloudEntry.dumpIsInbox
            };
          } else {
            const picked = pickNewerHistoryEntry(localSameId, cloudEntry);
            merged = {
              ...cloudEntry,
              ...picked,
              id: cloudEntry.id,
              dumpId: localSameId.dumpId || cloudEntry.dumpId || picked.dumpId,
              dumpIsInbox: localSameId.dumpIsInbox != null
                ? localSameId.dumpIsInbox
                : (cloudEntry.dumpIsInbox != null ? cloudEntry.dumpIsInbox : picked.dumpIsInbox)
            };
            // 本文同じでも振り分け先（folder）は新しい方を採用
            if (historyEntryTimestampMs(localSameId) >= historyEntryTimestampMs(cloudEntry)) {
              merged.folder = localSameId.folder || merged.folder;
              merged.file = localSameId.file || merged.file;
              merged.dumpIsInbox = localSameId.dumpIsInbox != null ? localSameId.dumpIsInbox : merged.dumpIsInbox;
              merged.dumpId = localSameId.dumpId || merged.dumpId;
              merged.timestamp = localSameId.timestamp || merged.timestamp;
            }
          }
          if (laneOverride && historyEntryTimestampMs(laneOverride) >= historyEntryTimestampMs(merged)) {
            merged.folder = laneOverride.folder || merged.folder;
            merged.file = laneOverride.file || merged.file;
            merged.dumpIsInbox = laneOverride.dumpIsInbox != null ? laneOverride.dumpIsInbox : merged.dumpIsInbox;
            merged.dumpId = laneOverride.dumpId || merged.dumpId;
            merged.timestamp = laneOverride.timestamp || merged.timestamp;
          }
          pushEntry(merged);
        } else if (laneOverride && historyEntryTimestampMs(laneOverride) >= historyEntryTimestampMs(cloudEntry)) {
          pushEntry({
            ...cloudEntry,
            folder: laneOverride.folder || cloudEntry.folder,
            file: laneOverride.file || cloudEntry.file,
            dumpIsInbox: laneOverride.dumpIsInbox != null ? laneOverride.dumpIsInbox : cloudEntry.dumpIsInbox,
            dumpId: laneOverride.dumpId || cloudEntry.dumpId,
            timestamp: laneOverride.timestamp || cloudEntry.timestamp
          });
        } else {
          pushEntry(cloudEntry);
        }
      });

      // 編集同期中: クラウドに旧本文しかなく tombstone で落ちると、同一IDのローカル新行が消える。
      // 使われなかったローカル行を救済する（登録チェックが一瞬消える／ワンテンポ遅れる対策）
      local.forEach((e) => {
        if (!e || !e.content) return;
        const id = e.id != null ? String(e.id) : '';
        const k = dumpContentKey(e.content);
        if ((k && usedContent.has(k)) || (id && usedIds.has(id))) return;
        if (k && inputHistorySuppressedContents.has(k)) return;
        if (typeof isInputHistoryTombstoned === 'function' && isInputHistoryTombstoned(e)) return;
        const hasPendingReplace = typeof getPendingInboxWrites === 'function'
          && getPendingInboxWrites().some((j) => isPendingHistoryReplaceJob(j, id, e.content));
        const keepForPause = typeof inputHistoryCloudSyncPaused === 'number' && inputHistoryCloudSyncPaused > 0;
        const missingFromCloud = !!(id && !isLocalOnlyHistoryId(id) && !cloudById.has(id));
        const missingContentFromCloud = !!(k && !cloudContentKeys.has(k));
        // local-* はクラウド未反映でも残す（3分制限だと登録チェックだけ欠ける）
        const keepLocalOnly = isLocalOnlyHistoryId(id);
        const keepResurrected = !!(k && typeof isInputHistoryResurrectedKey === 'function'
          && isInputHistoryResurrectedKey(k));
        if (hasPendingReplace || keepForPause || missingFromCloud || missingContentFromCloud
          || keepLocalOnly || keepResurrected) {
          pushEntry(e);
        }
      });

      // 生キャッシュ上の復活済み行も必ず残す（getLocalInputHistory 時点で落ちた場合の保険）
      if (typeof inputHistoryResurrectedKeys !== 'undefined' && inputHistoryResurrectedKeys.size
        && Array.isArray(localInputHistoryCache)) {
        localInputHistoryCache.forEach((e) => {
          if (!e || !e.content) return;
          const k = dumpContentKey(e.content);
          if (!k || !inputHistoryResurrectedKeys.has(k)) return;
          if (k && inputHistorySuppressedContents.has(k)) return;
          pushEntry(e);
        });
      }

      out.sort((a, b) => {
        const ta = typeof getSearchTimestampMs === 'function' ? getSearchTimestampMs(a) : new Date(a.timestamp || 0).getTime();
        const tb = typeof getSearchTimestampMs === 'function' ? getSearchTimestampMs(b) : new Date(b.timestamp || 0).getTime();
        return (tb || 0) - (ta || 0);
      });
      const guarded = typeof applyPendingHistoryLaneMoves === 'function'
        ? applyPendingHistoryLaneMoves(out)
        : out;
      cacheLocalInputHistory(guarded);
      return getLocalInputHistory();
    }

    async function syncInputHistoryToCloud(contents, folder, file) {
      const items = buildInputHistoryCloudItems(contents, folder, file);
      if (!items.length) return;
      await ensureInputHistoryStore();
      const writeRes = await callAPI('addManyDataRecords', { items }, { silent: true });
      if (isApiFailure(writeRes)) throw new Error('history_cloud_write');
      // pending は merge 側でクラウド反映確認後に外す（先に消すと登録チェックから消える）
      invalidateCloudInputHistoryCache();
      // 全件再取得は重いので待たない（端末の登録チェックは既に反映済み）
    }

    /** 検索振り分けなど: 同じ本文の登録チェック履歴の場所をクラウドでも更新 */
    async function publishInputHistoryLane(content, folder, file) {
      if (!isUsableInputHistoryContent(content)) return;
      clearInputHistoryTombstoneForContent(content);
      await ensureInputHistoryStore();
      const encoded = encodeInputHistoryPayload(content, folder, file);
      if (!encoded) return;
      let ids = [];
      try {
        ids = await findCloudInputHistoryIdsByContent(content);
      } catch (e) {
        console.warn('publishInputHistoryLane lookup', e);
      }
      if (ids.length) {
        for (let i = 0; i < ids.length; i++) {
          const res = await callAPI('updateDataRecord', { id: ids[i], content: encoded }, { silent: true });
          if (isApiFailure(res)) throw new Error('history_lane_update');
        }
      } else {
        const writeRes = await callAPI('addManyDataRecords', {
          items: [{ folder: '__SYSTEM__', file: 'input_history', content: encoded }]
        }, { silent: true });
        if (isApiFailure(writeRes)) throw new Error('history_lane_add');
      }
      invalidateCloudInputHistoryCache();
    }

    async function logInputHistory(contents, folder, file) {
      appendLocalInputHistory(contents, folder, file);
      try {
        await syncInputHistoryToCloud(contents, folder, file);
      } catch (e) {
        console.error('Failed to sync input history', e);
      }
    }
    function formatInputHistoryTime(iso) {
      if (!iso) return '';
      const raw = String(iso).trim();
      // GAS 側の "yyyy/MM/dd HH:mm" はそのまま表示
      if (/^\d{4}\/\d{2}\/\d{2}/.test(raw)) return raw;
      try {
        return new Date(raw).toLocaleString('ja-JP', {
          year: 'numeric',
          month: '2-digit',
          day: '2-digit',
          hour: '2-digit',
          minute: '2-digit'
        });
      } catch (e) {
        return raw;
      }
    }
    async function syncInputHistoryDeleteToCloud(historyId, contentOpt) {
      const id = historyId != null ? String(historyId) : '';
      const content = contentOpt || '';
      rememberInputHistoryTombstone(id, content);

      const idsToDelete = new Set();
      if (id && !isLocalOnlyHistoryId(id)) idsToDelete.add(id);

      let cloudLookupFailed = false;
      if (content) {
        try {
          const found = await findCloudInputHistoryIdsByContent(content);
          found.forEach((cid) => idsToDelete.add(cid));
        } catch (e) {
          cloudLookupFailed = true;
          console.warn('cloud history lookup for delete failed', e);
          // キャッシュ経由のフォールバック
          try {
            const cloud = await fetchCloudInputHistory({ force: true });
            (cloud || [])
              .filter((e) => e && e.id && dumpContentEquals(e.content, content))
              .map((e) => String(e.id))
              .filter((cid) => cid && !isLocalOnlyHistoryId(cid))
              .forEach((cid) => idsToDelete.add(cid));
          } catch (e2) {
            console.warn('fallback cloud history lookup failed', e2);
          }
        }
      }

      const idList = Array.from(idsToDelete);
      let deleteFailed = false;
      if (idList.length === 1) {
        const res = await callAPI('deleteDataRecord', { id: idList[0] }, { silent: true });
        if (!isDeleteResultOk(res)) {
          deleteFailed = true;
          console.warn('deleteDataRecord failed', res);
        }
      } else if (idList.length > 1) {
        const res = await callAPI('deleteDataRecords', { ids: idList }, { silent: true });
        if (!isDeleteResultOk(res)) {
          deleteFailed = true;
          console.warn('deleteDataRecords failed', res);
        }
      }
      if (idList.length) invalidateCloudInputHistoryCache();

      try {
        await pushInputHistoryTombstone(id, content);
      } catch (e) {
        console.warn('Failed to push input history tombstone', e);
        queuePendingInputHistoryDelete(id, content);
        throw e;
      }

      if (cloudLookupFailed && deleteFailed) {
        queuePendingInputHistoryDelete(id, content);
        throw new Error('history_delete_sync');
      }
      if (deleteFailed && idList.length) {
        queuePendingInputHistoryDelete(id, content);
        throw new Error('history_delete_sync');
      }
      // 本文はあるのにクラウド行を1件も消せていない（未同期のまま他端末に残る）→ 再試行
      if (content && !idList.length && cloudLookupFailed) {
        queuePendingInputHistoryDelete(id, content);
        throw new Error('history_delete_sync');
      }
      clearPendingInputHistoryDelete(id, content);
    }

    async function removeInputHistoryEntry(historyId, contentOpt) {
      if (!historyId && !contentOpt) return;
      const id = historyId != null ? String(historyId) : '';
      if (contentOpt) suppressReplacedHistoryContent(contentOpt);
      rememberInputHistoryTombstone(id, contentOpt);
      dropInputHistoryEntries((e) => {
        if (id && sameInputHistoryId(e.id, id)) {
          if (e.content) suppressReplacedHistoryContent(e.content);
          return true;
        }
        if (contentOpt && dumpContentEquals(e.content, contentOpt)) return true;
        return false;
      });

      await syncInputHistoryDeleteToCloud(id, contentOpt);
    }
    async function removeInputHistoryByContent(content) {
      if (!content) return;
      suppressReplacedHistoryContent(content);
      rememberInputHistoryTombstone(null, content);
      dropInputHistoryEntries((e) => dumpContentEquals(e.content, content));
      try {
        const cloud = await fetchCloudInputHistory();
        if (cloud) {
          const ids = cloud
            .filter((e) => e && e.id && dumpContentEquals(e.content, content))
            .map((e) => String(e.id))
            .filter((id) => id && !id.startsWith('mig-') && !id.startsWith('local-'));
          if (ids.length === 1) {
            await callAPI('deleteDataRecord', { id: ids[0] }, { silent: true });
          } else if (ids.length > 1) {
            await callAPI('deleteDataRecords', { ids }, { silent: true });
          }
        }
      } catch (e) {
        console.error('Failed to remove input history by content', e);
      }
      try {
        await pushInputHistoryTombstone(null, content);
        const refreshed = await fetchCloudInputHistory();
        if (refreshed) mergeLocalAndCloudHistory(refreshed);
      } catch (e) {
        console.warn('Failed to push input history tombstone', e);
      }
    }
    async function updateInputHistoryContent(oldContent, newContent, folder, file, dumpId) {
      if (!oldContent || !newContent) return;
      const dump = dumpId != null && dumpId !== '' ? String(dumpId) : '';
      const local = getLocalInputHistory();
      const primary = local.find((e) => {
        if (!e) return false;
        if (dumpContentEquals(e.content, oldContent)) return true;
        if (dump && e.dumpId != null && String(e.dumpId) === dump) return true;
        if (dump && e.id != null && String(e.id) === dump) return true;
        return false;
      });
      const historyId = primary && primary.id != null ? String(primary.id) : '';
      const nextFolder = folder || (primary && primary.folder) || 'INBOX';
      const nextFile = file || (primary && primary.file) || '未整理';
      upsertLocalInputHistoryReplace({
        fromId: historyId,
        toId: historyId,
        oldContent,
        newContent,
        folder: nextFolder,
        file: nextFile,
        persistTombstone: true,
        onlyIfExists: true
      });
      await replaceCloudInputHistoryEntry(historyId || null, oldContent, newContent, nextFolder, nextFile, {
        createIfMissing: false
      });
    }

    async function replaceCloudInputHistoryEntry(oldId, oldContent, newContent, folder, file, opts) {
      opts = opts || {};
      const skipPaint = !!opts.skipPaint;
      if (!isUsableInputHistoryContent(newContent)) return null;
      try {
        await ensureInputHistoryStore();
        // 再利用する ID が誤って tombstone されていれば外す（一覧から消えるのを防ぐ）
        if (oldId && inputHistoryTombstoneIds.has(String(oldId))) {
          inputHistoryTombstoneIds.delete(String(oldId));
          if (typeof persistHistoryTombstones === 'function') persistHistoryTombstones();
        }

        const updatedAt = new Date().toISOString();
        const payload = encodeInputHistoryPayload(newContent, folder, file, updatedAt);
        if (!payload) return null;

        let newCloudId = null;
        // 1) 同一IDを直接上書き（他端末が同じ行を見るために最優先）
        if (oldId && !isLocalOnlyHistoryId(String(oldId))) {
          const res = await callAPI('updateDataRecord', {
            id: String(oldId),
            content: payload
          }, { silent: true });
          if (!isApiFailure(res)) {
            newCloudId = String(oldId);
            // 直接上書き成功時は重いクラウド全件再取得を待たずに即時完了（同期待ちを大幅短縮）
            const sameMovedContent = dumpContentEquals(oldContent, newContent);
            if (oldContent && !sameMovedContent) {
              suppressReplacedHistoryContent(oldContent);
              const oldKey = dumpContentKey(oldContent);
              if (oldKey) {
                inputHistoryTombstoneKeys.add(oldKey);
                if (typeof persistHistoryTombstones === 'function') persistHistoryTombstones();
              }
            }
            return newCloudId;
          }
        }

        // 2) 本文 tombstone で落とさない取得で、旧本文／旧IDの行を特定して上書き
        invalidateCloudInputHistoryCache();
        const cloud = await fetchCloudInputHistory({ force: true, includeSuppressedContent: true });
        const matches = (cloud || []).filter((e) => {
          if (!e || !e.id) return false;
          if (oldId && String(e.id) === String(oldId)) return true;
          return !!(oldContent && dumpContentEquals(e.content, oldContent));
        });

        if (!newCloudId) {
          const primary = matches.find((e) => oldId && String(e.id) === String(oldId))
            || matches.find((e) => e && !isLocalOnlyHistoryId(String(e.id)))
            || null;
          if (primary && primary.id && !isLocalOnlyHistoryId(String(primary.id))) {
            const res = await callAPI('updateDataRecord', {
              id: String(primary.id),
              content: payload
            }, { silent: true });
            if (!isApiFailure(res)) newCloudId = String(primary.id);
          }
        }

        // 3) update 不能時のみ新規。その場合も旧本文行は後で必ず削除
        // createIfMissing:false かつ旧行が無いときは新規履歴を作らない（お気に入り編集の増殖防止）
        if (!newCloudId && !(opts.createIfMissing === false && !matches.length && !oldId)) {
          const addRes = await callAPI('addDataRecord', {
            folder: '__SYSTEM__',
            file: 'input_history',
            content: payload
          }, { silent: true });
          if (!isApiFailure(addRes) && addRes && addRes.id) newCloudId = String(addRes.id);
        }
        if (!newCloudId) return null;

        // 旧本文のクラウド行をすべて削除（更新した primary 以外）
        const idsToDelete = matches
          .map((e) => String(e.id))
          .filter((id) => id && !isLocalOnlyHistoryId(id))
          .filter((id) => !newCloudId || id !== String(newCloudId));
        if (idsToDelete.length === 1) {
          await callAPI('deleteDataRecord', { id: idsToDelete[0] }, { silent: true });
        } else if (idsToDelete.length > 1) {
          await callAPI('deleteDataRecords', { ids: idsToDelete }, { silent: true });
        }
        // IDが変わった場合だけ旧IDを tombstone（再利用IDは消さない）
        idsToDelete.forEach((id) => {
          if (id) inputHistoryTombstoneIds.add(String(id));
        });
        if (idsToDelete.length && typeof persistHistoryTombstones === 'function') persistHistoryTombstones();

        // 4) 本文が変わったときだけ旧本文を非表示化。場所だけの移動は同じ本文なので消さない
        const sameMovedContent = dumpContentEquals(oldContent, newContent);
        if (oldContent && !sameMovedContent) {
          suppressReplacedHistoryContent(oldContent);
          const oldKey = dumpContentKey(oldContent);
          if (oldKey) {
            inputHistoryTombstoneKeys.add(oldKey);
            if (typeof persistHistoryTombstones === 'function') persistHistoryTombstones();
          }
        } else if (sameMovedContent) {
          const keepKey = dumpContentKey(newContent);
          if (keepKey) {
            inputHistorySuppressedContents.delete(keepKey);
            inputHistoryTombstoneKeys.delete(keepKey);
            if (typeof persistHistoryTombstones === 'function') persistHistoryTombstones();
          }
        }

        invalidateCloudInputHistoryCache();
        // マージ前にローカルへ新本文を確定（マージで一瞬消えるのを防ぐ）
        upsertLocalInputHistoryReplace({
          fromId: oldId,
          toId: newCloudId || oldId,
          oldContent,
          newContent,
          folder,
          file,
          persistTombstone: true
        });
        const refreshed = await fetchCloudInputHistory({ force: true });
        if (refreshed) {
          mergeLocalAndCloudHistory(refreshed);
          if (!newCloudId) {
            const hit = (refreshed || []).find((e) => e && dumpContentEquals(e.content, newContent));
            if (hit && hit.id) newCloudId = String(hit.id);
          }
        }
        upsertLocalInputHistoryReplace({
          fromId: oldId,
          toId: newCloudId || oldId,
          oldContent,
          newContent,
          folder,
          file,
          persistTombstone: true
        });
        if (!skipPaint && typeof paintInputTabHistory === 'function') {
          paintInputTabHistory(getLocalInputHistory(), { skipDupSchedule: true });
        }
        return newCloudId;
      } catch (e) {
        console.error('Failed to replace cloud input history', e);
        return null;
      }
    }
    async function resolveInputHistoryItem(entry) {
      if (!entry || !entry.content) return null;
      const wantInbox = historyDestIsInbox(entry.folder);
      const content = String(entry.content);
      const folder = normalizeHistoryFolder(entry.folder);
      const file = entry.file || '未整理';
      const destOk = (r) => {
        if (wantInbox) return !!(r.isInbox || historyDestIsInbox(r.folder));
        return !r.isInbox && normalizeHistoryFolder(r.folder) === folder && (r.file || '未整理') === file;
      };

      const cached = typeof mergePendingDumpsInto === 'function'
        ? mergePendingDumpsInto((storedItemsCache && storedItemsCache.items) || [])
        : [];
      if (entry.dumpId && !isTempId(entry.dumpId)) {
        const byId = (cached || []).find((r) => r && String(r.id) === String(entry.dumpId) && !isNonUserDumpItem(r));
        if (byId && !isTempId(byId.id)) return toDumpMatch(byId);
      }
      const localHit = (cached || []).find((r) => isUsableDumpHit(r, content) && destOk(r));
      if (localHit) return toDumpMatch(localHit);

      try {
        if (wantInbox) {
          const data = await callAPI('getOrganizerData', { fresh: true }, { silent: true });
          if (data && !data.error && Array.isArray(data.inbox)) {
            const hit = data.inbox.find((r) => r && dumpContentEquals(r.content, content));
            if (hit && hit.id && !isTempId(hit.id)) {
              return toDumpMatch({ ...hit, folder: 'INBOX', file: '未整理', isInbox: true });
            }
          }
        } else if (folder && file) {
          const items = await callAPI('getFolderFileItems', {
            folder,
            file
          }, { silent: true });
          if (Array.isArray(items)) {
            const hit = items.find((r) => r && dumpContentEquals(r.content, content));
            if (hit && hit.id && !isTempId(hit.id)) {
              return toDumpMatch({ ...hit, folder, file, isInbox: false });
            }
          }
        }
      } catch (e) {
        console.warn('resolveInputHistoryItem direct lookup failed', e);
      }

      try {
        const keyword = content.length > 120 ? content.slice(0, 120) : content;
        const results = await callAPI('searchData', { keyword }, { silent: true });
        if (!Array.isArray(results)) return null;
        const hit = results.find((r) => isUsableDumpHit(r, content) && destOk(r));
        return hit ? toDumpMatch(hit) : null;
      } catch (e) {
        console.warn('resolveInputHistoryItem search fallback failed', e);
        return null;
      }
    }

    async function findDumpHitsByContent(content) {
      const hits = [];
      const seen = new Set();
      const pushHit = (r) => {
        if (!isUsableDumpHit(r, content)) return;
        const id = String(r.id);
        if (seen.has(id)) return;
        seen.add(id);
        hits.push(toDumpMatch(r));
      };
      const cached = typeof mergePendingDumpsInto === 'function'
        ? mergePendingDumpsInto((storedItemsCache && storedItemsCache.items) || [])
        : [];
      (cached || []).forEach(pushHit);
      if (typeof findExactDumpHitsOnServer === 'function') {
        try {
          const serverHits = await findExactDumpHitsOnServer(content, { inbox: true, anywhere: true });
          (serverHits || []).forEach(pushHit);
        } catch (e) {
          console.warn('findDumpHitsByContent server scan failed', e);
        }
      } else {
        try {
          const keyword = searchKeywordForDump(content);
          if (keyword) {
            const results = await callAPI('searchData', { keyword }, { silent: true });
            (Array.isArray(results) ? results : []).forEach(pushHit);
          }
        } catch (e) {
          console.warn('findDumpHitsByContent failed', e);
        }
      }
      return hits;
    }

    async function resolveInputHistoryItemAnywhere(content, preferred) {
      const hits = await findDumpHitsByContent(content);
      if (!hits.length) return null;
      if (preferred) {
        const folder = normalizeHistoryFolder(preferred.folder);
        const file = preferred.file || '未整理';
        const wantInbox = historyDestIsInbox(folder);
        const destHit = hits.find((r) => {
          if (wantInbox) return !!r.isInbox;
          return !r.isInbox && normalizeHistoryFolder(r.folder) === folder && (r.file || '未整理') === file;
        });
        if (destHit) return destHit;
      }
      return hits[0];
    }
    function formatResolvedHistoryItem(match, entry) {
      if (!match) return null;
      return {
        ...match,
        folder: match.isInbox || match.folder === 'INBOX' ? '📥 INBOX' : match.folder,
        file: match.file || (entry && entry.file) || '未整理',
        isInbox: !!(match.isInbox || match.folder === 'INBOX'),
        timestamp: match.timestamp || (entry ? formatInputHistoryTime(entry.timestamp) : '')
      };
    }

    async function withResolvedInputHistory(index, action) {
      const entry = inputHistoryView[index];
      if (!entry) return;
      const cached = typeof findCachedDumpForHistory === 'function' ? findCachedDumpForHistory(entry) : null;
      if (cached && cached.id != null && !(typeof isTempId === 'function' && isTempId(cached.id))) {
        const item = formatResolvedHistoryItem(cached, entry);
        searchResults = [item];
        await action(0, item, entry);
        return;
      }
      const resultsContainer = document.getElementById('search-results');
      const note = document.createElement('div');
      note.id = 'history-resolve-note';
      note.className = 'text-xs font-bold text-cyan-300 mb-2 bg-cyan-950/30 border border-cyan-800/40 rounded-xl px-3 py-2';
      note.textContent = '保存場所を確認中…';
      if (resultsContainer) resultsContainer.prepend(note);
      try {
        const match = await resolveInputHistoryItem(entry);
        const noteEl = document.getElementById('history-resolve-note');
        if (noteEl) noteEl.remove();
        if (!match) {
          if (confirm('元のデータが見つかりません（移動・削除済み、または同期遅延の可能性）。この入力履歴だけ削除しますか？\n\n※コピーだけなら「📋 コピー」ボタンを使えます')) {
            await removeInputHistoryEntry(entry.id, entry.content);
            renderInputHistoryView();
          }
          return;
        }
        const item = formatResolvedHistoryItem(match, entry);
        searchResults = [item];
        await action(0, item, entry);
      } catch (e) {
        console.error(e);
        const noteEl = document.getElementById('history-resolve-note');
        if (noteEl) noteEl.remove();
        alert('読み込みに失敗しました。しばらくしてから再度お試しください。\nコピーだけなら「📋 コピー」を使えます。');
      }
    }

    async function deleteInputHistoryFromSearch(entry, index, event) {
      if (event) event.stopPropagation();
      if (!entry) return;
      const preview = String(entry.content || '').trim().slice(0, 40);
      if (!confirm(`この入力履歴を削除し、同じ本文の保存データがあればゴミ箱へ移しますか？\n\n${preview}${preview.length >= 40 ? '…' : ''}`)) {
        return;
      }

      suppressReplacedHistoryContent(entry.content);
      dropInputHistoryEntries((e) => {
        if (entry.id && sameInputHistoryId(e.id, entry.id)) return true;
        return dumpContentEquals(e.content, entry.content);
      });
      renderInputHistoryView();

      logOperation('DELETE', '入力履歴から削除', {
        oldFolder: entry.folder || 'INBOX',
        oldFile: entry.file || '未整理',
        newFolder: '🗑️ ゴミ箱',
        newFile: '削除履歴',
        content: entry.content,
        id: entry.dumpId || null,
        historyId: entry.id || null
      });

      enqueueInputHistoryDeleteSync(async () => {
        await removeInputHistoryEntry(entry.id, entry.content);
        const hits = await findDumpHitsByContent(entry.content);
        const inboxMoves = [];
        const dataMoves = [];
        (hits || []).forEach((match) => {
          if (!match || match.id == null || (typeof isTempId === 'function' && isTempId(match.id))) return;
          const move = { id: String(match.id), folder: '🗑️ ゴミ箱', file: '削除履歴' };
          if (isSearchInboxItem(match)) inboxMoves.push(move);
          else dataMoves.push(move);
        });
        if (inboxMoves.length || dataMoves.length) {
          if (typeof syncBulkTrashMoves === 'function') {
            await syncBulkTrashMoves(inboxMoves, dataMoves, { silent: true });
          } else {
            for (const m of inboxMoves) {
              const res = await callAPI('moveInboxItem', m, { silent: true });
              if (res && res.error) throw new Error('inbox_trash');
            }
            for (const m of dataMoves) {
              const res = await callAPI('moveDataRecord', m, { silent: true });
              if (res && res.error) throw new Error('data_trash');
            }
          }
        }
        if (hits && hits.length) {
          if (typeof forgetDumpedItemsByContents === 'function') {
            forgetDumpedItemsByContents([entry.content], { includeStored: true });
          }
          if (typeof invalidateStoredItemsCache === 'function') {
            invalidateStoredItemsCache({
              ids: hits.map((h) => h && h.id).filter(Boolean),
              contents: [entry.content]
            });
          }
          if (typeof updateBadge === 'function') updateBadge();
        }
      }, {
        label: '削除',
        onFinalFail: () => {
          showInputHistoryDeleteStatus(
            '削除は端末に反映済みです。クラウド同期は後で再試行されます',
            'error'
          );
        }
      });
    }

    function sameInputHistoryList(a, b) {
      if (a === b) return true;
      if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
      for (let i = 0; i < a.length; i++) {
        const x = a[i];
        const y = b[i];
        if (x === y) continue;
        if (!x || !y) return false;
        if (String(x.id) !== String(y.id) || x.content !== y.content || x.timestamp !== y.timestamp
          || x.folder !== y.folder || x.file !== y.file) return false;
      }
      return true;
    }

    async function showInputHistory(opts) {
      currentSearchTabMode = "input_history";
      updateSimilarSearchPanelVisibility();
      if (isSearchSelectMode) toggleSearchSelectMode(false);
      if (!(opts && opts.keepList)) inputHistoryFlatLimit = SEARCH_LIST_CHUNK;
      // ローカルを先に出して、クラウド同期・類似解析は裏で進める
      inputHistoryView = getLocalInputHistory().filter((e) => {
        if (!e || !e.content) return false;
        return !inputHistorySuppressedContents.has(dumpContentKey(e.content));
      });
      inputHistoryAnalyzing = inputHistoryView.length > 0;
      renderInputHistoryView();
      const syncToken = ++inputHistoryAnalysisToken;
      runInBackground(async () => {
        try {
          if (typeof flushPendingInputHistoryDeletes === 'function') {
            try { await flushPendingInputHistoryDeletes({ silent: true }); } catch (_) { }
          }
          await migrateLocalInputHistoryToCloud();
          if (typeof invalidateCloudInputHistoryCache === 'function') invalidateCloudInputHistoryCache();
          const merged = await getInputHistory();
          if (syncToken !== inputHistoryAnalysisToken || currentSearchTabMode !== 'input_history') return;
          const unchanged = sameInputHistoryList(inputHistoryView, merged);
          inputHistoryView = merged;
          if (unchanged && inputHistoryRenderState) inputHistoryRenderState.view = merged;
          else renderInputHistoryView();
        } catch (e) {
          console.warn('input history cloud sync', e);
        }
        if (syncToken !== inputHistoryAnalysisToken || currentSearchTabMode !== 'input_history') return;
        if (inputHistoryView.length === 0) {
          inputHistoryAnalyzing = false;
          renderInputHistoryView();
          return;
        }
        inputHistoryAnalyzing = true;
        enrichInputHistorySimilarities(syncToken);
      });
    }

    function inputHistorySimilarKey(entry) {
      if (!entry) return '';
      return `${entry.folder || ''}\u0001${entry.file || ''}\u0001${String(entry.content || '').trim()}`;
    }

    function liveInputHistorySimilar(matches) {
      if (!matches || !matches.length) return [];
      return matches.filter((m) => {
        if (!m) return false;
        const key = dumpContentKey(m.content);
        if (key && inputHistorySuppressedContents.has(key)) return false;
        return !(typeof isInputHistoryTombstoned === 'function' && isInputHistoryTombstoned(m));
      });
    }

    function inputHistoryStoredSignature(items) {
      let h = 2166136261;
      const mix = (value) => {
        const s = String(value == null ? '' : value);
        for (let i = 0; i < s.length; i++) {
          h ^= s.charCodeAt(i);
          h = Math.imul(h, 16777619);
        }
        h ^= 0x1f;
        h = Math.imul(h, 16777619);
      };
      (items || []).forEach((it) => {
        if (!it) return;
        mix(it.id);
        mix(it.folder);
        mix(it.file);
        mix(it.content);
      });
      return `${(items || []).length}:${(h >>> 0).toString(36)}:${inputHistorySuppressedContents.size}`;
    }

    function sameSimilarMatches(a, b) {
      const x = a || [];
      const y = b || [];
      if (x.length !== y.length) return false;
      for (let i = 0; i < x.length; i++) {
        if (String(x[i].id) !== String(y[i].id) || x[i].content !== y[i].content
          || x[i].folder !== y[i].folder || x[i].file !== y[i].file
          || Math.round((x[i].matchScore || 0) * 100) !== Math.round((y[i].matchScore || 0) * 100)) return false;
      }
      return true;
    }

    function isSearchTabShown() {
      const el = document.getElementById('search-mode');
      return !!(el && el.classList.contains('active')) && !document.hidden;
    }

    // 検索タブを離れている間は解析を止めて待つ（入力タブなど他の画面の負荷にしない）
    function waitForIdleSlice() {
      return new Promise((resolve) => {
        const run = () => {
          if (!isSearchTabShown()) {
            setTimeout(run, 800);
            return;
          }
          if (typeof requestIdleCallback === 'function') requestIdleCallback(resolve, { timeout: 120 });
          else setTimeout(() => resolve(null), 0);
        };
        run();
      });
    }

    function idleSliceEnd(deadline) {
      const budget = deadline && !deadline.didTimeout
        ? Math.min(40, Math.max(6, deadline.timeRemaining()))
        : 10;
      return performance.now() + budget;
    }

    function applyInputHistorySimilarChanges(keys) {
      const st = inputHistoryRenderState;
      if (!st || st.view !== inputHistoryView || currentSearchTabMode !== 'input_history') return;
      keys.forEach((key) => {
        const hit = inputHistorySimilarStore.get(key);
        const matches = hit ? liveInputHistorySimilar(hit.matches) : [];
        (st.indicesByKey.get(key) || []).forEach((index) => {
          inputHistorySimilarMap[index] = matches;
          refreshInputHistoryCard(index);
        });
      });
      refreshInputHistorySimilarCounts();
    }

    function updateInputHistoryAnalysisProgress(done, total) {
      const st = inputHistoryRenderState;
      if (!st || !st.bannerText) return;
      st.bannerText.textContent = `類似情報を解析中… ${done}/${total}（履歴は先に表示しています）`;
    }

    function finishInputHistoryAnalysisUi() {
      const st = inputHistoryRenderState;
      if (!st || st.view !== inputHistoryView) {
        renderInputHistoryView();
        return;
      }
      if (st.banner) st.banner.remove();
      st.banner = null;
      st.bannerText = null;
      refreshInputHistorySimilarCounts();
    }

    async function enrichInputHistorySimilarities(token) {
      const alive = () => token === inputHistoryAnalysisToken && currentSearchTabMode === 'input_history';
      try {
        const allItems = await collectAllStoredItems();
        if (!alive() || !Array.isArray(allItems) || !allItems.length) return;
        const signature = inputHistoryStoredSignature(allItems);
        let bundle = null;
        // 未計算・保存データ更新で古くなった本文だけ計算し、結果が変わったカードだけ差し替える
        for (let round = 0; round < 3; round++) {
          const todo = inputHistoryView.filter((entry) => {
            const hit = inputHistorySimilarStore.get(inputHistorySimilarKey(entry));
            return !hit || hit.signature !== signature;
          });
          if (!todo.length) break;
          if (!bundle) {
            await waitForIdleSlice();
            if (!alive()) return;
            bundle = getOrBuildSimilarityBundle(allItems);
          }
          let changed = [];
          let lastApply = performance.now();
          let k = 0;
          while (k < todo.length) {
            const sliceEnd = idleSliceEnd(await waitForIdleSlice());
            if (!alive()) return;
            do {
              const entry = todo[k++];
              const key = inputHistorySimilarKey(entry);
              const prev = inputHistorySimilarStore.get(key);
              if (prev && prev.signature === signature) continue;
              const matches = findSimilarItemsForContent(entry, bundle, 5);
              inputHistorySimilarStore.set(key, { signature, matches });
              if (!sameSimilarMatches(prev && prev.matches, matches)) changed.push(key);
            } while (k < todo.length && performance.now() < sliceEnd);
            if (!alive()) return;
            // 画面更新は間引く（毎回書き換えると描画が挟まり解析が遅くなる）
            if (k >= todo.length || performance.now() - lastApply > 500) {
              if (changed.length) applyInputHistorySimilarChanges(changed);
              changed = [];
              updateInputHistoryAnalysisProgress(k, todo.length);
              lastApply = performance.now();
            }
          }
        }
        const liveKeys = new Set(inputHistoryView.map(inputHistorySimilarKey));
        [...inputHistorySimilarStore.keys()].forEach((key) => {
          if (!liveKeys.has(key)) inputHistorySimilarStore.delete(key);
        });
      } catch (e) {
        console.warn('input history similar analysis', e);
      } finally {
        if (token === inputHistoryAnalysisToken) {
          inputHistoryAnalyzing = false;
          if (currentSearchTabMode === 'input_history') finishInputHistoryAnalysisUi();
        }
      }
    }

    function getInputHistoryDateKey(ms) {
      if (!ms) return '日付不明';
      const d = new Date(ms);
      const y = d.getFullYear();
      const m = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      return `${y}/${m}/${day}`;
    }

    function formatInputHistoryDateLabel(dateKey) {
      if (dateKey === '日付不明') return dateKey;
      const parts = dateKey.split('/').map(Number);
      if (parts.length !== 3 || parts.some((n) => !Number.isFinite(n))) return dateKey;
      const wd = ['日', '月', '火', '水', '木', '金', '土'][new Date(parts[0], parts[1] - 1, parts[2]).getDay()];
      return `${dateKey}（${wd}）`;
    }

    function formatInputHistoryYearLabel(yearKey) {
      if (yearKey === '日付不明') return yearKey;
      return `${yearKey}年`;
    }

    function formatInputHistoryMonthLabel(monthKey) {
      if (monthKey === '日付不明') return monthKey;
      const parts = monthKey.split('/').map(Number);
      if (parts.length !== 2 || parts.some((n) => !Number.isFinite(n))) return monthKey;
      return `${parts[0]}年${parts[1]}月`;
    }

    function countSimilarInIndices(indices) {
      return (indices || []).filter((i) => (inputHistorySimilarMap[i] || []).length > 0).length;
    }

    function buildInputHistoryHierarchy() {
      const msList = inputHistoryView.map((entry) => getSearchTimestampMs(entry));
      const yearMap = new Map();
      msList.forEach((ms, index) => {
        const dateKey = getInputHistoryDateKey(ms);
        const parts = dateKey === '日付不明' ? null : dateKey.split('/');
        const yearKey = parts ? parts[0] : '日付不明';
        const monthKey = parts ? `${parts[0]}/${parts[1]}` : '日付不明';
        if (!yearMap.has(yearKey)) yearMap.set(yearKey, new Map());
        const monthMap = yearMap.get(yearKey);
        if (!monthMap.has(monthKey)) monthMap.set(monthKey, new Map());
        const dayMap = monthMap.get(monthKey);
        if (!dayMap.has(dateKey)) dayMap.set(dateKey, []);
        dayMap.get(dateKey).push(index);
      });
      const newestMs = (indices) => {
        let max = 0;
        for (let i = 0; i < indices.length; i++) {
          if (msList[indices[i]] > max) max = msList[indices[i]];
        }
        return max;
      };
      const byNewest = (list) => list
        .map((group) => ({ group, ms: newestMs(group.indices) }))
        .sort((a, b) => b.ms - a.ms)
        .map((x) => x.group);

      return byNewest([...yearMap.entries()].map(([yearKey, monthMap]) => {
        const months = byNewest([...monthMap.entries()].map(([monthKey, dayMap]) => {
          const days = byNewest([...dayMap.entries()].map(([dateKey, indices]) => ({ dateKey, indices })));
          return { monthKey, indices: days.flatMap((d) => d.indices), days };
        }));
        return { yearKey, indices: months.flatMap((m) => m.indices), months };
      }));
    }

    function createInputHistoryGroupDetails(key, label, indices, level, bodyBuilder) {
      const details = document.createElement('details');
      const levelClass = level === 'year'
        ? 'mb-2 rounded-2xl border border-emerald-900/50 bg-black/25'
        : level === 'month'
          ? 'mb-1.5 ml-2 rounded-xl border border-cyan-900/45 bg-black/20'
          : 'mb-1 ml-2 rounded-xl border border-indigo-900/40 bg-black/15';
      details.className = `${levelClass} overflow-hidden group`;
      const similarCount = countSimilarInIndices(indices);

      const summary = document.createElement('summary');
      const summaryPad = level === 'year' ? 'px-3.5 py-3' : level === 'month' ? 'px-3 py-2.5' : 'px-2.5 py-2';
      const labelClass = level === 'year'
        ? 'text-sm font-black text-emerald-200'
        : level === 'month'
          ? 'text-[13px] font-black text-cyan-200'
          : 'text-xs font-black text-indigo-200';
      summary.className = `cursor-pointer list-none ${summaryPad} flex items-center justify-between gap-2 hover:bg-emerald-950/20 transition select-none`;
      summary.innerHTML = `<div class="flex flex-wrap items-center gap-2 min-w-0">
          <span class="${labelClass}">${label}</span>
          <span class="text-[11px] font-bold text-emerald-500/80">${indices.length}件</span>
          <span data-similar-badge class="text-[10px] font-extrabold px-2 py-0.5 rounded-lg bg-amber-950/70 border border-amber-700/50 text-amber-300${similarCount > 0 ? '' : ' hidden'}">類似 ${similarCount}</span>
        </div>
        <span class="text-[10px] text-emerald-600/80 group-open:hidden">▼</span>
        <span class="text-[10px] text-emerald-600/80 hidden group-open:inline">▲</span>`;

      const body = document.createElement('div');
      body.className = level === 'year'
        ? 'px-2 pb-2 pt-1 border-t border-emerald-900/40'
        : level === 'month'
          ? 'px-2 pb-2 pt-1 border-t border-cyan-900/35'
          : 'px-2 pb-2 pt-1 border-t border-indigo-900/30 space-y-0';
      // 閉じているグループの中身は開くまで作らない
      let built = false;
      const ensureBody = () => {
        if (built) return;
        built = true;
        bodyBuilder(body);
      };
      details.open = inputHistoryExpandedKeys.has(key);
      if (details.open) ensureBody();
      summary.addEventListener('click', ensureBody);
      details.addEventListener('toggle', () => {
        if (details.open) {
          inputHistoryExpandedKeys.add(key);
          ensureBody();
        } else {
          inputHistoryExpandedKeys.delete(key);
        }
      });
      if (inputHistoryRenderState) {
        inputHistoryRenderState.groups.push({ indices, badge: summary.querySelector('[data-similar-badge]') });
      }

      details.appendChild(summary);
      details.appendChild(body);
      return details;
    }

    function setInputHistoryViewMode(mode) {
      const next = mode === 'flat' ? 'flat' : 'tree';
      if (inputHistoryViewMode === next) return;
      inputHistoryViewMode = next;
      localStorage.setItem('input_history_view_mode', inputHistoryViewMode);
      if (inputHistoryViewMode === 'tree') inputHistoryExpandedKeys.clear();
      inputHistoryFlatLimit = SEARCH_LIST_CHUNK;
      if (currentSearchTabMode === 'input_history') renderInputHistoryView();
    }

    function refreshInputHistoryCard(index) {
      const st = inputHistoryRenderState;
      if (!st || st.view !== inputHistoryView) {
        renderInputHistoryView();
        return;
      }
      const old = st.cards.get(index);
      if (!old || !old.isConnected || !inputHistoryView[index]) return;
      old.replaceWith(createInputHistoryCard(inputHistoryView[index], index));
    }

    function inputHistoryHeadingText() {
      const similarCount = (inputHistorySimilarMap || []).filter((m) => m && m.length > 0).length;
      const modeLabel = inputHistoryViewMode === 'tree' ? '年→月→日' : 'すべて表示';
      return similarCount > 0
        ? `📥 入力履歴（${inputHistoryView.length}件 · ${modeLabel} · 類似あり ${similarCount}件）`
        : `📥 入力履歴（${inputHistoryView.length}件 · ${modeLabel} · 端末間同期）`;
    }

    function refreshInputHistorySimilarCounts() {
      const st = inputHistoryRenderState;
      if (!st) return;
      st.groups.forEach((g) => {
        if (!g.badge) return;
        const n = countSimilarInIndices(g.indices);
        g.badge.textContent = `類似 ${n}`;
        g.badge.classList.toggle('hidden', n === 0);
      });
      if (st.heading) st.heading.textContent = inputHistoryHeadingText();
    }

    function appendSearchListMore(container, remaining, onMore, unit = '件') {
      const wrap = document.createElement('div');
      wrap.className = 'pt-1 pb-3';
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'w-full text-xs font-extrabold text-cyan-200 bg-cyan-950/40 border border-cyan-800/50 rounded-xl py-2.5 transition active:scale-95';
      btn.textContent = `▼ 続きを表示（残り ${remaining}${unit}）`;
      let io = null;
      const more = () => {
        if (!wrap.isConnected) return;
        if (io) io.disconnect();
        wrap.remove();
        onMore();
      };
      btn.onclick = (e) => {
        e.stopPropagation();
        more();
      };
      wrap.appendChild(btn);
      container.appendChild(wrap);
      if (typeof IntersectionObserver === 'function') {
        io = new IntersectionObserver((entries) => {
          if (entries.some((en) => en.isIntersecting)) more();
        }, { root: container, rootMargin: '0px 0px 480px 0px' });
        io.observe(wrap);
      }
    }

    function appendInputHistoryFlatCards(container, from) {
      const st = inputHistoryRenderState;
      const total = inputHistoryView.length;
      const end = Math.min(total, Math.max(from + SEARCH_LIST_CHUNK, inputHistoryFlatLimit));
      const frag = document.createDocumentFragment();
      for (let i = from; i < end; i++) frag.appendChild(createInputHistoryCard(inputHistoryView[i], i));
      container.appendChild(frag);
      inputHistoryFlatLimit = end;
      if (end < total) {
        appendSearchListMore(container, total - end, () => {
          if (st === inputHistoryRenderState && st.view === inputHistoryView) appendInputHistoryFlatCards(container, end);
          else renderInputHistoryView();
        });
      }
    }

    function renderInputHistoryTreeView(resultsContainer) {
      const hierarchy = buildInputHistoryHierarchy();
      if (hierarchy.length > 0) {
        const dateSummary = document.createElement('div');
        dateSummary.className = 'text-[10px] font-bold text-emerald-600/80 mb-2 px-1';
        const monthCount = hierarchy.reduce((n, y) => n + y.months.length, 0);
        const dayCount = hierarchy.reduce((n, y) => n + y.months.reduce((m, mo) => m + mo.days.length, 0), 0);
        dateSummary.textContent = `${hierarchy.length}年 · ${monthCount}月 · ${dayCount}日 · 年→月→日の順にタップして開く`;
        resultsContainer.appendChild(dateSummary);
      }

      hierarchy.forEach(({ yearKey, indices: yearIndices, months }) => {
        const yearNode = createInputHistoryGroupDetails(
          `y:${yearKey}`,
          formatInputHistoryYearLabel(yearKey),
          yearIndices,
          'year',
          (yearBody) => {
            months.forEach(({ monthKey, indices: monthIndices, days }) => {
              const monthNode = createInputHistoryGroupDetails(
                `m:${monthKey}`,
                formatInputHistoryMonthLabel(monthKey),
                monthIndices,
                'month',
                (monthBody) => {
                  days.forEach(({ dateKey, indices }) => {
                    const dayNode = createInputHistoryGroupDetails(
                      `d:${dateKey}`,
                      formatInputHistoryDateLabel(dateKey),
                      indices,
                      'day',
                      (dayBody) => {
                        indices.forEach((index) => {
                          dayBody.appendChild(createInputHistoryCard(inputHistoryView[index], index));
                        });
                      }
                    );
                    monthBody.appendChild(dayNode);
                  });
                }
              );
              yearBody.appendChild(monthNode);
            });
          }
        );
        resultsContainer.appendChild(yearNode);
      });
    }

    function createInputHistoryCard(entry, index) {
      const similarMatches = (inputHistorySimilarMap && inputHistorySimilarMap[index]) || [];
      const hasSimilar = similarMatches.length > 0;
      const isSelected = searchSelectedIndices.has(index);
      const card = document.createElement('div');
      card.className = hasSimilar
        ? `p-3 border-2 ${isSelected ? 'border-rose-500 bg-rose-950/20' : 'border-amber-500/70 bg-amber-950/15'} rounded-2xl text-xs mb-3 shadow-[inset_0_0_15px_rgba(0,0,0,0.5)] cursor-pointer hover:border-amber-400/80 transition active:scale-[0.99]`
        : `p-3 border-2 ${isSelected ? 'border-rose-500 bg-rose-950/20' : 'border-emerald-900/40 bg-black/40'} rounded-2xl text-xs mb-2 shadow-[inset_0_0_15px_rgba(0,0,0,0.5)] cursor-pointer hover:border-emerald-600/50 hover:bg-emerald-950/20 transition active:scale-[0.99]`;
      card.setAttribute('role', 'button');
      card.tabIndex = 0;
      card.onclick = () => {
        if (isSearchSelectMode) {
          toggleSearchItemSelection(index);
          return;
        }
        withResolvedInputHistory(index, (i) => openSearchResultLocation(i));
      };
      card.onkeydown = (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          card.onclick();
        }
      };

      if (isSearchSelectMode) {
        const check = document.createElement('div');
        check.className = `w-6 h-6 mb-2 rounded-lg border-2 ${isSelected ? 'bg-rose-500 border-rose-400 text-white' : 'border-cyan-700 bg-black/50'} flex items-center justify-center text-sm font-black`;
        check.textContent = isSelected ? '✓' : '';
        card.appendChild(check);
      }

      const header = document.createElement('div');
      header.className = 'flex justify-between items-center mb-2 gap-2';
      const badges = document.createElement('div');
      badges.className = 'flex flex-wrap gap-1.5 min-w-0';
      const folderBadge = document.createElement('span');
      folderBadge.className = 'px-2 py-0.5 bg-cyan-950 text-cyan-300 font-extrabold rounded-lg text-[11px] border border-cyan-800/50';
      folderBadge.textContent = entry.folder === 'INBOX' ? '📥 INBOX' : (entry.folder || '');
      const fileBadge = document.createElement('span');
      fileBadge.className = 'px-2 py-0.5 bg-indigo-950 text-indigo-300 font-extrabold rounded-lg text-[11px] border border-indigo-800/50';
      fileBadge.textContent = entry.file || '未整理';
      badges.appendChild(folderBadge);
      badges.appendChild(fileBadge);
      if (hasSimilar) {
        const similarBadge = document.createElement('span');
        similarBadge.className = 'px-2 py-0.5 bg-amber-950/90 text-amber-300 font-extrabold rounded-lg text-[11px] border border-amber-600/60';
        similarBadge.textContent = `類似 ${similarMatches.length}件`;
        badges.appendChild(similarBadge);
      }
      const time = document.createElement('span');
      time.className = 'text-[11px] text-emerald-500/80 font-mono flex-shrink-0';
      time.textContent = formatInputHistoryTime(entry.timestamp);
      header.appendChild(badges);
      header.appendChild(time);

      const content = document.createElement('div');
      content.className = hasSimilar
        ? 'whitespace-pre-wrap font-mono mt-1 bg-amber-950/30 p-2.5 border border-amber-700/40 rounded-xl shadow-inner text-[13px] text-amber-50 leading-relaxed'
        : 'whitespace-pre-wrap font-mono mt-1 bg-[#02040a]/60 p-2.5 border border-emerald-900/40 rounded-xl shadow-inner text-[13px] text-cyan-100 leading-relaxed';
      if (typeof setDumpContentDisplay === 'function') setDumpContentDisplay(content, entry.content || '');
      else content.textContent = entry.content || '';

      const hint = document.createElement('div');
      hint.className = 'mt-1.5 text-[10px] text-emerald-600/80 font-bold';
      hint.textContent = isSearchSelectMode ? 'タップで選択/解除' : '📋 コピーはボタン／カードタップで保存場所へ';

      const actions = document.createElement('div');
      actions.className = 'grid grid-cols-3 gap-2 mt-2.5';
      const editBtn = document.createElement('button');
      editBtn.type = 'button';
      editBtn.className = 'bg-cyan-900/40 text-cyan-200 border-2 border-cyan-700/50 hover:bg-cyan-800/60 font-extrabold h-10 rounded-xl transition active:scale-95 text-xs';
      editBtn.textContent = '✏️ 編集';
      editBtn.onclick = (e) => {
        e.stopPropagation();
        withResolvedInputHistory(index, (i) => {
          editSearchResult(i, e);
        });
      };
      const copyBtn = createCopyButton(
        () => entry.content || '',
        'bg-slate-800/60 text-slate-200 border-2 border-slate-600/60 hover:bg-slate-700/70 font-extrabold h-10 rounded-xl transition active:scale-95 text-xs'
      );
      const deleteBtn = document.createElement('button');
      deleteBtn.type = 'button';
      deleteBtn.className = 'border-2 border-rose-900/50 text-rose-400 hover:bg-rose-950/50 font-extrabold h-10 rounded-xl transition active:scale-95 text-xs';
      deleteBtn.textContent = '🗑️ 削除';
      deleteBtn.onclick = (e) => {
        e.stopPropagation();
        deleteInputHistoryFromSearch(entry, index, e);
      };
      actions.appendChild(editBtn);
      actions.appendChild(copyBtn);
      actions.appendChild(deleteBtn);

      card.appendChild(header);
      card.appendChild(content);
      card.appendChild(hint);
      card.appendChild(actions);

      if (hasSimilar && !isSearchSelectMode) {
        const similarBox = document.createElement('div');
        similarBox.className = 'mt-3 space-y-2 border-t border-amber-800/40 pt-3';
        const similarTitle = document.createElement('div');
        similarTitle.className = 'text-[11px] font-black text-amber-300 mb-1';
        similarTitle.textContent = '🔗 類似している保存済み情報';
        similarBox.appendChild(similarTitle);
        similarMatches.forEach((match) => {
          const row = document.createElement('div');
          row.className = 'flex items-start gap-2 p-2.5 rounded-xl bg-black/40 border border-amber-800/40';
          const meta = document.createElement('div');
          meta.className = 'flex-1 min-w-0';
          const loc = document.createElement('div');
          loc.className = 'text-[11px] font-bold text-amber-200/90 mb-1';
          loc.textContent = `${match.folder || ''} ＞ ${match.file || ''} · 一致率 ${Math.round((match.matchScore || 0) * 100)}%`;
          const preview = document.createElement('div');
          preview.className = 'text-xs text-cyan-100/90 font-mono line-clamp-2 whitespace-pre-wrap';
          if (typeof setDumpContentDisplay === 'function') setDumpContentDisplay(preview, match.content || '');
          else preview.textContent = match.content || '';
          meta.appendChild(loc);
          meta.appendChild(preview);
          const jumpBtn = document.createElement('button');
          jumpBtn.type = 'button';
          jumpBtn.className = 'flex-shrink-0 text-xs bg-amber-900/50 hover:bg-amber-800/60 text-amber-100 px-3 py-2 rounded-lg border border-amber-600/50 font-bold transition active:scale-95';
          jumpBtn.textContent = '開く';
          jumpBtn.onclick = (e) => {
            e.stopPropagation();
            openItemLocation(match);
          };
          const matchCopy = createCopyButton(() => match.content || '', 'flex-shrink-0 text-xs bg-slate-800/70 text-slate-200 px-2.5 py-2 rounded-lg border border-slate-600 font-bold');
          matchCopy.textContent = '📋';
          row.appendChild(meta);
          row.appendChild(matchCopy);
          row.appendChild(jumpBtn);
          similarBox.appendChild(row);
        });
        card.appendChild(similarBox);
      }

      if (inputHistoryRenderState) inputHistoryRenderState.cards.set(index, card);
      return card;
    }

    function renderInputHistoryView() {
      const resultsContainer = document.getElementById('search-results');
      searchResults = [];
      const st = {
        view: inputHistoryView,
        cards: new Map(),
        groups: [],
        indicesByKey: new Map(),
        heading: null,
        banner: null,
        bannerText: null
      };
      inputHistoryRenderState = st;
      inputHistorySimilarMap = inputHistoryView.map((entry, index) => {
        const key = inputHistorySimilarKey(entry);
        const same = st.indicesByKey.get(key);
        if (same) same.push(index);
        else st.indicesByKey.set(key, [index]);
        const hit = inputHistorySimilarStore.get(key);
        return hit ? liveInputHistorySimilar(hit.matches) : [];
      });
      if (inputHistoryView.length === 0) {
        resultsContainer.innerHTML = '<div class="text-center py-8 text-cyan-600 font-bold">入力履歴はまだありません<br><span class="text-xs text-cyan-700/80 font-bold mt-2 inline-block">入力タブでダンプすると、端末間で同期されてここに表示されます</span></div>';
        return;
      }
      resultsContainer.innerHTML = '';
      if (inputHistoryAnalyzing) {
        const analyzingBanner = document.createElement('div');
        analyzingBanner.className = 'text-xs font-bold text-amber-300 mb-3 bg-amber-950/30 border border-amber-800/40 rounded-xl px-3 py-2 flex items-center gap-2';
        analyzingBanner.innerHTML = '<span class="animate-spin">⏳</span><span>類似情報を解析中…（履歴は先に表示しています）</span>';
        st.banner = analyzingBanner;
        st.bannerText = analyzingBanner.lastElementChild;
        resultsContainer.appendChild(analyzingBanner);
      }
      const heading = document.createElement('div');
      heading.className = 'text-xs font-black text-emerald-400/90 tracking-wide min-w-0';
      heading.textContent = inputHistoryHeadingText();
      st.heading = heading;

      const modeBar = document.createElement('div');
      modeBar.className = 'flex flex-wrap gap-1.5 shrink-0';
      [
        { id: 'tree', label: '年→月→日' },
        { id: 'flat', label: 'すべて表示' }
      ].forEach((mode) => {
        const btn = document.createElement('button');
        btn.type = 'button';
        const active = inputHistoryViewMode === mode.id;
        btn.className = 'text-[11px] font-extrabold px-3 py-1.5 rounded-lg border transition active:scale-95 ' + (
          active
            ? 'text-cyan-100 bg-cyan-900/60 border-cyan-500/70'
            : 'text-emerald-300/80 bg-emerald-950/30 border-emerald-800/50 hover:border-emerald-600/60'
        );
        btn.textContent = mode.label;
        btn.title = mode.id === 'tree' ? '年→月→日→入力履歴の順に展開' : '一覧ですべて表示';
        btn.onclick = (e) => {
          e.stopPropagation();
          setInputHistoryViewMode(mode.id);
        };
        modeBar.appendChild(btn);
      });

      const toolbar = document.createElement('div');
      toolbar.className = 'flex flex-wrap justify-between items-center gap-2 mb-3';
      toolbar.appendChild(heading);
      toolbar.appendChild(modeBar);
      resultsContainer.appendChild(toolbar);

      if (inputHistoryViewMode === 'flat') {
        appendInputHistoryFlatCards(resultsContainer, 0);
        return;
      }

      renderInputHistoryTreeView(resultsContainer);
    }
    function getSearchTimestampMs(item) {
      if (!item || item.timestamp == null || item.timestamp === '') return 0;
      const ts = item.timestamp;
      if (typeof ts === 'number') return ts;
      if (ts instanceof Date) return ts.getTime();
      const raw = String(ts).trim();
      // "yyyy/MM/dd HH:mm" や ISO 文字列に対応
      const normalized = raw.includes('T') ? raw : raw.replace(/\//g, '-');
      const ms = new Date(normalized).getTime();
      return Number.isFinite(ms) ? ms : 0;
    }

    function sortSearchResultsByNewest(results) {
      return [...results].sort((a, b) => getSearchTimestampMs(b) - getSearchTimestampMs(a));
    }

    function fortuneAiPromptMeta() {
      const p = typeof getProfileBirth === 'function' ? getProfileBirth() : {};
      const name = (p.name || '').trim() || '対象者';
      const date = p.date || '';
      const time = p.time ? p.time : '';
      const gender = p.gender === 'female' ? '女性' : '男性';
      return { name, date, time, gender };
    }

    function fortuneAiPromptHeader(systems) {
      const meta = fortuneAiPromptMeta();
      const birth = meta.date
        ? `${meta.date}${meta.time ? ' ' + meta.time : '・時間未設定'}`
        : '生年月日未設定';
      return `${systems}の命式です。解説を8割・専門用語を2割で、短く日常語中心にまとめてください（性格・対人・仕事・注意・一手）。用語を使うときは括弧で一言説明。断定・医療・投資は禁止。${meta.name}／${meta.gender}／${birth}`;
    }

    function buildSanmeiAiPromptBody(chart) {
      if (!chart || !chart.day) return '';
      const ds = chart.day.stem;
      const body = chart.body || {};
      const bits = [
        `【算命】日干${SANMEI_STEMS[ds]}${SANMEI_ELEMENTS[ds]}${ds % 2 === 0 ? '陽' : '陰'} 年${chart.year.ganzi} 月${chart.month.ganzi} 日${chart.day.ganzi} 時${chart.hour.ganzi}`
      ];
      try {
        const dc = chart.zokan && chart.zokan.dayCount;
        const zo = (b) => (dc != null ? sanmeiZokanStem(b, dc) : SANMEI_BRANCH_HONKI[b]);
        bits.push(`蔵干 ${SANMEI_STEMS[zo(chart.year.branch)]}${SANMEI_STEMS[zo(chart.month.branch)]}${SANMEI_STEMS[zo(chart.day.branch)]}${SANMEI_STEMS[zo(chart.hour.branch)]}`);
      } catch (e) { }
      try {
        const tenchu = sanmeiTenchusatsuName(chart.day.stem, chart.day.branch);
        if (tenchu) bits.push(tenchu);
        const shuku = sanmeiAnalyzeShukumeiChusatsu(chart);
        if (shuku && shuku.items && shuku.items.length) bits.push(shuku.items.map((x) => x.name).join('・'));
      } catch (e) { }
      bits.push(`星図 頭${body.head || '—'} 胸${body.center || '—'} 腹${body.belly || '—'} 右手${body.rightHand || '—'} 左手${body.leftHand || '—'}／従星 ${body.early || '—'}・${body.mid || '—'}・${body.late || '—'}`);
      try {
        const hachi = typeof sanmeiAnalyzeHachimon === 'function' ? sanmeiAnalyzeHachimon(chart) : window.__sanmeiHachimon;
        if (hachi && hachi.typeName) {
          bits.push(`八門 ${hachi.typeName}${hachi.yinYang || ''}${hachi.junGyaku || ''} 中心主星${(hachi.centerStars || []).join('・') || '—'}`);
        }
      } catch (e) { }
      try {
        const kak = sanmeiAnalyzeKakkyoku(chart);
        const names = [].concat(kak.outer || [], kak.kakuho || [], kak.kyoku || [], kak.jugo || []).map((x) => x.name).filter(Boolean);
        if (names.length) bits.push(names.join('・'));
      } catch (e) { }
      try {
        const isou = sanmeiAnalyzeIsou(chart);
        const rels = (isou.pairs || []).filter((p) => p.relations && p.relations.length).map((p) => `${p.label}${p.relations.join('')}`);
        if (rels.length) bits.push(rels.join(' '));
      } catch (e) { }
      try {
        const dp = window.__sanmeiDaiunPack;
        if (dp && dp.list && dp.list.length) {
          const cur = dp.list.find((x) => x.current) || dp.list[0];
          if (cur) {
            bits.push(`大運${cur.ganzi}(${cur.periodStart}〜${cur.periodEnd}歳・${cur.star}・${cur.juusei}${cur.isDaiunTenchu ? '・大運天中殺' : ''})`);
          }
        }
      } catch (e) { }
      return bits.join('／');
    }

    function buildZiweiAiPromptBody(astrolabe) {
      if (!astrolabe) return '';
      const palaces = (astrolabe.palaces || []).map((p) => {
        const majors = (p.majorStars || []).map((s) => `${s.name}${s.mutagen ? '[' + s.mutagen + ']' : ''}`);
        if (!majors.length && !p.isBodyPalace && p.name !== '命宮' && p.name !== '命宫') return '';
        const tags = [];
        if (p.name === '命宮' || p.name === '命宫') tags.push('命');
        if (p.isBodyPalace) tags.push('身');
        return `${p.name}${p.earthlyBranch || ''}${tags.length ? '(' + tags.join('') + ')' : ''}:${majors.length ? majors.join(',') : '空'}`;
      }).filter(Boolean);
      return `【紫微】命主${astrolabe.soul || '—'} 身主${astrolabe.body || '—'} ${astrolabe.fiveElementsClass || ''} ${palaces.join(' ')}`.replace(/\s+/g, ' ').trim();
    }

    function buildBaziAiPromptBody(analysis) {
      if (!analysis || !analysis.pillars) return '';
      const p = analysis.pillars;
      const col = (key) => {
        const x = p[key];
        if (!x) return '';
        return `${SANMEI_STEMS[x.stem]}${SANMEI_BRANCHES[x.branch]}(${x.stemTg}/${SANMEI_STEMS[x.zo]}${x.zoTg})`;
      };
      const bits = [
        `【四柱】日主${SANMEI_STEMS[analysis.dayStem]} ${analysis.strength || ''} 年${col('year')} 月${col('month')} 日${col('day')} 時${col('hour')}`
      ];
      if (analysis.yongGods && analysis.yongGods.length) bits.push('用神' + analysis.yongGods.slice(0, 3).join('・'));
      if (analysis.chokoYong && analysis.chokoYong.length) bits.push('調候' + analysis.chokoYong.slice(0, 2).map((x) => x.stem).join('・'));
      try {
        const meta = fortuneAiPromptMeta();
        if (meta.date && p.day) {
          const chart = {
            year: { stem: p.year.stem, branch: p.year.branch },
            month: { stem: p.month.stem, branch: p.month.branch },
            day: { stem: p.day.stem, branch: p.day.branch },
            hour: { stem: p.hour.stem, branch: p.hour.branch }
          };
          const gender = meta.gender === '女性' ? 'female' : 'male';
          const daiun = baziListDaiun(chart, meta.date, meta.time || '12:00', gender, 8);
          const now = (daiun.list || []).find((x) => x.current);
          if (now) bits.push(`大運${now.ganzi}${now.tengod}`);
        }
      } catch (e) { }
      try {
        const ln = window.__baziLiunian;
        if (ln && ln.year) {
          bits.push(`流年${ln.year.ganzi}${ln.year.tengod}`);
          bits.push(`流月${ln.month.ganzi}${ln.month.tengod}`);
          bits.push(`流日${ln.day.ganzi}${ln.day.tengod}`);
          bits.push(`流時${ln.hour.ganzi}${ln.hour.tengod}`);
        }
        const gejuPack = window.__baziGejuPack;
        if (gejuPack && gejuPack.primary) bits.push('主格' + gejuPack.primary.name + (gejuPack.primary.broken ? '（破格）' : ''));
        else {
          const geju = window.__baziGeju;
          if (geju && geju.length && geju[0].name) bits.push('格局' + geju.slice(0, 2).map((x) => x.name).join('・'));
        }
        const parPack = window.__baziParentingPack;
        if (parPack && parPack.raise) bits.push(`子育て${parPack.raise.style.label}／育てられ${parPack.raised.style.label}`);
      } catch (e2) { }
      return bits.join('／');
    }

    function buildFortuneAiPrompt(kind) {
      const parts = [];
      const wantSanmei = kind === 'sanmei' || kind === 'all';
      const wantZiwei = kind === 'ziwei' || kind === 'all';
      const wantBazi = kind === 'bazi' || kind === 'all';
      if (wantSanmei) {
        const body = buildSanmeiAiPromptBody(window.__sanmeiSelfChart);
        if (body) parts.push(body);
      }
      if (wantZiwei) {
        const body = buildZiweiAiPromptBody(window.__ziweiAstrolabe);
        if (body) parts.push(body);
      }
      if (wantBazi) {
        const body = buildBaziAiPromptBody(window.__baziAnalysis);
        if (body) parts.push(body);
      }
      if (!parts.length) return '';
      const names = [];
      if (wantSanmei && window.__sanmeiSelfChart) names.push('算命学');
      if (wantZiwei && window.__ziweiAstrolabe) names.push('紫微斗数');
      if (wantBazi && window.__baziAnalysis) names.push('四柱推命');
      return fortuneAiPromptHeader(names.join('・') || '命式') + '\n' + parts.join('\n');
    }

