    function base64ToBlob(b64, mimeType) {
      const bin = atob(String(b64 || '').replace(/\s+/g, ''));
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      return new Blob([bytes], { type: mimeType || 'image/jpeg' });
    }

    async function blobToPngBlob(blob) {
      if (!blob) throw new Error('empty');
      if (blob.type === 'image/png') return blob;
      let bitmap = null;
      try {
        if (typeof createImageBitmap === 'function') bitmap = await createImageBitmap(blob);
      } catch (_) { }
      const draw = (img, w, h) => {
        const canvas = document.createElement('canvas');
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext('2d');
        if (!ctx) throw new Error('canvas');
        ctx.drawImage(img, 0, 0, w, h);
        return new Promise((resolve, reject) => {
          canvas.toBlob((b) => (b ? resolve(b) : reject(new Error('png'))), 'image/png');
        });
      };
      if (bitmap) {
        try {
          return await draw(bitmap, bitmap.width, bitmap.height);
        } finally {
          try { bitmap.close(); } catch (_) { }
        }
      }
      const url = URL.createObjectURL(blob);
      try {
        const img = await new Promise((resolve, reject) => {
          const el = new Image();
          el.onload = () => resolve(el);
          el.onerror = () => reject(new Error('image'));
          el.src = url;
        });
        return await draw(img, img.naturalWidth || img.width, img.naturalHeight || img.height);
      } finally {
        try { URL.revokeObjectURL(url); } catch (_) { }
      }
    }

    async function fetchDumpImageBlobByUrl(url) {
      const rawUrl = String(url || '');
      if (rawUrl.startsWith('https://dump-media.hatterisk3.workers.dev/img/')) {
        try {
          const r = await fetch(rawUrl, { mode: 'cors' });
          if (r && r.ok) return await r.blob();
        } catch (_) { }
        return null;
      }
      const id = typeof extractDriveFileIdFromUrl === 'function' ? extractDriveFileIdFromUrl(url) : '';
      if (!id) return null;
      const res = await callAPI('getDumpImageById', { id }, { silent: true });
      if (!res || res.error || res.success === false || !res.data) return null;
      return base64ToBlob(res.data, res.mimeType || 'image/jpeg');
    }

    async function blobToDataUrl(blob) {
      return await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ''));
        reader.onerror = () => reject(new Error('read'));
        reader.readAsDataURL(blob);
      });
    }

    const DUMP_CLIPBOARD_IMAGES_TYPE = 'web application/x-dump-images+json';

    function filesFromDataUrls(dataUrls) {
      const out = [];
      const list = Array.isArray(dataUrls) ? dataUrls : [];
      for (let i = 0; i < list.length && out.length < DUMP_COMPOSE_IMAGE_MAX; i++) {
        const dataUrl = String(list[i] || '');
        const mm = dataUrl.match(/^data:(image\/[a-zA-Z0-9+.-]+);base64,(.+)$/i);
        if (!mm) continue;
        try {
          const blob = base64ToBlob(mm[2], mm[1]);
          const ext = (mm[1].split('/')[1] || 'png').replace(/[^a-z0-9]/gi, '') || 'png';
          out.push(new File([blob], 'paste-' + (out.length + 1) + '.' + ext, { type: mm[1] }));
        } catch (_) { }
      }
      return out;
    }

    function filesFromHtmlClipboard(html) {
      const out = [];
      const src = String(html || '');
      const re = /<img[^>]+src=["'](data:image\/[a-zA-Z0-9+.-]+;base64,[^"']+)["']/gi;
      let m;
      const urls = [];
      while ((m = re.exec(src)) && urls.length < DUMP_COMPOSE_IMAGE_MAX) {
        urls.push(m[1]);
      }
      return filesFromDataUrls(urls);
    }

    function listDriveImageUrlsFromHtml(html) {
      const out = [];
      const seen = new Set();
      const re = /<img[^>]+src=["']([^"']+)["']/gi;
      let m;
      while ((m = re.exec(String(html || ''))) && out.length < DUMP_COMPOSE_IMAGE_MAX) {
        const src = String(m[1] || '');
        if (!src || /^data:/i.test(src)) continue;
        if (/^https:\/\/dump-media\.hatterisk3\.workers\.dev\/img\//i.test(src)) {
          if (seen.has(src)) continue;
          seen.add(src);
          out.push(src);
          continue;
        }
        const id = typeof extractDriveFileIdFromUrl === 'function'
          ? extractDriveFileIdFromUrl(src)
          : '';
        if (!id || seen.has(id)) continue;
        seen.add(id);
        out.push(src);
      }
      return out;
    }

    async function filesFromDriveHtmlClipboard(html) {
      const urls = listDriveImageUrlsFromHtml(html);
      const out = [];
      for (let i = 0; i < urls.length; i++) {
        try {
          const blob = await fetchDumpImageBlobByUrl(urls[i]);
          if (!blob) continue;
          const mime = blob.type || 'image/jpeg';
          const ext = (mime.split('/')[1] || 'jpg').replace(/[^a-z0-9]/gi, '') || 'jpg';
          out.push(new File([blob], 'paste-drive-' + (out.length + 1) + '.' + ext, { type: mime }));
        } catch (_) { }
      }
      return out;
    }

    function filesFromDumpClipboardJson(raw) {
      try {
        const parsed = JSON.parse(String(raw || ''));
        const images = parsed && Array.isArray(parsed.images) ? parsed.images : [];
        return filesFromDataUrls(images);
      } catch (_) {
        return [];
      }
    }

    function readDumpClipboardImagesFromPaste(cd) {
      if (!cd) return [];
      const types = [
        DUMP_CLIPBOARD_IMAGES_TYPE,
        'application/x-dump-images+json',
        'web application/x-dump-images+json'
      ];
      for (let i = 0; i < types.length; i++) {
        try {
          const raw = cd.getData(types[i]);
          if (raw) {
            const files = filesFromDumpClipboardJson(raw);
            if (files.length) return files;
          }
        } catch (_) { }
      }
      try {
        if (cd.items) {
          for (let i = 0; i < cd.items.length; i++) {
            const it = cd.items[i];
            const t = String((it && it.type) || '');
            if (t.indexOf('x-dump-images') >= 0 && typeof it.getAsString === 'function') {
              // getAsString は非同期なのでここでは使わず、types/getData 優先
            }
          }
        }
      } catch (_) { }
      return [];
    }

    function buildDumpCopyHtml(plain) {
      const htmlEsc = typeof escapeHtmlText === 'function'
        ? escapeHtmlText(plain).replace(/\n/g, '<br>')
        : String(plain || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/\n/g, '<br>');
      return htmlEsc ? ('<div>' + htmlEsc + '</div>') : '<div></div>';
    }

    async function copyPlainTextRobust(text) {
      const value = text == null ? '' : String(text);
      try {
        if (navigator.clipboard && navigator.clipboard.writeText) {
          await navigator.clipboard.writeText(value);
          return true;
        }
      } catch (_) { }
      try {
        const ta = document.createElement('textarea');
        ta.value = value;
        ta.setAttribute('readonly', '');
        ta.style.cssText = 'position:fixed;left:-9999px;top:0;opacity:0;';
        document.body.appendChild(ta);
        ta.focus();
        ta.select();
        try { ta.setSelectionRange(0, ta.value.length); } catch (_) { }
        const ok = document.execCommand('copy');
        document.body.removeChild(ta);
        return !!ok;
      } catch (_) {
        return false;
      }
    }

    /**
     * 📷 単一 Drive 写真 URL をクリップボードへ（image/png）。
     * クリック同一ターンで navigator.clipboard.write を呼ぶ。
     */
    function copySingleDumpImageUrl(url, btn) {
      if (!url) return Promise.resolve(false);
      if (!(navigator.clipboard && navigator.clipboard.write && window.ClipboardItem)) {
        if (btn) flashCopyButton(btn, false);
        alert('このブラウザは写真のコピーに対応していません');
        return Promise.resolve(false);
      }
      if (btn) flashCopyButton(btn, true);

      const pngPromise = (async () => {
        const blob = await fetchDumpImageBlobByUrl(url);
        if (!blob) throw new Error('fetch image failed');
        let png = null;
        try {
          const converted = await blobToPngBlob(blob);
          png = (converted && converted.type === 'image/png')
            ? converted
            : new Blob([converted || blob], { type: 'image/png' });
        } catch (_) {
          png = new Blob([blob], { type: 'image/png' });
        }
        if (!png) throw new Error('no png');
        return png;
      })();

      return navigator.clipboard.write([
        new ClipboardItem({ 'image/png': pngPromise })
      ]).then(() => {
        if (btn) flashCopyButton(btn, true);
        return true;
      }).catch((e) => {
        console.warn('copySingleDumpImageUrl failed', e);
        if (btn) flashCopyButton(btn, false);
        alert('写真のコピーに失敗しました');
        return false;
      });
    }

    /**
     * 📷 Drive URL 付きメモをクリップボードへ。
     * mode: 'both' | 'text' | 'image'
     * opts: { imageIndex?: number, imageUrl?: string }
     * 重要: クリック同一ターンで clipboard.write を呼ぶ（先に await すると権限切れで失敗する）。
     *
     * 注意: 多くの他アプリは image/png があると「画像だけ」貼って文字を捨てる。
     * DUMP は両方読むので both でOK。他アプリへは text / image を分ける。
     */
    function copyDumpContentWithImages(content, mode, opts) {
      opts = opts || {};
      const targetIndex = typeof opts.imageIndex === 'number' ? opts.imageIndex : -1;
      const targetUrl = opts.imageUrl ? String(opts.imageUrl) : '';
      const value = String(content || '');
      const urls = typeof listDumpImageUrls === 'function' ? listDumpImageUrls(value) : [];
      const plain = typeof stripDumpImageTokens === 'function' ? stripDumpImageTokens(value) : value;
      const hasText = !!String(plain || '').trim();
      const wantMode = mode || (hasText ? 'both' : 'image');

      if (wantMode === 'text') {
        return copyPlainTextRobust(plain).then((ok) => !!ok);
      }

      if (!urls.length) return Promise.resolve(false);
      if (!(navigator.clipboard && navigator.clipboard.write && window.ClipboardItem)) {
        return Promise.resolve(false);
      }
      const plainBlob = new Blob([plain || ''], { type: 'text/plain' });

      const loadAssets = async () => {
        const dataUrls = [];
        let firstPng = null;
        let selectedPng = null;
        for (let i = 0; i < urls.length && i < DUMP_COMPOSE_IMAGE_MAX; i++) {
          const u = urls[i];
          const isSelected = (targetIndex >= 0 && i === targetIndex)
            || (targetUrl && (u === targetUrl || (typeof extractDriveFileIdFromUrl === 'function' && extractDriveFileIdFromUrl(u) === extractDriveFileIdFromUrl(targetUrl))));
          const blob = await fetchDumpImageBlobByUrl(u);
          if (!blob) continue;
          try { dataUrls.push(await blobToDataUrl(blob)); } catch (_) { }
          let png = null;
          try {
            const converted = await blobToPngBlob(blob);
            png = (converted && converted.type === 'image/png')
              ? converted
              : new Blob([converted || blob], { type: 'image/png' });
          } catch (_) {
            png = new Blob([blob], { type: 'image/png' });
          }
          if (!firstPng && png) firstPng = png;
          if (isSelected && png) selectedPng = png;
        }
        const finalPng = selectedPng || firstPng;
        if (!finalPng) throw new Error('no image');
        return { dataUrls, firstPng: finalPng };
      };

      const assetsP = loadAssets();
      const writeWith = (itemData) => navigator.clipboard.write([new ClipboardItem(itemData)]);
      const pngPromise = assetsP.then((a) => a.firstPng);

      if (wantMode === 'image' || !hasText) {
        return writeWith({ 'image/png': pngPromise }).then(() => true);
      }

      // both: DUMP 向け。他アプリは画像優先になりがち
      const htmlPromise = assetsP.then((a) => {
        const imgs = (a.dataUrls || []).map((src) => '<img src="' + src + '" alt="">').join('');
        return new Blob([buildDumpCopyHtml(plain) + imgs], { type: 'text/html' });
      });
      const textPlain = Promise.resolve(plainBlob);

      return writeWith({
        'text/plain': textPlain,
        'text/html': htmlPromise,
        'image/png': pngPromise
      })
        .catch(() => writeWith({
          'text/plain': textPlain,
          'image/png': pngPromise
        }))
        .catch(() => writeWith({ 'image/png': pngPromise }))
        .then(() => true);
    }

    function flashCopyButton(btn, ok) {
      if (!btn) return;
      const prevHtml = btn.dataset.html || btn.innerHTML;
      const prevText = btn.dataset.label || btn.textContent;
      btn.dataset.html = prevHtml;
      btn.dataset.label = prevText;
      const iconOnly = btn.classList.contains('input-tab-history-icon-btn')
        && !btn.classList.contains('is-wide');
      btn.textContent = ok
        ? (iconOnly ? '✓' : '✓ 済')
        : (btn.dataset.label || '📋');
      if (ok) {
        setTimeout(() => {
          if (btn.dataset.html && btn.dataset.html.includes('<')) btn.innerHTML = btn.dataset.html;
          else btn.textContent = btn.dataset.label || prevText;
        }, 900);
      }
    }

    function syncDumpCopyChooserViewport() {
      const overlay = document.getElementById('dump-copy-chooser');
      if (!overlay) return;
      const vv = window.visualViewport;
      if (!vv) {
        overlay.style.top = '0px';
        overlay.style.left = '0px';
        overlay.style.width = '100%';
        overlay.style.height = '100%';
        overlay.style.right = 'auto';
        overlay.style.bottom = 'auto';
        return;
      }
      // キーボードで隠れているレイアウト下端ではなく、今見えている範囲の下に出す
      overlay.style.top = Math.round(vv.offsetTop) + 'px';
      overlay.style.left = Math.round(vv.offsetLeft) + 'px';
      overlay.style.width = Math.round(vv.width) + 'px';
      overlay.style.height = Math.round(vv.height) + 'px';
      overlay.style.right = 'auto';
      overlay.style.bottom = 'auto';
    }

    function closeDumpCopyChooser() {
      const el = document.getElementById('dump-copy-chooser');
      if (!el) return;
      if (typeof el._dumpCopyChooserCleanup === 'function') {
        try { el._dumpCopyChooserCleanup(); } catch (_) { }
      }
      el.remove();
    }

    /** 文字＋写真メモ / 写真複数枚メモ: 何をコピーするか選んでもらう */
    function openDumpCopyChooser(content, btn) {
      closeDumpCopyChooser();
      const value = String(content || '');
      const urls = typeof listDumpImageUrls === 'function' ? listDumpImageUrls(value) : [];
      const plain = typeof stripDumpImageTokens === 'function' ? stripDumpImageTokens(value) : value;
      const hasPlain = !!String(plain || '').trim();
      const isMultiImages = urls.length > 1;

      const overlay = document.createElement('div');
      overlay.id = 'dump-copy-chooser';
      overlay.style.cssText = 'position:fixed;z-index:100000;background:rgba(2,4,10,0.72);display:flex;align-items:flex-end;justify-content:center;padding:12px;padding-bottom:calc(12px + env(safe-area-inset-bottom,0px));box-sizing:border-box;';
      overlay.addEventListener('click', (e) => {
        if (e.target === overlay) closeDumpCopyChooser();
      });
      const onViewport = () => syncDumpCopyChooserViewport();
      if (window.visualViewport) {
        window.visualViewport.addEventListener('resize', onViewport);
        window.visualViewport.addEventListener('scroll', onViewport);
      }
      window.addEventListener('resize', onViewport);
      overlay._dumpCopyChooserCleanup = () => {
        if (window.visualViewport) {
          window.visualViewport.removeEventListener('resize', onViewport);
          window.visualViewport.removeEventListener('scroll', onViewport);
        }
        window.removeEventListener('resize', onViewport);
      };

      const sheet = document.createElement('div');
      sheet.style.cssText = 'width:100%;max-width:420px;max-height:85vh;overflow-y:auto;background:#0b1021;border:1px solid rgba(34,211,238,0.35);border-radius:18px;padding:14px;box-shadow:0 0 28px rgba(34,211,238,0.18);';
      const heading = isMultiImages
        ? (hasPlain ? 'どれをコピーしますか？（写真' + urls.length + '枚）' : 'どの写真をコピーしますか？（全' + urls.length + '枚）')
        : 'どちらをコピーしますか？';
      sheet.innerHTML = '<p style="margin:0 0 10px;font-size:13px;font-weight:800;color:#a5f3fc;line-height:1.45;">'
        + heading
        + '</p>';

      const executeCopy = (copyPromise) => {
        closeDumpCopyChooser();
        Promise.resolve(copyPromise).then((ok) => {
          flashCopyButton(btn, !!ok);
          if (!ok) alert('コピーに失敗しました');
        }).catch(() => {
          flashCopyButton(btn, false);
          alert('コピーに失敗しました');
        });
      };

      if (hasPlain) {
        const textBtn = document.createElement('button');
        textBtn.type = 'button';
        textBtn.textContent = '📝 文字だけコピー';
        textBtn.style.cssText = 'display:block;width:100%;margin:0 0 8px;height:46px;border-radius:12px;font-weight:800;font-size:14px;border:1px solid rgba(34,211,238,0.65);background:rgba(8,47,73,0.95);color:#ecfeff;cursor:pointer;';
        textBtn.onclick = (e) => {
          e.stopPropagation();
          executeCopy(copyDumpContentWithImages(value, 'text'));
        };
        sheet.appendChild(textBtn);
      }

      if (!isMultiImages && urls.length === 1) {
        const imgBtn = document.createElement('button');
        imgBtn.type = 'button';
        imgBtn.textContent = '🖼 写真だけコピー';
        imgBtn.style.cssText = 'display:block;width:100%;margin:0 0 8px;height:46px;border-radius:12px;font-weight:800;font-size:14px;border:1px solid rgba(34,211,238,0.65);background:rgba(8,47,73,0.95);color:#ecfeff;cursor:pointer;';
        imgBtn.onclick = (e) => {
          e.stopPropagation();
          executeCopy(copyDumpContentWithImages(value, 'image'));
        };
        sheet.appendChild(imgBtn);
      } else if (isMultiImages) {
        urls.forEach((u, i) => {
          const imgBtn = document.createElement('button');
          imgBtn.type = 'button';
          imgBtn.style.cssText = 'display:flex;align-items:center;gap:10px;width:100%;margin:0 0 8px;padding:6px 12px;min-height:48px;border-radius:12px;font-weight:800;font-size:13px;border:1px solid rgba(34,211,238,0.55);background:rgba(8,47,73,0.9);color:#ecfeff;cursor:pointer;text-align:left;';
          const fileId = typeof extractDriveFileIdFromUrl === 'function' ? extractDriveFileIdFromUrl(u) : '';
          const thumbSrc = fileId && typeof driveImageThumbUrl === 'function'
            ? driveImageThumbUrl(fileId)
            : (/^https:\/\/dump-media\.hatterisk3\.workers\.dev\/img\//i.test(String(u || '')) ? String(u) : '');
          if (thumbSrc) {
            const thumbImg = document.createElement('img');
            thumbImg.src = thumbSrc;
            thumbImg.alt = '';
            thumbImg.style.cssText = 'width:36px;height:36px;object-fit:cover;border-radius:8px;border:1px solid rgba(34,211,238,0.4);flex-shrink:0;background:#000;';
            imgBtn.appendChild(thumbImg);
          }
          const labelSpan = document.createElement('span');
          labelSpan.style.cssText = 'flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;';
          labelSpan.textContent = `🖼 写真 ${i + 1} をコピー`;
          imgBtn.appendChild(labelSpan);

          imgBtn.onclick = (e) => {
            e.stopPropagation();
            // クリック同一ターンで write を開始
            executeCopy(copyDumpContentWithImages(value, 'image', { imageIndex: i, imageUrl: u }));
          };
          sheet.appendChild(imgBtn);
        });
      }

      if (hasPlain && urls.length) {
        const bothBtn = document.createElement('button');
        bothBtn.type = 'button';
        bothBtn.textContent = isMultiImages ? '文字＋すべての写真' : '文字＋写真';
        bothBtn.style.cssText = 'display:block;width:100%;margin:0 0 8px;height:44px;border-radius:12px;font-weight:800;font-size:13px;border:1px solid rgba(100,116,139,0.55);background:rgba(15,23,42,0.9);color:#e2e8f0;cursor:pointer;';
        bothBtn.onclick = (e) => {
          e.stopPropagation();
          executeCopy(copyDumpContentWithImages(value, 'both'));
        };
        sheet.appendChild(bothBtn);
      }

      const cancel = document.createElement('button');
      cancel.type = 'button';
      cancel.textContent = 'キャンセル';
      cancel.style.cssText = 'display:block;width:100%;height:40px;border-radius:12px;font-weight:800;font-size:13px;border:none;background:transparent;color:#94a3b8;cursor:pointer;margin-top:2px;';
      cancel.onclick = (e) => { e.stopPropagation(); closeDumpCopyChooser(); };
      sheet.appendChild(cancel);
      overlay.appendChild(sheet);
      document.body.appendChild(overlay);
      syncDumpCopyChooserViewport();
      requestAnimationFrame(syncDumpCopyChooserViewport);
    }

    async function copyTextToClipboard(text, btn) {
      const value = text == null ? '' : String(text);
      const urls = typeof listDumpImageUrls === 'function' ? listDumpImageUrls(value) : [];
      const hasDumpImages = urls.length > 0;
      const plainForFallback = hasDumpImages && typeof stripDumpImageTokens === 'function'
        ? stripDumpImageTokens(value)
        : value;
      const hasPlain = !!String(plainForFallback || '').trim();

      // 文字＋写真、または写真が複数枚ある場合: 何をコピーするか選んでもらう
      if (hasDumpImages && (hasPlain || urls.length > 1)) {
        openDumpCopyChooser(value, btn);
        return true;
      }

      flashCopyButton(btn, true);
      try {
        if (hasDumpImages) {
          try {
            if (await copyDumpContentWithImages(value, 'image')) return true;
          } catch (imgErr) {
            console.warn('copy image clipboard failed, fallback to text', imgErr);
          }
        }
        if (await copyPlainTextRobust(plainForFallback)) return true;
        throw new Error('copy failed');
      } catch (e) {
        flashCopyButton(btn, false);
        alert('コピーに失敗しました');
        return false;
      }
    }

    function createCopyButton(getText, className) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = className || 'bg-slate-800/60 text-slate-200 border-2 border-slate-600/60 hover:bg-slate-700/70 font-extrabold h-11 rounded-xl transition active:scale-95 text-sm';
      btn.textContent = '📋 コピー';
      btn.onclick = (e) => {
        e.stopPropagation();
        const text = typeof getText === 'function' ? getText() : getText;
        void copyTextToClipboard(text, btn);
      };
      return btn;
    }

    function copyReviewDetailContent(btn) {
      const textarea = document.getElementById('review-edit-textarea');
      const text = textarea
        ? textarea.value
        : ((reviewItems[reviewCurrentIndex] && reviewItems[reviewCurrentIndex].content) || '');
      copyTextToClipboard(text, btn);
    }

    function findReviewItemIndex(item) {
      if (!item || !Array.isArray(reviewItems) || reviewItems.length === 0) return -1;
      if (item.id != null && item.id !== '') {
        const byId = reviewItems.findIndex(r => String(r.id) === String(item.id));
        if (byId >= 0) return byId;
      }
      const content = String(item.content || '').trim();
      return reviewItems.findIndex(r => String(r.content || '').trim() === content);
    }

    function setReviewDetailHydrateHint(show, text) {
      const hint = document.getElementById('review-detail-hydrate-hint');
      if (!hint) return;
      hint.textContent = text || '一覧を同期中…';
      hint.classList.toggle('hidden', !show);
    }

    function setupReviewViewerForJump(item) {
      const isInbox = isSearchInboxItem(item);
      isReviewingInbox = isInbox;
      reviewSelectedFolder = isInbox ? 'INBOX' : (item.folder || '');
      reviewSelectedFile = isInbox ? '未整理' : (item.file || '未整理');
      reviewOpenedFromSearch = true;
      // 確認タブは撤去済み。検索／お気に入り上から詳細オーバーレイだけ開く
      const folderStep = document.getElementById('review-step-folder');
      const fileStep = document.getElementById('review-step-file');
      const viewerStep = document.getElementById('review-step-viewer');
      if (folderStep) folderStep.classList.add('hidden');
      if (fileStep) fileStep.classList.add('hidden');
      if (viewerStep) viewerStep.classList.remove('hidden');
      const pathEl = document.getElementById('review-path-indicator');
      if (pathEl) {
        pathEl.textContent = isInbox
          ? 'INBOX ＞ 未整理'
          : `${reviewSelectedFolder} ＞ ${reviewSelectedFile}`;
      }
      if (typeof setupReviewViewerChrome === 'function') setupReviewViewerChrome();
    }

    async function hydrateReviewLocationList(item) {
      const isInbox = isSearchInboxItem(item);
      const targetId = item && item.id != null ? String(item.id) : '';
      try {
        if (isInbox) {
          const data = await callAPI('getOrganizerData', {}, { silent: true });
          if (data && data.config) configData = data.config;
          reviewItems = (data && data.inbox) || reviewItems;
        } else if (item.file === '未整理') {
          const overview = await callAPI('getReviewOverview', {}, { silent: true });
          configData = (overview && overview.organizer && overview.organizer.config) || configData;
          const pending = ((overview && overview.pendingByFolder) || {})[item.folder] || [];
          reviewItems = pending.length ? pending : reviewItems;
        } else {
          // キャッシュがあれば先に使う
          let fromCache = null;
          try {
            if (storedItemsCache && Array.isArray(storedItemsCache.items) && storedItemsCache.items.length) {
              fromCache = storedItemsCache.items.filter((r) =>
                r && !r.isInbox
                && String(r.folder || '') === String(item.folder || '')
                && String(r.file || '') === String(item.file || '')
              );
            }
          } catch (e) { }
          if (fromCache && fromCache.length) {
            reviewItems = fromCache;
            renderReviewItemsList();
            const cachedIdx = findReviewItemIndex(item);
            if (cachedIdx >= 0) reviewCurrentIndex = cachedIdx;
          }
          const items = await callAPI('getFolderFileItems', {
            folder: reviewSelectedFolder,
            file: reviewSelectedFile
          }, { silent: true });
          if (Array.isArray(items)) reviewItems = items;
          if (!configData || !Object.keys(configData).length) {
            try {
              const data = await callAPI('getOrganizerData', {}, { silent: true });
              if (data && data.config) configData = data.config;
            } catch (e) { }
          }
        }
        renderReviewItemsList();
        const idx = findReviewItemIndex(item);
        if (idx >= 0) {
          reviewCurrentIndex = idx;
          const live = reviewItems[idx];
          const textarea = document.getElementById('review-edit-textarea');
          // ユーザーがまだ編集していないときだけ本文を最新に合わせる
          if (textarea && live && String(textarea.value) === String(textarea.dataset.originalContent || '')) {
            textarea.value = live.content || '';
            textarea.dataset.originalContent = live.content || '';
            const timeEl = document.getElementById('review-detail-time');
            if (timeEl && live.timestamp) timeEl.textContent = `登録: ${live.timestamp}`;
          } else if (textarea && live && targetId && String(live.id) === targetId) {
            // id は揃っているが編集中なら original だけ更新しない（現在の編集を優先）
          }
          updateReviewDetailFavoriteButton();
        }
      } catch (e) {
        // 先に開いた内容で操作は可能なので失敗は黙ってヒントだけ消す
      } finally {
        setReviewDetailHydrateHint(false);
      }
    }

    function openItemLocation(item) {
      if (!item) return;
      return openSearchResultLocationItem(item, { openDetail: true, startEdit: true, instant: true });
    }

    async function openSearchResultLocationItem(item, options = {}) {
      if (!item) return;
      const openDetail = options.openDetail !== false;
      // 検索タブからは常に即開き（一覧は裏で補完）
      setupReviewViewerForJump(item);
      reviewItems = [{ ...item, id: item.id }];
      reviewCurrentIndex = 0;
      if (openDetail) {
        setReviewDetailHydrateHint(true, '一覧を同期中…');
        openReviewDetail(0);
      }
      hydrateReviewLocationList(item);
    }

    function removeFromSearchResultsOptimistic(targetId, deletedContent) {
      if (!Array.isArray(searchResults) || !searchResults.length) return;
      const before = searchResults.length;
      searchResults = searchResults.filter((r) => {
        if (!r) return false;
        if (targetId != null && String(r.id) === String(targetId)) return false;
        if (deletedContent && dumpContentEquals(r.content, deletedContent)) return false;
        return true;
      });
      if (searchResults.length !== before && currentSearchTabMode === 'search') {
        renderSearchResultsView();
      }
    }

    // ---------- お気に入り（端末間でマージ同期） ----------
    const FAVORITES_STORAGE_KEY = 'dump_favorites';
    const FAVORITES_REMOVED_KEY = 'dump_favorites_removed';
    const FAVORITES_CLOUD_FOLDER = '__SYSTEM__';
    const FAVORITES_CLOUD_FILE = 'favorites';
    const FAVORITES_SYNC_POLL_MS = 30000;
    let favoritesCloudTimer = null;
    let favoritesSyncing = false;
    let favoritesPollTimer = null;
    let favoritesStoreReady = false;
    let favoritesAligningLive = false;

    function readFavoritesRaw() {
      try {
        const raw = JSON.parse(localStorage.getItem(FAVORITES_STORAGE_KEY) || '[]');
        return Array.isArray(raw) ? raw : [];
      } catch (e) {
        return [];
      }
    }

    function favoriteHasId(fav, id) {
      if (!fav || id == null || id === '') return false;
      const s = String(id);
      if (fav.id != null && String(fav.id) === s) return true;
      return Array.isArray(fav.ids) && fav.ids.some((x) => x != null && String(x) === s);
    }

    function normalizeFavorite(f) {
      if (!f || typeof f !== 'object') return null;
      const id = f.id != null && f.id !== '' ? String(f.id) : '';
      const content = f.content != null ? String(f.content) : '';
      const ids = [];
      const pushId = (v) => {
        if (v == null || v === '') return;
        const s = String(v);
        if (!ids.includes(s)) ids.push(s);
      };
      pushId(id);
      if (Array.isArray(f.ids)) f.ids.forEach(pushId);
      if (!id && !content && !ids.length) return null;
      const favKey = f.favKey
        ? String(f.favKey)
        : (id ? ('id:' + id) : ('content:' + dumpContentKey(content)));
      if (!favKey) return null;
      return {
        favKey,
        id: id || ids[0] || '',
        ids,
        content,
        folder: f.folder || '',
        file: f.file || '',
        isInbox: !!f.isInbox,
        timestamp: f.timestamp || '',
        favoritedAt: f.favoritedAt || '',
        editedAt: f.editedAt || ''
      };
    }

    function getFavorites() {
      return readFavoritesRaw().map(normalizeFavorite).filter(Boolean);
    }

    function saveFavorites(list, opts) {
      opts = opts || {};
      const beforeKeys = new Set(getFavorites().map((f) => f.favKey));
      const incoming = (list || []).map(normalizeFavorite).filter(Boolean);
      let stored = incoming;
      if (!opts.replace) {
        const map = new Map();
        getFavorites().forEach((f) => map.set(f.favKey, f));
        incoming.forEach((f) => {
          const old = map.get(f.favKey);
          if (!old) {
            map.set(f.favKey, f);
            return;
          }
          const ids = [];
          const pushId = (v) => {
            if (v == null || v === '') return;
            const s = String(v);
            if (!ids.includes(s)) ids.push(s);
          };
          (old.ids || []).forEach(pushId);
          (f.ids || []).forEach(pushId);
          pushId(old.id);
          pushId(f.id);
          const contentSource = pickFavoriteContent(old, f);
          map.set(f.favKey, {
            ...old,
            ...f,
            favKey: old.favKey,
            ids,
            id: f.id || old.id,
            content: contentSource.content || old.content || f.content,
            favoritedAt: old.favoritedAt || f.favoritedAt,
            editedAt: contentSource.editedAt || old.editedAt || f.editedAt || ''
          });
        });
        stored = Array.from(map.values());
      }
      try {
        localStorage.setItem(FAVORITES_STORAGE_KEY, JSON.stringify(stored));
      } catch (e) { }
      if (opts.replace && !opts.skipTombstones) {
        const kept = new Set(stored.map((f) => f.favKey));
        const tombs = readFavoriteTombstones();
        const now = new Date().toISOString();
        beforeKeys.forEach((key) => {
          if (!kept.has(key)) tombs[key] = now;
        });
        writeFavoriteTombstones(tombs);
      }
      if (opts.queueCloud !== false) queueFavoritesCloudSync();
    }

    function favoriteTimeMs(iso) {
      const t = new Date(iso || 0).getTime();
      return Number.isFinite(t) ? t : 0;
    }

    function favoriteRevisionMs(f) {
      if (!f) return 0;
      return Math.max(favoriteTimeMs(f.editedAt), favoriteTimeMs(f.favoritedAt));
    }

    /** 本文は編集時刻が新しい方を残す。同時刻なら先に持っていた方を残す */
    function pickFavoriteContent(current, incoming) {
      if (!current) return incoming;
      if (!incoming) return current;
      const cur = favoriteRevisionMs(current);
      const inc = favoriteRevisionMs(incoming);
      if (inc > cur) return incoming;
      if (cur > inc) return current;
      if (incoming.editedAt && !current.editedAt) return incoming;
      return current;
    }

    function readFavoriteTombstones() {
      try {
        const raw = JSON.parse(localStorage.getItem(FAVORITES_REMOVED_KEY) || '{}');
        return raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
      } catch (e) {
        return {};
      }
    }

    function writeFavoriteTombstones(map) {
      const src = map || {};
      const keys = Object.keys(src);
      if (keys.length > 300) {
        keys.sort((a, b) => favoriteTimeMs(src[a]) - favoriteTimeMs(src[b]));
        keys.slice(0, keys.length - 300).forEach((k) => { delete src[k]; });
      }
      try { localStorage.setItem(FAVORITES_REMOVED_KEY, JSON.stringify(src)); } catch (e) { }
    }

    function favoritesSignature(list, removed) {
      const items = (list || []).map((f) =>
        f.favKey + '@' + (f.favoritedAt || '') + '!' + (f.editedAt || '') + '#' + (f.ids || []).join(',') + '~' + String(f.content || '')
      ).sort();
      const tombs = Object.keys(removed || {}).sort().map((k) => k + '@' + removed[k]);
      return items.join('|') + '||' + tombs.join('|');
    }

    function mergeFavoriteSets(localList, cloudList, localRemoved, cloudRemoved) {
      const removed = {};
      const putRemoved = (key, iso) => {
        if (!key || !iso) return;
        if (!removed[key] || favoriteTimeMs(iso) >= favoriteTimeMs(removed[key])) removed[key] = iso;
      };
      Object.keys(localRemoved || {}).forEach((k) => putRemoved(k, localRemoved[k]));
      Object.keys(cloudRemoved || {}).forEach((k) => putRemoved(k, cloudRemoved[k]));
      const map = new Map();
      const consider = (raw) => {
        const f = normalizeFavorite(raw);
        if (!f) return;
        const tomb = favoriteTimeMs(removed[f.favKey]);
        const at = favoriteTimeMs(f.favoritedAt);
        if (tomb && tomb >= at) return;
        if (tomb && at > tomb) delete removed[f.favKey];
        const old = map.get(f.favKey);
        if (!old) {
          map.set(f.favKey, f);
          return;
        }
        const ids = [];
        const pushId = (v) => {
          if (v == null || v === '') return;
          const s = String(v);
          if (!ids.includes(s)) ids.push(s);
        };
        (old.ids || []).forEach(pushId);
        (f.ids || []).forEach(pushId);
        pushId(old.id);
        pushId(f.id);
        const contentSource = pickFavoriteContent(old, f);
        const newerStar = favoriteTimeMs(f.favoritedAt) >= favoriteTimeMs(old.favoritedAt) ? f : old;
        map.set(f.favKey, {
          ...old,
          ...f,
          favKey: old.favKey,
          ids,
          id: newerStar.id || old.id || f.id,
          content: contentSource.content || old.content || f.content,
          favoritedAt: old.favoritedAt || f.favoritedAt,
          editedAt: contentSource.editedAt || ''
        });
      };
      (localList || []).forEach(consider);
      (cloudList || []).forEach(consider);
      return { list: Array.from(map.values()), removed };
    }

    let favoritesRenderScheduled = false;
    function scheduleFavoritesRender() {
      if (favoritesRenderScheduled) return;
      const favTab = document.getElementById('favorites-mode');
      if (!favTab || !favTab.classList.contains('active')) return;
      favoritesRenderScheduled = true;
      const run = () => {
        favoritesRenderScheduled = false;
        const tab = document.getElementById('favorites-mode');
        if (tab && tab.classList.contains('active')) renderFavoritesList();
      };
      if (typeof queueMicrotask === 'function') queueMicrotask(run);
      else Promise.resolve().then(run);
    }

    function refreshFavoritesUi() {
      scheduleFavoritesRender();
      if (typeof updateReviewDetailFavoriteButton === 'function') updateReviewDetailFavoriteButton();
    }

    async function ensureFavoritesStore() {
      if (favoritesStoreReady) return;
      await callAPI('addConfigRecord', {
        folder: FAVORITES_CLOUD_FOLDER,
        file: FAVORITES_CLOUD_FILE
      }, { silent: true });
      favoritesStoreReady = true;
    }

    function parseFavoritesSnapshot(row) {
      if (!row || row.content == null) return null;
      try {
        const payload = JSON.parse(row.content);
        const favorites = Array.isArray(payload && payload.favorites)
          ? payload.favorites.map(normalizeFavorite).filter(Boolean)
          : [];
        const removed = payload && payload.removed && typeof payload.removed === 'object' && !Array.isArray(payload.removed)
          ? payload.removed
          : {};
        return {
          cloudId: row.id ? String(row.id) : '',
          favorites,
          removed
        };
      } catch (e) {
        return null;
      }
    }

    async function fetchCloudFavoritesSnapshot() {
      const items = await callAPI('getFolderFileItems', {
        folder: FAVORITES_CLOUD_FOLDER,
        file: FAVORITES_CLOUD_FILE
      }, { silent: true });
      if (!Array.isArray(items) || !items.length) return null;
      const parsed = items.map(parseFavoritesSnapshot).filter(Boolean);
      if (!parsed.length) return null;
      let favorites = [];
      let removed = {};
      const cloudIds = [];
      parsed.forEach((p) => {
        const next = mergeFavoriteSets(favorites, p.favorites, removed, p.removed);
        favorites = next.list;
        removed = next.removed;
        if (p.cloudId) cloudIds.push(p.cloudId);
      });
      return { favorites, removed, cloudId: cloudIds[0] || '', cloudIds };
    }

    async function publishFavorites() {
      await ensureFavoritesStore();
      const list = getFavorites();
      const removed = readFavoriteTombstones();
      const existing = await fetchCloudFavoritesSnapshot();
      const cloudSig = favoritesSignature(existing && existing.favorites, existing && existing.removed);
      if (cloudSig === favoritesSignature(list, removed)) return;
      const payload = JSON.stringify({
        v: 1,
        updatedAt: new Date().toISOString(),
        favorites: list,
        removed
      });
      const ids = existing && Array.isArray(existing.cloudIds) && existing.cloudIds.length
        ? existing.cloudIds
        : (existing && existing.cloudId ? [existing.cloudId] : []);
      try {
        await upsertSystemSnapshotRecord({
          cloudId: ids[0] || '',
          extraIds: ids.slice(1),
          folder: FAVORITES_CLOUD_FOLDER,
          file: FAVORITES_CLOUD_FILE,
          content: payload
        });
      } catch (_) {
        throw new Error('favorites_sync');
      }
    }

    function queueFavoritesCloudSync() {
      if (favoritesCloudTimer) clearTimeout(favoritesCloudTimer);
      favoritesCloudTimer = setTimeout(() => {
        favoritesCloudTimer = null;
        syncFavorites().catch(() => { });
      }, 400);
    }

    async function syncFavorites() {
      if (favoritesSyncing) return;
      favoritesSyncing = true;
      try {
        const beforeSig = favoritesSignature(getFavorites(), readFavoriteTombstones());
        const cloud = await fetchCloudFavoritesSnapshot();
        if (cloud) favoritesStoreReady = true;
        const local = getFavorites();
        const localRemoved = readFavoriteTombstones();
        if (favoritesSignature(local, localRemoved) !== beforeSig) {
          queueFavoritesCloudSync();
          return;
        }
        const merged = mergeFavoriteSets(
          local,
          cloud && cloud.favorites,
          localRemoved,
          cloud && cloud.removed
        );
        const localSig = favoritesSignature(local, localRemoved);
        const mergedSig = favoritesSignature(merged.list, merged.removed);
        const cloudSig = favoritesSignature(cloud && cloud.favorites, cloud && cloud.removed);
        if (mergedSig !== localSig) {
          saveFavorites(merged.list, { replace: true, queueCloud: false, skipTombstones: true });
          writeFavoriteTombstones(merged.removed);
          refreshFavoritesUi();
        }
        if (mergedSig !== cloudSig) await publishFavorites();
      } catch (e) {
      } finally {
        favoritesSyncing = false;
      }
    }

    let favoritesPollChecking = false;
    function startFavoritesPoll() {
      if (favoritesPollTimer) return;
      favoritesPollTimer = setInterval(async () => {
        if (document.visibilityState !== 'visible') return;
        if (favoritesPollChecking) return;
        const onFav = !!(document.getElementById('favorites-mode')
          && document.getElementById('favorites-mode').classList.contains('active'));
        if (!onFav) return;
        favoritesPollChecking = true;
        try {
          const changed = await checkPollStampChanged('favorites');
          if (changed) {
            await syncFavorites().catch(() => { });
          }
        } finally {
          favoritesPollChecking = false;
        }
      }, FAVORITES_SYNC_POLL_MS);
    }

    function stopFavoritesPoll() {
      if (!favoritesPollTimer) return;
      clearInterval(favoritesPollTimer);
      favoritesPollTimer = null;
    }

    function isFavoriteId(id) {
      if (id == null || id === '' || (typeof isTempId === 'function' && isTempId(id))) return false;
      return getFavorites().some((f) => favoriteHasId(f, id));
    }

    function itemIsFavorited(item) {
      if (!item) return false;
      if (item.id != null && item.id !== '' && isFavoriteId(item.id)) return true;
      if (!item.content) return false;
      return getFavorites().some((f) => f && dumpContentEquals(f.content, item.content));
    }

    function buildFavoriteRecord(item, extras = {}) {
      if (!item || item.id == null || item.id === '') return null;
      if (typeof isTempId === 'function' && isTempId(item.id)) return null;
      const isInbox = !!(item.isInbox || extras.isInbox || item.folder === 'INBOX' || item.file === '未整理');
      return {
        id: String(item.id),
        content: item.content || '',
        folder: isInbox ? 'INBOX' : (item.folder || extras.folder || ''),
        file: isInbox ? '未整理' : (item.file || extras.file || ''),
        isInbox,
        timestamp: item.timestamp || '',
        favoritedAt: new Date().toISOString()
      };
    }

    function favoriteFallbackId(entry) {
      if (!entry) return '';
      const historyId = entry.id != null ? String(entry.id) : '';
      if (historyId && !isTempId(historyId) && !(typeof isLocalOnlyHistoryId === 'function' && isLocalOnlyHistoryId(historyId))) {
        return 'hist:' + historyId;
      }
      const key = typeof dumpContentKey === 'function' ? dumpContentKey(entry.content) : String(entry.content || '').trim();
      if (!key) return '';
      let h = 2166136261;
      for (let i = 0; i < key.length; i++) {
        h ^= key.charCodeAt(i);
        h = Math.imul(h, 16777619);
      }
      return 'favc:' + (h >>> 0).toString(36);
    }

    /** 登録チェック行からお気に入り用の本体を解決。dump ID が無くても本文で登録できる */
    function getDumpFavoriteTargetFromHistory(entry) {
      if (!entry) return null;
      const dump = typeof findCachedDumpForHistory === 'function' ? findCachedDumpForHistory(entry) : null;
      const dumpId = (dump && dump.id && !(typeof isTempId === 'function' && isTempId(dump.id)))
        ? String(dump.id)
        : (entry.dumpId && !(typeof isTempId === 'function' && isTempId(entry.dumpId))
          ? String(entry.dumpId)
          : '');
      const id = dumpId || favoriteFallbackId(entry);
      if (!id) return null;
      const isInbox = dump
        ? !!(dump.isInbox || historyDestIsInbox(dump.folder))
        : (entry.dumpIsInbox != null
          ? !!entry.dumpIsInbox
          : historyDestIsInbox(entry.folder));
      return {
        id,
        content: entry.content || (dump && dump.content) || '',
        folder: isInbox ? 'INBOX' : ((dump && dump.folder) || entry.folder || ''),
        file: isInbox ? '未整理' : ((dump && dump.file) || entry.file || '未整理'),
        isInbox,
        timestamp: (dump && dump.timestamp) || entry.timestamp || ''
      };
    }

    function isHistoryEntryFavorited(entry) {
      const target = getDumpFavoriteTargetFromHistory(entry);
      if (target && isFavoriteId(target.id)) return true;
      if (entry && entry.content) {
        return getFavorites().some((f) => f && dumpContentEquals(f.content, entry.content));
      }
      return false;
    }

    function toggleFavoriteFromInputHistory(entry, btn) {
      const target = getDumpFavoriteTargetFromHistory(entry);
      if (!target) {
        alert('同期完了までお気に入りに登録できません');
        return false;
      }
      const list = getFavorites();
      const byId = list.filter((f) => favoriteHasId(f, target.id));
      const already = byId.length
        ? byId
        : list.filter((f) => target.content && dumpContentEquals(f.content, target.content));
      if (already.length) {
        const drop = new Set(already.map((f) => f.favKey));
        saveFavorites(list.filter((f) => !drop.has(f.favKey)), { replace: true });
        if (btn) styleFavoriteButton(btn, false);
        const favTab = document.getElementById('favorites-mode');
        if (favTab && favTab.classList.contains('active') && typeof renderFavoritesList === 'function') {
          renderFavoritesList();
        }
        if (typeof updateReviewDetailFavoriteButton === 'function') updateReviewDetailFavoriteButton();
        return false;
      }
      const nowOn = toggleFavorite(target, {
        folder: target.folder,
        file: target.file,
        isInbox: target.isInbox
      });
      if (btn) styleFavoriteButton(btn, nowOn);
      const favTab = document.getElementById('favorites-mode');
      if (favTab && favTab.classList.contains('active') && typeof renderFavoritesList === 'function') {
        renderFavoritesList();
      }
      if (typeof updateReviewDetailFavoriteButton === 'function') updateReviewDetailFavoriteButton();
      return nowOn;
    }

    function addFavorite(item, extras = {}) {
      const rec = buildFavoriteRecord(item, extras);
      if (!rec) return false;
      const list = getFavorites();
      const existing = list.find((f) => favoriteHasId(f, rec.id) || (rec.content && dumpContentEquals(f.content, rec.content)));
      const ids = [];
      const pushId = (v) => {
        if (v == null || v === '') return;
        const s = String(v);
        if (!ids.includes(s)) ids.push(s);
      };
      if (existing) {
        (existing.ids || []).forEach(pushId);
        pushId(existing.id);
        rec.favKey = existing.favKey;
        rec.favoritedAt = existing.favoritedAt || rec.favoritedAt;
      }
      pushId(rec.id);
      rec.ids = ids;
      if (!rec.favKey) rec.favKey = 'fav:' + rec.id + ':' + (rec.favoritedAt || Date.now());
      const next = list.filter((f) => f.favKey !== rec.favKey);
      next.unshift(rec);
      saveFavorites(next);
      return true;
    }

    function removeFavoriteById(id) {
      if (id == null || id === '') return false;
      const next = getFavorites().filter((f) => !favoriteHasId(f, id));
      saveFavorites(next, { replace: true });
      return true;
    }

    /** 編集で dump ID／本文が変わってもお気に入りを引き継ぐ。他のお気に入りは消さない。 */
    function syncFavoriteAfterEdit(opts) {
      opts = opts || {};
      const oldId = opts.oldId != null && opts.oldId !== '' ? String(opts.oldId) : '';
      const newId = opts.newId != null && opts.newId !== '' ? String(opts.newId) : '';
      const oldContent = opts.oldContent != null ? String(opts.oldContent) : '';
      const newContent = opts.newContent != null ? String(opts.newContent) : '';
      if (!oldId && !newId && !oldContent && !newContent) return false;
      const list = getFavorites();
      if (!list.length) return false;
      const realNewId = newId && !(typeof isTempId === 'function' && isTempId(newId)) ? newId : '';
      let matched = list.filter((f) => (oldId && favoriteHasId(f, oldId)) || (realNewId && favoriteHasId(f, realNewId)));
      if (!matched.length && oldContent) {
        matched = list.filter((f) => dumpContentEquals(f.content, oldContent));
      }
      if (!matched.length) return false;
      const matchedKeys = new Set(matched.map((f) => f.favKey));
      const next = list.map((f) => {
        if (!f || !matchedKeys.has(f.favKey)) return f;
        const ids = (f.ids || []).slice();
        const pushId = (v) => {
          if (v == null || v === '' || (typeof isTempId === 'function' && isTempId(v))) return;
          const s = String(v);
          if (!ids.includes(s)) ids.push(s);
        };
        pushId(f.id);
        pushId(oldId);
        pushId(realNewId);
        const takenByOther = !!(realNewId && list.some((o) => o && o.favKey !== f.favKey && !matchedKeys.has(o.favKey) && favoriteHasId(o, realNewId)));
        const keepId = (!takenByOther && realNewId) ? realNewId : (f.id || oldId);
        const isInbox = opts.isInbox != null
          ? !!opts.isInbox
          : !!(f.isInbox || historyDestIsInbox(f.folder));
        return {
          ...f,
          id: keepId,
          ids,
          content: newContent || f.content,
          folder: opts.folder != null
            ? (isInbox ? 'INBOX' : opts.folder)
            : (isInbox ? 'INBOX' : (f.folder || '')),
          file: opts.file != null
            ? (isInbox ? '未整理' : opts.file)
            : (isInbox ? '未整理' : (f.file || '')),
          isInbox,
          timestamp: opts.timestamp || f.timestamp || '',
          favoritedAt: f.favoritedAt || new Date().toISOString(),
          editedAt: (newContent && newContent !== f.content)
            ? new Date().toISOString()
            : (f.editedAt || '')
        };
      });
      saveFavorites(next);
      if (!opts.skipUi) scheduleFavoritesRender();
      return true;
    }

    function toggleFavorite(item, extras = {}) {
      if (!item || item.id == null || item.id === '') {
        alert('この情報はまだ同期中のため、お気に入りに登録できません');
        return false;
      }
      if (typeof isTempId === 'function' && isTempId(item.id)) {
        alert('同期完了までお気に入りに登録できません');
        return false;
      }
      const existing = getFavorites().find((f) => favoriteHasId(f, item.id) || (item.content && dumpContentEquals(f.content, item.content)));
      if (existing) {
        saveFavorites(getFavorites().filter((f) => f.favKey !== existing.favKey), { replace: true });
        return false;
      }
      addFavorite(item, extras);
      return true;
    }

    function styleFavoriteButton(btn, favorited) {
      if (!btn) return;
      if (favorited) {
        btn.textContent = btn.dataset.favLabelOn || '★';
        btn.classList.add('text-amber-300', 'border-amber-500/70', 'bg-amber-950/50');
        btn.classList.remove('text-slate-300', 'border-slate-600/60');
        btn.title = 'お気に入り解除';
        btn.setAttribute('aria-pressed', 'true');
      } else {
        btn.textContent = btn.dataset.favLabelOff || '☆';
        btn.classList.remove('text-amber-300', 'border-amber-500/70', 'bg-amber-950/50');
        btn.title = 'お気に入り';
        btn.setAttribute('aria-pressed', 'false');
      }
    }

    function createFavoriteButton(item, extras = {}, favorited) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.dataset.favLabelOn = '★';
      btn.dataset.favLabelOff = '☆';
      btn.className = 'text-xs bg-slate-800/70 hover:bg-slate-700 text-slate-200 px-2.5 py-2 rounded-xl border border-slate-600/60 transition active:scale-95 font-bold';
      styleFavoriteButton(btn, typeof favorited === 'boolean' ? favorited : itemIsFavorited(item));
      btn.onclick = (e) => {
        e.stopPropagation();
        e.preventDefault();
        const nowOn = toggleFavorite(item, extras);
        styleFavoriteButton(btn, nowOn);
        const favTab = document.getElementById('favorites-mode');
        if (favTab && favTab.classList.contains('active')) renderFavoritesList();
        updateReviewDetailFavoriteButton();
      };
      return btn;
    }

    function updateReviewDetailFavoriteButton() {
      const btn = document.getElementById('review-detail-fav-btn');
      if (!btn || reviewCurrentIndex < 0 || !reviewItems[reviewCurrentIndex]) return;
      const item = reviewItems[reviewCurrentIndex];
      const on = itemIsFavorited(item);
      btn.dataset.favLabelOn = '★ 登録済';
      btn.dataset.favLabelOff = '☆ お気に入り';
      styleFavoriteButton(btn, on);
      if (on) {
        btn.classList.add('text-amber-200', 'border-amber-700/50', 'bg-amber-950/40');
      }
    }

    function toggleFavoriteFromReviewDetail(btn) {
      if (reviewCurrentIndex < 0 || !reviewItems[reviewCurrentIndex]) return;
      const item = reviewItems[reviewCurrentIndex];
      const extras = {
        folder: isReviewingInbox ? 'INBOX' : reviewSelectedFolder,
        file: isReviewingInbox ? '未整理' : reviewSelectedFile,
        isInbox: !!isReviewingInbox || reviewSelectedFile === '未整理'
      };
      const nowOn = toggleFavorite(item, extras);
      if (btn) {
        btn.dataset.favLabelOn = '★ 登録済';
        btn.dataset.favLabelOff = '☆ お気に入り';
        styleFavoriteButton(btn, nowOn);
      }
      if (typeof renderReviewItemsList === 'function') renderReviewItemsList();
      const favTab = document.getElementById('favorites-mode');
      if (favTab && favTab.classList.contains('active')) renderFavoritesList();
    }

    function renderFavoritesList() {
      const listEl = document.getElementById('favorites-list');
      const countEl = document.getElementById('favorites-count');
      if (!listEl) return;
      const favorites = getFavorites();
      if (countEl) countEl.textContent = `${favorites.length}件`;
      listEl.innerHTML = '';
      if (!favorites.length) {
        listEl.innerHTML = '<div class="text-center py-10 text-slate-500 font-bold text-sm border-2 border-dashed border-amber-900/40 rounded-2xl">まだお気に入りがありません<br><span class="text-[11px] text-slate-600">検索・登録チェックの ★ から追加できます</span></div>';
        return;
      }
      const liveById = new Map();
      const putLive = (rows) => {
        (rows || []).forEach((row) => {
          if (!row || row.id == null || row.id === '' || !row.content) return;
          const id = String(row.id);
          if (!liveById.has(id)) liveById.set(id, String(row.content));
        });
      };
      if (typeof pendingDumpCache !== 'undefined') putLive(pendingDumpCache);
      if (typeof storedItemsCache !== 'undefined' && storedItemsCache) putLive(storedItemsCache.items);
      const liveUpdates = [];
      const frag = document.createDocumentFragment();
      favorites.forEach((fav) => {
        const liveContent = liveDumpContentForFavorite(fav, liveById);
        const shown = liveContent || fav.content || '';
        if (liveContent && liveContent !== String(fav.content || '')) {
          liveUpdates.push({ fav, liveContent });
        }
        const card = document.createElement('div');
        card.className = 'px-1.5 py-2 sm:p-4 border border-amber-900/40 sm:border-2 bg-black/40 rounded-xl sm:rounded-2xl text-sm shadow-[inset_0_0_15px_rgba(0,0,0,0.5)]';
        const header = document.createElement('div');
        header.className = 'flex justify-between items-center mb-1.5 sm:mb-2 gap-1.5 sm:gap-2';
        const badges = document.createElement('div');
        badges.className = 'flex flex-wrap gap-1.5 min-w-0';
        const folderBadge = document.createElement('span');
        folderBadge.className = 'px-2.5 py-1 bg-cyan-950 text-cyan-300 font-extrabold rounded-lg text-xs border border-cyan-800/50';
        folderBadge.textContent = fav.folder || (fav.isInbox ? 'INBOX' : '—');
        const fileBadge = document.createElement('span');
        fileBadge.className = 'px-2.5 py-1 bg-indigo-950 text-indigo-300 font-extrabold rounded-lg text-xs border border-indigo-800/50';
        fileBadge.textContent = fav.file || (fav.isInbox ? '未整理' : '—');
        badges.appendChild(folderBadge);
        badges.appendChild(fileBadge);
        const time = document.createElement('span');
        time.className = 'text-[10px] text-amber-500/70 font-mono flex-shrink-0';
        time.textContent = fav.timestamp || '';
        header.appendChild(badges);
        header.appendChild(time);
        const content = document.createElement('div');
        content.className = 'whitespace-pre-wrap font-mono mt-1 bg-[#02040a]/60 px-1.5 py-1.5 sm:p-3 border border-amber-900/40 hover:border-cyan-600/60 rounded-lg sm:rounded-xl shadow-inner text-base text-cyan-100 leading-relaxed cursor-pointer transition active:scale-[0.99]';
        if (typeof setDumpContentDisplay === 'function') setDumpContentDisplay(content, shown);
        else content.textContent = shown;
        content.title = 'タップして開く・編集';
        let tapStartX = 0;
        let tapStartY = 0;
        let tapMoved = false;
        let tapMovedAt = 0;
        const markTapStart = (x, y) => {
          tapStartX = x;
          tapStartY = y;
          tapMoved = false;
        };
        const markTapMove = (x, y) => {
          if (Math.abs(x - tapStartX) > 10 || Math.abs(y - tapStartY) > 10) {
            tapMoved = true;
            tapMovedAt = Date.now();
          }
        };
        content.addEventListener('touchstart', (e) => {
          const t = e.touches && e.touches[0];
          if (t) markTapStart(t.clientX, t.clientY);
        }, { passive: true });
        content.addEventListener('touchmove', (e) => {
          const t = e.touches && e.touches[0];
          if (t) markTapMove(t.clientX, t.clientY);
        }, { passive: true });
        content.addEventListener('pointerdown', (e) => {
          if (e.pointerType === 'touch') return;
          markTapStart(e.clientX, e.clientY);
        }, { passive: true });
        content.addEventListener('pointermove', (e) => {
          if (e.pointerType === 'touch') return;
          markTapMove(e.clientX, e.clientY);
        }, { passive: true });
        content.onclick = (e) => {
          if (tapMoved || (Date.now() - tapMovedAt < 350)) {
            tapMoved = false;
            return;
          }
          if (e.target && e.target.closest && e.target.closest('a')) return;
          const sel = window.getSelection ? String(window.getSelection()) : '';
          if (sel) return;
          const realId = favoriteUsableDumpId(fav) || fav.id;
          openItemLocation({
            id: realId,
            ids: fav.ids,
            content: shown,
            folder: fav.folder,
            file: fav.file,
            isInbox: fav.isInbox,
            timestamp: fav.timestamp
          });
        };
        const actions = document.createElement('div');
        actions.className = 'grid grid-cols-2 gap-1.5 sm:gap-2 mt-2 sm:mt-3';
        const copyBtn = createCopyButton(() => shown || '');
        const unfavBtn = document.createElement('button');
        unfavBtn.type = 'button';
        unfavBtn.className = 'border-2 border-amber-700/50 text-amber-300 bg-amber-950/40 hover:bg-amber-900/50 font-extrabold h-11 rounded-xl transition active:scale-95 text-sm';
        unfavBtn.textContent = '★ 解除';
        unfavBtn.onclick = () => {
          saveFavorites(getFavorites().filter((f) => f.favKey !== fav.favKey), { replace: true });
          renderFavoritesList();
          if (typeof renderReviewItemsList === 'function' && document.getElementById('confirm-mode')?.classList.contains('active')) {
            renderReviewItemsList();
          }
          if (typeof renderSearchResultsView === 'function' && currentSearchTabMode === 'search' && document.getElementById('search-mode')?.classList.contains('active')) {
            renderSearchResultsView();
          }
        };
        actions.appendChild(copyBtn);
        actions.appendChild(unfavBtn);
        card.appendChild(header);
        card.appendChild(content);
        card.appendChild(actions);
        frag.appendChild(card);
      });
      listEl.appendChild(frag);
      if (liveUpdates.length && !favoritesAligningLive) {
        favoritesAligningLive = true;
        try {
          liveUpdates.forEach(({ fav, liveContent }) => {
            syncFavoriteAfterEdit({
              oldId: fav.id,
              newId: fav.id,
              oldContent: fav.content,
              newContent: liveContent,
              folder: fav.folder,
              file: fav.file,
              isInbox: fav.isInbox,
              timestamp: fav.timestamp,
              skipUi: true
            });
          });
        } finally {
          favoritesAligningLive = false;
        }
      }
    }

    function liveDumpContentForFavorite(fav, byId) {
      if (!fav) return '';
      const ids = [];
      if (fav.id) ids.push(String(fav.id));
      (fav.ids || []).forEach((id) => { if (id != null && id !== '' && !ids.includes(String(id))) ids.push(String(id)); });
      if (!ids.length) return '';
      if (byId) {
        for (let i = 0; i < ids.length; i++) {
          const hit = byId.get(ids[i]);
          if (hit) return hit;
        }
        return '';
      }
      const idSet = new Set(ids);
      const lists = [];
      if (typeof pendingDumpCache !== 'undefined' && Array.isArray(pendingDumpCache)) lists.push(pendingDumpCache);
      if (typeof storedItemsCache !== 'undefined' && storedItemsCache && Array.isArray(storedItemsCache.items)) {
        lists.push(storedItemsCache.items);
      }
      for (let i = 0; i < lists.length; i++) {
        const hit = lists[i].find((row) => row && idSet.has(String(row.id)) && row.content);
        if (hit) return String(hit.content);
      }
      return '';
    }

    function formatDupCheckTiming(ms) {
      const n = Math.max(0, Number(ms) || 0);
      if (n < 1) return '1ms未満';
      if (n >= 1000) return `${(n / 1000).toFixed(1)}秒`;
      return `${Math.round(n)}ms`;
    }

    function appendDupCheckTiming(msg) {
      return `${msg} · 重複チェック ${formatDupCheckTiming(lastDupCheckMs)}`;
    }

    function destKeyForItem(item) {
      if (!item) return '';
      const folder = String(item.folder || '').replace(/^📥\s*/, '');
      if (item.isInbox || !folder || folder === 'INBOX') return 'INBOX';
      return `${folder}::${item.file || '未整理'}`;
    }

    function destKeyForDump(destFolder, destFile, isInbox) {
      if (isInbox) return 'INBOX';
      return `${destFolder}::${destFile || '未整理'}`;
    }

    function markSimilarityIndexDirty() {
      similarityIndexBundle.fingerprint = '';
    }

    function addToExactDupIndex(item) {
      if (!item || !item.content) return;
      const k = destKeyForItem(item);
      let set = exactDupIndex.dests.get(k);
      if (!set) {
        set = new Set();
        exactDupIndex.dests.set(k, set);
      }
      set.add(item.content);
    }

    function removeContentFromExactDupIndex(content) {
      if (!content) return;
      exactDupIndex.dests.forEach((set) => { set.delete(content); });
      if (exactDupIndex.history) exactDupIndex.history.delete(content);
    }

    function rebuildExactDupIndex(items) {
      exactDupIndex.dests = new Map();
      exactDupIndex.history = new Set();
      (items || []).forEach(addToExactDupIndex);
      (typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : []).forEach((e) => {
        if (!e || !e.content) return;
        exactDupIndex.history.add(e.content);
        addToExactDupIndex({
          content: e.content,
          folder: e.folder || 'INBOX',
          file: e.file || '未整理',
          isInbox: !e.folder || e.folder === 'INBOX'
        });
      });
      exactDupIndex.hydrated = true;
    }

    function getKnownContentsForDest(destFolder, destFile, isInbox, excludeHistoryId) {
      if (!exactDupIndex.hydrated) {
        rebuildExactDupIndex(mergePendingDumpsInto(storedItemsCache.items || []));
      }
      const known = new Set();
      const destSet = exactDupIndex.dests.get(destKeyForDump(destFolder, destFile, isInbox));
      if (destSet) destSet.forEach((c) => known.add(c));
      if (excludeHistoryId && typeof getLocalInputHistory === 'function') {
        getLocalInputHistory().forEach((e) => {
          if (e && e.id === excludeHistoryId && e.content) known.delete(e.content);
        });
      }
      return known;
    }

    function forgetStoredCacheEntries(patch) {
      if (!patch) return;
      const idSet = new Set((patch.ids || []).filter((id) => id != null).map(String));
      const contentSet = new Set((patch.contents || []).filter(Boolean));
      (patch.items || []).forEach((item) => {
        if (!item) return;
        if (item.id != null) idSet.add(String(item.id));
        if (item.content) contentSet.add(item.content);
      });
      if (!idSet.size && !contentSet.size) return;
      const drop = (item) => {
        if (!item) return false;
        if (item.id != null && idSet.has(String(item.id))) return true;
        if (item.content && contentSet.has(item.content)) return true;
        return false;
      };
      if (storedItemsCache.items) {
        storedItemsCache.items = storedItemsCache.items.filter((item) => !drop(item));
      }
      pendingDumpCache = pendingDumpCache.filter((item) => !drop(item));
      contentSet.forEach((c) => removeContentFromExactDupIndex(c));
      markSimilarityIndexDirty();
    }

    /** ゴミ箱へ移した直後は、移動前に読まれた古い一覧（GAS の読み取りはロックなし・45秒キャッシュ）で復活させない */
    function getRecentDumpTrashGuard() {
      const now = Date.now();
      if (!recentDumpTrashGuard) {
        recentDumpTrashGuard = { ids: new Map(), keys: new Map() };
        try {
          const raw = JSON.parse(localStorage.getItem(RECENT_DUMP_TRASH_STORE) || 'null');
          if (raw && typeof raw === 'object') {
            (Array.isArray(raw.ids) ? raw.ids : []).forEach((p) => {
              if (Array.isArray(p) && p[0] && Number(p[1]) > now) recentDumpTrashGuard.ids.set(String(p[0]), Number(p[1]));
            });
            (Array.isArray(raw.keys) ? raw.keys : []).forEach((p) => {
              if (Array.isArray(p) && p[0] && Number(p[1]) > now) recentDumpTrashGuard.keys.set(String(p[0]), Number(p[1]));
            });
          }
        } catch (e) { }
      }
      const g = recentDumpTrashGuard;
      let expired = false;
      g.ids.forEach((until, id) => {
        if (until <= now) { g.ids.delete(id); expired = true; }
      });
      g.keys.forEach((until, key) => {
        if (until <= now) { g.keys.delete(key); expired = true; }
      });
      if (expired) persistRecentDumpTrashGuard();
      return g;
    }

    function persistRecentDumpTrashGuard() {
      const g = recentDumpTrashGuard;
      if (!g) return;
      try {
        if (!g.ids.size && !g.keys.size) {
          localStorage.removeItem(RECENT_DUMP_TRASH_STORE);
          return;
        }
        localStorage.setItem(RECENT_DUMP_TRASH_STORE, JSON.stringify({
          ids: [...g.ids.entries()].slice(-200),
          keys: [...g.keys.entries()].slice(-200)
        }));
      } catch (e) { }
    }

    function rememberRecentDumpTrash(patch) {
      if (!patch) return;
      const g = getRecentDumpTrashGuard();
      const until = Date.now() + RECENT_DUMP_TRASH_TTL_MS;
      (patch.ids || []).forEach((id) => {
        if (id == null || id === '' || isTempId(id)) return;
        g.ids.set(String(id), until);
      });
      (patch.contents || []).forEach((c) => {
        const key = dumpContentKey(c);
        if (key) g.keys.set(key, until);
      });
      persistRecentDumpTrashGuard();
    }

    function forgetRecentDumpTrash(patch) {
      if (!patch) return;
      const g = getRecentDumpTrashGuard();
      if (!g.ids.size && !g.keys.size) return;
      let changed = false;
      (patch.ids || []).forEach((id) => {
        if (id != null && g.ids.delete(String(id))) changed = true;
      });
      (patch.contents || []).forEach((c) => {
        const key = dumpContentKey(c);
        if (key && g.keys.delete(key)) changed = true;
      });
      if (changed) persistRecentDumpTrashGuard();
    }

    function isRecentlyTrashedDump(item, guard) {
      if (!item) return false;
      const g = guard || getRecentDumpTrashGuard();
      if (item.id != null && g.ids.has(String(item.id))) return true;
      if (!g.keys.size) return false;
      const key = dumpContentKey(item.content);
      return !!(key && g.keys.has(key));
    }

    function queueStoredItemsRefresh() {
      if (storedRefreshQueued || storedItemsCache.promise) return;
      storedRefreshQueued = true;
      runInBackground(async () => {
        storedRefreshQueued = false;
        await collectAllStoredItems(true);
      });
    }

    function invalidateStoredItemsCache(patch) {
      if (patch) forgetStoredCacheEntries(patch);
      storedItemsCache.fetchedAt = 0;
      queueStoredItemsRefresh();
    }

    function warmDuplicateIndexes() {
      collectAllStoredItems().then((items) => {
        rebuildExactDupIndex(items);
        getOrBuildSimilarityBundle(items);
      }).catch(() => { });
    }

    function dumpItemKey(item) {
      if (!item) return '';
      const folder = item.isInbox ? 'INBOX' : (item.folder || '');
      return `${folder}::${item.file || ''}::${item.content || ''}`;
    }

    function rememberDumpedItems(items) {
      const incoming = (items || []).filter((i) => i && i.content);
      if (!incoming.length) return;
      // 同じ本文を再DUMP／取り消しで戻したときは削除直後ガードを外す
      forgetRecentDumpTrash({
        ids: incoming.map((i) => i.id),
        contents: incoming.map((i) => i.content)
      });
      const seen = new Set(incoming.map(dumpItemKey));
      pendingDumpCache = incoming.concat(pendingDumpCache.filter((i) => !seen.has(dumpItemKey(i)))).slice(0, 200);
      if (storedItemsCache.items) {
        storedItemsCache.items = incoming.concat(storedItemsCache.items.filter((i) => !seen.has(dumpItemKey(i))));
        storedItemsCache.fetchedAt = Date.now();
      }
      incoming.forEach((item) => {
        addToExactDupIndex(item);
        if (exactDupIndex.history) exactDupIndex.history.add(item.content);
      });
      exactDupIndex.hydrated = true;
      markSimilarityIndexDirty();
    }

    function patchStoredDumpById(id, patch) {
      if (!id || !patch) return;
      const target = String(id);
      const apply = (list) => (list || []).map((item) => {
        if (!item || String(item.id) !== target) return item;
        return { ...item, ...patch, id: item.id };
      });
      pendingDumpCache = apply(pendingDumpCache);
      if (storedItemsCache.items) storedItemsCache.items = apply(storedItemsCache.items);
    }

    function forgetDumpedItemsByContents(contents, opts) {
      const includeStored = !!(opts && opts.includeStored);
      const drop = new Set((contents || []).map(dumpContentKey).filter(Boolean));
      if (!drop.size) return;
      pendingDumpCache = pendingDumpCache.filter((i) => !drop.has(dumpContentKey(i && i.content)));
      if (storedItemsCache.items) {
        storedItemsCache.items = storedItemsCache.items.filter((i) => {
          if (!drop.has(dumpContentKey(i && i.content))) return true;
          if (includeStored) return false;
          return !i._pending;
        });
      }
      (contents || []).forEach((c) => removeContentFromExactDupIndex(c));
      markSimilarityIndexDirty();
    }

    function mergePendingDumpsInto(allItems) {
      const list = allItems || [];
      const existing = new Set(list.map(dumpItemKey));
      const extras = pendingDumpCache.filter((i) => i && i.content && !existing.has(dumpItemKey(i)));
      const merged = extras.concat(list);
      const guard = getRecentDumpTrashGuard();
      if (!guard.ids.size && !guard.keys.size) return merged;
      return merged.filter((i) => !isRecentlyTrashedDump(i, guard));
    }

    async function collectAllStoredItems(force = false) {
      const now = Date.now();
      const hasItems = Array.isArray(storedItemsCache.items);
      const fresh = hasItems && (now - storedItemsCache.fetchedAt) < STORED_ITEMS_CACHE_MS;
      if (!force && hasItems && fresh) {
        return mergePendingDumpsInto(storedItemsCache.items);
      }
      if (!force && hasItems) {
        queueStoredItemsRefresh();
        return mergePendingDumpsInto(storedItemsCache.items);
      }
      if (storedItemsCache.promise) return storedItemsCache.promise;

      storedItemsCache.promise = (async () => {
        const [organizerData, groupedData] = await Promise.all([
          callAPI('getOrganizerData', {}, { silent: true }),
          callAPI('getAllDataGrouped', { includeSystem: false, includeTrash: false }, { silent: true })
        ]);
        const allItems = [];
        if (!organizerData || organizerData.error) {
          return mergePendingDumpsInto(storedItemsCache.items || []);
        }
        if (organizerData && organizerData.config) configData = organizerData.config;
        if (organizerData && organizerData.inbox) {
          organizerData.inbox.forEach(item => {
            if (item && item.content) {
              allItems.push({
                ...item,
                folder: '📥 INBOX',
                file: '未整理',
                isInbox: true
              });
            }
          });
        }
        if (groupedData && !groupedData.error && Array.isArray(groupedData.items)) {
          groupedData.items.forEach((item) => {
            if (item && item.content) {
              allItems.push({
                id: item.id,
                timestamp: item.timestamp,
                content: item.content,
                folder: item.folder,
                file: item.file,
                isInbox: false
              });
            }
          });
        } else if (organizerData && organizerData.config) {
          // 旧 GAS 向けフォールバック（getAllDataGrouped 未デプロイ時）
          const fetchPromises = [];
          const itemMeta = [];
          Object.keys(organizerData.config).forEach(folder => {
            if (folder === '__SYSTEM__') return;
            if (String(folder).indexOf('ゴミ箱') !== -1) return;
            (organizerData.config[folder] || []).forEach(file => {
              if (String(file) === '削除履歴') return;
              fetchPromises.push(callAPI('getFolderFileItems', { folder, file }, { silent: true }));
              itemMeta.push({ folder, file });
            });
          });
          const CONCURRENCY = 8;
          const fileResults = new Array(fetchPromises.length);
          for (let i = 0; i < fetchPromises.length; i += CONCURRENCY) {
            const slice = fetchPromises.slice(i, i + CONCURRENCY);
            const sliceResults = await Promise.all(slice);
            sliceResults.forEach((items, idx) => {
              fileResults[i + idx] = items;
            });
          }
          fileResults.forEach((items, idx) => {
            if (!Array.isArray(items)) return;
            items.forEach(item => {
              if (item && item.content) {
                allItems.push({
                  ...item,
                  folder: itemMeta[idx].folder,
                  file: itemMeta[idx].file,
                  isInbox: false
                });
              }
            });
          });
        }
        storedItemsCache.items = mergePendingDumpsInto(allItems);
        storedItemsCache.fetchedAt = Date.now();
        rebuildExactDupIndex(storedItemsCache.items);
        markSimilarityIndexDirty();
        return storedItemsCache.items;
      })();

      try {
        return await storedItemsCache.promise;
      } catch (e) {
        throw e;
      } finally {
        storedItemsCache.promise = null;
      }
    }

    function buildBigramSet(s) {
      const set = new Set();
      for (let i = 0; i < s.length - 1; i++) set.add(s.substring(i, i + 2));
      return set;
    }

    function buildSimilarityIndex(allItems) {
      return (allItems || []).map(item => makeSimilarityRecordFromText(item && item.content, item)).filter(entry => entry.raw);
    }

    function makeSimilarityRecordFromText(rawText, item) {
      const raw = String(rawText || '').trim();
      const norm = raw.toLowerCase().replace(/[\s\r\n\t　,.\-#!?！？「」『』（）()\\\[\]]/g, '');
      const pNorm = typeof normalizeTextForSimilarity === 'function' ? normalizeTextForSimilarity(raw) : norm;
      return {
        item: item || { content: raw },
        raw,
        norm,
        pNorm,
        bigrams: pNorm.length >= 2 ? buildBigramSet(pNorm) : new Set(),
        len: pNorm.length
      };
    }

    function buildBigramPostings(index) {
      const postings = new Map();
      (index || []).forEach((entry, i) => {
        if (!entry || !entry.bigrams) return;
        entry.bigrams.forEach((g) => {
          let arr = postings.get(g);
          if (!arr) {
            arr = [];
            postings.set(g, arr);
          }
          arr.push(i);
        });
      });
      return postings;
    }

    function candidateIndicesFromPostings(query, postings, afterIndex, indexLen) {
      if (!query || !query.bigrams || query.bigrams.size === 0) {
        const all = [];
        for (let i = afterIndex + 1; i < indexLen; i++) all.push(i);
        return all;
      }
      const counts = new Map();
      query.bigrams.forEach((g) => {
        const arr = postings.get(g);
        if (!arr) return;
        for (let k = 0; k < arr.length; k++) {
          const i = arr[k];
          if (i <= afterIndex) continue;
          counts.set(i, (counts.get(i) || 0) + 1);
        }
      });
      // 短い文は bigram が1〜2個しかない。minShare=2 固定だと候補0件になるため、長さに応じて下げる
      const bg = query.bigrams.size;
      const minShare = bg <= 2
        ? 1
        : Math.max(2, Math.floor(bg * 0.28));
      const out = [];
      counts.forEach((c, i) => {
        if (c >= minShare) out.push(i);
      });
      return out;
    }

    function getOrBuildSimilarityBundle(allItems) {
      const list = allItems || [];
      const fp = `${list.length}|${storedItemsCache.fetchedAt}|${(list[0] && list[0].id) || ''}|${(list[list.length - 1] && list[list.length - 1].id) || ''}`;
      if (similarityIndexBundle.fingerprint === fp && similarityIndexBundle.index) return similarityIndexBundle;
      const index = buildSimilarityIndex(list);
      similarityIndexBundle = { index, postings: buildBigramPostings(index), fingerprint: fp };
      return similarityIndexBundle;
    }

    function scoreIndexedSimilarity(query, candidate) {
      if (!query || !candidate) return 0;
      if (query.raw === candidate.raw) return 1.0;
      if (query.norm && query.norm === candidate.norm) return 0.98;
      if (query.pNorm.length >= 2 && query.pNorm === candidate.pNorm) return 0.95;
      if (!query.pNorm || !candidate.pNorm) return 0;

      const maxLen = Math.max(query.len, candidate.len);
      const minLen = Math.min(query.len, candidate.len);
      if (maxLen === 0) return 0;

      let inter = 0;
      query.bigrams.forEach(g => { if (candidate.bigrams.has(g)) inter++; });
      const union = query.bigrams.size + candidate.bigrams.size - inter;
      const jaccard = union > 0 ? inter / union : 0;

      // 長さ差が大きい場合は、十分高い Jaccard（ほぼ包含・重複）のときだけ通す
      if (minLen / maxLen < 0.45) {
        return jaccard >= 0.55 ? jaccard : 0;
      }

      if (jaccard >= 0.68) return jaccard;
      // Jaccardが低い場合は重いLevenshteinを省略
      if (jaccard < 0.42) return jaccard;
      // 長い文字列はLevenshteinを省略して高速化
      if (query.len > 160 || candidate.len > 160) return jaccard;

      const dist = calculateLevenshteinDistance(query.pNorm, candidate.pNorm);
      const levSim = 1 - (dist / maxLen);
      return Math.max(jaccard, levSim);
    }

    function isSameHistoryLocation(entry, item) {
      const entryFolder = (entry.folder === 'INBOX' || entry.folder === '📥 INBOX') ? 'INBOX' : (entry.folder || '');
      const itemFolder = isSearchInboxItem(item) ? 'INBOX' : (item.folder || '');
      const entryFile = entry.file || '未整理';
      const itemFile = item.file || '未整理';
      return entryFolder === itemFolder && entryFile === itemFile
        && String(entry.content || '').trim() === String(item.content || '').trim();
    }

    function findSimilarItemsForContent(entry, allItemsOrIndex, limit = 5, minScore = 0.62) {
      let index;
      let postings = null;
      if (allItemsOrIndex && allItemsOrIndex.index && allItemsOrIndex.postings) {
        index = allItemsOrIndex.index;
        postings = allItemsOrIndex.postings;
      } else if (Array.isArray(allItemsOrIndex) && allItemsOrIndex[0] && allItemsOrIndex[0].item) {
        index = allItemsOrIndex;
      } else {
        const bundle = getOrBuildSimilarityBundle(allItemsOrIndex);
        index = bundle.index;
        postings = bundle.postings;
      }
      const raw = String(entry.content || '').trim();
      if (!raw) return [];
      const query = makeSimilarityRecordFromText(raw, entry);
      const threshold = Number.isFinite(minScore) ? minScore : 0.62;

      const matches = [];
      const candIdx = postings
        ? candidateIndicesFromPostings(query, postings, -1, index.length)
        : index.map((_, i) => i);
      for (let n = 0; n < candIdx.length; n++) {
        const candidate = index[candIdx[n]];
        if (!candidate || !candidate.item) continue;
        if (isSameHistoryLocation(entry, candidate.item)) continue;
        // 編集で置き換えた旧本文・tombstone 済みは重複表示しない
        const candKey = dumpContentKey(candidate.item.content);
        if (candKey && inputHistorySuppressedContents.has(candKey)) continue;
        if (typeof isInputHistoryTombstoned === 'function' && isInputHistoryTombstoned(candidate.item)) continue;
        if (dumpContentEquals(candidate.item.content, raw)) continue;
        const score = scoreIndexedSimilarity(query, candidate);
        if (score >= threshold) matches.push({ ...candidate.item, matchScore: score });
      }
      matches.sort((a, b) => (b.matchScore || 0) - (a.matchScore || 0));
      return matches.slice(0, limit);
    }

    function updateSearchSelectUI() {
      const countEl = document.getElementById('search-selected-count');
      if (countEl) countEl.textContent = String(searchSelectedIndices.size);
      const delBtn = document.getElementById('search-bulk-delete-btn');
      if (delBtn) delBtn.disabled = searchSelectedIndices.size === 0;
      ['inbox', 'todo', 'log'].forEach((lane) => {
        const btn = document.getElementById('search-bulk-lane-' + lane);
        if (btn) btn.disabled = searchSelectedIndices.size === 0;
      });
      const toggleBtn = document.getElementById('search-select-toggle-btn');
      if (toggleBtn) {
        toggleBtn.textContent = isSearchSelectMode ? '☑️ 選択中...' : '☑️ まとめて選択';
        toggleBtn.classList.toggle('bg-rose-700/50', isSearchSelectMode);
      }
    }

    function toggleSearchSelectMode(force) {
      isSearchSelectMode = typeof force === 'boolean' ? force : !isSearchSelectMode;
      searchSelectedIndices = new Set();
      const bar = document.getElementById('search-bulk-action-bar');
      if (bar) bar.classList.toggle('hidden', !isSearchSelectMode);
      updateSearchSelectUI();
      if (currentSearchTabMode === 'search' && searchResults.length) {
        renderSearchResultsView();
      } else if (currentSearchTabMode === 'input_history') {
        renderInputHistoryView();
      } else if (currentSearchTabMode === 'similar') {
        // similar view is rebuilt only on full scan; ignore select for now
      }
    }

    function toggleSearchItemSelection(index) {
      if (searchSelectedIndices.has(index)) searchSelectedIndices.delete(index);
      else searchSelectedIndices.add(index);
      updateSearchSelectUI();
      if (currentSearchTabMode === 'search') refreshSearchResultCard(index);
      else if (currentSearchTabMode === 'input_history') refreshInputHistoryCard(index);
    }

    function selectAllSearchItems(selected) {
      searchSelectedIndices = new Set();
      if (selected) {
        const len = currentSearchTabMode === 'input_history' ? inputHistoryView.length : searchResults.length;
        for (let i = 0; i < len; i++) searchSelectedIndices.add(i);
      }
      updateSearchSelectUI();
      if (currentSearchTabMode === 'search') renderSearchResultsView();
      else if (currentSearchTabMode === 'input_history') renderInputHistoryView();
    }

    async function executeBulkDeleteSearchItems() {
      if (searchSelectedIndices.size === 0) return;
      if (!confirm(`選択した ${searchSelectedIndices.size} 件を削除しますか？`)) return;
      const indices = [...searchSelectedIndices].sort((a, b) => b - a);

      if (currentSearchTabMode === 'input_history') {
        const entries = indices.map((index) => inputHistoryView[index]).filter(Boolean);
        if (entries.length === 0) return;
        const removeIds = new Set(entries.map((e) => String(e.id)));
        const removeContents = new Set(entries.map((e) => dumpContentKey(e.content)).filter(Boolean));
        const snapshot = inputHistoryView.slice();
        entries.forEach((e) => suppressReplacedHistoryContent(e.content));
        dropInputHistoryEntries((h) => {
          if (h.id != null && removeIds.has(String(h.id))) return true;
          return removeContents.has(dumpContentKey(h.content));
        });
        toggleSearchSelectMode(false);
        renderInputHistoryView();

        const resultsContainer = document.getElementById('search-results');
        const syncNote = document.createElement('div');
        syncNote.id = 'bulk-delete-sync-note';
        syncNote.className = 'text-center text-cyan-400 text-xs font-bold py-2';
        syncNote.textContent = 'まとめて削除を同期中...';
        if (resultsContainer) resultsContainer.prepend(syncNote);

        const deleteLogId = logOperation('DELETE', `入力履歴 ${entries.length}件を削除`, {
          oldFolder: 'INBOX',
          oldFile: '未整理',
          newFolder: '🗑️ ゴミ箱',
          newFile: '削除履歴',
          contents: entries.map((e) => e && e.content).filter(Boolean)
        });

        runInBackground(async () => {
          const stored = await collectAllStoredItems();
          if (stored && stored.error) throw new Error('fetch_items');
          const inboxMoves = [];
          const dataMoves = [];
          entries.forEach((entry) => {
            if (!entry || !entry.content) return;
            const wantInbox = entry.folder === 'INBOX' || entry.folder === '📥 INBOX';
            const match = (stored || []).find((r) => {
              if (r.content !== entry.content) return false;
              if (wantInbox) return !!(r.isInbox || r.folder === 'INBOX' || r.folder === '📥 INBOX');
              return !r.isInbox && r.folder === entry.folder && r.file === entry.file;
            });
            if (!match || match.id == null) return;
            const move = { id: String(match.id), folder: '🗑️ ゴミ箱', file: '削除履歴' };
            if (isSearchInboxItem(match)) inboxMoves.push(move);
            else dataMoves.push(move);
          });
          const historyIds = entries
            .map((e) => e.id)
            .filter((id) => id && !String(id).startsWith('mig-') && !String(id).startsWith('local-'))
            .map((id) => String(id));
          await syncBulkTrashMoves(inboxMoves, dataMoves, { silent: true });
          for (const idChunk of chunkArray(historyIds, 25)) {
            const res = await callAPI('deleteDataRecords', { ids: idChunk }, { silent: true });
            if (res && res.error) throw new Error('history_delete');
          }
          // 本文一致の残りクラウド履歴も掃除
          for (const entry of entries) {
            if (!entry || !entry.content) continue;
            await removeInputHistoryByContent(entry.content);
          }
          updateBadge();
          invalidateStoredItemsCache({
            ids: inboxMoves.concat(dataMoves).map((m) => m && m.id),
            contents: entries.map((e) => e && e.content).filter(Boolean)
          });
          const note = document.getElementById('bulk-delete-sync-note');
          if (note) note.remove();
        }, {
          onError: (err) => {
            rollbackLoggedOperation(deleteLogId);
            inputHistoryView = snapshot;
            cacheLocalInputHistory(snapshot);
            unsuppressReplacedHistoryContents(entries.map((e) => e && e.content));
            renderInputHistoryView();
            const note = document.getElementById('bulk-delete-sync-note');
            if (note) note.remove();
            const reason = err && err.message ? String(err.message) : '通信エラー';
            alert(`まとめて削除の同期に失敗しました（${reason}）。一覧を復元しました。`);
          }
        });
        return;
      }

      const items = indices.map((index) => searchResults[index]).filter((item) => item && item.id != null);
      items.forEach((item) => unshieldDumpContentFromTrash(item && item.content));
      if (items.length === 0) return;
      const removeIds = new Set(items.map((i) => String(i.id)));
      const deletedContents = items.map((i) => i.content).filter(Boolean);
      const snapshot = searchResults.slice();
      const historySnapshot = getLocalInputHistory();
      const historyViewSnapshot = Array.isArray(inputHistoryView) ? inputHistoryView.slice() : [];
      searchResults = searchResults.filter((i) => !removeIds.has(String(i.id)));
      deletedContents.forEach((c) => suppressReplacedHistoryContent(c));
      dropInputHistoryEntries((e) => deletedContents.some((c) => dumpContentEquals(e.content, c)));
      toggleSearchSelectMode(false);
      renderSearchResultsView();

      const resultsContainer = document.getElementById('search-results');
      const syncNote = document.createElement('div');
      syncNote.id = 'bulk-delete-sync-note';
      syncNote.className = 'text-center text-cyan-400 text-xs font-bold py-2';
      syncNote.textContent = 'まとめて削除を同期中...';
      if (resultsContainer) resultsContainer.prepend(syncNote);

      const deleteLogId = logOperation('DELETE', `検索タブから ${items.length}件を削除`, {
        oldFolder: items[0] && items[0].folder,
        oldFile: items[0] && items[0].file,
        newFolder: '🗑️ ゴミ箱',
        newFile: '削除履歴',
        contents: deletedContents
      });

      runInBackground(async () => {
        const liveItems = items.filter((item) => item && !isDumpContentShieldedFromTrash(item.content));
        if (!liveItems.length) return;
        const inboxMoves = [];
        const dataMoves = [];
        liveItems.forEach((item) => {
          const move = { id: String(item.id), folder: '🗑️ ゴミ箱', file: '削除履歴' };
          if (isSearchInboxItem(item)) inboxMoves.push(move);
          else dataMoves.push(move);
        });
        await syncBulkTrashMoves(inboxMoves, dataMoves, { silent: true });
        for (const content of deletedContents) {
          if (isDumpContentShieldedFromTrash(content)) continue;
          try { await removeInputHistoryByContent(content); } catch (e) { console.warn(e); }
        }
        updateBadge();
        invalidateStoredItemsCache({ ids: items.map((i) => i && i.id), contents: deletedContents });
        const note = document.getElementById('bulk-delete-sync-note');
        if (note) note.remove();
      }, {
        onError: (err) => {
          rollbackLoggedOperation(deleteLogId);
          searchResults = snapshot;
          cacheLocalInputHistory(historySnapshot);
          inputHistoryView = historyViewSnapshot;
          unsuppressReplacedHistoryContents(deletedContents);
          renderSearchResultsView();
          const note = document.getElementById('bulk-delete-sync-note');
          if (note) note.remove();
          const reason = err && err.message ? String(err.message) : '通信エラー';
          alert(`まとめて削除の同期に失敗しました（${reason}）。一覧を復元しました。`);
        }
      });
    }

    function searchItemLane(item) {
      if (!item) return '';
      if (typeof isSearchInboxItem === 'function' && isSearchInboxItem(item)) return 'inbox';
      const folder = String(item.folder || '').replace(/^📥\s*/, '').trim();
      if (folder === 'やることリスト') return 'todo';
      if (folder === 'ログ') return 'log';
      return '';
    }

    function applySearchItemLaneLocal(item, dest) {
      if (!item || !dest) return item;
      const wasInbox = typeof isSearchInboxItem === 'function' ? isSearchInboxItem(item) : !!item.isInbox;
      item.folder = dest.isInbox ? 'INBOX' : dest.folder;
      item.file = dest.file;
      item.isInbox = !!dest.isInbox;
      if (wasInbox !== dest.isInbox && typeof bumpBadgeOptimistic === 'function') {
        bumpBadgeOptimistic(dest.isInbox ? 1 : -1);
      }
      if (item.id != null && typeof patchStoredDumpById === 'function') {
        patchStoredDumpById(item.id, {
          folder: item.folder,
          file: item.file,
          isInbox: item.isInbox
        });
      }
      const contentText = String(item.content || '');
      if (typeof getLocalInputHistory === 'function' && typeof isUsableInputHistoryContent === 'function'
        && isUsableInputHistoryContent(contentText)) {
        const id = item.id != null ? String(item.id) : '';
        const contentKey = typeof dumpContentKey === 'function' ? dumpContentKey(contentText) : contentText;
        const now = new Date().toISOString();
        if (typeof clearInputHistoryTombstoneForContent === 'function') {
          clearInputHistoryTombstoneForContent(contentText);
        }
        if (contentKey && typeof inputHistorySuppressedContents !== 'undefined') {
          inputHistorySuppressedContents.delete(contentKey);
        }
        let matched = 0;
        const next = getLocalInputHistory().map((e) => {
          if (!e) return e;
          const sameId = id && e.id != null && String(e.id) === id;
          const sameDump = id && e.dumpId != null && String(e.dumpId) === id;
          const sameContent = contentKey && typeof dumpContentKey === 'function'
            && dumpContentKey(e.content) === contentKey;
          if (!sameId && !sameDump && !sameContent) return e;
          matched += 1;
          const entryId = e.id != null ? String(e.id) : '';
          if (entryId && typeof isLocalOnlyHistoryId === 'function' && isLocalOnlyHistoryId(entryId)
            && typeof addPendingInputHistoryIds === 'function') {
            addPendingInputHistoryIds([entryId]);
          }
          return {
            ...e,
            folder: dest.folder,
            file: dest.file,
            dumpIsInbox: dest.isInbox,
            dumpId: e.dumpId || id || e.dumpId,
            timestamp: now
          };
        });
        if (!matched) {
          const localId = 'local-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7);
          if (typeof addPendingInputHistoryIds === 'function') addPendingInputHistoryIds([localId]);
          next.unshift({
            id: localId,
            dumpId: id || undefined,
            timestamp: now,
            content: contentText,
            folder: dest.folder,
            file: dest.file,
            dumpIsInbox: dest.isInbox
          });
        }
        if (typeof cacheLocalInputHistory === 'function') cacheLocalInputHistory(next);
        if (typeof flushLocalInputHistoryCache === 'function') flushLocalInputHistoryCache();
        if (typeof publishInputHistoryLane === 'function') {
          runInBackground(async () => {
            try {
              await publishInputHistoryLane(contentText, dest.folder, dest.file);
            } catch (err) {
              console.warn('publishInputHistoryLane', err);
              if (typeof enqueueInputHistoryCloudSync === 'function') {
                enqueueInputHistoryCloudSync([contentText], dest.folder, dest.file);
              }
            }
          });
        } else if (typeof enqueueInputHistoryCloudSync === 'function') {
          enqueueInputHistoryCloudSync([contentText], dest.folder, dest.file);
        }
      }
      if (typeof syncFavoriteAfterEdit === 'function') {
        syncFavoriteAfterEdit({
          oldId: item.id,
          newId: item.id,
          oldContent: item.content,
          newContent: item.content,
          folder: dest.folder,
          file: dest.file,
          isInbox: dest.isInbox
        });
      }
      if (typeof paintInputTabHistory === 'function') {
        paintInputTabHistory(typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : [], {
          force: true,
          skipDupSchedule: true
        });
      }
      if (typeof refreshCheckBlocksListIfVisible === 'function') refreshCheckBlocksListIfVisible();
      return item;
    }

    function createSearchLaneTriageBar(item, index) {
      const row = document.createElement('div');
      row.className = 'search-lane-triage';
      row.setAttribute('role', 'group');
      row.setAttribute('aria-label', '振り分け');
      const current = searchItemLane(item);
      [
        { lane: 'inbox' },
        { lane: 'todo' },
        { lane: 'log' }
      ].forEach(({ lane }) => {
        const label = dumpLaneLabel(lane, { short: true });
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'search-lane-triage-btn' + (current === lane ? ' is-current' : '');
        btn.setAttribute('data-lane', lane);
        btn.textContent = current === lane ? ('今の場所 · ' + label) : (label + 'へ');
        btn.title = label + 'へ振り分け';
        btn.onclick = (e) => triageSearchResultToLane(index, lane, e);
        row.appendChild(btn);
      });
      return row;
    }

    async function triageSearchResultToLane(index, lane, event) {
      if (event) {
        event.preventDefault();
        event.stopPropagation();
      }
      const item = searchResults[index];
      if (!item || item.id == null) {
        alert('この項目は振り分けできません');
        return false;
      }
      if (typeof isTempId === 'function' && isTempId(item.id)) {
        alert('同期完了まで振り分けできません');
        return false;
      }
      const dest = dumpLaneDest(lane);
      if (typeof pauseInputHistoryCloudSync === 'function') pauseInputHistoryCloudSync();
      if (searchItemLane(item) === dest.lane) {
        // 本体はすでにその場所でも、登録チェック未登録なら載せる
        applySearchItemLaneLocal(item, dest);
        if (currentSearchTabMode === 'search') refreshSearchResultCard(index);
        setTimeout(() => {
          if (typeof resumeInputHistoryCloudSync === 'function') resumeInputHistoryCloudSync();
        }, 2500);
        return true;
      }
      const snapshot = { ...item };
      applySearchItemLaneLocal(item, dest);
      if (currentSearchTabMode === 'search') refreshSearchResultCard(index);
      const match = {
        id: item.id,
        folder: snapshot.folder,
        file: snapshot.file,
        isInbox: typeof isSearchInboxItem === 'function' ? isSearchInboxItem(snapshot) : !!snapshot.isInbox,
        content: item.content
      };
      runInBackground(async () => {
        try {
          const ok = await moveDumpMatchToDest(match, dest.folder, dest.file, dest.isInbox);
          if (!ok) throw new Error('move failed');
          if (typeof updateBadge === 'function') updateBadge();
        } finally {
          if (typeof resumeInputHistoryCloudSync === 'function') resumeInputHistoryCloudSync();
          if (typeof paintInputTabHistory === 'function') {
            paintInputTabHistory(typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : [], {
              force: true,
              skipDupSchedule: true
            });
          }
          if (typeof refreshCheckBlocksListIfVisible === 'function') refreshCheckBlocksListIfVisible();
        }
      }, {
        onError: () => {
          applySearchItemLaneLocal(item, {
            lane: searchItemLane(snapshot) || '',
            folder: snapshot.folder || 'INBOX',
            file: snapshot.file || '未整理',
            isInbox: typeof isSearchInboxItem === 'function' ? isSearchInboxItem(snapshot) : !!snapshot.isInbox,
            label: ''
          });
          if (currentSearchTabMode === 'search') refreshSearchResultCard(searchResults.indexOf(item));
          alert('振り分けの同期に失敗しました。場所を戻しました。');
        }
      });
      return true;
    }

    async function executeBulkTriageSearchItems(lane) {
      if (searchSelectedIndices.size === 0) return;
      const dest = dumpLaneDest(lane);
      const indices = [...searchSelectedIndices].sort((a, b) => a - b);
      const targets = indices
        .map((i) => ({ index: i, item: searchResults[i] }))
        .filter(({ item }) => item && item.id != null && !(typeof isTempId === 'function' && isTempId(item.id)))
        .filter(({ item }) => searchItemLane(item) !== dest.lane);
      if (!targets.length) {
        alert('振り分け先がすでに同じか、対象がありません');
        return;
      }
      if (!confirm(`選択した ${targets.length} 件を「${dest.label}」へ振り分けますか？`)) return;
      if (typeof pauseInputHistoryCloudSync === 'function') pauseInputHistoryCloudSync();
      const snapshots = targets.map(({ item }) => ({ item, snap: { ...item } }));
      targets.forEach(({ item }) => applySearchItemLaneLocal(item, dest));
      searchSelectedIndices = new Set();
      updateSearchSelectUI();
      if (currentSearchTabMode === 'search') renderSearchResultsView();
      runInBackground(async () => {
        let failed = 0;
        try {
          for (const { item, snap } of snapshots) {
            const match = {
              id: item.id,
              folder: snap.folder,
              file: snap.file,
              isInbox: typeof isSearchInboxItem === 'function' ? isSearchInboxItem(snap) : !!snap.isInbox,
              content: item.content
            };
            const ok = await moveDumpMatchToDest(match, dest.folder, dest.file, dest.isInbox);
            if (!ok) {
              failed += 1;
              applySearchItemLaneLocal(item, {
                lane: searchItemLane(snap) || '',
                folder: snap.folder || 'INBOX',
                file: snap.file || '未整理',
                isInbox: typeof isSearchInboxItem === 'function' ? isSearchInboxItem(snap) : !!snap.isInbox,
                label: ''
              });
            }
          }
          if (typeof updateBadge === 'function') updateBadge();
          if (failed) throw new Error('partial move fail ' + failed);
        } finally {
          if (typeof resumeInputHistoryCloudSync === 'function') resumeInputHistoryCloudSync();
          if (typeof paintInputTabHistory === 'function') {
            paintInputTabHistory(typeof getLocalInputHistory === 'function' ? getLocalInputHistory() : [], {
              force: true,
              skipDupSchedule: true
            });
          }
          if (typeof refreshCheckBlocksListIfVisible === 'function') refreshCheckBlocksListIfVisible();
          if (currentSearchTabMode === 'search') renderSearchResultsView();
        }
      }, {
        onError: () => {
          if (currentSearchTabMode === 'search') renderSearchResultsView();
          alert('一部の振り分けに失敗しました。失敗分は元の場所に戻しています。');
        }
      });
    }

    function isSearchInboxItem(item) {
      if (!item) return false;
      if (item.isInbox) return true;
      const f = (item.folder || '').toString().trim();
      return f === 'INBOX' || f === '📥 INBOX' || f === '📥  INBOX';
    }
    function prepareSearchItemContext(item) {
      const isInbox = isSearchInboxItem(item);
      isReviewingInbox = isInbox;
      reviewSelectedFolder = isInbox ? 'INBOX' : item.folder;
      reviewSelectedFile = item.file || '未整理';
      reviewItems = [{ ...item, id: item.id }];
      reviewCurrentIndex = 0;
      reviewOpenedFromSearch = true;
    }
    async function deleteSearchResult(index, event) {
      if (event) event.stopPropagation();
      const item = searchResults[index];
      if (!item || item.id == null) {
        alert('この項目は削除できません');
        return false;
      }
      if (!confirm('このデータを削除しますか？')) return false;
      unshieldDumpContentFromTrash(item.content);
      const isInbox = isSearchInboxItem(item);
      const snapshot = searchResults.slice();
      const historySnapshot = getLocalInputHistory();
      const historyViewSnapshot = Array.isArray(inputHistoryView) ? inputHistoryView.slice() : [];
      const deletedContent = item.content;
      const folder = item.folder;
      const file = item.file;
      const targetId = item.id;
      removeFavoriteById(targetId);

      searchResults.splice(index, 1);
      renderSearchResultsView();
      if (isInbox) bumpBadgeOptimistic(-1);
      if (deletedContent) {
        suppressReplacedHistoryContent(deletedContent);
        dropInputHistoryEntries((e) => dumpContentEquals(e.content, deletedContent));
      }

      const resultsContainer = document.getElementById('search-results');
      const syncNote = document.createElement('div');
      syncNote.id = 'search-delete-sync-note';
      syncNote.className = 'text-center text-cyan-400 text-xs font-bold py-2';
      syncNote.textContent = '削除を同期中...';
      if (resultsContainer) resultsContainer.prepend(syncNote);

      const deleteLogId = logOperation('DELETE', isInbox ? 'INBOXのデータを削除' : `${folder} のデータを削除`, {
        oldFolder: isInbox ? 'INBOX' : folder,
        oldFile: isInbox ? '未整理' : file,
        newFolder: '🗑️ ゴミ箱',
        newFile: '削除履歴',
        content: deletedContent,
        id: targetId
      });

      runInBackground(async () => {
        if (isDumpContentShieldedFromTrash(deletedContent)) return;
        if (isInbox) {
          const res = await callAPI('moveInboxItem', { id: targetId, folder: '🗑️ ゴミ箱', file: '削除履歴' }, { silent: true });
          if (res && res.error) throw new Error('delete');
        } else {
          const res = await callAPI('moveDataRecord', { id: targetId, folder: '🗑️ ゴミ箱', file: '削除履歴' }, { silent: true });
          if (res && res.error) throw new Error('delete');
        }
        if (isDumpContentShieldedFromTrash(deletedContent)) return;
        if (deletedContent) await removeInputHistoryByContent(deletedContent);
        if (typeof forgetDumpedItemsByContents === 'function') {
          forgetDumpedItemsByContents([deletedContent], { includeStored: true });
        }
        invalidateStoredItemsCache({ ids: [targetId], contents: [deletedContent] });
        updateBadge();
        const note = document.getElementById('search-delete-sync-note');
        if (note) note.remove();
      }, {
        onError: () => {
          rollbackLoggedOperation(deleteLogId);
          searchResults = snapshot;
          cacheLocalInputHistory(historySnapshot);
          inputHistoryView = historyViewSnapshot;
          unsuppressReplacedHistoryContent(deletedContent);
          renderSearchResultsView();
          if (isInbox) bumpBadgeOptimistic(1);
          const note = document.getElementById('search-delete-sync-note');
          if (note) note.remove();
          alert('削除の同期に失敗しました。一覧を復元しました。');
        }
      });
      return true;
    }
    async function openSearchResultLocation(index, options = {}) {
      const item = searchResults[index];
      if (!item) return;
      return openSearchResultLocationItem(item, {
        openDetail: options.openDetail !== false,
        instant: options.instant !== false
      });
    }
    function editSearchResult(index, event) {
      if (event) event.stopPropagation();
      const item = searchResults[index];
      if (!item || item.id == null) {
        alert('この項目は編集できません');
        return;
      }
      return openSearchResultLocationItem(item, { openDetail: true, instant: true });
    }
    function normalizeTextForSimilarity(str) {
      if (!str) return '';
      return String(str)
        .toLowerCase()
        .replace(/[Ａ-Ｚａ-ｚ０-９]/g, s => String.fromCharCode(s.charCodeAt(0) - 0xfee0))
        .replace(/[\s\r\n\t　、。・,.\-#!?！？「」『』（）()\\\[\]]/g, '')
        .replace(/[のでにはをがとへよりから]/g, '');
    }

    function calculateLevenshteinDistance(a, b) {
      if (a.length === 0) return b.length;
      if (b.length === 0) return a.length;
      const matrix = [];
      for (let i = 0; i <= b.length; i++) matrix[i] = [i];
      for (let j = 0; j <= a.length; j++) matrix[0][j] = j;

      for (let i = 1; i <= b.length; i++) {
        for (let j = 1; j <= a.length; j++) {
          if (b.charAt(i - 1) === a.charAt(j - 1)) {
            matrix[i][j] = matrix[i - 1][j - 1];
          } else {
            matrix[i][j] = Math.min(
              matrix[i - 1][j - 1] + 1,
              matrix[i][j - 1] + 1,
              matrix[i - 1][j] + 1
            );
          }
        }
      }
      return matrix[b.length][a.length];
    }

    function computeTextSimilarityScore(str1, str2) {
      if (!str1 || !str2) return 0;
      const raw1 = String(str1).trim();
      const raw2 = String(str2).trim();
      if (raw1 === raw2) return 1.0;

      const norm1 = raw1.toLowerCase().replace(/[\s\r\n\t　,.\-#!?！？「」『』（）()\\\[\]]/g, '');
      const norm2 = raw2.toLowerCase().replace(/[\s\r\n\t　,.\-#!?！？「」『』（）()\\\[\]]/g, '');
      if (norm1 === norm2) return 0.98;

      const pNorm1 = normalizeTextForSimilarity(raw1);
      const pNorm2 = normalizeTextForSimilarity(raw2);
      if (pNorm1.length >= 2 && pNorm1 === pNorm2) return 0.95;

      if (!pNorm1 || !pNorm2) return 0;

      const maxLen = Math.max(pNorm1.length, pNorm2.length);
      const minLen = Math.min(pNorm1.length, pNorm2.length);
      if (minLen / maxLen < 0.45) return 0;

      const bg1 = buildBigramSet(pNorm1);
      const bg2 = buildBigramSet(pNorm2);
      let inter = 0;
      bg1.forEach(g => { if (bg2.has(g)) inter++; });
      const union = bg1.size + bg2.size - inter;
      const jaccard = union > 0 ? inter / union : 0;
      if (jaccard >= 0.68) return jaccard;
      if (jaccard < 0.42) return jaccard;
      if (pNorm1.length > 160 || pNorm2.length > 160) return jaccard;

      const dist = calculateLevenshteinDistance(pNorm1, pNorm2);
      const levSim = maxLen > 0 ? 1 - (dist / maxLen) : 0;
      return Math.max(jaccard, levSim);
    }

    async function showSimilarItems(opts) {
      const rescan = !!(opts && opts.rescan);
      currentSearchTabMode = 'similar';
      updateSimilarSearchPanelVisibility();
      if (isSearchSelectMode) toggleSearchSelectMode(false);
      const resultsContainer = document.getElementById('search-results');
      const thresholdPct = syncSimilarThresholdUi();
      const threshold = thresholdPct / 100;
      const token = ++similarScanToken;
      const alive = () => token === similarScanToken && currentSearchTabMode === 'similar';
      const busyLabel = rescan ? `一致率 ${thresholdPct}% で再判定中` : '索引で類似を判定中';
      resultsContainer.innerHTML = `<div class="text-center text-amber-400 py-6 font-bold text-sm flex items-center justify-center gap-2"><span class="animate-spin text-lg">⏳</span> <span id="similar-scan-progress">${busyLabel}...</span></div>`;

      try {
        let autoPurgedCount = 0;
        if (!rescan && isAutoPurgeInboxExactEnabled()) {
          const purged = await purgeInboxExactDuplicatesIfEnabled();
          autoPurgedCount = purged.count || 0;
          updateBadge();
        }

        let allItems;
        let fetchMs = 0;
        let bundle;

        if (rescan && similarScanCache && similarScanCache.allItems && similarScanCache.allItems.length >= 2) {
          allItems = similarScanCache.allItems;
          fetchMs = similarScanCache.fetchMs || 0;
          bundle = similarScanCache.bundle || getOrBuildSimilarityBundle(allItems);
        } else {
          const fetchStart = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
          allItems = await collectAllStoredItems(true);
          fetchMs = Math.max(0, ((typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now()) - fetchStart);
          if (!alive()) return;
          if (!allItems || allItems.error) {
            resultsContainer.innerHTML = '<div class="text-center text-rose-400 py-6 font-bold text-sm">データの取得に失敗しました。同期後にもう一度お試しください。</div>';
            return;
          }
          await waitForIdleSlice();
          if (!alive()) return;
          markSimilarityIndexDirty();
          bundle = getOrBuildSimilarityBundle(allItems);
          similarScanCache = { allItems, fetchMs, bundle };
        }

        if (allItems.length < 2) {
          resultsContainer.innerHTML = '<div class="text-center text-slate-400 py-6 font-bold text-sm">比較可能なデータが足りません（2件以上必要）</div>';
          return;
        }

        const matchStart = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
        const index = bundle.index;
        const postings = bundle.postings;
        const groups = await buildSimilarItemGroups(index, postings, threshold, alive, (done, total) => {
          const progress = document.getElementById('similar-scan-progress');
          if (progress) progress.textContent = `${busyLabel}… ${Math.floor((done / Math.max(1, total)) * 100)}%`;
        });
        if (!groups || !alive()) return;
        const matchMs = Math.max(0, ((typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now()) - matchStart);
        const timingLabel = rescan && fetchMs === 0
          ? `再判定 ${formatDupCheckTiming(matchMs)}`
          : `取得 ${formatDupCheckTiming(fetchMs)} · 判定 ${formatDupCheckTiming(matchMs)}`;

        renderSimilarGroupsView(groups, { thresholdPct, timingLabel, autoPurgedCount });
      } catch (err) {
        console.error('Similar search failed', err);
        if (alive()) resultsContainer.innerHTML = '<div class="text-center text-rose-400 py-6 font-bold text-sm">類似データの解析中にエラーが発生しました</div>';
      }
    }

    function editSimilarItem(item) {
      prepareSearchItemContext(item);
      openReviewDetail(0);
    }

    async function deleteSimilarItem(item, cardElement) {
      if (!confirm('この類似データを削除してもよろしいですか？')) return;
      unshieldDumpContentFromTrash(item && item.content);
      if (!item || item.id == null) {
        alert('この項目は削除できません');
        return;
      }
      const isInbox = isSearchInboxItem(item);
      const targetId = item.id;
      const deletedContent = item.content;
      const folder = item.folder;
      const file = item.file;

      if (cardElement) {
        cardElement.style.transition = 'all 0.3s ease';
        cardElement.style.opacity = '0';
        cardElement.style.transform = 'scale(0.95)';
        setTimeout(() => { cardElement.remove(); }, 300);
      }
      if (isInbox) bumpBadgeOptimistic(-1);

      const deleteLogId = logOperation('DELETE', isInbox ? 'INBOXのデータを削除' : `${folder} のデータを削除`, {
        oldFolder: isInbox ? 'INBOX' : folder,
        oldFile: isInbox ? '未整理' : file,
        newFolder: '🗑️ ゴミ箱',
        newFile: '削除履歴',
        content: deletedContent,
        id: targetId
      });

      runInBackground(async () => {
        if (isDumpContentShieldedFromTrash(deletedContent)) return;
        if (isInbox) {
          const res = await callAPI('moveInboxItem', { id: targetId, folder: '🗑️ ゴミ箱', file: '削除履歴' }, { silent: true });
          if (res && res.error) throw new Error('delete');
        } else {
          const res = await callAPI('moveDataRecord', { id: targetId, folder: '🗑️ ゴミ箱', file: '削除履歴' }, { silent: true });
          if (res && res.error) throw new Error('delete');
        }
        if (isDumpContentShieldedFromTrash(deletedContent)) return;
        invalidateStoredItemsCache({ ids: [targetId], contents: [deletedContent] });
        updateBadge();
      }, {
        onError: () => {
          rollbackLoggedOperation(deleteLogId);
          if (isInbox) bumpBadgeOptimistic(1);
          alert('削除の同期に失敗しました。画面を更新して確認してください。');
          showSimilarItems();
        }
      });
    }

    function operationMatchesHistoryFilter(op, filter) {
      if (!filter || filter === 'all') return true;
      if (filter === 'ADD') return op.type === 'ADD';
      if (filter === 'EDIT') return op.type === 'EDIT' || op.type === 'MOVE_EDIT';
      if (filter === 'DELETE') return op.type === 'DELETE';
      return true;
    }

    function setOperationHistoryFilter(filter) {
      operationHistoryFilter = filter || 'all';
      localStorage.setItem('operation_history_filter', operationHistoryFilter);
      renderOperationHistoryView();
    }

    function getOperationTypeLabel(type) {
      if (type === 'ADD') return '🟢 追加';
      if (type === 'MOVE') return '🔵 移動';
      if (type === 'DELETE') return '🔴 削除';
      if (type === 'EDIT') return '🟠 編集';
      if (type === 'MOVE_EDIT') return '🟠 編集';
      return '⚪ 操作';
    }

    function formatOperationDetailsHtml(op) {
      const p = op.payload || {};
      let preview = '';
      if (Array.isArray(p.contents) && p.contents.length) {
        preview = p.contents[0];
        if (p.contents.length > 1) preview += ` …他${p.contents.length - 1}件`;
      } else if (p.content) {
        preview = p.content;
      }
      const folder = p.oldFolder || p.folder || '';
      const file = p.oldFile || p.file || '';
      let html = '';
      if (folder) {
        html += `<div class="text-[10px] text-indigo-400/80 font-bold mt-1">${escapeHtmlText(folder)} ＞ ${escapeHtmlText(file || '未整理')}</div>`;
      }
      if (preview) {
        html += `<div class="mt-2 text-xs text-indigo-300 font-mono opacity-80 whitespace-pre-wrap truncate max-h-[72px]">${escapeHtmlText(preview)}</div>`;
      }
      return html;
    }

    function renderOperationHistoryView() {
      const resultsContainer = document.getElementById('search-results');
      if (!resultsContainer) return;
      const history = JSON.parse(localStorage.getItem('operation_history') || '[]');
      const filtered = history.filter((op) => operationMatchesHistoryFilter(op, operationHistoryFilter));

      resultsContainer.innerHTML = '';

      const filterBar = document.createElement('div');
      filterBar.className = 'mb-4 flex flex-wrap gap-2';
      [
        { id: 'all', label: 'すべて' },
        { id: 'ADD', label: '🟢 追加' },
        { id: 'EDIT', label: '🟠 編集' },
        { id: 'DELETE', label: '🔴 削除' }
      ].forEach((f) => {
        const btn = document.createElement('button');
        btn.type = 'button';
        const active = operationHistoryFilter === f.id;
        btn.className = active
          ? 'text-xs font-bold px-3 py-1.5 rounded-lg border border-indigo-400 bg-indigo-900/60 text-indigo-100 transition active:scale-95'
          : 'text-xs font-bold px-3 py-1.5 rounded-lg border border-indigo-800/50 bg-indigo-950/30 text-indigo-400 hover:text-indigo-200 transition active:scale-95';
        btn.textContent = f.label;
        btn.onclick = () => setOperationHistoryFilter(f.id);
        filterBar.appendChild(btn);
      });
      resultsContainer.appendChild(filterBar);

      if (filtered.length === 0) {
        const empty = document.createElement('div');
        empty.className = 'text-center py-8 text-cyan-600 font-bold';
        empty.textContent = history.length === 0 ? '操作履歴はありません' : '該当する操作履歴はありません';
        resultsContainer.appendChild(empty);
        return;
      }

      filtered.forEach((op) => {
        const timeStr = new Date(op.timestamp).toLocaleString('ja-JP');
        const typeLabel = getOperationTypeLabel(op.type);
        const detailsHtml = formatOperationDetailsHtml(op);

        const card = document.createElement('div');
        card.className = 'bg-black/40 border-2 border-indigo-900/40 rounded-2xl p-4 shadow-[inset_0_0_15px_rgba(0,0,0,0.5)] mb-3';
        card.innerHTML = `
          <div class="flex justify-between items-start mb-2 gap-2">
            <div class="min-w-0">
              <span class="text-xs font-black bg-indigo-950/60 text-indigo-200 px-2 py-1 rounded border border-indigo-800/50 mr-2">${typeLabel}</span>
              <span class="text-xs text-indigo-400 font-bold">${timeStr}</span>
            </div>
            <button type="button" data-op-id="${escapeHtmlText(op.id)}" class="op-history-undo-btn text-xs bg-slate-800/80 hover:bg-slate-700 text-slate-300 px-3 py-1 rounded border border-slate-600 transition font-bold active:scale-95 flex-shrink-0 flex items-center gap-1">
              ↩️ 取り消す
            </button>
          </div>
          <p class="text-sm text-cyan-50 font-bold">${escapeHtmlText(op.description || '')}</p>
          ${detailsHtml}
        `;
        const undoBtn = card.querySelector('.op-history-undo-btn');
        if (undoBtn) {
          undoBtn.onclick = () => undoOperation(op.id);
        }
        resultsContainer.appendChild(card);
      });
    }

    function showOperationHistory() {
      currentSearchTabMode = 'operation_history';
      updateSimilarSearchPanelVisibility();
      if (isSearchSelectMode) toggleSearchSelectMode(false);
      renderOperationHistoryView();
    }
    async function executeSearch() {
      const keyword = document.getElementById('search-keyword').value;
      const resultsContainer = document.getElementById('search-results');
      if (!keyword.trim()) return;
      currentSearchTabMode = "search";
      updateSimilarSearchPanelVisibility();
      if (isSearchSelectMode) toggleSearchSelectMode(false);
      const keepPrevious = Array.isArray(searchResults) && searchResults.length > 0;
      const existingNote = document.getElementById('search-running-note');
      if (existingNote) existingNote.remove();
      if (keepPrevious) {
        const searchingNote = document.createElement('div');
        searchingNote.id = 'search-running-note';
        searchingNote.className = 'text-xs font-bold text-indigo-300 mb-3 bg-indigo-950/30 border border-indigo-800/40 rounded-xl px-3 py-2 flex items-center gap-2';
        searchingNote.innerHTML = '<span class="animate-pulse">🔎</span><span>検索中…（前回の結果を表示したまま更新します）</span>';
        resultsContainer.prepend(searchingNote);
      } else {
        resultsContainer.innerHTML = '<div id="search-running-note" class="text-center text-slate-400 py-4 font-bold text-sm animate-pulse">検索中...</div>';
      }
      try {
        const [dataResults, organizerData] = await Promise.all([
          callAPI('searchData', { keyword: keyword }, { silent: true }),
          callAPI('getOrganizerData', {}, { silent: true })
        ]);
        if (organizerData && organizerData.config) {
          configData = organizerData.config;
        }
        let results = (dataResults || []).filter((r) => {
          if (!r) return false;
          if (typeof isNonUserDumpItem === 'function') return !isNonUserDumpItem(r);
          const folder = String(r.folder || '');
          const file = String(r.file || '');
          if (folder === '__SYSTEM__' || folder.indexOf('__SYSTEM__') !== -1) return false;
          if (folder.indexOf('ゴミ箱') !== -1 || file === '削除履歴') return false;
          return true;
        });
        // searchData が古いデプロイで id 無しの場合に備え、INBOX は organizer から補完
        const hasInboxFromSearch = results.some(r => r.isInbox || r.folder === 'INBOX');
        if (!hasInboxFromSearch && organizerData && organizerData.inbox) {
          const lowerKeyword = keyword.toLowerCase();
          const inboxMatches = organizerData.inbox.filter(item =>
            (item.content && item.content.toLowerCase().includes(lowerKeyword))
          ).map(item => ({
            ...item,
            folder: '📥 INBOX',
            file: '未整理',
            isInbox: true
          }));
          results = inboxMatches.concat(results);
        } else {
          results = results.map(r => {
            if (r.isInbox || r.folder === 'INBOX') {
              return { ...r, folder: '📥 INBOX', file: '未整理', isInbox: true };
            }
            return r;
          });
        }
        // 補完後にもう一度ゴミ箱等を除外
        results = results.filter((r) => !(typeof isNonUserDumpItem === 'function' && isNonUserDumpItem(r)));
        results = sortSearchResultsByNewest(results);
        searchResults = results;
        searchResultsLimit = SEARCH_LIST_CHUNK;
        if (isSearchSelectMode) {
          searchSelectedIndices = new Set();
          updateSearchSelectUI();
        }
        renderSearchResultsView();
      } catch (err) {
        const note = document.getElementById('search-running-note');
        if (note) note.remove();
        if (!keepPrevious) {
          searchResults = [];
          resultsContainer.innerHTML = '<div class="text-center text-rose-400 py-4 font-bold text-sm">エラーが発生しました</div>';
        } else {
          alert('検索に失敗しました。前回の結果を表示したままにしています。');
        }
      }
    }

    function searchItemFavorited(item, favLookup) {
      if (!item) return false;
      if (!favLookup) return itemIsFavorited(item);
      if (item.id != null && item.id !== '' && !(typeof isTempId === 'function' && isTempId(item.id))
        && favLookup.ids.has(String(item.id))) return true;
      return !!(item.content && favLookup.contentKeys.has(dumpContentKey(item.content)));
    }

    function renderSearchResultsView() {
      const resultsContainer = document.getElementById('search-results');
      currentSearchTabMode = "search";
      updateSimilarSearchPanelVisibility();
      resultsContainer.innerHTML = '';
      searchResultCardNodes = new Map();
      if (!searchResults || searchResults.length === 0) {
        resultsContainer.innerHTML = '<div class="text-center text-slate-400 py-4 font-bold text-sm">該当データなし</div>';
        return;
      }
      appendSearchResultCards(resultsContainer, 0);
    }

    function appendSearchResultCards(container, from) {
      const list = searchResults;
      const total = list.length;
      const end = Math.min(total, Math.max(from + SEARCH_LIST_CHUNK, searchResultsLimit));
      const favLookup = buildInputTabFavLookup();
      const frag = document.createDocumentFragment();
      for (let i = from; i < end; i++) frag.appendChild(createSearchResultCard(list[i], i, favLookup));
      container.appendChild(frag);
      searchResultsLimit = end;
      if (end < total) {
        appendSearchListMore(container, total - end, () => {
          if (list === searchResults && currentSearchTabMode === 'search') appendSearchResultCards(container, end);
          else if (currentSearchTabMode === 'search') renderSearchResultsView();
        });
      }
    }

    function refreshSearchResultCard(index) {
      const old = searchResultCardNodes.get(index);
      if (!old || !old.isConnected || !searchResults[index]) return;
      old.replaceWith(createSearchResultCard(searchResults[index], index, buildInputTabFavLookup()));
    }

    function createSearchResultCard(item, index, favLookup) {
      const isSelected = searchSelectedIndices.has(index);
      const card = document.createElement('div');
      card.className = `p-4 border-2 ${isSelected ? 'border-rose-500 bg-rose-950/20' : 'border-cyan-900/50 bg-black/40'} rounded-2xl text-sm mb-2 shadow-[inset_0_0_15px_rgba(0,0,0,0.5)] cursor-pointer hover:border-cyan-600/60 hover:bg-cyan-950/20 transition active:scale-[0.99]`;
      card.setAttribute('role', 'button');
      card.tabIndex = 0;
      card.onclick = () => {
        if (isSearchSelectMode) toggleSearchItemSelection(index);
        else openSearchResultLocation(index);
      };
      card.onkeydown = (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          card.onclick();
        }
      };
      if (isSearchSelectMode) {
        const check = document.createElement('div');
        check.className = `w-6 h-6 mb-2 rounded-lg border-2 ${isSelected ? 'bg-rose-500 border-rose-400 text-white' : 'border-cyan-700 bg-black/50'} flex items-center justify-center text-sm font-black`;
        check.textContent = isSelected ? '✓' : '';
        card.appendChild(check);
      }
      const header = document.createElement('div');
      header.className = 'flex justify-between items-center mb-2 gap-2';
      const badges = document.createElement('div');
      badges.className = 'flex flex-wrap gap-1.5 min-w-0';
      const folderBadge = document.createElement('span');
      folderBadge.className = 'px-2.5 py-1 bg-cyan-950 text-cyan-300 font-extrabold rounded-lg text-xs border border-cyan-800/50';
      folderBadge.textContent = item.folder || '';
      const fileBadge = document.createElement('span');
      fileBadge.className = 'px-2.5 py-1 bg-indigo-950 text-indigo-300 font-extrabold rounded-lg text-xs border border-indigo-800/50';
      fileBadge.textContent = item.file || '';
      badges.appendChild(folderBadge);
      badges.appendChild(fileBadge);
      const time = document.createElement('span');
      time.className = 'text-xs text-cyan-500/70 font-mono flex-shrink-0';
      time.textContent = item.timestamp || '';
      header.appendChild(badges);
      header.appendChild(time);
      const content = document.createElement('div');
      content.className = 'whitespace-pre-wrap font-mono mt-1 bg-[#02040a]/60 p-3 border border-cyan-900/50 rounded-xl shadow-inner text-base text-cyan-100 leading-relaxed';
      if (typeof setDumpContentDisplay === 'function') setDumpContentDisplay(content, item.content || '');
      else content.textContent = item.content || '';
      const hint = document.createElement('div');
      hint.className = 'mt-2 text-[11px] text-cyan-600/80 font-bold';
      hint.textContent = isSearchSelectMode ? 'タップで選択/解除' : 'タップで確認 · 下のボタンで振り分け';
      const actions = document.createElement('div');
      actions.className = 'grid grid-cols-4 gap-2 mt-3';
      const favOn = searchItemFavorited(item, favLookup);
      const favBtn = createFavoriteButton(item, {
        folder: item.folder,
        file: item.file,
        isInbox: !!item.isInbox
      }, favOn);
      favBtn.className = 'bg-amber-950/40 text-amber-200 border-2 border-amber-700/50 hover:bg-amber-900/50 font-extrabold h-11 rounded-xl transition active:scale-95 text-sm';
      favBtn.dataset.favLabelOn = '★';
      favBtn.dataset.favLabelOff = '☆';
      styleFavoriteButton(favBtn, favOn);
      const editBtn = document.createElement('button');
      editBtn.type = 'button';
      editBtn.className = 'bg-cyan-900/40 text-cyan-200 border-2 border-cyan-700/50 hover:bg-cyan-800/60 font-extrabold h-11 rounded-xl transition active:scale-95 text-sm';
      editBtn.textContent = '✏️ 編集';
      editBtn.onclick = (e) => editSearchResult(index, e);
      const copyBtn = createCopyButton(() => item.content || '');
      const deleteBtn = document.createElement('button');
      deleteBtn.type = 'button';
      deleteBtn.className = 'border-2 border-rose-900/50 text-rose-400 hover:bg-rose-950/50 font-extrabold h-11 rounded-xl transition active:scale-95 text-sm';
      deleteBtn.textContent = '🗑️ 削除';
      deleteBtn.onclick = (e) => deleteSearchResult(index, e);
      actions.appendChild(favBtn);
      actions.appendChild(editBtn);
      actions.appendChild(copyBtn);
      actions.appendChild(deleteBtn);
      card.appendChild(header);
      card.appendChild(content);
      card.appendChild(hint);
      if (!isSearchSelectMode) card.appendChild(createSearchLaneTriageBar(item, index));
      card.appendChild(actions);
      searchResultCardNodes.set(index, card);
      return card;
    }
    // Dynamic Sucking Particles Initialization
    function createSuckingParticles() {
      if (document.documentElement.classList.contains('lightweight-mode')) return;
      const container = document.getElementById('floating-icons-container');
      if (!container || container.childElementCount > 0) return;
      const icons = ['📁', '📝', '💡', '✏️', '⭐', '💬', '⚙️', '&lt;/&gt;', '0', '1', '1', '0', '0'];

      function createParticle(isLeft) {
        const el = document.createElement('div');
        const icon = icons[Math.floor(Math.random() * icons.length)];
        el.innerHTML = icon;
        el.className = "absolute top-1/2 text-2xl drop-shadow-[0_0_10px_rgba(255,255,255,0.8)] font-black text-cyan-100 pointer-events-none";

        // Randomize Y path slightly
        const startY = (Math.random() - 0.5) * 300 + 'px';
        const midY = (Math.random() - 0.5) * 100 + 'px';
        const endY = (Math.random() - 0.5) * 20 + 'px';
        const duration = 2.5 + Math.random() * 3 + 's';
        const isBinary = icon === '0' || icon === '1';

        if (isBinary) {
          el.className = "absolute top-1/2 text-sm drop-shadow-[0_0_8px_rgba(34,211,238,0.8)] font-mono font-bold text-cyan-300 pointer-events-none";
        }

        el.style.setProperty('--start-y', startY);
        el.style.setProperty('--mid-y', midY);
        el.style.setProperty('--end-y', endY);

        if (isLeft) {
          el.style.left = '50%';
          el.style.animation = `suck-in-left ${duration} infinite linear`;
        } else {
          el.style.right = '50%';
          el.style.animation = `suck-in-right ${duration} infinite linear`;
        }

        // Stagger start
        el.style.animationDelay = '-' + (Math.random() * 5) + 's';

        container.appendChild(el);
      }
      // Generate particles for both sides
      for (let i = 0; i < 15; i++) {
        createParticle(true);
        createParticle(false);
      }
    }

    async function migrateDraftsToInboxOnBoot() {
      await migrateDraftsToInbox();
    }
    // Call when DOM loads
    document.addEventListener('DOMContentLoaded', () => {
      const lightweightMode = localStorage.getItem('setting_lightweight_mode') === 'true';
      applyLightweightMode(lightweightMode);
      applyColorTheme(getColorTheme());
      // 廃止タブが残っていたら退避／フォルダ直接保存設定を無効化
      try {
        const sub = localStorage.getItem('memo_sub_tab');
        if (sub === 'diary-mode') {
          localStorage.setItem('memo_sub_tab', 'gantt-mode');
        } else if (sub === 'organize-mode' || sub === 'confirm-mode') {
          localStorage.setItem('memo_sub_tab', 'input-mode');
        }
        localStorage.setItem('setting_direct_destination_enabled', 'false');
      } catch (_) { }
      if (typeof restoreLiveInputDraftSync === 'function') restoreLiveInputDraftSync();
      bindInputContentHistoryLock();
      if (typeof bindDumpComposeImageUi === 'function') bindDumpComposeImageUi();
      if (typeof restoreLiveInputDraftFromCacheStorage === 'function') {
        void restoreLiveInputDraftFromCacheStorage();
      }
      syncInputTabHistoryLock();

      const afterSplash = typeof window.__afterBootSplash === 'function'
        ? window.__afterBootSplash
        : function (fn) { setTimeout(fn, 0); };

      // 起動アニメーションの突っかかりを防ぐため、初期表示に不要なバインド・掃除はスプラッシュ完了後に分割実行
      afterSplash(() => {
        bindSimilarThresholdControls();
        renderAppBuildTag();
        updateSkipInputTopUI();
        if (typeof bindAppEdgeBackGesture === 'function') bindAppEdgeBackGesture();
        if (typeof bindAppBrowserBack === 'function') bindAppBrowserBack();
        if (typeof toggleDirectDestinationUI === 'function') toggleDirectDestinationUI();
      });

      afterSplash(() => {
        migrateDraftsToInboxOnBoot();
        setupServiceWorkerUpdates();
        // 古いキャッシュHTMLに日記ナビ／画面が残っていても強制撤去
        try {
          ['diary-mode', 'memo-sub-diary-mode'].forEach((id) => {
            const el = document.getElementById(id);
            if (el) el.remove();
          });
          document.querySelectorAll('#memo-sub-nav .memo-sub-btn').forEach((btn) => {
            const label = String(btn.textContent || '');
            const onclick = String(btn.getAttribute('onclick') || '');
            if (label.indexOf('日記') >= 0 || onclick.indexOf('diary-mode') >= 0) btn.remove();
          });
          if (typeof contextHelp !== 'undefined' && contextHelp && contextHelp['diary-mode']) {
            delete contextHelp['diary-mode'];
          }
        } catch (_) { }
      });
    });

    const APP_BUILD = window.__DUMP_BUILD__ || 'v456';
    function renderAppBuildTag() {
      ['app-build-tag', 'app-build-tag-settings'].forEach((id) => {
        const el = document.getElementById(id);
        if (el) el.textContent = APP_BUILD;
      });
    }

    // 手動クリア専用。起動処理からは絶対に呼ばない（控えが消えて起動不能になるため）
    async function wipeDumpAppCachesAndWorkers() {
      try {
        if (typeof caches !== 'undefined' && caches.keys) {
          const keys = await caches.keys();
          await Promise.all(
            keys
              .filter((key) => String(key).indexOf('dump-app-') === 0)
              .map((key) => caches.delete(key))
          );
        }
      } catch (_) { }
      try {
        if ('serviceWorker' in navigator) {
          const regs = await navigator.serviceWorker.getRegistrations();
          await Promise.all(regs.map((reg) => reg.unregister()));
        }
      } catch (_) { }
    }

    async function forceClearDumpAppCache() {
      const status = document.getElementById('app-cache-clear-status');
      if (!confirm('アプリのキャッシュと Service Worker を消去して再読み込みしますか？\n（INBOXなどの保存データは消えません）')) return;
      if (status) status.textContent = 'クリア中…';
      try {
        try { localStorage.removeItem(RELOAD_GUARD_KEY); } catch (_) { }
        await wipeDumpAppCachesAndWorkers();
        if (status) status.textContent = '再読み込みします';
        location.reload();
      } catch (e) {
        if (status) status.textContent = 'クリアに失敗';
        alert('キャッシュのクリアに失敗しました。ブラウザのサイトデータ削除を試してください。');
      }
    }

    // 起動を最優先する更新方式。
    // 原則: 起動時に「キャッシュ削除」も「SW登録解除」も「自動リロード」もしない。
    //       自動リロードすると、開いた直後にもう一度スタートアップ画面が出る。
    // 新しい Service Worker は裏で受け取るだけにし、反映は次に開き直したとき、
    // またはユーザーが「最新」を押したときに任せる。
    // 万一リロードが連鎖しても、回数ガードで必ず止めて「とにかく起動する」side に倒す。
    const RELOAD_GUARD_KEY = 'dump_reload_guard';
    const RELOAD_GUARD_WINDOW_MS = 60 * 1000;
    const RELOAD_GUARD_MAX = 2;

    /** 短時間に何度もリロードしそうなら false を返してリロードを止める */
    function allowAutoReload() {
      try {
        const now = Date.now();
        const raw = JSON.parse(localStorage.getItem(RELOAD_GUARD_KEY) || '{}');
        const times = (Array.isArray(raw.times) ? raw.times : [])
          .filter((t) => typeof t === 'number' && now - t < RELOAD_GUARD_WINDOW_MS);
        if (times.length >= RELOAD_GUARD_MAX) {
          console.warn('DUMP auto reload suppressed (loop guard)');
          return false;
        }
        times.push(now);
        localStorage.setItem(RELOAD_GUARD_KEY, JSON.stringify({ times }));
        return true;
      } catch (_) {
        return true;
      }
    }

    function setupServiceWorkerUpdates() {
      if (!('serviceWorker' in navigator)) return;

      let refreshing = false;
      navigator.serviceWorker.addEventListener('controllerchange', () => {
        if (refreshing) return;
        if (!sessionStorage.getItem('sw_update_reload')) return;
        sessionStorage.removeItem('sw_update_reload');
        if (!allowAutoReload()) return;
        // オフライン時の強制リロードは ERR_FAILED を招きやすいので次回起動に回す
        try {
          if (typeof navigator.onLine === 'boolean' && !navigator.onLine) return;
        } catch (_) { }
        refreshing = true;
        location.reload();
      });

      navigator.serviceWorker
        .register('./service-worker.js', { updateViaCache: 'none' })
        .then((reg) => {
          // 見つかった更新はその場で適用してリロードしない。
          // install 側の skipWaiting で制御が替わっても、フラグが無いので画面は再起動しない。
          // 新しいビルドがあれば SW の install が新 index を取り込む。
          // 旧キャッシュは新キャッシュの準備が整うまで消さない（activate 側で保証）。
          const quietUpdate = () => {
            try { reg.update(); } catch (_) { }
          };
          setTimeout(quietUpdate, 1500);
          setInterval(quietUpdate, 30 * 60 * 1000);
          document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'visible') quietUpdate();
          });
        })
        .catch((err) => console.warn('SW register failed', err));
    }
